(window.GIM_TP=window.GIM_TP||{})["Chullin.1"]={"from":196,"a":[[["בריה שאני:","וכן חתיכה של נבלה [וכו']: ותבטיל ברובא","הניחא למאן דאמר כל שדרכו לימנות שנינו אלא למ\"ד את שדרכו לימנות שנינו מאי איכא למימר שאני חתיכה הואיל וראויה להתכבד בה לפני האורחים","וצריכא דאי אשמעינן גיד משום דבריה היא אבל חתיכה אימא לא","ואי אשמעינן חתיכה הואיל וראויה להתכבד בה לפני האורחים אבל גיד אימא לא צריכא","דרש רבה בר בר חנה חתיכה של נבלה ושל דג טמא אינה אוסרת עד שתתן טעם ברוטב ובקיפה ובחתיכות","אוקי רב אמורא עליה ודרש כיון שנתן טעם בחתיכה חתיכה עצמה נעשת נבלה ואוסרת כל החתיכות כולן מפני שהן מינה","אמר ליה רב ספרא לאביי מכדי רב כמאן אמרה לשמעתיה כרבי יהודה דאמר מין במינו לא בטיל מאי איריא כי נתן טעם אפילו כי לא נתן טעם נמי אמר ליה הכא במאי עסקינן בשקדם וסלקו","רבא אמר"],[[2,"הניחא למ\"ד","במסכת ביצה (דף ג:):"],[2,"כל שדרכו לימנות שנינו","במסכת ערלה (פ\"ג משנה ו) גבי חבילי תילתן דלא בטיל הא נמי פעמים שנמנית דאדם עשוי למנות חתיכותיו למנין אורחים שזימן:"],[2,"אלא למ\"ד את שדרכו","מיוחד למנין הוא דלא בטל כגון תבלין אבל דבר העשוי לינתן באומד אע\"פ שנמנה לפעמים בטל אמאי לא בטלה:"],[5,"חתיכה של נבלה","ומכירה:"],[5,"אינה אוסרת","בפליטתה עד שיהא בה כדי ליתן טעם ברוטב ובקיפה ובחתיכות:"],[6,"אוקי רב אמורא עליה","העמיד מתורגמן לפניו לדרוש ולהשמיע לרבים שלא ילמדו מרבה בר בר חנה:"],[6,"כיון שנתנה טעם בחתיכה","אחת שהיתה בצדה תמיד או שנתבשלה תחלה עמה קודם שיתן שאר החתיכות בקדרה ולא היה בזו ששים באיסור ונתנה הנבלה טעם בה ואח\"כ נתן שאר החתיכות בקדרה:"],[6,"חתיכה","זו שקבלה טעם הנבלה נעשת נבלה עצמה:"],[6,"ואוסרת כל החתיכות כולן מפני שהן מינה","וקא ס\"ד מפני שהן מינה לא בטלי ואפילו יש בהן כדי ביטול שתיהן:"],[7,"רב","דאמר מפני שהן מינה כמאן אמרה כו':"],[7,"אפילו לא נתנה טעם","בחתיכה שבצדה לא בטלה נמי דהא נבלה גופה מינייהו היא ולא בטלה:"],[7,"בשקדם וסלקו","לאיסור וסלק רוטב קודם שיתן האחרות בקדרה הלכך נתנה טעם בראשונה הרי זו חוזרת ואוסרתן ואי לאו במאי מיתסרי ואשמועינן דחתיכה עצמה נעשת נבלה לאסור חברותיה בפליטתה:"]],[[0,"בריה שאני","ואפילו באלף לא בטיל וכן חתיכה הראויה להתכבד לא בטלה כדאמר הכא והיכא דפירש חד מינייהו נמי אסור גזירה שמא יקח מן הקבוע כיון שאין האיסור ניכר כדפרישית לעיל (חולין דף צה.) ודבר שאינו לא בריה ולא חתיכה הראויה להתכבד בטל ברוב ואפילו איסור מדרבנן ליכא כדמשמע הכא ומיהו שמא לחד גברא היה אסור:"],[2,"שאני חתיכה הואיל וראויה להתכבד","וא\"ת אם כן אמאי אמר בפרק הערל (יבמות פא:) דחתיכה של חטאת טמאה במאה של חטאות טהורות תעלה וכי תימא שאני חתיכה דנבלה דראויה להתכבד לפני אורחין עובדי כוכבי' אבל של חטאת טמאה אסור בהנאה דהא חתיכת בשר בחלב תנן בפרק בתרא דמסכת ע\"ז (דף עד.) דלא בטלה אע\"ג דאסור בהנאה כדקאמר התם ויש לומר דכל דבר הראוי להתכבד אם היה מתבטל חשיב ולא בטיל אבל בהערל (יבמות פא:) אפילו תתבטל בחטאות טהורות התם אינה ראויה אלא לכהנים ולא חשיבא דכהנים אין מחזיקין טובה זה לזה שכולן שוין דלכל בני אהרן תהיה איש כאחיו כתיב (ויקרא ז) אבל של חטאת בשל חולין קאמר התם דלא תעלה וא\"ת דמשמע הכא דחתיכת נבלה לא בטלה ובפרק בתרא דמסכת ע\"ז (דף עד.) משמע דבטלה דפריך האי תנא מאי קא חשיב אי דבר שבמנין קא חשיב ליתני נמי חתיכת נבלה ואי איסורי הנאה קא חשיב ליתני נמי חמץ בפסח ומשני דתרתי אית ליה דבר שבמנין ואיסורי הנאה ומפרש נמי התם דהרי אלו אסורין למעוטי דבר שבמנין ולאו איסורי הנאה אי נמי איסורי הנאה ולאו דבר שבמנין וי\"ל דהתם לא קאמר אלא דלא איירי בהו תנא דמתניתין דהתם ולאו משום דסבר דבטלי והא דקאמר למעוטי היינו למעוטי דלא חשיב להו וכה\"ג יש בריש פ\"ק דבבא קמא (דף ה:) דמנינא דמתניתין למעוטי דרבי חייא ודרבי חייא למעוטי דרבי אושעיא ולא משום דפליגי אבל קשה דכי פריך התם וליתני נמי חתיכת נבלה אמאי לא משני דלא תני לה משום דכבר תנא ליה הכא במתניתין כדמשני התם אהא דפריך התם וליתני נמי אגוזי פרך ורמוני באדן ומשני הא תנא התם הראוי לערלה וכו' וי\"ל דהכי פריך התם וליתני נמי חתיכת נבלה ואי משום דכבר תנא ליה הכא א\"כ לא ליתני חתיכת בשר בחלב כיון דכבר אשמועינן הכא דחתיכת איסור לא בטלה משום דהוי דבר שבמנין ומשני דההוא תנא תרתי אית ליה ולפירוש זה צריך לפרש דדבר שבמנין ולא איסור הנאה בטל לההוא תנא ולכך לא נקט אלא חתיכת בשר בחלב ופליג אתנא דהכא:"],[6,"חתיכה עצמה נעשת נבלה","פי' בקונטרס שנתבשלה תחילה עמה קודם שנתן שאר חתיכות בקדרה ולא היה בזו ששים באיסור ונתנה הנבלה טעם בה ואח\"כ נתן שאר החתיכות בקדרה חתיכה זו שקבלה טעם הנבלה חתיכה עצמה נעשת נבלה ואוסרת כל החתיכות כולן מפני שהן מינה וקשה לפירושו דא\"כ גם הרוטב שהיה באותה שעה נאסר מתחלה ע\"י טעם הנבלה ובסמוך משמע דמבטלינן לחתיכות ע\"י רוטב דהוי שאינו מינו והלא רוטב עצמו נאסר מתחלה ונעשת נבלה ואוסר כל הרוטב שאחרי כן מפני שהוא מינו ויצטרך שיהא ששים בחתיכות שנתן אחרי כן לבטל הרוטב דמעיקרא אלא י\"ל דמיירי כגון שיש חתיכה של היתר כולה חוץ לרוטב וחתיכת נבלה מונחת עליה חוץ לרוטב ונעשת חתיכת היתר נבלה לפי שבולעת טעם נבלה דאין בהן ששים לבטל הטעם ואחרי כן כשמנער הקדרה אוסרת כל החתיכות מפני שהן מינה:"],[7,"בשקדם וסלקו","את האיסור וא\"ת למה לי שחתיכה של היתר קבלה טעם מן הנבלה אפילו לא נתנה טעם נמי דהא במינה אוסרת בכל דהו ואומר ר\"ת דנהי דהיא גופה מיתסרא בכל שהוא מ\"מ לא אמרינן שתעשה נבלה לאסור כל האחרות כיון שהיא עצמה לא נאסרה אלא ע\"י כל שהוא ורבינו אפרים היה אומר מתוך כך דאפילו כי נתנה בה טעם אין ההיתר נעשה נבלה שיצטרך ששים כנגד כל החתיכה אלא כנגד האיסור הבלוע הלכך לרב דאמר הכא דמין במינו לא בטיל כשחתיכת היתר קבלה טעם מן הנבלה חשיב האיסור כאילו הוא בעין ואוסרת כל החתיכות במשהו אבל כי לא נתנה הנבלה טעם בה לא היתה אוסרת החתיכות מפני שהם מינה שהרי אין צריך לבטל אלא האיסור לבד וכיון שלא נתנה טעם בחתיכה הוי האיסור כמאן דליתיה דלא הוי כאילו הוא בעין ולא אסר אלא חתיכה ראשונה שאין ההיתר נעשה איסור ולא אסר שאר חתיכות ודוקא גבי טפת חלב אמרינן לקמן בפרק כל הבשר (חולין דף קח.) דחתיכה עצמה נעשת נבלה וצריך ששים כנגד כל החתיכה ולא סגי בביטול טיפה לחוד משום דכל חד וחד באפיה נפשיה שרי וכי איתנהו בהדי הדדי אסור הלכך הבשר עצמו נעשה איסור ולוקה אם אכל חצי זית מבשר וחצי זית מחלב ולכך צריך ברוטב ששים לבטל כל החתיכה שנפלה עליה טיפת חלב אבל חתיכת היתר שבלעה טעם נבלה ונאסרה וחזרה ונתנה טעם ברוטב אין צריך אלא ששים לבטל האיסור שנבלע בחתיכה ואין צריך שיעור ששים של אותה חתיכה וקשה לפירושו לרבא דמשני אפילו תימא לא קדם וסלקו מאי מהני ליה חתיכה של היתר שנאסרה מתחלה ונעשת נבלה והלא לעולם אין צריך ס' ברוטב אלא כדי לבטל חתיכה של נבלה לבדה ולא בעינן ששים לבטל שתי חתיכות של נבלה ושל היתר שנאסרה על ידה וי\"ל כגון שנתמעטה הנבלה הרבה מכמו שהיתה קודם שנבלע טעמו בחתיכה של היתר והשתא לפי שנתנה טעם בשל היתר צריך ס' כנגד כל מה שהיתה מתחלה ואין שיעור ברוטב לבטלה אבל לא נתנה בה טעם אין צריך ס' אלא כנגד מה שנשאר בנבלה ויש שיעור ברוטב לבטלה ורב דאתא לפלוגי אדרבה בר בר חנה לא היה צריך רב לומר אלא חתיכה של נבלה אוסרת כל החתיכות מפני שהן מינה אלא אגב אורחיה אשמועינן דדוקא נתנה בה טעם נבלה אבל לא נתנה בה טעם נבלה לא ורבינו אפרים עליו השלום היה מביא ראיה מהא דאמר לעיל (חולין דף צח.) ההוא כזיתא דתרבא דנפל לדיקולא דבשרא ודיקולא הוא סל מלא חתיכות של בשר רותח ולא אמר שתעשה נבלה אותה חתיכה שנפל עליה כזית חלב ותאסור שאר חתיכות שאין בהן ששים כנגד כולה לפי שבאותה חתיכה עצמה לא היה בה כדי לבטל הכזית אלא משערינן הכזית בכל הבשר שבסל ואין משם ראיה כלל דדיקולא היינו קלחת וכדפירש הקונטרס וכדפירשנו לעיל ואפילו אם נאמר דדיקולא הוא סל כדמשמע הכא ובכל דוכתא אין ראיה משם דממה נפשך אם אין חלב מפעפע מחתיכה לחתיכה כמו שפירשנו לעיל א\"כ אין אסור אלא החתיכה שנפלה עליה החלב והשאר מותרות ואם הוא מפעפע מחתיכה לחתיכה א\"כ בדין הוא שכל החתיכות מסייעות לבטל ולא אמרינן שתעשה נבלה אותה חתיכה שנפלה עליה חלב מאחר שסופו להתפשט בכל החתיכות מידי דהוה אטיפת חלב שנפלה על חתיכת בשר דאם אין נ\"ט מותר אע\"פ שקודם שתתפשט הטפה נ\"ט במקום נפילתה ולא אמרינן שיעשה אותה הבשר נבלה כיון דסוף הטיפה להתפשט בכל החתיכה מיהו לפי מה שפי' לעיל בשם הרב רבי אלעזר ממי\"ץ דבחצי חתיכה אין שייך לומר שתעשה נבילה אין ראיה משם ואין ראיה לרבינו אפרים מהא דאמר (תרומות פ\"ה משנה ו) אין המדומע מדמע אלא לפי חשבון ולא אמרינן שיעשה הכל תרומה דיש לחלק בין דבר יבש לדבר הנאסר ע\"י בליעה ולפירושו ניחא הא דאמר גבי יין נסך בסוף מסכת ע\"ז (דף עג:) יין נסך שנפל לבור דאיכא למאן דאמר אפילו נפל שם קיתון של מים לבסוף רואין ההיתר כאילו אינו ושאר מים רבים עליו ומבטלין אותו ולא אמר שיין עצמו של היתר נעשה איסור ליחשב כאילו הוא יין נסך ויצטרך מן המים כדי לבטל כל היין ומיהו י\"ל דהתם מיירי כגון שלא היה שם יין נסך כדי ליתן טעם בשל היתר שבבור ולא נאסר אלא ע\"י כל שהוא וכיון דלא הוי אלא משהו לא אמרינן חתיכה עצמה נעשת נבלה כדפרישית לעיל אע\"ג דלא דמי דלעיל לא אמרינן אלא לענין שלא תאסור האחרות אבל היא עצמה נאסרה במשהו וכיון שנאסרה אסורה לעולם למ\"ד (לקמן חולין דף קח.) אפשר לסוחטו אסור ומ\"מ יש לומר דההוא דשרי בע\"ז אפילו נפלו המים לבסוף יסבור אפשר לסוחטו מותר והיה מתיר כמו כן חתיכה עצמה ומדקאמר התם נפל חמרא דהתירא בגו מיא דאיסורא בנ\"ט וכי ליכא נ\"ט שרי אין ראיה לפירושו דאיכא למימר דאיירי כגון שנפל כל ההיתר בבת אחת שנתבטל לאלתר האיסור אבל אם לא נפל בבת אחת ראשון ראשון נעשה איסור ועושה יין נסך לאסור הבא אחריו כדפירש' בפרק כיסוי הדם (לעיל חולין פז.) ולפי פירוש רבינו אפרים ודאי ניחא מה שצוה הכתוב להגעיל כלי מדין דהשתא יורה גדולה שאי אפשר להגעיל בתוך כלי אחר היכי משתריא הא אין במים ס' לבטל האיסור ואי שיחזור ומגעילה בשניה והלא המים הראשונים נעשו נבלה וחוזרין ואוסרין ואי לא משערין אלא באיסור עצמו ניחא דזה אין לומר דכשאין בת יומא מגעילין אותה דהא לא אסרה תורה אלא קדרה בת יומא ואין ראיה גמורה מכאן דאיכא למימר דלא אמרה תורה להגעיל אלא כלים קטנים בתוך כלי גדול שיהיה במים ששים כדי לבטל האיסור וכתב רבינו יהודה דנראה לר\"י להחמיר בדבר כיון דאין ראיה ברורה:"]]],[["אפילו תימא לא קדם וסלקו הוי מין ומינו ודבר אחר","וכל מין ומינו ודבר אחר סלק את מינו כמי שאינו ושאין מינו רבה עליו ומבטלו:","\u0001מתני׳\u0002 נוהג בטהורה ואינו נוהג בטמאה רבי יהודה אומר אף בטמאה אמר ר' יהודה והלא מבני יעקב נאסר גיד הנשה ועדיין בהמה טמאה מותרת להן אמרו לו בסיני נאמר אלא שנכתב במקומו:","\u0001גמ׳\u0002 וסבר ר' יהודה איסור חל על איסור והתניא ר' יהודה אומר יכול תהא נבלת עוף טמא מטמא בגדים בבית הבליעה","תלמוד לומר (ויקרא כב, ח) נבלה וטרפה לא יאכל לטמאה בה מי שאיסורו משום בל תאכל נבלה יצא זה שאין איסורו משום בל תאכל נבלה אלא משום בל תאכל טמאה","וכי תימא קסבר אין בגידין בנותן טעם ובטמאה נמי איסור גיד איכא איסור טומאה ליכא","וסבר ר' יהודה אין בגידין בנותן טעם והתניא האוכל גיד הנשה של בהמה טמאה ר' יהודה מחייב שתים ור\"ש פוטר","לעולם קסבר יש בגידין בנותן טעם וקסבר נוהג בשליל דאיסור גיד ואיסור טומאה בהדי הדדי קאתי","ומי מצית אמרת נוהג בשליל והתנן נוהג בשליל ר' יהודה אומר אינו נוהג בשליל וחלבו מותר","הני מילי גבי טהורה דרחמנא אמר (דברים יד, ו) כל בבהמה תאכלו אבל בטמאה נוהג","ומי מצית אמרת דתרוייהו בהדי הדדי קאתו והתנן על אלו טומאות הנזיר מגלח על המת ועל כזית מן המת","וקשיא לן על כזית מן המת מגלח על המת כולו לא כ\"ש וא\"ר יוחנן לא נצרכא אלא לנפל שלא נתקשרו אבריו בגידין אלמא איסור טומאה קדים","אע\"ג דאיסור טומאה קדים אתי איסור גיד חייל עליה שכן איסורו נוהג בבני נח","דיקא נמי דקתני א\"ר יהודה והלא מבני יעקב נאסר גיד הנשה ועדיין בהמה טמאה מותרת להם","גופא האוכל גיד הנשה של בהמה טמאה רבי יהודה מחייב שתים"],[[0,"אפילו תימא בשלא קדם וסלקו","ולא מיתסרי שאר חתיכות אלא משום חתיכת היתר קמייתא:"],[1,"דכל מין ומינו","כגון נבלה ושחוטה:"],[1,"ודבר אחר","כגון תבלין ורוטב מינו דהיתר אינו מבטלו לאיסור ולא מוסיפו אלא סלקהו כמי שאינו בקדרה זו ונשארו הנבלה והרוטב ובטלה נבלה ברוטב ובקיפה. הלכך נתנה טעם בראשונה תחלה בעוד שלא רבה הרוטב עליה ואח\"כ נתן מים וקיפה וחתיכות נתוספה חתיכה ראשונה על הנבלה ואוסרת הכל מפני שהן מינה ולא מצו חתיכות לבטלה ואע\"פ שיש בהן יותר מששים והרוטב לבדו אין בו כדי לבטל שניהם:"],[2,"מתני' ואינו נוהג בטמאה","שאם אכל גיד הנשה של טמאה למ\"ד יש בגידין טעם לוקה משום טמאה ולאו משום גיד ולמ\"ד אין טעם בגידין פטור מכלום דבטהורה עץ הוא והתורה חייבה עליו אבל בטמאה אינו נוהג:"],[2,"מבני יעקב נאסר","דכתיב (בראשית לב) על כן וגו' ועדיין טמאה מותרת להן עד מתן תורה:"],[2,"אמרו לו","פסוק זה שהזהירו עליו בסיני נאמר ועד סיני לא הוזהרו אלא שנכתב במקומו לאחר שנאמר בסיני וכתב וסידר משה את התורה כתב המקרא הזה על המעשה על כן הוזהרו בני ישראל אחרי כן שלא יאכלו גיד:"],[3,"גמ' איסור חל על איסור","דקא ס\"ד משום טומאה ומשום גיד קמחייב ליה:"],[3,"ה\"ג יכול תהא נבלת עוף טמא מטמא בבית הבליעה ת\"ל (כו') נבלה וטרפה לא יאכל לטמאה בה","מפני שהיא מטמא באכילה זו ובנבלת עוף מיתוקם בת\"כ ובמסכת נדה (דף מב:) והכא ה\"ק יכול אף נבלת עוף טמא במשמע ת\"ל נבלה וטרפה לא יאכל לטמאה מי שאיסורו משום בל תאכל נבלה אני אומר לך שמטמא בה יצא זה שאינו אסור משום נבלה אלא משום עוף טמא. ומדקאמר אין איסורו משום נבלה אלמא סבירא ליה לא אתיא איסור נבלה וחייל אאיסור טמאה:"],[5,"וכי תימא קסבר אין בגידין בנ\"ט","ואין כאן איסור טומאה אלא איסור גיד:"],[6,"ור\"ש פוטר","לגמרי משמע ולקמיה מפרש טעמא:"],[7,"ה\"ג לעולם קסבר יש בגידין בנותן טעם וקסבר נוהג בשליל דאיסור גיד ואיסור טומאה כו'","משעת יצירת ולד חלו שניהם לפיכך חייב לעולם על שניהם:"],[8,"אינו נוהג בשליל","ועל כרחך איסור טומאה חל על השליל שהרי כל יצירתו טומאה ואיסור גיד אינו חל עד שנולד והיכי חייל אאיסור טומאה:"],[9,"כל בבהמה","ואפילו חלבו וגידו דמהאי קרא נפקא לן היתר שליל בשחיטת האם בפרק בהמה המקשה (לעיל חולין סט.):"],[10,"הנזיר מגלח","אם האהיל עליהם נטמא נזרו דכתיב (במדבר ו) והימים הראשונים יפלו ומגלח וחוזר ומונה כדכתיב וגלח ראשו ביום טהרתו:"],[11,"שלא נתקשרו","דליכא עדיין כזית בשר בכוליה וכיון דאיתיה שלם מטמא באהל. אלמא תחלה נוצרין אברים קודם לגידין וש\"מ שם טומאה קדים חייל עלייהו:"],[12,"ומשני אע\"ג דאיסור טומאה קדים אתי איסור גיד וחייל עליה שכן","איסור חמור הוא ויש בו כח לחול על אחרים ומהו חומרו שנוהג בבני נח לר' יהודה כדתנן והלא מבני יעקב כו':"],[13,"דיקא נמי","דטעמא דרבי יהודה משום האי טעמא הוא מדיליף מבני יעקב דקודם מתן תורה בני נח הוו:"]],[[0,"הוי מין ומינו ודבר אחר כו'","אומר רשב\"ם דכמו שצריך שיהיה ברוטב כדי לבטל החתיכה דאיסור כך צריך נמי שיהיה ס' בחתיכה של היתר לבטל מן הרוטב כשיעור ב' החתיכות דמכיון שנבלע הרוטב בחתיכת האיסור נעשה נבלה וכשנפלט אחרי כן ממנה אוסר שאר הרוטב מפני שהוא מינו דהכי אמרינן בפרק כל הבשר (לקמן חולין דף קח.) גבי כזית בשר שנפל לתוך יורה של חלב אמר רב בשר אסור חלב מותר ואי אמרת אפשר לסוחטו אסור אמאי חלב מותר חלב נבלה היא פירוש דחלב שנבלע בבשר נעשה נבלה וכשנפלט אח\"כ אוסר כל החלב מפני שהוא מינו:"],[1,"סלק את מינו כמי שאינו ואת שאינו מינו רבה עליו ומבטלו","הקשה רבינו אפרים דאמר בפרק הלוקח בהמה (בכורות כב.) הלוקח ציר של ע\"ה משיקו במים וטהור אי רובא מים טהר להו בהשקה ואי רובא ציר לאו בר קיבולי טומאה הוא והנך מיעוטא דמים בטלי ברובא וקאמר לא שנו אלא לטבל בו פיתו אבל לקדרה מצא מין את מינו וניעור והשתא היאך ניעור אמאי לא קאמר סלק את מינו כמי שאינו ושאינו מינו דהיינו הציר רבה על מים טמאים ומבטלן לעולם הציר שהוא רוב מבטל אותם מים הטמאים וי\"ל דלא דמי דהכא אין מינו נאסר אלא מכח האיסור שנתערב בו ואי אפשר להבדילו ובכל מקום שישנו היתר הוא ולפיכך שייך לומר שם סלק אבל התם דמינו עצמו מטמא מחמת מגע מים טמאים אין שייך לומר סלק:"],[5,"וכי תימא אין בגידין בנ\"ט","לפי זה היה יכול להקשות ממתניתין דמאי קאמר ר' יהודה והלא מבני יעקב נאסר ועדיין בהמה טמאה מותרת להן דמשמע דמטעם זה יש לחול איסור גיד אאיסור טומאה כמו שפירש בסמוך במסקנא ואמר דיקא נמי דקתני כו' וכן היה יכול להקשות למאי דבעי מעיקרא למימר דטעמא דר' יהודה משום דאיסור חל על איסור בכל מקום ונראה להרב רבינו שמואל דיש ליישב דס\"ד דר' יהודה דטעמא דת\"ק כר' שמעון דבסמוך משום מי שגידו אסור ובשרו מותר יצא כו' ולהכי פריך ר' יהודה והלא אף לבני יעקב נאסר ועדיין בהמה טמאה בשרה מותרת:"],[9,"אבל בטמאה נוהג","היה יכול להקשות דאמרינן בפרק בהמה המקשה (לעיל חולין דף עה.) הפילה נפל חלבו כחלב חיה דחדשים קא גרמי לה אלא עדיפא מיניה פריך דאיכא למ\"ד התם דאסור דאוירא גרים ובהמה טמאה כאוירא דמיא כיון דלא שייך בה כל בבהמה תאכלו ועוד יש לומר דילמא שאני חלב דרחמנא אמר כל חלב שור או כשב או עז ואין זה קרוי שור וכשב ועז אבל גיד אסר הכתוב כל מקום שישנו על הכף:"]]],[["ורבי שמעון פוטר","ור\"ש מה נפשך אי איסור חל על איסור ליחייב נמי משום גיד אי אין איסור חל על איסור ליחייב משום טומאה דקדים ואי אין בגידין בנותן טעם ליחייב משום גיד","אמר רבא לעולם קסבר אין בגידים בנותן טעם ושאני התם דאמר קרא (בראשית לב, לג) על כן לא יאכלו בני ישראל את גיד הנשה מי שגידו אסור ובשרו מותר יצתה זו שגידו אסור ובשרו אסור","אמר רב יהודה אמר רב האוכל גיד הנשה של נבלה ר\"מ מחייב שתים וחכמים אומרים אינו חייב אלא אחת","ומודים חכמים לר\"מ באוכל גיד הנשה של עולה ושל שור הנסקל שחייב שתים","ומאן האי תנא דבאיסור כולל איסור חל על איסור לית ליה איסור כולל באיסור חמור אית ליה","אמר רבא רבי יוסי הגלילי היא דתנן טמא שאכל קדש בין קדש טמא בין קדש טהור חייב","רבי יוסי הגלילי אומר טמא שאכל את הטהור חייב טמא שאכל את הטמא פטור שלא אכל אלא דבר טמא","אמרו לו אף טמא שאכל את הטהור כיון שנגע בו טמאהו","שפיר קא אמרי ליה רבנן לר' יוסי הגלילי ואמר רבא בנטמא הגוף ואח\"כ נטמא בשר כולי עלמא לא פליגי דחייב דאיסור כרת קדים","כי פליגי בנטמא בשר ואח\"כ נטמא הגוף רבנן אית להו איסור כולל דמגו דמיחייב אחתיכות טהורות דעלמא מיחייב נמי אחתיכה טמאה","ורבי יוסי הגלילי לית ליה איסור כולל דמגו לא אמרינן","ורבי יוסי הגלילי נהי דאיסור כולל לית ליה באיסור קל יבא איסור חמור יחול על איסור קל ומאי ניהו טומאת הגוף שהרי טומאת הגוף בכרת","אמר רב אשי מאן לימא לן דטומאת הגוף חמורה דלמא טומאת בשר חמורה דלית ליה טהרה במקוה"],[[1,"","ה\"ג מה נפשך אי קסבר איסור חל על איסור ליחייב נמי משום גיד ואי אין איסור חל על איסור ליחייב משום טומאה דקדים ואי קסבר אין בגידין בנ\"ט ליחייב משום גיד - כלומר ואי אין בגידין בנ\"ט ומש\"ה פטור משום טומאה ליחייביה משום גיד דהא ליכא למיפטריה הכא משום דאין איסור חל על איסור דהא ליכא טומאה:"],[2,"אמר רבא לעולם קסבר אין בגידין בנ\"ט","לפיכך אין כאן טומאה ומשום גיד נמי ליכא דקסבר אינו נוהג בטמאה וטעמא לאו משום דאין איסור חל על איסור אלא דמעטיה קרא בהדיא דאמר קרא כו':"],[3,"ה\"ג אמר רב יהודה אמר רב האוכל גיד הנשה של נבלה ר\"מ מחייב שתים כו' ומודים חכמים באוכל גיד של עולה","דחמיר איסורה או של שור הנסקל ומאי חומרייהו שאסורין בהנאה:"],[3,"דמחייב שתים","וטעמא כדמפרש:"],[5,"ומאן האי תנא","חכמים:"],[5,"דבאיסור כולל איסור חל על איסור לית ליה ואיסור כולל באיסור חמור אית ליה ה\"ג","והיינו פירושה איסור גיד חל משנולדה וקודם שנתנבלה היה גידה אסור ובשרה מותר וכשנתנבלה נאסר אף בשרה ואע\"ג דשם נבלה ה\"ל למיחל נמי על גיד משום טעמא דכולל שהוא כולל את הבשר עמו ליאסר ואיכא למימר אפילו למאן דאמר אין איסור חל על איסור האי איסור נבלה חייל דמגו דחייל אבשר דהוה מותר חייל נמי אגיד שכוללו עם הבשר אפ\"ה אמרו רבנן דלא חייל:"],[5,"ואיסור כולל באיסור חמור אית ליה","והיכא דאיסור אחרון אית ביה תרתי כולל ומוסיף כגון עולה או שור הנסקל דמעיקרא כשנולדה היה גידה אסור ובשרה מותר הקדישה או נגחה נאסר אף בשרה הרי זה כולל והגיד הזה מתחלה היה אסור באכילה ומותר בהנאה וכשהקדיש חל עליו איסור הקדש לאוסרו בהנאה שאין כאן איסור חל על איסור שמה ששייר הראשון מוסיף השני וכי היכי דחייל עליה שם הקדש לאוסרו בהנאה על כרחך חל עליו אף באכילה שאם אכלו יתחייב שתים ואע\"ג דבאכילה אסור ועומד היה ואין איסור חל על איסור האי הואיל וחייל להנאה חייל נמי אף לאכילה:"],[6,"רבי יוסי הגלילי היא","דשמעינן ליה דלית ליה כולל באיסור קל ומיהו באיסור חמור לא שמעיניה דפליג:"],[7,"חייב","חטאת שהאוכל קדשים בטומאת הגוף זדונו כרת כדכתיב (ויקרא ז) והנפש אשר תאכל בשר וגו':"],[8,"כיון שנגע בו טמאהו","קודם שיאכלנו ואפ\"ה חייביה קרא:"],[9,"","ואמר רבא גרסינן:"],[9,"בנטמא הגוף ואח\"כ נטמא הבשר","דטמא שאכל טהור וטמאהו במגעו שקדמה טומאת גופו לטומאת קדש מודי רבי יוסי דחייב דכיון דאיטמי גופיה איתסר בקדש זה באיסור כרת וכי הדר ואיטמי בשר איסור כרת דטומאת הגוף לא פקעה:"],[9,"ה\"ג דכ\"ע לא פליגי דחייב דאיסור כרת קדים כי פליגי בנטמא הבשר","תחלה ונאסר על כהנים בלאו בעלמא והבשר אשר יגע וגו' רבנן אית להו איסור חל על איסור ע\"י כולל והאי איסור טומאת הגוף כולל הוא דכולל טהורות שהיו מותרות לו והטמאות שהיו אסורות לו ומיגו דחייל אטהורות חייל נמי אטמאות ויש כאן איסור כולל:"]],[[0,"ורבי שמעון פוטר מאי קסבר אי קסבר איסור חל על איסור כו'","המ\"ל הא רבי שמעון לית ליה איסור חל על איסור אפילו באיסור כולל ואפילו חמור על קל גבי האוכל נבלה ביום הכפורים אלא דבלאו הכי פריך שפיר:"],[5,"מאן האי תנא דבאיסור כולל איסור חל על איסור לית ליה","איסור כולל הוא זה כשנתנבלה וא״ת איסור מוסיף הוא דמגו דאיתוסף בה איסור לגבוה כשנתנבלה איתוסף נמי להדיוט וי״ל דסבר כמ״ד בריש פירקין (חולין דף צ.) דגיד נמי אסור לגבוה:"],[5,"איסור כולל באיסור חמור אית ליה","הא דאמרינן בפ' אמרו לו (כריתות יד.) אקדשה מגו דאיתוסף בה איסור הנאה לא נקט לשון איתוסף משום דחשיב בכך איסור מוסיף דהא קרי ליה הכא איסור כולל אלא כלומר איתוסף בה חומרא זו ואין לומר דאיסור כולל דקאמר הכא לאו דוקא אלא איסור הנאה חשיב איסור מוסיף כיון דמעיקרא הוה שרי בהנאה דאם כן אדמייתי הכא רבי יוסי הגלילי דלא שמעינן אלא דלית ליה איסור כולל באיסור קל אבל הא דאית ליה באיסור חמור לא אשכחן אלא מסברא אמרינן דאית ליה משום דלא שמעינן ליה דפליג כי היכי דשמעינן ליה לרבי שמעון גבי האוכל נבלה בי\"ה הוה ליה לאתויי רבי יוסי דאית ליה בפרק ד' אחין (יבמות לב.) אשת איש ונעשית חמותו נידון משום אשת איש דלית ליה איסור כולל ואמרינן דמודה רבי יוסי באיסור מוסיף ועוד אי איסור הנאה איסור מוסיף הוא מאי פריך בסמוך ורבי יוסי הגלילי נהי דאיסור כולל לית ליה יבא איסור חמור ויחול על איסור קל ודילמא לית ליה איסור כולל אפילו באיסור חמור ואיסור מוסיף אית ליה אלא ודאי איסור הנאה לא חשיב איסור מוסיף אלא איסור חמור בעלמא וכן צריך לפרש בסוף פרק כל הבשר (לקמן חולין קיג:) גבי הא דפריך וסבר שמואל איסור חל על איסור:"],[9,"שפיר קאמרי ליה רבנן לרבי יוסי הגלילי","יודעין היו דלא איירי כשתחב לו חבירו לתוך פיו מדקאמרי ליה הכי:"],[9,"בנטמא הגוף ואח\"כ נטמא הבשר כ\"ע לא פליגי דחייב דאיסור כרת קדים","ותו לא פקע ולא גרסינן דאיסור מוסיף הוא דלא איירי הכא לאיחיובי תרתי אלא לאיחיובי חטאת משום טומאת הגוף והא דקאמרי ליה רבנן כיון שנגע בו טמאהו היו סבורין רבנן דרבי יוסי הגלילי פטר משום דמחולל ועומד הוא וגמר מתרומה דפטרינן בפ' כל הבשר (לקמן חולין דף קיג:) טמא האוכל תרומה טמאה משום דכתיב ומתו בו כי יחללוהו פרט לזו שמחוללת ועומדת וא\"ת לרבנן דפרכי מכי נגע בו טמאהו היכי משכחת טמא שאכל תרומה שיהא במיתה הא מכי נגע בה טמאה וי\"ל כגון שתחב לו חברו והכא לא פרכי ליה רבנן אלא משום דידעי דלא איירי בתחב לו כדפירשנו א\"נ בשלא נכשרה או בנילושה במי פירות ועוד לפי האמת אפילו הוכשרה משכחת לה כגון שנטמא הגוף ואח\"כ נטמאה התרומה כדאמרינן הכא ואיצטריך קרא דפטר במחוללת שנטמא תחלה ואצטריך קרא לאשמועינן דילפינן מהתם בעלמא דאין איסור חל על איסור ולמ\"ד איסור חל על איסור בעלמא שאני התם דגלי קרא וכן משמע לקמן בפ' כל הבשר (שם) [וע\"ע תוס' סנהדרין פג: ד\"ה פרט לזו]:"]]],[["ורבי יוסי הגלילי לית ליה איסור כולל","והתניא שבת ויוה\"כ שגג ועשה מלאכה מנין שחייב על זה בעצמו ועל זה בעצמו תלמוד לומר (ויקרא כג, ג) שבת היא (ויקרא כג, כז) יום הכפורים הוא דברי רבי יוסי הגלילי רבי עקיבא אומר אינו חייב אלא אחת","שלח רבין משום דרבי יוסי בר' חנינא כך הצעה של משנה ואיפוך","שלח רב יצחק בר יעקב בר גיורי משום דרבי יוחנן לדברי רבי יוסי הגלילי למאי דאפכן שגג בשבת והזיד ביום הכפורים חייב הזיד בשבת ושגג ביום הכפורים פטור","מאי טעמא אמר אביי שבת קביעא וקיימא יום הכפורים בי דינא דקא קבעי ליה","אמר ליה רבא סוף סוף תרוייהו בהדי הדדי קאתו אלא אמר רבא שמדא הוה ושלחו מתם דיומא דכפורי דהא שתא שבתא הוא וכן כי אתא רבין וכל נחותי אמרוה כרבא:","אמר רבי יהודה והלא מבני יעקב [וכו']:","תניא אמרו לו לר' יהודה וכי נאמר על כן לא יאכלו בני יעקב והלא לא נאמר אלא בני ישראל ולא נקראו בני ישראל עד סיני אלא בסיני נאמר אלא שנכתב במקומו לידע מאיזה טעם נאסר להם","מתיב רבא (בראשית מו, ה) וישאו בני ישראל את יעקב אביהם לאחר מעשה","אמר ליה רב אחא בריה דרבא לרב אשי מההיא שעתא ליתסר","אמר ליה וכי תורה פעמים פעמים ניתנה ההוא שעתא לאו שעת מעשה הואי ולא שעת מתן תורה הואי","ת\"ר אבר מן החי נוהג בבהמה חיה ועוף בין טמאין ובין טהורין דברי רבי יהודה ורבי אלעזר וחכמים אומרים אינו נוהג אלא בטהורין","אמר ר' יוחנן ושניהן מקרא אחד דרשו (דברים יב, כג) רק חזק לבלתי אכול הדם כי הדם הוא הנפש"],[[0,"ור' יוסי לית ליה [איסור] כולל","ולא חייל איסור טומאת גוף על איסור טומאת בשר ואין כאן כרת אלמא שמעינן ליה דלית ליה כולל הלכך תנא דלעיל דלית ליה כולל ר' יוסי הגלילי היא ואשמועינן תנא דלעיל דבאיסור חמור אית ליה כולל. ופרכינן יבא איסור חמור דכרת ויחול עליה דהא אמרת דמודה הוא באיסור חמור והכא איתוסף ביה כרת. ומשני דילמא הא חמירא דלית ליה טהרה במקוה וההיא דלעיל איכא לאוקומה אליביה דלא שמעינן ליה באיסור חמור דלית ליה כולל. ואע\"ג דלרבי שמעון נמי שמעינן בעלמא דלית ליה כולל דתניא רבי שמעון אומר האוכל נבלה ביום הכפורים פטור מחטאת שאין יוה\"כ חל על איסור נבלה ואע\"ג דאיסורו איסור כולל הוא שכולל איסור והיתר לאוסרן יחד אפ\"ה אליביה לא מצינו לאוקומה משום דהא אף באיסור חמור אית ליה דלא חייל דהא יום הכפורים כרת ונבלה לאו בעלמא הוא ואפילו הכי לא חייל ותנא דלעיל סבר דבאיסור חמור אמרינן כולל:"],[1,"שבת ויום הכפורים","שחל להיות בשבת:"],[1,"שבת היא לה'","בשבת בראשית כתיב דמשמע שאם בא איסור אחר עמה יתחייב על שמה בפני עצמה כדכתיב היא וכן גבי יום הכפורים דכתיב הוא והני איסור בת אחת נינהו דהא בהדי הדדי אתו כשקדש היום. מיהו אי אמרת בשלמא אית ליה לרבי יוסי הגלילי באיסור כולל או מוסיף דחיילי אשאר איסורין איכא למימר מש\"ה מתחייב אתרווייהו דהא אי נמי הוה אפשר דקדמיה חד לחבריה הוה אתי חבריה וחייל עליה דשבת לגבי יוה\"כ איסור מוסיף הוא דאי הוה יוה\"כ קדים הוה חייב על זדון מלאכה כרת וכי אתי שבת איתוסף ביה מיתת ב\"ד ויוה\"כ לגבי שבת איסור כולל דשבת אסורה במלאכה ומותר באכילה מיגו דאיתסר באכילה משום יום הכפורים איתסר ליה נמי מלאכה משום יום הכפורים אלא אי אמרת באיסור כולל ואיסור מוסיף לא חיילי כי אתו אהדדי אמאי חיילי תרוייהו:"],[2,"שלח רבין כך ודאי","הצעת המשנה במקום שנשנית שם אבל משובשת היא ואיפוך וה\"ה דמצי למימר דס\"ל לר\"י הגלילי דאע\"ג דאיסור כולל לא חייל איסור בת אחת חייל ומיהו ר' יוסי בר' חנינא סבר דמאן דלית ליה איסור כולל לית ליה נמי איסור בת אחת ופלוגתא היא ביבמות בפ\"ג (דף לג.) כך נראה בעיני. ואני שמעתי דשבת חשיב לה כקודמת משום דקביעא וקיימא ויום הכפורים חשיב אחרון משום דבי דינא מקדשי ליה כדלקמן ורבי יוסי הגלילי דמחייב תרתי טעמיה משום כולל וקשיא לי בגווה למאי דקא מותיב רבא לקמן לרב יצחק לבתר דאפכוה סוף סוף תרוייהו בהדי הדדי קאתו מאי תיובתיה הא רב יצחק לדברי ר' יוסי הגלילי קאמר ורבי יוסי הגלילי מדפטר ליה ש\"מ לאו איסור בת אחת חשיב לה וכי פטר ליה מיום הכפורים פטר ליה וכי הזיד בשבת על כרחיך פטור משניהם לדברי רבי יוסי הגלילי:"],[3,"למאי דאפכנא","ומוקמינא דאיהו פטר:"],[3,"שגג בשבת","ששכח שהוא שבת:"],[3,"והזיד באיסור יום הכפורים","שהיה יודע שהוא יום הכפורים:"],[3,"חייב","חטאת משום שוגג שבת. אבל שגג באיסור יום הכפורים ששכח שהוא יום הכפורים אבל יודע הוא שהוא שבת פטור משתיהן וטעמא מפרש ואזיל:"],[4,"אמר אביי","קסבר רבי יוחנן דההוא חטאת דמחייב ליה רבי יוסי [הגלילי] בשגג בזה ובזה אדשבת קמחייב ליה דאיהו קדמיה ואדיום הכפורים הוא דפטר ליה הלכך כי הזיד בשבת ושגג ביום הכפורים פטור לגמרי דאין מביאין קרבן על המזיד:"],[5,"סוף סוף תרוייהו בהדי הדדי קאתו","ואין כאן אחרון ועל כרחיך כי פטר ליה רבי יוסי הגלילי משום דקסבר כיון דבכולל ומוסיף אין איסור חל על איסור באיסור בת אחת נמי לא מחייב אלא חדא ואי נמי הזיד באחד מהן הרי שגגת חבירו עומדת וחייב:"],[5,"אלא אמר רבא","הא דשלח רב יצחק דאדיום הכפורים מפטר לאו בפלוגתא דרבי יוסי הגלילי קאי ומאן דאמר בה לדברי רבי יוסי הגלילי לא היו דברים מעולם אלא שמדא הוה וגזרו שלא לעשות יום הכפורים:"],[5,"ושלחו מתם יום הכפורים דהאידנא שבתא הוא","עשו יום הכפורים בשבת אע\"פ שאינו חל להיות בו כדי שלא תשתכח תורת יוה\"כ והאויבים לא יבינו בו משום דבכל שבת נמי לא עבדי מלאכה ואההוא יוה\"כ קאמר רב יצחק דאם שגג בו והזיד בשבת פטור דהא לאו יום הכפורים הוא ואין שגגתו שגגה:"],[7,"ולא נקראו בני ישראל עד הר סיני","ולקמיה מקשי ליה:"],[7,"אלא","מקרא זה לא נאמר עד סיני אלא לאחר שקבלו משה בסיני ובא לכתוב את התורה כתב אותה אזהרה אצל המעשה לידע כו':"],[8,"לאחר מעשה","לאחר אותו מעשה שנאבק עמו לזמן מרובה בבואו מפדן ארם והקב\"ה קראו ישראל דכתיב (בראשית לה) לא יקרא שמך עוד יעקב כי אם ישראל וגו':"],[9,"מההיא שעתא","דוישאו בני ישראל ליתסר:"]],[[0,"ואיסור כולל לית ליה והתניא כו'","פי' בקונטרס ואע\"ג דאיסור בת אחת הוא מאן דלית ליה איסור כולל לית ליה איסור בת אחת ואין נראה לר\"י דהא בפרק ארבעה אחים (יבמות לג:) פריך השתא באיסור כולל מחייב תרתי באיסור בת אחת מבעיא אלמא אפילו מאן דלית ליה איסור כולל מצי סבר איסור בת אחת לכך נראה לר\"י דהשתא ס\"ד דלאו איסור בת אחת הוא אלא חשיב שבת קדים משום דקביעא וקיימא אבל קשה דאי לא איסור בת אחת הוא א\"כ שבת היא למה לי פשיטא דחייב משום דשבת קדים:"],[1,"תלמוד לומר שבת היא יוה\"כ הוא","וא\"ת ומאי פריך שאני הכא דגלי קרא וי\"ל דפריך וליגמר מיניה וליכא למימר דאדרבה ניגמר מתרומה דפטרינן בפרק כל הבשר (לקמן חולין דף קיג:) מומתו בו כי יחללוהו דלחומרא מקשינן וילפינן מהכא והא דאמר התם בעלמא קסבר שמואל אין איסור חל על איסור וגבי בשר בחלב שאני דגלי קרא גדי לרבות חלב מתה ולא יליף מבשר בחלב לחומרא היינו משום דבשר בחלב חדוש הוא ואית ספרים דגרסי התם ונגמר מיניה חדוש הוא:"],[1,"רבי עקיבא אומר אינו חייב אלא אחת","למאי דפירש בקונטרס שהוא איסור בת אחת וכן הוא במסקנא קשה דתנן בפרק דם שחיטה (כריתות כג.) חתיכת חלב חולין וחתיכת חלב קדש ואכל אחת מהם ואינו יודע איזה מהם אכל מביא חטאת ור' עקיבא אומר אף אשם תלוי אלמא אית ליה איסור חל על איסור וכ\"ש איסור בת אחת ומיהו יש לומר דקדשים שאני כדאמר התם בסוף פרקא דאפילו מאן דאית ליה בעלמא דאין איסור חל על איסור בקדשים אית ליה אך הקשה הרב רבינו שמואל מוורדו\"ן מהא דתנן בפרק כל הבשר (לקמן חולין דף קיג.) רבי עקיבא אומר חיה ועוף אינם מה\"ת שנאמר לא תבשל גדי ג' פעמים פרט לחיה ועוף ובהמה טמאה ופריך בגמרא (שם דף קטז.) הני הא אפקינהו לכדשמואל ומשני קסבר רבי עקיבא איסור חל על איסור וחלב מתה לא צריך קרא והכא משמע דאפילו בבת אחת לית ליה ואע\"ג דאמר הכא איפוך לאו מכח קושיא זאת אמר הכי ועוד למאי דפרישנא דהכא פריך משום דס\"ד דלא הוי איסור בת אחת למאי דמסיק רבא דהוי בת אחת לא אמר איפוך וי\"ל דהתם פריך משום שמואל דאי ס\"ל כר\"ע בחיה ועוף ובהמה טמאה היכי דריש ומשני דקסבר שמואל איסור חל על איסור בלאו קרא:"],[3,"הזיד בשבת ושגג ביוה\"כ פטור","וא\"ת והא לרבי עקיבא נמי פטור דהא אינו שב מידיעתו דמזיד הוא על השבת דחמיר דבסקילה וי\"ל דאפ\"ה חמיר ליה יוה\"כ לפי שהוא יום כפרה ומחילה:"],[5,"יום הכפורים דהאי שתא שבתא הוא","ולא שייך כאן אתם ואפי' מזידים כיון דלא נקבע בעשור לחדש ודוקא אקביעות החדש אמרינן ליה:"],[8,"לאחר מעשה","פירש בקונטרס לאחר אותו מעשה שנאבק עמו לזמן מרובה בבואו מפדן ארם והקב\"ה קראו ישראל והא דקאמר לעיל לא נקרא ישראל עד סיני היינו לענין מצות ופריך מההיא שעתא ליתסר מההיא דוישאו בני ישראל ומשני ההיא שעתא לא שעת מעשה היה דנשיית גיד ולא שעת מתן תורה ולא גרסינן מההוא מעשה ליתסר דמשמע מעשה דנשיית הגיד כמו לאחר מעשה דקאי אנשיית גיד ואם נאמר דלאחר מעשה קאי אברכה שברכו המלאך והסכים הקדוש ברוך הוא על ידו של מלאך וכן מההיא מעשה ליתסר מ\"מ לא הוי כמו האי שעתא לאו שעת מעשה הוי דקאי אנשיית גיד:"]]],[["(דברים יב, כג) לא תאכל הנפש עם הבשר ר' יהודה ור' אלעזר סברי כל שאתה מצווה על דמו אתה מצווה על אבריו והני טמאין נמי הואיל ואתה מצווה על דמן אתה מצווה על אברין","ורבנן סברי לא תאכל הנפש עם הבשר אלא בשר לחודיה כל שבשרו מותר אתה מצווה על אבריו וכל שאין בשרו מותר אי אתה מצווה על אבריו","ור' יהודה למה ליה קרא ליתי איסור אבר ליחול על איסור טומאה שכן איסורו נוהג בבני נח","אין הכי נמי וכי איצטריך קרא לרבי אלעזר","תניא נמי הכי אבר מן החי נוהג בבהמה חיה ועוף בין טמאה בין טהורה שנאמר (דברים יב, כג) רק חזק לבלתי אכול הדם","כל שאתה מצווה על דמו אתה מצווה על אבריו וכל שאי אתה מצווה על דמו אי אתה מצווה על אבריו דברי רבי אלעזר","וחכמים אומרים אינו נוהג אלא בטהורין שנאמר לא תאכל הנפש עם הבשר אלא בשר לחודיה כל שבשרו מותר אתה מצווה על אבריו וכל שאין בשרו מותר אין אתה מצווה על אבריו","ר' מאיר אומר אינו נוהג אלא בבהמה טהורה בלבד","(סימן שמואל שילא שימי)","אמר רבה בר שמואל אמר רב חסדא ואיתימא רב יוסף ואמרי לה אמר רבה בר שילא אמר רב חסדא ואיתימא רב יוסף ואמרי לה רבה בר שימי אמר רב חסדא ואיתימא רב יוסף מאי טעמא דר\"מ","אמר קרא (דברים יב, כא) וזבחת מבקרך ומצאנך","אמר רב גידל אמר רב מחלוקת בישראל אבל בבן נח דברי הכל מוזהר על הטמאין כטהורין","תניא נמי הכי אבר מן החי בן נח מוזהר עליו על הטמאים כטהורים וישראל אינו מוזהר אלא על הטהורין בלבד","איכא דאמרי טהורה ור\"מ איכא דאמרי טהורים ורבנן","אמר רב שיזבי אף אנן נמי תנינא אכל אבר מן החי ממנה אינו סופג ארבעים ואין שחיטה מטהרתה","במאי אילימא בישראל פשיטא דאין שחיטה מטהרתה אלא לאו בבני נח מכלל דאסור","רבי מני בר פטיש רמי רישא אסיפא ומשני רישא בישראל וסיפא בבן נח","אמר רב אבר מן החי צריך כזית מ\"ט אכילה כתיבה ביה","מתיב רב עמרם אכל אבר מן החי ממנה אינו סופג את הארבעים ואין שחיטה מטהרתה ואי סלקא דעתך בעינן כזית תיפוק ליה דקאכל כזית","כדאמר רב נחמן במשהו בשר גידין ועצמות הכא נמי במשהו בשר גידין ועצמות","תא שמע דאמר רב"],[[0,"לא תאכל הנפש עם הבשר","לא תאכל ממנו בעוד שהנפש עמו וזו היא אזהרה לאבר מן החי:"],[0,"טמאין אתה מצווה על דמן","בכריתות בפרק דם שחיטה (כריתות דף כא.) לא יצאו מכלל אזהרתו אלא שרצים ודגים וחגבים ומהלכי שתים:"],[1,"לא תאכל הנפש עם הבשר","משמע הא אין דם הנפש עמו אכול:"],[2,"שכן איסורו נוהג בבני נח","שאף הם הוזהרו עליו דכתיב (בראשית ט) אך בשר בנפשו דמו וגו' ור' יהודה הא שמעינן ליה גבי גיד לעיל (חולין דף ק:) דמשום האי טעמא חייל אטמאה שכן איסורו נוהג בבני נח:"],[3,"כי איצטריך קרא","לאסרו לר' אלעזר איצטריך דאסר ליה בטמאה כר' יהודה ולית ליה איסור חל על איסור באיסור חמור אי לאו דכתביה קרא:"],[4,"תניא נמי הכי","כר' יוחנן דרבי אלעזר ורבנן מהאי קרא ילפי:"],[5,"וכל שאי אתה מצווה על דמו","דגים וחגבים:"],[7,"אלא בבהמה טהורה","ולא בחיה ועוף ואע\"פ שהן טהורין:"],[10,"מבקרך ומצאנך","וכתיב בתריה אבר מן החי:"],[12,"אבל בן נח מוזהר","על הכל דכל דקרינא ביה בשר לחודיה אכול קרינא ביה אבר מן החי לא תאכל:"],[13,"אית דאמרי טהורה","קתני ואבהמה קאי כר' מאיר ואית דאמרי טהורים קתני ואף חיה ועוף במשמע:"],[14,"אף אנן נמי תנינא","במסכת טהרות דבן נח מוזהר על הטמאין והתם (פ\"א מ\"א) קאמר י\"ג דבר נאמרו בנבלת עוף טהור וכך וכך בנבלת עוף טמא וזו היא מהן:"],[14,"אכל אבר מן החי ממנה","בעוף טמא קא מיירי:"],[14,"אינו סופג","וקסבר אינו נוהג בטמאים כרבנן:"],[14,"ה\"ג ואין שחיטתה מטהרתה","ואעוף טמא קאי וקאמר דאין שחיטתה מטהרתה והא דנקיט לה לשון נקבה משום דרישא אתחיל בה לשון נקבה דתנן בה הכי נבלת עוף טמא צריכה מחשבה כו':"],[15,"במאי","קתני סיפא אין שחיטתו מטהרתו אי נימא בישראל פשיטא דהא טמא הוא והא ליכא לפרושי מטהרתו מידי טומאת נבלות דעוף טמא אין לו שום טומאה אפילו בבית הבליעה וע\"כ אין מתירתו באכילה קאמר אלא לבן נח קאמר שאין שחיטתו מתירתו לו באכילה כל זמן שהוא מפרכס כדאמרינן בפ\"ב (לעיל חולין דף לג.) דבן נח לאו בשחיטה תליא מילתא כו' וגבי טהורה הוא דאמרינן שחיטה מכשרא ליה לבן נח מיגו דמכשרא ליה לישראל דליכא מידי דלישראל שרי ולעובד כוכבים אסור שמעינן מינה דאפילו רבנן מודו דבן נח מוזהר על הטומאה באבר מן החי:"],[16,"רמי רישא אסיפא","קתני רישא אינו סופג אלמא אין אבר מן החי נוהג בטמאין והדר תני אין שחיטתו מטהרתו וליכא לאוקומא אלא באבר מן החי אלמא נוהג:"],[16,"רישא בישראל וסיפא בבן נח","ורבנן היא. ומעיקרא כי רמייה הוה משמע ליה נמי סיפא בבן נח ומיהו לא הוה ידע טעמא והדר פשטה דאפי' למ\"ד אין נוהג בטמאין בישראל הוא דקאמר דקרינא ביה כל שאין בשרו מותר אי אתה מצווה על אבריו אבל בבן נח מודה:"],[17,"אבר מן החי צריך כזית","אע\"ג דתרי קראי כתיבי חד לאבר מן החי וחד לבשר מן החי לא תימא דאתרבי אבר אע\"ג דאין בו שיעור אלא ודאי יש בו שיעור בעינן דאין אכילה בפחות מכזית:"],[18,"אכל אבר מן החי ממנה","מעוף טמא:"],[18,"אינו סופג","דאינו נוהג בטמאין ועל כרחך בדאיכא שיעור דאיסור אבר מן החי בטהורה עסקינן דאי ליכא שיעור פשיטא דאינו סופג ואי ס\"ד איסור אבר מן החי בכזית וה\"נ דאכל כזית אמאי אינו סופג והא איכא כזית ואיכא לאו דלא (יאכל כי) שקץ הם (ויקרא יא):"],[19,"כדאמר רב נחמן","לקמן:"],[19,"במשהו בשר וגידין ועצמות","משלימין לכזית דמשום טומאה לא מחייב דאין בגידין ועצמות טעם טמא ומשום אבר מחייב דלהכי פלגינהו קרא לאבר מן החי ובשר מן החי דמיחייב אאבר אף על גב דאין שיעור בשר ואבשר אע\"פ שאינו אבר:"]],[[2,"ורבי יהודה למה ליה קרא ליתי איסור אבר מן החי וליחול אאיסור טומאה שכן איסורו נוהג בבני נח","פי' כדשמעינן ליה לעיל (חולין דף ק:) גבי גיד דמההוא טעמא חייל אאיסור טומאה וא\"ת ודילמא מהכא יליף וי\"ל דלא מצי למילף מהכא דאיסור מוסיף הוא דאיתוסף ביה איסור אבר מן החי לבני נח אבל גיד לא נאסר אלא לבני יעקב ולא הוי אלא איסור חמור:"],[3,"כי איצטריך לר' אלעזר","וא\"ת אי קסבר בהמה בחייה לאברים עומדת אם כן איסור בת אחת היא ואפי' למאן דלית ליה בחמור על קל מודה וי\"ל דאיסור טומאה קדים בעוד שלא נקשרו אברים בגידים:"],[7,"ורבי מאיר אומר אינו נוהג אלא בבהמה טהורה בלבד","הקשה רבינו אפרים דתנן בריש מסכת טהרות י\"ג דברים נאמרו בנבלת עוף טהור כו' והאוכל אבר מן החי ממנה סופג את הארבעים ומליקתה ושחיטתה מטהרת טרפתה מטומאתה דברי ר' מאיר וי\"ל דדברי ר' מאיר לא קאי אכולה מילתא אלא לענין שחיטה ומליקה נקט ליה דפליג עליה ר' יהודה בזבחים בס\"פ טבול יום (זבחים דף קה:) דהא דקתני נמי התם דמטמא טומאת אוכלין בכביצה לא אתי כרבי מאיר ולא אמרינן מדסיפא ר' מאיר רישא נמי ר\"מ ומיהו לפי מה שרצה הש\"ס לדקדק שם מדסיפא רבי מאיר רישא נמי ר' מאיר קשה דאדרבה מדמציעתא דאבר מן החי לאו ר' מאיר רישא נמי לאו ר' מאיר וי\"ל דהוה מצי למימר וליטעמיך וק\"ק לשון הגמרא התם דקאמר מאן שמעת ליה דאית ליה דמליקתה ושחיטתה מטהרת טרפתה מטומאה ר\"מ אמאי צריך לדקדק בענין זה הא קתני בה בהדיא דברי ר\"מ:"],[15,"אלא לאו בבני נח","דאין שחיטתו מתירתו באכילה כל זמן שמפרכסת גבי נבלת עוף טהור דקתני רישא ושחיטתה מטהרת טרפתה מטומאתה ולא קתני דאין שחיטה מטהרתו כדקתני סיפא גבי טהורה דוקא הוא דאמר שחיטה מכשרה ליה לבני נח מגו דמכשרה לישראל דליכא מידי דלישראל שרי ולעובד כוכבים אסור ותימה דתקשה מהך משנה לרב אחא בר יעקב דאמר לעיל בפ\"ב (חולין דף לג.) דאין מזמנין עובד כוכבים על בני מעים ומיהו בלאו הכי אמר לעיל דתניא דלא כוותיה וקושית המשנה אינה פשוטה כל כך:"]]],[["אכל צפור טהורה בחייה בכל שהוא במיתתה בכזית וטמאה בין בחייה בין במיתתה בכל שהוא הכא נמי במשהו בשר גידים ועצמות","ת\"ש נטל צפור שאין בו כזית ואכלו רבי פוטר ור' אלעזר בר ר\"ש מחייב אמר ר' אלעזר בר' שמעון ק\"ו על אבר ממנה חייב על כולה לא כל שכן חנקה ואכלה דברי הכל בכזית","עד כאן לא פליגי אלא דמר סבר בחייה לאברים עומדת ומר סבר בחייה לאו לאברים עומדת","דכ\"ע מיהא לא בעינן כזית אמר רב נחמן במשהו בשר גידים ועצמות","ומי איכא מידי דבכוליה לית ביה כזית בשר ובחד אבר אית כזית במשהו בשר גידין ועצמות אמר רב שרביא אין בקלניתא","אימא סיפא חנקה ואכלה דברי הכל בכזית והא קלניתא עוף טמא הוא ואמר רב טמאה בין בחייה בין במיתתה במשהו אלא כעין קלניתא","אמר רבא את\"ל סבר רבי מחשבת אוכלין שמה מחשבה חישב לאוכלה אבר אבר ואכלה כולה חייב","א\"ל אביי ומי איכא מידי דאילו אכיל ליה אחר לא מיחייב ואכיל ליה האי מיחייב אמר ליה זה לפי מחשבתו וזה לפי מחשבתו","ואמר רבא אם תמצא לומר סבר ר' אלעזר בר ר' שמעון מחשבת אוכלין שמה מחשבה חישב לאוכלה מתה ואכלה חיה פטור","א\"ל אביי ומי איכא מידי דאילו אכיל ליה אחר מחייב ואכיל ליה האי פטור א\"ל זה לפי מחשבתו וזה לפי מחשבתו","אמר ר' יוחנן (דברים יב, כג) לא תאכל הנפש עם הבשר זה אבר מן החי (שמות כב, ל) ובשר בשדה טרפה לא תאכלו זה בשר מן החי ובשר מן הטרפה","ור\"ש בן לקיש אמר לא תאכל הנפש עם הבשר זה אבר מן החי ובשר מן החי ובשר בשדה טרפה לא תאכלו זה בשר מן הטרפה","אכל אבר מן החי ובשר מן החי לר' יוחנן חייב שתים לר\"ש בן לקיש אינו חייב אלא אחת אכל בשר מן החי ובשר מן הטרפה לר\"ש בן לקיש חייב שתים לר' יוחנן אינו חייב אלא אחת אכל אבר מן החי ובשר מן הטרפה לדברי הכל חייב שתים","ורמינהו"],[[0,"בחייה בכל שהוא","משום אבר מן החי. אלמא לא בעינן ביה כזית:"],[0,"במיתתה בכזית","דבנבלה אכילה כתיבא וכל אכילה בכזית בר מאבר מן החי דרבייה קרא וקפיד אאבר לחודיה:"],[0,"טמאה בין בחייה בין במיתתה בכל שהוא","חייב דבריה היא ולא צריכה שיעור כדתנן באלו הן הלוקין (מכות דף יג.) באוכל נמלה כל שהוא שהוא חייב משום שהיא כברייתה אלמא בריה אסורה בכל שהוא אבל לאו דנבלה ליכא לחיובי משום בריה דכשנבראת לא היה עליה שם נבלה הלכך אלאו דנבלה לא מיחייב עד כזית. קתני מיהא בטהורה בחייה בכל שהוא:"],[1,"נטל צפור","והיא טהורה:"],[1,"רבי פוטר","מפרש ואזיל דקסבר אין אבר מן החי בשלימה דלאו אבר מיקריא ומיהו אי איכא כזית הוה מיחייב דלא גרע מבשר מן החי דמיחייב עלה בכזית דהא נמי בשר הוא:"],[1,"ורבי אלעזר ברבי שמעון מחייב","דקסבר שלימה אין לך אבר מן החי גדול מזה ובאבר לא בעינא כזית:"],[1,"חנקה ואכלה","אין כאן אלא איסור נבלה ואנבלה לא מיחייב משום בריה וכזית בעינן:"],[2,"לאברים עומדת","לנתחה עומדת הלכך כל אבר ואבר שבה קרוי אבר בפני עצמו ויש כאן משום אבר מן החי דמיחייב בכל דהו ומיהו חדא הוא דמיחייב דחדא התראה היא:"],[2,"לאו לאברים עומדת","עד שתשחט ואין כאן שם אבר אא\"כ הפרישו אבל דכ\"ע לאבר לא בעינן כזית כדקתני ק\"ו על אבר ממנה חייב ולא פליג רבי:"],[3,"במשהו בשר","הא דקתני שאין בו כזית כשאין בו כזית בשר אלא משהו וגידין ועצמות משלימין לכזית:"],[4,"מי איכא מידי","עוף כחוש כל כך:"],[4,"דבכוליה ליכא כזית בשר","והוא גדול שבאחת מאבריו איכא כזית במשהו בשר וגידין ועצמות משלימין דקתני על אבר ממנה חייב ואמרת דבכזית עסקינן ורישא קתני שאין בו כזית ומוקמינן דליכא כזית בשר:"],[4,"קלניתא","עוף כחוש מאד:"],[5,"קלניתא עוף טמא הוא","ונהי דליכא איסור נבלה בפחות מכזית איסור טמא מיהא איכא דבריה היא דאמר רב טמאה בין בחייה ובין במיתתה בכל שהוא:"],[5,"כעין קלניתא","עוף טהור שהוא כחוש כעין קלניתא:"],[6,"את\"ל","אם תמצא באחד מדבריו של רבי בעלמא דאית ליה מחשבת אוכלין אם חישב לאוכלן כענין זה:"],[6,"שמה מחשבה","ואזלינן בתרה:"],[6,"חישב לאוכלה","לצפור זה שאין בה כזית:"],[6,"אבר אבר","גלי אדעתיה דלאברים עומדת וכי אכלה שלימה נמי אבר קרינא ביה:"],[7,"אכיל ליה אחר לא מיחייב","דלא אבר מיקריא לחייב עליה בכל שהוא:"],[8,"לאוכלה מתה","דגלי דעתיה דבחייה לאו לאברים עומדת:"],[10,"לא תאכל הנפש עם הבשר זה אבר מן החי","דאבר חי מקרינן נפש שאם יחתכנו אינו עושה חליפין שלא ישוב עוד כנפש הנטולה שאינה חוזרת והכי משמע לא תאכל הנפש בעודו עם הבשר בעוד החיות עם הבשר:"],[10,"ובשר בשדה","משמע שפירש ממקומו זהו בשר מן החי וטרפה כמשמעו:"],[11,"וריש לקיש אמר לא תאכל הנפש עם הבשר זה אבר מן החי ובשר מן החי","והכי משמע לא תאכל הנפש ולא תאכל הבשר כל זמן שזה עם זה:"],[12,"לר' יוחנן חייב שתים","דתרי לאוי איכא ואע\"ג דבחדא אכילה וחדא התראה אכלינהו מיחייב תרתי:"],[12,"אלא אחת","דחד לאו הוא וכיון דבחדא אכילה וחדא התראה וחד לאו הוא חדא הוא דמיחייב וכן כולן:"],[12,"לדברי הכל חייב שתים","דבין למר ובין למר מתרי קראי נפקי:"]],[[0,"אכל צפור כו' הכא נמי במשהו בשר גידים ועצמות","ובין הכל צריך שיהא כזית ולא הוי כמשהו דסיפא דהוי בריה והוי משהו ממש:"],[1,"שאין בו כזית ואכלו רבי פוטר","פי' בקונטרס דקסבר דאין אבר מן החי בשלימה ומיהו אי איכא כזית הוה מחייב דלא גרע מבשר מן החי דמחייב בכזית דהא נמי בשר הוא וקשה לפירושו דאמר בסמוך אכל אבר מן החי ובשר מן הטרפה רבי יוחנן אמר חייב שתים וריש לקיש אמר אינו חייב אלא אחת ומוקי לה בבהמה אחת ונטרפה עם יציאת רובה וקסבר ר\"ל דלאו לאברים עומדת ולא אתי איסור אבר מן החי וחייל אאיסור טרפה והשתא מ\"מ ליחייב שתים משום טרפה ובשר מן החי דקאתו בהדי הדדי ויש לדחות כגון שאין באבר זה כזית בשר דלא מיחייב משום בשר מן החי והא דחייב משום טרפה היינו כשלקח בשר מטרפה אחרת והשלים לכזית ודוחק הוא ועוד דא\"כ אמאי לא חייל עליה איסור אבר מן החי כיון דליכא מטרפה אלא חצי שיעור דבפ' בתרא דיומא (דף עג:) ופרק ג' דשבועות (דף כא:) תניא שבועה שלא אוכל טרפות ונבלות שקצים ורמשים חייב ומוקי לה ר\"ל במפרש חצי שיעור אלמא אע\"ג דלא חייל איסור שבועה אכזית משום דמושבע ועומד הוא מ\"מ חייל אחצי כזית ונראה לפרש כי היכי דלאו לאברים עומדת הכי נמי לאו לחתיכת בשר עומדת והא דנקט צפור שאין בו כזית לרבותא דרבי אלעזר נקט דאפ\"ה מחייב ועוד נראה לר\"י דאפילו למ\"ד לאברים עומדת מודה דלאו לחתיכת בשר עומדת בחייה דאמר ר' יוחנן בסמוך אכל חלב מן החי מן הטרפה חייב שלשה ומוקי לה בנטרפה עם יציאת רובה ובהמה לאברים עומדת דאתי איסור טרפה וחלב ואבר מן החי בהדי הדדי והשתא אמאי נקט טרפה בלאו טרפה איכא ג' אבר מן החי ובשר מן החי וחלב אלא ודאי בהמה בחייה לאו לחתיכת בשר עומדת ולא אתי וחייל על שאר איסורין:"],[10,"ובשר בשדה טרפה זה בשר מן החי","מדכתיב בשדה דריש דמשמע שפירש ממקומו ואף על גב דאצטריך לבשר שיצא חוץ ממחיצתו כדאמר בפ' בהמה המקשה (לעיל חולין דף סח:) כולהו דריש מיניה:"],[12,"אכל אבר מן החי ובשר מן החי לר' יוחנן חייב שתים","ואע\"ג דאין לוקין על לאו שבכללות ה\"מ היכא דלא מפרש בקרא כגון (שמות יב) אל תאכלו כי אם צלי אש ומכל אשר יעשה מגפן היין (במדבר ו) אבל ובשר בשדה טרפה דמפרשינן בשר וטריפה לא חשיב ליה לאו שבכללות כמו נא ומבושל וחרצן וזג דמפרשי בקרא לקי וכגון אלמנה וגרושה דלקי לכ\"ע:"],[12,"לרבי יוחנן אינו חייב אלא אחת","משום דמחד קרא נפקי ואף על גב דאנא ומבושל לקי שתים שאני התם דכתיב בוי\"ו ובשל דקאי אאל תאכלו והכא נמי אי הוה כתיב בשדה וטרפה לא תאכלו היה לוקה שתים לרבי יוחנן משום בשר מן החי ובשר מן הטריפה:"]]],[["אכל אבר מן החי מן הטרפה ר' יוחנן אמר חייב שתים ור' שמעון בן לקיש אמר אינו חייב אלא אחת","בשלמא לר' יוחנן ניחא אלא לר' שמעון בן לקיש קשיא","אמר רב יוסף לא קשיא כאן בבהמה אחת כאן בשתי בהמות בשתי בהמות מיחייב שתים בבהמה אחת פליגי","בבהמה אחת במאי פליגי אמר אביי כגון שנטרפה עם יציאת רובה מ\"ס בהמה בחייה לאברים עומדת ואיסור טרפה ואיסור אבר בהדי הדדי קאתו","ומ\"ס בהמה בחייה לאו לאברים עומדת ולא אתי איסור אבר חייל אאיסור טרפה","ואיבעית אימא דכ\"ע בהמה בחייה לאו לאברים עומדת ובמיתי איסור אבר מיחל אאיסור טרפה קא מיפלגי מר סבר אתי איסור אבר חייל אאיסור טרפה ומר סבר לא אתי איסור אבר חייל אאיסור טרפה","איבעית אימא דכ\"ע בהמה בחייה לאברים עומדת וכגון שנטרפה לאחר מכאן ובמיתי איסור טרפה חייל אאיסור אבר קא מיפלגי","מר סבר אתי וחייל ומר סבר לא אתי וחייל","רבא אמר כגון שתלש ממנה אבר וטרפה בו מר סבר בהמה בחייה לאברים אינה עומדת איסור אבר ואיסור טרפה בהדי הדדי קאתו","ומר סבר בהמה בחייה לאברים עומדת ולא אתי איסור טרפה חייל אאיסור אבר","אמר ר' חייא בר אבא אמר ר' יוחנן אכל חלב מן החי מן הטרפה חייב שתים אמר ליה ר' אמי ולימא מר שלש שאני אומר שלש איתמר נמי אמר ר' אבהו א\"ר יוחנן אכל חלב מן החי מן הטרפה חייב שלש","במאי קמיפלגי כגון שנטרפה עם יציאת רובה מ\"ד שלש קסבר בהמה בחייה לאברים עומדת דאיסור חלב ואיסור אבר ואיסור טרפה בהדי הדדי קאתו","ומ\"ד שתים קסבר בהמה בחייה לאו לאברים עומדת ואיסור חלב ואיסור טרפה איכא איסור אבר לא אתי חייל","ואי בעית אימא דכ\"ע בהמה בחייה לאו לאברים עומדת ובמיתי איסור אבר וחייל אאיסור חלב ואאיסור טרפה קא מיפלגי מר סבר אתי חייל ומר סבר לא אתי חייל","ואי בעית אימא דכולי עלמא בהמה בחייה לאברים עומדת וכגון שנטרפה לאחר מכאן ובמיתי איסור טרפה מיחל אאיסור אבר קא מיפלגי","מר סבר אתי חייל מידי דהוה אחלב דאמר מר התורה אמרה יבא איסור נבלה יחול על איסור חלב ויבא איסור טרפה יחול על איסור חלב","ואידך אחלב הוא דחייב דהותר"],[[0,"ה\"ג אכל אבר מן החי מן הטרפה ר' יוחנן אמר חייב שתים כו'","בהמה טרפה מחיים ואכל ממנה אבר בחייה:"],[1,"לריש לקיש קשיא","דהא אפילו לדידיה מתרי קראי נפקי וליחייב תרתי:"],[2,"בשתי בהמות","אבר מן החי מזו ובשר טרפה מזו:"],[2,"חייב שתים","ואע\"ג דבחדא אכילה ובחד התראה אכלינהו דהא תרי לאוי איכא:"],[2,"בבהמה אחת","טרפה שאכל ממנה אבר מן החי פליגי ומפרש ואזיל:"],[3,"במאי פליגי","אמאי פטור והא תרי לאוי נינהו:"],[3,"עם יציאת רובה","בהולדה נטרפה:"],[3,"לאברים עומדת","ובשעה שנולדה חל עליה שם איסור אבר ואיסור טרפה:"],[4,"לאו לאברים עומדת","ולא היה עליה איסור אבר עד שהפרישו ממנה והרי כבר טרפה היא ואין איסור חל על איסור אבל בשתי בהמות ליכא למימר הכי דזו משום טרפה וזו משום אבר של כשרה ואין כאן איסור חל על איסור:"],[5,"דכולי עלמא לאו לאברים עומדת","וכיון דבשעת לידתה נטרפה איסור טרפה קדים:"],[5,"ובמיתי איסור אבר","כשחתכו וחייל אטרפה קא מיפלגי:"],[5,"מר סבר חייל","שכן איסורו נוהג בבני נח ומר סבר לא חייל:"],[6,"ואי בעית אימא דכ\"ע לאברים עומדת","ואיסור אבר קדים:"],[6,"וכגון שנטרפה לאחר מכאן","ורבי יוחנן סבר איסור חל על איסור ואתי איסור טרפה וחייל אאיסור אבר מחיים וריש לקיש סבר אין איסור טרפה חל על הבהמה עד שתשחט דאיסור מיתלא תלי וקאי וכי פקע איסור חיות אתי איסור טרפה וחייל:"],[8,"כגון שתלש כו'","כגון חתך רגליה מן הארכובה ולמעלה רבי יוחנן סבר מתחלה לאו לאברים עומדת וכשחתכן חלו שניהן ור\"ל סבר מעיקרא הוה בה איסור אבר:"],[10,"חייב שתים","ואע\"ג דאיכא תלתא איסורי אבר וחלב וטרפה אין לוקה אלא שתים ולקמן מפרש אהי מינייהו קא פטר ליה:"],[10,"א\"ל רבי אמי","לרבי חייא בר אבא לימא מר שלש שהרי אני אומר משמו של רבי יוחנן שחייב שלש:"],[10,"איתמר נמי","כרבי אמי כשנולדה חל איסור חלב דהא חלב השליל מותר דכתיב כל בבהמה תאכלו ואמרינן (לעיל חולין דף סט.) לרבות את הולד דכתיב כל:"],[12,"ומ\"ד שתים קסבר לאו לאברים עומדת","ואיסור טרפה וחלב חלו בעת לידתה אבל איסור אבר לא בא עד יום שהופרש הלכך לא מצי חייל:"],[13,"מ\"ס אתי חייל","קסבר איסור חל על איסור:"],[15,"מידי דהוי אחלב","כלומר כי היכי דקים לן דאתי איסור טרפה וחייל אאיסור חלב:"],[15,"דאמר מר","רבא אמרה בזבחים בפרק חטאת העוף (זבחים דף ע.):"],[15,"התורה אמרה כו'","ואכול לא תאכלוהו (ויקרא ז) למה לי דכתיב הא בחלב כשרה הוזהרו כל חלב וכל דם לא תאכלו (ויקרא ג) אלא התורה אמרה כו' והאי ואכול לא תאכלוהו משום דנבלה אזהרינהו ואשמועינן דיחול על איסור חלב ואף על גב דאיסור חלב קדים משנולדה. וה\"נ אע\"ג דאיכא איסור אבר בהדי איסור חלב אתי איסור טרפה וחייל עליה:"]],[[3,"מר סבר רבי יוחנן בהמה בחייה לאברים עומדת ואיסור אבר ואיסור טרפה בהדי הדדי קא אתו","משמע דאי לאו לאברים עומדת דאיסור טרפה קדים לא אתי איסור אבר וחייל עלה אע\"ג דאיסור מוסיף הוא דאסור לבני נח ותימה דבפרק ג' דשבועות (דף כא:) ובפ' בתרא דיומא (דף עג:) גבי שבועה שלא אוכל נבלות וטרפות קאמר רבי יוחנן בכולל דברים המותרים עם הדברים האסורים אלמא אית ליה איסור כולל וא\"כ כ\"ש איסור מוסיף כדמוכח בפרק ארבעה אחין (יבמות דף לב:) וי\"ל אף על גב שפירש רבי יוחנן מתניתין דהתם בכולל לדידיה לא ס\"ל הכי:"],[4,"ומר סבר לאו לאברים עומדת ולא אתי איסור אבר וחייל אאיסור טרפה","וא\"ת כמאן ס\"ל אי כרבי אלעזר דאמר לעיל (חולין דף קב.) כל שאתה מצווה על דמו אתה מצווה על אבריו אם כן ליחייב נמי הכא טרפה משום אבר מן החי ואי כרבנן דאמרי כל שבשרו מותר כו' אם כן למה לן טעמא דלאו לאברים עומדת וי\"ל דדרשינן כל מין שבשרו מותר:"],[11,"דאיסור חלב ואיסור אבר ואיסור טרפה בהדי הדדי קאתו","פי' הקונטרס דכשנולדה חל איסור חלב דהא חלב שליל מותר מכל בבהמה תאכלו וקשה דהא א\"ר יוחנן בפ' בהמה המקשה (לעיל חולין דף עה.) תלש חלב בן ט' חי חלבו כחלב בהמה א\"כ איסור חלב קדים וי\"ל דמ\"מ איסור טרפה ואבר חיילי אאיסור חלב דקיל שהותר מכללו ובהדי הדדי קאתו לא נקט אלא משום טרפה ואבר ומיהו קשה דבסוף דם שחיטה (כריתות דף כג:) אמרינן דבקדשים איסור חל על איסור דכתיב כל חלב לה' לרבות אמורי קדשים קלים למעילה דאתי איסור מעילה וחייל אאיסור חלב ופריך למ\"ד אף בקדשים אין איסור חל על איסור ל\"ל כל חלב ומוקי לה בולדות קדשים וקסבר בהווייתן הן קדושין ובהדי הדדי קאתו והשתא אכתי לרבי יוחנן הא איסור חלב קדים דחל במעי אמו ונראה לפרש דדוקא נקט תלש חלב והוציאו ממעי אמו לחוץ הוא דמיקרי חלב והא דאמר חדשים הוא דגרמי ולא אוירא אוירא דבהמה הוא דלא בעי אבל אוירא דחלב בעינן והשתא ניחא הכא דכולהו בהדי הדדי קאתו והא דקאמר כשנטרפה עם יציאת רובה הוא הדין נטרפה במעי אמה דלא מיחייב משום טרפה עד שיולד כמו חלב אלא לא אתי אלא לאפוקי נטרפה לאחר יציאת רובה וא\"ת לרבא דאמר לעיל כגון שתלש ממנה אבר וטרפה בו ולאו לאברים עומדת דהשתא בהדי הדדי קאתו משמע דאם נטרפה קודם שנתלש האבר לא אתי איסור אבר וחייל על איסור טרפה א\"כ היכי משכחת לה שלש הכא לר' יוחנן כיון דלאו לאיברים עומדת ואין איסור אבר חל על איסור טרפה וי\"ל כגון שתלש ממנה אבר וטרפה בו דמיגו דאתי איסור טרפה וחייל אאיסור חלב חייל נמי איסור אבר עליו ומ\"ד שתים לית ליה האי מיגו אלא דוקא איסור טרפה דגלי קרא חייל ולא איסור אבר וא\"ת לההוא לישנא דאמר לעיל דכ\"ע לאו לאברים עומדת ולרבי יוחנן איסור אבר חייל אאיסור טרפה א\"כ היכי משכחת לה דלא מיחייב אלא שתים באכל חלב מן החי ומן הטרפה וי\"ל כגון שעם יציאת רובה נטרפה ואיסור אבר שבא לבסוף נהי דחייל אאיסור טרפה דקיל על איסור חלב דחמיר דבכרת לא חייל:"]]],[["מכללו אבל אבר דלא הותר מכללו לא","כי אתא רב דימי אמר בעא מיניה רבי שמעון בן לקיש מרבי יוחנן חלקו מבחוץ מהו אמר ליה פטור","מבפנים מאי אמר ליה חייב","כי אתא רבין אמר חלקו מבחוץ פטור מבפנים רבי יוחנן אמר חייב וריש לקיש אמר פטור","רבי יוחנן אמר חייב הרי נהנה גרונו בכזית וריש לקיש אמר פטור אכילה במעיו בעינן וליכא","אלא לרבי שמעון בן לקיש היכי משכחת לה דמחייב אמר רב כהנא בגרומיתא זעירתא","ורבי אלעזר אמר אפילו חלקו מבחוץ נמי חייב מחוסר קריבה לאו כמחוסר מעשה דמי","אמר ר\"ש בן לקיש כזית שאמרו חוץ משל בין השינים ורבי יוחנן אמר אף עם בין השינים","אמר רב פפא בשל בין שינים דכולי עלמא לא פליגי כי פליגי בין החניכיים מר סבר הרי נהנה גרונו בכזית ומר סבר אכילה במעיו בעינן","אמר רבי אסי אמר רבי יוחנן אכל חצי זית והקיאו וחזר ואכל חצי זית אחר חייב מ\"ט הרי נהנה גרונו בכזית","בעא רבי אלעזר מר' אסי אכל חצי זית והקיאו וחזר ואכלו מהו מאי קא מיבעיא ליה אי הוי עיכול אי לא הוי עיכול ותיבעי ליה כזית","אלא אי בתר גרונו אזלינן אי בתר מעיו אזלינן ותפשוט ליה מדרבי אסי","רבי אסי גמריה איעקר ליה ואתא ר' אלעזר לאדכוריה והכי קאמר ליה למה לי חצי זית אחר לימא מר בדידיה דאיכא למשמע מינה תרתי שמעינן מינה דלא הוי עיכול ושמעינן מינה דהרי נהנה גרונו בכזית","אישתיק ולא א\"ל ולא מידי א\"ל מופת הדור לא זימנין סגיאין אמרת קמיה דרבי יוחנן ואמר לך הרי נהנה גרונו בכזית:","\u0001הדרן עלך גיד הנשה\u0002","מתני׳ \u0001כל\u0002 הבשר אסור לבשל בחלב חוץ מבשר דגים וחגבים ואסור להעלות עם הגבינה על השלחן חוץ מבשר דגים וחגבים"],[[0,"מכללו","אצל חיה:"],[1,"חלקו מבחוץ","לכזית אבר מן החי נחלק לשנים קודם שיתננו לתוך פיו ואכל זה לבדו ואח\"כ חציו השני:"],[1,"מהו","מי מצטרפי לחיוביה ככל שאר איסורים דקיימא לן דמצטרפי שיעורייהו לחצאין בתוך כדי אכילת פרס כדאמרינן בפרק בתרא דיומא (דף פ:) או דילמא כיון דחידוש הוא דהא גידין ועצמות דעלמא לא מיחייב עלייהו והכא מיחייב ואימא אין לך בו אלא חדושו וכי אכיל ליה בבת אחת מיחייב דסתם אכילה בבת אחת משמע אבל לחצאין לא:"],[2,"מבפנים","לאחר שבא סמוך לבית בליעתו בלעו לחצאין:"],[4,"אכילה במעיו","כשהוא יורד לתוך מעיו צריך שיהא בו שיעור אכילה:"],[5,"היכי משכחת לה דמיחייב","בכזית הא אי אפשר ללעוס אכילה כולה יחד:"],[5,"בגרומיתא זעירתא","עצם קטן שעל כף הירך שיש בו משהו בשר וגיד ועצם משלימו לכזית ואין אדם לועסו אלא בולעו:"],[6,"מחוסר קריבה","שנתרחקו זה מזה מעט:"],[6,"מחוסר מעשה","נמי שלא אכל אלא חצי זית:"],[7,"חוץ משל בין השינים","צריך שיהא כזית במה שהוא בולע לבד הנשאר בשינים:"],[8,"בשל בין השינים","אפילו רבי יוחנן מודה דלא מיחשיב בהדיה דהא אין נהנה לא גרונו ולא מעיו שאין אדם טועם עד שיהא סמוך לבית הבליעה כדכתיב (איוב יב) וחיך (יטעם אוכל):"],[8,"בין החניכיים","המדבק בחכו שגרונו נהנה בו ומעיו לא נהנו:"],[9,"חייב","ואע\"ג דלא בא במעיו זית שלם לא בבת אחת ולא בזה אחר זה:"],[9,"הרי נהנה גרונו","בטעם שני חצאי זיתים. והא דרבי אסי פליגא אדרב דימי ורבין דאמרי לעיל משמיה דרבי יוחנן חלקו מבחוץ פטור. והאי נהנה גרונו משום דהנאת גרונו היינו טעימה והרי טעם שני חצאי זיתים ואע\"ג דזה אחר זה הוא לא איכפת לן הואיל ובכדי אכילת פרס הואי אבל הנאת מעיים אינה אלא במילוי כרס ואע\"ג דבלע שני חצאי זיתים לא נתמלא כרסו אלא בחצי זית שכשבלעו לזה יצא כבר זה:"],[10,"אי הוי עיכול","בבליעתו והוי פירשא בעלמא ואכילה שניה לאו כלום היא:"],[10,"תבעי ליה כזית","ולחייבו ב' מלקיות:"],[11,"אלא אי בתר גרונו אזלינן","דפשיטא ליה דלאו עיכול הוא וקא מיבעיא ליה מי אמרינן הרי נהנה גרונו או דילמא הרי לא נהנו מעיו אלא בחצי זית:"],[11,"תפשוט ליה מדרבי אסי","דבתר גרונו אזלינן:"],[12,"רבי אסי גמריה איעקר ליה","כלומר רבי אלעזר תרוייהו פשיטא ליה ולא הוצרך לישאל כלום אלא שמעיה לרבי אסי ששכח שמועתו ששמעו שניהם מפי ר' יוחנן שאפילו חזר ואכל אותו כזית עצמו חייב ושמעיה לרבי אסי דקא נקיט כזית אחר אבל ההוא לא אלמא הוי עיכול ואתא לאדכוריה ושאל לו בלשון בעיא משום כבודו אכלו לאותו עצמו מהו כלומר היזכר מה ששמעת על כך:"],[13,"אישתיק","רבי אסי:"],[13,"א\"ל","ר' אלעזר:"],[13,"מופת הדור","גדול הדור כמו (זכריה ג) אנשי מופת המה:"],[13,"זימנין סגיאין אמרת","דבר זה לפני רבי יוחנן דאפילו בההוא עצמו חייב והודה לדבריך ואמר הרי נהנה גרונו בכזית:"],[15,"מתני' כל הבשר אסור לבשל בחלב","דאע\"ג דאמר רחמנא גדי הוא הדין לחיה ועוף ומיפלג פליגי בה לקמן (חולין דף קיג.) איכא למ\"ד דאורייתא ואיכא למ\"ד דרבנן:"],[15,"ואסור להעלות","דילמא אתי למיכלינהו כי הדדי דקא נגעי ובלעי מהדדי ואע\"ג שמותר לאכול בשר אחר גבינה כדאמרינן בגמרא:"]],[[1,"חלקו מבחוץ","פירש בקונטרס כזית אבר מן החי חלקו לשנים קודם שיתננו לתוך פיו ואכל זה לבדו ואח\"כ אכל חציו השני משמע דאם נתן שני החלקים בפיו ובלען בבת אחת חייב לכ\"ע ואין נראה דאם כן מאי קשיא ליה לריש לקיש היכי משכחת לה דמיחייב וכי אינו יכול לבלוע כזית בבת אחת והא אמרינן בפרק בתרא דיומא (דף פ.) דבית הבליעה מחזיק כביצת תרנגולת דגדולה יותר מגרוגרת כדמוכח בפרק חלון (עירובין דף פ:) דאיכא כמה גרוגרות בסעודה של עירוב וגרוגרת גדולה יותר מכזית כדמוכח בפרק המצניע (שבת דף צא.) ואמרי' בפ' אמרו לו (כריתות דף יד.) דאין בית הבליעה מחזיק יותר משני זיתים משמע דשני זיתים מחזיק ועוד דכי היכי דאע\"פ שחלקו מבחוץ והניחם בבת אחת לתוך פיו מיחייב לר' יוחנן דאזיל בתר אכילת פיו לפי שנהנה גרונו כזית בבת אחת ה\"נ אפילו בלען בזה אחר זה יתחייב לריש לקיש דאזיל בתר אכילת מעיו כיון שיש כזית בבת אחת במעיו קודם שיתעכל דאינו ממהר להתעכל כדמוכח בסמוך ונראה לפרש דחלקו מבחוץ פטור ואפילו אכלו בבת אחת דבעינן שיהא מחובר בפיו ויהיה עליו שם אבר משום דהכא חדוש הוא כדפירש בקונט' דבעלמא לא מיחייב אגידין ועצמות והכא מיחייב ואין לך בו אלא חידושו אבל חלקו בפנים חייב דדרך הוא שנחלק בפיו בשעת לעיסה וריש לקיש פטר ואפי' חלקו בפנים ולכך דוחק הש\"ס אליביה היכי משכחת לה שיתחייב בדרך אכילה ומשני בגרומיתא זעירתא דאין אדם לועסו אלא בולעו ומיהו לרבי אלעזר ודאי חייב חלקו מבחוץ דאפילו אכל זה אחר זה מיחייב:"],[15,"מתני' כל הבשר אסור לבשל בחלב","תימה דלא תני בארץ ובחו\"ל בפני הבית ושלא בפני הבית בחולין ובמוקדשין כמו בהנך פירקין ובתוספתא תני להו ושמא מאי דשייר במתניתין פירש בברייתא ואשמעינן דחייל איסור בשר בחלב אאיסור מוקדשין ורשב\"ם פי' דאיצטריך משום חו\"ל דס\"ד דאינו נוהג בח\"ל משום דאיתקש לבכורים (שמות כג) בחד קרא ראשית בכורי אדמתך לא תבשל גדי בחלב אמו ולפירושו ניחא הא דאמר בפ' ראשית הגז (לקמן חולין דף קלו.) דארצך דבכורים אתא למעוטי חו\"ל דאע\"ג דהיא מצוה התלויה בארץ איצטריך משום דאיתקיש לבשר בחלב:"],[15,"ואסור להעלות עם הגבינה על השלחן חוץ מבשר דגים וחגבים","האי חוץ לא איצטריך דאפילו לבשל שרי אלא אגב רישא נקטיה:"]]],[["הנודר מן הבשר מותר בבשר דגים וחגבים:","\u0001גמ׳\u0002 הא עוף אסור מדאורייתא כמאן דלא כרבי עקיבא דאי רבי עקיבא האמר חיה ועוף אינו מן התורה","אימא סיפא הנודר מן הבשר מותר בבשר דגים וחגבים הא עוף אסור אתאן לרבי עקיבא דאמר כל מילי דמימליך עליה שליח בר מיניה הוא","דתניא הנודר מן הירק מותר בדלועין ור\"ע אוסר אמרו לו לר\"ע והלא אומר אדם לשלוחו קח לנו ירק והוא אומר לא מצאתי אלא דלועין","אמר להן כן הדבר כלום אומר לא מצאתי אלא קטנית אלא שדלועין בכלל ירק ואין קטנית בכלל ירק רישא רבנן וסיפא ר\"ע","אמר רב יוסף רבי היא ונסיב לה אליבא דתנאי בנדרים סבר לה כר\"ע בבשר בחלב סבר לה כרבנן","רב אשי אמר כולה ר\"ע היא והכי קאמר כל הבשר אסור לבשל בחלב מהן מדברי תורה ומהן מדברי סופרים חוץ מבשר דגים וחגבים שאינם לא מדברי תורה ולא מדברי סופרים:","ואסור להעלות [וכו']: אמר רב יוסף שמע מינה בשר עוף בחלב דאורייתא דאי סלקא דעתך דרבנן אכילה גופה גזירה ואנן נגזר העלאה אטו אכילה","ומנא תימרא דלא גזרינן גזירה לגזירה דתנן חלת חוצה לארץ"],[[0,"הנודר מן הבשר","כל הנודר אין דעתו אלא אחר לשון בני אדם שהוא קורא שם הדבר כך ואשמועינן מתני' דכל מין בשר אדם קורהו בשר חוץ מבשר דגים וחגבים:"],[1,"גמ'","קס\"ד האי איסור דמתניתין מדאורייתא קאמר:"],[1,"","דר\"ע במתניתין היא בהאי פירקא (לקמן חולין דף קיג.):"],[2,"מותר בבשר דגים","שאין קורהו בשר:"],[2,"הא עוף אסור","דבנדרים אחר לשון בני אדם אנו צריכין להלך ואשמועינן מתני' דדרך לקרותו בשר:"],[2,"כל מידי דמימליך עליה שליח","כל דבר שאינו נשמע מן הסתם לא בתוך הכלל ולא מוצא [מן] הכלל וצריך השליח לחזור ולפרש ולשאול רוצה אתה בזה:"],[2,"מיניה הוא","חשוב לענין נדרים מאותו המין כגון הכא שהאומר לשלוחו קנה לנו בשר מן השוק אינו נשמע לו מן הסתם בשר עוף והוא נמלך בבעל הבית ושואל כלום אני לוקח בשר עוף:"],[2,"מיניה הוא","מין בשר הוא שהרי אמר לו קנה לי בשר ואם לא היה עוף מין בשר לא היה נמלך אם יקח ממנו דהא לאו בשר הוא:"],[3,"לא מצאתי אלא דילועין","ואינו לוקחן מיד כשמוצאן אלמא לא קרו ליה אינשי ירק דהא האי ירק סתם קאמר ליה ואי בכלל ירק הוא לא היה צריך לימלך:"],[4,"אמר להם כן הדבר","ומשם אני מביא ראיה שהוא מין ירק שאילו לא מצא אלא קטנית לא היה משיבו לא מצאתי אלא קטנית אלא לא מצאתי ירק ובדילועין היה אומר לא מצאתי ירק אחר אלא דילועין ולמה היה אומר כן אלא שיש לך ללמוד שהדילועין נקראים ירק ואין הקטנית בכלל ירק:"],[5,"סבר לה כר\"ע","דאע\"ג דצריך לאימלוכי (ולא שקיל) מיניה הוא דאי לאו מיניה הוא לא הוה אמר אשקול מהאי:"],[6,"ויש מהן מה\"ת","בשר בהמה:"],[6,"ויש מדברי סופרים","חיה ועוף:"],[7,"ש\"מ","מדאסר עוף בהעלאה משום גזירת אכילה ש\"מ איסור אכילה דידיה מדאורייתא ולא כרב אשי:"],[7,"אכילה גופה גזירה","אטו בשר בהמה:"],[8,"חלת חו\"ל","אינה אסורה לזרים אלא מדרבנן אבל חלת הארץ תרומה קרייה רחמנא ואסורה לזרים מוכל זר לא יאכל קדש (ויקרא כב):"]],[[0,"הנודר מן הבשר מותר בבשר דגים וחגבים","בגמרא מוקי לה כר\"ע דכל מילי דמימליך עליה שליח בר מיניה הוא ובפ' הנודר מן הירק (נדרים דף נד:) פריך דבבשר דגים נמי מימלך ומוקי מתניתין דהכא במאן דכאיב ליה עיניה וביומא דהקזה דלא אכיל איניש דגים אבל עוף אכיל בשלקא ומיהו בפרק בתרא דמעילה (דף כ.) לא קיימא שינויא דהקזה אלא מסיק במאן דכאיב ליה עיניה אבל בשאר ימים הנודר מן הבשר אסור נמי בדגים:"],[1,"הא עוף אסור מדאורייתא","ה\"נ ה\"מ למינקט חיה ונראה דהא דס\"ד שהוא דאורייתא משום דסמיך אסיפא דגזר העלאה אטו אכילה כדדייק רב יוסף בסמוך אבל אין לומר דדייק מדקתני כל הבשר דמשמע ליה שכל הבשר שוה זה כזה בשר עוף כבשר בהמה דהא הנודר מן הבשר אין כל הבשר שוה דאפילו ר\"ע מודה דלא מיתסר בבשר עוף מדאורייתא כדאמר בפרק הנודר מן הירק (נדרים דף נד.) דמודה ר\"ע דלא לקי:"],[8,"ומנא תימרא דלא גזרינן גזירה לגזירה","בכמה מקומות אמר היא גופה גזירה ואנן ניקום ונגזור גזירה לגזירה בפ\"ק דשבת (דף יא:) ובפ' במה מדליקין (שבת דף כא.) ובריש ביצה (דף ג.) והכא בעינן לאתויי ראיה לענין גזירה דהעלאה אטו אכילה ויש מקומות נמי דגזרינן גזירה לגזירה ולא חיישינן אין לדמות גזירות חכמים זו לזו אלא במקומות שהש\"ס מדמה:"],[8,"חלת חוצה לארץ נאכלת עם הזר על השלחן","אין המשנה שנויה כן אלא הגמרא מביאה בקיצור וכן היא שנויה בפ' בתרא דמס' חלה (משנה ח) אמר ר\"ג שלש ארצות לחלה מארץ ישראל עד כזיב חלה אחת מכזיב עד הנהר ועד אמנה שתי חלות אחת לאור ואחת לכהן של אור יש לה שיעור ושל כהן אין לה שיעור מנהר ועד אמנה ולפנים שתי חלות אחת לאור ואחת לכהן של אור אין לה שיעור ושל כהן יש לה שיעור וטבול יום אוכלה רבי יוסי אומר אין צריך טבילה ואסורה לזבים ולזבות ולנדות וליולדות ונאכלת עם הזר על השלחן וניתנת לכל כהן שירצה והכי פירושו מכזיב עד הנהר ועד אמנה שהיו סמוכים לארץ העמים ואין יכולין לשמור עצמם ופירותיהם בטהרה והיו חלותיהם טמאות וטעונות שרפה ולכך צריכין להפריש שתי חלות אחת לאור שהיא חלה דאורייתא דפירותיהן גדלין בארץ ישראל ולכך נמי יש לה שיעור כדמפרש בירושלמי מפני שהיא מדברי תורה ואחת לכהן מדברי סופרים שלא תשתכח תורת חלה ולפי שהיא מדברי סופרים אין לה שיעור מנהר ועד אמנה ולפנים שהוא חוצה לארץ שתי חלות ושתיהן מדברי סופרים אחת לאור משום דסמוכין לארץ ישראל ומתחזיא חלה דידהו כחלת ארץ ישראל גזרו עליה שלא לאוכלה כלל אפילו כהן טהור גמור כמו בחלת אור דא\"י ואחת לכהן שלא תשתכח ויש לה שיעור לפי שהיא נאכלת וטבול יום אוכלה ואין צריך הערב שמש שלא החמירו בה כמו בתרומה דאורייתא רבי יוסי אומר אין צריך טבילה ואפילו בטומאה דקרי דבטומאה היוצא מגופו שרי רבי יוסי מדלא חשיב בעל קרי באיסורא דזבין וזבות ואסורה לזבין וזבות כו' בלא טבילה איירי מדקאמר עלה בירושלמי דלרבי יוסי נצרכה ונראה דלרבנן נמי דבעו טבילה דוקא לבעל קרי שטומאה יוצאה לו מגופו אבל טמא מת שרי בלא טבילה כרבי יוסי דאי מצרכי נמי טבילה בטמא מת תקשה להו כדמקשה גמ' בפ' עד כמה (בכורות דף כז:) וכי הזאה יש לנו ומה תועיל טבילה בטמא מת ומסתמא טמאי מתים היו כמה פעמים כי אי אפשר להם ליזהר מטומאת מת דנהי דמטומאת מת עצמו צריכין ליזהר מחמת כהונתם מטומאת חרב הרי הוא כחלל אין יכולים כלל ליזהר דבשום בית שהיה בו מת מעולם נעשה כחלל כל המתכות שבתוכו והוי כמאהיל על המת כדאמרינן בנזיר בפ' כ\"ג (דף נג:) וגם לא היו צריכין ליזהר מטומאת חרב הרי הוא כחלל כיון שאין הנזיר מגלח עליה כדמוכח בריש תוספתא דאהלות וא\"כ כולן צריכין הזאה ואין סברא כלל שתקנו חכמים חלת חו\"ל שלא יאכלוה אא\"כ ילך ויזה בא\"י ולהכי מסתבר שבלא הזאה וטבילה היו אוכלין אותה אפילו לרבנן דרבי יוסי ובבבל וכן לדידן שרחוקין מא\"י א\"צ שתי חלות אלא אחת כדאמרינן בפ' עד כמה (בכורות דף כז.) ונותנה לכהן קטן ואכיל לה דכי ליכא כהן קטן דוקא קאמר התם דמפריש אחרת ונותנה לכהן גדול וראשונה שורפה וחלה של אור מנהר ועד אמנון ולפנים אינה מותרת לכהן קטן אלא לעולם נשרפת דומיא דחלת אור א\"י משום דסמוכין לא\"י ומתחזיא כחלת א\"י כדפרישית ומש\"ה צריך לעולם שתים אבל ברחוקים כגון דבבל ודידן דלא מתחזיא חלה דידהו כחלת הארץ טמאה נותן לכהן קטן ומסתבר דאף לכהן גדול שטבל לקריו ולא בעינן הערב שמש דאין להחמיר בה מבחלה של כהן בסמוכין לא\"י וכ\"כ בה\"ג בהלכות חלה אמר רבינא הלכה נדה קוצה לה חלה ואכיל לה כהן קטן או מאן דטביל לקריו ויש קצת תימה אמאי קאמר דנותנה לכהן קטן כיון דאפילו כהן גדול יכול לאוכלה אחר שטבל או לבטלה ברוב כמו תרומה דאמרינן בפ' עד כמה (שם) רבה הוה מבטל לה ברוב ואכיל לה בימי טומאה ונראה דדוקא חלת חו\"ל לפי שאין לה שיעור ודבר מועט הוא קאמר דיכול ליתנה לכהן קטן כ\"ש אם יש כהן גדול שטבל או רוצה לבטלה שיכול ליתנה לו וכן משמע דדבר מועט הוא דקאמר התם דשקל לה בריש מסיא אבל תרומה שהיא מתבואה או מיין ושמן אין ליתן לכהן קטן לפי שהוא מאבדה ועוד יש לה שיעור כמו בתרומת מעשר ולכך אין ליתנה לקטן אלא לכהן גדול שטבל או רוצה לבטלה ברוב וא\"צ להפריש שניה דלא תשתכח כיון דמפרישין אחת כמו בחלה היכא דאיכא כהן קטן שלא מצינו בכל הש\"ס שהיה צריך לפרש שתי תרומות אלא דוקא חלה כי ליכא כהן קטן או גדול שטבל שאז היא נשרפת ולכך צריך להפריש חלה שניה שלא תשתכח תורת חלה אבל תרומה דאין נותנין אותה אלא לכהן גדול שטבל או רוצה לבטלה ברוב א\"צ להפריש שניה דלא תשתכח כיון שמפרישין אחת ומיהו נראה דגם בסמוכים לא\"י שמפרישין לעולם שתי חלות לא היו מפרישין אלא תרומה אחת לכך נראה שבחלה יש לחוש יותר שלא תשתכח משום דשייכא בכל אדם המגלגל עיסתו אבל תרומה אין רגילין בה אלא בעלי קרקעות וממריחי תבואות והיכא דליכא כהן קטן ששורפה ומפריש שניה נותנה לכהן טמא אפילו הוא זב דלא מפליג התם בשום טומאה ולא דמיא לחלה שניה בסמוכין לא\"י דהתם לעולם צריך להפריש אבל ברחוקים אי איכא כהן קטן או גדול שטבל לקריו אין צריך להפריש חלה שניה כלל והיא קלה ביותר אלא שאסורה לזרים דלא אשכחן דשרי לה אלא לכהנים ונראה שאינה טובלת שהרי יש כמה מקומות דלא מפרשי לה כלל ואפילו ליכא כהן קטן ועל אותן מקומות יש קצת תימה אלא לפי שאינה טובלת וצריך לשומרה מלהאכילה לזרים נמנעו מלהפריש ושמא אפילו אינה מדמעת ואף על פי שהראשונה נראה קצת דמדמעת מדתניא בפרק רבי ישמעאל (מנחות דף סז.) תרומת עובד כוכבים בחו\"ל אינה מדמעת דמשמע הא דישראל מדמעת מ\"מ השניה שהיא קלה ביותר שמא אינה מדמעת וכמו שלא גזרו על תערובות דמאי כמו כן שמא לא גזרו בה כיון שהיא קלה כל כך:"]]],[["נאכלת עם הזר על השלחן וניתנת לכל כהן שירצה","אמר ליה אביי בשלמא אי אשמועינן חלת חוצה לארץ בארץ דאיכא למיגזר משום חלת הארץ דאורייתא ולא גזרינן איכא למשמע מינה","אלא חו\"ל משום דליכא למיגזר הוא אבל הכא אי שרית ליה לאסוקי עוף וגבינה אתי לאסוקי בשר וגבינה ומיכל בשר בחלב דאורייתא","מתקיף לה רב ששת סוף סוף צונן בצונן הוא אמר אביי גזירה שמא יעלה באילפס רותח","סוף סוף כלי שני הוא וכלי שני אינו מבשל אלא גזירה שמא יעלה באילפס ראשון:","\u0001מתני׳\u0002 העוף עולה עם הגבינה על השולחן ואינו נאכל דברי ב\"ש וב\"ה אומרים לא עולה ולא נאכל א\"ר יוסי זו מקולי ב\"ש ומחומרי ב\"ה","באיזה שולחן אמרו בשולחן שאוכל עליו אבל בשולחן שסודר עליו את התבשיל נותן זה בצד זה ואינו חושש:","\u0001גמ׳\u0002 רבי יוסי היינו ת\"ק וכ\"ת אכילה גופה איכא בינייהו דקאמר ת\"ק בהעלאה קא מיפלגי באכילה לא פליגי ואמר ליה רבי יוסי אכילה גופה מקולי בית שמאי ומחומרי ב\"ה","והתניא רבי יוסי אומר ששה דברים מקולי ב\"ש ומחומרי ב\"ה וזו אחת מהן עוף עולה עם הגבינה על השולחן ואינו נאכל דברי ב\"ש ובה\"א לא עולה ולא נאכל","אלא הא קמשמע לן מאן תנא קמא רבי יוסי כל האומר דבר בשם אומרו מביא גאולה לעולם שנאמר (אסתר ב, כב) ותאמר אסתר למלך בשם מרדכי","תנא אגרא חמוה דרבי אבא עוף וגבינה נאכלין באפיקורן הוא תני לה והוא אמר לה בלא נטילת ידים ובלא קינוח הפה","רב יצחק בריה דרב משרשיא איקלע לבי רב אשי אייתו ליה גבינה אכל אייתו ליה בשרא אכל ולא משא ידיה אמרי ליה והא תאני אגרא חמוה דרבי אבא עוף וגבינה נאכלין באפיקורן עוף וגבינה אין בשר וגבינה לא","אמר להו הני מילי בליליא אבל ביממא הא חזינא","תניא בית שמאי אומרים מקנח ובית הלל אומרים מדיח מאי מקנח ומאי מדיח"],[[0,"נאכלת","לכהן עם הזר ולא גזרינן דילמא שקיל זר מיניה ואכיל דהא אכילה גופה לא מיתסרא בה אלא משום גזירת אכילת חלת הארץ:"],[0,"לכל כהן שירצה","אפילו לעם הארץ שאין משמרה בטהרה מה שאין כן בחלת הארץ דכתיב (דברי הימים ב ל״א:ד׳) לתת מנת לכהנים למחזיקים בתורת ה' מחזיקים יש להם מנת ולא שאין מחזיקין. אלמא בדרבנן לא גזרינן העלאה אטו אכילה:"],[1,"בשלמא אי אשמועינן תלת חו\"ל בארץ","שהביאה לארץ ואשמועינן דאע\"ג דיש כאן חלה דאורייתא ואיכא למיגזר הא אטו הא דאי מסקת חלת חוצה לארץ (לארץ) אתי לאסוקי חלת הארץ ומיכלה הזר הוה איכא למשמע מינה מתניתין נמי אי לא דאכילת עוף דאורייתא לא הוה גזר העלאתו אטו אכילתו ולא אטו דבהמה אלא בחוצה לארץ טעמא משום דליכא למיגזר אטו שום איסור דאורייתא הוא:"],[2,"אבל הכא","אע\"ג דלא איבעי לן למגזר העלאתו אטו אכילתו איכא למיגזר העלאתו אטו העלאת ואכילת בשר בהמה דכי מסיק להו היינו אכילה דאתי למיכלינהו בהדדי:"],[3,"מתקיף לה רב ששת","אפילו את\"ל בשר עוף בחלב דאורייתא עדיין משכחת לה גזירה לגזירה דהא העלאה דרבנן משום אכילה ואכילה גופה דרבנן דהא סוף סוף צונן וצונן הוא ואפי' אכיל להו כי הדדי ליכא איסור דאורייתא דדרך בישול אסרה תורה:"],[3,"גזירה שמא יעלה","בשר בהמה עם הגבינה בתוך אילפס רותח דה\"ל בישול:"],[5,"מתני' ואינו נאכל","עם הגבינה:"],[5,"א\"ר יוסי דבר זה כו'","בגמ' פריך היינו תנא קמא:"],[6,"בשולחן שאוכל עליו","דאיידי דממשמשי ביה ידא אתי לאתנוחי זה ע\"ג זה:"],[8,"גמ' רבי יוסי אומר ו' דברים כו'","יש אחרות הרבה אבל באלו ששה לא היו מודים לו חביריו שיהיו ב\"ש מקילין ובית הלל מחמירין:"],[9,"כל האומר דבר בשם אומרו","והתנא שכח ולא הזכיר שמו בתחילה וחזר והזכיר שמו:"],[10,"באפיקורן","דרך הפקר שאינו נזהר בהן וכדמפרש:"],[10,"הוא תני","כך קבלה סדורה מרבו:"],[10,"והוא אמר לה","והוא פירשה מסברא שלו דמאי אפיקורן:"],[10,"בלא קינוח הפה","שאם אכל זה ובקש לאכול זה אין צריך ליטול ידיו ולקנח. אבל בבשר בהמה בעי קינוח כדלקמן שלא יהא נדבק כלום מן הראשון בחניכיו:"],[12,"הא קא חזינן","ידים ריקניות שאין דבוק בהם כלום:"]],[[0,"וניתנת לכל כהן שירצה","פירש בקונטרס דאפילו אינו מחזיק בתורת ה' יתנו לו חלת חוצה לארץ ואין נראה לר\"י דהא הוו דומיא דהנהו ששונה אחר משנה זאת ואלו ניתנין לכל כהן שירצה כו' וחשיב בהדייהו הזרוע והלחיים והקבה ואמרינן לקמן בפרק הזרוע (חולין דף קל:) שאינן ניתנות למי שאינו מחזיק בתורת ה' לכך נראה לרבינו יצחק דהכא מיירי בדליכא כהן חבר אי נמי איכא כהן חבר שהוא עשיר ואינו רוצה לקבל ואפילו רוצה לקבל כיון דאין צריך וזה ע\"ה עני וצריך שמצווים להחיותו שאם לא יתנו לו יצטרכו לתת לו חולין וקמ\"ל דיכול ליתן אע\"פ שאין בקי בטומאה וטהרה ולא חיישינן שמא יאכלנו בימי טומאתו אבל חלת הארץ אינה ניתנת אלא לכהן חבר שישמרנה בטהרה אפי' ליכא עתה כהן חבר אל יתננה לכהן ע\"ה אלא ימתין עד שיזדמן לו כהן חבר:"],[3,"מתקיף לה רב ששת","לא אאביי קא פריך אלא ארב יוסף חבירו פריך כדפי' בקונטרס:"],[7,"רבי יוסי היינו ת\"ק","אבית הלל לא פריך היינו ת\"ק דהכי קאמר דבר זה מחלוקת ב\"ש וב\"ה ואין זה סתמא ואח\"כ מחלוקת דב\"ש במקום בית הלל אינה משנה:"],[11,"עוף וגבינה אין בשר וגבינה לא","תימה דהיכי פריך מגבינה אחר בשר אבשר אחר גבינה דרב יצחק גבינה ואח\"כ בשר אכיל ולא דמי כדאמר בסמוך ויש לומר דהכי פריך דברייתא דאגרא משמע עוף וגבינה נאכלין באפיקורן בלי נטילת ידים ובלא קינוח הפה אבל שאר בשר בעי נטילה וקינוח הפה והיכי דמי אי בשר תחלה אפילו בנטילה וקינוח לא סגי עד סעודה אחריתי כדאמר בסמוך אלא לאו אגבינה תחלה והא דנקט הכא בשר וגבינה לא דק אלא. גבינה ובשר לא ואגב דמזכיר בברייתא עוף תחלה נקט נמי הכא בשר תחלה וברייתא נקט עוף תחלה דאפילו עוף תחלה נאכל באפיקורן ור\"ת מפרש וכן הלכות גדולות דאכל בשר אסור לאכול גבינה היינו בלא נטילה וקינוח אבל בנטילה וקינוח שרי אכל גבינה מותר לאכול בשר אף בלא נטילה וקינוח ומר עוקבא דלא אכיל עד סעודה אחריתי היינו בלא נטילה וקינוח אי נמי מחמיר על עצמו היה ולפירושו קשה מאי פריך הכא ארב יצחק וצ\"ל לפירושו דלענין נטילת ידים אין חילוק בין בשר תחלה לגבינה תחלה ולגבי קינוח דווקא יש חילוק והעולם נהגו שלא לאכול גבינה אחר בשר כלל ואפילו אחר עוף ואע\"ג דתני אגרא עוף וגבינה נאכלין באפיקורן דמשמע עוף תחלה דילמא משום דסבר בשר עוף בחלב לאו דאורייתא ולא קיימא לן הכי ומיהו קשה ברייתא דאגרא כמאן אי כרבי יוסי הגלילי הא אף לכתחלה שרי לבשל ולאכול זה עם זה כדאמר לקמן (חולין דף קטז.) דבמקומו של רבי יוסי הגלילי היו אוכלין בשר עוף בחלב ואי כר\"ע הוה ליה למיתני חיה בהדי עוף ודוחק להעמידה כב\"ש דאמרי העוף עולה ואינו נאכל ומיהו אשכחן נמי לרבי אלעזר בר' צדוק דתניא בתוספתא כב\"ש אי נמי כר\"ע ונקט עוף משום דשכיח והוא הדין חיה דהכי נמי קאמר לעיל הא עוף אסור מדאורייתא כמאן דלא כר\"ע והוה ליה למינקט נמי חיה ור\"ת מפרש טעמא דאגרא משום דעוף אינו נדבק בידים ובשינים וחניכים:"]]],[["אילימא בית שמאי אומרים מקנח ולא בעי מדיח ובית הלל אומרים מדיח ולא בעי מקנח אלא הא דאמר רבי זירא אין קינוח פה אלא בפת כמאן כב\"ש","אלא בית שמאי אומרים מקנח ולא בעי מדיח ובית הלל אומרים אף מדיח הוי ליה מקולי בית שמאי ומחומרי בית הלל ולתנייה גבי קולי בית שמאי וחומרי בית הלל","אלא בית שמאי אומרים מקנח והוא הדין למדיח וב\"ה אומרים מדיח והוא הדין למקנח מר אמר חדא ומר אמר חדא ולא פליגי","גופא אמר רבי זירא אין קינוח הפה אלא בפת והני מילי בדחיטי אבל בדשערי לא","ודחיטי נמי לא אמרן אלא בקרירא אבל בחמימא משטר שטרי והני מילי ברכיכא אבל באקושא לא והלכתא בכל מילי הוי קינוח לבר מקמחא תמרי וירקא","בעא מיניה רב אסי מרבי יוחנן כמה ישהה בין בשר לגבינה א\"ל ולא כלום איני והא אמר רב חסדא אכל בשר אסור לאכול גבינה גבינה מותר לאכול בשר אלא כמה ישהה בין גבינה לבשר א\"ל ולא כלום","גופא אמר רב חסדא אכל בשר אסור לאכול גבינה גבינה מותר לאכול בשר אמר ליה רב אחא בר יוסף לרב חסדא בשר שבין השינים מהו","קרי עליה (במדבר יא, לג) הבשר עודנו בין שיניהם","אמר מר עוקבא אנא להא מלתא חלא בר חמרא לגבי אבא דאילו אבא כי הוה אכיל בשרא האידנא לא הוה אכל גבינה עד למחר עד השתא ואילו אנא בהא סעודתא הוא דלא אכילנא לסעודתא אחריתא אכילנא","אמר שמואל אנא להא מלתא חלא בר חמרא לגבי אבא דאילו אבא הוה סייר נכסיה תרי זמני ביומא ואנא לא סיירנא אלא חדא זימנא שמואל לטעמיה דאמר שמואל מאן דסייר נכסיה כל יומא משכח אסתירא","אביי הוה סייר נכסיה כל יומא ויומא יומא חד פגע באריסיה דדרי פתכא דאופי אמר ליה הני להיכא אמר ליה לבי מר אמר ליה כבר קדמוך רבנן","רב אסי הוה סייר נכסיה כל יומא אמר היכא נינהו כל הני אסתירי דמר שמואל יומא חד חזא צינורא דבדקא בארעיה שקליה לגלימיה כרכיה אותביה בגוה רמא קלא אתו אינשי סכרוה אשכחתינהו לכולהו איסתרי דמר שמואל:","אמר רב אידי בר אבין אמר רב יצחק בר אשיין מים ראשונים מצוה ואחרונים חובה","מיתיבי מים ראשונים ואחרונים חובה אמצעיים רשות מצוה לגבי רשות חובה קרי לה","גופא מים ראשונים ואחרונים חובה אמצעיים רשות ראשונים נוטלין בין בכלי בין על גבי קרקע אחרונים אין נוטלין אלא בכלי ואמרי לה אין נוטלין על גבי קרקע","מאי בינייהו איכא בינייהו קינסא","מים ראשונים נוטלין בין בחמין בין בצונן אחרונים אין נוטלין אלא בצונן מפני שחמין מפעפעין את הידים ואין מעבירין את הזוהמא: מים ראשונים נוטלין בין בחמין בין בצונן: אמר רב יצחק בר יוסף אמר רבי ינאי לא שנו אלא שאין היד"],[[0,"אילימא בית שמאי אומרים מקנח","פיו:"],[0,"ולא מדיח","במים שהקינוח יפה מן ההדחה ולא הוזכרה כאן הדחה:"],[0,"ובית הלל אומרים מדיח ולא בעי קינוח","דלא סגי ליה בקינוח אלא מדיח במים והוא עיקר ואין צריך קינוח:"],[0,"אין קינוח פה","להכשיר לאכול בשר אחר גבינה:"],[0,"אלא","אם כן קנחו בפת דקינוח הפת שאוכל הפת בינתים היא יפה:"],[0,"נימא בית שמאי היא","דאי בית הלל הדחה בעי ולא הוזכר קינוח:"],[1,"אף מדיח","תרוייהו בעינן וקאמר רבי זירא דקינוח בין למר ובין למר בפת הוא:"],[1,"וליתנייה","במסכת עדיות (פ\"ד ופ\"ה) שכל קולי ב\"ש וחומרי ב\"ה נשנו שם:"],[2,"והוא הדין","דתרווייהו בעינן:"],[3,"בדשערי לא","מפני שמתפרר בתוך הפה ואינו נקשר יחד כשלועסו לפיכך אינו מקנח:"],[4,"שטר","נעשה רך ונדבק בחיך. ודוגמתו בהשוכר (ב\"מ דף פה:) אשטר מישטר תחבושת על העין:"],[4,"אקושא","קשה יותר מדאי וגם הוא מתפרר בתוך הפה כשל שעורים:"],[4,"קמחא תמרי וירקא","רכין הן:"],[5,"בין בשר לגבינה","משמע שאכל בשר ורוצה לאכול גבינה:"],[5,"אסור לאכול גבינה","משום דבשר מוציא שומן והוא נדבק בפה ומאריך בטעמו:"],[6,"בשר שבין השיניים","מי חשיב בשר שלא לאכול גבינה עמו עד שיטלנו:"],[7,"הבשר עודנו","אלמא מיקרי בשר:"],[8,"אנא להא מילתא חלא בר חמרא","לדבר זה אני גרוע מאבי כחומץ בן יין:"],[8,"למחר כי השתא","מעת לעת:"],[9,"סייר","הולך ורואה קרקעותיו מה הן צריכות:"],[9,"משכח איסתירא","מוצא סלע מפני שמתקנם בכל הצריך:"],[10,"פתכא דאופי","משוי עצים שהיה גונבו:"],[10,"קדמוך","שאמרו שיהא אדם רואה נכסיו בכל יום ויראה מה יעשה:"],[11,"צנורא דבדקא","המים יוצאין חוץ לגדותיהן ובאין לשטוף פירותיו דרך פחת שבשפת האמה:"],[11,"רמא קלא","הרים קול וצווח:"],[12,"מצוה","לשמוע דברי חכמים:"],[12,"חובה","עדיפא ממצוה. ולקמיה מפרש מאי חובותייהו:"],[13,"אמצעיים","שנוטלין בין תבשיל לתבשיל בעלמא:"],[13,"מצוה לגבי רשות חובה קרי לה","משום דתני אמצעיים בהדייהו קרי לראשוני' חובה דאע\"פ שאינן אלא מצוה חשיבות הן אצל הרשות לקרותם חובה:"],[14,"בין בכלי","מתחתיהם לקבלם:"],[15,"קינסא","אם נותן שפאי עצים וקסמין תחתיהן למאן דאמר כלי הכא לאו כלי הוא ולמ\"ד אין נוטלין על גבי קרקע שפיר דמי ולקמן מפרש משום דרוח רעה שורה עליהן כשהן על גבי קרקע:"],[16,"מפעפעין","אשטנ\"ט מרככין את הידים ומבליעין בהן את זוהם התבשיל:"]],[[0,"אילימא ב\"ש אומרים מקנח ולא בעי מדיח","פירש בקונטרס שהקינוח יפה מן ההדחה ולא הוזכר כאן הדחה וב\"ה אומרים מדיח ולא בעי מקנח ולא סגי ליה בקינוח אלא מדיח במים והוא עיקר ואינו צריך קינוח וקשה לפירושו דלא הוה ליה למימר ולא בעי אלא מקנח ולא מדיח מדיח ולא מקנח ועוד אמאי דחיק לאסוקי דלא פליגי לימא דלבית שמאי עדיף קינוח ובית הלל סברי דאף בהדחה לחודיה סגי כמו בקינוח לחודיה לכן נראה דפשיטא ליה למסדר הש\"ס דהדחה עדיף מקינוח והכי פירושא בית שמאי סברי מקנח ולא בעי מדיח כלומר בקינוח סגי אע\"ג דגרע ולא בעי מדיח דעדיף וב\"ה סברי מדיח לחודיה בעינן והשתא הוה ליה למימר ולא סגי במקנח דגרע אלא איידי דנקט לב\"ש ולא בעי נקט נמי לבית הלל והשתא הוה ליה למיפרך אם כן הוה ליה מקולי בית שמאי ומחומרי ב\"ה אלא דאית ליה פירכא אחריתי ולא מצי לשנויי דבית שמאי תרתי בעי ונקט מקנח והוא הדין דבעי מדיח בהדיה ובית הלל סברי דסגי בחד או מדיח או מקנח דאם כן הוו להו לבית הלל למינקט מקנח דהוי רבותא טפי דגרע ממדיח:"],[2,"מקנח וה\"ה למדיח","תרווייהו בעינן כדפי' בקונט' וכ\"פ ר\"ח:"],[8,"לסעודתא אחריתא אכילנא","לאו בסעודתא שרגילין לעשות אחת שחרית ואחת ערבית אלא אפילו לאלתר אם סילק השולחן ובירך מותר דלא פלוג רבנן:"],[12,"מים ראשונים מצוה ואחרונים חובה כו'","בברכות בסוף פרק אלו דברים (ברכות דף נג: ושם) דריש תרווייהו מקרא מוהתקדשתם אלו מים ראשונים והייתם קדושים אלו מים אחרונים ואסמכתא בעלמא הוא דהא טעמא דמים אחרונים הוי משום מלח סדומית כדאמר בסמוך ואנו לפי שאין מלח סדומית מצוי בינינו לא נהגו במים אחרונים והכי נמי כי דריש התם כי קדוש זה שמן שהיו סכין את ידיהן להעביר את הזוהמא הוי אסמכתא דלא מצינו בשום מקום שיהא שמן לא חובה ולא מצוה והא דאמר התם כשם שהמזוהם פסול לעבודה כך ידים מזוהמות פסולין לברכה היינו להם שהיה הדבר עליהם חובה ליטול אחר סעודה לפיכך נחשבות כמזוהמות וצריך להקדים וליטול קודם ברכה וא\"ת למאי נפקא מינה הא דראשונים מצוה ואחרונים חובה מה לי מצוה מה לי חובה הא תרווייהו חובה כדקתני בברייתא ולא רשות ואומר רבינו תם דנפקא מינה לענין מלחמת הרשות דתנן בפ\"ק דעירובין (דף יז.) דפטורין מרחיצת ידים וקאמר רב חייא בגמ' לא שנו אלא מים ראשונים אבל אחרונים לא דאמר רב יהודה בריה דרב חייא מפני מה אמרו מים אחרונים חובה מפני שמלח סדומית כו' ובהלכות גדולות פירש דראשונים שהם מצוה משום סרך תרומה טעונין ברכה אבל אחרונים שהם לצורך אדם משום מלח סדומית אין טעונין ברכה ומכאן כתב רבינו יהודה בפרק במה מדליקין בתוספ' שאין לברך על קריאת שמע שלפני מטתו אשר קדשנו במצותיו וצונו לקרות שמע ואם תאמר אמצעיים כגון בין גבינה לבשר שהן לצורך מצוה יהיו טעונין ברכה וי\"ל דאין זה כי אם הכשר אכילה כמו ניקור חלב ומליחת בשר:"]]],[["סולדת בהן אבל היד סולדת בהן אין נוטלין בהן","ואיכא דמתני לה אסיפא אחרונים אין נוטלין אלא בצונן אבל בחמין לא אמר רב יצחק בר יוסף אמר רבי ינאי לא שנו אלא שהיד סולדת בהן אבל אין היד סולדת בהן נוטלין מכלל דראשונים אף על פי שהיד סולדת בהן מותר","אמצעיים רשות אמר רב נחמן לא שנו אלא בין תבשיל לתבשיל אבל בין תבשיל לגבינה חובה","אמר רב יהודה בריה דרבי חייא מפני מה אמרו מים אחרונים חובה שמלח סדומית יש שמסמא את העינים אמר אביי ומשתכח כי קורטא בכורא אמר ליה רב אחא בריה דרבא לרב אשי כל מלחא מאי אמר ליה לא מבעיא","אמר אביי מריש הוה אמינא האי דלא משו מיא בתראי על ארעא משום זוהמא אמר לי מר משום דשריא רוח רעה עלייהו","ואמר אביי מריש הוה אמינא האי דלא שקיל מידי מפתורא כי נקיט איניש כסא למשתי שמא יארע דבר קלקלה בסעודה אמר לי מר משום דקשי לרוח צרדא","ולא אמרן אלא דשקיל ולא מהדר אבל משקל ואהדורי לית לן בה ולא אמרן אלא חוץ לארבע אמות אבל תוך ארבע אמות לית לן בה ולא אמרן אלא מידי דצריך לסעודתא אבל מידי דלא צריך לסעודתא לית לן בה","מר בר רב אשי קפיד אפילו אאסיתא ובוכנא דתבלי מידי דצריכי לסעודתא","ואמר אביי מריש הוה אמינא האי דכנשי נשווראה משום מנקירותא אמר לי מר משום דקשי לעניותא","ההוא גברא דהוה מהדר עליה שרא דעניותא ולא הוה יכיל ליה דקא זהיר אנשוורא טובא יומא חד כרך ליפתא איבלי אמר השתא ודאי נפל בידאי בתר דאכיל אייתי מרא עקרינהו ליבלי שדינהו לנהרא שמעיה דקאמר ווי דאפקיה ההוא גברא מביתיה","ואמר אביי מריש הוה אמינא האי דלא שתי אופיא משום מאיסותא אמר לי מר משום דקשי לכרסם מישתיה קשה לכרסם מינפח ביה קשיא לרישא מדחייה קשיא לעניותא מאי תקנתיה לשקעיה שקועי","לכרסם דחמרא שיכרא דשיכרא מיא דמיא לית ליה תקנתא והיינו דאמרי אינשי בתר עניא אזלא עניותא","ואמר אביי מריש הוה אמינא האי דלא אכלי ירקא מכישא דאסר גינאה משום דמיחזי כרעבתנותא אמר לי מר משום דקשי לכשפים","רב חסדא ורבה בר רב הונא הוו קאזלי בארבא אמרה להו ההיא מטרוניתא אותבן בהדייכו לא אותבוה אמרה מלתא אסרתה לארבא אמרו אינהו מילתא שריוה אמרה להו מאי איעביד לכו דלא מקנח לכו בחספא ולא קטיל לכו כינה אמנייכו ולא אכיל לכו ירקא מכישא דאסר גינאה","ואמר אביי מריש הוה אמינא האי דלא אכלי ירקא דנפל אתכא משום מאיסותא אמר לי מר משום דקשה לריח הפה ואמר אביי מריש הוה אמינא האי דלא יתבי תותי מרזיבא משום שופכים אמר לי מר משום דשכיחי מזיקין","הנהו שקולאי דהוו דרו חביתא דחמרא בעו לאיתפוחי אותבוה תותי מרזיבא פקעה אתו לקמיה דמר בר רב אשי אפיק שיפורי שמתיה אתא לקמיה אמר ליה אמאי תעביד הכי אמר ליה היכי אעביד כי אותביה באונאי","אמר ליה את בדוכתא דשכיחי רבים מאי בעית את הוא דשנית זיל שלים אמר ליה השתא נמי ליקבע לי מר זימנא ואפרע קבע ליה זימנא כי מטא זימנא איעכב כי אתא אמר ליה אמאי לא אתית בזמנך אמר ליה כל מילי דצייר וחתים וכייל ומני לית לן רשותא למשקל מיניה עד דמשכחינן מידי דהפקרא","ואמר אביי מריש הוה אמינא האי דשדי מיא מפומא דחצבא משום ציבתא אמר לי מר משום דאיכא מים הרעים","ההוא בר שידא דהוה בי רב פפא אזל לאתויי מיא מנהרא איעכב כי אתא אמרו ליה אמאי איעכבת אמר להו עד דחלפי מים הרעים אדהכי"],[[0,"סולדת","נכוית. אם היד סולדת בהן בטלו ונשתנו מתורת מים:"],[1,"איכא דמתני לה אסיפא","לא שנו דאחרונים בחמין לא:"],[1,"מכלל כו'","דבהנך דאסר לאחרונים שרי לראשונים:"],[3,"שמלח סדומית יש","ואמרו חכמים על כל אכילתך אכול מלח וכיון דנגע במלח כי הדר יהיב ידו אעינים מסמא להו ולפיכך צריך לנטלן:"],[3,"ומשתכחא כי קורטא בכורא","אינה מצויה אלא קורט בכור:"],[3,"כל מילחא","מדד מלח כמו (שמות ט״ז:י״ח) וימודו בעומר וכלו בעומרא:"],[3,"מאי","צריך ליטול אחריו או לא:"],[4,"משום זוהמא","שריחן מסריח ונראות מאוסות:"],[5,"למישתי","כשאדם שותה אין לוקחין כלום מלפניו:"],[5,"דבר קלקלה","שמא יכעוס השותה שחפץ באותו דבר הניטל וכי יכעוס יסתכן ויחנק:"],[5,"רוח צרדא","אשטורדישו\"ן:"],[6,"חוץ לארבע אמות","שמוציאו חוץ לארבע אמות של שולחן:"],[8,"דכנשי נשווראה","שמכבדין פירורי אוכלין מן הבית:"],[8,"מנקירותא","לנקר הבית נקיון:"],[9,"מהדר אבתריה שרא דעניותא","שר הממונה על העניות היה רודף ללוכדו ולהביאו לידי עניות:"],[9,"איבלי","על עשבים שבאפר:"],[9,"נפל לידאי","שלא יוכל ללקט הפירורין מבין העשבים ויהו למדרס רגלים ואלכדנו בכך:"],[9,"שמעיה","ההוא גברא לההוא שרא:"],[9,"דקאמר ווי דאפקיה מביתיה","הוציאני זה ממקום מנוחתי:"],[10,"אופיא","אשקומ\"א:"],[10,"לכרסם","רירין הבאין מן החוטם:"],[10,"מדחיה","בידו לצדדין:"],[10,"לישקעיה שקועי","בתוך המשקה עד שיכלה מאליו:"],[11,"לכרסם דחמרא","שבא לו מחמת אופיא דחמרא:"],[11,"שכרא","רפואתו לשתות שכר:"],[11,"לכרסם דשכרא","שבא מחמת אופיא דשכרא לישתי מיא:"],[11,"בתר עניא","זה שלא היה לו אלא מים לשתות:"],[12,"מכישא דאסר גינאה","שאין מוציאין שום או כרישין מאגודה שאוגדין מוכרי ירק לאוכלו:"],[12,"כרעבתנותא","שאין יכול להמתין עד שיתירנו:"],[12,"לכשפים","הרואה אותו יכול לעשות לו כשפים והנשמר ממנו אין כשפים נוחין לחול עליו:"],[13,"מטרוניתא","נכרית:"],[13,"אותבן בהדייכו","הושיבוני עמכם בספינה:"],[13,"אמרה מילתא","לחש של מכשפות:"],[13,"אסרתה לארבא","שלא זזה ממקומה:"],[13,"אמרי אינהו מילתא","אף הן היו בקיאין בדבר ועושין להציל עצמם מיד המכשול. ואיכא דאמרי שאמרו שם ולא מוכחא מילתא:"],[13,"מאי איעבד לכו","שאין מכשפות שולטת בכם שאתם נשמרין מכל דבר הקשה להן:"],[13,"דלא מקנח לכו בחספא","אין אתם מקנחין עצמכם בחרס בבית הכסא ואין אתם הורגין כינה במלבושכם:"],[14,"מרזיבא","צינור המקלח מים מן הגג:"],[14,"שופכין","שמא ירדו עליו מים מאוסין המקלחים מתשמיש המשתמשין על הגג ושופכין מי תשמיש והן באין לצינור:"],[15,"שקולאי","נושאי משאות בשכר:"],[15,"פקעה","ששברה המזיק:"],[15,"שמתיה","למזיק:"],[15,"דאותביה באונאי","הושיבוה באזני שהייתי ישן שם:"],[16,"דצייר וחתים","כלומר באחד מכל אלו אין לנו רשות:"],[17,"דשדו מיא","השותה בכד שופך תחלה מן המים לארץ:"],[17,"משום ציבתא","קסמין וקשין שעל פני המים:"],[17,"מים רעים","פעמים ששתה מהן שד וזו תקנתן:"],[18,"דהוה בי רב פפא","שהיה משמשו:"],[18,"עד דחלפי מים הרעים","ששתו המזיקין מהן:"]],[[2,"לא שנו אלא בין תבשיל לתבשיל","אומר רבינו שמואל דמיירי בשניהם של בשר או שניהם של גבינה אבל בין תבשיל של בשר לגבינה שלפניו חובה אבל לגבינה של אחריו לא קאמר דאפילו בנטילת ידים אסור לאכול עד סעודה אחרת כדאמר לעיל אכל בשר אסור לאכול גבינה ואין נראה לר\"ת דבין תבשיל לגבינה משמע תבשיל תחלה כדאמר לעיל כמה ישהה בין בשר לגבינה ולא כלום ופריך והא אמר רב חסדא אכל בשר אסור לאכול גבינה אלא כמה ישהה בין גבינה לבשר כו' ועוד בין תבשיל לתבשיל בשניהם של בשר או של גבינה למה יש לו ליטול כלל ומפרש ר\"ת דבין תבשיל לתבשיל היינו בין תבשיל דבשר לתבשיל של גבינה דכיון דאין הבשר והגבינה בעין וליכא אלא טעם לא החמירו שיהא חובה ליטול ידיו בינתיים ואינו אלא רשות אבל בין תבשיל דבשר לגבינה שהגבינה בעין חובה ויתכן פירוש זה אף לדברי האוסרין לאכול גבינה אחר בשר באותה סעודה אפי' בנטילה וקינוח:"]]],[["חזנהו דקא שדו מיא מפומא דחצבא אמר אי הוה ידענא דרגיליתו למיעבד הכי לא איעכבי","כי אתא רב דימי אמר מים הראשונים האכילו בשר חזיר","אחרונים הוציאו את האשה מבעלה","כי אתא רבין אמר ראשונים האכילו בשר נבלה אחרונים הרגו את הנפש אמר רב נחמן בר יצחק וסימניך אתא רב דימי אפקה אתא רבין קטלה","ר' אבא מתני חדא מהני וחדא מהני לחומרא","איתמר חמי האור חזקיה אמר אין נוטלים מהן לידים ורבי יוחנן אמר נוטלין מהם לידים אמר רבי יוחנן שאלתי את רבן גמליאל בנו של רבי ואוכל טהרות ואמר לי כל גדולי גליל עושין כן","חמי טבריא חזקיה אמר אין נוטלין מהם לידים אבל מטבילין בהן הידים ורבי יוחנן אמר כל גופו טובל בהן אבל לא פניו ידיו ורגליו","השתא כל גופו טובל בהם פניו ידיו ורגליו לא כ\"ש אמר רב פפא במקומן דכולי עלמא לא פליגי דשרי משקל מינייהו במנא דכ\"ע לא פליגי דאסיר כי פליגי דפסקינהו בבת בירתא מר סבר גזרינן בת בירתא אטו מנא ומר סבר לא גזרינן","כתנאי מים שנפסלו משתיית בהמה בכלים פסולים בקרקע כשרין רבי שמעון בן אלעזר אומר אף בקרקע טובל בהן כל גופו אבל לא פניו ידיו ורגליו","השתא כל גופו טובל בהן ידיו ורגליו לא כ\"ש אלא לאו דפסקינהו בבת בירתא ובהא פליגי דמר סבר גזרינן בת בירתא אטו מנא ומר סבר לא גזרינן","אמר רב אידי בר אבין אמר רב יצחק בר אשיאן נטילת ידים לחולין מפני סרך תרומה","ועוד משום מצוה מאי מצוה אמר אביי מצוה לשמוע דברי חכמים רבא אמר מצוה לשמוע דברי ר\"א בן ערך דכתיב (ויקרא טו, יא) וכל אשר יגע בו הזב וידיו לא שטף במים אמר ר\"א בן ערך מכאן סמכו חכמים לנטילת ידים מן התורה","אמר ליה רבא לרב נחמן מאי משמע דכתיב וידיו לא שטף במים הא שטף טהור הא טבילה בעי אלא הכי קאמר ואחר שלא שטף טמא","אמר ר' אלעזר אמר רבי אושעיא לא אמרו נטילת ידים לפירות אלא משום נקיות סבור מינה חובה הוא דליכא הא מצוה איכא אמר להו רבא לא חובה ולא מצוה אלא רשות ופליגא דרב נחמן דאמר רב נחמן הנוטל ידיו לפירות אינו אלא מגסי הרוח","אמר רבה בר בר חנה הוה קאימנא קמיה דרבי אמי ורבי אסי אייתו לקמייהו כלכלה דפירי ואכלו ולא משו ידייהו ולא יהבו לי מידי ובריך חד חד לחודיה שמע מינה תלת שמע מינה אין נטילת ידים לפירות וש\"מ אין מזמנין על הפירות ושמע מינה שנים שאכלו מצוה ליחלק","תניא נמי הכי שנים שאכלו מצוה ליחלק במה דברים אמורים שהיו שניהם סופרים אבל אחד סופר ואחד בור סופר מברך ובור יוצא","תנו רבנן נטילת ידים לחולין עד הפרק לתרומה"],[[1,"האכילו בשר חזיר","שהיה חנוני ישראל מוכר בשר שחוטה לישראל ומבשל ומאכילם וכשהעובד כוכבים בא בחנותו מאכילו נבלות ובא יהודי אחד לאכול ולא נטל ידיו וכסבור זה שעובד כוכבים הוא והאכילו בשר חזיר:"],[2,"הוציאו אשה מבעלה והרגו את הנפש","בפרק בתרא דיומא בעובדא דכידור איכא למ\"ד קטלה ואיכא למ\"ד לא קטלה אלא אפקה:"],[3,"וסימניך","שלא תטעה מי מהם אמר הוציאו ומי מהם אמר הרגו:"],[3,"אתא רב דימי אמר אפקה אתא רבין אמר קטלה","הראשון הוציאה והשני הרגה אחוז הסימן כאילו שניהם נעשו בה גירושין והריגה ושוב לא תטעה דודאי אין להחליף ולומר הראשון הרגה והשני הוציאה והם היו יודעין דרב דימי אתא מארץ ישראל מקמי רבין:"],[4,"חדא מהני כו' לחומרא","ראשונים בשר חזיר כרב דימי אחרונים הרגו כרבין. בשר חזיר חמור מנבלה דאית ביה תרי איסורי:"],[5,"אין נוטלין מהם","מים הראשונים ופליג אדלעיל וחזקיה תנא הוא:"],[5,"רבן גמליאל ברבי","בנו של רבי ואוכל טהרות היה:"],[6,"חמי טבריא חזקיה אמר אין נוטלין מהם לידים אבל מטבילין בהן הידים","אי איכא מ' סאה:"],[6,"כל גופו טובל בהן","אם נטמא ראויות הן לטבילת כל גופו:"],[6,"אבל לא פניו ידיו ורגליו","אם טבל בהם פניו ידיו ורגליו אין טבילה עולה לידים ולאכילה:"],[7,"השתא כל גופו כו'","הלא אף טבילה עולה לידים יותר מן הנטילה כדאמרינן בחגיגה (דף יח:) נוטלין לידים לחולין ולמעשר ולקדש מטבילין אלמא טבילת ידים עדיפא ולכל גופו חזו לטבילה לידיו לא כל שכן:"],[7,"במקומן","בחיבורן אם בא להטביל ידיו בהן:"],[7,"דכ\"ע שפיר דמי","דשם טבילה עליהם ככל מעיינות ומקוואות:"],[7,"משקל מינייהו במנא","לשפוך על ידיו כדין הנטילה:"],[7,"דכ\"ע אסור","דכי תקון רבנן נטילה לאו בחמין תקון והני גריעי מחמי האור שלא היתה להן שעת הכושר:"],[7,"דאפסקינהו בבת בירתא","חריץ קצר והמים פונים שם ואין שם שיעור מקוה אבל מחוברין למקוה דגזירה בעלמא הוא אטו מנא:"],[8,"שנפסלו משתיית בהמה","כגון סרוחין או חמי טבריא:"],[8,"בקרקע כשרין","להטביל ידיו דהא מקוה נינהו אבל נטילה לא תקנו רבנן אלא בראוין לשתיית בהמה:"],[8,"אבל לא פניו ידיו ורגליו","אפילו דרך טבילה. פניו ורגליו משום ידיו נקט להו ואורחא בעלמא נקט:"],[10,"נט\"י לחולין מפני סרך תרומה","הוצרכה שהידים שניות ופוסלות את התרומה אבל חולין לא מהני בהו שני ומפני סרך תרומה שירגילו אוכלי תרומה ליטול ידיהם הנוהגת בחולין:"],[11,"מצוה לשמוע דברי חכמים","שתקנוה:"],[11,"רבא אמר","דאורייתא היא מצוה כרבי אלעזר בן ערך:"],[11,"מכאן סמכו","כדמפרש ואזיל:"],[12,"הא שטף","במים את ידיו טהור מנגיעתו בזב בתמיה:"],[12,"אלא ה\"ק","הנוגע בזב ומי שאינו שוטף את ידיו שניהם טמאין ואסמכתא בעלמא היא:"],[13,"ופליגא דרב נחמן דאמר","גסות הוא ואסור לנהוג עצמו בגסות הרוח ולאו רשות היא:"],[14,"ולא יהבו לי מידי","שלא חשו לצרפני עמהם לזימון דקסברי אין מזמנין על הפירות לומר נברך:"],[14,"וש\"מ","מדברכו כל חד וחד לחודיה לאחריהם ולא יצא האחד בברכת חבירו שמע מינה בשנים מצוה ליחלק הואיל ואין כאן שלשה:"],[16,"עד הפרק","השני שבאמצע אצבעות דכיון דמשום סרך תרומה בעלמא הוא דיו אם נטל במה שנוגע במאכל דהיינו ראשי אצבעות:"],[16,"לתרומה עד הפרק","פרק השלישי והוא בגב היד:"]],[[0,"חזנהו דהוו שדו מיא מפומא דחצבא","והא דאיעכב ולא עשה בעצמו כן או שלא הודיעם לפי שהיה ירא שיקפידו עליו שאר השדים אם היה מודיע אי נמי אין מועיל אא\"כ שדי להו ההוא גברא גופיה דשתי:"],[5,"חמי האור חזקיה אמר אין נוטלין מהם לידים","והא דתניא לעיל (חולין דף קה.) מים ראשונים נוטלין בין בחמין בין בצונן מוקי חזקיה כלישנא קמא דר' ינאי דלעיל כשאין היד סולדת וכאן איירי כשהיד סולדת בהן ורבי יוחנן דשרי הכא בלשון בתרא דמוקי לה אע\"פ שהיד סולדת מותר ובחנם פירש בקונטרס דחזקיה תנא הוא ופליג אברייתא דלעיל:"],[7,"דפסקינהו בבת בירתא","והא דאמרינן בפרק ג' מינין (נזיר לח.) דרביעית דמקוה בטלי בטלוה היינו לענין מחטין וצינורות אבל שרי להטביל בהן ידיו א\"נ לגמרי בטלוה אף לידים והכא במחוברין למקוה וכן פירש בקונטרס:"],[8,"מים שנפסלו משתיית בהמה בכלים פסולין בקרקע כשרין","בפ\"ב דזבחים (דף כב.) אמרינן כל המשלים למי מקוה משלים למי באר ולרביעית אינו משלים למעוטי מאי אילימא למעוטי טיט הנרוק היכי דמי אי דפרה שוחה ושותה ממנו אפילו לרביעית נמי משלים פירש שם בקונטרס וכשרים הן לידים כדאמר בפרק כל הבשר מים שנפסלו משתיית בהמה בין בכלים בין בקרקע פסולין הא לא נפסלו כשרין ואגב ריהטא לא עיין כן ואם תאמר דהתם קאמר ואי דאין פרה שוחה ושותה ממנו אפילו למקוה נמי לא והכא משמע דלכ\"ע טובל בהן כל גופו ונראה לפרש דהתם מיירי שנפסלו משתיית בהמה מחמת שהטיט עב כל כך שאינה יכולה לשתות דאז אין שם מים עליו אבל הכא איירי בצלולין הרבה אלא דמאיס ומסרחי ומחמת כך אין הפרה יכולה לשתות:"],[11,"מצוה לשמוע דברי חכמים","וא\"ת והלא משום סרך תרומה תקנוה וא\"כ מאי ועוד וי\"ל דתקנו משום נקיות:"],[11,"מצוה לשמוע דברי רבי אלעזר בן ערך","פירוש דאסמיך ליה קרא דלאו דרשה גמורה דעיקר קרא אתא לכדדרשינן בנדה (דף מג.) מה ידיו מאבראי:"],[14,"ושמע מינה שנים שאכלו מצוה ליחלק","תימה לר\"י מנא ליה דמצוה ליחלק דילמא רשות כמ\"ד בריש פ' שלשה שאכלו (ברכות מה.) דאם רצו לזמן מזמנין דפלוגתא היא דרב ורבי יוחנן ועוד קשה דהתם לא פליגי אלא בפת שיש עליו תורת זמון בג' אבל פירות דאין מזמנין עליהן כלל כדאמר ש\"מ דאין מזמנין על הפירו' פשיטא דמצו' ליחלק וי\"ל דה\"ק ש\"מ אין מזמנין על הפירות פירוש אין חובה לזמן על הפירות אפילו כשהן שלשה מדלא נתנו לו ואין חילוק בפירות בין ג' לב' ואכתי לא ידעינן אם יכול לזמן בשנים בפת או בפירות אפילו בג' או אסור כמ\"ד אם רצו לזמן אין מזמנין אלא מדבריך כל חד וחד לחודיה שמע מינה דמצוה ליחלק דאם איתא דמותר לזמן לא היה מברך כל אחד לעצמו אלא היה מברך אחד לחברו ואומר נברך שאכלנו משלו כדי להוסיף שבח למקום ואכתי לא ידעינן אלא שבשנים אסור לומר נברך שאכלנו משלו אבל בלא נברך שמא יכול אחד לברך ולפטור חברו אבל מדתניא שנים שישבו מצוה ליחלק בד\"א כו' אלמא דבשניהם יודעים לברך חייבים שניהם לברך וא\"ת ומ\"ש ברכה דבסוף דכל אחד מברך לעצמו מברכה דבתחלה דאחד מברך לכולן כדמוכח בכיצד מברכין (ברכות דף לט.) גבי תלמידי (דרב) דהוו יתבי קמיה דבר קפרא ואייתו קמייהו פרגיות כרוב ודורמסקין ונתן בר קפרא רשות לאחד מהן לברך ובסוף אלו דברים (ברכות דף נג.) תניא היו יושבים בבית המדרש הביאו מאור לפניהם בית הלל אומרים אחד מברך לכולן ובפרק כיצד מברכין (ברכות מב:) תנן גבי מוגמר דאחד מברך לכולן ויש לומר דשאני ברכה דלכתחלה שכל אחד מרויח באותה ברכה שע\"י כן מותרין לאכול וליהנות לפיכך מצטרפין לה אבל בסוף שכבר אכלו לא מצטרפין והא דאמרינן בפרק כיצד מברכין (ברכות דף לז.) רבן גמליאל וזקנים שהיו מסובים בעליה ביריחו והביאו לפניהם כותבות ואכלום ונתן ר\"ג רשות לר' עקיבא לברך וקפץ וברך ברכה אחת מעין ג' היינו משום דר\"ג לטעמיה דחשיב להו כפת דקאמר התם כל שהוא מז' המינים רבן גמליאל אומר ג' ברכות ואע\"ג דר' עקיבא כרבנן סבירא ליה דאמרי ברכה אחת מעין ג' לא בשביל להוציא כולם ברך אלא ברך לעצמו בקול רם להודיע להם דהלכה כרבנן ומה שאין אנו נוהגין עכשיו לברך בתחלה אחד לכולן אלא בפת לחודיה לפי שאין אנו קובעים עצמנו להסב על היין ועל הפירות ואפילו גבי פת תנן בכיצד מברכין (שם דף מב.) היו יושבין כל אחד מברך לעצמו היסבו אחד מברך לכולן וגבי יין פליגי התם בגמרא (דף מג.) רב ור' יוחנן דרב סבר לא מהניא ליה היסבה ואיכא דאמרי לא בעיא היסבה ור' יוחנן אמר מהניא ליה היסבה ומיהו צריך עיון דפשט המשנה משמע דמיירי בברכה דלכתחלה ובגמרא משמע דמיירי בברכה דבסוף גבי תלמידי דרב דאמרי ניכול לחמא אנהר דינק בתר דכריכו יתבי וקא מבעיא להו היסבו אין לא היסבו לא או דלמא כו' משמע דלכ\"ע דברכה דלכתחלה הוה פשיטא להו דלא בעי היסבה דלא נסתפקו אלא לברכת המזון לבתר דכריכו ועוד דאי בברכה דלכתחלה פליגי רב ורבי יוחנן לרב מ\"ש יין ממוגמר ואור דאחד מברך לכולן וי\"ל משום דמוגמר ואור בא להם הנאה בבת אחת אבל קשה דבהדיא תנן התם בא להם יין לאחר המזון אחד מברך לכולם ואע\"ג דאיכא למימר דשאני התם דמגו דמהניא היסבה לפת מהניא נמי ליין דהכי נמי משני התם כי פריך ליה לרב מברייתא דאורחין מ\"מ הוה ליה לאקשויי טפי לרב ממתניתין ולשנויי הכי אלא להכי לא פריך ליה ממתניתין דעל כרחך איירי בברכה דמתחלה דומיא דיין שבתוך המזון אבל ברייתא ע\"כ איירי בברכה דבסוף מדבעי היסבה ולפי זה בברכה דלכתחלה לא בעי לאקבועי דוכתא לא בפת ולא בשאר דברים ובברכה דבסוף בעי לאקבועי דוכתא בין בפת בין בשאר דברים דהלכה כרבי יוחנן ומיהו יש ליישב כולה מלתא בברכה דבתחלה והא דפריך לרב מברייתא ולא ממתניתין משום דמברייתא פריך לתרי לישני דרב ומה שלא נסתפקו תלמידי דרב עד אחר המזון לפי שבתחלה לא באו בבת אחת לנהר דינק אלא היו מתקבצין שם ליסע משם בבת אחת וכל אחד שהיה מגיע שם היה יושב ואוכל והיה מברך לעצמו והא דמייתי שם ראיה ממתניתין דמיירי בברכה דלכתחלה אע\"ג דברכת המזון בשנים מצוה ליחלק ודבתחלה אחד מברך לחבירו מ\"מ מייתי ראיה דכי אמרי ניזול וניכול נהמא בדוכתא פלוני כהיסבה דמיא והוי קביעות ובכל מקום שהאחד מברך לכולם בין ברכה ראשונה בין ברכה אחרונה אין מברך אחד לכולם עד דקביעי:"]]],[["עד הפרק קידוש ידים ורגלים במקדש עד הפרק וכל דבר שחוצץ בטבילה בגוף חוצץ בנטילת ידים לחולין ובקידוש ידים ורגלים במקדש","אמר רב עד כאן לחולין עד כאן לתרומה ושמואל אמר עד כאן בין לחולין בין לתרומה לחומרא ורב ששת אמר עד כאן בין לחולין בין לתרומה לקולא","אמר בר הדיא הוה קאימנא קמיה דרבי אמי ואמר עד כאן בין לחולין בין לתרומה לחומרא ולא תימא רבי אמי משום דכהן הוא דהא רבי מיישא בר בריה דרבי יהושע בן לוי הוא ליואי ואמר עד כאן בין לחולין בין לתרומה לחומרא","אמר רב נוטל אדם את שתי ידיו שחרית ומתנה עליהן כל היום כולו אמר להו רבי אבינא לבני"],[[0,"קידוש ידים ורגלים","מן הכיור:"],[0,"עד הפרק","העליון מקום חבור היד והזרוע:"],[1,"עד כאן לחולין","מראה היה בידו כמו שפירשתי:"],[1,"ושמואל אמר","פרק החולין והתרומה שוין ולחומרא בפרק השלישי והוא שבגב היד:"],[2,"משום דכהן הוא","ורגיל בתרומה לפיכך החמיר על עצמו להרגיל אף בחולין כן כדי שיהא רגיל בה:"],[3,"ומתנה","לאכילה ובלבד שיזהר מלטנפם ומלטמאם:"]],[[0,"וכל דבר שחוצץ בטבילה חוצץ בנטילת ידים לחולין","הקשה הרב ר' אברהם בן הרב ר' משה דבתוספתא דמקוואות תניא בפרק ז' כל החוצץ בכלים חוצץ בנדה ובגר בשעת טבילה ובחולין אין חוצצין והכא קאמר דחוצצין וי\"ל דהכא איירי לאכילה כדמוכח כוליה שמעתא והחמירו באכילה כמו בטבילה והתם בנגיעה ואיירי אף בחולין שנעשו על טהרת תרומה דלא החמירו וצריך ליזהר בשעת נטילה מטיט ובצק שתחת הצפורן דחוצצין בטבילה כדתנן במסכת מקואות (פ\"ט מ\"ב) וכל דבר שחוצץ בטבילה צריך כמו כן ליזהר בנטילה לאכילה אבל במיעוט שאינו מקפיד אין לחוש דבטבילה נמי אינו חוצץ כדאמרינן בפ\"ק דעירובין (דף ד:):"],[1,"אמר רב עד כאן לחולין ועד כאן לתרומה","כדקתני בברייתא לחולין עד הפרק לתרומה עד הפרק כו' והיה מראה רב בידיו ופירש בקונטרס דעד הפרק לחולין הוא פרק ב' שבאמצע אצבעות ולתרומה עד הפרק שבגב היד ובקדוש ידים עד הפרק העליון מקום חבור היד והזרוע ולא רצה לפרש בקונטרס דפרק דחולין הוא פרק ראשון שבראש האצבעות לפי שאינו שוה בכל האצבעות כמו באגודל אבל פרק האמצעי שוה בכולם ושמואל אמר דפרק דחולין ודתרומה שוין לחומרא ולא פליג אברייתא אלא משום דכהן הוא ורגיל בתרומה לכך החמיר על עצמו להרגיל אף בחולין אבל לרב ששת קשה דאמר עד כאן בין לחולין בין לתרומה לקולא וי\"ל דרב ששת מפרש הברייתא בפרק הראשון שבראש אצבעות לחולין ושני לתרומה שהוא פרק אמצעי ולא להקל על הברייתא קאמר אלא אדרב ושמואל דאמרי דפרק דתרומה הוא מקום חבור אצבעות ותפיסת היד ור\"ת פירש ע\"כ לחולין פרק ראשון כמו שפירש רב ששת ולפירוש זה קשה ברייתא לרב ששת דלפירושו צריך לומר דלרב ששת דחולין ותרומה בפרק ראשון לקולא ומיהו יש לדחות דלשמואל לחומרא היינו פרק שבגב היד כמו קדוש ידים ובא רב ששת להקל משמואל אבל אין לפרש כמו שפירש הרב ר' אברהם דחולין עד פרק שלישי דאצבעות ולתרומה כל פיסת היד פירוש עד הקנה ולקדוש ידים עד העצילה שקורין קוד\"א בלע\"ז והביא ראיה מספר הזהיר שכתוב שם אמר שמואל לחולין כל היד ואי אפשר לומר כן מדתניא בפרק האומר משקלי עלי (ערכין יט:) משקל ידי ומשקל רגלי עלי ר' יהודה אומר ממלא אדם חבית ומכניס ידו עד העציל וברגל עד הארכובה ופריך וביד עד העציל ורמינהו קדוש ידים ורגלים במקדש עד הפרק ומשני דאורייתא עד הפרק בנדרים הלך אחר לשון בני אדם אלמא אין קדוש ידים עד העציל ומיהו יתכן פירושו לפי מה שמפרש שם דעציל היינו אישיל\"א והוא בית השחי מקום חבור הזרוע והכתף וכן פירש בקונטרס בפרק הזרוע (לקמן חולין קלד:) אבל קשה לר\"ת דאמר בזבחים (דף יח:) ולא יחגרו ביזע אין חוגרין במקום שמזיעין לא למטה ממתניהם ולא למעלה מאציליהם אלא כנגד אצילי ידיהם והיינו כנגד קוד\"א ששם דרך לחגור דאי במקום שחי אדרבה הוא מקום זיעה יותר ועוד דמה שייך לומר ולא למעלה דלמעלה הוי צואר ואיך יחגרו שם ועוד דבערכין (דף יט:) קאמר ביד עד העציל וברגל עד הארכובה משמע דעציל באמצע היד כמו הארכובה באמצע הרגל ועוד דבאהלות (פ\"א מ\"ח) כשמונה רמ\"ח אברים קתני ל' בפיסת היד ששה בכל אצבע שנים בקנה ושנים במרפק אחד בזרוע וארבעה בכתף משמע דמרפק הוא קוד\"א שכן הוא הסדר ומרפק ועציל הכל אחד דהא בערכין (דף יט.) קתני ר' יהודה במתניתין דהתם מכניס ידו עד מרפקו ותרגום כל אצילי ידים דיחזקאל (יג) כל מרפוקי ידיא ואין לפרש דקידוש ידים הוא עד בית השחי דהיינו עד הכתף דהא פריך בערכין ודאורייתא עד הפרק והא גבי תפילין כתיב ידך ותני דבי מנשה ידך זו קיבורת ומשני דאורייתא קיבורת כו' קידוש ידים ורגלים הלכתא גמירי לה משמע דפרק דקידוש ידים ורגלים אין מגיע עד קיבורת וקיבורת מפרש רבינו תם קבוצת בשר שבזרוע כמו (ב\"ב דף ה.) קיבורא דאהינא שהוא לשון קבוצת תמרים:"],[3,"נוטל אדם ידיו שחרית ומתנה עליהן כל היום","תימה דאמרינן בערבי פסחים (דף קו:) הנוטל ידיו לא יקדש משום דקידוש מפסיק בין נטילת ידים לסעודה ואמר בפרק אלו דברים (ברכות נב:) ב\"ה אומרים מוזגין כוס ואח\"כ נוטלין משום דתיכף לנטילת ידים סעודה והשתא הא מועיל תנאי אפילו כל היום ואומר ר\"ת דהני מילי כשמתנה שחרית ועוד י\"ל דאע\"ג דמועיל תנאי לרב אף שלא בשעת הדחק היינו אם אין מים בסמוך לו אי נמי יש לו וצריך לדברים אחרים:"]]],[["פקתא דערבות כגון אתון דלא שכיחי לכו מיא משו ידייכו מצפרא ואתנו עלייהו לכולא יומא איכא דאמרי בשעת הדחק אין שלא בשעת הדחק לא ופליגא דרב ואיכא דאמרי אפילו שלא בשעת הדחק נמי והיינו דרב","אמר רב פפא האי אריתא דדלאי אין נוטלין ממנו לידים דלא אתו מכח גברא ואי מיקרב לגבי דולא דקאתו מכח גברא נוטלין ממנו לידים","ואי בזיע דולא בכונס משקה מילף ליופי ומטביל בה את הידים ואמר רבא כלי שניקב בכונס משקה אין נוטלין ממנו לידים","ואמר רבא כלי שאין בו רביעית אין נוטלין ממנו לידים איני והאמר רבא כלי שאין מחזיק רביעית אין נוטלין ממנו לידים הא מחזיק אע\"ג דלית ביה","לא קשיא הא לחד הא לתרי דתניא מי רביעית נוטלין לידים לאחד ואפילו לשנים","אמר ליה רב ששת לאמימר קפדיתו אמנא א\"ל אין אחזותא א\"ל אין אשיעורא אמר ליה אין","איכא דאמרי הכי אמר ליה אמנא ואחזותא קפדינן אשיעורא לא קפדינן דתניא מי רביעית נוטלין לידים לאחד ואפי' לשנים","ולא היא שאני התם משום דקאתו משירי טהרה","אתקין רב יעקב מנהר פקוד נטלא בת רביעתא אתקין רב אשי בהוצל כוזא בת רביעתא","ואמר רבא מגופת חבית שתקנה נוטלין ממנה לידים תניא נמי הכי מגופת חבית שתקנה נוטלין ממנה לידים חמת וכפישה שתקנן נוטלין מהם לידים שק וקופה אע\"פ שמקבלים אין נוטלין מהם לידים","איבעיא להו מהו לאכול במפה מי חיישינן דלמא נגע או לא","ת\"ש וכשנתנו לו לרבי צדוק אוכל פחות מכביצה נוטלו במפה ואוכלו חוץ לסוכה ואין מברך אחריו מאי לאו הא כביצה בעי נטילת ידים","דלמא הא כביצה בעי סוכה ובעי ברכה","תא שמע דשמואל אשכחיה לרב דקאכיל במפה אמר ליה"],[[0,"פקתא דערבות","בקעה של אותה מדינה ואין מים מצויין להם:"],[0,"ופליגא דרב","דשרי אפי' בלא דחק:"],[1,"האי אריתא דדלאי","צינור ששופכין לו מים מן היאור בדלי והוא מוליך מים לשדות:"],[1,"אין נוטלין ממנו לידים","לתת ידיו לתוכו ויקלחו המים לתוכן דלאו מכח גברא אתו שכבר עבר כח השופך והן מקלחין מאליהם ואין כאן לא נטילה ולא טבילה נטילה דלאו מכח גברא קאתו טביל' נמי בצינור ליתא שאין כאן שעור מקוה:"],[1,"ואי מיקרב גבי דולא","כשהדולה שופך וזה נותן ידיו סמוך למקום השפיכה והמים מקלחין מכח השפיכה לתוך ידיו שפיר דמי:"],[2,"ואי בזיע דולא בכונס משקה","כשהנקב מכניס משקה גדול הוא קצת וקילוח היוצא ממנו נראה והשופך שופך דרך פיו לצינור והנקב מקלח מאחוריו ליאור:"],[2,"מילף לייף","הצינור עם היאור ע\"י דלי ומטבילין בצינור את הידים דלאו טבילה גמורה היא ודיה בחבור זה ולא בעינן כשפופרת הנוד כדין עירוב מקואות דעלמא:"],[2,"כלי שניקב כו'","לאו כלי הוא דרבנן כלי תקון:"],[4,"הא לחד והא לתרי","לחד רביעית בעינן מתחלה אבל לתרי שהיה בו רביעית ונטל הראשון ואח\"כ נטל השני אע\"ג דלא הוי רביעית בנטילת שני שפיר דמי הואיל ומשירי טהרה אתו כדמפרש לקמיה מי רביעית:"],[5,"קפדיתו אמנא","שיהא כלי שלם:"],[5,"אחזותא","שיהא בהן מראה מים:"],[5,"אשיעורא","דרביעית:"],[7,"דקאתו משירי טהרה","אבל מעיקרא צריך שיהא בו רביעית:"],[8,"נטלא בת רביעית","של זכוכית קרי נטלא והיתה מוצנעת לשער בה כלי של כל איש ואיש שמתקנו ליטול ידיו:"],[8,"כוזא","של חרס:"],[9,"שתקנה","חקקה לקבל רביעית אף על גב דמעיקרא לאו לאישתמושי בגווה עבידא ואין חללה עשוי לתוכו:"],[9,"חמת וכפישה","מיני נודות של עור הן:"],[9,"שק וקופה","אין מלאכתן למים דרובן אין מקבלין מים:"],[10,"במפה","מי שלא נטל ידיו מהו לפרוש מפה על ידיו ולא יגע באוכלין ויאכל:"],[11,"וכשנתנו לו לר' צדוק","במסכת סוכה כשהיו נותנין לו לרבי צדוק אוכל שהוא פחות מכביצה נוטלו במפה ואוכלו ולא היה נוטל ידיו ולא היה מצריכו סוכה ולא ברכת המזון:"],[12,"לא","הא דנקט פחות מכביצה משום סוכה וברכה נקט ליה:"]],[[1,"האי אריתא","פי' בקונטרס צינור ששופכין לו מים מן היאור בדלי והוא מוליך מים בשדה אין ר\"ל שיהא הצינור קרוי אריתא דהא יאורים מתרגמינן אריתי ובפ' הפרה (ב\"ק נ:) אמר ההוא תורא דנפל לאריתא ומשמע שם שהוא עמוק עשרה טפחים:"],[1,"דלא אתו מכח גברא","פירש בהלכות גדולות שמותר להטביל ידים בתוך הכלי דחשיבא נטילה והביא ראיה מפ\"ב דזבחים (דף כא.) דאיבעיא להו מהו לקדש ידיו ורגליו בכיור ממנו אמר רחמנא ולא לתוכו משמע דבקידוש ידים מבעי ליה משום דכתיב ממנו אבל בנטילת ידים אפילו בתוכן מותר וקשה לפירושו דהכא אמר אינו נוטל ממנו דלא אתי מכח גברא משמע דבעינן כח גברא השופך ומיהו י\"ל דבעינן נטילה מן הכלי בין טובל ידיו בתוך הכלי ובין שופך מן הכלי על ידיו יש כאן נטילה מן הכלי אבל הכא ידיו חוץ לכלי הן וכבר פסק כח הכלי כשהמים באים עליו הלכך אין כאן נטילה מן הכלי וגם טבילה אין כאן שהן שאובין והא דנקט דלא אתו מכח גברא לאו דוקא מכח גברא אלא משום דלא אתו מכח כלי דבעינן נטילה מן הכלי א\"נ משום דתנן במס' ידים בפ\"ק (מ\"ה) הכל כשרין ליתן מים לידים אפילו חרש שוטה וקטן ומניח חבית בין ברכיו ונוטל ומניח חבית על צדו ונוטל הקוף נותן לידים רבי יוסי פוסל בשניהם פירוש בקוף ובחבית נוטה על צדו והמים נשפכים מאליהן דבעי רבי יוסי מכח גברא ות\"ק לא בעי אלא שיהא כח כלי והשתא שמעתא דנקט כח גברא אתי כרבי יוסי אבל ההלכות גדולות אי אפשר להעמיד אלא כרבנן וצריך להחמיר כיון דסוגיא דשמעתין כרבי יוסי ואם אדם נוטל ידו אחת וחוזר ומשפשף בחברתה צריך לחזור וליטול כדאמרינן בפרק שני דידים (מ\"ג) נטל ידו אחת ושפשף בחברתה טמאה ואם שרה פתו במים או הדיח בהן את הכלים פסולים לנטילה ואם הדיח בהן ידיו כשרין דהכי תנן במסכת ידים וצריך לשפוך מים על ידיו ג' פעמים פעם ראשונה כדי להעביר טיט ודבר החוצץ מעל ידיו ופעם שניה לטהר ידיו ופעם שלישית לטהר אותן מים וכן מוכח בכמה דוכתין במסכת ידים שצריך מים ראשונים ושניים ומיהו אם בפעם אחת שופך מים הרבה כשיעור רביעית ידיו טהורות דתנן במסכת ידים (פ\"ב מ\"א) ידו אחת בשטיפה אחת ידו טהורה שתי ידיו משטיפה אחת ר\"מ מטמא עד שיטול מי רביעית פירוש ואפילו באין משירי טהרה דלא בעו רביעית כשנוטל בשתי שטיפות והשתא דליכא אלא שטיפה אחת צריך רביעית בשטיפה זו אבל בנוטל ידו אחת לא צריך רביעית כי אתו משירי טהרה אלא שתהא אותה שטיפה מרובה כשתים:"],[2,"ואי בזיע דולא בכונס משקה מילף לייפי","ואע\"ג דלענין טבילת כל גופו לא מהני מתרי טעמי דנצוק אינו חבור וגם בעינן כשפופרת הנוד לענין עירוב מקוואות גבי רביעית ידים לא החמירו:"],[5,"קפדיתו אחזותא","והא דתנן במסכת ידים (פ\"א מ\"ג) נפל בהן דיו או קנקנתום ונשתנו מראיהן פסולין דלמא הני מילי לתרומה:"],[7,"ולא היא שאני התם דקא אתו משירי טהרה","משמע דמעיקרא בעי למימר דאפילו הראשון לא בעי שיעור ותימה דהא בהדיא קתני מי רביעית לאחד וי\"ל דמתניתין לתרומה והוה דייק מיניה דכי היכי דאפילו לתרומה לא בעינן שיעור לשני ה\"ה בחולין אף לראשון ומסיק דשאני התם דאתו משירי טהרה:"],[9,"מגופת חבית שתקנה","פי' בקונטרס שחקקה נראה דבלא חקיקה היא רביעית אלא שמשופעת היא ואינה יושבת אלא מסומכת כעין כסוי כוסות של כסף וכסוי קנקנים ותקנה היינו שהרחיבה מלמטה עד שיושבת שלא מסומכת וקודם שתקנה אין נוטלין ממנה דאין בית קבול שלה חשוב כיון שאם בא להושיב בלא סמיכה היו המים נשפכין ואין נשאר בהם רביעית ואמר לעיל כלי שאין מחזיק רביעית אין נוטלין ממנה וכן משמע במסכת ידים (שם מ\"ב) דחשיב מגופת חבית בהדי דפנות הכלים דאין מחוסרין חקיקה אלא לפי שאין יושבין שלא מסומכין כדפרישית:"],[11,"ולא ברך אחריו","סבר כרבי יהודה דבעי כביצה דדריש ואכלת ושבעת אכילה שיש בה שביעה דהיינו כביצה בפרק ג' שאכלו (ברכות מט:) ודוקא לאחריו אבל לפניו משמע דמברך וכן לר\"מ דפוטר בפחות מכזית היינו דוקא לבסוף אבל בתחלה מברך אף בפחות מכזית ובהדיא מדקדק בירושלמי הכי ואע\"ג דבריש כיצד מברכין (ברכות לה.) נפקא לן ברכה דלכתחלה מק\"ו מברכה דלסוף כשהוא שבע מברך כשהוא רעב לא כ\"ש מ\"מ לא שייך לומר דיו ומברך בתחלה אמשהו ואע\"ג דלא מברך בסוף דאותו ק\"ו אינו אלא גילוי בעלמא דברכה דלפניו לאו דאורייתא כדתנן בפרק מי שמתו (ברכות דף כ:) בעל קרי על המזון מברך לאחריו ואינו מברך לפניו וכן בפרק היה קורא (ברכות טז.) תניא הפועלים שהיו עושים מלאכה אצל בעל הבית ואוכלין פתן אין מברכים לפניהם אבל מברכים לאחריהם שתי ברכות:"],[11,"מאי לאו הא כביצה בעי נטילת ידים","תימה היכי מצי למימר הכי הא ע\"כ בתרומה אפי' כביצה לא בעי נטילת ידים דהא התירו מפה לאוכלי תרומה דרבי צדוק כהן הוה כדמוכח בפ' מי שמתו (ברכות כ:) גבי מדלגים היינו ע\"ג ארונות כו' ובפ' כל פסולי המוקדשין (בכורות לו.) גבי ההוא בוכרא דהוה ליה לר' צדוק ובספ\"ק דיבמות (דף טו:) והיה אוכל חולין על טהרת תרומה וי\"ל דהוה מצי למימר וליטעמיך. [ע' תוס' יומא עט: ד\"ה הא ותוס' סוכה כז. ד\"ה הא כביצה]:"]]],[["עבדין כדין אמר ליה דעתי קצרה עלי","כי סליק ר' זירא אשכחינהו לר' אמי ור' אסי דקאכלי בבלאי חמתות אמר תרי גברי רברבי כוותייכו ליטעו בדרב ושמואל הא דעתי קצרה קאמר","אשתמיטתיה הא דאמר רב תחליפא בר אבימי אמר שמואל התירו מפה לאוכלי תרומה ולא התירו מפה לאוכלי טהרות ורבי אמי ורבי אסי כהנים הוו","איבעיא להו אוכל מחמת מאכיל צריך נטילת ידים או לא ת\"ש דרב הונא בר סחורה הוה קאי קמיה דרב המנונא בלם ליה אומצא ואכיל אמר ליה אי לאו דרב המנונא את לא ספינא לך","מאי טעמא לאו משום דזהיר ולא נגע לא דזריז קדים ומשי ידיה מעיקרא","תא שמע דאמר רבי זירא אמר רב לא יתן אדם פרוסה לתוך פיו של שמש אא\"כ יודע בו שנטל ידיו והשמש מברך על כל כוס וכוס ואינו מברך על כל פרוסה ופרוסה ור' יוחנן אמר מברך על כל פרוסה ופרוסה","אמר רב פפא בשלמא דרב ורבי יוחנן לא קשיא הא דאיכא אדם חשוב הא דליכא אדם חשוב","מכל מקום הא קאמר אא\"כ יודע שנטל ידיו שאני שמש דטריד","תנו רבנן לא יתן אדם פרוסה לשמש בין שהכוס בידו בין שהכוס בידו של בעל הבית שמא יארע דבר קלקלה בסעודה והשמש שלא נטל ידיו אסור ליתן פרוסה לתוך פיו","איבעיא להו מאכיל צריך נטילת ידים או אינו צריך","ת\"ש דתני דבי מנשה רבן שמעון בן גמליאל אומר אשה מדיחה את ידה אחת במים ונותנת פת לבנה קטן אמרו עליו על שמאי הזקן שלא רצה להאכיל בידו אחת וגזרו עליו שיאכיל בשתי ידיו","אמר אביי התם משום שיבתא","ת\"ש דאבוה דשמואל אשכחיה לשמואל דקא בכי אמר ליה אמאי קא בכית דמחיין רבאי אמאי דאמר לי קא ספית לבראי ולא משית ידיה ואמאי לא משית א\"ל הוא אכיל ואנא משינא","א\"ל לא מיסתייה דלא גמיר מימחא נמי מחי והלכתא אוכל מחמת מאכיל צריך נטילת ידים מאכיל אינו צריך נטילת ידים:","\u0001מתני׳\u0002 צורר אדם בשר וגבינה במטפחת אחת ובלבד שלא יהו נוגעין זה בזה רבן שמעון בן גמליאל אומר שני אכסנאין אוכלין על שלחן אחד זה בשר וזה גבינה ואין חוששין:","\u0001גמ׳\u0002 וכי נוגע זה בזה מאי הוי צונן בצונן הוא אמר אביי נהי דקליפה לא בעי הדחה מי לא בעי:","רשבג\"א שני אכסנאין אוכלין על שולחן וכו': אמר רב חנן בר אמי אמר שמואל לא שנו אלא שאין מכירין זה את זה אבל מכירין זה את זה אסור","תניא נמי הכי רבן שמעון בן גמליאל אומר ב' אכסנאים שנתארחו לפונדק אחד זה בא מן הצפון וזה בא מן הדרום זה בא בחתיכתו וזה בא בגבינתו אוכלין על שלחן אחד זה בשר וזה גבינה ואין חוששין","ולא אסרו אלא בתפיסה אחת תפיסה אחת סלקא דעתך אלא כעין תפיסה אחת","א\"ל רב יימר בר שלמיא לאביי שני אחין ומקפידין זה על זה מהו","אמר ליה יאמרו כל הסריקין אסורין וסריקי בייתוס מותרין","ולטעמיך הא דאמר רבי אסי אמר רבי יוחנן מי שאין לו אלא חלוק אחד מותר לכבסו בחולו של מועד יאמרו"],[[0,"עבדין כדין","וכי עושין כן לאכול בלא נטילה:"],[0,"דעתי קצרה","אסטניס אני דאע\"פ שנטלתי ידי אי אפשי לאכול בידי:"],[1,"בבלאי חמתות","חמתות בלויין וכורכין ידיהן בהם ואוכלים בלא נטילת ידים:"],[1,"ליטעו בדרב [ושמואל]","כסבורים אתם דהא דאשכחיה שמואל לדרב דאכיל במפה משום דלא נטל ידיו הוא:"],[1,"והא דעתי קצרה קאמר ליה","אלמא נטל ידיו:"],[2,"התירו מפה לאוכלי תרומה","דהכהנים זריזין הן ולא נגעי:"],[2,"ולא התירו לאוכלי","חוליהם בטהרה לפי שאינם למודין להשמר כמו כהנים:"],[3,"אוכל מחמת מאכיל","אדם שאוכל מיד חבירו התוחב לתוך פיו צריך האוכל נטילת ידים או אין צריך:"],[3,"בלם ליה אומצא","חתך לו חתיכת בשר:"],[3,"בלם","במ\"ם סתומה כמו (תהלים לב) עדיו לבלום שהמתג והרסן מחתכין עדיו (לבלום) של סוס ולי נראה בלם ליה אומצא לשון הטמנה בגחלים כמו (בכורות דף מ:) פיו בלום גבי מומין של בכור שפיו סגור שאין יכול לפותחו אלא מעט ורגליו מבולמות:"],[3,"אי לאו דרב המנונא את","אדם חכם וזריז כדמפרש ואזיל לא הוינא ספינא לך בלא נטילה:"],[4,"מאי","חוכמתיה:"],[4,"לאו דזהיר ולא נגע","אלמא אין צריך נטילת ידים ובלבד שלא יגע:"],[4,"לא","הכי קא\"ל אי לאו דרב המנונא את ויודע אני בך שנטלת ידיך. זריז עדיף מזהיר זהיר שיודע להזהר בשעת מעשה שלא יעבור על המצוה זריז הרואה את הנולד ומתקן עצמו שלא יבא לידי כך והיינו דאמרינן בע\"ז (דף כ:) זהירות מביאה לידי זריזות:"],[5,"השמש מברך על כל כוס וכוס","לפי שאין קבע לשתיית השמש שאינו יודע אם יתנו לו עוד הלכך אסח דעתיה מן השתיה:"],[5,"ואינו מברך על כל פרוסה ופרוסה","דבטוח הוא שלא ימנעו ממנו לחם:"],[6,"אי איכא אדם חשוב","בסעודה בטוח השמש שיתן לו לחם כל הצורך:"],[7,"דטריד","לשמש את המסובין ושוכח שלא נטל ונוגע באוכלין שיאכל. ואע\"פ שנוגע בכל הסעודה לא איכפת לן שלא הצריכו נטילה לנוגעין אלא לאוכלין:"],[8,"לא יתן אדם פרוסה לשמש","באחד מן האורחים קאמר שלא יכעוס בעה\"ב כשהוא שותה חונקו לו יין ומזיק לו ובלאו כעס נמי מתוך שחש שלא יכלה הלחם לאורחים הוא מביט ומציץ במה שזה נותן והכוס נשפך מידו ואפילו הכוס ביד השמש שמא ישפכנו:"],[10,"אשה מדיחה ידה במים","ביום הכפורים דאע\"פ שאסור ברחיצה התירו לאשה להדיח ידה אחת וליגע בפת:"],[10,"שלא רצה להאכיל בידו אחת","אפילו ידו אחת לא רצה להדיח כדי ליתן פת לתינוק ביוה\"כ ומונע מלהאכילו. אלמא מאכיל צריך נטילה:"],[11,"התם משום שיבתא","רוח רעה שורה על ידים שלא נטלו שחרית אבל נטל ידיו שחרית ולא נזהר בהן ובא להאכיל את חבירו אין צריך נטילה ולא אמרינן דאסתם נותן לתוך פיו תקון רבנן נטילה:"],[12,"","דמחיין רבאי:"],[12,"קספית לבראי בדלא משית","האכלת את בני ולא רחצת ידים תחלה:"],[13,"לא מסתייה דלא גמיר","לא די לו שאינו בקי בהלכות נטילה שהמאכיל אין צריך ליטול:"],[14,"מתני' שני אכסנאין","אין לחוש שיאכל זה משל חבירו:"],[17,"גמ' זה בא מן הצפון כו'","אלמא דוקא בשאין מכירין זה את זה קאמר:"],[18,"ולא אסרו","להעלות בשר עם הגבינה על השולחן:"],[18,"אלא בתפיסה אחת","בכרך אחד:"],[18,"תפיסה אחת ס\"ד","הא בלא שלחן אוכל עליו נמי אסור:"],[19,"מהו","כיון דמקפידין שאין זה אוכל משל זה מותר או לא:"]],[[3,"בלם ליה אומצא","פירוש ופת עמה:"],[11,"התם משום שיבתא","פירש בקונטרס רוח רעה שורה על הידים שלא נטלו שחרית ורבינו תם מפרש דבלא נתינת פת לתינוק מותר ליטול ידיו שחרית ביום הכפורים דלא גרע ממלוכלכות בטיט ובצואה דאמרינן שרוחץ כדרכו ואינו חושש ואין לך מלוכלכות יותר מזה שאין יכול ליגע בפיו ובעיניו בחוטמו ובאזניו דבכולהו אמרינן בפ' שמונה שרצים (שבת דף קט.) דתקצץ ידו משום בת מלך ושיבתא דהכא יש לפרש כמו שפירש ר\"ח שהוא רוח רעה השורה על האוכל כשבא ליתן הפת לתנוק בן ד' וה' שנים וחונקת אותו אם לא נטל ידיו באותה שעה אע\"פ שנטל שחרית ומה שאין אנו נזהרים עכשיו מזה לפי שאין אותה רוח רעה מצויה בינינו כמו שאין אנו נזהרין על הזוגות ועל הגילוי:"],[18,"כעין תפיסה אחת","ואם יש דבר מפסיק לא הוי כעין תפיסה אחת כההיא דמסכת ע\"ז בפרק רבי ישמעאל (עבודה זרה דף נ.) גבי אבני מרקוליס דאמר כאן בתפיסה אחת כאן בשתי תפיסות והיכי דמי כגון דאיכא גובה ביני וביני ולפיכך נוהגין עכשיו כשזה אוכל בשר וזה אוכל גבינה על שלחן אחד מניחין לחם או קנקן או שאר כלים להפסיק בינתיים או אוכל על מפה אחרת דהוי כעין שתי תפיסות וי\"מ דלא אסרו אלא בתפיסה אחת כלומר שהן בהוצאה אחת כגון אחים שקנו אתרוג בתפיסת הבית דיש נוחלין (ב\"ב קלז:) ופריך תפיסה אחת ס\"ד מה לי בהוצאה אחת ומה לי בשתי הוצאות אם מכירין זה את זה ומשני כעין תפיסה אחת דהיינו שמכירין זה את זה ולפי' זה לא איירי כלל שיהא מותר לאכול על שלחן אחד בשביל הפסק שבינתיים:"]]],[["כל הסריקין אסורין וסריקי בייתוס מותרין התם הא אמר מר בר רב אשי איזורו מוכיח עליו:","\u0001מתני׳\u0002 טיפת חלב שנפלה על החתיכה אם יש בה בנותן טעם באותה חתיכה אסור ניער את הקדרה אם יש בה בנותן טעם באותה קדרה אסור:","\u0001גמ׳\u0002 אמר אביי טעמו ולא ממשו בעלמא דאורייתא","דאי סלקא דעתך דרבנן מבשר בחלב מאי טעמא לא גמרינן דחדוש הוא אי חדוש הוא אף על גב דליכא נותן טעם נמי","אמר ליה רבא דרך בשול אסרה תורה","אמר רב כיון שנתן טעם בחתיכה חתיכה עצמה נעשית נבלה ואוסרת כל החתיכות כולן מפני שהן מינה","אמר ליה מר זוטרא בריה דרב מרי לרבינא מכדי רב כמאן אמר לשמעתיה כרבי יהודה דאמר מין במינו לא בטיל לימא פליגא אדרבא","דאמר רבא קסבר רבי יהודה כל שהוא מין ומינו ודבר אחר סלק את מינו כמי שאינו ושאינו מינו רבה עליו ומבטלו","אמר ליה אי דנפל ברוטב רכה הכי נמי הכא במאי עסקינן דנפל ברוטב עבה","ומאי קסבר אי קסבר אפשר לסוחטו מותר חתיכה אמאי נעשית נבלה אלא קסבר אפשר לסוחטו אסור","דאיתמר רב ורבי חנינא ורבי יוחנן דאמרי אפשר לסוחטו אסור שמואל ורבי שמעון בר רבי וריש לקיש דאמרי אפשר לסוחטו מותר","וסבר רב אפשר לסוחטו אסור והאיתמר כזית בשר שנפל לתוך יורה של חלב אמר רב בשר אסור וחלב מותר ואי סלקא דעתך אפשר לסוחטו אסור"],[[0,"כל הסריקין אסורין","לענין מצות דפסח תנא אין עושין סריקין המצויירין בפסח מפני שהאשה שוהה עליהן ומחמצתן ונחתום אחד ובייתוס שמו היה לו דפוס אחד מצוייר והיה מושיב לתוכו את הסריק והוא מצוייר מיד אמר להם אפשר יעשנה בדפוס ויקבענה מיד אמרו לו א\"כ יאמרו כל הסריקין אסורין וסריקי בייתוס מותרין. והכא נמי יאמרו כל האחין אסורין ואלו מותרין:"],[0,"איזורו מוכיח עליו","האיזור תמיד הוא קבוע בחלוקו וכשהוא פושט חלוקו ולובש חלוק אחר נוטל האיזור מזה וקובעו בזה וזה שאין לו אחר מכבסו עם איזורו והרואה כשהוא מכבסו ואיזורו עמו יודע שאין לו חלוק אחר ולכך התירו לו חכמים:"],[1,"מתני' טיפת חלב שנפלה על החתיכה","בתוך הקדירה על אחת מן החתיכות ולא הגיס את הקדירה ולא נחלק טעם הטיפה אלא לאותה חתיכה בלבד:"],[1,"אם יש בה בנותן טעם באותה חתיכה","כלומר שאין באותה חתיכה לבדה ששים לבטל הטיפה מיד נאסרת החתיכה. ובשאר חתיכות דקדרה לא איירי תנא דמתני' ובגמרא פליגי בה אם חוזרת אותה חתיכה ואוסרתן או לאו:"],[1,"ניער את הקדרה","הגיס בה מיד קודם שקבלה החתיכה טעם מן הטיפה דהשתא נתערבה הטיפה בכולן:"],[1,"אם יש בה בנ\"ט באותה קדרה","כלומר אין כח בטיפה לאסור כולן אא\"כ יש בנ\"ט ליתן בכל הקדרה:"],[2,"גמ' אמר אביי טעמו ולא ממשו בעלמא דאורייתא","הא דאסרינן בכל איסורין משנתנו טעם בהיתר אע\"פ שאין אוכל ממש כגון סילק האיסור ואין כאן אלא טעמו דאורייתא היא דגמרינן מבשר בחלב דאסריה רחמנא באכילה כדגמרינן לקמן (חולין דף קטו:) מלא תבשל שלשה פעמים האמורים בתורה ואע\"ג דכי מסלק זה מתוך זה לאחר בשולו אין כאן אלא הטעם ומיניה גמרינן לכל איסורין במה מצינו:"],[3,"דאי ס\"ד","בכל שאר איסורין טעמו דרבנן היא דלא גמרינן להו מבשר בחלב:"],[3,"מ\"ט לא גמרינן מיניה משום דחדוש הוא","דשניהם מין היתר זה לבדו וזה לבדו וכשנתערבו נאסרו ועוד שדרך בשול נאסרו בלא אכילה הילכך לא גמרינן חומרא מינייהו:"],[3,"אי חדוש הוא","אמאי קתני מתני' דבעיא טעמא בלא נותן טעם נמי אסור דהא חדושא חדיש ביה רחמנא ואפי' כל דהו דהא בשר בחלב הוא אלא ש\"מ לאו חדושא דאהכי קפיד רחמנא דומיא דכלאי הכרם דמתסרי נמי משום כלאי תערובת דכיון דלאו חדוש הוא גמרינן ליה (לעיל חולין דף צח.) מזרוע בשלה דמישתרי כל כמה דליכא טעמא:"],[4,"אמר ליה רבא","לעולם אימא לך חדוש הוא ודקאמרת אע\"ג דליכא טעמא ליתסר דהא ליכא למגמריה מזרוע בשלה על כרחך בגופיה גלי קרא דבעינן טעמא מדלא אסרתו תורה אלא דרך בשול שאסר הבשר להתבשל בחלב ואין לך כגון זו שלא יתן טעם:"],[5,"אמר רב","הא דתנן במתניתין אם יש בנותן טעם באותה חתיכה לאסור את כל הקדרה דכיון דנאסרה החתיכה היא עצמה כולה נעשית איסור ואוסרת כל החתיכות כולן ואפילו יש בהן כדי לבטל החתיכה כולה נאסרות כולן:"],[5,"מפני שהן מינה","ורב סבר לה כרבי יהודה דאמר מין במינו לא בטיל:"],[6,"לימא פליגא אדרבא דאמר","בפ' גיד הנשה (לעיל חולין דף ק:) קסבר רבי יהודה כל מין ומינו ודבר אחר שעם מינו כלומר מין דאיסור שנתערב עם מינו ובשאינו מינו דהיתר סלק את מינו דהיתר כמי שאינו מועיל לא לבטלו לאיסור דמין במינו לא בטיל ולא תוספת הוא נוסף עליו להיות שניהם איסור ולא יוכל מין האחר לרבות עליו ולבטלו אלא סלקהו כאילו אינו כאן וירבה שאינו מינו של היתר על האיסור ויבטלנו והכא נמי יש כאן רוטב שיוכל לבטל את כל החתיכה הנאסרת ואמאי אוסרת:"],[8,"ברוטב עבה","דק דק של בשר ושומן דכוליה מין בשר הוא:"],[9,"ומאי קסבר","רב באפשר לסוחטו באיסור שנבלע בהיתר ונתן בו טעם ואסרו וחזר ובישל ההיתר הזה עם היתר אחר שאפשר האיסור הנבלע בזה ליסחט ממנו וליחלק בהיתר האחרון ואין בו כשיעור לאסור את האחרון:"],[9,"אי קסבר","הותר גם הראשון מפני שנפלט האיסור ממנו ולכתחלה הוא דאסור שאין מבטלין איסור לכתחלה ומיהו דיעבד שרי לאכול אף הראשון:"],[9,"אמאי חתיכה נעשת נבלה","הא אפשר היא ליסחט ממנה וליחלק לאחרים שלא קבלו ממנה כלום ואין לנו לאסור עד שיתן החלב טעם בכולן דליכא למימר אפשר ליסחט מזה וליבלע בזה שהרי כולן שוין בטעמו ואיזה תתיר ואיזה תאסור:"],[9,"אלא קסבר","משנאסרה החתיכה שוב אין לה היתר בסחיטה ואשמועינן אף ההיתר שבה נעשה איסור להיות כאן שיעור גדול לאסור אחרים הרבה:"],[10,"מותר","אף הראשון שנאסר:"],[11,"בשר אסור","שנתן החלב טעם בו:"]],[[1,"טיפת חלב שנפלה על חתיכת בשר אם יש בנותן טעם באותה חתיכה","נאסרת כשהחתיכה כולה חוץ לרוטב איירי כדאמרינן בפ' גיד הנשה (לעיל חולין דף צו:) ולכך משערינן באותה חתיכה לבטל הטיפה ולא בשאר חתיכות משום דחלב מפעפע על כל החתיכה ואין מפעפע מחתיכה לחברתה אלא ע\"י ניעור וכסוי כדאמרינן בגמ' אילימא לא ניער כלל אמאי כל החתיכות אסורות מיבלע בלע מפלט לא פליט:"],[3,"מבשר בחלב מ\"ט לא גמרינן כו'","וא\"ת דהכא משמע דנפקא ליה לאביי טעם כעיקר מבשר בחלב ואילו בפ' אלו עוברין (פסחים דף מד:) ובפ' ג' מינין (נזיר דף לז.) פליגי ר' עקיבא ורבנן למר נפקא ליה טעם כעיקר ממשרת ולמר מגיעולי עובדי כוכבים ואביי דאיירי בההיא סוגיא משמע דידע לההיא ברייתא וי\"ל דאביי קבלה מרבא שדחה לו וחזר בו:"],[3,"דחדוש הוא","פי' בקונטרס דשניהן מין היתר זה לבדו וזה לבדו וכשנתערבו נאסרין וטעם זה לא קאמר באלו עוברין (פסחים דף מד:) ובפ' ג' מינים (נזיר דף לז.) דהא כלאים נמי הכי הוו ומסיק דהיינו חדושו דאי תרו ליה כוליה יומא בחלבא שרי אע\"ג שנבלע החלב בבשר אע\"פ שהוא צונן לפי שהוא צלול והבשר שוהה בתוכו וכי בשיל ליה אסור:"],[4,"אמר רבא דרך בשול אסרה תורה","דיחויא בעלמא הוא דמהכא ליכא למילף אבל טעם כעיקר הוי דאורייתא כדפי' (בקונטרס) פ' גיד הנשה (לעיל חולין דף צח: ד\"ה רבא):"],[7,"דאמר רבא קסבר רבי יהודה כו'","פי' בקונטרס דאמר רבא בפ' גיד הנשה (חולין דף ק:) ואין לשון זה שם אבל בפ' הקומץ רבה (מנחות דף כג. ושם ד\"ה אמר) איתיה גבי רבי יהודה אומר מנחת כהנים כמנחת כהן משיח כו' ומדרבא דאמר הכי בפ' גיד הנשה (לעיל חולין דף ק:) אליבא דרב לא בעי לאקשויי הכא דרב אדרב דאיכא לשנויי כדמשני אביי התם כשקדם וסלקו אבל בההיא דהקומץ רבה (מנחות דף כב.) ליכא טעמא אחרינא לרבי יהודה אלא כמו שמפרש רבא ולהכי פריך שפיר מינה וא\"ת אמאי לא פריך מדרבי יהודה גופיה דלקמן קאמר רבי יהודה בברייתא האי לישנא גופיה דקאמר רב הכא אדרבא דמפרש טעמא דרבי יהודה וי\"ל דלא שמיע ליה ברייתא כי היכי דלא שמיע ליה לרב דאי ידע ליה רב לא הוה ליה למימר אלא הלכה כרבי יהודה ותו לא ועוד י\"ל דברייתא דרבי יהודה משמע שפיר דאין ברוטב ששים לבטל החתיכה מדאמור רבנן עד שתתן טעם ברוטב ובחתיכות משמע דליכא ברוטב לחודיה כדי לבטל:"],[9,"אפשר לסוחטו מותר","פי' דיעבד אי נסחט האיסור ונתבטל מותרת עם החתיכה שכבר נאסרת אבל לכתחלה אין מבטלין איסור כדפירש בקונטרס:"]]],[["חלב אמאי מותר חלב נבלה הוא","לעולם קסבר רב אפשר לסוחטו אסור ושאני התם דאמר קרא (שמות כג, יט) לא תבשל גדי בחלב אמו גדי אסרה תורה ולא חלב","וסבר רב גדי אסרה תורה ולא חלב והא איתמר חצי זית בשר וחצי זית חלב שבשלן זה עם זה אמר רב לוקה על אכילתו ואינו לוקה על בשולו ואי ס\"ד גדי אסרה תורה ולא חלב אאכילה אמאי לוקה חצי שיעור הוא","אלא לעולם קסבר רב חלב נמי אסור והכא במאי עסקינן כגון שנפל לתוך יורה רותחת דמבלע בלע מפלט לא פלט","סוף סוף כי נייח הדר פליט כשקדם וסילקו","גופא חצי זית בשר וחצי זית חלב שבשלן זה עם זה אמר רב לוקה על אכילתו ואינו לוקה על בשולו מה נפשך אי מצטרפין אבשול נמי לילקי אי לא מצטרפין אאכילה נמי לא לילקי","לעולם לא מצטרפי ובבא מיורה גדולה","ולוי אמר אף לוקה על בשולו וכן תני לוי במתניתין כשם שלוקה על אכילתו כך לוקה על בשולו ובאי זה בשול אמרו בבשול שאחרים אוכלין אותו מחמת בשולו","ואפשר לסוחטו עצמו תנאי היא דתניא טפת חלב שנפלה על החתיכה כיון שנתנה טעם בחתיכה החתיכה עצמה נעשת נבלה ואוסרת כל החתיכות כולן מפני שהן מינה דברי ר' יהודה","וחכ\"א עד שתתן טעם ברוטב ובקיפה ובחתיכות","אמר רבי נראין דברי ר' יהודה בשלא ניער ושלא כסה ודברי חכמים בשניער וכסה","מאי לא ניער ולא כסה אילימא לא ניער כלל ולא כסה כלל מבלע בלע מפלט לא פלט","ואלא לא ניער בתחלה אלא בסוף ולא כסה בתחלה אלא בסוף אמאי הא בלע והא פלט","קסבר אפשר לסוחטו אסור"],[[0,"חלב אמאי מותר","הרי חלב מעט שנבלע בבשר נעשה נבלה שהרי נאסר וכשחזר ונפלט בשאר החלב הוה ליה מין במינו חלב אסור בחלב היתר ורב אית ליה מין במינו לא בטיל:"],[0,"חלב נבלה הוא","זה שנבלע ונסחט:"],[1,"גדי אסרה תורה ולא חלב","ואפילו חלב מותר ואפילו היה בבשר שיעור גדול לתת טעם בשר בכל החלב ס\"ל נמי לרב דחלב מותר:"],[2,"חצי זית חלב","הכי משערינן יין וחלב וכל משקה לשערו בכזית מביא כוס מלא משקין ומביא זית ונותן לתוכו הזית והמשקה יוצא לחוץ וההוא דנפיק הוי כזית וכך היא שנויה בתוספתא בפרק נזיר שאכל:"],[2,"לוקה על אכילתו","דכזית איסור אכל:"],[2,"ואינו לוקה על בשולו","לקמן מפרש טעמא בשמעתין:"],[3,"אלא לעולם קסבר רב חלב נמי אסור גרסי'","היכא דיש בו טעם איסור או איסור מינו בלא טעם:"],[3,"והכא במאי עסקינן","דאמר רב לעיל בשר אסור חלב מותר כגון שנפל אותו זית לתוך יורה רותחת דמה שבולע אינו פולט שכל זמן שאינו נח מרתיחותיו אינו פולט:"],[4,"כשקדם וסילקו","לאותו זית קודם שתנוח:"],[6,"לעולם לא מצטרפי","לעשות איסור אא\"כ היה בו בתחלה כשיעור וכי אמר רב לוקה על אכילתו שבא מיורה גדולה ולצדדין אמר רב למילתיה אכל חצי זית בשר וחצי זית חלב הבא מיורה גדולה שנתבשל בה שיעור מזה ומזה ונאסרו לוקה על אכילתו שאכל שיעור שלם איסור של שם אחד ואין לוקה על בשולו דאם בשל כחצי זית בשר וכחצי זית חלב זה עם זה לפי שאין מצטרפין מכלל היתרן לקרות איסור עד שיהא בכל אחד ליעשות איסור לעצמו:"],[7,"אחרים","עובדי כוכבים. כלומר שנתבשל כל צרכו:"],[8,"כיון שנתנה טעם באותה חתיכה","כלומר כיון שיש בה כדי ליתן טעם באותה חתיכה הכל אסור ואפילו ניער את הקדרה דאיכא למימר נחלק לכולן והרי אין בו כדי לאסור אפ\"ה אסור וטעמא מפרש לקמיה:"],[8,"מפני שהן מינה","לפיכך אוסרת כולן ואפילו הן אלף שיש בהן כדי לבטל חתיכת האיסור כו' דכיון דמינו נינהו לא בטיל טעמא דבשר דנפיק מיניה שאף טעם הבשר נאסר:"],[9,"וחכ\"א עד שתתן טעם כו'","קס\"ד דאטפה קיימי עד שיהא בה כדי ליתן טעם בכולם אין כאן איסור אפילו בחתיכה ראשונה מפני שהוא חוזר ונסחט:"],[9,"קיפה","דק דק של בשר שיורד לשולי קדרה:"],[10,"נראין כו'","מפרש לקמיה כולה מילתא דרבי:"],[10,"ניער","הגיס בה במגיס. המנער את הקדרה מתפשט הטעם בכולה וכן המכסה אותה מפני שמי השוליים עולין עד פה ויורדין:"],[11,"אילימא לא ניער כלל","אמאי נאסרות האחרות:"],[11,"מבלע בלע","ההיא חתיכה:"],[11,"מפלט לא פליט","באחרות את טעם החלב שהחלב בגגה של חתיכה הוה:"],[12,"לא ניער בתחלה","וקבלה החתיכה את הטעם ואח\"כ ניער וחזרה ופלטתה באחרות:"],[12,"הא בלע והא פלט","מה שבלעה וחזרה להתירה והאיסור שיצא ממנה אין בו כשיעור לאסור:"],[13,"קסבר אפשר לסוחטו אסור","מפני שכולה נעשית איסור וכל הנסחט ממנה אסור וכל הנשאר בה אסור וכיון דאף טעם בשר שבה נאסר חוזר ואוסר האחרות אפילו הן אלף דמין במינו לא בטיל:"]],[[0,"אמאי מותר חלב נבלה הוא","מכאן היה מדקדק רבינו שמואל דלמ\"ד מין במינו לא בטיל צריך תרי ששים ששים ברוטב לבטל טעם חתיכת נבלה וששים בחתיכת היתר לבטל רוטב היוצא מן הנבלה וקשה לר\"י לדבריו דמשני גדי אסרה תורה ולא חלב והלא בעלמא חתיכה של היתר נעשית נבלה מדרבנן וצריך ששים כנגד כולה דמדאורייתא לא צריך ס' אלא כנגד האיסור הנבלע בה א\"כ אע\"ג דגדי אסרה תורה ולא חלב מ\"מ מדרבנן החלב עצמו נאסר כשאר איסורין דמאי שנא משאר איסורין ויאסור כל חלב שביורה אלא ודאי כיון שהחלב הנפלט מן הבשר לא נעשה נבלה אלא מטעם בשר המעורב בו אין לו דין חלב טמא אלא מתבטל בחלב שביורה כמו שמתבטל טעם בשר האסור ולא חשיב מין במינו והכי נמי רוטב הנפלט מן הנבלה אין לו דין מים אסורין שלא להתבטל במים אחרים אלא יש לו דין בשר נבלה שמתבטל שפיר במים שבקדרה והא דקאמר חלב נבלה הוא וקאי הכי במסקנא היינו דוקא בבשר בחלב שכל אחד לבדו היתר וכשנתבשל יחד עשה הכתוב הכל כנבלה והוא כחלב היוצא מן הטרפה ולכך לוקה על חצי זית חלב הנבלע מחצי זית שמנונית בשר אבל מים הנפלטים מן הנבלה אין נאסרין אלא מחמת טעם הנבלה המעורב בהן ואין מצטרפין ללקות עליהן משום נבלה ומכאן יש להוכיח דתבלין הבלועים מחלב או מדם ונפלו לקדרה מתבטלין בששים ואע\"ג דנותנין טעם אפי' באלף מותר דאינו חמור מן האיסור הנבלע בהן:"],[1,"גדי אסרה תורה ולא חלב","והא דנקט כזית בשר בתוך יורה גדולה משום דאם נפל לתוך חלב מועט היה נחשב הכל כגדי משום שמנונית הבשר המעורב בחלב ולא נתבטל:"],[3,"שנפל לתוך יורה רותחת דמבלע בלע מפלט לא פלט","תימה דדבר הנראה לעינים הוא דפליט דכשנותנין ירק בקדרה רותחת משתנה מראית המים מן הירק וכן בשר שומן נימוח לתוכה ונראה השמנונית על הרוטב ופי' רבינו שמואל דהא דקאמר מפלט לא פליט היינו עד שיהא שבע מלבלוע אבל לאחר ששבע חוזר ופולט וכן פירש הרב רבינו שמעיה סוף סוף כי נייח הדר פליט היינו כי נייח מבליעתו ומשני שקדם וסלקו קודם שגמר בליעתו ואותן כלים וקערות האסורות כשמגעילים אותם בתוך יורה גדולה ומניחין אותן מבפנים כשהמים רותחין היה מצריך רבינו שמואל להניחם שעה גדולה עד כדי שיהא להם שהות לגמור בליעה ולחזור ולפלוט אח\"כ ודבר תימה הוא דמי בקי לידע שיעור זה ואומר ר\"ת דהא דקאמר הכא מבלע בלע מפלט לא פליט היינו לא פליט מה שבלע עכשיו אבל מה שהיה בלוע מקודם פליט ואין להתיר מטעם זה להגעיל כלי שהוא בן יומו כשאין במים ששים לבטל האיסור ולהניחן בפנים כשהן רותחין משום דמים מבלע בלעי האיסור שבכלי ולא פלטי דבמים שהן צלולים לא שייך לומר בליעה דלא בלעי אלא שמתערב בהן האיסור וגם אין סברא לומר דכי היכי דאמר מבלע בלע מפלט לא פליט מה שבלע הכי נמי מפלט פליט מבלע לא בלע מה שפלט ועוד דא\"כ יהא אסור להגעיל שני כלים זה אחר זה דבהגעלת הראשון נאסרו המים והשני יבלע מן המים האסורין דודאי פליטת עצמו לא יבלע אבל פליטת כלי אחר יבלע וגם כלי הראשון אינו מכניס כולו בבת אחת במים רותחים וא\"כ מה שנכנס תחלה פולט וצד השני שמכניס אח\"כ בולע מה שפלט צדו הראשון לכך נראה דאין להגעיל כלי בן יומו כשאין במים ס' לבטל והגעלה דמדין דלא אסרה תורה אלא בן יומו לא הגעילו אלא כלים קטנים בתוך הגדולים שהיה במים ששים לבטל האיסור ובערב פסח קודם ארבע שעות מותר להגעיל כלי של חמץ אע\"פ שאין במים ס' דאיכא ג' נותני טעם של היתר החמץ נ\"ט בכלי והכלי נ\"ט במים והמים חוזרין ונבלעין בכלי ועדיין הוא היתר שהוא קודם הפסח:"]]],[["מכלל דר' יהודה סבר כי ניער מתחלה ועד סוף וכסה מתחלה ועד סוף אסור אמאי הא לא בלע כלל","אימא לא ניער יפה יפה ולא כסה יפה יפה","אמר מר ודברי חכמים כשניער וכסה מאי ניער ומאי כסה אילימא ניער בסוף ולא ניער בתחלה וכסה בסוף ולא כסה בתחלה האמרת נראין דברי ר' יהודה בהא אלא ניער מתחלה ועד סוף וכסה מתחלה ועד סוף","מכלל דרבנן סברי ניער בסוף ולא ניער בתחלה כסה בסוף ולא כסה בתחלה מותר","אלמא קסברי אפשר לסוחטו מותר","א\"ל רב אחא מדיפתי לרבינא ממאי דבאפשר לסוחטו פליגי דלמא אפשר לסוחטו דברי הכל אסור והכא במין במינו קא מיפלגי ורבי יהודה לטעמיה דאמר מין במינו לא בטיל ורבנן לטעמייהו דאמרי מין במינו בטיל","האי מאי אי אמרת בשלמא דרבנן במין במינו הכא כרבי יהודה סבירא להו ובאפשר לסוחטו פליגי היינו דקאמר רבי נראין דברי רבי יהודה בהא ודברי חכמים בהא","אלא אי אמרת אפשר לסוחטו דברי הכל אסור והכא במין במינו קמיפלגי האי נראין דברי ר' יהודה ואין נראין מבעי ליה ותו לא מידי:","\u0001מתני׳\u0002 הכחל קורעו ומוציא את חלבו לא קרעו אינו עובר עליו הלב קורעו ומוציא את דמו לא קרעו אינו עובר עליו: \u0001גמ׳\u0002"],[[0,"ופרכינן מכלל דר' יהודה סבר כי ניער כו'","נמי אסירי דמדקאמר רואה אני דברי ר' יהודה בשלא ניער בתחלה אבל איני רואה את מה שהוא אוסר אף בשניער מכלל דאיהו אף בשניער אסר מדלא קתני אמר רבי לא אמר ר' יהודה אלא בשלא ניער:"],[0,"הא לא בלעה","חתיכה ראשונה יותר מן האחרונה ובטיפה הזאת אין שיעור לאסור את כולן:"],[1,"שמא לא ניער תחלה יפה","ובלעה ואח\"כ פלטה כשניער בסוף ובהא גזירה לא סבר לה רבי כוותיה אבל בדאפשר לסוחטו אסור ובמין במינו לא בטיל סבר לה כוותיה:"],[2,"אמר מר ודברי חכמים","המתירין את הכל נראין לרבי כשניער אבל בשלא ניער לא נראה לו מכלל דהם מתירין אף בשלא ניער:"],[2,"ומאי ניער","דקאמר רבי:"],[2,"אילימא ניער בסוף ולא בתחלה","דאע\"ג דקבלה את הטעם קאמר רבי דרואה הוא את דברי המתירין הואיל וניער בסוף וחזר ונסחט דקסבר אפשר לסוחטו מותר האמרת נראין דברי ר' יהודה בהא:"],[2,"ניער מתחלה ועד סוף","ראה את דברי המתירין בזו דכיון דפשט מתחלה הטעם בכולה קדרה ואין בה כדי לאסור את כולה מותר ולא ראה דברי ר' יהודה החושש שמא לא ניער יפה יפה:"],[3,"מכלל דרבנן סברי כו'","מדקאמר רואה אני את דבריהם בשניער בתחלה ואין אני רואה את דבריהם מה שהתירו בשלא ניער מתחלה והן מתירין אותו בניעור שבסוף ומשום סחיטה מכלל דקסברי אפשר לסוחטו מותר:"],[5,"וממאי דבאפשר לסוחטו פליגי","והאי עד שתתן דקאמרי רבנן אטיפה קאי ושרי אף החתיכה דילמא חתיכה קמייתא ודאי אסירא ואסיפא דמילתיה דרבי יהודה דאסר את השאר אפילו הן אלף מפני שהן מינה פליגי רבנן ואמרי לעולם אין חתיכה זו אוסרת את השאר עד שיהא בחתיכה כדי לתת טעם בכולן דמין במינו נמי בטיל ורבי הכי קאמר רואה אני את דברי רבי יהודה לאסור אף בשאר החתיכות בשלא ניער בתחלה וקבלה טעם האיסור ונעשת איסור אלא בסוף וחזרה ופלטה באחרות ומין במינו לא בטיל ואין אני רואה דבריו בשניער בתחלה דהא לא נעשת איסור ולשמא לא ניער יפה לא חיישינן ורואה אני את דברי המתירין כשניער בתחלה כדפרישית דלא נעשת איסור ולשמא לא ניער לא חיישינן ואין אני רואה היתר אפילו באחרות בשלא ניער בתחלה אלא בסוף דנעשת איסור מתחלה ואוסרת בסוף את חברותיה במשהו דמין במינו לא בטיל:"],[6,"האי מאי אי אמרת בשלמא במין במינו","כולם מודים דלא בטיל ובחתיכה קמייתא שרו רבנן משום דאפשר לסוחטו מותר ועד שתתן דקתני אטיפה קאי:"],[6,"היינו","דשייך למימר נראין דברי חכמים המתירין בשניער בתחלה דלא בלעה:"],[7,"אלא אי אמרת אפשר לסוחטו לרבנן נמי אסור","והאי דקשרו רבנן בין שניער בתחלה ובין שלא ניער בתחלה אשארא הוא דקשרו ומשום דמין במינו בטל ועד שתתן דקתני אחתיכה קאי היכי מצי רבי למיתני נראין דברי חכמים בשניער והא רבנן נמי אסרי לה לחתיכה דאית להו גזרה שמא לא ניער יפה יפה ורבי מדתלי טעמא דהיתרא בשניער מכלל דשרי אף בקמייתא משום דלא בלעה ואין נראין לו בה לא דברי רבי יהודה האוסר בכולן ולא דברי חכמים המתירין באחרות ואוסרין מיהא בראשונה ואם בא רבי להשמיענו דמין במינו לא בטיל ועוד דלא חיישינן לשמא לא ניער יפה הכי איבעי ליה למיתני נראין דברי רבי יהודה שאוסר בכולן בשלא ניער בתחלה אלא ניער בסוף דכיון שקבלה הטעם ונאסרה אוסרת חברותיה בכל שהוא דמין במינו לא בטיל ואין נראין דבריו כשניער דאיהו חושש לשמא לא ניער יפה ואוסרת כולן דכיון דניער לא חיישינן להכי ואף הראשונה מותרת ומדקאמר נראין דברי חכמים מכלל דרבנן בקמייתא נמי שרו ועד שתתן אטיפה קאי וקסברי אפשר לסוחטו מותר ולא נעשית החתיכה נבלה:"],[7,"ותו לא מידי","אין לשנות את הסוגיא. והשתא דקם ליה רבי בשיטתיה דר' יהודה דאפשר לסוחטו אסור ורב ורבי יוחנן ורבי חנינא נמי כוותיה סברי אע\"ג דאיפליגו עלייהו שמואל ור\"ל הא אמרינן שמואל באיסורי במקום רב ליתא וכן לגבי רבי יוחנן ליתא ועבדינן כרבי יהודה בין בטיפת חלב שנפל על החתיכה ולא ניער ויש בה כדי ליתן טעם באותה חתיכה ובין בחלב הדבוק בחתיכת בשר ויש בו ליתן טעם בה ואפילו אין בו כזית דהוי חצי שיעור אסור מן התורה והחתיכה עצמה נעשית נבלה ואין מועילין שאר החתיכות לבטלה דכולן נאסרות ואפילו הן אלף דבהא נמי קיימא לן כרבי יהודה דמין במינו לא בטיל דהא קם ליה רבי בשיטתיה ורב ושמואל נמי בשיטתיה קיימי דרב ושמואל דאמרי תרוייהו כל איסורין שבתורה במינו במשהו ותניא כותייהו במסכת עבודה זרה (דף עג:) ואע\"ג דאיפלוג עלייהו רבי יוחנן ור\"ל התם ותניא נמי כוותייהו שמעינן לאביי ורבא דבתראי הוו דקמו כרב ושמואל דאיתמר חלא לגו חמרא כו' במסכת עבודה זרה (דף סו.) ובפסחים (דף ל.) נמי פסק רבא הלכתא כרב דמין במינו במשהו דאמר רבא הלכתא חמץ בזמנו בין במינו בין שלא במינו במשהו ומפרשינן טעמא במינו במשהו רב לטעמיה דאמר כל איסורין שבתורה במינו במשהו ובשלא במינו גזר רב בחמץ אטו מינו משום דלא בדילי אינשי מיניה ואתו לזלזולי ביה שמע מינה בתרוייהו הלכה כר' יהודה בין באפשר לסוחטו אסור וכולה נעשית נבלה בין במין במינו לא בטיל אבל אם יש ברוטב לבדו יותר מששים בכל החתיכה שקבלה את הטעם הרוטב מבטלה ומשליכה וכולן מותרות דבהא אפי' רבי יהודה מודי דכל מין ומינו ודבר אחר סלק את מינו כמי שאינו ושאינו מינו רבה עליו ומבטלו. ואית ספרים דמתניא בהו איפכא אמר רבי נראין דברי רבי יהודה בשניער וכסה כו' ולא אפשר לאוקמא דא\"כ כולהו מודו בקמייתא דאסירא דכיון דמוקי פלוגתייהו נמי בשלא ניער כלל א\"כ על כרחך לרבנן נמי קמייתא אסורה דהא בלע ולא פלט ואין כאן מחלוקת אלא באחרונות ולא איירי באפשר לסוחטו מידי הילכך לא גרסינן לה:"],[8,"מתני' לא קרעו אינו עובר","על אכילתו ללקות ולא על בשולו דלאו חלב מקרי. ובגמרא מפרש אי איכא מיהא איסורא דרבנן או לא:"],[8,"הלב קורעו ומוציא את דמו לא קרעו אינו עובר עליו","להיות בכרת ובמס' כריתות (דף כב.) מוקים לה בלב עוף שאין בדמו כזית אבל בבהמה חייב כרת אם לא קרעו לאחר בשולו אבל בשרו אינו נאסר שהלב חלק הוא ואינו בולע והכי נמי אמרינן בפסחים (דף עד:) שאני לב דשיע:"]],[[2,"ודברי חכמים כשניער מאי ניער אילימא ניער בסוף ולא בתחלה","ה\"מ למיפרך מכלל דלרבנן אפילו לא ניער כלל מבלע בלע מיפלט לא פליט אלא דפריך טפי שפיר:"],[7,"נראין דברי ר' יהודה ואין נראין מבעיא ליה","תימה לימא דכ\"ע מין במינו לא בטיל וה\"ק נראין דברי ר' יהודה לחכמים בשלא ניער בתחלה אלא בסוף שחכמים לא נחלקו עליו אלא כשניער מתחלה ועד סוף דכי האי גוונא משני לעיל בפרק קמא (חולין דף יב.) גבי אבדו לו גדייו ותרנגוליו ובפרק המוכר את הספינה (ב\"ב דף עט.) גבי בור ושובך ובכמה דוכתין ויש לומר דלא קאמר אלא היכא דלא אפשר ליה למימר בענין אחר:"],[8,"הלב קורעו ומוציא את דמו לא קרעו אינו עובר עליו","פירש בקונטרס במס' כריתות (דף כב.) מוקי לה בלב עוף דאין בדמו כזית אבל בבהמה חייב כרת אם לא קרעו לאחר בשולו ואי אפשר לומר כן דבהדיא אמרינן בהקומץ רבה (מנחות דף כא.) דדם שבשלו אינו עובר עליו אם אכלו והא דמוקי לה בפ' דם שחיטה (כריתות דף כב.) בלב עוף משום דבכל ענין קתני מתניתין דאינו עובר עליו בין חי בין מבושל ומה שפירש בקונטרס דבשר הלב אינו נאסר שהלב חלק הוא ואינו בולע דהכי אמרינן בפסחים (דף עד:) שאני לב דשיע אומר ר\"ת דאין לסמוך על זה לעשות מעשה דדחייה בעלמא הוא בפ' כיצד צולין (פסחים דף עד:) דהוה בעי למיפשט מיניה דאמרינן כבולעו כך פולטו מדקתני קורעו לאחר בשולו ודחי שאני לב דשיע אבל למאי דמסיק דכבולעו כך פולטו תו לא אמרי' דשיע ולא בלע וקורעו לאחר בשולו היינו לאחר צלייתו דשייך ביה כבולעו כך פולטו שהדם נופל לחוץ אבל בקדרה אסור ולא אמרינן דשיע ולא בלע:"]]],[["אמר רבי זירא אמר רב אינו עובר עליו ומותר והא אנן תנן אינו עובר עליו מיעבר הוא דלא עבר הא איסורא איכא","בדין הוא דאיסורא נמי ליכא ואיידי דבעא למיתנא סיפא הלב קורעו ומוציא את דמו לא קרעו אינו עובר עליו התם מיעבר הוא דלא עבר הא איסורא איכא תנא נמי רישא אינו עובר עליו","לימא מסייע ליה הכחל קורעו ומוציא את חלבו לא קרעו אינו עובר עליו הלב קורעו ומוציא את דמו לא קרעו קורעו לאחר בשולו ומותר לב הוא דבעי קריעה אבל כחל לא בעי קריעה","דלמא לב הוא דסגי ליה בקריעה אבל כחל לא סגי ליה בקריעה","ואיכא דאמרי א\"ר זירא אמר רב אינו עובר עליו ואסור לימא מסייע ליה אינו עובר עליו מיעבר הוא דלא עבר הא איסורא איכא","בדין הוא דאיסורא נמי ליכא ואיידי דבעא למיתנא סיפא הלב קורעו ומוציא את דמו לא קרעו אינו עובר עליו דהתם מיעבר הוא דלא עבר הא איסורא איכא תנא נמי רישא אינו עובר עליו","ת\"ש הכחל קורעו ומוציא את חלבו לא קרעו אינו עובר עליו הלב קורעו ומוציא את דמו לא קרעו קורעו לאחר בשולו ומותר לב הוא דבעי קריעה אבל כחל לא בעי קריעה","דלמא לב הוא דסגי ליה בקריעה אבל כחל לא סגי ליה בקריעה","תניא כלישנא קמא דרב כחל שבשלו בחלבו מותר קבה שבשלה בחלבה אסור","ומה הפרש בין זה לזה זה כנוס במעיו וזה אין כנוס במעיו","כיצד קורעו אמר רב יהודה קורעו שתי וערב וטחו בכותל א\"ל ר' אלעזר לשמעיה קרע לי ואנא איכול מאי קמ\"ל מתניתין היא הא קמ\"ל דלא בעינן שתי וערב וטחו בכותל","אמרה ליה ילתא לרב נחמן מכדי כל דאסר לן רחמנא שרא לן כוותיה אסר לן דמא שרא לן כבדא נדה דם טוהר","חלב בהמה חלב חיה חזיר מוחא דשיבוטא גירותא לישנא דכורא","אשת איש גרושה בחיי בעלה אשת אח יבמה כותית יפת תאר בעינן למיכל בשרא בחלבא","אמר להו רב נחמן לטבחי זויקו לה כחלי והאנן תנן קורעו ההוא לקדרה","והא קתני שבשלו דיעבד אין לכתחלה לא ה\"ה דאפי' לכתחלה ואיידי דקא בעי למיתנא סיפא קבה"],[[0,"אמר רב אינו עובר עליו","מדאורייתא ומותר לכתחלה באכילה אם בשלו ולא אמרינן אסור מיהא מדרבנן דהא אפילו נסחט ממנו ויצא אמרינן לקמן (חולין דף קיא.) חלב שחוטה מדרבנן הוא והאי כיון דמובלע ולא פירש אפי' איסור דרבנן ליכא:"],[1,"דהתם מיעבר הוא דלא עבר","ללקות דאין בו כזית:"],[1,"הא איסורא איכא","דחצי שיעור אסור מה\"ת:"],[2,"הא כחל לא בעי קריעה","לאחר הבישול מדלא תנא ביה לא קרעו קורעו לאחר בשולו:"],[3,"דלמא","משום הכי לא תנייה משום דלב הוא דסגי ליה בקריעה דלאחר בשול משום דבשעת בשול לא בלע דשיע:"],[3,"אבל כחל","שהוא רך כבר נבלע בו החלב ע\"י בשול ולא סגי ליה תו בקריעה:"],[8,"קבה","של טלה או של עגל שיונקים החלב לתוך קבתן:"],[9,"זה כנוס במעיו","ומשיצא מדדי הבהמה חלב הוא וכחל אינו כנוס במעיו שלא יצא מדדי הבהמה בחייה ולא נאסף אלא מובלע בבשר הוא ולא בא לכלל חלב ומיהו לכתחלה בעי קריעה מדרבנן:"],[10,"וטחו בכותל","כובשו בידיו לכותל כדי שיסחט חלבו:"],[10,"קרע לי","כחל קודם שתצלנו ואנא איכול:"],[10,"מתניתין היא","דקורעו מתחלתו ומותר:"],[10,"הא קמ\"ל","קריעה בעלמא קא\"ל או שתי או ערב לפי שהחלב הנוטף יוצא למטה ומשיצא והרי הוא חלב לא חזר ולא בעי שתי וערב אלא לקדרה דהתם ודאי צריך להוציא כולו מתחלה לפי שכשהוא יוצא הרי הוא חלב גמור וחוזר ומתבשל עמו ודקתני לעיל שבשלו מותר בצלי קאמר דצלי נמי קרי בשול דכתיב בדברי הימים (ב לה) ויבשלו (את) הפסח:"],[11,"ילתא","אשתו:"],[11,"","הכבד כולו דם הוא קרוש טעם דם לו:"],[11,"דם טוהר","של בתולין ושל ימי טוהר של יולדת:"],[12,"מוח","של דג ששמו שיבוטא טעמו כטעם חזיר:"],[12,"גירותא","עוף טמא הוא:"],[12,"לישנא דכוורא","יש לו טעם גירותא:"],[13,"אסר לן אשת איש שרא לן גרושה","ואע\"פ שבעלה חי:"],[13,"בעינא למיכל בישרא בחלבא","ומה אמצא היתר דוגמתו:"],[14,"זויקו","שפודו. תנו לה כחל בשפוד:"],[14,"והא אנן קורעו תנן ההוא לקדרה","דכי נפיק מיניה הוי חלב שחוטה וכי הדר ומיבלע ליה אסר ליה. ודקתני לא קרעו אינו עובר עליו רב נחמן סבירא ליה כלישנא בתרא דרב וברייתא מוקי לה בצלי דכתיב ויבשלו (את) הפסח בדברי הימים:"],[15,"והא קתני שבשלו בדיעבד","והא ודאי בצלי הוא מדקתני מותר דאי בקדרה אמאי מותר הא יצא החלב וחזר ונבלע:"]],[[0,"אינו עובר עליו ומותר","פירש בקונטרס דמותר אם בשלו משום דחלב שחוטה דרבנן הוא והאי כיון דאבלע ולא פירש אפילו איסורא דרבנן ליכא משמע שרוצה להעמיד כולה שמעתתא דכחל לצלי דאי לקדרה אמאי מותר הא יצא חלב וחזר ונבלע וכן פירש לקמן בהדיא גבי זויקו לה כחלי דפריך והא בשלו קתני בדיעבד ופירש בקונטרס והא ודאי בצלי הוא מדקתני מותר דאי בקדרה אמאי מותר הא יצא החלב וחזר ונבלע ולקמן בתר שמעתתא דכבד פי' בקונטרס והלכות כחל כבר אמרנו למעלה דלצלי בעי קריעה שתי או ערב ואי לא קרעו מותר כלישנא קמא דרב דהא תניא כוותיה ולקדרה קורעו שתי וערב וטחו בכותל ומה שכתוב בספרים בפ' גיד הנשה (לעיל חולין דף צז:) כחל עצמו אסור היכא דלא קרעיה ובשליה בהדי בשרא ל\"ג ליה דאפי' בשליה לחודיה אסור לפירוש הקונטרס לפי שפירש וחזר ונבלע ומיהא גם לפירוש הקונטרס היכא דאיכא ס' במים שנתבשל בהן הכחל לא היה נאסר הכחל היכא שבשלו לחודיה לפי שהחלב הנפלט נתבטל במים אבל היכא דבשלו עם בשר אסור משום טעם בשר הנבלע בחלב שבכחל וכן יש ספרים דגרסי בסמוך כחל שבשלו בחלבו מותר היכא דבשליה לחודיה בלא בשר ויש להעמידו לפירוש הקונטרס שיש במים ששים כדפרישית שמתבטל בהן חלב היוצא מן הכחל:"],[0,"הא איסורא איכא","וא\"ת לפירוש הקונטרס דלמא הא איסורא איכא לקדרה אבל לצלי מותר וי\"ל דא\"כ ה\"ל למתני דאם לא קרעו מותר דהוי חדוש וממילא הוה מוקמינן ליה בצלי:"],[2,"לב הוא דבעי קריעה אבל כחל לא בעי קריעה","וא\"ת אדרבה דוק מינה איפכא אינו עובר עליו הא איסורא איכא כדדייק לעיל דהכא לא שייך למימר איידי דבעי למימר בסיפא כדקאמר לעיל וי\"ל דדלמא איידי דקתני במתניתין ואינו עובר עליו נקט נמי בברייתא הכי:"],[2,"הא כחל לא בעי קריעה","מדלא קתני קורעו לאחר בשולו והוה מוקמינן לה בצלי כדקתני גבי לב וא\"ת ומאי קסבר אי מהניא ביה קריעה אחר בשול אמאי מותר בלא קריעה יותר מקודם בשול דצריך קריעה ואי לא מהניא ביה קריעה היכי מייתי סייעתא לרב מהך ברייתא מדלא קתני קורעו לאחר בשולו הא אין קריעה מועלת לו כלום לאחר שנתבשל וי\"ל דודאי ס\"ד דמועלת לו קריעה לאחר בשולו והא דקאמר רב ואינו עובר עליו ומותר בלא קריעה במבושל ובחי קורעו היינו משום דכי נתבשל כבר פלט במקצת אבל חי שיש לו רוב חלב בעי קריעה:"],[3,"דלמא לב הוא דסגי ליה בקריעה","פירוש משום דשיע ולא בלע אפילו לקדרה או לצלי משום דכבולעו כך פולטו כמסקנא דפסחים (דף עד:) אבל כחל לא סגי ליה בקריעה אפילו לצלי משום דכבולעו כך פולטו לא שייך בשאר איסורים אלא בדם לחודיה:"],[11,"נדה דם טוהר","בסלוק של פרשת פרה יסד ר' אליעזר הקליר מן הדם טחול הדם מטומאת נדה (אשה) טהרת בתולי אשה ומאשת איש יפת תואר לאיש וכנגד כותית לא פירש והכל עשה ע\"פ הירושלמי:"],[14,"זויקו לה כחלי","פירש בערוך כמו זיקים מלאים ודמי לזויקני דארמאי בפ' שני דמסכת ע\"ז (דף לא:) כלומר נפוחין וכן הכא כחל כמו נוד נפוח מלא חלב ולא נקרע ובקונטרס פירש שפודו תנו לה כחל בשפוד:"],[14,"ההוא לקדרה","פירש בקונטרס דרב נחמן ס\"ל כלישנא בתרא דרב וברייתא מוקי לה בצלי כדכתיב ויבשלו (את) הפסח בדברי הימים ואין זה דוחק דה\"נ מוקמינן בפ' כיצד צולין (פסחים דף עד.) קורעו לאחר בשולו היינו אחר צלייתו ואינו רוצה לומר דסבר לגמרי כלישנא בתרא דהא מיקל טפי אפילו מלישנא קמא דשרי אפילו לכתחלה אלא בפירוש דמתניתין סבר כלישנא בתרא דכיון דשרי רב נחמן לצלי לכתחלה בלא קריעה א\"כ הא דקתני קורעו היינו לקדרה כדקאמר הכא וכי קתני לא קרעו אינו עובר עליו ע\"כ אינו עובר עליו ואסור כיון דמיירי לקדרה ורבינו תם פירש דהא דצריך קריעת שתי וערב וטחו בכותל לקדרה היינו קדרה עם בשר דלקדרה משמע עם בשר כדתנא אם בנותן טעם בקדרה אבל לקדרה בלא בשר או לצלי שרי לכתחלה בקריעה קצת וטעמא דהחמירו בה עם הבשר לפי דטעם החלב נכנס בבשר ומשתנה טעם הבשר ויש בו טעם בשר בחלב ולכך גזרו חכמים וכשאין הבשר עם הכחל בקדרה אף על פי שלא קרעו שתי וערב כיון שקרעו קצת לכתחלה מותר דאין החלב בעינה עוד בכחל כמו שהיה קודם ואע\"פ שנפלט וחוזר ונבלע תוך הכחל לא גזרו בו חכמים כיון שאין שם בשר אחר ולא נשתנה טעמו של כחל מפני בליעה זו ולא אתי למיכל בשר בחלב ובדיעבד שרי אפילו לא קרעו כלל ואין חילוק בין צלי לקדרה בלא בשר דאין בו שום טעם להקל בצלי יותר דבצלי נמי נוטף החלב ונופל על הכחל מבחוץ וחוזר ונבלע ולא שייך כבולעו כך פולטו אלא בדם אבל טיפת חלב שנפלה על חתיכת צלי לא כמו בשמנונית דנבלה דאפילו צלי אינו חוזר ופולט שמנונית שבלע והכי פירושו הכחל קורעו ומוציא את חלבו פירוש שתי וערב וטחו בכותל כדמפרש בגמרא דמוקי ליה רבי אלעזר לקדרה והיינו עם בשר כדפרישית ומוקי לה הכי משום דמתניתין סתמא קתני משמע שבא להתיר בכל ענין בשול לא קרעו פירוש לא עשה דין קריעה שלא קרעו שתי וערב וטחו בכותל אלא קריעה קצת אינו עובר עליו אמר רב אינו עובר עליו ומותר כיון דקרעו קצת אבל אם לא קרעו כלל ובשלו בהדי בשר אסור מדרבנן כדאמרינן בפ' גיד הנשה (לעיל חולין דף צז:) כחל בס' דחלב שחוטה אסור מדרבנן כיצד קורעו אמתניתין קאי אמר ליה ר' אלעזר קרע לי ואנא איכול פי' קרע לי קריעה קצת ואנא איכול בקדרה בלא בשר מאי קמ\"ל דלא בעי שתי וערב אלא לקדרה בהדי בשר אמר להו רב נחמן זויקו לה כחלי פירוש בשלו לה בקדרה בלא בשר כחלי נפוחים כנודות פירוש שלא נקרעו שתי וערב אלא קריעה קצת מ\"מ קרי זויקו לפי שלא נקרעו שתי וערב והא אנן תנן קורעו פירוש שתי וערב אבל קריעה קצת לא מהני ההוא לקדרה פירוש בהדי בשר והא קתני כחל שבשלו בחלבו מותר אלמא אפילו בקדרה בלא בשר אסור לכתחלה לבשל דבלא בשר מיירי מדקתני שבשלו בחלבו דמשמע דליכא איסורא אלא איהו גופיה ורב נחמן מתיר לכתחלה כו' והוה מצי לשנויי דמיירי בשלא קרעו כלל אלא דעדיפא משני וא\"ת היכי מייתי סייעתא מהך ברייתא ללישנא קמא דרב והא רב איירי אפילו בקדרה בהדי בשר וברייתא איירי בקדרה בלא בשר כדפרישית ויש לומר משום דלישנא בתרא דרב קאמר אינו עובר עליו ואסור בין בהדי בשר בין בלא בשר והך ברייתא שריא מיהא בלא בשר ומשום דפליגא אלישנא בתרא קאמר תניא כלישנא קמא והשתא רב נחמן כלישנא קמא דתניא כוותיה והילכתא כוותיה ולמאי דפרישית דמתניתין איירי נמי בקדרה בהדי בשר משום דקתני סתמא א\"כ רישא דברייתא דקתני נמי הכחל קורעו ומוציא את חלבו הוי נמי אפילו בהדי בשר ולא הוי דומיא דלב קורעו לא קרעו קורעו לאחר בישולו דלא איירי בהדי בשר דאי בהדי בשר נעשה הבשר נבלה וחוזר ואוסר את הלב דטעם דלב דשיע לא קאי לפי המסקנא דפסחים (דף עד:) לפירוש ר\"ת:"]]],[["שבשלה בחלבה אסורה דאפילו דיעבד נמי לא תנא נמי רישא שבשלה","כי סליק רבי אלעזר אשכחיה לזעירי אמר ליה איכא תנא דאתנייה לרב כחל אחוייה לרב יצחק בר אבודימי אמר ליה אני לא שניתי לו כחל כל עיקר ורב בקעה מצא וגדר בה גדר","דרב איקלע לטטלפוש שמעה לההיא איתתא דקאמרה לחבירתה ריבעא דבשרא כמה חלבא בעי לבשולי אמר לא גמירי דבשר בחלב אסור איעכב וקאסר להו כחלי","רב כהנא מתני הכי רבי יוסי בר אבא מתני אנא כחל של מניקה שניתי לו ומפלפולו של רבי חייא שנה ליה כחל סתם","רבין ורב יצחק בר יוסף איקלעו לבי רב פפי אייתו לקמייהו תבשילא דכחל רב יצחק בר יוסף אכל רבין לא אכל אמר אביי רבין תכלא אמאי לא אכל מכדי דביתהו דרב פפי ברתיה דר' יצחק נפחא הואי ור\"י נפחא מריה דעובדא הוה אי לאו דשמיע לה מבי נשא לא הוה עבדא","בסורא לא אכלי כחלי בפומבדיתא אכלי כחלי רמי בר תמרי דהוא רמי בר דיקולי מפומבדיתא איקלע לסורא במעלי יומא דכפורי אפקינהו כולי עלמא לכחלינהו שדינהו אזל איהו נקטינהו אכלינהו","אייתוה לקמיה דרב חסדא אמר ליה אמאי תעביד הכי אמר ליה מאתרא דרב יהודה אנא דאכיל אמר ליה ולית לך נותנין עליו חומרי המקום שיצא משם וחומרי המקום שהלך לשם אמר ליה חוץ לתחום אכלתינהו","ובמה טויתינהו אמר ליה בפורצני ודלמא מיין נסך הויא אמר ליה לאחר שנים עשר חדש הוו","ודלמא דגזל הוה אמר ליה יאוש בעלים הוה דקדחו בהו חילפי","חזייה דלא הוה מנח תפילין אמר ליה מאי טעמא לא מנחת תפילין אמר ליה חולי מעיין הוא ואמר רב יהודה חולי מעיין פטור מן התפילין","חזייה דלא הוה קא רמי חוטי אמר ליה מאי טעמא לית לך חוטי אמר ליה טלית שאולה היא ואמר רב יהודה"],[[1,"איכא תנא","בהאי דוכתא:"],[1,"דאתנייה לרב כחל","יש כאן מי ששנה לרב כחל שבשלו בלא קריעה אסור באכילה ולישנא בתרא דרב הוה שמיעא ליה לרבי אלעזר:"],[1,"אחוייה","בני המקום:"],[1,"לרב יצחק","אמרו לו לרבי אלעזר זה שנאה לו:"],[1,"אני לא שניתי לו כחל כל עיקר","כלומר שום כחל לא שניתי לו לאיסור בין כחל מניקה ובין כחל שאינה מניקה:"],[1,"ורב","ששנה להם כחל שאסור:"],[1,"בקעה מצא","כלומר ראה שהיו מזלזלים באיסור בשר בחלב והחמיר עליהן:"],[2,"","לטטלפוש:"],[2,"ריבעא","ליטרא:"],[3,"רב כהנא מתני הכי","כמו שאמרנו שכן השיבו רב יצחק לרבי אלעזר לא שניתי לו כל עיקר:"],[3,"כחל מניקה","שהיתה מניקה ויש בדדיה חלב כנוס הרבה:"],[3,"ומתוך פלפולו של רבי חייא","שהוא מחודד מאד ומבין מעצמו וכסבור שתלמידיו מחודדין כמותו כשחזר ושנאה לפני ר' חייא שנה לו סתם וסבור שיבין רב שאין אסור אלא מניקה ולא הבין:"],[4,"תכלא","שכול קובר את בניו:"],[4,"מרא דעובדא","זהיר במעשים טובים:"],[5,"לא אכלי כחלי","לגמרי אפילו צלי ואפילו קרעו:"],[7,"במאי טויתינהו","היכן הוו לך שם עצים:"],[7,"בפורצני","חרצנים שאצל היקבים והבערתים:"],[7,"לאחר שנים עשר חדש הוה","ותנן במס' ע\"ז (דף לד.) לחים אסורין יבשין מותרין ואלו הם לחים כל שנים עשר חדש:"],[8,"דקדחו בהו חילפי","גדלו בהם מחמת שנרקבו ונעשו עפר:"],[8,"חילפי","אורטיי\"ש והואיל ומתקלקלין ונרקבין ולא נטלו משם ש\"מ אינו חושש:"],[9,"פטור מן התפילין","מפני שצריך לחלצן תדיר:"],[10,"דלא הוה רמי חוטי","לא הטיל ציצית לטליתו:"]],[[1,"איכא תנא דאתנייה לרב כחל אחוייה ליה לרב יצחק בר אבודימי","וכן בפרק המוכר את הספינה (ב\"ב דף פז.) איכא תנא דאתנייה לרב מידות אתוי ליה רב יצחק בר אבודימי והקשה רבינו שמואל דהא רב יצחק בר אבודימי היה רבו של רבא כדאמר בריש יבמות (דף ג.) ובריש פ' אלו הן הנשרפין (סנהדרין דף עו.) אמר רבא א\"ל רב יצחק בר אבודימי אתיא הנה הנה וכו' ואיך יתכן דרב יצחק בר אבודימי שהיה רבו של רב שהיה חי עד רבא והלא ביום שמת רב יהודה שהיה תלמידו של רב נולד רבא וגרס התם רבינו שמואל איכא תנא דאתנייה רב מדות וקשה לר\"ת דהכא בשמעתין אין שייך לומר כן דקאמר אני לא שניתי לו ומיהו יש לפרש לו כמו ממנו כמו (ב\"מ דף לג.) תלמיד ורבו צריך לו אבל הא דקאמר ומתוך פלפולו של רבי חייא שנה לו כחל סתם לא אתי שפיר ואור\"ת דשנים היו אחד היה בימי רבינו הקדוש דאמרינן פרק כירה (שבת דף מ:) דאמר רב יצחק בר אבודימי פעם אחת נכנסתי אחר רבי לבית המרחץ ואותו יכול להיות שהיה רבו של רב וקשה קצת דאם רב יצחק בר אבודימי דהמוכר את הספינה היה רבו של רב היכי קאמר לרבי אלעזר התם הא איתמר עלה אמר ר' אבהו אמר ר' יוחנן והלא ר' יוחנן שהיה רבו של ר' אבהו היה קורא לרב רבינו כדאמרינן באלו טרפות (לעיל חולין דף נד):"],[1,"דאתנייה לרב כחל","פי' בקונטרס יש כאן מי ששנה לרב כחל שבשלו בלא קריעה אסור באכילה ולישנא בתרא דרב הוה שמיע ליה לר' אלעזר ונראה דלא קאי אהנהו לישני דלעיל אלא שמע שהיה רב אוסר כחל ואפילו בקריעת שתי וערב כדאמרינן בסמוך בסורא לא אכלי כחלי אע\"ג דמתניתין שריא ליה בקריעה והיה תמיה ר\"א והשיב לו רבי יצחק בר אבודימי דרב בקעה מצא וגדר בה גדר ורב יוסף קאמר דכחל מניקה שנה לו דאסור אפילו בקריעה ומתניתין כשאינה מניקה ור' חייא שנה לו כחל סתם והיה סבור שיבין רב מעצמו ולא הבין וטעה בדבריו והיה סבור שמכח שום ברייתא היה בא לחלוק על משנתנו לאסור כל כחל אפילו בקריעה ואנן דאכלינן כחלי אפילו של מניקה בקריעה סמכינן אלישנא דרב בקעה מצא ואין חילוק בין מניקה לשאינה מניקה וגם אעובדא דרבין ורב יצחק בר יוסף דאייתו קמייהו תבשיל דכחלי ואכל רב יצחק ומסתמא של מניקה היה מדלא רצה רבין לאכול ורב יצחק עיקר מדאמר אביי רבין תיכלא אמאי לא אכל וגם מעובדא דרמי בר תמרי דנקטינהו לכולהו כחלי ואפילו של מניקה ואכל:"]]],[["טלית שאולה כל שלשים יום פטורה מן הציצית","אדהכי אייתוה לההוא גברא דלא הוה מוקר אבוה ואמיה כפתוהו","אמר להו שבקוהו דתניא כל מצות עשה שמתן שכרה בצדה אין בית דין שלמטה מוזהרין עליה אמר ליה חזינא לך דחריפת טובא אמר ליה אי הוית באתריה דרב יהודה אחוינא לך חורפאי","אמר ליה אביי לרב ספרא כי סלקת להתם בעי מינייהו כבדא מה אתון ביה כי סליק אשכחיה לרב זריקא אמר ליה אנא שלקי ליה לרבי אמי ואכל","כי אתא לגביה אמר ליה למיסר נפשה לא קא מיבעיא לי כי קמבעיא לי למיסר חבירתה","מ\"ש למיסר נפשה דלא מיבעיא לך דתנן אינה נאסרת למיסר חבירתה נמי לא תבעי לך דתנן הכבד אוסרת ואינה נאסרת מפני שהיא פולטת ואינה בולעת אמר ליה דילמא התם בכבדא דאיסורא"],[[1,"כפתוהו","על העמוד להלקותו כדתניא (כתובות דף פו.) בד\"א דארבעים ותו לא במצות לא תעשה שכבר נעשית העבירה אבל מצות עשה שלפניו ואינו רוצה לקיימה כגון אומרין לו עשה סוכה ואינו עושה עשה לולב ואינו עושה מכין אותו עד שתצא נפשו:"],[2,"שמתן שכרה בצדה","למען יאריכון ימיך (שמות כ) לכך פירש מתן שכרה לומר אם לא תקיימנה זהו עונשו שלא תטול שכר זה:"],[3,"כבדא מה","אתם נוהגין בו מותר לבשל בקדרה או אסור מפני שפולט דם ואע\"פ שכולו דם אפ\"ה לאחר שפירש ויצא הרי הוא דם ואסור:"],[3,"כי סליק","רב ספרא:"],[3,"אשכחיה לרבי זריקא","ובעא מיניה:"],[3,"אמר ליה","ר' זריקא:"],[3,"אנא שלקי לר' אמי ואכל","בשלתי לו הכבד ואכלו:"],[4,"כי אתא","רב ספרא:"],[4,"לגביה","דאביי סיפר לו מה ששמע:"],[4,"א\"ל","אביי:"],[4,"למיסר נפשה","שיהא דם הנפלט ממנה חוזר לתוכה ואוסרת:"],[4,"לא מיבעיא לי","דפשיטא לי דכיון דטרודה היא לפלוט ולהוציא כל שעה לא בלעה:"],[4,"כי קמיבעיא לי למיסר חבירתה","אם דם היוצא ממנה אוסר בשר אחר המתבשל עמו:"],[5,"דתנן הכבד [אוסרת] ואינה נאסרת","כלומר מדפשוט לך בדידה דשריא אלמא שמיעא לך הא מתני' אם כן למיסר נמי חבירתה לא תיבעי לך דהא הך משנה גופה תנן בה דאוסרת ובסדר זרעים היא:"],[5,"אמר ליה דלמא ההיא בכבדא דאיסורא","כגון דטרפה:"]],[[0,"טלית שאולה פטורה כל שלשים יום כו'","מדאורייתא פטורה לעולם כדקאמר בראשית הגז (לקמן חולין דף קלז.) כסותך ולא של אחרים אלא לפי שנראית כשלו חייבוהו חכמים משלשים יום ואילך דאין דרך לישאל יותר משלשים יום ומכאן מדקדק ר\"ת דסתם שאלה שלשים יום כמו הלואה דאמרינן במכות (דף ג:) המלוה את חבירו סתם אין רשאי לתובעו פחות משלשים יום ונראה דאין ראיה מזה דה\"נ אמרינן בהתכלת (מנחות דף מד.) השוכר בית בחוצה לארץ כל שלשים יום פטור מן המזוזה אע\"ג דסתם שכירות לא הויא שלשים יום ולענין ברכה נראה שאין לברך על השאולה אע\"פ שאומר ר\"ת דנשים מברכות אסוכה אע\"ג דפטורות דהוי אינה מצווה ועושה מדאשכחן רב יוסף דאמר מאן דאמר לי הלכה כרבי יהודה דאמר סומא פטור מן המצות עבידנא יומא טבא לרבנן ואם לא היה יכול לברך כל הברכות לא היה שמח בדבר מ\"מ לא דמי לטלית שאולה דהתם אדם אחר היה חייב שאינו סומא או שאינה אשה אבל הכא כל אדם פטור כשאינו שלו ואעפ\"כ המברך לא הפסיד וי\"מ דאם היא של כלאים כגון תכלת דאסורה כיון דפטורה מדאורייתא ואומר ר\"ת דאין לחוש מדאמרינן בריש התכלת (מנחות דף מ:) ותכלת אין בה משום כלאים ואפילו בטלית פטורה ומסיק כגון שהטיל למוטלת פירוש טלית שיש בה ציצית כבר ולא בעי למימר כגון שאחר כך הסיר הראשונים וקמ\"ל דלא הויא פסולה משום תעשה ולא מן העשוי דאם כן למה ליה למימר אין בה משום כלאים לימא הטיל למוטלת כשרה אלא הא קמ\"ל כל טלית דאשתרי בה כלאים דהיינו בתכלת מותר בכל ענינים בין להתעטף בין להציע תחתיו בין לו בין לחבירו בין לאשתו בין ביום בין בלילה דלגמרי שרא ביה כלאים והא דאמרינן בפרק במה מדליקין (שבת דף כה:) גזירה משום כסות לילה לא כמו שפירש בקונטרס שמא יתכסה בה בלילה אלא גזירה משום כסות המיוחד ללילה דלא אשתרי בה כלאים כלל דאימעיט מוראיתם ור' אלעזר ממי\"ץ הקשה לו דאמר בריש ערכין (דף ג:) הכל חייבים בציצית כהנים לוים וישראלים ומפרש דכהנים אצטריך ליה דסלקא דעתך אמינא הואיל ואשתרי כלאים גבייהו לא ליחייבו קמ\"ל נהי דאישתרי בעידן עבודה שלא בעידן עבודה לא אישתרי ולא אמרינן דאישתרי בכל ענין ואומר ר\"ת דהתם נמי אישתרו בכל ענין אפילו שלא בעידן עבודה כדאמרינן בפרק בא לו (יומא דף סח.) גבי בגדי כהונה ניתנו ליהנות בהם או לא ת\"ש לא היו ישנים בבגדי כהונה שינה הוא דלא הא הלוכי מהלכי ועוד תניא התם גבי בגדי כהונה דלצאת בהם במדינה אסור פירוש משום איסור הקדש ובמקדש מותר בין בשעת עבודה בין שלא בשעת עבודה והא דקאמר נהי דאשתרו בשעת עבודה כלומר בגדים שלובשים בשעת עבודה שלא בשעת עבודה פירוש בגדי חול מי אישתרו בכלאים ומיהו משמע התם דלא שרו אלא דרך לבישה דבעי למידק התם דניתנו ליהנות בהם מדקתני פושטים אותם ומקפלים ומניחין אותם תחת ראשיהם ודחי לא תימא תחת ראשיהם אלא אימא כנגד ראשיהם וה\"נ מסתברא דאי ס\"ד תחת ראשיהם נהי דנתנו ליהנות בהם תיפוק ליה משום כלאים ולפי זה בטלית שאולה היה אסור להציעו תחתיו ומיהו נראה שיש לחלק בין טלית שכל עיקר לבישתה לצורך הנאתו ובין בגדי כהונה שעיקר לבישתן לצורך עבודה:"],[2,"כל מצות עשה שמתן שכרה כו'","וא\"ת והרי צדקה דכתיב פתוח תפתח את ידך וגו' כי בגלל הדבר הזה יברכך וגו' (דברים טו) ואמרינן בפ\"ק דב\"ב (דף ח:) דרבא אכפייה לרב נתן בר אמי ואפיק מיניה ארבע מאות זוז לצדקה ואומר ר\"ת דאכפייה היינו בדברים כדאשכחן פ' נערה בכתובות (דף נג.) אכפייה ועל ועוד דבצדקה נמי איכא לאו לא תקפוץ ולא תאמץ (דברים טו):"],[3,"כבדא מה אתון ביה","אומר ר\"ת דכולה הך שמעתא איירי בכבד שלא נמלח דאי בתר מליחה ושהייה במלח פשיטא דשרי לבשלה בהדי בשר שעל ידי מליחה יצא כל הדם שכך נוהגין העולם לבשל אחר צלייה והוא הדין דשרי אחר מליחה דשיעור מליחה פי' בה\"ג דהוי כשיעור צלייה משום דמליח הרי הוא כרותח דצלי ופולט על ידי מליחה כמו שפולט על ידי צלייה אבל בלא מליחה מיבעיא ליה אי שרי לבשל עם בשר דשמא דם הכבד אע\"פ שפירש מותר אע\"פ שדם שאר האברים שפירש אסור כדאמרינן בפ' קמא דכריתות (דף ד:) חד לדם האברים ולכך אמרינן לקמן (חולין דף קיג.) דאין מולחין בשר אלא בכלי מנוקב דם הכבד שמא שרי דהא כל הכבד דם הוא ושרייה רחמנא כדאמר לעיל (חולין דף קט:) שרא לן כבדא ונראה דמדאורייתא פשיטא ליה דדם הכבד מותר אף על פי שפירש משום דכולו דם הוא כדפירשתי מדלא חשיב פרק דם שחיטה (כריתות דף כא:) דם הכבד דקתני דם הטחול ודם הלב ודם הכליות ודם האברים הרי אלו בלא תעשה אלא מדרבנן מבעיא ליה ואפילו נאסור מדרבנן דם היוצא ממנו על ידי מליחה לפי שהוא בעין גזירה אטו שאר דם כי היכי דגזרינן בדם מהלכי שתים דאמרינן (שם דף כא:) שבין השינים מוצצו שעל הככר גוררו מ\"מ מיבעיא ליה בבשול לפי שאינו ניכר הדם כלל ולכך יהא מותר ולא נגזור בשול כבד אטו בשול בשר אחר בלא מליחה ועוד יש לומר בע\"א דבלא מליחה פשיטא דאסור ועל ידי מליחה הוא דמבעיא ליה כיון שיש בכבד רוב דם שמא אינו יוצא כולו על ידי מליחה או שמא יוצא ומיהו קשה קצת דקאמר בסמוך למיסר חבירתה נמי לא תבעי לך דתנן הכבד אוסרת הא איכא לאוקמי בשלא נמלחה ולפירוש רבינו תם ניחא וי\"ל דמשמע ליה דמיירי אחר מליחה כמו שדרך לבשל בשר ולקמן (חולין דף קיא.) גבי בר שבא דאייתו לקמיה כבדא שליקא ולא אכל לפירוש ר\"ת צריך לומר דיודע היה שלא נמלחה הכבד והא נמי דפשיט מההוא דקריבי קניא בקופיה יודע היה שלא נמלחה הכבד אף על פי שצ\"ל כי הריאה והלב שהיו עם הכבד נמלחו ואין לתמוה על זה דכמה דברים היו עושין כדי להראות הלכה לתלמידים אי נמי כל שלשתן נמלחו אלא דלכבד לא מהניא מליחה אלא בקריעת שתי וערב וחתוכיה לתחת כדקאמר בסמוך ולקמן (שם) נמי דקאמר אבל לטחול שומנא בעלמא הוא ומייתי מדשמואל דעבדי ליה תבשילא דטחלי ביומא דהקזה היו יודעים דבלא מליחה היו עושין לו דבמליחה כבדא נמי שרי א\"נ התם קאי אקריעה שתי וערב הני מילי כבדא אבל טחלא לא בעי קריעה כי הא דשמואל כו' ויודעין היו דמטחול שלם עבדי ליה ורב אלפס כתב שמנהג בכל ישראל שלא לבשל כבד אפילו אחר מליחה בלא צלייה:"],[5,"דתנן הכבד אוסרת ואינה נאסרת מפני שהיא כו'","משנה היא במסכת תרומות (פ\"י מי\"א) ותימה רב ספרא מעיקרא מאי סבר שלא הביא לו המשנה כמו שמביאה לבסוף דבסתמא גם מתחלה היה יודע דמשניות אפילו דזרעים ודטהרות היו שגורות בפיהם כדפי' בפרק תולין (שבת דף קלח:) גבי עתידה תורה שתשתכח מישראל הא נמי מתניתין היא השרץ שנמצא בתנור הפת שבתוכו שניה מפני שהתנור תחלה ויש לומר דגם בתחלה היה יודע המשנה אבל היה סבור שאביי הוה מסופק בשלוקה אם נאסרת או אינה נאסרת כמבושלת דפליגי בה תנאי בסמוך והיה מסופק היאך הלכה ועל כן הביא לו ראיה מר' זריקא ור' אסי שלקו ליה ואכיל והשיב לו אביי דלמיסר נפשה לא קמיבעיא ליה דאינה נאסרת כת\"ק דרבי ישמעאל בנו של רבי יוחנן בן ברוקה וכסתם מתניתין דתרומות והשיב לו למה אין פשוט לך מתוך אותה משנה עצמה שאתה למד ממנה שאינה נאסרת אפילו בשליקה שאפילו בבישול אוסרת חבירתה:"]]],[["ומשום שמנוניתא משום דמא מאי","כי הדר סליק אשכחיה לר' זריקא אמר ליה האי נמי לא תבעי לך דאנא וינאי בריה דרבי אמי איקלען לבי יהודה בריה דר' שמעון בן פזי וקריבו לן קניא בקופיה ואכלנא","מתקיף לה רב אשי ואיתימא ר' שמואל מזרוקיניא ודלמא פי קנה חוץ לקדרה הוה אי נמי מיחלט הוה חליט ליה מעיקרא כי הא דרב הונא חלטי ליה בחלא ורב נחמן חלטי ליה ברותחין","וסבר רב פפא קמיה דרבא למימר חלא אסיר אמר ליה אי חלא אסיר איהו נמי אסיר כי היכי דפליט הדר בלע","רב בר שבא איקלע לבי רב נחמן אייתו ליה כבדא שליקא ולא אכל אמרו ליה בר בי רב דלגיו לא אכיל ומנו רב בר שבא אמר להו רב נחמן גאמו לשבא","כתנאי ר' אליעזר אומר הכבד אוסרת ואינה נאסרת מפני שפולטת ואינה בולעת ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר מתובלת אוסרת ונאסרת שלוקה אוסרת ונאסרת","רבה בר רב הונא אקלע לבי רבה בר רב נחמן אייתי לקמיה תלת סאוי טחאי אמר להו מי הוה ידעיתו דאתינא אמרו ליה מי עדיפת לן מינה דכתיב (ישעיהו נח, יג) וקראת לשבת עונג","אדהכי אשכח ההוא כבדא דהוה בה סמפונא דבליעא דמא אמר להו אמאי עבדיתו הכי אמרו ליה אלא היכי נעביד אמר להו קרעו שתי וערב וחיתוכא לתחת","וה\"מ כבדא אבל טחלא שומנא בעלמא הוא כי הא דשמואל עבדי ליה תבשילא דטחלי ביומא דעביד מלתא","אתמר כבדא עילוי בשרא שרי דמא משרק שריק כחלא עילוי בשרא אסור מאי טעמא חלב סרוכי מסריך","רב דימי מנהרדעא מתני אפכא כחלא עילוי בשרא שרי מ\"ט חלב שחוטה דרבנן כבדא עילוי בשרא אסור דם דאורייתא","דרש מרימר הלכתא בין כבדא בין כחלא תותי בשרא שרי עילוי בשרא דיעבד אין לכתחלה לא","רב אשי איקלע לבי רמי בר אבא חמוה חזייה לבריה דרמי בר אבא דקא"],[[0,"ומשום שמנונית","קאמר דאוסרת את המתבשל עמה לפי שבולע מן הטרפה ואינה נאסרת אם של היתר היא ובשלה עם טרפה אינה נאסרת לפי שטרודה לפלוט כל שעה ואינה בולעת כלום אבל דמא דנפיק מינה דכשרה מיבעיא לי אי אסיר אחריני אי לא דאיכא למימר דמא דהיתירא הוא שהרי עיקרה דם וכל זמן שלא פירש פשיטא לי דמותר וכי פירש מיבעיא לי מאי:"],[1,"קניא בקופיה","הקנה עם כל המחובר לו הריאה והלב וכבד וכולן נתבשלו יחד:"],[2,"דלמא פי קנה חוץ לקדרה הוה","וסימפוני הכבד שופכין דרך קנה הכבד לתוך קנה הגדול של ריאה ויוצא דם דרך חללו חוץ לקדרה:"],[2,"אי נמי חליט הוה מעיקרא","ונתבשל דמו בתוכו כדי שלא יפלוט עוד כשיבשלהו עם האחר ודמו המובלע בתוכו מותר כל זמן שלא יצא:"],[2,"חלטי ליה בחלא","צומתו בחומץ שהחומץ צומתו אשטרוינ\"ט ושוב אינו פולט עולמית והדר מבשלי ליה עם בשר אחר:"],[3,"חלא אסיר","אותו חומץ שנצמת בו אסור דקסבר מוציא מקצת מן הדם:"],[3,"כי היכי דפליט הדר בלע","מאותו חומץ עצמו דכיון שנצמת ואינו טרוד לפלוט חוזר ובולע:"],[4,"אמרו ליה בר בי רב דלגיו לא אכיל","אמרו לו לרב נחמן תלמיד שנתארח אצלך אינו אוכל מה שהביאו לפניו:"],[4,"גאמו לשבא","הגמיאהו והלעיטהו לשבא על כרחו. על שם אביו קראו:"],[5,"מתובלת","התבלין מרככין אותה:"],[5,"שלוקה","הרבה מאד:"],[5,"נאסרת","לפי שלאחר שגמרה פליטתה חוזרת ובולעת:"],[6,"תלת סאוי טחאי","שלש סאין פת נקיה פניה טוחין בשמן ודבש:"],[6,"מי עדיפת לן מינה","יום השבת היה:"],[7,"אמאי עבדיתו הכי","אע\"פ שדם הנבלע בו היתר הוא מיהו דם הכנוס בסמפונות דם הוא:"],[7,"וחתוכא לתחת","חתוכו למטה כשנתנוהו בתנור לצלות כדי שיזוב הדם ויצא:"],[8,"והני מילי","דבעי קריעה בכבדא מפני שדם כנוס לתוכו אבל טחלא אין בו דם ואפילו לקדרה שרי:"],[8,"כי עביד מילתא","הקזה:"],[9,"כבדא עילוי בשרא","בתנור היו צולין כל צלי שלהן וחודו של שפוד תלוי למטה וכשהכבד נתון תחלה ואחר כך הבשר נמצא הכבד עליון כשתולין אותו:"],[9,"דמא משרק שריק","אע\"פ שזב מן הכבד על הבשר אין בכך כלום לפי שהדם ע\"י צלי אינו נוח ליבלע אלא מחליק ונופל:"],[9,"מסרך סריך","נדבק ונבלע:"],[11,"הלכתא כו'","ולדידן אסור לגמרי לכתחלה לפי ששפודים שלנו אינן תלויין אלא שוכבות ופעמים שמרים זנב השפוד ונמצא התחתון עליון ופעמים שמשפילו ונמצא חברו עליון הלכך בין שהכבד לצד הראש ובין שהוא לצד הזנב אסור:"]],[[2,"כי הא דרב הונא חלטי ליה בחלא ורב נחמן חלטי ליה ברותחין","וא\"ת ותפשוט מינה דאסור מדהוו צריכי למחלטיה וי\"ל דלדידהו נמי הוה מספקא להו ולכך היו מחמירין ודוקא לבשל עם הבשר הוו חלטי ליה שלא תאסור הבשר אבל בפני עצמה אינה נאסרת:"],[4,"רב בר שבא איקלע לבי רב נחמן אייתו ליה כבדא שליקא ולא אכל","צריך לומר שלא היה נחלט ברותחין ולפי שלא היה בשר אחר עמו לא הוצרכו לחלטו אע\"פ שפולט דם ואוסר הרוטב והכלים מזה לא היו חוששין כיון שהכבד עצמו מותר שאין לומר שנחלט וע\"י כן היה רב נחמן מתירו אבל אם לא נחלט היה אוסרו ובר שבא היה סבור דחליטה אינה מועלת א\"כ לא מייתי שפיר כתנאי דתנאים לא נחלקו בזה:"],[7,"וחתוכיה לתחת","לבשלו בקדרה אחר צלייתו או מליחתו איירי דאי לאוכלו צלי למה לי חתוכה דמה שפולט שריק ונופל דמה שלא נפלט הוי דם האברים שלא פירש ושרי פ' דם שחיטה (כריתות דף כא) ואי משום דם סמפונות הכבד צריך קריעה אף לצלי דהוי בכרת אע\"פ שלא פירש א\"כ בטחול נמי אי איכא סמפונות למה לא יצטרך קריעה ועוד דסברא הוא דאין בטחול סמפונות וא\"כ מה בא להשמיענו אבל דטחלא לא ובה\"ג כתב האי מאן דמצלי כבדא בשלומיה צריך לחתוכיה מ\"ט דאזיל דמא ומכניס בסמפונות והיכא דלא קרעיה לקרעיה לאחר בשולו וחותך ויצא דם הכנוס בסמפונות ולא חיישינן שמא דם הסמפונות חזר ונבלע בכבד דהא מסקינן בכיצד צולין (פסחים דף עד:) דכבולעו כך פולטו:"],[8,"אבל טחלא שומנא בעלמא הוא","היינו דוקא גוף הטחול הוא שומן אבל דם היוצא ממנו אסור כדתניא פ' דם שחיטה (כריתות דף כא:):"],[9,"דמא משרק שריק","וא\"ת למה לי האי טעמא תיפוק ליה דכבולעו כך פולטו וכ\"ת דאצטריך להתיר אפילו למאן דלית ליה בכיצד צולין (גז\"ש) כבולעו כך פולטו אכתי קשה דמסקינן התם דמולייתא שריא אפילו לכתחלה מהאי טעמא והכא פסקינן דאסור לכתחלה לכולי עלמא ואי משום דפעמים נצלה הבשר שלמטה מן הכבד תחלה והכבד עדיין פולטת ונופל על הבשר וכשמסירין הבשר הרי בלע ולא היה לו שהות לפלוט א\"כ בשרא עלוי בשרא נמי ליתסר מהאי טעמא כשהתחתון נצלה קודם ומסירין אותו מן השפוד ויש לומר דכבד שיש בו שפע דם לא אמרינן כבולעו כך פולטו והא דאמרינן בכיצד צולין (גז\"ש) דלב קורעו אחר בישולו משום דכבולעו כך פולטו אע\"פ שיש בו שפע דם הלב מתבשל ומתייבש במקומו בחלל הלב:"],[10,"כבדא עילוי בשרא אסור","לכתחלה אסור לכ\"ע אע\"ג דבשרא עילוי בשרא שרי אפי' למאן דלית ליה בפרק כיצד צולין (פסחים דף עד:) כבולעו כך פולטו משום דדם מישרק שריק בכבד שיש בו רוב דם שאינו יכול לצאת ע\"י מליחה כמו בשאר בשר כדמשמע כוליה שמעתין לא שריק שפיר ולפירוש ר\"ת לא ניחא כולי האי דבכולה שמעתין לא נסתפק בדם הכבד כ\"א להקל ולהתיר בלא מליחה ולא להחמיר ואע\"פ שדברנו לעיל שאינה בולעת מחמת שטרודה לפלוט לעולם מ\"מ עיקר השמועה אינה מדבר זה ולכאורה משמע שמאותו טעם שדברנו בכח השמועה הוא בא לאסור כבדא עילוי בישרא ומיהו י\"ל דקאי אמאי דאמרינן מקמי הך מילתא הני מילי כבדא שיש בו רוב דם אבל טחלא שומנא בעלמא הוא:"],[10,"דם דאורייתא","אע\"ג דאמר בהקומץ רבה (מנחות דף כא.) דם שבשלו אינו עובר עליו מ\"מ תחלה כשנפלט עד שלא נתבשל היה דאורייתא אבל חלב שחוטה תחלתו דרבנן ומיהו קשה לפי מה שפירש הקונטרס לעיל דדם כבד אפילו פירש לאו דאורייתא מדלא חשיב ליה בפרק דם שחיטה (כריתות דף כא:) בהדי לב וטחול וכליות:"],[11,"תותי בשרא שרי","וא\"ת כחל היאך מותר תותי בשרא והלא שמנונית הבשר נוטף על הכחל ואי בקרעו שתי וערב וטחו בכותל א\"כ עילוי בשרא נמי לישתרי דהא מותר לבשלו עם הבשר בקדרה וי\"ל דהכא גרע טפי דאע\"פ שקרעו עדיין נוטף החלב מן הכחל על הבשר וניכר שהוא בעין ויש ללמוד מכאן היתר פשוט דהיכא דקרעו שתי וערב וטחו בכותל דמותר לבשלו עם בשר בקדרה כדברי ר\"ת ולא מצינו בקונט' שחולק עליו בזה דהא בהדיא שרי הכא תותי בשרא אע\"פ ששמנונית הבשר על הכחל ומה שנזהרים שלא לחתוך כחל רותח בסכין של בשר מנהג של הבל הוא דאפי' בשפוד אחד שרינן הכא לכתחלה כשהכחל למטה ואפי' עילוי בשרא לכתחלה הוא דאסור מטעם דפרישית אבל בדיעבד שרי:"]]],[["שפיד כבדא עילוי בשרא אמר כמה יהיר האי מרבנן אימר דאמור רבנן דיעבד לכתחלה מי אמור","ואי איכא בי דוגי בשרא עילוי כבדא נמי אסיר","ומ\"ש מדמא דבשרא דמא דבשרא שכן דמא דכבדא קפי","אמר רב נחמן אמר שמואל סכין ששחט בה אסור לחתוך בה רותח צונן אמרי לה בעיא הדחה ואמרי לה לא בעיא הדחה","אמר רב יהודה אמר שמואל קערה שמלח בה בשר אסור לאכול בה רותח ושמואל לטעמיה דאמר שמואל מליח הרי הוא כרותח וכבוש הרי הוא כמבושל","כי אתא רבין א\"ר יוחנן מליח אינו כרותח וכבוש אינו כמבושל אמר אביי הא דרבין ליתא דההיא פינכא דהוה בי ר' אמי דמלח ביה בשרא ותבריה מכדי רבי אמי תלמיד דר' יוחנן הוה מאי טעמא תבריה לאו משום דשמיעא ליה מיניה דר' יוחנן דאמר מליח הרי הוא כרותח","יתיב רב כהנא אחוה דרב יהודה קמיה דרב הונא ויתיב וקאמר קערה שמלח בה בשר אסור לאכול בה רותח וצנון שחתכו בסכין מותר לאכלו בכותח","מאי טעמא אמר אביי האי היתרא בלע והאי איסורא בלע","א\"ל רבא כי בלע היתרא מאי הוי סוף סוף האי היתרא דאתי לידי איסורא הוא דאיסורא קאכיל אלא אמר רבא האי אפשר למטעמיה והאי לא אפשר למטעמיה","א\"ל רב פפא לרבא וליטעמיה קפילא ארמאה מי לא תנן קדרה שבישל בה בשר לא יבשל בה חלב ואם בשל בנותן טעם בשל בה תרומה לא יבשל בה חולין ואם בשל בנותן טעם","ואמרינן בשלמא תרומה טעים לה כהן אלא בשר בחלב מאן טעים לה ואמר לן ליטעמיה קפילא ה\"נ ליטעמיה קפילא ה\"נ כי קאמינא דליכא קפילא:","איתמר דגים שעלו בקערה רב אמר אסור לאכלן בכותח ושמואל אמר מותר לאכלן בכותח","רב אמר אסור נותן טעם הוא ושמואל אמר מותר נותן טעם בר נ\"ט הוא","והא דרב לאו בפירוש איתמר אלא מכללא איתמר דרב איקלע לבי רב שימי בר חייא בר בריה חש בעיניו עבדו ליה שייפא בצעא בתר הכי רמו ליה בשולא בגווה טעים ליה טעמא דשייפא אמר יהיב טעמא כולי האי ולא היא שאני התם דנפיש מררה טפי","רבי אלעזר הוה קאים קמיה דמר שמואל אייתו לקמיה דגים שעלו בקערה וקא אכיל בכותח יהיב ליה ולא אכל א\"ל לרבך יהיבי ליה ואכל ואת לא אכלת אתא לקמיה דרב א\"ל הדר ביה מר משמעתיה א\"ל חס ליה לזרעיה דאבא בר אבא דליספי לי מידי ולא סבירא לי","רב הונא ורב חייא בר אשי הוו יתבי חד בהאי גיסא דמברא דסורא וחד בהאי גיסא דמברא למר אייתו ליה דגים שעלו בקערה ואכל בכותח למר אייתו ליה תאנים וענבים בתוך הסעודה ואכל ולא בריך","מר א\"ל לחבריה יתמא עבד רבך הכי ומר א\"ל לחבריה יתמא עבד רבך הכי מר א\"ל לחבריה אנא כשמואל סבירא לי ומר א\"ל לחבריה אנא כר' חייא סבירא לי דתני ר' חייא פת פוטרת כל מיני מאכל ויין פוטר כל מיני משקין","אמר חזקיה משום אביי הלכתא דגים שעלו בקערה מותר לאוכלן בכותח צנון שחתכו בסכין שחתך בה בשר אסור לאוכלו בכותח","וה\"מ צנון"],[[0,"שפיד","נותן בשפוד ולא היה חש למה שהכבד יהיה עליון:"],[1,"בי דוגי","שנותנין כלי לקבל השומן כדרך שאנו עושין לאווזין והוא נקרא בי דוגי בלשון ארמי:"],[1,"בשרא עילוי כבדא נמי אסור","לפי שדם הכבד נוטף לתוך הבי דוגי ונמצא אוכלו:"],[2,"ומ\"ש מדמא דבשרא","והרי אף דם הבשר כשאין שם כבד זב עם השומן ואנו אוכלין אותו:"],[2,"ומשני דמא דבשרא שכן","יורד לשולי הכלי והשומן צף למעלה ומניחין לתוך הכלי מראה אדמומית שבשולים:"],[2,"קפי","צף למעלה כמו (מלכים ב ו) ויצף הברזל ומתרגמינן וקפא פרזלא. והלכות כחל כבר למדנו למעלה לצלי בעי קריעה שתי וערב ואם לא קרעו מותר כלישנא קמא דרב דהא תניא כוותיה ולקדרה קורעו שתי וערב וטחו בכותל:"],[3,"סכין ששחט בה","איידי דבית השחיטה רותח בולע הסכין מן הדם ואסור לחתוך בה רותח מפני שחוזר ופולט בו:"],[3,"צונן","ואם חתך בה צונן:"],[3,"בעי הדחה","ההוא צונן:"],[4,"קערה שמלח בה בשר אסור לאכול בה","דבר רותח לפי שנבלע בה הדם ונותן טעם ראשון הוי כאיסור גמור:"],[5,"הא דרבין","דאמר רבי יוחנן מיקל ליתא:"],[5,"דההיא פינכא גרסינן","קערה של חרס שאין לה תקנה בהגעלה:"],[5,"מכדי רבי אמי תלמיד דר' יוחנן כו'","אביי מסיק ליה למילתיה:"],[6,"וצנון שחתכו בסכין","אע\"ג דאגב חורפיה דצנון איגר\"ש בלע\"ז הוא בולע משמנונית הסכין הקרוש עליו והוי האי צנון נתינת טעם ראשון שהרי בלע איסור ממש והוי כבשר:"],[6,"מותר לאכלו","לאותו צנון בכותח שיש בו נסיובי דחלבא כדמפרש טעמא דכיון שבלע מן השמנונית דהיתרא בלע:"],[7,"והאי איסורא בלע","קערה בלעה דם:"],[8,"סוף סוף האי היתירא לידי איסורא אתי","כשנותנו בכותח:"],[8,"האי","צנון אפשר לו לישראל לטועמו קודם שיתננו בכותח והאי מותר דקאמר כגון שטעמו בתחלה ולא היה בו טעם שמנונית:"],[8,"והאי","דם הקערה:"],[8,"לא אפשר למטעמיה","לפי שאסור הוא הלכך אין לו תקנת היתר:"],[9,"קפילא","נחתום עובד כוכבים:"],[10,"כי קאמינא","דאסור לאוכל בה רותח בדליכא קפילא:"],[11,"דגים שעלו בקערה","מן הצלי כשהיו רותחין נתנן לתוך הקערה שאכלו בה בשר:"],[11,"אסור לאוכלן בכותח","לפי שהבשר נותן בהם טעם:"],[12,"נותן טעם בר נותן טעם הוא","אם היו מבושלים עם בשר ממש היה אסור לאוכלן בכותח אי נמי מודה שמואל שאסור לאכול חלב רותח בקערה דנותן טעם ראשון הוי כבשר גמור אבל קערה זו היא עצמה אינה בשר אלא על ידי נותן טעם ואינה כבשר:"],[13,"שייפא","משיחה מסממנים:"],[13,"בצעא","קערה:"],[13,"רמו בישולא","באותה קערה לאחר זמן:"],[13,"אמר יהיב טעמא","בקערה:"],[13,"כולי האי","שחוזר ונותן טעם בבישול. ומאן דשמע סבר דאית ליה לרב נתינת טעם בר נתינת טעם נמי בעלמא:"],[13,"ולא היא","דגבי סממנים נפיש מררייהו מרים הם מאד:"],[14,"קאים קמיה","משמש לפניו בסעודה:"],[14,"לרבך","רב שלמדת ממנו שאסור:"],[14,"אבא בר אבא","אבוה דשמואל הוה וחסיד גדול היה:"],[14,"דליספי לי מידי דלא סבירא לי","לא היו דברים מעולם:"],[15,"בהך גיסא דמברא דסורא","שהיה הנהר מפסיקן:"],[15,"תאנים וענבים","לא אתו לליפתן וקיימא לן (ברכות דף מא:) דברים הבאים לאחר סעודה כלומר הרגילים לבא לאחר סעודה טעונין ברכה בין לפניהם ובין לאחריהם אפילו הביאן בתוך הסעודה דכיון דאינן ליפתן אין הפת פוטרתן:"],[16,"יתמא","בלא דעת:"]],[[5,"מליח אינו כרותח","והא דתניא (לקמן חולין דף קיג.) דטמא מליח וטהור תפל אסור היינו בדגים דרפו קרמייהו:"],[7,"אמר אביי האי היתרא בלע כו'","לא ר\"ל משום דהוי נותן טעם בר נותן טעם כמו דגים שעלו בקערה דאביי לטעמיה דחשיב ליה חד טעמא משום חורפיה דצנון ואע\"ג דלקמן אסר אביי אליבא דרב כהנא קאמר לה:"],[13,"ולא היא שאני התם דנפיש מרריה","כלומר מכאן אין להוכיח אבל הוא בפירוש אמרה כדמוכח בסמוך:"],[14,"אבא בר אבא","אבוה דשמואל הוה כדאמרינן בפרק מי שמתו (ברכות דף יח:):"],[16,"כרבי חייא בר אבא ס\"ל","אין הלכה כן אלא כדפסקינן בפרק כיצד מברכין (ברכות דף מא:):"],[17,"הלכתא דגים שעלו בקערה","של בשר מותר לאוכלן בכותח אם הקערה והדגים צוננים לא איצטריך לפסוק דליכא מאן דפליג אלא כשהאחד מהן רותח דבין עלאה גבר בין תתאה גבר קליפה מיהא בעי כדאמרי' בפ' כיצד צולין (פסחים דף עו.) אדמיקר ליה בלע. בשם רש\"י פי' ריב\"ן חתנו דוקא עלו שרו אבל נתבשלו אסור דכחד טעמא חשיב ובא מעשה לפניו בביצים שנתבשלו בקדרה של חלב ואסר לעשות מהם מולייתא של בשר ויש להביא ראיה לדבריו מצנון שחתכו בסכין דאסור לאוכלו בכותח משום דאגב חורפיה בלע טפי וחשיב כחד טעמא ונתבשלו לא גרע מצנון ומיהו לפירוש לשון אחר שפי' בקונט' דטעמא דאסור משום שהשומן קרוש על הסכין ואינו ניכר והוי טעם ראשון בצנון אין ראיה משם ומתוך לשון הקונט' משמע דאין חלוק בין עלו לנתבשלו דלעיל גבי נותן טעם בר נותן טעם פירש בקונטרס דאם היו מבושלים עם בשר ממש או לאכול חלב בקערה מודה שמואל דאסור דהוי נותן טעם ראשון משמע מתוך פירושו דמבושלים עם בשר הוא דאסור אבל מבושלים עם הקערה שרי והא דאמרינן פרק כל שעה (פסחים דף ל:) אין טשין התנור באליה ואם טש כל הפת אסורה עד שיוסק התנור ולא סגי בקנוח אין ראיה משם דנתבשל אסור מדלא חשיב ליה בקנוח נותן טעם בר נותן טעם דאומר ר\"ת דאי אפשר לתנור להתקנח יפה כשנדבק בו השמנונית והוי בעין עד שיוסק ויש לדקדק דאפילו נתבשלו שרי כדאמרינן פרק דם חטאת (זבחים דף צז.) דכל יום ויום נעשה גיעול לחבירו ומותר לבשל שלמים האידנא בקדרה שבשל בה שלמים אתמול דלא אמרינן דקא ממעט באכילת שלמים דהאידנא משום דטעם שני הוא ונתבטל קודם שיבא לידי איסור ואין לומר דשאני התם דהוי טעם שלישי לפי שיש מים בקדרה מטעם זה יהיו נמי הביצים מותרים שנתבשלו במים בקדרה ועוד דגבי שפוד ואסכלה מייתי בסוף מסכ' ע\"ז (דף עו.) ההיא דכל יום ויום נעשה גיעול לחבירו ומיהו ע\"כ אין ראיה משם דהא אפילו בשל בה חטאת שרי לבשל באותה קדרה שלמים בסוף מסכת ע\"ז (שם) והרי ממעט באכילתה דמתסרי לזרים ולנשים ולעבדים דאין נאכלת אלא לזכרי כהונה וגם מפסלי ביוצא דהוי טעם שני באיסור ועל כרחיך התם הוי טעמא משום דמין במינו מדאורייתא בטל ברוב ובכלי מקדש אוקמוה אדאורייתא וקערות שמשתמשין בהן בשר שהודחו במחבת של חלב בכלי ראשון ושניהם בני יומן יש לאסור אפילו אם נאמר לאו דוקא עלו אלא אפילו נתבשלו אם השמנונית בעין על הקערות דהוי כסכין שלא נתקנח דאסר בקונטרס ללשון אחר ואפילו אין שמנונית בעין אסור דהקערות נוגעות במחבת ונפלט טעם מזה לזה והוי טעם שני באיסור ועוד דלא דמי כלל לדגים שעלו בקערה דהא כשהטעם שני של בשר ושל חלב נכנס במים מיד נאסרו המים וחוזרין ואוסרין הקערות והמחבת ואם האחד אינו בן יומו אז אותו שהוא בן יומו מותר:"]]],[["דאגב חורפיה בלע אבל קישות גריר לבי פסקיה ואכיל","קילחי דליפתא שרי דסילקא אסירי ואי פתך בהו דליפתא שפיר דמי","בעא מיניה רב דימי מרב נחמן מהו לאנוחי כדא דמלחא גבי כדא דכמכא אמר ליה אסור דחלא מאי אמר ליה שרי","ומאי שנא לכי תיכול עלה כורא דמלחא מאי טעמא האי איתיה איסורא בעיניה והאי ליתיה איסורא בעיניה","ההוא בר גוזלא דנפל לכדא דכמכא שרייה רב חיננא בריה דרבא מפשרוניא אמר רבא מאן חכים למישרי כי האי גוונא אי לאו רב חיננא בריה דרבא מפשרוניא קסבר כי אמר שמואל מליח הרי הוא כרותח הני מילי היכא דאינו נאכל מחמת מלחו אבל האי כותחא הרי נאכל מחמת מלחו","והני מילי חי אבל צלי בעי קליפה ואי אית ביה פילי כוליה אסור ואי מתבל בתבלין כוליה אסור","אמר רב נחמן אמר שמואל ככר שחתך עליה בשר אסור לאכלה והני מילי דאסמיק והני מילי דאבריה והני מילי דאסמכיה אבל קלישתא לית לן בה","שמואל שדי ליה לכלביה רב הונא יהיב ליה לשמעיה מה נפשך אי שרי לכולי עלמא שרי אי אסור לכולי עלמא אסור שאני רב הונא דאנינא דעתיה רבא אכיל ליה וקרי ליה חמר בשר","אמר רב נחמן אמר שמואל אין מניחין כלי תחת בשר עד שיכלה כל מראה אדמומית שבו מנא ידעינן מר זוטרא משמיה דרב פפא אמר משתעלה תימרתו","מתקיף לה רב אשי ודלמא תתאה מטא עילאה לא מטא אלא אמר רב אשי לית ליה תקנתא אלא משדא ביה תרתי גללי מלחא"],[[0,"קישות","מתוקה היא ואינו נבלע בתוכה אלא השמנונית צף ועומד על מקום החתך הלכך גריר לבי פסקיה למקום חתך גורר מעט בסכין ואכיל אף בכותח. הלכך דגים שעלו בקערה מותר לאוכלן בכותח כדאמר דאין נותן טעם הבא מן הממש אלא נותן טעם הבא מנותן טעם דסתם קערה מקנחין אותה משומן הקרוש עליה משום מיאוס אבל לסכין פעמים שהשמנונית קרוש עליו ואינו ניכר וכשחותך בצנון הוי נותן טעם הבא מן הממש ועוד דמשום חורפיה בלע טפי מדגים הרותחים ואגב דוחקא דסכינא פליט סכינא ובלע צנון:"],[1,"קלחי","קלחים:"],[1,"ליפתא","לפת אינו חריף אלא מתוק ואין טעם שומן ניכר בו:"],[1,"דסילקא אסירי","לפי שנותן טעם בהן:"],[1,"ואי פתך בהו דליפתא","ערבן בעת חתוכן שחתך אחת של לפת ואחת של תרדין הלפת מבטל טעם השמנונית מן הסכין ואין התרדין מקבלין טעם הימנו:"],[2,"כמכא","כותח. מי חיישינן שמא יפול מן הכותח במלח והוא לא ידע וימלחו ממנו קדרת בשר:"],[2,"דחלא מאי","דרך לתת חומץ לתוך התבשיל. מי חיישינן שמא יפול מן הכותח בחומץ ויחזור ויתן ממנו לתבשיל:"],[3,"לכי תיכול","כשתמדוד לי עליה כור של מלח בשכרי אומר לך טעמו של דבר:"],[3,"האי","כותח הנופל במלח נראה וניכר מפני שהוא עב ולא בטיל אבל כותח הנופל בחומץ ליתיה בעיניה וטעמא נמי לא יהיב כותח בחומץ:"],[4,"שרייה רב חיננא","אע\"פ שהכותח מליח הוא:"],[4,"דאינו נאכל מחמת מלחו","אינו נוח ליאכל מרוב מלח שבו עד ששורין ומדיחין אותו במים כעין מליחת בשר להצניע:"],[4,"נאכל מחמת מלחו הוא","כלומר נאכל במלחו הוא:"],[5,"קליפה","מלמעלה סביב:"],[5,"ואי אית ביה פילי","בקעים והוא צלי לא סגיא ליה בקליפה לפי שבולע דרך הנקבים וכולו אסור:"],[5,"ואי מתבל בתבלין","התבלין שנתבשלו עמו מרככין אותו ונוח לבלוע וכשנפל לכותח היה צמא לבלוע ובלע:"],[6,"שחתך עליה בשר","כשהוא חותך מן הצלי:"],[6,"אסור לאכלה","מפני שהדם יוצא ונבלע בו:"],[6,"וה\"מ דאסמיק","שהיה הבשר אדום שנקטרוד\"א:"],[6,"והני מילי דאבריה","שנקב הדם את הככר כלומר עבר מצדו לצדו עד שנראה משני צדדין:"],[6,"הכי גרסינן והני מילי דאסמכיה","שהיה אותו מוהל היוצא מן הבשר עבה אבל צלול לאו דם הוא:"],[7,"שדי ליה לכלביה","לההוא ככר:"],[7,"מה נפשך","דאיהו לא בעי למיכליה ולשמעיה ספי ליה איסורא:"],[7,"דאנינא דעתיה","האי דלא אכיל ליה משום דאיסטניס הוה ולאו משום איסורא:"],[7,"חמר בשר","יין הבשר:"],[8,"אין מניחין כלי","בי דוגי דלעיל (חולין דף קיא:):"],[8,"עד שיכלה","שיהא כל דמו כבר נפלט ממנו:"],[8,"משתעלה תימרתו","שהבשר מעלה עשן. לישנא אחרינא שיהו הגחלים מעלין עשן שכל זמן שהדם שותת עליהן אינן אלא כבין והולכים אבל כשהשומן נוטף הן מעלין עשן. לשון מורי:"],[9,"ודילמא תתאה מטא","צד התחתון של צד גחלים נצלה והעליון לא נצלה:"],[9,"תרי גללי דמלחא","בין על הבשר ובין בתוך הכלי והדם נגרר אצל המלח לשוליים:"]],[[0,"אגב חורפיה בלע","יש ליזהר שלא לחתוך שומין כרישין ובצלים בסכין חולבת משום דחריפי טובא והיכא דחתך ונתנן בקדרה מלאה מים רותחת מותר בששים לבטל טעם הבלוע בירק ונפלט מן הסכין אבל חתכו בסכין של עובד כוכבים נעשה הירק כולו נבלה וצריך ששים לבטל הירק וצריך עיון אם הסכין מקונח ואין בן יומו אי חורפא דידהו מחליא לשבח כדאמר גבי חלתית פרק אין מעמידין (ע\"ז דף לט.):"],[2,"מהו לאנוחי כדא דמלחא בהדי כדא דכמכא א\"ל אסור","אין לאסור מטעם זה להניח בתבה אחת כד של בשר אצל כד של חלב דהתם נזהר יפה שלא יפול מזה על זה אבל הכא לא מסקי אדעתייהו ליזהר שלא יפול מן הכותח במלח ולא ידע וימלח ממנו בשר וכן דחלא כי דרך לתת חומץ בתבשיל וחיישינן שמא יפול מן הכותח לתוכו ויחזור ויתן לתוך התבשיל:"],[4,"הני מילי דאינו נאכל מחמת מלחו","הר\"ר יעקב ישראל התיר פעם אחת גיגית מלאה בשר שנמלחה יפה עם חתיכת נבלה ואמר דלא חשיב אינו נאכל מחמת מלחו אא\"כ נמלח כעין עבוד כדאמר פרק כלל גדול (שבת דף עה:) האי מאן דמלח בישרא בשבת חייב משום מעבד ומוקי לה דבעי לאורחא אבל לביתא לא משוי איניש מיכליה עץ ובקונטרס נמי פירש אינו נאכל מרוב מלח שבו עד ששורהו ומדיחו במים כעין בשר שמולחים להצניע וקשיא לר\"ת דאטו הנהו אטמהתא דאימליחו בגידא דנשיא בי ריש גלותא בפרק גיד הנשה (לעיל חולין דף צז:) דמייתי עלה מליח הרי הוא כרותח וכי נמלחו לאורחא וכן (לעיל חולין דף קיא:) קערה שנמלח בה בשר אסור לאכול בה רותח וההיא פינכא דהוה בי רבי אמי וכן רב מרי דאימלח ליה בשר שחוטה בהדי טרפה בסמוך אטו כל הני הוו לאורחא או להצניע כפי' הקונטרס ואור\"ת דכל מליחות שאנו עושין לקדרה חשיבי אין נאכלין מחמת מלחן מדפירש בהלכות גדולות דשיעור מליחה כשיעור צלייה משום דמליח הרי הוא כרותח דצלי וכן משמע בהקומץ רבה (מנחות דף כא.) דקאמר טעמא דמעטיה קרא הא לאו הכי [הו\"א] דם ליבעי מלח והא נפק ליה מתורת דם דאמר רב יהודה דם שמלחו אינו עובר עליו אלמא מליחת קדשים הוי אין נאכל מחמת מלחו מדפטר דם שמלחו כמו דם שבשלו דאמרינן התם דאין עובר עליו וקאמר התם רבה על מליחת קדשים וכן לקדרה אלמא למליחת קדרות צריך שלא יהו נאכלים מחמת מלחן:"],[9,"תרי גללי דמלחא ומשפייה","שהדם נגרר אצל המלח בשולים ואפילו למ\"ד (לעיל חולין דף קח:) אפשר לסוחטו אסור יש להתיר כאן ולא אמרינן מיד כשנוטף השומן מן הבשר נאסר מחמת דם המעורב בו ושוב לא יועיל לו תרי גללי דמלחא דכיון שהדם נפרש ממנו לגמרי אין נשאר בו טעם ואפילו משהו דכך היו בקיאין בדבר המותר ולא דמי לאפשר לסוחטו דלעיל דהתם אין האיסור יוצא לגמרי אלא שמתבטל ועכשיו אין להתיר על ידי תרי גללי דמלחא לפי מה שפירש בהלכות גדולות דדוקא נקט תרי גללי אבל הרבה מלח פוסק כח הדם ואין אנו בקיאין בדבר שלא להרבות ושלא למעט:"]]],[["ומשפייה","אמר ליה רב אחא בריה דרב איקא לרב אשי ומי אמר שמואל הכי והאמר שמואל ככר שחתך עליה בשר אסור לאכלה שאני התם דאגב דוחקא דסכינא פליט","אמר רב נחמן דגים ועופות שמלחן זה עם זה אסורין היכי דמי אי בכלי שאינו מנוקב אפי' עופות ועופות נמי אסירי אי בכלי מנוקב אפי' דגים ועופות נמי שרי","לעולם בכלי מנוקב ודגים משום דרפו קרמייהו קדמי ופלטי ועופות קמיטי בתר דניחי דגים פליטי עופות והדר בלעי מיניה","רב מרי בר רחל אימלח ליה בשר שחוטה בהדי בשר טרפה אתא לקמיה דרבא","אמר ליה (ויקרא יא, כו) הטמאים לאסור צירן ורוטבן וקיפה שלהן"],[[0,"ומשפייה","כמו (ב\"מ דף ס.) השופה יין לחבירו קולי\"ר כלומר יערה השומן העליון בנחת מכלי אל כלי כדי שלא יתערב הדם בו. וראיתי בהלכות גדולות דדוקא נקט תרי גללי כלומר מעט מלח אבל מלח הרבה פוסק כח הדם ועושהו כמים והוא נעכר ומתערב עם השומן:"],[1,"ומי אמר שמואל הכי","דלאחר שיכלה כל מראה אדמומית שבו מותר:"],[1,"והאמר שמואל כו'","והאי בשר כבר נצלה:"],[1,"שאני התם דאגב דוחקא דסכינא פליט","לעולם כשתעלה תמרתו אין הדם יוצא ממנו ע\"י האור ושמנונית הוא ומותר אבל כשחותכו וכובש עליו את הסכין הוא דוחקו ואם נשאר בו דם דוחקו והוא יוצא:"],[2,"דגים ועופות","לאו דווקא עופות דכל שכן בשר אחר לפי שהוא קשה מבשר עופות:"],[2,"אסורין","[הדגים לבדן] שהדם יוצא מן הבשר ונבלע בדגים:"],[2,"אפילו עופות ועופות [נמי] אסירי","כדאמרינן לקמן (חולין דף קיג.) אין מולחין בשר אלא על גבי כלי מנוקב לפי שהדם היוצא נשאר בכלי וחוזר ונבלע בבשר:"],[2,"אפילו עופות ודגים [נמי] שרי","שהרי הדם יוצא דמה לי דגים ומה לי שאר שתי חתיכות הנמלחות זו על גב זו שאע\"ג שהדם יוצא מעליונה לתחתונה אין נאסרין אם הכלי מנוקב:"],[3,"לעולם בכלי מנוקב","והיינו טעמא דדגים אסורין:"],[3,"משום דדגים רפו קרמייהו","קרום שלהן רך:"],[3,"וקדמי ופלטי","ממהרין לפלוט ציר שלהן:"],[3,"ועופות קמיטי","צומתין אשטרינ\"ט. כלומר אין ממהרין לפלוט וכבר נחו הדגים מלפלוט ועדיין עופות פולטין הלכך בלעי דגים אבל בשר ובשר כמה שזה שוהה לפלוט כך זה שוהה לפלוט ושניהם פולטין יחד וכל זמן שהתחתון טרוד בפליטה אינו בולע:"],[4,"אימלח ליה בשר שחוטה בהדי בשר נבלה","ובכלי מנוקב כמשפט המולחים בשר וקמיבעיא ליה מי אמרינן כי היכי דגבי דם לא חיישינן לדלמא פלט עליון ובלע תחתון דאמרינן כל זמן שטרודים בפליטה אינן בולעין ושניהם נחין יחד מפליטתן ה\"נ לא שנא או לא:"],[5,"אמר ליה הטמאים","ה\"א יתירא דגבי הטמאים לכם בכל השרץ (ויקרא יא):"],[5,"לאסור צירן ורוטבן וקיפה","פירמא בשר ותבלין הנקפה בשולי הקדירה וכיון דצירן אסור מיתסר הבשר השחוט מחמת ציר הטרפה שהוא נוח ליבלע מן הדם:"]],[[2,"דגים ועופות שמלחן זה עם זה אסורין","הדגים לבדן והקשה רבינו שמואל דא\"כ הול\"ל דגים שמלחן עם עופות אסורין וי\"ל דא\"כ הוה משמע אפילו העופות תפל והדגים מלוחים כמו דג טהור שמלחו עם דג טמא דבסמוך דמיירי בטהור מליח וטמא תפל וזה אינו כי בענין זה לא היו הדגים אסורין ונראה דאין העופות נאסרים מהדגים שנאסרו אפילו לאותו פירוש שבכל איסורין אמרינן חתיכה עצמה נעשית נבלה אם האיסור עצמו הולך ומתפשט ונאמר שגם מן הדם שנבלע בדגים נפלט מקצת עם ציר הדגים ונבלע בעופות אף על פי שכולה אין פולטין להיות מותרין על ידי כן כיון דכבר גמרו פליטתן דמ\"מ אין סברא לאסור העופות דדם משרק שריק במליחה כמו בצליה ובדגים דרפו קרמייהו הוא דאמר לעיל דלא שריק דם עופות מינייהו:"],[3,"ודגים רפו קרמייהו ופלטי ועופות קמיטי","פירש בקונטרס אבל בשר ובשר כמו שזה שוהה לפלוט כך זה שוהה לפלוט ושניהם פולטין יחד וכל זמן שתחתון טרוד לפלוט אינו בולע וכמו כן פירש בסמוך (לקמן חולין דף קיג.) גבי רב ששת דמלח גרמא גרמא דמסיק אלא לא שנא ופירש בקונטרס ל\"ש ומותר דכל זמן שטרודים לפלוט אינן בולעים וכשנח זה כבר נח זה ולפירושו תימה כשמולחין הרבה חתיכות יחד זו אחר זו ומניחין שניה על הראשונה וכן שלישית וכן רביעית אפילו יש כמה חתיכות אע\"פ שהראשונה גומרת פליטתה תחלה ופשטיה דאלא לא שנא (נמי) משמע (שמותר למלוח כל אחד ואחד בפני עצמו וכן מפרש ר\"ת אלא לא שנא) שאע\"פ שהתחתון פולט תחלה אינו נאסר ולמה מותר כיון שפליטת התחתון קודמת ונראה דהיינו טעמא משום דדם מישרק שריק במליחה כמו בצליה וכי היכי דשרי בצלי בשרא עלוי בשרא אפילו לכתחלה אע\"פ שכלה תחלה פליטתה בצד התחתון של צד האש משום דמשרק שריק הוא הדין נמי במליחה דשרי כה\"ג ודגים דוקא משום דרפו קרמייהו אסירי משום דרכיכי ונבלע הדם בתוכן ולא שריק מינייהו ומיהו היכא דאיכא גומות בצד עליון של תחתונות דלא מצי שריק קשה למה יהא מותרין דמעשים בכל יום שמוצאין גומות [בחתיכות] התחתונות מלאות ציר ונוהגין בדבר היתר וי\"מ משום דפליטת ציר מושכת הרבה אחר פליטת הדם וכל זמן שמושך פליטת הציר פולטות מה שבולעות מן העליונות אחר פליטת דמן ומה שנמצא בגומות ציר הוא ולא דם אבל בדגים אין לומר כן לפי שפליטת דם העופות מושכת אחר פליטת ציר הדגים וה\"ר יוסף מאורלינ\"ש היה אומר לפי שפליטת הדגים נגמר קודם התחלת פליטת העופות לכך אינן פולטין עוד מה שבולעין מן העופות אבל בשר ובשר כיון שלא נגמר פליטת דם תחתון קודם התחלת בליעתה מן העליון אין דרך פליטתה נסתמת דהואיל ופתוח לפלוט לא יסתם עד גמר פליטת החתיכה שעליה וכן אם מלחו שלישית ונתנו על העליונות קודם גמר פליטתה התחתונה פולטת עד שתגמור השלישית פליטתה וכן לעולם כל מה שיתנו עליה תבלע ותפלוט כיון שלא נחה רגע אחת וא\"ת נהי דלפי שני הטעמים האלו אין לאסור מחמת פליטת חתיכה העליונה מ\"מ נאסור מחמת דם הבלוע במלח שבין חתיכה לחתיכה שנמחה בציר שבגומות אחר פליטת כל הדם והציר דבשלמא בכל חתיכה מלוחה דעלמא אין המלח שעליה אוסרה לפי שמועט הוא הדם הבלוע במלח ואינו יכול עוד לזוז משם כלל אבל כאן שנמחה המלח בציר שבגומא ונעשה צלול היה לו לדם זה לאסור כדי קליפה ושמא לא אמרינן מליח הרי הוא כרותח אלא בשעת פליטה אבל אחר גמר פליטה לא חשיב כרותח דפסק כח המלח מחמת שהפליט את הבשר ויוצא כח המלח עם הדם אי נמי י\"ל שהמלח שעל הבשר מעכב הדם הזה מליכנס בבשר ולפי אותן השני טעמים שפירשתי דכל זמן שהתחתונה פולטת ציר בולעת ופולטת דם העליונות עם ציר שלה אז כל זמן שפתוחה לפלוט בולעת ופולטת צריך להמתין לתחתונה עד שתשהה העליונה שיעור צליה שעד אותה שעה אין התחתונה יוצאת מידי דמה ומיהו עדיין י\"ל טעם אחר דכל זמן שהבשר טרוד לפלוט ציר אין בולע דם וזמן פליטת הציר אינו כלה כל כך מהרה ומכל מקום בשר שבתוך הציר כגון בכלי שאינו מנוקב אין להתיר מטעם זה דאין לו שם כח לפלוט מחמת שהוא שקוע בתוך הציר ובולע והיינו טעמא דשמואל דאמר לקמן (חולין דף קיג.) אין מולחין אלא בכלי מנוקב דאע\"ג דעדיין לא גמר הבשר פליטת דמו בולע כדפרישית והיכא דחציה של חתיכה בתוך הציר וחציה בחוץ מה שבתוכו אסור ומה שבחוץ מותר כדפרישית לעיל בפרק גיד הנשה (חולין דף צו:) גבי גדי שצלאו בחלבו והיכא ששהה הבשר במלח כשיעור צליה על דף אחד ואח\"כ הושם בגיגית ושהה שם כל הלילה ואחר כך נמצא הכלי מלא מיץ מן המליח שיצא מן הבשר אירע מעשה בביתו של רש\"י והשיב דמאחר ששהה הבשר במלח כדי שיעור קודם שהושם בכלי אין המים הנמצאים בכלי מין דם אלא מוחל בעלמא וכן נראה ותדע שאותו המוחל הוא היתר מיד כששהה שיעור צליה הוא מותר להדיחו ולבשלו בקדרה אע\"פ שלא נפלט ממנו המוחל היוצא אח\"כ ואין לאסור נמי המוחל מחמת המלח שעל הבשר שנמחה בתוכו דאם מכח זה באנו לאסור בשר הנופל באותו מוחל לפי שיש בו רוב מלח שעל הבשר ואין נאכל מחמת מלחו ליחשב כרותח ואוסר את הבשר א\"כ גם מטעם זה יאסר כל הבשר שבעולם כשמניחין אותו בתוך הכלי להדיחו שנמחה המלח שעל הבשר במים דמה לי מים מה לי מוחל כיון דשניהם של היתר אלא צריך לומר שהדם שבמלח מתייבש בו ואין בו כח ליבלע בבשר אלא עומד במקומו אע\"פ שנמחה בתוך אותו מוחל כמו שפי' גבי אותן גומות שבבשר דמה לי גומא מלאה ציר ומה לי כל הבשר בתוך הציר או מטעם שפסק כח המלח מחמת שהפליט הבשר ולא חשיב כרותח כדפרישית לעיל ומ\"מ אין להקל שכבר נהגו העם איסור:"],[5,"הטמאים לאסור צירן","דרשה גמורה היא גבי שרצים ובהמה חוץ מגבי דגים כדפרישית בפרק גיד הנשה (לעיל חולין דף צט:) גבי שאני ציר דזיעה בעלמא הוא:"],[5,"ורוטבן וקיפה שלהן","וא\"ת ותיפוק ליה ממשרת ליתן טעם כעיקר דמשם אתה דן לכל התורה כדאיתא פרק אלו עוברין (פסחים דף מד:) וי\"ל דעיקר דרשה לא איצטריך אלא לצירן ושאר הוו אסמכתא בעלמא כדאמר פרק אלו מציאות (ב\"מ דף ל:) גבי והתעלמת דעיקר קרא לזקן ואינו לפי כבודו אי נמי איצטריך נמי לרוטבן וקיפה ואשמעינן דמחוי כממש אם המחה השרץ וגמעו דהוי כאכילה דס\"ד דבשתיה לא מיחייב כיון דאכילה כתיבא ביה והכי איתא בהעור והרוטב (לקמן חולין דף קכ.) דמייתי לה אהמחה את החלב וגמעו ואם תאמר אם כן היכי דריש מינה דצירן אסור כיון דאיצטריך להכי ויש לומר דשקולים הם ומציר גופיה לא הוה שמעינן דלהוי שתיה כאכילה דהוי מצינן לאוקומי כשהקפהו ואכלו:"],[5,"וקיפה שלהן","בהעור והרוטב (גז\"ש) מפרש קיפה פירמא ופריך הוא עצמו ליטמא טומאת אוכלין אלא מאי קיפה תבלין והיה יכול להיות בין פירמא בין תבלין דאתא לאשמועינן דשתייתה כאכילתה וכן פירש בקונטרס פירמא בשר ותבלין הנקפה בשולי הקדרה ומיהו לא היה לו לומר הנקפה:"]]],[["ולימא ליה מדשמואל דאמר שמואל מליח הרי הוא כרותח וכבוש הרי הוא כמבושל","אי מדשמואל הוה אמינא הני מילי דמן אבל צירן ורוטבן לא קמשמע לן","מיתיבי דג טהור שמלחו עם דג טמא מותר מאי לאו שהיו שניהן מלוחין לא כגון שהיה טהור מליח וטמא תפל","והא מדקתני סיפא (אבל אם היה טהור מליח וטמא תפל) מכלל דרישא בששניהם מלוחין עסקינן פרושי קא מפרש טהור שמלחו עם דג טמא מותר כיצד שהיה טהור מליח וטמא תפל","ה\"נ מסתברא דאי סלקא דעתך רישא שניהם מלוחים השתא שניהם מלוחים שרי טהור מליח וטמא תפל מיבעיא","אי משום הא לא איריא תנא סיפא לגלויי רישא דלא תימא רישא טהור מליח וטמא תפל אבל שניהם מלוחין אסור תנא סיפא טהור מליח וטמא תפל מכלל דרישא שניהן מלוחין ואפ\"ה שרי","ת\"ש מסיפא דסיפא אבל אם היה טמא מליח וטהור תפל אסור טמא מליח וטהור תפל הוא דאסור הא שניהן מלוחין שרי","איידי דתנא רישא טהור מליח וטמא תפל תנא נמי סיפא טמא מליח וטהור תפל","(סימן בישרא דמנח נפקותא)","אמר שמואל אין הבשר יוצא מידי דמו אלא א\"כ מולחו יפה יפה ומדיחו יפה יפה אתמר רב הונא אמר מולח ומדיח במתניתא תנא מדיח ומולח ומדיח ולא פליגי הא דחלליה בי טבחא הא דלא חלליה בי טבחא רב דימי מנהרדעא מלח ליה במילחא גללניתא ומנפיץ ליה","אמר רב משרשיא אין מחזיקין דם בבני מעיים תרגמא אכרכשא ומעייא והדרא דכנתא","אמר שמואל אין מניחין בשר מליח אלא ע\"ג כלי מנוקב","רב ששת מלח ליה גרמא גרמא תרי מאי טעמא לא משום דפריש מהאי ובלע האי חד נמי פריש מהאי גיסא ובלע האי גיסא אלא לא שנא","אמר שמואל משום ר' חייא השובר מפרקתה של בהמה קודם שתצא נפשה הרי זה מכביד את הבשר וגוזל את הבריות ומבליע דם באברים","איבעיא להו היכי קאמר מכביד את הבשר וגוזל את הבריות משום דמבליע דם באברים הא לדידיה שפיר דמי או דלמא לדידיה נמי אסור תיקו:","\u0001מתני׳\u0002 המעלה את העוף עם הגבינה על השלחן אינו עובר בלא תעשה:","\u0001גמ׳\u0002 הא אוכלו עובר בלא תעשה שמע מינה בשר עוף בחלב דאורייתא אימא המעלה את העוף עם הגבינה על השולחן אינו בא לידי לא תעשה:","\u0001מתני׳\u0002 בשר בהמה טהורה בחלב בהמה טהורה אסור לבשל ואסור בהנאה בשר בהמה טהורה בחלב בהמה טמאה בשר בהמה טמאה בחלב בהמה טהורה מותר לבשל ומותר בהנאה ר\"ע אומר חיה ועוף אינם מן התורה שנאמר (שמות כג, יט) לא תבשל גדי בחלב אמו ג' פעמים פרט לחיה ולעוף ובהמה טמאה","רבי יוסי הגלילי אומר נאמר (דברים יד, כא) לא תאכלו כל נבלה ונאמר לא תבשל גדי בחלב אמו את שאסור משום נבלה אסור לבשל בחלב עוף שאסור משום נבלה יכול יהא אסור לבשל בחלב ת\"ל בחלב אמו יצא עוף שאין לו חלב אם:","\u0001גמ׳\u0002 מנא הני מילי א\"ר אלעזר אמר קרא (בראשית לח, כ) וישלח יהודה את גדי העזים"],[[1,"הני מילי דמן","כלומר הני מילי לגבי דם וכגון בכלי שאינו מנוקב דבתר דפלט הדר בלע:"],[1,"אבל צירן","זיעה הוא ולא מיתסר והכא לדם ליכא למיחש דמנוקב הוא וא\"כ כשרה וכשרה נמי:"],[1,"קמ\"ל","דציר אסור וציר נוח ליבלע הוא:"],[1,"מאי לאו שניהם מלוחים","ושמע מינה ציר נמי לא מיבלע כל זמן שעסוקים בפליטה:"],[1,"","וש\"מ צירן מותר לא גרסינן:"],[2,"תפל","מבלי מלח דהשתא לא פליט טמא מידי אבל שניהם מלוחים דטמא נמי פליט אסור וכ\"ש טמא מליח וטהור תפל:"],[6,"הא שניהם מלוחים שרי","דשניהם טרודים בפליטה:"],[9,"","רב הונא דלא בעי הדחה ברישא בדחלליה בי טבחא. כל רחיצת הבשר מתרגמינן חילול:"],[9,"מילחא גללניתא","מלח גסה שלמי\"א:"],[9,"ומנפיץ ליה","למילחא לאחר זמן מפני שהדם נבלע בה אבל מלח דקה אין צריך לנפץ שהיא נתכת מעצמה:"],[10,"אין מחזיקין דם","אינן בחזקת דם ליאסר אם לא נמלחו:"],[10,"הדרא דכנתא","דקין שסביב הכנתא אנטרי\"ל:"],[10,"ומעיא","קבה וכרס ושאר הדקין:"],[10,"וכרכשא","טבחיי\"א. אבל הלב והריאה והכבד וכנתא גופה יש בהן דם וצריכין לימלח:"],[12,"אלא ל\"ש","ומותר וטעמא כדפרשינן לעיל (חולין דף קיב: ד\"ה ועופות) דכל זמן שטרודים לפלוט אינן בולעים וכשנח זה כבר נח זה:"],[13,"הרי זה מכביד את הבשר","לפי שבשעת שחיטתה היא טרודה להוציא דם וכששובר מפרקתה מתוך צרתה אין בה כח להתאנח ולהוציא דם והיא נחה ושוקטת והדם נבלע באבריה ומכביד הבשר ונמצא גוזל את הבריות כשהוא מוכרה במשקל והדם שוקל:"],[14,"איבעיא להו היכי קאמר","האי ומבליע דם דקתני כוליה חד איסורא הוא וה\"ק מכביד את הבשר ונמצא גוזל את הבריות הוא משום דמבליע דם שמכביד את משקלה והבלעת דם לפרושי גוזל את הבריות נקט לה:"],[14,"הא לדידיה","דליכא למימר משום גזילה שרי לפי שהוא חוזר ויוצא ע\"י מלח:"],[14,"או דילמא לדידיה נמי אסור","ותרתי איסורי קחשיב חדא דגוזל את הבריות וחדא דמבליע דם ושוב אינו יוצא ואוכל דם:"],[15,"מתני' אינו עובר בלא תעשה","היא גופה לא איצטריך דהעלאה לאו דאורייתא אלא דיוקא דילה איצטריך למידק מינה הא אוכל עוף בחלב עובר ולאפוקי מדרבי עקיבא דאמר פרט לעופות:"],[16,"גמ' אינו בא לידי לא תעשה","כלומר אין לחוש שמא יאכלנו ויעבור עליו דאי נמי אכיל ליה לא עבר:"],[17,"מתני' מותר לבשל ומותר בהנאה","דאין בו משום בשר בחלב כדיליף בגמרא. ובאכילה מיהא אסור משום איסור טמאה:"],[17,"פרט לעוף וחיה ובהמה טמאה","גדי פרט לעוף שאינו בהמה. גדי פרט לחיה שאינה בהמה דאע\"ג דחיה בכלל בהמה אתא קרא יתירא ומפקיע. גדי ולא את הבהמה טמאה אבל בהמה טהורה דלאו גדי כגון פרה ורחל איתרבאי מקראי כדקתני בברייתא בגמרא:"],[18,"נאמר לא תאכלו כל נבלה ונאמר","באותו פסוק עצמו לא תבשל גדי בחלב אמו דמשמע כל שנוהג בו איסור נבלה יש בו משום בשר בחלב:"],[19,"גמ' מנהני מילי","דכל בהמה במשמע:"]],[[0,"ולימא ליה מדשמואל","אע\"ג דברייתא עדיפא בברייתא לחוד לא סגי אלא מכח מילתיה דשמואל דמייתי בהדה אבל בדשמואל לחוד סגי ומשני הוה אמינא הני מילי דמן וכאן אין שייך לאסור משום דמשרק שריק או כבולעו כך פולטו:"],[2,"מאי לאו שניהם מלוחין","אלמא לא בלע ולא גרסינן וש\"מ דצירן מותר דהא משנה שלמה היא במסכת ע\"ז (דף לה) דדג טמא צירו אסור ובסיפא דהך ברייתא נמי קתני טמא מליח וטהור תפל אסור:"],[2,"טהור מליח וטמא תפל מותר","גבי מליח כרותח לא שייך לא עילאה גבר ולא תתאה גבר ואפילו קליפה לא בעי אע\"ג דאמרינן (פסחים דף עו.) גבי עילאה ותתאה אדמיקר ליה בלע ויש ללמוד מכאן דא\"צ להגעיל דפוסי גבינות העובדי כוכבים ומותר לעשות בהם גבינות לישראל ולמולחן בתוכן דהוי כמו טהור מליח וטמא תפל דאין שייך מליחה בעץ ולא נעשה עץ רותח ע\"י מליחה ומעשים בכל יום דמלח בקערה שמשתמשין בה בשר לוקחים ממנו לתת ממנו בחלב והמחמיר תבא עליו ברכה:"],[10,"אין מחזיקין דם בבני מעיים","לאסור מטעם זה למלוח בני מעיים עם שאר בשר משום דלא טרידי לפלוט דבלעי דם כמו דגים דהכא דם משרק שריק אבל דגים רפו קרמייהו כדפי' לעיל (חולין דף קיב: ד\"ה ודגים) ואין להתיר מטעם שריקה אם היו שופכין דם על הבשר בשעת צליה דדוקא דם הנפלט נופל עם הציר ע\"י צליה או ע\"י מליחה כדאמר לעיל (חולין דף קיא.) דשריק אבל היכא דהוי הדם בעיניה לא אשכחן:"],[12,"אלא ל\"ש","ומותר בכל ענין אע\"פ שמניח השניה על אותה שנמלחה תחלה כדפרישית לעיל:"],[17,"בשר בהמה טהורה בחלב בהמה טהורה כו'","הוא הדין בשר עוף לרבנן דאסור מן התורה דדוקא ר\"ע הוא דאמר חיה ועוף אינם מן התורה ונפקא לן מדדריש לקמן את שאסור משום נבלה אסור לבשלו בחלב:"]]],[["כאן גדי עזים הא כל מקום שנאמר גדי סתם אפילו פרה ורחל במשמע","ולילף מיניה כתיב קרא אחרינא (בראשית כז, טז) ואת עורות גדיי העזים כאן גדיי העזים הא כל מקום שנאמר גדי סתם אפילו פרה ורחל במשמע","ולילף מיניה הוו להו שני כתובין הבאין כאחד וכל שני כתובים הבאים כאחד אין מלמדין","הניחא למ\"ד אין מלמדין אלא למ\"ד מלמדין מאי איכא למימר תרי מיעוטי כתיבי עזים העזים","אמר שמואל גדי לרבות את החלב גדי לרבות את המתה גדי לרבות את השליל","גדי להוציא את הדם גדי להוציא את השליא גדי להוציא את הטמאה","בחלב אמו ולא בחלב זכר בחלב אמו ולא בחלב שחוטה בחלב אמו ולא בחלב טמאה","הא תלתא גדי כתיבי ואנן שיתא דרשינן קסבר שמואל איסור חל על איסור ואיסור חלב ומתה מחד קרא נפקי דם נמי לאו גדי הוא ושליא נמי פירשא בעלמא הוא פשו להו תרי חד לרבות את השליל וחד למעוטי בהמה טמאה","וסבר שמואל איסור חל על איסור והאמר שמואל משום ר' אלעזר מנין לכהן טמא שאכל תרומה טמאה שאינו במיתה שנאמר (ויקרא כב, ט) ומתו בו כי יחללוהו פרט לזו שמחוללת ועומדת","איבעית אימא בעלמא איסור חל על איסור ושאני התם דמיעט רחמנא ומתו בו איבעית אימא בעלמא קסבר שמואל אין איסור חל על איסור ושאני הכא דרבי רחמנא גדי","ואיבעית אימא הא דידיה הא דרביה","בעא מיניה רב אחדבוי בר אמי מרב המבשל בחלב גדי שלא הניקה מהו א\"ל מדאיצטריכא לשמואל למימר בחלב אמו ולא בחלב זכר זכר הוא דלא אתי לכלל אם אבל האי כיון דבא לכלל אם אסור","אתמר המבשל חלב בחלב רבי אמי ורבי אסי חד אמר לוקה וחד אמר אינו לוקה לימא בהא קמיפלגי דמ\"ד לוקה קסבר איסור חל על איסור ומאן דאמר אינו לוקה קסבר אין איסור חל על איסור","לא דכ\"ע אין איסור חל על איסור אאכילה דכ\"ע לא פליגי דלא לקי כי פליגי אבשול מ\"ד לוקה חד איסורא הוא ומ\"ד אינו לוקה להכי אפקה רחמנא לאכילה בלשון בישול"],[[0,"כאן","פירש לך הכתוב שגדי זה מעזים היה:"],[0,"הא","אם לא פירש יש במשמע אף שאר בהמה מדאיצטריך ביה לפרושי:"],[1,"ונילף","גזירה שוה מיניה מה גדי האמור כאן עזים אף גדי האמור בבשר וחלב עזים הוא:"],[3,"תרי מיעוטי כתיבי","ה\"א דכתיב בכל חד מיעוטא הוא:"],[4,"אמר שמואל","קרא יתירא כתיב לדרשה ודרשינן להו. ולקמן פריך תלתא קראי כתיבי ושמואל שיתא דריש:"],[4,"לרבות את החלב","שאם בשל חֵלב בחָלב ואכלו עובר משום חלב ומשום בשר בחלב:"],[4,"את המתה","שאם בשל בשר נבלה בחלב ואכלו עובר משום בשר בחלב ואף על גב דבעלמא אין איסור חל על איסור וכאן הרי קדמו איסור חלב ואיסור נבלה לאיסור בשר בחלב אתא קרא ורבינהו:"],[5,"להוציא את הטמאה","בשר בהמה טמאה שבשל אפילו בחלב בהמה טהורה:"],[6,"ולא בחלב זכר","שהיה לו חלב מועט מן הדדים כגון אם נשתנה והיו לו דדים:"],[6,"ולא בחלב שחוטה","דאמו משמע הראויה להיות אם ולא משנשחטה:"],[6,"בחלב אמו","משמע שלא נאסר חלב אלא ממין שנאסר בשר וגדי הא איתרבאי ביה כל בהמה טהורה ולא טמאה הלכך חלב כגדי דהא אמו כתיב וקא ממעט חלב טמאה אפילו הבשר טהור:"],[7,"איסור חל על איסור","אני שמעתי דגרס ליה והכי פירושו איסור חל על איסור ולא אצטריך קרא לא לחלב ולא למתה:"],[7,"מחד קרא","כלומר מההוא קרא דאתא לגופיה נפקי דאם בשל חלב או בשר נבלה בחלב אף הם במשמע. וקשיא לי הא דאמרינן לקמן בפירקין (חולין דף קטז.) לר\"ע משום דאית ליה איסור חל על איסור מייתרי ליה כולהו תלתא גדי לדרשה ואמרינן חלב ומתה לא צריכי קרא והכא לשמואל נמי דאית ליה איסור חל על איסור אמרינן חלב ומתה מחד קרא נפקי ולא מייתרי כולהו אלא תרי. ונראה בעיני דלא גרסינן להאי קסבר שמואל איסור חל על איסור אלא הכי גרסינן חלב ומתה מחד קרא נפקי כו' דכולהו תלתא גדי מייתרי לדרשה דהוה ליה למיכתב לא תבשל בחלב אמו כל מי שיש לו חלב אם בהמה כיון דסופינו להביא במשמע גדי אף עגל וטלה כדאמרן לעיל ומדכתב גדי לדרשה אתי חד לחלב ומתה לאשמועינן שיהא איסור חל על איסור ואיתרבו להו תרוייהו דהא מין גדי הן והי מינייהו מפקת וחד לשליל וחד למעוטי טמאה ולקמן נמי בשמעתין אמרינן שאני הכא דרבי רחמנא גדי אלמא איסור חל על איסור לשמואל הכא מגדי נפקא ליה מריבויא והא דפריך לקמן וסבר שמואל איסור חל על איסור הא קשיא ליה דמדרבי שמואל חלב ומתה אלמא איסור חל על איסור:"],[7,"","דם ושליא לא בעיא קרא למעוטינהו דהא לאו גדי נינהו ומהיכא תיתי לאיסורא:"],[8,"ומתו בו","באוכל תרומה בטומאת גופו כתיב דהא לעיל מיניה כתיב איש איש מזרע וגו':"],[8,"פרט לזו כו'","אלמא לא אתי איסור טומאת הגוף שהוא במיתה בידי שמים וחייל אאיסור טומאת תרומה שאסורה ועומדת עליו באיסור עשה כדמפרש ביבמות בפ' הערל (יבמות דף עג:) מבשעריך תאכלנו הטמא והטהור דמשמע טמא וטהור אוכלין בקערה אחת בשר פסולי המוקדשין לאחר פדיונן דאין בהן איסור טומאה וכתיב תאכלנו לזה ולא לאחר כלומר בזה התרתי לטהור לאכול עם הטמא ואע\"פ שאוכל בשר טמא שמותר לאכול פסולי המוקדשין בין בטומאת הגוף ובין בטומאת עצמן אבל בתרומה לא התרתי לך לאכול בטומאת עצמה ולאו הבא מכלל עשה עשה. אבל אוכל תרומה בטומאת הגוף מפורש בו לא תעשה דכתיב בקדשים לא יאכל וכתיב בתריה ובא השמש וטהר ואחר יאכל וגו' ומוקמינן ליה בתרומה ביבמות (דף עד:):"],[9,"","ה\"ג בעלמא סבר שמואל איסור חל על איסור ושאני הכא דגלי רחמנא ומתו בו כי יחללוהו ואבע\"א בעלמא קסבר אין איסור חל על איסור ושאני הכא דרבי רחמנא גדי - ולשון ששמעתי קשיא לי כיון דחד לגופיה הי רבי והי מייתר והא דרשינהו:"],[10,"הא דרביה","רבי אלעזר שאמר לעיל שמואל משמו וכל היכא דקתני משום פלוני לא שמע מפיו אלא מפי אחרים שאמרו מפיו ושמואל לא ראה את רבי אלעזר מימיו דר' אלעזר בחורבן היה (גיטין דף נו.) מתלמידי רבן יוחנן בן זכאי ושמואל מדורות האחרונים היה בסוף שנותיו דרבי:"],[11,"שלא הניקה","לא ילדה מעולם ויש לה חלב כשהיא קרובה לימי לידתה מי דייקינן אמו שהיתה אמו כבר או לא:"],[12,"חד אמר לוקה","קס\"ד דאאכילה קאמר (והם) התרו בו משום בשר בחלב:"],[12,"אין איסור חל על איסור","ולא נפיק מקרא דלגופיה וקרא יתירא לית לן לרבויי דאיכא למימר חד לרבויי שליל אתא דחד איסור הוא דאיכא וחד למעוטי שליא אתא דלא ס\"ל פירשא הוא ובעי קרא למעוטי דאילו למעוטי דם וטמאה לא איצטריך דכיון דאין איסור חל על איסור מהיכא תיתי לן דליתסרו דבעי למעוטינהו:"],[13,"כי פליגי אבשול","שהרי החלב וכל שאר איסורין לא נאסרו לבשל אלא בשר בחלב הלכך גבי בשול אין כאן אלא איסור בשר בחלב:"]],[[3,"אלא למאן דאמר שני כתובים כו'","טובא כתיבי אלא כל הנהו דרבקה חשיב להו כחד וכן הנהו דיהודה כחד:"],[3,"עזים העזים","תימה דבחד מיעוטא סגי וכן לקמן בסוף פרקין (חולין דף קיז:) גבי תרומת הדשן:"],[7,"קסבר שמואל איסור חל על איסור","בחנם מוחק בקונטרס זאת הגירסא דלהכי קאמר דקסבר שמואל איסור חל על איסור דאי הוה ס\"ל בעלמא דאין איסור חל על איסור אלא הוה יליף מהכא לא הוה מפיק חלב ומתה תרוייהו מחד קרא אלא הוה מוקי קרא בדדמי ולמאי דמשני בסמוך דבעלמא קסבר אין איסור חל על איסור נפקי תרוייהו מחד קרא כדפירש בקונט' משום דתרוייהו מין גדי הם:"],[7,"דם לאו גדי הוא","ואם תאמר מכל מקום לא אמעיט אלא מגדי וי\"ל דאפילו לא הוה כתיב אלא לא תבשל בשר בחלב אמו הוה ממעטינן דם דלא איקרי בשר כדאמר בפ' כל שעה (פסחים דף כג:) כשהותרה נבלה היא וחלבה וגידה הותרה אבל דמה לא קאמר שהותרה דלאו בכלל נבלה היא:"],[9,"ושאני הכא דרבי רחמנא גדי","אי לאו גדי לא הוה ילפינן שיחול איסור בשר בחלב על איסור חלב מדאמרינן סוף פרק גיד הנשה (לעיל חולין דף קג.) יבא איסור נבלה ואיסור טרפה ויחול על איסור חלב דשאני נבלה דמטמאה וטרפה נמי משום דמחיים דכה\"ג אמרינן בזבחים פרק חטאת העוף (זבחים דף ע.) והא דאמר בפ' גיד הנשה (לעיל חולין דף קג.) דאיסור טרפה חל על איסור אבר מידי דהוה אאיסור חלב אע\"ג דאבר מן החי מטמא מ\"מ כיון דחלב בכרת ואפ\"ה חייל עליה כל שכן אאבר מן החי:"]]],[["כיון דעל אכילה לא לקי אבישול נמי לא לקי","ואיכא דאמרי אבישול כולי עלמא לא פליגי דלקי כי פליגי אאכילה מאן דאמר אינו לוקה דהא אין איסור חל על איסור ומאן דאמר לוקה להכי אפקה רחמנא לאכילה בלשון בישול כיון דאבישול לקי אאכילה נמי לקי","ואיבעית אימא מר אמר חדא ומר אמר חדא ולא פליגי","מיתיבי המבשל במי חלב פטור דם שבשלו בחלב פטור העצמות והגידים והקרנים והטלפים שבשלן בחלב פטור","הפגול והנותר והטמא שבשלן בחלב חייב","האי תנא סבר איסור חל על איסור","המבשל במי חלב פטור מסייע ליה לריש לקיש דתנן מי חלב הרי הן כחלב והמוחל הרי הוא כשמן אמר ריש לקיש לא שנו אלא להכשיר את הזרעים אבל לענין בישול בשר בחלב מי חלב אינו כחלב","תנו רבנן בחלב אמו אין לי אלא בחלב אמו בחלב פרה ורחל מנין","אמרת קל וחומר ומה אמו שלא נאסרה עמו בהרבעה נאסרה עמו בבשולו פרה ורחל שנאסרו עמו בהרבעה אינו דין שנאסרו עמו בבשולו תלמוד לומר בחלב אמו","והא למה לי קרא הא אתיא ליה","אמר רב אשי משום דאיכא למימר מעיקרא דדינא פירכא מהיכא קא מייתית לה מאמו מה לאמו שכן נאסרה עמו בשחיטה תאמר בפרה שלא נאסרה עמו בשחיטה תלמוד לומר בחלב אמו","תניא אידך בחלב אמו אין לי אלא בחלב אמו בחלב אחותו גדולה מנין","אמרת ק\"ו ומה אמו שנכנסה עמו לדיר להתעשר נאסרה עמו בבשול אחותו שלא נכנסה עמו לדיר להתעשר אינו דין שנאסרה עמו בבשול תלמוד לומר בחלב אמו","והא למה לי קרא הא אתיא ליה אמר רב אשי משום דאיכא למימר מעיקרא דדינא פירכא מהיכא קא מייתית לה מאמו מה לאמו שכן נאסרה עמו בשחיטה תאמר באחותו גדולה שלא נאסרה עמו בשחיטה תלמוד לומר בחלב אמו","אשכחן אחותו גדולה אחותו קטנה מנין אתיא מביניא","מהי תיתי תיתי מאמו מה לאמו שכן נאסרה עמו בשחיטה אחותו גדולה תוכיח מה לאחותו גדולה שלא נכנסה עמו לדיר להתעשר אמו תוכיח","וחזר הדין לא ראי זה כראי זה ולא ראי זה כראי זה הצד השוה שבהן שהוא בשר ואסור לבשל בחלב אף אני אביא אחותו קטנה שהוא בשר ואסור לבשל בחלב","אי הכי אחותו גדולה נמי תיתי מביניא","אין הכי נמי אלא בחלב אמו למה לי מבעי ליה לכדתניא בחלב אמו אין לי אלא בחלב אמו"],[[2,"ומר אמר חדא כו'","מ\"ד לוקה קאי אבישול דחדא איסורא הוא ומ\"ד אין לוקה קאי אאכילה דאם לא התרו בו משום אכילת חלב אלא משום בשר בחלב אינו לוקה דלא אתי איסור בשר בחלב וחייל אאיסור חלב:"],[3,"במי חלב","מישג\"א בלע\"ז:"],[4,"הפגול והנותר","אלמא אע\"ג דאסירי וקיימי אתי איסור בשר בחלב וחייל עלייהו והוא הדין נמי אם בשל חלב בחלב אלמא מרבויא דגדי נפקא לן דחייל על כל איסורין:"],[5,"האי תנא","נמי סבר בכל איסורין דאיסור חל על איסור ואינהו סברי לה כמ\"ד אין איסור חל על איסור ותנאי טובא איפליגו בה:"],[6,"הרי הן כחלב","להכשיר את הזרעים וחלב נקרא משקה דכתיב (שופטים ד) ותפתח את נאד החלב ותשקהו:"],[6,"והמוחל","משקה הזב מן הזיתים:"],[6,"הרי הוא כשמן","ושמן איקרי משקה דכתיב (ישעיהו כה) משתה שמנים:"],[7,"אין לי אלא בחלב אמו","כלומר עז:"],[8,"ת\"ל","מקרא שני:"],[8,"בחלב אמו","דמייתר לרבויי כל חלב בהמה טהורה דהאי תנא לא מצריך ליה לכדשמואל דחלב זכר וחלב שחוטה וחלב טמאה מחד קרא דלגופי' נפקי דהא אמו כתיב ולא שחוטה ולא זכר ולא טמאה דהא גדי כתיב ובטהורה משתעי כדאמרן להוציא את הטמאה ועל כרחיך אמו נמי טהורה דאי אמו טמאה לא הוי איהו טהור הלכך להכי לא אתא וגדי משמע ליה גדי דווקא ובשר חיה ושאר בהמות מגדי יתירא נפקי לאיסורא דאי סבירא ליה גדי הכל במשמע אפילו עגל וטלה למה ליה לרבויי חלב פרה ורחל והא אמו כתיב ולקמן (חולין דף קטז.) דמשמע לן יתורא דגדי גדי לר\"ע למעוטי חיה ועוף הני מילי למאן דמשמע ליה גדי ואפילו עגל וטלה אתי קרא יתירא למעוטי אבל למאן דמשמע ליה גדי דווקא קראי יתירי לרבויי אתו דאי למעוטי לא איצטריך וחד למעוטי טמאה ולשליל לא איצטריך קרא דממשמעות יליף ליה כדאשכחנא גבי ר\"ע לקמן דאמר שליל גדי מעליא:"],[9,"הא אתיא ליה","שפיר בק\"ו:"],[10,"מעיקרא דדינא","מתחלת הדין דקתני מה אמו שלא נאסרה עמו בהרבעה נאסרה עמו בבשול זהו תחלתו של ק\"ו ויש להקשות מה לאמו שכן נאסרה לישחט עמו ביום אחד. ולהכי נקט מעיקרא דדינא פירכא משום דפעמים מקשה על סוף הדין כגון דקתני סיפא פרה ורחל שנאסרו עמו בהרבעה אינו דין שנאסרו עמו בבשול זהו סוף הדין ואם היה מקשה ואומר בהמה טמאה תוכיח שנאסרה עמו בהרבעה ולא נאסרה עמו בבישול אף אתה אל תתמה על פרה ורחל כו' זו היא פירכא על סוף הדין:"],[11,"חלב אחותו גדולה מנין","אני שמעתי דהיינו פרה שהיא מין בהמה כמותה אבל מין גדול הוא ומהאי קרא גופיה דריש ותנא אחרינא הוא ולישניה הוא דשני ועוד דלא נפק ליה פרה ורחל מיתורא דחד קרא אלא פרה לחודה דחלוקה מן הגדי בשני חילוקין חדא דנאסרה עמו בהרבעה וחדא דאין נכנסת עמו לדיר להתעשר אבל רחל שנכנסת עמו לדיר להתעשר דהא מעשר בקר וצאן כתיב (ויקרא כז) וכל צאן במשמע לא נפקא ליה מיניה שתאסר עמו בבישול הלכך יליף ברישא פרה והדר אתיא ליה רחל בהצד השוה כדלקמן. בקר אינו נכנס עם הצאן להתעשר בפרק בתרא דבכורות (דף נג.):"],[12,"ומה אמו","שאינה חלוקה ממנו לענין מעשר דהא מינה היא ואע\"פ שכבר ילדה עדיין היא ראויה ליכנס עמו לדיר להתעשר דגדייה יולדת בתוך שנתה ונכנסת עם בנה לדיר להתעשר כשעדיין לא נכנסה להתעשר כדתניא בבכורות (דף כ:) גדייה שילדה שלש בנות וכל בנותיה ילדו שלש [שלש] כולן נכנסות לדיר להתעשר ואפ\"ה חלקה הכתוב ממנו לאוסרה עמו בבישול:"],[13,"אחותו גדולה","פרה שאינה נכנסת כו':"],[13,"תלמוד לומר בחלב אמו","קרא יתירא לרבויי כל חלב וממילא איתרבאי פרה דאשכחן דנחלקה ממנו לענין מעשר תיחלק ממנו לבישול:"],[14,"אחותו קטנה","רחל:"],[14,"מביניא","מאמו ומאחותו גדולה:"],[15,"תיתי מאמו","דמה אמו שלא נאסרה עמו בהרבעה נאסרה עמו בבישול אחותו קטנה שנאסרה עמו בהרבעה אינו דין שנאסרה עמו בבישול:"],[15,"","מה לאמו כו':"],[17,"אי הכי אחותו גדולה נמי תיתי מביניא","מאמו ומאחותו קטנה ומחצי הדין שהרי אין להשיב עליו והכי דנינן מה אמו שנכנסת עמו לדיר נאסרה עמו בבשול אחותו גדולה לא כל שכן וכי פרכת מה לאמו שכן נאסרה עמו בשחיטה תאמר באחותו גדולה אחותו קטנה תוכיח ותו ליכא למיפרך מה לאחותו קטנה שכן לא נכנסה כו' אלמא מפלגי דינא נפקא לן כך שמעתי וקשיא לי היכי נימא אחותו קטנה תוכיח הא אכתי לא קיימא לן אחותו קטנה לאיסורא. ואני שמעתי דהכי פריך מאי חזית דאחותו גדולה נפקא לן מקרא וקטנה מביניא תיפוק ליה אחותו קטנה מרבויא דקרא וגדולה מביניא וקשיא לי חדא דמסתברא קרא כי רבי לאחותו גדולה לאיסורא רבי שנאסרה עמו במעשר אבל קטנה לא ועוד מאי קא מותיב לקמיה בחלב אמו למאי אתא טובא איצטריך לאחותו קטנה. ורואה אני את דברי ר' יוסף טוב עלם ז\"ל שראיתי תשובת כתב ידו דאחותו גדולה ואחותו קטנה אמינו ממש קאמר שהן מין גדי כמותו וגדולה זו היא זקנה שכבר נתעשרה וקטנה זו היא גדייה שלא נתעשרה עדיין והאי תנא היינו תנא גופיה דלעיל דאתיא ליה פרה ורחל מחד מקראי יתירי והשתא קא דריש לאידך וה\"ק אחותו גדולה שנתעשרה כבר מנין וע\"כ נקט גדולה משום דסופו יליף לה מרבויא וקטנה לא מיתרביא ליה מיניה משום דמסתברא כי רבי קרא לאיסורא גדולה רבי דנאסרה עמו במעשר דאילו מקרא יתירא קמא לא מצי לרבויי דאיכא למימר כי רבי לאיסורא לא רבי אלא פרה ורחל דאסורין עמו בהרבעה אבל אחותו לא ולהכי אשמעינן קרא אחרינא לאחותו גדולה וקטנה אתיא מביניא:"],[17,"אי הכי","דקטנה אתיא לה מביניא:"],[17,"אחותו גדולה נמי","לא תיבעי קרא ותיתי מביניא דאמו ופרה ודרוש הכי מה אמו שנכנסה עמו לדיר נאסרה עמו בבשול אחותו גדולה לא כ\"ש מה לאמו שכן נאסרה עמו בשחיטה פרה תוכיח מה לפרה שכן נאסרה עמו בהרבעה ובמעשר אמו תוכיח שמותרת עמו בהרבעה ובמעשר וחזר הדין הצד השוה שבהן שהם חלב כו' ואתיא מביניא בין אחותו גדולה ובין קטנה:"],[18,"אלא","קרא שלישי למאי אתא קמא לגופיה תניינא לפרה ורחל ואידך למאי:"]],[[0,"כיון דעל אכילה לא לקי","תימה אימא איפכא כדאמר בסמוך כיון דאבשול לקי אאכילה נמי לקי:"],[3,"המבשל במי חלב פטור","איסורא מיהא איכא דהא כותח מנסיובי דחלבא עבדי ליה כדאמר בריש אלו עוברין (פסחים דף מב.) ואמרינן לעיל (חולין דף קיא:) דאסור לאכול בשר בכותח:"],[7,"בחלב פרה ורחל מנין","לא איצטריך ליה אלא לרבות בשאין מינו כגון פרה בחלב גדי או גדי בחלב פרה אבל פרה בחלב עצמה הא דרשינן לעיל (חולין דף קיג:) כל מקום שנאמר גדי אפילו פרה ורחל במשמע ובחנם דחק בקונטרס:"],[8,"פרה ורחל שנאסרו עמה בהרבעה","וא\"ת חיה ועוף יוכיחו לר' עקיבא או עוף לחודיה לר' יוסי הגלילי דנאסרו בהרבעה עם שאינו מינו כדאמרינן בסוף שור שנגח את הפרה (ב\"ק דף נה.) ולא נאסרו בבשול וי\"ל דעדיפא פריך:"],[10,"מה לאמו שכן נאסרה עמו בשחיטה","תימה לרבנן חיה תוכיח דאין אותו ואת בנו נוהג בחיה:"],[10,"תלמוד לומר בחלב אמו","עוד דריש מינה בסמוך היא עצמה בחלבה אע\"ג דשמואל דריש ליה למלתייהו לעיל (חולין דף קיג:) הכא דריש מבחלב דתרי מינייהו מייתרי דהוה מצי למכתב באמו ואנא ידענא דבחלב אמו קאמר כיון דבחד מינייהו הוה כתיבא בחלב אמו ורבי יוסי הגלילי דממעט עוף שאין לו חלב אם מוי\"ו דאמו קא דריש:"]]],[["היא עצמה בחלבה מנין אמרת ק\"ו ומה במקום שלא נאסר פרי עם פרי בשחיטה נאסר פרי עם האם בשחיטה מקום שנאסר פרי עם פרי בבשול אינו דין שנאסר פרי עם האם בבשול ת\"ל בחלב אמו","הא למה לי קרא הא אתיא לה אמר רב אחדבוי בר אמי משום דאיכא למימר סוס בן סוסיא אחי פרדה יוכיח שאסור פרי עם פרי ומותר פרי עם האם","התם זרע האב הוא דקא גרים","דהא פרד בן סוסיא אחי פרדה יוכיח שמותר פרי עם פרי ואסור פרי עם האם","אלא אמר מר בריה דרבינא משום דאיכא למימר עבד בן שפחה אחי משוחררת יוכיח שאסור פרי עם פרי ומותר פרי עם האם","התם גט שיחרור הוא דקא גרים דהא עבד בן משוחררת אחי שפחה יוכיח שמותר פרי עם פרי ואסור פרי עם האם","אלא אמר רב אידי בר אבין משום דאיכא למימר כלאי זרעים יוכיחו שאסור פרי עם פרי ומותר פרי עם האם כלום נאסר פרי עם פרי אלא ע\"י האם דהא חיטי ושערי בכדא ולא מיתסרו","אלא אמר רב אשי משום דאיכא למימר מה לפרי עם פרי שכן שני גופים תאמר בפרי עם האם שכן גוף אחד משום הכי איצטריך קרא","אמר רב אשי מנין לבשר בחלב שאסור באכילה שנאמר (דברים יד, ג) לא תאכל כל תועבה כל שתעבתי לך הרי הוא בבל תאכל","ואין לי אלא באכילה בהנאה מנין כדרבי אבהו דאמר ר' אבהו א\"ר אלעזר כל מקום שנאמר לא יאכל לא תאכל לא תאכלו אחד איסור אכילה ואחד איסור הנאה במשמע עד שיפרוט לך הכתוב כדרך שפרט לך בנבלה לגר בנתינה ולעובד כוכבים במכירה","דתניא (דברים יד, כא) לא תאכלו כל נבלה לגר אשר בשעריך תתננה ואכלה או מכור לנכרי אין לי אלא לגר בנתינה ולעובד כוכבים במכירה לגר במכירה מנין ת\"ל לגר תתננה או מכור","לעובד כוכבים בנתינה מנין ת\"ל תתננה או מכור לנכרי נמצא אחד גר ואחד עובד כוכבים בין במכירה בין בנתינה דברי ר\"מ רבי יהודה אומר דברים ככתבן לגר בנתינה ולעובד כוכבים במכירה","מ\"ט דרבי יהודה אי ס\"ד כדקאמר ר\"מ לכתוב רחמנא לא תאכלו כל נבלה לגר אשר בשעריך תתננה ואכלה ומכור או למה לי ש\"מ לדברים ככתבן הוא דאתא לגר בנתינה ולעובד כוכבים במכירה","ור\"מ אמר לך האי או להקדים נתינה דגר למכירה דעובד כוכבים ורבי יהודה להקדים נתינה דגר למכירה דעובד כוכבים לא צריך קרא סברא הוא זה אתה מצווה להחיותו וזה אי אתה מצווה להחיותו:","(סימן שבת חורש וכלאי זרעים אותו ואת בנו ושילוח הקן):","אלא מעתה"],[[0,"היא עצמה בחלבה","שיצא ממנה בעודה חיה מנין כו'. ואף מדרשה זו נראין הדברים דלאחותו ממש מצריך תלמודא או מקרא או מביניא דהא אפילו להיא עצמה מצרכינן תלמודא אלמא לא נפקא לן מקרא דלגופיה כל מין גדי אלא אמו דווקא אבל היא עצמה לא וה\"ה אחותו גדולה וקטנה:"],[0,"פרי עם פרי בשחיטה","ששוחטין שני בני פרה אחת ביום אחד:"],[0,"פרי עם פרי בבישול","גדי עם החלב:"],[1,"אמר רב אחדבוי כו'","הכא לא אמרי מעיקרא דדינא פירכא כדלעיל משום דמקשי על סוף הדין:"],[1,"אחי פרדה","שילדתה הסוסיא מן החמור והיה לה בן אחר מן הסוס הרי בן מותר עם אמו ואסור עם אחותו:"],[2,"התם זרע אב קא גרים","ואיסורא לאו משום פרי עם פרי הוא אלא משום פרי עם שאינו פרי כלומר משום צד אביהן שהוא חלוק אבל גדי בחלב אמו שניהם על שם אמן קראן הכתוב ואפ\"ה אסרינהו. ותדע דטעמא משום חלוק האב הוא דהא זימנין דהוי איסור איפכא דפרי עם האם אסור ופרי עם פרי מותר:"],[3,"דהא פרד בן סוסיא","שילדתו מן החמור והוא אחי פרדה שהיתה לה לסוסיא זו עוד בת אחת מן החמור:"],[4,"עבד בן שפחה","מותר במין אמו ואסור בבת חורין:"],[5,"ופרכינן התם גט שחרור קא גרים","ולאו משום פרי עם פרי הוא דהא זימנין דהוי איפכא ומיתסר:"],[6,"כלאי זרעים","חטין עם עדשין שאסור לזרוע זה עם זה:"],[6,"ומותר","לזרוע כל אחד עם אמו עם הקרקע:"],[6,"ופרכינן התם פרי עם פרי מי מיתסר","כלום נאסר פרי עם פרי אלא בזריעה דהיינו ע\"י האם:"],[6,"הא חטי ושערי בכדא","שהניח בכד להצניע שם:"],[8,"כל שתיעבתי לך","כל שאסרתי לך לתעבו ולהתרחק ממנו:"],[8,"הרי הוא בבל תאכל","עולמית בכל ענינין שהוא בין שבא בעבירה ובין שלא בא בעבירה כגון ע\"י קטן או ע\"י עובד כוכבים מאחר שתיעבתי לך אסור והאי הרי תיעבתיו לך להתרחק מבשולו שלא לבשלם יחד:"],[9,"עד שיפרוט לך הכתוב שהוא מותר בהנאה כדרך שפרט לך בנבלה","שאע\"פ שלא כתב לך אלא לא תאכל הוצרך לפרש בה היתר הנאה הא כל מקום שלא פירש לך בה היתר הנאה הוי במשמע איסור הנאה מלא תאכל: מדכתיב מכירה ונתינה באמצע שמע מינה אחד מכירה ואחד נתינה קיימי בין אגר ובין אעובד כוכבים דאי דוקא כתיב הוה ליה למכתב הכי תתננה לגר ותמכרנה לעובד כוכבים:"]],[[8,"(לעיל) כל שתיעבתי לך הרי הוא בבל תאכל","וא\"ת היאך אנו אוכלין אילים אפילו סירסן עובד כוכבים מ\"ש מבשר בחלב וי\"ל מדאסר רחמנא מעוך וכתות לגבוה מכלל דלהדיוט שרי וא\"ת צורם אוזן בכור ליתסר אפילו צרמו עובד כוכבים וי\"ל דשרי רחמנא קדשים שהוממו כצבי ואיל א\"כ אינו דבר מתועב:"],[9,"עד שיפרוט לך הכתוב כדרך שפרט לך בנבלה","בפרק כל שעה (פסחים דף כא:) אמרינן דלא מתוקמא דרבי אבהו אלא כר\"מ דלרבי יהודה איצטריך לדברים ככתבן ולר' יהודה נפקא לן מלכלב תשליכון אותו אותו אתה משליך לכלב ואי אתה משליך לכלב כל איסורין שבתורה וא\"ת לר\"מ נמי היכי יליף מיניה דלא תאכלו משמע איסור הנאה מדפרט היתר הא איצטריך קרא להקדים נתינת גר למכירת עובד כוכבים וי\"ל דמסברא בלא שום קרא הוה ידעינן להקדים אלא השתא דכתיב נתינה ומכירה ללמד בעלמא איסור הנאה אי לאו דכתיב או להקדים ה\"א דאתא קרא להשוותם וא\"ת ולא ליכתוב אלא חד מינייהו או מכירה דעובד כוכבים או נתינה דגר ולא יצטרך או להקדים כיון דידעי ליה מסברא וי\"ל דה\"א דאתי קרא למעוטי נתינה דעובד כוכבים וא\"ת ויכתוב נתינה דעובד כוכבים וי\"ל דה\"א דאתי למעוטי נתינה דגר דלא ליספו ליה אע\"פ דלא קבל עליו אלא לאכול נבלות כדי שימהר להתגייר ודוקא נבלה בא\"י שאין עובדי כוכבים מצויין שם ואם בא למוכרה לעובד כוכבים צריך ליתנה בדמים מועטין נתינת גר קודמת אבל פשיטא שאם יש חפץ לאדם למכור קודם ימכרנו לעובד כוכבים ממה שיתננו אפילו לישראל חברו:"],[9,"כדרך שפרט לך בנבלה","לא גרס לגר בנתינה ולעובד כוכבים במכירה כדפירש בקונט' בפסחים (שם) דא\"כ הוה משמע דאיירי אליבא דר' יהודה דאמר דברים ככתבן ודר' אבהו לא מתוקמא אלא כר\"מ כדפרישית ואי גרס ליה יש לפרש דלישנא דקרא בעלמא נקט ולא משום דלהוו דברים ככתבן אי נמי נקט הכי משום דנתינת הגר קודמת:"],[11,"רבי יהודה אומר דברים ככתבן","ואסור ליתן לכנעני עובד כוכבים מתנת חנם ועל זה מביאה בפ\"ק דמסכת ע\"ז (דף כ.) וא\"ת והתנן (לעיל חולין דף צג:) שולח אדם לעובד כוכבים ירך שגיד הנשה בתוכה ושולח משמע בחנם ובפרק כל שעה (פסחים דף כב.) משמע דאתיא אפילו כר' יהודה ויש לומר דתניא בתוספתא אם היה שכנו מותר מפני שהוא כמוכרו לו:"],[12,"או למה לי ש\"מ לדברים ככתבן","משמע דאי לאו או הוה אמינא תתננה ומכור אגר דלעיל ואעובד כוכבים והכי נמי אמרינן בריש איזהו נשך (ב\"מ דף סא.) ובמרבית קאי אכסף ואאוכל דבתריה ותימה דבפרק קמא דקדושין (דף לב:) איכא פלוגתא דתנאי גבי קימה והדור דשיבה וזקן דאיכא למ\"ד דלא קיימי אתרוייהו משום דכתיב מפני שיבה תקום והדרת פני זקן ויש לומר משום דאין לשון מפני נופל על והדרת ולא לשון פני נופל על תקום ואם תאמר דבפרק הוציאו לו (יומא נב.) קאמר איסי בן יהודה חמש פסוקים אין להם הכרע שאת מחר ארור משוקדים וקם ואמאי לא קאי אלעיל ולתחת ועוד דאיסי גופיה סבר בקדושין דקימה והדור קיימי אתרוייהו ויש לומר דהכא ובאיזהו נשך (ב\"מ סא.) ופרק קמא דקדושין (דף לב:) דאיכא תרי מילי קאי חד ודאי אלעיל וחד ודאי אלתחת אית לן למימר דתרוייהו קיימי אהכא והכא אבל התם אית לן למימר דקאי אחד דוכתא או אלעיל או אלתחת ובזבחים בפ\"ב (דף כד.) דפליגי תנאי גבי ולקח הכהן מדם החטאת באצבעו ונתן דאיכא דמוקי אצבע אשלפניו אולקח ולא אנתינה של אחריו ואיכא דמוקי לה אנתינה של אחריו ולא אלקיחה דלפניו ואיכא דמוקי לה אתרוייהו היינו טעמא דפשטיה דקרא משמע טפי אלקיחה דלקמיה ואשכחן בדוכתא אחרינא ולקחת מדם הפר ונתת על קרנות המזבח באצבעך דהוי אצבע אנתינה והשתא פליגי דחד מוקי אלקיחה כמשמעותיה דקרא וחד מוקי לה אנתינה דיליף סתום מן המפורש ולא בעי נמי לאוקומי אלקיחה דלא שייך לקיחה אאצבע אלא בדעבד אוזן לשפת המזרק והך דמוקי אתרוייהו אלקיחה משום משמעותא ואנתינה דיליף נמי מן המפורש וצריך עיון כל היכא דאמר מקרא נדרש לפניו ולאחריו אם נוכל ליישב שלא יקשה למה ידרשנו לפניו ולאחריו יותר מאותם שאין להם הכרע:"]]],[["מעשה שבת ליתסרו דהא תיעבתי לך הוא","אמר קרא (שמות לא, יד) כי קדש היא לכם היא קדש ואין מעשיה קדש","חורש בשור ובחמור וחוסם פי פרה ודש בה ליתסרו דהא תיעבתי לך הוא","השתא ומה שבת דחמירא מעשיה מותרים הני לא כל שכן","כלאי זרעים ליתסרו דהא תיעבתי לך הוא מדגלי רחמנא גבי כלאי הכרם (דברים כב, ט) פן תקדש פן תוקד אש מכלל דכלאי זרעים שרו","ואימא כלאי כרם אסורין בין באכילה בין בהנאה כלאי זרעים באכילה אסירי בהנאה שרו איתקוש לכלאי בהמה דכתיב (ויקרא יט, יט) בהמתך לא תרביע כלאים שדך לא תזרע כלאים מה בהמתך היוצא ממנה מותרת אף שדך היוצא ממנו מותר","וכלאי בהמה גופייהו מנא לן מדאסר רחמנא כלאים לגבוה מכלל דלהדיוט שרי","אותו ואת בנו ליתסר מדאסר רחמנא מחוסר זמן לגבוה מכלל דלהדיוט שרי","שילוח הקן ליתסר לא אמרה תורה שלח לתקלה","אמר ריש לקיש מנין לבשר בחלב שאסור ת\"ל (שמות יב, ט) אל תאכלו ממנו נא ובשל מבושל שאין תלמוד לומר מבושל מה תלמוד לומר מבושל לומר לך יש לך בשול אחר שהוא כזה ואי זה זה בשר בחלב","א\"ל רבי יוחנן"],[[0,"מעשה שבת","כגון המבשל בשבת ליתסרו באכילה לכל ישראל דהא הזהרתיך לתעבו ולהתרחק ממנו ואנן תנן במזיד לא יאכל הוא משום קנס אבל אחרים אוכלין בפ\"ק (לעיל חולין טו.):"],[0,"ליתסרו","הזרעים והדישה דהא הרחקתיך מהם כל הנך דקאמר ליתסרו באכילה ובהנאה קאמר דליתסרו:"],[3,"הני לא כ\"ש","אבל בבשר בחלב לא אמרינן האי ק\"ו דהא כתיב לא תאכל כל שתיעבתי לך ומסתברא דאיסורא דקרא עליה קאמר דהא אכיל תועבה גופה אבל האי לא אכיל החרישה עצמה אלא הבא ממנה והחוסם והדש נמי לאו חסימה גופה קאכיל אלא מעשה הבא על ידה וילפינן משבת דאין הבא מכחה קדש:"],[4,"כלאי זרעים","הן עצמן תועבה וליתסרו:"],[5,"כלאים","אסירי לגבוה דתניא שור או כשב או עז פרט לכלאים בגמרא דהשוחט (לעיל חולין לח:):"],[7,"אותו ואת בנו","אינו אלא מחוסר זמן שהיום אסור ומחר מותר:"],[8,"שילוח הקן ליתסר","כגון נטל את האם מעל הבנים ובא לפנינו וחייבנוהו לשלח כדתנן לקמן (חולין דף קמא.) משלח ואינו לוקה תאסר לאכילה עולמית דהא נעבדה בה עבירה:"],[8,"לא אמרה תורה שלח לתקלה","וכאן הרי אמרה שלח דכתיב (דברים כב) לא תקח האם והדר שלח תשלח דאם לקחת אותה חזור ושלחה ואם היתה אסורה לא היה אומר לך שלחנה ויכשלו בה בני אדם וה\"ה דמצי למימר נמי בכל הני מה שבת דחמירא כו' ומיהו מידי דמשכח פירוקא מגופיה לא יליף מאחריני לישנא אחרינא שילוח הקן ליתסר כל שילוח הקן ליתסר האם לעולם ואפילו שלחה דהא כל שתיעבתי לך הרי הוא לך לעולם בבל תאכל והרי אסרתיה לך באותה שעה וזה נראה לי עיקר דהא לא קאמר רב אשי דכל דבר שנעבדה בו עבירה ומתחלה הוא מותר אסור דאם כן החורש בשור וחמור והמרביע כלאים והחוסם יאסרו הבהמות ואנן לא פרכינן מינייהו מידי אלא מן היוצא מהן:"],[9,"שהוא כזה","שאסור באכילה כזה:"]],[[1,"היא קדש ואין מעשיה קדש","וא\"ת ואימא למשרי בהנאה אבל באכילה אסירי כדפריך בסמוך גבי זרעים וי\"ל דהיתר הנאה נפקא לן מלכם כדאמר במרובה (ב\"ק דף עא.) ובאלו נערות (כתובות לד.) אפילו לרבי יוחנן הסנדלר דאוסר במבשל בשבת וקצת תימה לרבי יוחנן למה ליה למימר מקדש דמעשה שבת אסירי תיפוק ליה מכל שתיעבתי והיתר הנאה מלכם:"],[2,"חורש בשור וחמור וחוסם פי פרה ודש בה ליתסרו","פי' השור והחמור ויש ספרים דגרסי השתא לגבוה שרו להדיוט מבעיא ולגבוה מנא לן דשרו דכתיב (ויקרא כג) ומיד בן נכר לא תקריבו את לחם אלהיכם מכל אלה מכל אלה אי אתה מקריב פי' מעוך וכתות ונתוק וכרות אבל אתה מקריב קדשים שנעבדה בהן עבירה וא\"ת הזרעים והדישה ליתסרו דמקרא דאלה על כרחך לא מישתרו לגבוה אלא בעלי חיים דאי כל מילי א\"כ כל מעשה שבת נמי תיפוק ליה מאלה ול\"ל היא קדש וי\"ל דלא שייך מכל שתיעבתי לך הזרעים והדישה דלא תחסום אסור משום בהמה וכן לא תחרוש ולא משום חרישה וזריעה דאפילו בלאו חרישה אסור להנהיג בשור וחמור וא\"ת ובסמוך בסוגיין פריך שילוח הקן ליתסר תיפוק ליה דאף לגבוה שרי מהאי קרא דאלה וי\"ל דקרא דאלה בבהמה כתיב ולא בעופות ועוף מבהמה לא אתי משום דאין גדלות וקטנות פוסל בבהמה כמו בתורים ובני יונה וא\"ת למה לי קרא דאלה הא מדאיצטריך קרא בפרק כל האסורין (תמורה כח:) מן הבהמה להוציא הרובע והנרבע מכלל דשאר קדשים שנעבדה בהן עבירה לא אסירי מכל שתיעבתי וכי תימא דלא אתא מן הבהמה אלא לאשמעינן מכלל דלהדיוט שרי ולא מיתסר מכל שתיעבתי מ\"מ נילף חורש בשור וחמור וחוסם פי פרה בק\"ו מרובע ונרבע דבמיתה ושרי להדיוט וי\"ל דאי לאו אלה הוה אסרינן להו מדכתיב מן הבקר כי היכי דממעטינן מיניה נעבד ואית ספרים דגרסי ומה שבת דחמירא אמרת היא קדש ואין מעשיה קדש הני לא כל שכן וכן גריס בקונטרס ופי' דבבשר וחלב לא אמרינן האי קושיא דמסתברא דכל שתיעבתי עליה רמינן דקא אכיל תועבה גופה אבל האי לא אכיל החרישה עצמה וכן חוסם לאו חסימה גופה קאכיל אלא הבא על ידה ממנה וילפינן משבת דאין הבא מכחה קודש וקשה דלמה לא יחשב בישול של שבת תועבה גופה כמו בישול של בשר בחלב ונראה דהיינו טעמא משום דבבשר בחלב הבישול ניכר אבל מעשה שבת אין ניכר שנעשה בשבת ואותו ואת בנו ושילוח הקן דפריך ליה מינייהו צ\"ל דניכר בהם האיסור יותר ממה שניכר בחורש בשור וחמור וחוסם פי פרה ודש בה:"],[4,"פן תקדש פן תוקד אש","וא\"ת והא איצטריך לאשמועינן דמצותו בשריפה הא כלאי זרעים אין מצותן בשריפה אבל בהנאה אסירי וי\"ל דבלאו הכי פריך שפיר א\"נ ליכתוב פן תשרף ומדכתיב תקדש משמע דאתא לאסור הנאה כקדש:"],[5,"כלאי זרעים באכילה אסירי בהנאה שרו","וא\"ת לקמן (חולין דף קטז.) גבי מעביר עציץ דלא מיתסר כי אם בהוסיף מאתים אבל לא הוסיף שרי באכילה מדכתיב תרי קראי המלאה והזרע נימא ה\"מ בהנאה אבל באכילה אסירי מכל שתעבתי לך כדבעי למימר הכא וי\"ל דמאחר דאשכחן כלאי זרעים דשרו באכילה דאיתקוש לבהמה וכלאי הכרם אסורין אם כן סברא הוא בלא הוסיף כיון דלא מיתסר לגמרי כשאר כל כלאי הכרם יש לו להתיר אף באכילה כמו בכלאי זרעים:"],[6,"מדאסר רחמנא כלאים לגבוה מכלל דלהדיוט שרי","וא\"ת ודלמא איצטריך קרא להקדישה ואח\"כ הרביעה כלאים כדאמר פרק כל האסורים (תמורה כט.) גבי טרפה דאיצטריך לאסור לגבוה היכא דהקדישה ואח\"כ נטרפה וי\"ל דמ\"מ הכא אי אתינן למיסר של הדיוט מכל שתעבתי לך כ\"ש דלגבוה אסירא מכל שתעבתי לך אע\"ג דהוקדש תחלה וכן י\"ל גבי אותו ואת בנו בסמוך אי נמי מדגלי לך בטרפה שאין חילוק ה\"ה בכלאים ומחוסר זמן:"],[7,"מדאסר רחמנא מחוסר זמן לגבוה","דכתיב ומיום השמיני והלאה ירצה דאמר לעיל בפרק אותו ואת בנו (חולין דף פא.) נתקו הכתוב ללאו דאותו ואת בנו לעשה:"],[8,"לא אמרה תורה שלח לתקלה","תימה דשרינן הכא מהא סברא בלא שום קרא ובסוף פרק שני דקדושין (דף נז.) גבי צפרי מצורע דריש כל צפור טהורה תאכלו לרבות המשולחת וזאת אשר לא תאכלו לרבות השחוטה ופריך ואיפוך אנא ומשני רבא לא אמרה תורה שלח לתקלה והשתא למה לן קרא דכל צפור טהורה תאכלו להתיר דהכא שרינן מהאי טעמא שילוח הקן וי\"ל דהתם כיון דכתיב לא תאכלו לאסור האחת הוה אמינא דאידך נמי אסירא משום דאתקוש צפרים אהדדי ולא הוה שרינן מטעם דלא אמרה תורה שלח לתקלה אי לאו דאיכא עדיין יתורא דכל צפור טהורה תאכלו ולא דמי לכל שתעבתי לך דהכא דלא כתיב בהדיא אשלוח הקן ומהך סברא איכא לאוקומי במילי אחריני:"],[9,"שאין ת\"ל מבושל","לית ליה לר\"ל הנך דרשות דדרשינן בסוף פרק כל שעה (פסחים דף מא.) מינה צלאו ואח\"כ בשלו או לשאר משקים כו':"]]],[["כעורה זו ששנה רבי לא תאכלנו בבשר בחלב הכתוב מדבר","אתה אומר בבשר בחלב הכתוב מדבר או אינו אלא באחד מכל האיסורין שבתורה אמרת צא ולמד מי\"ג מדות שהתורה נדרשת בהן דבר הלמד מענינו במה הכתוב מדבר בשני מינין אף כאן בשני מינין","אי מההיא הוה אמינא הני מילי באכילה אבל בהנאה לא קמ\"ל","ורבי בהנאה מנא ליה נפקא ליה מהכא נאמר כאן (דברים יד, ב) כי עם קדוש אתה לה' ונאמר להלן (דברים כג, יח) ולא יהיה קדש בבני ישראל מה להלן בהנאה אף כאן בהנאה","דבי רבי אליעזר תנא (דברים יד, כא) לא תאכלו כל נבלה [וגו'] אמרה תורה כשתמכרנה לא תבשלנה ותמכרנה","דבי רבי ישמעאל תנא (שמות כג, יט) לא תבשל גדי בחלב אמו ג' פעמים אחד לאיסור אכילה ואחד לאיסור הנאה ואחד לאיסור בשול","תניא איסי בן יהודה אומר מנין לבשר בחלב שאסור נאמר כאן (דברים יד, ב) כי עם קדוש אתה ונאמר להלן (שמות כב, ל) ואנשי קדש תהיון לי ובשר בשדה טרפה לא תאכלו מה להלן אסור אף כאן אסור","ואין לי אלא באכילה בהנאה מנין אמרת ק\"ו ומה ערלה שלא נעבדה בה עבירה אסורה בהנאה בשר בחלב שנעבדה בו עבירה אינו דין שאסור בהנאה","מה לערלה שכן לא היתה לה שעת הכושר","חמץ בפסח יוכיח שהיתה לו שעת הכושר ואסור בהנאה מה לחמץ בפסח שכן ענוש כרת","כלאי הכרם יוכיחו שאין ענוש כרת ואסור בהנאה","למה לי גז\"ש לייתי כולה בק\"ו מערלה ומה ערלה שלא נעבדה בה עבירה אסורה בין באכילה בין בהנאה בשר בחלב שנעבדה בו עבירה אינו דין שאסור בין באכילה בין בהנאה","משום דאיכא למימר חורש בשור ובחמור וחוסם פי פרה ודש בה יוכיח שנעבדה בהם עבירה ושרו","למה לי למימר כלאי הכרם יוכיחו לימא ערלה תוכיח וליהדר דינא וליתי במה הצד","אמר רב אשי משום דאיכא למימר נבלה תוכיח שאסורה באכילה ומותרת בהנאה","אמר ליה רב מרדכי לרב אשי הכי אמרינן משמיה דריש לקיש כל מה הצד מגופו פרכינן מעלמא לא פרכינן","אי הכי תיתי במה הצד משום דאיכא למיפרך מה להצד השוה שבהן שכן גדולי קרקע","אי הכי השתא נמי איכא למיפרך מה לכלאי הכרם שכן גדולי קרקע","א\"ל רב מרדכי לרב אשי הכי אמרינן משמיה דר\"ל כל מה הצד פרכינן כל דהו לא אם אמרת (חדא מחדא) קל וחומר פרכינן כל דהו לא פרכינן","וליפרוך לכולהו מה לכולהו שכן גדולי קרקע","אלא אמר ליה רב מרדכי לרב אשי הכי אמרינן משמיה דר\"ל"],[[0,"כעורה זו ששנה רבי","כלומר וכי מכוערת היא בעיניך משנה זו ששנה רבי ולמדה לבשר בחלב ממקרא הזה:"],[0,"לא תאכלנו","יתירא דכתיב בראה אנכי גבי פסולי המוקדשין שנפדו (דברים יב, טז) רק הדם לא תאכלנו על הארץ תשפכנו כמים והדר כתיב (דברים יב, כה) לא תאכלנו למען ייטב לך וגו' לדם לא איצטריך דהא כתיבי קראי טובא ומוקי ליה לבשר בחלב:"],[1,"דבר הלמד מענינו","דבר סתום שאין מפורש בו במה מדבר הוי לומדו מן הענין פרשה שנכתב בה במה הענין מיירי:"],[1,"בשני מינין","פסולי המוקדשין שנפדו שני מינין הן מותרין באכילה כחולין ואסורין בגיזה ועבודה כקדשים כדאמר בבכורות (דף טו.) תזבח ולא גיזה בשר ולא חלב:"],[2,"אבל בהנאה לא קמ\"ל","מהאי קרא דכתיבא אזהרה דידיה גבי פסח מה פסח מבושל אסור באכילה ובהנאה דכל קדשים שאינם ראוים לאכילה תעובר צורתן ויצאו לבית השריפה אף זה אסור בהנאה:"],[3,"כי עם קדוש אתה","לא תבשל גדי:"],[3,"מה להלן בהנאה","[בעילה] הנאה היא:"],[4,"לא תאכלו כל נבלה","בסיפיה דקרא כתיב בשר בחלב:"],[4,"לא תבשלנה","בחלבו ותמכרנה אלמא אסורה בהנאה:"],[7,"שנעבדה בו עבירה","בבישול:"],[8,"לא היתה לו שעת הכושר","פרי הערלה באיסור גדל אבל בשר בחלב היתה לו שעת הכושר קודם שניתן בשר בחלב:"],[10,"כלאי הכרם יוכיחו","לקמן פריך ל\"ל כלאי הכרם נימא ערלה תוכיח וחזר הדין ועוד פריך נימא מה לכלאי הכרם שכן לא היתה [להן] שעת הכושר:"],[11,"למה לי גז\"ש","לאיסור אכילה כי היכי דיליף לאיסור הנאה מערלה נילף נמי לאיסור אכילה:"],[12,"משום דאיכא למימר חורש בשור ובחמור יוכיח","שנעבדה בו עבירה ומותר באכילה אבל השתא דקיימא לן אכילה מג\"ש ילפינן הנאה בק\"ו וליכא למימר חורש בשור וחמור יוכיח דמה לחורש בשור וחמור דמותר באכילה תאמר בבשר בחלב שאסור באכילה:"],[13,"למה ליה למימר","לעיל כלאים יוכיח דאיצטריך ליה לאהדורי אכלאים דהוה ליה למד חדא מתלת בשר בחלב מערלה וחמץ וכלאים לימא ערלה תוכיח ותיתי חדא מתרתי שפיר:"],[13,"וליהדר דינא","וכשיחזור הדין מה לערלה שכן לא היתה לה שעת הכושר חמץ יוכיח מה לחמץ שכן כרת ערלה תוכיח וגמרינן ומייתינן לה במה הצד כגון לא ראי ערלה כראי חמץ ולא ראי חמץ כראי ערלה הצד השוה שבהן שאסורין באכילה ואסורין בהנאה אף אני אביא בשר בחלב דהואיל ואסור באכילה מגז\"ש יהא אסור אף בהנאה:"],[15,"הכי אמרינן משמיה דר\"ל","האי נבלה תוכיח אינה תשובה דכל הבאה במה הצד מגופיה פרכינן אם יש להשיב בשניהם מה להצד השוה שבשניהם שכן כך וכך יש בהם תאמר בזה שלא הושווה להן במדה זו (היא) פרכינן אבל מעלמא כגון פלוני יוכיח לא פרכינן:"],[16,"שכן גדולי קרקע","אע\"ג דאין חומר להיות נאסרין בכך אפ\"ה אמרינן:"],[18,"כל מה הצד פרכינן כל דהו","כל דבר הלמד בהצד השוה ויש להשיב שום דבר שהמלמדין שוין בו והלמד אינו שוה להן בו אפילו שאינו לא קל ולא חמור פרכינן ליה:"],[18,"לא אם אמרת כו'","אי הוה הדר דינא ואתי במה הצד הוה פרכינן כל דהו אבל השתא דאתי מכלאים ואתה בא להשיב לא אם אמרת בכלאים שכן גדולי קרקע אין זו תשובה דקולא וחומרא פרכינן אם אנו צריכין ללמוד קולא יש לך להשיב לא אם אמרת בזה שכן יש בו צד קל אחר ואם אנו לומדים חומר צריך אתה להשיב לא אם אמרת בזה שכן יש בו צד חמור כגון הני דאמרינן לעיל מה לערלה שכן לא היתה לה שעת הכושר וכגון חמץ בפסח שהשבנו לא אם אמרת בחמץ בפסח שכן כרת אבל כל דהו כי האי שכן גדולי קרקע לאו פירכא היא:"],[19,"וליפרוך לכולהו כו'","דכיון דלאו חדא מחדא היא אלא חד מתלת כמה הצד דמי הלכך ליפרוך בכולהו ואע\"ג דלאו קולא וחומרא היא דקא ס\"ד דכי אמרינן בלא אם אמרת דלא פרכינן ביה כל דהו ה\"מ היכא דאתיא חדא מחדא כגון בריש מלתא דבעי לאתויי מערלה לחודה אבל חדא מתרתי או מתלת כמה הצד דמיא ואף על גב דלא אמרינן וחזר הדין פרכינן לכולהו פירכא כל דהו:"]],[[1,"בשני מינין","פי' בקונטרס מותרין באכילה כחולין ואסורין בגיזה ועבודה כקדשים ואין נראה דלא שייך משום הכי דמקרי שני מינים אלא נראה משום דאיתקש לצבי ואיל חשיב להו כשני מינין כדאמר פ' אלו הן הלוקין (מכות דף כב.) אמר רבי יצחק המרביע שור פסולי המוקדשין לוקה ור' אושעיא נמי קאמר המנהיג שור פסולי המוקדשין לוקה גוף אחד הוא ועשאו הכתוב ב' גופים פירוש שעשאו הכתוב כצבי ואיל ובהכי מיישב ר\"ת הא דאמר בפ' כל פסולי המוקדשין (בכורות לג.) תלת צבי ואיל כתיבי חד לכדרבי יצחק ורבי אושעיא ופי' שם בקונטרס דלא אתפרש היכא:"],[3,"ונאמר להלן לא יהיה קדש","ואי לאו קרא דלא תאכלנו ה\"א דהנאת הגוף בלא אכילה אסר הכתוב:"],[7,"ומה ערלה","ליכא למפרך מה לערלה שכן צריך מאתים לבטלה דמדרבנן הוא דצריך מאתים:"],[9,"מה לחמץ בפסח שכן כרת","וכרת גופיה לא שייך למילף שאין עונשין מן הדין:"],[10,"כלאי הכרם יוכיחו","מכלאי הכרם גרידא הוה מצי למילף במה מצינו אלא ניחא ליה למעבד תחלת הדין בק\"ו ואין להקשות מה לערלה וחמץ וכלאי הכרם שכן בשריפה כדתנן בתמורה (דף לג:) דהיא גופה נילף ועוד דהיינו דוקא לרבי יהודה דאמר אין ביעור חמץ אלא שריפה אבל לרבנן לא הוי חמץ בשריפה הקשה ה\"ר יעקב מאורליינ\"ש מה לכולהו שכן לא הותרו מכללן תאמר בבשר בחלב שהותר מכללו אצל בהמה טמאה וחלב בהמה טמאה וטובא דאמר לעיל וי\"ל דאין זה קרוי הותר מכללו דדוקא חלב דכתיב (ויקרא ג) כל חלב דמשמע אפילו דחיה והדר שרא דחיה זה חשיב הותר מכללו אבל בבשר בחלב לא כתיב כל:"],[12,"חורש בשור וחמור כו'","אבל השתא עבדינן ק\"ו דכשם שאסור באכילה אסור בהנאה:"],[19,"וליפרוך מה לכולהו שכן גדולי קרקע","ואע\"ג דמכלאי הכרם איכא למילף במה מצינו ולא פרכינן כל דהו מ\"מ אהא דיליף בק\"ו משלשתן פריך:"]]],[["חדא מחדא קולא וחומרא פרכינן כל דהו לא פרכינן חדא מתרתי אפילו כל דהו פרכינן","חדא מתלת אי הדר דינא ואתי במה הצד פרכינן כל דהו ואי לא קולא וחומרא פרכינן כל דהו לא פרכינן","ולפרוך מה לכלאי הכרם שכן לא היתה להן שעת הכושר אמר רב אדא בר אהבה זאת אומרת כלאי הכרם עיקרן נאסר והיתה להן שעת הכושר קודם השרשה","מתיב רב שמעיה בר זעירא המעביר עציץ נקוב בכרם אם הוסיף מאתים אסור הוסיף אין לא הוסיף לא","אמר אביי תרי קראי כתיבי כתיב (דברים כב, ט) פן תקדש המלאה וכתיב הזרע","הא כיצד זרוע מעיקרו בהשרשה זרוע ובא הוסיף אין לא הוסיף לא","מתני' דלא כי האי תנא דתניא רבי שמעון בן יהודה אומר משום רבי שמעון בשר בחלב אסור באכילה ומותר בהנאה שנאמר (דברים יד, ב) כי עם קדוש אתה ונאמר להלן (שמות כב, ל) ואנשי קדש תהיון לי","מה להלן אסור באכילה ומותר בהנאה אף כאן אסור באכילה ומותר בהנאה:","רבי עקיבא אומר חיה ועוף וכו': הני הא אפקינהו לכדשמואל","קסבר רבי עקיבא איסור חל על איסור חלב ומתה לא צריכי קרא שליל גדי מעליא הוא אייתרו להו כולהו פרט לחיה ועוף ולבהמה טמאה:","רבי יוסי הגלילי אומר נאמר לא תאכלו: מאי איכא בין רבי יוסי הגלילי לרבי עקיבא","איכא בינייהו חיה רבי יוסי הגלילי סבר חיה דאורייתא ור' עקיבא סבר חיה דרבנן","איבעית אימא עוף איכא בינייהו ר' עקיבא סבר חיה ועוף אינן מן התורה הא מדרבנן אסירי ור' יוסי הגלילי סבר עוף אפילו מדרבנן נמי לא אסיר","תניא נמי הכי במקומו של רבי אליעזר היו כורתין עצים לעשות פחמין לעשות ברזל במקומו של רבי יוסי הגלילי היו אוכלין בשר עוף בחלב","לוי איקלע לבי יוסף רישבא אייתו לקמיה רישא דטיוסא בחלבא ולא אמר להו ולא מידי כי אתא לקמיה דרבי אמר ליה אמאי לא תשמתינהו","אמר ליה אתריה דרבי יהודה בן בתירא הוא ואמינא דרש להו כרבי יוסי הגלילי דאמר יצא עוף שאין לו חלב אם:","\u0001מתני׳\u0002 קבת עובד כוכבים ושל נבלה הרי זו אסורה המעמיד בעור של קבה כשרה"],[[0,"חדא מחדא","כגון בריש מילתא דבעי לאתויי מערלה לחודה פרכינן קולא וחומרא ולא כל דהו:"],[0,"חדא מתרתי","כגון שהשבנו מה לערלה שכן לא היתה כו' וסייעתנו ראיית דברינו בדבר אחר כגון חמץ בפסח יוכיח פרכינן אפילו כל דהו אם לא היה בידינו תשובת קולא וחומרא שהשבנו מה לחמץ בפסח שכן כרת והיה בידינו תשובה כל דהו השוה בשני המלמדין היינו משיבין אותה אע\"פ שלא חזר הדין ולא באנו להצד השוה:"],[1,"אבל חדא מתלת","כגון זו שאמרנו כלאים יוכיחו אי הדר דינא ואתי במה הצד אם היה בידינו תשובת קולא וחומרא להשיב על כלאים כגון מה לכלאים שכן כך וכך דליצטריך מיהדר דינא ומייתי במה הצד פרכינן כל דהו על מה הצד אבל כל כמה דלא הדר דינא לא פרכינן כל דהו אפילו שוים בכולהו כך המדות מסורות בידינו מסיני:"],[2,"ולפרוך מה לכלאי הכרם שכן לא היתה להם שעת הכושר","דקס\"ד אין הזריעה נאסרת אלא הגידולים ולהם לא היתה שעת הכושר מעולם:"],[2,"זאת אומרת","מדלא פריך הכי ש\"מ כלאי הכרם עיקרן נאסר אפילו הזריעה עצמה נאסרת משנשרשה:"],[2,"עיקרן","השרשתן נאסרת ולזריעה הזאת היתה לה שעת היתר כל ימיה משבאה לעולם עד שנשרשה:"],[3,"עציץ נקוב","וזרעים בו והעבירו בכרם וכיון דנקוב הוא יונק מן הכרם:"],[3,"הוסיף מאתים","הוסיף בתוך הכרם אחד ממאתים שגדל הירק או גרעיני הזרעים בתוכו דהוו להו מאה ותשעים ותשעה דהיתר וחלק המאתים הוי איסור אסור וכל שכן אם הוסיף יותר דכלאי הכרם אין בטלים עד שיהו בו מאתים דהיתר והאחד (ומאתים) של איסור:"],[3,"לא הוסיף","מאתים אלא פחות כל דהו וכגון שיש בהיתר מאתים בו דהוי איהו אחד ומאתים מותר:"],[4,"המלאה","משמע מילויו ותוספתו:"],[4,"וכתיב הזרע","דמשמע זריעה עצמה:"],[5,"זרוע מעיקרו","בתוך הכרם נאסר מיד בהשרשה:"],[5,"זרוע ובא","שהיה נשרש כבר בהיתר חוץ לכרם בעינן מלאה:"],[6,"מתניתין","דקתני בשר בחלב אסור בהנאה דלא כי האי תנא:"],[7,"מה להלן מותר בהנאה","דכתיב ביה לכלב תשליכון אותו:"],[8,"הא דרשינהו לכדשמואל","חד לחלב ומתה וחד לרבות שליל וחד להוציא טמאה (לעיל חולין דף קיג:):"],[9,"קסבר ר\"ע כו'","וכל הני גדי קראי יתירי נינהו לדרשה מדהוה ליה למיכתב בכולהו לא תבשל בהמה וכתב גדי שמע מינה לדרשה פרט לבהמה טמאה ולחיה ולעוף וחלב ומתה ממשמעותיה דגדי משמע נמי חלב ומתה ואי משום דאסירי וקיימי ואין איסור חל על איסור אי לא כתיב רבויא קסבר ר\"ע איסור חל על איסור הילכך חלב ומתה לא צריכי קרא לרבויי ואתו ממשמעותא וכן שליל:"],[10,"מאי איכא בין ר\"ע","דנפקא ליה מגדי פרט לעוף ובין רבי יוסי הגלילי דנפקא ליה מבחלב אמו:"],[11,"רבי יוסי הגלילי סבר חיה דאורייתא","דכל שהוא אסור משום נבלה נוהג בו בשר בחלב חוץ מן העוף שאין לו חלב אם:"],[12,"עוף איכא בינייהו","ר\"ע דפריש דאינו מן התורה משמע הא מדרבנן יש לו אבל רבי יוסי הגלילי דלא פריש האי לישנא שרי ליה לגמרי:"],[13,"תניא נמי הכי","דלרבי יוסי הגלילי אפילו איסורא דרבנן לית ליה בעוף:"],[13,"רבי אליעזר","אית ליה מכשירי מצוה דוחין את השבת במצוה שדוחה את השבת ואם אין לו אזמל למולו בשבת כורתין עצים לעשות פחמין ועושין אזמל:"],[14,"רישבא","צייד עופות רישבא לשון אין פורסין רישבין ליונים:"],[14,"טווסא","פואו\"ן:"],[16,"מתני' קבה","זהו חלב קרוש שבתוך הקבה:"],[16,"ושל נבלה","בגמרא פריך אטו דעובד כוכבים לאו נבלה היא:"],[16,"המעמיד","חלב:"],[16,"בעור הקבה","דהוא בשר:"]],[[0,"חדא מתרתי אפילו כל דהו פרכינן","משמע אע\"ג דלא הדר דינא וא\"ת א\"כ מיד כשאמר חמץ בפסח יוכיח נפרוך שכן גדולי קרקע ושוב לא יוכל לומר כלאי הכרם יוכיח וי\"ל דמתחלה היה יכול לומר חמץ בפסח וכלאי הכרם יוכיחו דהוו להו תלתא ועוד דהוה מצי למימר בשר תקרובת עבודת כוכבים יוכיח וכי תימא מה לתקרובת שכן מטמא הא דמטמא היינו מדרבנן כדפרישית בפ\"ק (לעיל חולין דף יג: ד\"ה תקרובת):"],[2,"עיקרן נאסר","משמע שאף הקשים והעץ נאסרין וכן משמע בפרק כל שעה (פסחים דף כו:) דאמרינן תנור שהסיקוהו בקליפי ערלה או בקשים של כלאי הכרם חדש יותץ ותימה דבפרק האשה שנפלו לה נכסים (כתובות דף פ.) משמע דשרו גבי המוציא הוצאות על נכסי אשתו עבד רב יהודה עובדא בחבילי זמורות רב יהודה לטעמיה דאמר אכלה ערלה שביעית וכלאים הרי זו חזקה פירוש דאז אינו יכול לאכול אלא זמורות וי\"ל דקשין ועץ שהיו קודם שנזרע כלאים מותר עד שיוסיף מאתים ורוב פעמים שהפרי הוסיף מאתים ונאסרו הקשין והעץ שהיו מקודם כבר גדולין ושוב לא יוסיפו מאתים אבל ודאי כל מה שגדל אחר שנזרע כלאים אסור אף הקשין והעץ:"],[2,"והיתה להם שעת הכושר קודם השרשה","הקשה הרב רבי משה כהן דבפ\"ק דמנחות (דף ו.) אמר אי ממשקה ישראל ה\"א היכא דלא היתה להן שעת הכושר דומיא דערלה וכלאי הכרם והכא משמע דהיתה להן שעת הכושר וי\"ל דהתם מיירי ביין שעושין ממנו נסכים למזבח דבעי שיהיה ממשקה ישראל ואותו לא היה לו שעת הכושר דמה שגדל לאחר זריעת הכלאים הוא אסור (ואותו לא היתה לו שעת הכושר) ומה שגדל קודם מותר ואינו נאסר כשהוסיף מאתים אלא משום תערובת שנתערב עם מה שגדל אח\"כ והגרעינים שנזרעו הוא דהיתה להן שעת הכושר:"],[7,"מה להלן אסור באכילה ומותר בהנאה","אע\"ג דאיכא למילף איסור הנאה בקל וחומר כדלעיל קא סבר אין ג\"ש למחצה ויליף מיניה אף היתר הנאה וההוא דלעיל סבר דאהני ג\"ש ואהני ק\"ו אי נמי משום דבההוא קרא דטרפה איירי נמי בקדשים שיצאו חוץ למחיצתן כדאמר פרק בהמה המקשה (לעיל חולין דף סח:) דאסירי אף בהנאה וגלי לן ק\"ו דילפינן מינייהו ור\"ש דהכא סבר דפשטיה דקרא בטרפה מיירי:"],[16,"המעמיד בעור של קבה אם יש בה כו'","תימה דבגמרא מפרש טעמא דאסרו גבינות העובדי כוכבים מפני שמעמידין אותם בעור קבת נבלה מאי איריא נבלה אפילו כשרה נמי ויש לומר דמשום בשר בחלב לא היו אסורין מספק משום דליכא אלא איסורא דרבנן דדרך בישול אסרה תורה:"]]],[["אם יש בנותן טעם הרי זו אסורה כשרה שינקה מן הטרפה קבתה אסורה טרפה שינקה מן הכשרה קבתה מותרת מפני שכנוס במעיה:","\u0001גמ׳\u0002 אטו קבת עובד כוכבים לאו נבלה היא אמר רב הונא הכא בלוקח גדי מן העובד כוכבים עסקינן וחיישינן שמא ינק מן הטרפה","ומי חיישינן שמא ינק מן הטרפה והתנן לוקחים ביצים מן העובדי כוכבים ואין חוששין לא משום נבלה ולא משום טרפה אלא אימא חיישינן שמא ינק מן הטמאה","ומאי שנא טרפה דלא חיישינן ומאי שנא טמאה דחיישינן טרפה לא שכיחא טמאה שכיחא","אי שכיחא אפילו גבי דידן ניחוש אנן דבדלינן מינייהו וכי חזינן להו מפרשינן להו לא גזרו בהו רבנן אינהו דלא בדילי מינייהו וכי חזו להו לא מפרשי להו גזרו בהו רבנן","ושמואל אמר חדא קתני קבת שחיטת עובד כוכבים נבלה","ומי אמר שמואל הכי והאמר שמואל מפני מה אסרו גבינת העובדי כוכבים מפני שמעמידין אותה בעור קבת נבלה הא קבה גופה שריא","לא קשיא כאן קודם חזרה כאן לאחר חזרה:","כשרה שינקה מן הטרפה [וכו']: והא קתני רישא קבת עובד כוכבים ושל נבלה הרי זו אסורה","אמר רב חסדא רישא נראה כאוכל נבלות הכא איכא שחיטה","א\"ל רבא ולאו כל דכן הוא ומה נבלה דמאיסה דאי שרית ליה קבתה לא אתי למיכל מינה אמרת לא טרפה שחוטה דאי שרית אתי למיכל מינה לא כ\"ש","אלא אמר רב יצחק אמר רבי יוחנן לא קשיא כאן קודם חזרה כאן לאחר חזרה ומשנה לא זזה ממקומה","אמר רבי חייא בר אבא אמר רבי יוחנן מעמידין בקבת נבלות ואין מעמידין בקבת שחיטת עובד כוכבים אמר לפניו רבי שמעון בר אבא כמאן כרבי אליעזר דאמר סתם מחשבת עובד כוכבים לעבודת כוכבים","א\"ל ואלא כמאן","כי אתא רב שמואל בר רב יצחק אמר רבי יוחנן מעמידין בין בקבת נבלה בין בקבת שחיטת עובד כוכבים שלא לחוש לדברי רבי אליעזר","והלכתא אין מעמידין בעור קבת נבלה אבל מעמידין בקבת נבלה ובקבת שחיטת עובד כוכבים (ובקבת כשרה שינקה מן הטרפה וכ\"ש בקבת טרפה שינקה מן הכשרה מ\"ט חלב המכונס בה פירשא בעלמא הוא):","\u0001מתני׳\u0002 חומר בחלב מבדם וחומר בדם מבחלב חומר בחלב שהחלב"],[[0,"אם יש בה","ליתן טעם בחלב:"],[0,"הרי זו אסורה","וחלב הנמצא קרוש בעור הקבה שמולחין אותה בעורה בין שנותנין עמו חלב אחר ובין שמולחין אותה עמה נראה בעיני איסור גמור כבשר בחלב ממש לאסור הגבינה איסור גמור ואין בידי כח להתיר ויש מתירין אותו ומביאין ראיה מדגים שעלו בקערה שפסקנו (לעיל חולין דף קיא:) שמותר לאוכלן בכותח משום דהוה ליה נותן טעם בר נותן טעם שחלב הקבה לא נאסר אלא משום נתינת טעם וכי הדר יהיב טעמא בגבינה הוה ליה נותן טעם בר נותן טעם ורחוקות זו מזו כרחוק מזרח ממערב מהאי טעמא דדגים שעלו בקערה אע\"פ שבלעו את טעמה עדיין היתר גמור הן לאוכלן וכשבא לאוכלן בכותח למה אתה אוסר עליו מפני טעם בשר שלה ההוא טעם בשר לאו טעם הוא שהרי לא בא מן הממש אלא מנ\"ט אחר אבל חלב הנמלח בבשר משנתנו טעם זה בזה נעשו שניהם איסור כדקיימא לן (לעיל חולין דף קח.) חתיכה עצמה נעשית נבלה וכל טעם היוצא עוד מן החלב בין טעם חלב שבו בין טעם בשר שבו הכל אסור לפי שכולה נבלה וכשמתערב חלב זה עם חלב הגבינות הוה ליה מין במינו חלב נבלה בחלב היתר וכבר פסקנו חתיכה עצמה נעשית נבלה ואוסרת כל החתיכות כולן ולא אמרינן נותן טעם בר נותן טעם הוא מפני שאף טעם חלב שבו שהיה מתחלה נעשה כולו נבלה וכן הלכה כרב וגם פסקנו בפסחים (דף כט:) הלכה דמין במינו בכל שהוא ואני הייתי נוהג היתר עד הנה ובלבד שלא יתנו בה חלב אחר וטועה הייתי בכך שהייתי סבור כדאמרינן בע\"ז (דף כט:) גבי קבת עולה כהן שדעתו יפה שורפה חיה שמע מינה פירשא בעלמא היא ולא מיתסרא ולא היא חלב גמור הוא מדתנא במתניתין כשרה שינקה מן הטרפה קבתה אסורה שמע מינה חלב הוא ותניא נמי קבה שבשלה בחלבה אסורה וקבת עולה דשריא משום דלאו גופה היא אלא שינקתו מאמו והוה ליה כנוס במעיה כנתון בקערה ומותר כדתניא טרפה שינקה מן הכשרה קבתה מותרת מפני שכנוס במעיה ודמייתי ראיה במסכת ע\"ז מינה דאיסורי הנאה שרי פירשייהו וגבי עגלי עבודת כוכבים דאסור פירשייהו מדקתני קבת עגלי עבודת כוכבים אסירא לאו משום דקבה פירשא חשיב לה לענין עיכול דתיהוי כפירשא למפקע שם חלב מינה אלא הכי מייתי ראייה מינה מדאסר קבת עבודת כוכבים ש\"מ פירשא אסור דהא קבתה נמי לאו גופה היא ומיתסר משום דניחא ליה בנפח כשהבמה נראת שמנה ויפה לעבודה זרה וה\"ה לשאר הפרש ומדשרי לה גבי עולה ש\"מ לא מיתסר אלא גופה אבל פירשא שרי כי האי גוונא דאין קדושה חלה אלא על הראוי ממנה למזבח מידי דהוי אעור של עולה שהוא מתחלק לכהנים כן מצאתי בנימוקי רבינו שלמה ברבי מאיר:"],[1,"גמ' בלוקח גדי מן העובד כוכבים","ושחטו קרי ליה קבת עובד כוכבים ואסורה:"],[1,"חיישינן שמא ינק","חלב זה מן הטרפה:"],[2,"לא משום נבלות","שמא נמצא בתרנגולת נבלה:"],[2,"ולא משום טרפה","שמא מעוף טרפה היא דאמרינן באלו טרפות (לעיל חולין דף נח.) ומודים בביצת טרפה שאסורה:"],[4,"גבי דידן","גדיים שלנו נמי תהא אסורה קבתן משום דחיישינן שמא ינק חלב זה מן (הטמאה) בהמה טמאה:"],[5,"חדא קתני","משום דשל נבלה היא אסר לה:"],[6,"ומי אמר שמואל","קבת נבלה אסורה אלמא כגופה דמי:"],[6,"והאמר שמואל","במסכת ע\"ז מפני שמעמידין אותה בעור קבת נבלה הא קבה גופה חלב הקרוש קרי קבה וקאמר דשריא:"],[7,"כאן קודם חזרה כו'","בפרק אין מעמידין (ע\"ז דף כט:) שאל רבי ישמעאל את רבי יהושע מפני מה אסורין גבינות העובדי כוכבים אמר לו מפני שמעמידין אותה בקבת נבלה כלומר בחלב הקרוש שבה אמר לו והלא קבת העולה חמורה מקבת נבלה ואמרו כל כהן שדעתו יפה שורפה חיה אמר לו מפני שמעמידין אותה בקבת עגלי עבודה זרה אלמא חזר בו מקבת נבלה משום דלאו גופה היא ואסורה משום עבודה זרה דאפילו פירשא דידה אסור כדמפרש התם משום דניחא ליה בנפחיה הלכך משנתינו זאת נשנית קודם חזרה ומשום הכי אסר וכי אתמר דשמואל דעור קבה הוא דאסור הא קבה שריא לאחר חזרה קאמר ומשנתינו זאת מכיון שנשנית אף על פי שחזר בו לא זזה ממקומה ולא סילקוה ולא אמרו שלא לשנותה עוד:"],[8,"והא קתני רישא קבת נבלה אסורה","והדר קתני קבת טרפה מותרת דקתני טרפה שינקה מן הכשרה קבתה מותרת:"],[9,"איכא שחיטה","ולא מאיסה כולי האי כנבלה ואיסור אין כאן לא בזו ולא בזו כדקתני מפני שכנוס במעיה נאסף הוא במעיה מן אחרים ולא משל עצמה:"],[11,"משנה הראשונה","קודם חזרה נשנית וכיון שנשנית לא זזה ממקומה וחזרו ושנו אחרונה להיתר:"],[12,"מחשבת עובד כוכבים לעבודת כוכבים","הילכך אף על גב דלאו גופה הוא מיתסר כדפרישית דאפילו פירשא מיתסר משום דניחא ליה בניפחיה:"],[13,"ואלא כמאן","כלומר לא הוצרכת לשאול:"],[14,"מעמידין בין בקבת נבלה כו'","דלאו מגופה הוא אלא כנוס במעיה:"]],[[2,"חיישינן שמא ינק מן הטמאה","לא קיימא לן הכי דהלכה כשמואל דמשני מתניתין בשינויא אחרינא ואנו מעמידין בקבת עגלים שאנו לוקחים מן העובדי כוכבים ולא חיישינן שמא ינק מן הטמאה:"],[5,"חדא קתני","תימה מאי קא משמע לן דקבת עובד כוכבים נבלה הא שמעינן מפרק קמא במתניתין ולא הוה ליה למיתני הכא אלא קבת עובד כוכבים אסורה:"],[6,"ומי אמר שמואל הכי","בלאו הכי הוה מצי למיפרך ממתניתין על שמואל אלא הא עדיפא ליה דמדמפרש שמואל מתניתין אלמא סבר כוותה:"],[7,"כאן לאחר חזרה","ולפי זה שריא קבת נבלה אלא עכשיו נהגו העולם הדבר לאיסור ואין להקל ליקח קבת עובד כוכבים ובדיעבד מותר דאפילו לכתחלה שרי היכא דידעינן שלא נמלחה בעורה אם לא שמכוער הדבר הואיל והחזיקו בו איסור ומיהו היכא דנמלחה הקבה בעורה אסורה ודאי משום בשר בחלב:"],[15,"הכי גרסינן ברוב ספרים","והלכתא אין מעמידין בעור קבת נבלה אבל מעמידין בקבת נבלה ובקבת שחיטת עובד כוכבים ובקבת כשרה שינקה מן הטרפה וכ\"ש בקבת טרפה שינקה מן הכשרה מ\"ט חלב המכונס בה פירשא בעלמא הוא ולכאורה לגירסא זו קשיא מתני' דתנא כשרה שינקה מן הטרפה קבתה אסורה וכן ברייתא דלעיל בפירקין (חולין דף קט:) קבה שבשלה בחלבה אסורה ואומר ר\"ת דהני מילי חלב צלול שבתוך הקבה דלא חשוב פירשא אבל הקרוש שבתוך הקבה חשוב פירשא ואותו הקרוש לפי דבריו אפילו נמלח בתוך הקבה מותר:"]]],[["מועלין בו וחייבין עליו משום פיגול ונותר וטמא מה שאין כן בדם","וחומר בדם שהדם נוהג בבהמה וחיה ועוף בין טמאים ובין טהורים וחלב אינו נוהג אלא בבהמה טהורה בלבד:","\u0001גמ׳\u0002 מנא הני מילי אמר ר' ינאי דאמר קרא (ויקרא ד, י) כאשר יורם משור זבח השלמים וכי מה למדנו משור זבח השלמים מעתה","הרי זה בא ללמד ונמצא למד מקיש שור זבח השלמים לפר כהן משיח מה פר כהן משיח יש בו מעילה אף שור זבח השלמים יש בו מעילה","א\"ל ר' חנינא כעורה זו ששנה רבי (ויקרא ג, טז) כל חלב לה' לרבות אימורי קדשים קלים למעילה","אמר אביי איצטריך דאי כתב רחמנא חלב הוה אמינא חלב אין יותרת ושתי כליות לא כתב רחמנא כאשר יורם","ואי כתב רחמנא כאשר יורם הוה אמינא חלב אליה דליתא בשור לא כתב רחמנא כל חלב","א\"ל רב מרי לרב זביד אי אליה איקראי חלב תיתסר באכילה א\"ל עליך אמר קרא (ויקרא ז, כג) כל חלב שור וכשב ועז דבר השוה בשור וכשב ועז","רב אשי אמר (ויקרא ג, ט) חלבו האליה איקראי חלב סתמא לא איקראי אלא מעתה לא ימעלו בה אלא מחוורתא כדרב זביד:","משא\"כ בדם: מנה\"מ אמר עולא דאמר קרא (ויקרא יז, יא) לכם שלכם יהא דבי רבי ישמעאל תנא (ויקרא יז, יא) לכפר לכפרה נתתיו ולא למעילה","ורבי יוחנן אמר אמר קרא (ויקרא יז, יא) הוא הוא לפני כפרה כלאחר כפרה מה לאחר כפרה אין בו מעילה אף לפני כפרה אין בו מעילה","ואימא הוא לאחר כפרה כלפני כפרה מה לפני כפרה יש בו מעילה אף לאחר כפרה יש בו מעילה אין לך דבר שנעשה מצותו ומועלין בו","ולא והרי תרומת הדשן דנעשה מצותו ומועלין בו דכתיב (ויקרא ו, ג) ושמו אצל המזבח","משום דהואי תרומת הדשן ובגדי כהונה שני כתובין הבאין כאחד וכל שני כתובין הבאין כאחד אין מלמדין","הניחא לרבנן דאמרי (ויקרא טז, כג) והניחם שם מלמד שטעונין גניזה אלא לר' דוסא דאמר שלא ישתמש בהן ליום הכפורים אחר מאי איכא למימר","אלא משום דהואי תרומת הדשן ועגלה ערופה שני כתובים הבאין כאחד וכל שני כתובים הבאין כאחד אין מלמדין","הניחא למ\"ד אין מלמדין אלא למאן דאמר מלמדין מאי איכא למימר תרי"],[[0,"מתני' מועלין בו","אם קרבן הוא דהא קדשי ה' הן ואינם לכהנים והדם אין מועלין בו כדיליף בגמרא:"],[0,"וטמא","אם אכלו בטומאת הגוף חייב שתי חטאות אחת משום חלב ואחת משום טומאת הגוף שהיא בכרת:"],[0,"משא\"כ בדם","מפרש בגמרא:"],[1,"אלא בבהמה טהורה","כדכתיב (ויקרא ז׳:כ״ה) מן הבהמה אשר יקריבו ממנה וגו':"],[2,"גמ' מנה\"מ","דחלב יש בו מעילה ולא מפליג דאפילו חלב קדשים קלים אע\"ג דאין בהן מעילה בחייהן דהא ממון בעלים הן יש בו מעילה באימוריהם לאחר שנזרק דמן:"],[2,"כאשר יורם","באימורי פר כהן משיח כתיב:"],[2,"ומה למדנו","דקאמר ככל מה שמפרישים אימורים משלמים כך יפרשו מזה אף כאן האימורים מפורשים את החלב המכסה [על הקרב] ואת כל החלב ואת שתי הכליות וגו':"],[3,"מה פר כהן משיח יש מעילה","באימורים דהא מחיים הוה ביה מעילה דקדשי קדשים הוא:"],[3,"יש בו מעילה","בחלבו:"],[4,"כל חלב לה'","בקדשים קלים כתיב ולהכי כתיב בהו לה' למימרא דקדשי ה' קרינא ביה לענין מעילה:"],[5,"יותרת ושתי הכליות לא","דלאו חלב איקרו:"],[6,"כאשר יורם","לימד על כל האימורים שהוקשו לאימורי פר כהן משיח:"],[6,"אליה דליתא בשור לא","נמעלו בה כי מייתו כבש לשלמים דאלית הכבש קרינא ביה כתב רחמנא כל חלב ואשכחן אליה דאיקרי חלב דכתיב (ויקרא ג) חלבו האליה תמימה:"],[7,"תיתסר","כל אלית כבש באכילה:"],[7,"כל חלב שור וכשב ועז","לא אסרה תורה אלא הנוהג בכולן ואליה אינה נוהגת לא בשור ולא בעז:"],[8,"לא ימעלו בה","דהא מעילה מכל חלב לה' נפקא לן והא אמרת דלאו חלב איקראי:"],[9,"לכם","ואני נתתיו לכם וגו' שלכם יהא אלמא לאו קדשי גבוה הוא:"],[9,"לכפרה נתתיו","ולא שיהא קרוי שלי למעול בו שאינה עומדת אלא לכפר בשבילכם:"],[10,"הוא","משמע בהוייתו יהא לעולם דינו שוה בין לפני כפרה ובין לאחר כפרה שנתן מתנותיו ונשארו השיריים:"],[10,"מה לאחר כפרה אין מעילה","בשיריים כדלקמן דאין לך דבר שנעשה מצותו ומועלין בו שהרי כבר נעשה צורך גבוה ממנו ולאו קדשי ה' קרינא ביה:"],[12,"תרומת הדשן","כל בקר תורם מדשן מזבח מלא מחתה ונותנו בצדי המזבח ונבלעת שם במקומה כדכתיב והרים את הדשן אשר תאכל האש וגו' ושמו אצל המזבח מלמד שטעון שימה וגניזה אלמא אסור בהנאה:"],[13,"בגדי כהונה","ארבעה בגדי לבן שכ\"ג נכנס בהן לפני ולפנים ביום הכפורים וטעונין גניזה עולמית ואין הדיוט עובד בהן כל השנה ולא [כ\"ג] ליום כפורים אחר כדכתיב ופשט את בגדי הבד והניחם שם:"],[14,"אלא לרבי דוסא דאמר","כשרין הן לכהן הדיוט כל השנה שכהן הדיוט משמש בהן בארבעה כלים ומה ת\"ל והניחם שם מלמד שלא ישתמש הוא ליוה\"כ אחר מאי איכא למימר:"],[15,"עגלה ערופה","אף על פי שנעשה מצותה אסורה בהנאה דכתיב וערפו שם שם תהא קבורתה (כריתות דף ו.):"]],[[2,"אמר רבי ינאי דאמר קרא כאשר יורם כו'","בפרק איזהו מקומן (זבחים דף מט:) מוקמינן לה לדבר הלמד בהיקש דאינו חוזר ומלמד בהיקש דיותרת ושתי הכליות ילפינן בשעיר עבודה זרה מפר העלם דבר של ציבור ופר העלם מפר כהן משיח ואייתר כאשר יורם בפר כהן משיח לאוקומי בפר העלם דבר למהוי כמאן דכתיב בגופיה דלא ליהוי שעיר עבודה זרה למד מן הלמד ורבי ינאי דהכא סבר לה כמאן דיליף בפרק ב\"ש (זבחים דף מא:) ית ושתי הכליות בשעירי עבודה זרה מועשה לפר כו' ועוד י\"ל דרבי ינאי דהכא אסמכתא בעלמא הוא [דהא] במעילה בפרק קדשי מזבח (מעילה דף טו.) א\"ר ינאי אין חייבין משום מעילה אלא קדשי בדק הבית בלבד ולא בקדשי מזבח דאית בהו לכהנים ולבעלים ופריך ליה ממשניות טובא ומוקי לה מדרבנן ופריך והא קרא קא נסיב פי' כל חלב לרבות האימורים ומשני אסמכתא בעלמא וה\"ה קרא דהכא והא דתנן בפרק אמרו לו (כריתות יג:) יש אוכל אכילה אחת וחייב עליה ד' חטאות ואשם איכא לאוקומי בעולה ואע\"פ דעורה לכהנים אין לחוש כיון דכל הבשר למזבח:"],[10,"הוא לפני כפרה כלאחר כפרה","הקשה ר\"ת דבמעילה פ' ולד חטאת (מעילה דף יב:) אמרינן המקיז דם לבהמת קדשים מועלין בו אלמא יש מעילה בדם ותירץ דהתם מחיים דלא שייכא כפרה אבל לאחר שחיטה אף לפני כפרה אין מועלין וא\"ת דהתם תנן (דף יא.) ומייתי לה בפרק כל שעה (פסחים דף כב.) דם בתחלה אין מועלין בו יצא לנחל קדרון מועלין בו וי\"ל דמעילה דהתם מדרבנן היא וא\"ת א\"כ בריש מעילה (דף ב:) דדחיק לאשכוחי מעילה מדרבנן לייתי מהך משנה וי\"ל דהתם אקדשים ששחטן בדרום קאי דכחנקינהו דמי וכי האי גוונא דחיק לאתויי דתקון רבנן (כמה) מעילה אע\"ג דבדילי מינייהו ומייתי ראייה מר' יוחנן דאמר קדשים שמתו יצאו מידי מעילה דבר תורה וא\"ת בסוף תמורה (דף לב:) גבי מקדיש עולה לבדק הבית קאמר אי מדרבנן אימא סיפא ומועלין בה שתי מעילות ואי מדרבנן אמאי ומאי קושיא הא איכא מעילה דרבנן בדם ובקדשים שמתו וי\"ל דהתם שיש מעילה דאורייתא משום עולה אין לחכמים לתקן שם מעילה כיון דבלאו הכי בדילי מינייהו ומשני ראוי למעול בו ב' מעילות בבשר מעילה דאורייתא משום עולה ובעור דליכא מעילה דאורייתא לא בדילי מיניה ותקנו רבנן מעילה:"],[11,"אין לך דבר שנעשה מצותו ומועלין בו","וא\"ת אדרבה לא נמעט לפני כפרה דאין לך דבר שלא נעשה מצותו שלא ימעלו בו ואע\"ג דאיכא קדשים קלים היינו משום דלא אקרו קדשי שמים וי\"ל דאשכחן טובא דהא דשן אין מועלין בו עד שעת תרומה ועגלה ערופה עד לאחר ירידתה:"],[12,"ולא והרי תרומת הדשן","וא\"ת דתנן במעילה פרק ולד חטאת (מעילה דף יא.) דישון מזבח פנימי והמנורה לא נהנים ולא מועלין וקאמר בגמרא בשלמא מזבח החיצון דכתיב ביה ושמו אלא מזבח פנימי מנלן משמע דמושמו דריש דאין מועלין ובשמעתין אדרבה משמע ליה מושמו דמועלין וי\"ל דמתניתין דהתם משמע דאין מועלין בדישון הפנימי שהדישון מוציאו מידי מעילה אבל קודם מועלים א\"כ מצוה לדשן ועל זה קאמר בשלמא חיצון דכתיב ושמו לכך מצוה לדשן ומ\"מ אף לאחר הרמה איכא מעילה כדדרשינן בסוף מעילה (דף לד.) ושמו בנחת שלא יפזר אלא פנימי מנא לן דמצוה לדשן שאתה אומר שהדישון מוציאו מידי מעילה ומשני דאמר קרא והסיר מוראתו והשליך אותה אל מקום הדשן אם לענין מזבח החיצון לא צריך דהא כתיב ושמו אצל המזבח כו' והתם פריך והא איצטריך למזבח החיצון לקבוע לו מקום דכתיב קדמה:"],[13,"משום דהוי תרומת הדשן ובגדי כהונה כו'","במעילה בפרק ולד חטאת (מעילה דף יא:) מאריך יותר ומסקינן כי הכא:"]]],[["מיעוטי כתיבי הכא כתיב (ויקרא ו, ג) ושמו התם כתיב (דברים כא, ו) הערופה","ותלתא קראי ל\"ל בדם","חד למעוטי מנותר וחד למעוטי ממעילה וחד למעוטי מטומאה","אבל מפגול לא צריך קרא דתנן כל שיש לו מתירין בין לאדם ובין למזבח חייבין עליו משום פגול ודם גופיה מתיר הוא:","\u0001הדרן עלך כל הבשר\u0002","מתני׳ \u0001העור\u0002 והרוטב והקיפה והאלל והעצמות והגידין והקרנים והטלפים","מצטרפין לטמא טומאת אוכלין אבל לא טומאת נבלות","כיוצא בו השוחט בהמה טמאה לעובד כוכבים ומפרכסת מטמאה טומאת אוכלין אבל לא טומאת נבלות עד שתמות או עד שיתיז את ראשה ריבה לטמא טומאת אוכלין ממה שריבה לטמא טומאת נבלות","ר' יהודה אומר האלל המכונס אם יש בו כזית במקום אחד חייב עליו:","\u0001גמ׳\u0002 תנינא להא דת\"ר שומרים לטומאה קלה ולא שומרים לטומאה חמורה","שומרים לטומאה קלה מנלן דתנא דבי רבי ישמעאל (ויקרא יא, לז) על כל זרע זרוע כדרך שבני אדם מוציאין לזריעה חטה בקליפתה ושעורה בקליפתה ועדשים בקליפתן","ולא שומרים לטומאה חמורה מנלן דתנו רבנן (ויקרא יא, לט) בנבלתה ולא בעור שאין עליו כזית בשר"],[[0,"מיעוטי כתיבי","אפילו למ\"ד בעלמא מלמדין הני אין מלמדין דמיעוטי כתיבי בהו דמשמע הני ולא אחריני:"],[1,"תלתא קראי בדם","לכם לכפר הוא:"],[2,"לנותר","שאם נתותר ושגג בין בדם ובין בנותר ואכלו אינו חייב אלא משום דם:"],[2,"מטומאה","אם אכלו בטומאת הגוף אינו חייב אלא משום דם:"],[3,"אבל מפגול לא צריך","למעוטי דשאם היה הזבח פגול ואכל מדמו פשיטא לן דאין בו משום פגול:"],[3,"דתנן כל שיש לו מתירין","שדבר אחר מתיר אותו בין שהוא מתירו לאדם כגון בשר קדשים שהדם מתירו לכהנים בזריקתו ובין שיש לו מתירין למזבח ולא לאדם כגון עולה שדמה מתירה למזבח דאם לא נזרק דמה אין אבריה נקטרים כדכתיב (ויקרא יז) וזרק הכהן את הדם על מזבח ה' והדר והקטיר החלב לריח ניחוח:"],[3,"חייבין עליו משום פגול","אם פיגל את הזבח באחת מארבע עבודות הדם ואח\"כ אכל מן הבשר שהיה בכלל היתר הדם או מן האימורים שאף הן בהיתר הדם חייב כרת אבל כל דבר שאין אחר מתירו אלא הוא מתיר עצמו כגון הדם והקומץ והקטורת ומנחת כהנים שכולה כליל אין חייבין עליהם משום פגול משום דעיקר פגול בשלמים כתיב ומינייהו ילפינן מה שלמים יש להם מתירין לאדם ולמזבח חייבין עליהם משום פגול אף כל כו':"],[5,"מתני' העור והרוטב","העור של בהמה שחוטה כגון פחות מכביצה בשר ועורה אדוק בה ומשלימה לכביצה מצטרף מפני שהוא שומר ובגמרא ילפינן שהשומרים מצטרפין לטומאה קלה טומאת אוכלין:"],[5,"רוטב","גלייר\"א שאינה אוכל לקבל טומאה בפני עצמה אבל מצטרפת להשלים לפי שדרך לאוכלה כשהיא קרושה על הבשר:"],[5,"הקיפה","תבלין והן עצמן לאו אוכלין חשיבי אבל לאצטרופי מצטרפין:"],[5,"והאלל","בגמרא מפרש:"],[5,"והעצמות","שיש בהן מוח והוא אוכל והעצם שומר לו לפיכך מצטרף עמו:"],[5,"והקרנים","מפרש בגמרא כל שחותכו ויוצא מהם דם אצל עיקרן מלמטה שהן רכין ומיהו באנפי נפשייהו לאו אוכלא נינהו:"],[5,"והטלפים","משום שומר:"],[7,"אבל לא טומאת נבלות","אם מנבלה הן אין מטמאין ואין מצטרפין לכזית להשלים שיעור נבלה לטמא דתניא בנבלתה ולא בעצמות ולא בגידים ולא בעור ואע\"ג דשומר הויא אין שומר מצטרף לטומאה חמורה כדמפרש בגמרא וכן קיפה ורוטב לאו מנבלה נינהו ואלל וגידים לאו בשר הן אבל אוכלין בעלמא הוו בהדי בשר:"],[7,"כיוצא בו","יש שהוא מטמא טומאת אוכלין להיות מקבל טומאה מן השרץ ומטמא אוכלין אחרים ואינו מטמא מאליו טומאת נבלות לטמא אחרים:"],[7,"השוחט בהמה טמאה לעובד כוכבים","ודוקא ישראל ודוקא שחיטה ודוקא טמאה ודוקא לעובד כוכבים ישראל ששחט בהמה טמאה לצורך עובד כוכבים ועודה מפרכסת אף על גב דלא חזיא לעובד כוכבים דבמיתה תליא מילתא לבני נח ולא שריא להו שחיטה עד שתמות אפ\"ה הואיל וישראל שחט שחיטה מעלייתא היא ואשכחן לגבי ישראל דשחיטה שריא לגביה בטהורה הלכך משויא ליה מחשבתו אוכלא בשחיטה אף בטמאה לעובד כוכבים אבל עובד כוכבים בשחיטה לא משויא ליה מחשבתו אוכלא דלא אשכחן שחיטה לגביה וכן ישראל בנחירה לאו אוכלא משויא לה דלא אשכחן נחירה גביה והכי תניא נחרה אין בה טומאה של כלום ובטהורה לישראל לא איצטריך למתני דכ\"ש דהויא אוכלא מיד בשחיטתה וטמאה לישראל לא משויא ליה אוכלא דבטלה מחשבתו:"],[7,"אבל לא טומאת נבלות עד שתמות","דהא וכי ימות מן הבהמה כתיב (ויקרא יא):"],[7,"עד שיתיז את ראשה","דהוה ליה גיסטרא ונבלה היא דחשובה מתה ואפילו היא מפרכסת:"],[7,"ריבה","הכתוב לטמא טומאת אוכלין ממה שריבה כו' דהא איכא כל הני דלגבי אוכלין אוכלא נינהו ונבלה לא מיקריא אע\"ג דשייכי בה:"],[8,"המכונס","הנאסף במקום אחד דהואיל ואחשביה לא בטיל וחשיב הבשר נבלה וחייב עליו אם נגע ונכנס למקדש או אכל קדש:"],[9,"גמ' תנינא","במתניתין דעור עצמו אין מצטרף לכזית דנבלה אע\"ג דשומרין הן:"],[9,"להא דתנו רבנן שומרין","יש לטומאה קלה ששומרין האוכל מצטרפין לכביצה לטומאת אוכלין אבל לא לכזית דנבלה שהיא טומאה חמורה לטמאות אדם וכלים:"],[10,"על כל זרע זרוע","לגבי טומאת אוכלין כתיב ואע\"ג דבההוא קרא טהור הוא כתיב ביה טעמא משום דלא הוכשר דסמיך ליה וכי יותן מים על זרע דהוכשר טמא הוא:"],[10,"קליפה","הוא שומר לאוכל והיא קליפה החיצונה החופה אותה בעודה שבולת אבל הנושרת כשכותשין במכתשת אוכל גמור הוא מדתנן לקמן (חולין דף קיט:) המלאין שבשבלין לא הוו שומר מכלל דהויא שומר וכן עדשין אותה קליפה שהעדשה חבויה לתוכה שאין מקפידין עליה בשעת זריעה אלא בשעת אכילה ומשום הכי נקט אשר יזרע:"]],[[0,"תרי מיעוטי כתיבי","תימה דבחד סגי וכן לעיל גבי העזים (דף קיג:):"],[2,"חד למעוטי מנותר וחד למעוטי מטומאה","תימה דלנותר וטומאה סגי בחד מיעוטא דילפינן מהדדי חלול חלול אף לקולא כדמוכח בסוף פרק בית שמאי בזבחים (דף מה:):"],[5,"מתני' העור והרוטב","משום דתנן פרק בהמה המקשה (לעיל חולין דף עז.) אשליא ואינה מטמאה טומאת אוכלין ולא טומאת נבלות תנא העור והרוטב ומאי דאפסקיה משום דתנא פרק בהמה המקשה (לעיל חולין דף עד.) מצא בה בן ט' חי טעון שחיטה וחייב באותו ואת בנו תנא אח\"כ אותו ואת בנו ואיידי דאיירי ביה בשחיטה שאינה ראויה תנא בתריה כסוי הדם ואיידי דתנא בכסוי הדם ונוהג בחיה ובעוף תנא גיד הנשה דנוהג בחיה ולא בעוף ואיידי דאיירי ביה בירך שנתבשל בה גיד הנשה בבליעת איסור תנא כל הבשר ובתריה הדר לעניינא קמייתא:"],[5,"האלל","איכא דמפרש בגמרא אף מרטקא ופי' בקונטרס גיד הצואר ואי תנא גידין ולא מרטקא הוה אמינא דמרטקא שהיא קשה לא מצטרף דלא הוי בכלל שאר גידים ואי תנא אלל ה\"א שאר גידים מטמו אפילו טומאת נבילות בצירוף:"],[5,"הקרנים","בגמרא מפרש מקום שחותכו ויוצא דם:"],[5,"והטלפים","ול\"ג וצפרנים דלא שייכי אלא בעוף ומתניתין לא איירי במילי דעוף מדלא קתני והחרטום כדקתני במשנה דמייתי בגמרא (שם) ואפשר דגרס וצפרנים וחרטום דלא פירש הכא [פירש] במשנה אחריתי ועל צפרנים מפרש בגמרא מקום המובלע בבשר ועל טלפים לא מפרש מידי ואפשר דבטלפים אף מה שאין מובלע בבשר צריך לבשר טפי מבצפרנים:"],[10,"שומר לטומאה קלה מנלן דתנא דבי רבי ישמעאל וכו'","ולהוציא ולהכניס לא אצטריך דמטמי דמיד נפיק כדמסיק וכי אצטריך לצירוף:"],[10,"חטה בקליפתה","והא דאמר בסוף כתובות (דף קיא:) חטה שנקברה ערומה ה\"ק אף כשנקברה ערומה יוצאה בכמה לבושים:"],[11,"ולא שומר לטומאה חמורה מנלן","וא\"ת ל\"ל קרא דמזרעים לא אתי שכן טומאתן מרובה כדפריך בסמוך וי\"ל דס\"ד לרבויי מריבויא דיטמא וא\"ת דאמר בפרק כל שעה (פסחים דף לג:) ענבים שנטמאו דורכן פחות פחות מכביצה דקסבר משקין מפקד פקידי ולא נטמאו המשקין עם האוכל ואמאי לא נטמאו בנגיעת הטומאה לקליפה משום שומר וי\"ל דאין שם משקין עליהם עד שיצאו לחוץ:"]]],[["יכול הנוגע כנגד בשר מאחוריו לא יהא טמא תלמוד לומר (ויקרא יא, כד) יטמא","מאי קאמר אמר רבא ואמרי לה כדי חסורי מיחסרא והכי קתני בנבלתה ולא בעור שאין עליו כזית בשר ועור משלימו לכזית","יכול שאני מוציא אף עור שיש עליו כזית בשר הנוגע כנגד בשר מאחוריו יכול לא יהא טמא ואפילו מעשה יד נמי לא עביד","תלמוד לומר יטמא","תנן התם כל שהוא יד ולא שומר טמא ומטמא ואינו מצטרף","שומר ואע\"פ שאינו יד טמא ומטמא ומצטרף לא יד ולא שומר לא טמא ולא מטמא","ידות היכא כתיבי דכתיב (ויקרא יא, לח) וכי יותן מים על זרע ונפל מנבלתם עליו טמא הוא לכם לכם לכל שבצרכיכם לרבות את הידות","וכתיב (ויקרא יא, לט) וכי ימות מן הבהמה אשר היא לכם לכם לכל שבצרכיכם לרבות את הידות יד להכניס ולהוציא","שומר להכניס ולהוציא לא צריך קרא ק\"ו מיד אתי ומה יד שאינה מגינה מכנסת ומוציאה שומר לא כ\"ש","שומר דכתב רחמנא למה לי ש\"מ לצרף","ואימא יד להכניס ולא להוציא שומר להכניס ולהוציא אבל יד להוציא ושומר לצרף לא","יד להכניס ולא להוציא לא מצית אמרת השתא עיולי מעיילא אפוקי מיבעיא","ואימא יד להוציא ולא להכניס שומר להוציא ולהכניס אבל יד להכניס ושומר לצרף לא","יד יתירא כתיב (ויקרא יא, לה) תנור וכירים יותץ וגו'","לכם לכל שבצרכיכם לרבות את הידות","הי מינייהו מייתר","לכתוב רחמנא בזרעים וליתו הנך מינייהו מה לזרעים שכן טומאתן מרובה","לכתוב רחמנא בתנור וליתי הנך מיניה מה לתנור שכן מטמא מאוירו","לכתוב רחמנא בנבלה וליתי הנך מינה מה לנבלה שכן מטמאה אדם ומטמאה במשא וטומאה יוצאה מגופה","חדא מחדא לא אתיא תיתי חדא מתרתי","הי תיתי לא לכתוב רחמנא בזרעים ותיתי מהנך מה להנך שכן מטמאין שלא בהכשר תאמר בזרעים שאין מטמאין אלא בהכשר","אמר רב הונא בריה דרב יהושע פירות שלא הוכשרו כתנור שלא נגמרה מלאכתו דמי","אלא פריך הכי מה להנך שכן מטמאין שלא בנגיעה תאמר בזרעים שאין מטמאין אלא בנגיעה","לא לכתוב רחמנא בתנור ותיתי מהנך מה להנך שכן אוכל","לא לכתוב רחמנא בנבלה ותיתי מהנך (אין הכי נמי אלא) יד דנבלה למה לי אם אינו ענין ליד נבלה תנהו ענין ליד דעלמא","יד להכניס יד להוציא שומר לצרף","ואכתי יד דנבלה אצטריך דאי לא כתב רחמנא בנבלה הוה אמינא דיו לבא מן הדין להיות כנדון מה הנך לא מטמא אדם אף נבלה לא מטמאה אדם","אלא יד דנבלה מיצרך צריך ושומר דנבלה הוא דלא צריך למאי הלכתא כתביה רחמנא אי לאיצטרופי אמרת לא מצטרף ולהוציא קל וחומר מיד אתי","אלא אם אין ענין לשומר דנבלה תנהו ענין ליד דנבלה ואם אינו ענין ליד דנבלה תנהו ענין ליד דעלמא יד להוציא יד להכניס ושומר לצרף"],[[1,"מאי קאמר","רישא קתני ולא בעור אלמא לאו נבלה מיקרי ופחות מכזית לאו שיעורא הוא והדר תני דמטמא:"],[1,"ועורה משלימו לכזית","ואשמעינן דאין שומר מצטרף לטומאת נבלות:"],[2,"יכול שאני מוציא כו'","שהנוגע כנגד הבשר לא יהא טמא דאפילו מעשה יד לא עבד להכניס ולהוציא טומאה לא נעביד האי שומר דכיון דאימעיט מאיצטרופי אפילו תורת יד האוכל לא ניהוי ליה דשאם נגע יד האוכל הטמא בדבר אחר ילפינן לקמן דמוציאה טומאה מן הטמא לטהור והאי שומר לאו יד הוא ושמירתו לא תשוייה אפילו לחשיבות יד תלמוד לומר יטמא:"],[4,"כל שהוא יד","עצם שאין בו מוח ובראשו האחד בשר:"],[4,"טמא","אם היה טהור ונגע היד בשרץ מכנסת טומאה לאוכל דאע\"ג דאיהו לאו אוכל הוא מקבל טומאה כאוכל עצמו:"],[4,"ומטמא","אם אוכל טמא הוא ונגע ידו באוכל טהור מטמאו:"],[4,"ואינו מצטרף","לכביצה:"],[5,"וכל שהוא שומר אע\"פ שאינו יד","כגון עור שכנגדו כזית בשר:"],[5,"טמא","אם היה טהור מקבל טומאה ומכניסה לאוכל:"],[5,"ומטמא","אם היה אוכל טמא ונגע שומרו בטהור מוציא שומר את הטומאה מזה לזה:"],[5,"לא יד ולא שומר","כגון שער:"],[7,"טמא הוא לכם לכל שבצרכיכם","לכל דבר שהוא צורך לכם באוכל הזה הכל טמא הרי לך שהיד מביאה טומאה לאוכל דהא יד גבי הבאת טומאה כתיב:"],[7,"וכי ימות וגו'","הרי יד להוציא דהא נבלה לאו בת הכנסה היא שהטומאה מגופה ויד דכתיב בה לטמויי אחריני כתיב:"],[7,"יד להכניס ולהוציא","כלומר הרי לנו יד להכניס דטומאת אוכלין ויד נבלה להוציא:"],[8,"שומר","דכתב רחמנא לעיל מעל כל זרע זרוע למה לי:"],[10,"ה\"ג ואימא יד להכניס ולא להוציא ושומר להכניס ולהוציא","כלומר יד האמורה באוכלין להכניס היא אבל לא להוציא ומנבלה לא ילפא להוציא כדאמרינן לקמן דשאני נבלה דטומאה חמורה היא וכי כתב שומר להוציא כתיב דלהכניס אתי בק\"ו מיד אבל יד להוציא ושומר לצרף לית לך:"],[11,"ומשני יד להכניס ולא להוציא לא מצית אמרת דהשתא עיולי מעיילא","ואע\"פ שעדיין לא ירדה לו טומאה אפוקי מיבעיא הלכך כיון דמכנסת כ\"ש דמוציאה ושומר אתי להכניס ולהוציא בק\"ו והאי דכתביה רחמנא לצרף כתביה:"],[12,"ואימא יד","דכתיבא באוכלים להוציא כתיבא ולא להכניס והכנסה לא אתי מהוצאה וכתב שומר לרבות בו אף הכנסה אבל יד להכניס ושומר לצרף לא ולקמיה משני מעיקרא כי כתיבא יד באוכלין אתחלת טומאה כתיבא דהיא הכנסה ומיהו השתא משני ליה שינויא אחרינא:"],[13,"יד יתירא כתיבא","ועל כרחך תרתי להוצאה לא איצטריך דל חד מינייהו להכנסה וכיון דאיתא הכנסה והוצאה ביד יליף שומר בק\"ו וכי כתביה רחמנא לצרף כתביה:"],[15,"הי מינייהו מייתר","כולהו להוצאה צריכי:"],[16,"וליתו הנך","תנור ונבלה:"],[16,"זרעים טומאה מרובה","שמקבלין טומאה מולדי טומאה תאמר בתנור שאינו מקבל טומאה אלא מאב הטומאה וכן מנבלה מרובה טומאת אוכלין כדתנן מתניתין ריבה לטמא טומאת אוכלין ממה שריבה לטמא טומאת נבלות:"],[17,"תנור מטמא אוכלין באוירו","שהתנור תחלה הוי ואוכלין שניים כדתניא בפסחים בפרק ראשון (דף כ:) דת\"ר תוכו אע\"פ שלא נגע מה תוכו האמור לטמא כו' אלמא תנור מטמא לאוכלין אע\"פ שאינן נוגעין בו תאמר בנבלה ובזרעים טמאין שאינן מטמאין אחרים אא\"כ נגעו בהן כל הנך דקאמר תיתי מיניה בבנין אב קאמר טימא כאן וטימא כאן מה מצינו כאן שהיד מוציאה טומאה לאחרים אף כאן יד מוציאה טומאה לאחרים:"],[20,"הי תיתי","איזו מהן לא תכתוב ותיתי מינייהו:"],[20,"ותיתי מהנך","הצד השוה שבהם שהן טמאין וידן מוציאה טומאתן לאחרים אף אני אביא זרעים טמאים שתהא ידן מוציאה טומאתן לאחרים:"],[21,"אמר רב הונא בריה דרב יהושע","הא דהכשר לאו פירכא היא דהיינו גמר מלאכה דידהו ותנור נמי בלאו גמר מלאכה לאו טמא הוא:"],[22,"מה להנך שכן מיטמאין","קבלו הטומאה שלא בנגיעה דהא אמרן בכל הבשר (לעיל חולין דף קטו:) דמה הצד פרכינן כל דהו:"],[24,"אלא יד דנבלה","מייתר דתיתי מהנך דכי פרכת מה לזרעים שכן טומאתן מרובה תנור יוכיח מה לתנור שכן מטמא אחרים מאוירו זרעים יוכיחו וחזר הדין הצד השוה שבהן שהן טמאין וידן מוציאה טומאה לאחרים אף אני אביא נבלה אלמא מייתר יד דנבלה להוציא:"],[24,"למה לי דאם אינו ענין לה","דהא אתיא במה הצד:"],[24,"תנהו ענין ליד דעלמא","לאוכלין ואם אינו ענין להוצאה דהא בדידהו יד כתיבא תנהו להכנסה הרי יד להכניס ולהוציא ושומר לצרף:"],[26,"שלא תאמר דיו","אי לא הוה כתיבא בגופה וגמרה מהנך הוה אמינא דיו ליד נבלה הלמדה מאלו להיות כאלו דמה אלו לא מטמו אדם אף נבלה הואיל ויד דידה מהנך אתיא לא תטמא אדם דרך ידה כגון תחב קיסם בכזית בשר נבלה להיות לו יד ונגע אדם בו לא יטמא עד שיגע בנבלה עצמה וכן עצם של נבלה עצמה נמי דהויא יד:"],[27,"ושומר דנבלה","דרבינן לה לעיל דאמר יכול אף עור שיש עליו כזית בשר הנוגע כנגד בשר מאחוריו לא יהא טמא ת\"ל יטמא לא צריך למיכתביה דלמאי הלכתא כתביה:"],[27,"אי לאצטרופי","הא מעטיה מהכי דקתני רישא בנבלתה ולא בעור שאין עליו כזית בשר ועור משלימו לכזית:"],[28,"תנהו ענין ליד דנבלה","שאף ע\"פ שאינו שומר תוציא:"],[28,"ואם אינו ענין לה","דהא בגופה כתיבא תנהו ענין ליד דעלמא ולהוציא לא אצטריך אלא להכניס. האי דנקט תנהו ענין ליד דנבלה והדר איצטריך ליה למימר תנהו ענין ליד דעלמא ולא נקט הכי אם אינו ענין לשומר דנבלה תנהו ענין ליד דעלמא הכי שייך למיתני שפיר מדכיון דיתורא דשומר בנבלה כתיבא תנהו ענין לנבלה דנבלה ונבלה היא וכיון דמשום יד אתא תנהו ענין ליד דעלמא דיד ויד הוא אבל שומר דנבלה להיות ענין ליד דעלמא לא שייך למימר:"]],[[9,"שומר דכתב רחמנא למה לי ש\"מ לצרף","וא\"ת לפי' ר\"ת ורבינו שמואל דבעו כביצה לקבל טומאה מנלן צירוף בשומר להכניס דאימא קרא אתא להוציא וי\"ל כיון דיד מכניס ומוציא ושומר מכניס ומוציא לענין צירוף שומר נמי לא שנא:"]]],[["ואימא אם אינו ענין לשומר דנבלה תנהו ענין לשומר דעלמא שומר להכניס ושומר לצרף אבל יד להכניס לא","אלא מעיקרא כי כתיבא יד אהכנסה כתיבא","אלא שומר דנבלה למה לי לגופיה","ולמאי אי לאצטרופי אמרת לא מצטרף אי להכניס ולהוציא ק\"ו מיד אתיא מילתא דאתיא בקל וחומר טרח וכתב לה קרא","אי הכי שומר דעלמא אימא לך להכניס ומלתא דאתי בקל וחומר טרח וכתב לה קרא","היכא דאיכא למידרש דרשינן","רב חביבא אמר שאני שומר דנבלה כיון דמעשה יד קא עביד איד שדינן ליה","מתקיף לה רב יהודה בר ישמעאל הא דתנן הפיטמא של רמון מצטרפת והנץ שלו אין מצטרף","ואמאי קרי כאן על כל זרע זרוע וליכא","ותו הא דתנן העור והרוטב והקיפה וכו' מצטרף לטמא טומאת אוכלים מנלן","אלא תלתא קראי כתיבי (ויקרא יא, לז) על כל זרע זרוע אשר יזרע חד לשומר דזרעים וחד לשומר דאילנות אידך לשומר בשר וביצים ודגים","אמר רב חייא בר אשי אמר רב יש יד לטומאה ואין יד להכשר","ור' יוחנן אמר יש יד לטומאה ולהכשר","במאי קמיפלגי איבעית אימא סברא איבעית אימא קרא","איבעית אימא קרא מר סבר מקרא נדרש לפניו ולא לפני פניו","ומר סבר מקרא נדרש לפניו ולפני פניו","איבעית אימא סברא מר סבר הכשר תחלת טומאה הוא ומר סבר הכשר לאו תחלת טומאה הוא","תניא כוותיה דרבי יוחנן כשם שיש יד לטומאה כך יש יד להכשר וכשם שאין מקבלין טומאה אלא לכשיתלשו כך אין מקבלין הכשר אלא עד שיתלשו","אמר רב אין יד לפחות מכזית ואין שומר לפחות מכפול","ורבי יוחנן אמר יש יד לפחות מכזית ויש שומר לפחות מכפול","מיתיבי ב' עצמות ועליהן ב' חצאי זיתים והכניס ראשיהן ב' לבית והבית מאהיל עליהן הבית טמא","יהודה בן נקוסא אומר משום רבי יעקב היאך שני עצמות מצטרפין לכזית"],[[0,"ואימא אם אינו ענין לשומר דנבלה תנהו ענין לשומר","דאוכל דהא שומר ושומר הוא דאע\"ג דכתיב בהו שומר אחרינא חד להכניס דהא לא כתיבא ביד דליתי שומר מינה וחד לצרף ושומר להוציא מיד יליף אבל יד להכניס לא איתרבאי:"],[1,"אלא מעיקרא כי כתיבא יד אהכנסה כתיבא","כלומר הא דפרכינן מרישא אימא יד להוציא ולא להכניס לאו פירכא היא דכי כתיבא יד באוכלין אתחלת טומאתן כתיבא כשהן מקבלין אותה מן השרץ וכיון דמכנסת כל שכן דמוציאה ושומר להכניס ולהוציא מק\"ו אתי שומר דזרעים לצרף:"],[2,"אלא שומר דנבלה ל\"ל","בשלמא כולהו צריכי ואפילו יד דנבלה שלא תאמר דיו אלא שומר דנבלה למה לי הא לא מצטרף:"],[3,"ואי להכניס ולהוציא בא","כיון דכתיבא יד בנבלה אתי שומר בק\"ו מינה:"],[4,"א\"ה","דאמרת טרח וכתב שומר מנא לך דמצטרף הא לאו צירוף בהדיא כתיבא ומשום דלא אצטריך להכניס ולהוציא שדית ליה אצירוף אימא להכניס ולהוציא אתא ואע\"ג דבקל וחומר מיד אתי מילתא דאתיא בק\"ו טרח וכתב לה קרא:"],[6,"רב חביבא אמר","לעולם כדאמרינן מעיקרא דשומר דנבלה דלא איצטריך תנהו ענין ליד ודקפרכת אימא תנהו ענין לשומר דעלמא אבל יד להכניס לא אשכחן לאו פירכא היא דכיון דמעשה יד עביד שאין מצטרף כשאר שומרים אלא מכניס ומוציא כמעשה יד מסתברא דיתורא דידיה דלא איצטריך:"],[6,"איד שדינן ליה","להיות ענין ליד דעלמא והשתא כולהו צריכי כל ידות דכתיבי להוציא צריכי דחדא מאידך לא אתיא כדאמרן ודנבלה משום שלא תאמר דיו שומר דנבלה להיות ענין ליד דהכנסה ושומר דאוכלים לצרף:"],[7,"הפיטמא של רמון","הוא שומר על פיו והנץ שומר אחר ע\"ג הפיטמא כמו שיש על אגוזים שומר ע\"ג שומר:"],[7,"אין מצטרף","דאין שומר ע\"ג שומר כדאמרינן לקמן פיטמא מיהא מצטרף ואמאי הא ליכא למימר כדרך שבני אדם מוציאין לזריעה הא לאו זרעים נינהו וכשנוטעין אילן אין נוטעין אלא יחור ואם נוטעין רמון כבר נשרה אותה פטמא שהיא כעין פרח שבראש התפוחים ומתניתין נמי דקתני עור מצטרף משום שומר הא לא כתיב שומר אלא בזרעים וטעמא משום דזרעי ליה בהדיה הוא:"],[10,"ג' קראי","זרע זרוע יזרע:"],[11,"יש יד לטומאה","להכניס ולהוציא כדאמרינן:"],[11,"ואין יד להכשר","אין תורת יד לענין הכשר שאם הוכשרה היד לא הוכשרו הזרעים:"],[14,"מקרא נדרש","לכל דנפקי ידות מיניה נדרש לפניו אטמא הוא ולא לפני פניו אוכי יותן מים דהוא רישא דקרא:"],[16,"תחלת טומאה הוא","ויש לו יד טומאה:"],[17,"וכשם שאין","זרעים מקבלין טומאה אלא לכשיתלשו כדאמרינן בת\"כ אם אתה אומר מחוברין טמאין טימאת את הכל שאין לך מחוברין שאין שרצים מצויין אצלם:"],[18,"פול","פחות הרבה מכזית:"],[18,"אין יד לפחות מכזית","אם יש אוכל פחות מכזית כגון פול או חצי זית בשר ולו יד והרי הן עם אוכלין כביצה ונגעה טומאה ביד הואיל ועיקרו אינו כזית ביחד אין חשוב להיות לו יד והכל טהור אבל יש שומר לפחות מכזית ובלבד שיהא כפול:"],[18,"וכן אין שומר לפחות מכפול","לא להצטרף לענין כביצה ולא להכניס ולהוציא כגון עצם ובו מוח פחות מכפול והוא עם אוכלין כביצה או עדשים בשרביטיהם:"],[19,"ורבי יוחנן אמר כו' ויש שומר לפחות מכפול","אבל יד לפחות מכפול לא מדלא ערבינהו ותני יש יד ויש שומר לפחות מכפול:"],[20,"והכניס ראשיהן השנים","אותן ראשין שאין בשר עליהן והן של מת:"],[20,"הבית טמא","המאהיל על היד כמאהיל על הבשר עצם בלא בשר מטמא במגע ובמשא ואינו מטמא באהל:"],[21,"היאך שני עצמות","אם היה עצם אחד ובראשו אחד כזית מודינא דיש לו יד להביא טומאה לבית אבל יד לפחות מכזית לא אמרינן:"]],[[1,"מעיקרא כי כתיבא יד אהכנסה כתיבא","הקשה רבי אליהו מנלן ידות בכלים דעלמא דמיד דזרעים ותנור ונבלה לא אתו דמה להנך שאין להם טהרה במקוה ונראה משום דדרשינן בתורת כהנים והנוגע בהן לרבות את הידות וההוא אפשר דלשאר כלים איצטריך ואי לא כתיב אלא ההוא קרא לחודיה הוה מוקמינן ליה בדמסתבר טפי:"],[17,"וכשם שאין מקבלין טומאה אלא לכשיתלשו","וא\"ת אדרבה יותר ראוי לתלות טומאה בהכשר דמה שאין מטמא זה תלוי בהכשר דמעיקרא לא הוכשרו וכ\"ת דאפשר באילן מלא פירות שנתלש והוכשר וחזר ונטעו אי אפשר לומר כן דהא כשחזר ונטעו בטל ליה הכשר כשהשריש שאפילו טומאה בטלה כדאמרינן (תרומות פ\"ט מ\"ז) גבי גידולי תרומה וי\"ל דפשיטא ליה שאין מקבלין טומאה אלא לכשיתלשו כדפי' בקונטרס שאם אומר מחוברין טמאין טימאת [את] הכל וקאמר דה\"נ אין מקבלין הכשר אלא לכשיתלשו אפילו לקבל טומאה אחר התלישה וא\"ת מההוא טעמא דפשוט לו בטומאה תפשוט לו בהכשר שאם אתה אומר כן הכשרת הכל במחובר וי\"ל דאין זה תימה כל כך אם נאמר דהוכשר הכל במחובר ע\"י גשמים שנופלין על הזרעים:"],[18,"אין יד לפחות מכזית","פי' בקונטרס כגון פול או חצי זית בשר ולו יד והרי הוא עם כביצה אוכלין ואין נראה דאפילו היה נוגע בחצי זית עצמו לא היה טמא מדאמרי' בפ\"ק (לעיל חולין דף כד:) התורה העידה על כלי חרס אפילו הוא מלא חרדל אלמא אי לאו אויר כלי חרס לא הוי כמו במחובר אע\"פ שנוגעין יחד ותנן נמי בפרק בתרא דחגיגה (דף כ:) הכלי מצרף כל מה שבתוכו לקדש אבל לא לתרומה ומבעיא לן בהקומץ רבה (מנחות דף כד.) אי דוקא דנגעי אהדדי או לא ואי נגיעה חשיב כמחובר א\"כ פשיטא דבלא נגיעה איירי דבנגיעה לא היה צריך צירוף כלי ונראה לפרש שזה חצי זית מחובר עם כביצה אוכלין אבל אינו מחובר כל כך ואם היה מגביה אותו היה ניתק אותו כביצה אוכלין מאותו פחות מכזית דלא הוי יד לשאר אוכל אלא לפחות מכזית ולפי' הקונטרס שמפרש בעלמא דאוכל כל שהוא מקבל טומאה א\"צ לומר שהוא מחובר עם שאר אוכלין אלא בעי אם מכניס טומאה לאותו חצי זית אבל להוציא אפילו היה זית שלם ונגע בו לא היה טמא דצריך כביצה ואפילו אם אין מקבל טומאה בכל שהוא מדאורייתא איכא למימר דמבעיא ליה אי מקבל טומאה מדרבנן דמדרבנן מקבל טומאה בכל שהוא:"],[20,"והבית מאהיל עליה הבית טמא","ויד למת נפקא לן במה הצד מנבלה ותנור דמה נבלה שאין מטמא באהל כו' ואי פרכת מה לנבלה שכן אוכל תאמר במת שאין אוכל כדאמרינן בפרק דם שחיטה תנור יוכיח מה לתנור שכן מטמא מאוירו נבלה תוכיח הצד השוה שבהם שמטמא וידיהם כיוצא בהם כו' וא\"ת לענין אהל נימא דיו וי\"ל דמעיקרא ודאי לא אשכחן בטומאה חמורה ידות הוה פרכינן על נבילה דיו אבל השתא דאשכחן יד בטומאה חמורה דהוי כגוף לענין מת נמי משוינן יד כגוף:"]]],[["ורב האי במאי אוקים לה אי ביד קשיא רישא","אי בשומר קשיא סיפא","איבעית אימא בשומר איבעית אימא ביד","איבעית אימא ביד והוא דאמר (כרבי יהודה) בן נקוסא ואיבעית אימא בשומר והוא דאמר כתנא קמא","ור' יוחנן אמר כולה ביד והוא דאמר כת\"ק","ת\"ש רבי יהודה אומר קולית שיש עליה כזית בשר גוררת כולה לטומאה אחרים אומרים אפילו אין עליה אלא כפול גוררת כולה לטומאה","ורב האי במאי מוקים לה אי ביד קשיא סיפא אי בשומר קשיא רישא","איבעית אימא ביד והוא דאמר כרבי יהודה ואיבעית אימא בשומר כאחרים","ורבי יוחנן אמר כולה בשומר והוא דאמר כאחרים","אחרים הא כפול קא אמרי","איידי דקאמר תנא קמא שיעורא קאמרי אינהו נמי שיעורא","אמר רבא דיקא נמי דבשומר עסקינן דקתני קולית שמע מינה","איתמר רבי חנינא אמר זהו שיעור ור' יוחנן אמר אין זה שיעור","אין זה שיעור והא קתני כפול איידי דקאמר ת\"ק שיעורא קאמרי אינהו נמי שיעורא","ת\"ש רבי אלעזר בן עזריה מטהר בשל פול ומטמא בשל קטנית מפני שרוצה במשמישן","כדאמר רב אחא בריה דרבא בקולחא ומשום יד","הכא נמי בקולחא ומשום יד ומאי במשמישן בתשמישן","ת\"ש דתנא דבי רבי ישמעאל (ויקרא יא, לז) על כל זרע זרוע (אשר יזרע) כדרך שבני אדם מוציאין חטה בקליפתה ושעורה בקליפתה ועדשים בקליפתן","בריה שאני","בעי רב אושעיא"],[[0,"ורב האי במאי מוקים לה","שלא יהא אחד מאלו חלוק עליו:"],[0,"אי ביד","שבעצם הזה אין בו מוח אבל בשר יש בראשו האחד:"],[0,"קשיא רישא","דקתני הבית טמא אלמא יש יד לפחות מכזית:"],[1,"ואי בשומר","כגון בעצמות שיש בהן מוח והכניס שני ראשיהן הריקנין לבית ומשום הכי הבית טמא דיש שומר לחצי זית ואע\"פ שאין המוח בבית שומר מכניס ומוציא טומאה ומביאה לבית. וא\"ת עצם הזה הנכנס לבית אינו שומר למוח שהרי אין המוח כנגדו אלא בראשו האחר ואנן תנן הנוגע כנגד הבשר מאחוריו דלא הוי שומר אלא מה שכנגד האוכל על כרחך שומר הוא שכל זמן שהקולית סתומה אוכל שבתוכה נשמר נפתחה אין מה שבתוכה נשמר:"],[1,"קשיא סיפא","דקא מטהר ר' יהודה בן נקוסא ורב אמר לעיל אין שומר לפחות מכפול הא לכפול יש שומר וחצי זית יתר על כפול. ואר' יוחנן נמי הוה מצי לאקשויי מרבי יהודה בן נקוסא כל היכי דמוקמת לה אי ביד אי בשומר מתנא קמא אי בשומר מוקמינן לה דמדנקט שני חצאי זיתים משמע דבד' וה' עצמות ובכל אחת פחות מכפול מודי הוא דטהור ור' יוחנן אמר יש שומר לפחות מכפול ומיהו לחד מינייהו פריך והדר מתרצי לה תרוייהו מר לטעמיה ומר לטעמיה:"],[3,"איבעית אימא ביד כו'","בין ביד בין בשומר ליכא לאוקמא דא\"כ רב דאמר כמאן הא רב ביד מטהר ובשומר מטמא ות\"ק מטמא בתרוייהו ורבי יהודה בן נקוסא מטהר בתרוייהו אלא כחדא מוקים וקאים כחד מינייהו. איבעית אימא ביד קאי והוא דאמר כרבי יהודה אבל בשומר אפילו רבי יהודה מודי:"],[3,"ואיבעית אימא בשומר","מוקי לה:"],[3,"והוא דאמר כתנא קמא","וביד אפילו תנא קמא מודי:"],[4,"ור' יוחנן","מוקי לה ביד ואשמעינן תנא קמא דיש יד לפחות מכזית דאי בשומר אפילו בד' עצמות נמי הוי מטמא דיש שומר לפחות מכפול אלא ביד קאי הילכך בעי חצי זית דניהוי מיהא כפול דמודי ר' יוחנן דאין יד לפחות מכפול כדפרישית לעיל מדלא עריב ותנא להו בשומר לא מצי לאוקומה דקשיא ליה אם כן אפילו ד' עצמות נמי דיש שומר לפחות מכפול:"],[5,"קולית","הוא עצם עליון של ירך ובו מוח תמיד רדונדי\"ל בלע\"ז:"],[5,"גורר את כולה לטומאה","אותו זית גורר את כל הקולית לטומאה שאם היה עם כביצה אוכלין ונגע השרץ בה בכל מקום שבה טמא:"],[6,"קשיא סיפא","דאחרים דהאמר רב אין יד לפחות מכזית:"],[6,"אי בשומר קשיא רישא","דקאמר ת\"ק כזית אין בציר מכזית לא ורב אמר אין שומר לפחות מכפול הא לכפול יש שומר:"],[8,"ורבי יוחנן אמר לך כולה בשומר והוא דאמר כאחרים","דיש שומר מיהא לפחות מכזית:"],[9,"הא כפול קאמרי","ורבי יוחנן אמר יש שומר לפחות מכפול:"],[10,"אמרי אינהו נמי שיעור","ולעולם לפחות מכפול נמי אמרי. וכל שכן דאי הוה מוקי לה ר' יוחנן ביד הוה ניחא ליה טפי הואיל והוא דאמר כאחרים אלא משום דקתני קולית ולא נקט עצם אחר אי הוה מוקי לה ביד ודוקא כפול קאמרי אחרים הוה מקשינן ליה והא קולית קתני וסתם קולית שומר היא ואפילו הכי קאמרי אחרים כפול ורבי יוחנן הכי גמיר לה דאחרים לאו דוקא כפול אמרו כדאמר לקמן רבי יוחנן אמר אין זה שיעור הילכך מוקי לה בשומר:"],[11,"דיקא נמי דבשומר עסקינן מדקתני קולית","וסתם קולית יש בה מוח:"],[12,"אתמר רבי חנינא אמר","האי כפול דקאמרי אחרים דוקא קאמרי וזה הוא שיעור דבציר מכפול ליכא שומר כרב:"],[12,"אין זה שיעור","לאו דוקא קאמרי:"],[14,"רבי אלעזר בן עזריה מטהר","בשומר של פול דלאו שומר הוא כגון אותן השרביטים שהפולים גדלין בהן קוש\"ט בלע\"ז מפני שהפולין גסין ואין צריכין לשומר דנוח למשמשן ולנקרן לפיכך אין שומר זה מכניס ומוציא ומצטרף כשאר שומרין:"],[14,"ומטמא בשל קטנית","דשומר הוא דדקים הן ואין יכולין לנקרן וניחא ליה שיהו באותם שרביטין ואל יתערב בהן פסולת:"],[16,"במשמישן","שממשמש בהן על ידי השרביטין. ורישא דהך מתניתין הכי שרביט שריקנו טהור שייר בו גרגיר אחד טמא שיש שרביטין הרבה וכגון שיש בין השרביט והפול כביצה ר' אלעזר בן עזריה מטהר בשל פול דאין שומר מצטרף לו לכביצה ומטמא בשל קטניות. אלמא יש שומר לפחות מכפול:"],[16,"בקולחא","הא דמטמא בשל קטנית לאו בשרביט ומשום שומר אלא בקלח נגעה טומאה ומשום יד דהשתא הוי האי יד יד לדבר חשוב שהוא יותר מכזית שהרי כל השרביטים מחוברין בו ובפול הואיל וגסים הן לא איכפת ליה דליהוי להו יד:"],[16,"בתשמישן","שמטלטלן באותו קלח ואותו קלח תשמיש לאוכל:"],[17,"עדשים בקליפתן","אלמא יש שומר לפחות מכפול:"],[18,"בריה שאני","וכי קאמר רב שאין שומר לפחות מכפול כגון חצי פול שאין ברייתו שלמה או בשר שיעור חצי פול ועור עליו שמשלימו לכביצה. ולעיל נמי גבי שרביטין מצי לתרוצי בריה שאני:"]],[[0,"ורב במאי מוקי לה אי ביד קשיא רישא","ה\"מ למימר לר' יוחנן אי ביד אי בשומר קשיא סיפא ולאו קושיא גמורה היא דמקשה לרב אלא פירוש בעלמא דמפרש מילתיה אליבא דכולהו תנאי:"],[4,"ורבי יוחנן אמר כולה ביד וכת\"ק","ה\"מ למימר כולה בשומר וכת\"ק דלת\"ק אפילו בשלשה עצמות שיש בכל אחד פחות מכפול מצטרפין לכזית ושני עצמות דנקט להודיעך כחו דר' יהודה בן נקוסא אלא משום דאמר הש\"ס לרב אי ביד קשיא רישא קאמר דרבי יוחנן מוקי לה ביד ולא קשיא רישא הוא הדין בשומר ומשום דלרבי יוחנן א\"ש בין ביד בין בשומר כת\"ק דייק מעיקרא אליבא דרב:"],[8,"ורבי יוחנן אמר כולה בשומר והוא דאמר כאחרים","וביד לא בעי לאוקומי אע\"ג דהוה ניחא טפי כדפירש בקונטרס משום דמשמע דבשומר מיירי והא דמוקי לה ביד לרב כי היכי דליקום כרבי יהודה דהלכתא כוותיה לגבי ר\"מ דאחרים היינו ר' מאיר:"],[12,"רבי יוחנן אמר אין זה שיעור","אין להקשות הא א\"ר יוחנן לעיל (חולין קיח:) יש יד לפחות מכזית ושומר לפחות מכפול וא\"כ ע\"כ אחרים לאו שיעורא קאמרי כדאקשינן ושנינן לעיל דהכא אתא לפרושי מילתא דאחרים דלא תטעה לאוקמיה ביד ולמימר דהוי דוקא ומהך מילתא לא הוה שמעינן דסבירא ליה כאחרים דדלמא הא דאיצטריך לאחרים דאין זה שיעור משום דהכי הוה שמיע ליה מרביה דהשתא נמי דסבר ר' יוחנן הכי צ\"ל כדפי' מדלא מוקי לה ביד והוי כפול דוקא כי היכי דמוקי לה רב ביד למיקם כר' יהודה אף ע\"ג דמשמע דבשומר מיירי הכי נמי ה\"ל לר' יוחנן לאוקומי ביד כי היכי דלהוי כפול דוקא:"],[14,"שרביט שריקנו","פירש בקונטרס קופא קוש\"ט ולא משמע כן דהא כתיב בכל הספרים שייר גרגיר אחד בכל שומר טמא מכלל דשרביט לאו היינו קופא שהוא שומר עצמו אלא הוא הקלח שהשומרים דבוקים בו שקורין ריי\"ס שריקנו שהוציא האוכל מן השומרים טהור:"],[14,"שייר גרגיר אחד לכל שומר ושומר טמא","וקס\"ד המקשה דמיירי כשנגע טומאה בשומר וכל הגרגרין שבשאר שומרים מצטרפין לכביצה אלמא יש שומר לפחות מכפול וקשיא לרבי חנינא דאמר הרי זה שיעור ואע\"ג דאליבא דאחרים קאמר מ\"מ פריך ה\"ל לפרושי מלתייהו כמו שמפרש רבי יוחנן דאין זה שיעור ולא לפלוגי אחרים אהך ברייתא ומשני בקולחא דנגע בקולחא ומשום יד ולא בשומר ולפי מה שפי' מייתי מינה שפיר ראייה לקמן גבי אוכל דקס\"ד דמיירי כגון שנגע בשומרים ומשום שומר ומצטרפין כל השומרים יחד אבל לפירוש הקונטרס דגריס שייר בה גרגיר אחד טמא צ\"ל דלקמן ס\"ד דמיירי בהרבה שרביטים כדפירש בקונטרס לקמן דאי לא מיירי אלא בחד א\"כ לא איירי מידי בצירוף דלא איירי אלא בשומר אחד:"],[15,"הכא נמי בקולחא ומשום יד","ואם תאמר א\"כ מ\"ל ריקנו ומה לי לא ריקנו כיון דקולחא הוי יד ליותר מכזית דלמאי דס\"ד מעיקרא ניחא דקמשמע לן דאף על גב דליכא כפול הוי שומר ויש לומר דקמשמע לן דאף על גב דליכא כזית במקום אחד אלא כאן גרגיר וכאן גרגיר הוי קולחא יד:"]]],[["שני שומרין מהו שיצטרפו","היכי דמי אילימא בזה על גב זה ומי איכא שומר על גב שומר","והתנן רבי יהודה אומר שלש קליפות בבצל פנימית בין שלמה בין קדורה מצטרפת אמצעית שלמה מצטרפת קדורה אין מצטרפת חיצונה בין כך ובין כך טהורה","רב אושעיא שומר אוכל שחלקו קמיבעיא ליה","כיון דהאי לא מגין אהאי והאי לא מגין אהאי לא מצטרפת","או דלמא כיון דהאי מגין אדידיה והאי מגין אדידיה מצטרפין","תא שמע רבי אלעזר בן עזריה מטהר בשל פול ומטמא בשל קטנית מפני שרוצה במשמישן","אמר רב אחא בריה דרבא בקולחא ומשום יד ומאי במשמישן בתשמישן","ת\"ש דתנא דבי רבי ישמעאל (ויקרא יא, לז) על כל זרע זרוע (אשר יזרע) כדרך שבני אדם מוציאין לזריעה חטה בקליפתה ושעורה בקליפתה ועדשים בקליפתן","כדאמר רב אחא בריה דרבא בקולחא ומשום יד","הכא נמי בשדרה ומשום שומר","בשלמא עיליתא צריכי לתתיתא אלא תתיתא מאי צריכי לעיליתא בחד דרא","ומי איכא כביצה אוכלין בחד דרא בחטי דשמעון בן שטח","השתא דאתית להכי חדא חטה נמי בחטי דשמעון בן שטח","גופא שני עצמות ועליהן שני חצאי זיתים והכניס ראשיהן שנים לבית והבית מאהיל עליהן הבית טמא","יהודה בן נקוסא אומר משום רבי יעקב היאך שני עצמות מצטרפין לכזית","אמר ריש לקיש לא שנו אלא עצם דהוי יד אבל נימא לא הויא יד ורבי יוחנן אמר אפילו נימא נמי הויא יד","איתיביה ר' יוחנן לר\"ל עור שיש עליו כזית בשר הנוגע בציב היוצא ממנו ובשערה שכנגדו טמא מאי לאו משום יד","לא משום שומר ומי איכא שומר על גבי שומר חלחולי מחלחל","מתקיף לה רב אחא בר יעקב אלא מעתה תפילין היכי כתבינן הא בעינן כתיבה תמה וליכא","אשתמיטתיה הא דאמרי במערבא כל נקב שהדיו עובר עליו אינו נקב","ואיבעית אימא כוליה משום יד כדאמר רבי אלעא במלאי שבין המלאים","הכא נמי בנימא שבין הנימין","והיכא אתמר דר' אלעא אהא מלאי שבשבלים מיטמאין ומטמאין ואינן מצטרפין מלאי למאי חזי אמר רבי אלעאי במלאי שבין המלאים","לישנא אחרינא אמרי לה","הכי נמי מסתברא דמשום שומר דאי סלקא דעתך משום יד נימא אחת למאי חזי","כדאמר ר' אלעא במלאי שבין המלאין הכא נמי בנימא שבין הנימין","והיכא איתמר דר' אלעאי אהא דתנן המלאי שבשבלים מיטמאין ומטמאין ואין מצטרפין מלאי למאי חזי אמר רבי אלעאי במלאי שבין המלאים","ואיכא דמתני לה"],[[0,"שני שומרין מהו שיצטרפו","לאוכל שבתוכן לכביצה:"],[2,"פנימית","היינו אותה לבנה הראשונה הראויה לאכול:"],[2,"קדורה","נקובה:"],[2,"מצטרפת","שהרי היא עצמה אוכל:"],[2,"אמצעית","שומר היא:"],[2,"שלמה מצטרפת","דהוי שומר:"],[2,"קדורה אינה מצטרפת","דלא הויא שומר:"],[2,"חיצונה טהורה","שאין שומר על גבי שומר חשוב שומר:"],[3,"שומר אוכל שחלקו","כגון אוכל כביצה ושומרו עליו וחלקו או כגון שני בצלים קטנים שאין בשניהם אלא כביצה עם שומריהם וקמבעיא ליה אי מצטרפי הני שומרין עם האוכל אי לא:"],[6,"ומטמא בשל קטנית","קא סלקא דעתיה ששנים ושלשה שרביטים מצטרפין לכביצה עם אוכלין שבהן דודאי אין בשרביט אחד כביצה אלמא שני שומרין מצטרפין עם שני אוכלין לכביצה אע\"ג דהאי לא מגין אהאי:"],[7,"בקולחא","האי מטמא ומטהר בקולחא קאי ומשום יד דהוי יד לכולהו שרביטין:"],[8,"חטין בקליפתן","אלמא חטין עם שומריהן מצטרפין לכביצה אלמא שני שומרין מצטרפין וה\"ה לאוכל שחלקו. וה\"נ הוה מצי לתרוצי בריה שאני אלא תירוצא דחיקא הוא:"],[9,"כדאמר רב אחא בקולחא ומשום יד","דיד אחד הוא:"],[10,"הך קליפה נמי בשדרה","קאמר בסאסא דשבלתא שהחטין קבועין בשדרה בהיקף סביב ומשום שומר דכל השבולת שלמה וכל הסאסא הויא חד שומר דכולן צריכין זה לזה שאם יפול אחד כולם נופלין ולא הוו שומרין:"],[11,"בשלמא עיליתא צריכי לתתייתא","כלומר דשורות עליונות שהחטין קבועין בהן צריכות שיהו שורות התחתונות קיימות שאם נשרה הקליפה התחתונה של שבולת נושרת הקליפה הסמוכה לה עד שיפלו כל הקליפות והחטין עד ראש השבולת:"],[11,"אלא דרא תתייתא מי צריכי לעילייתא","בלא עילייתא נמי מקיימי תתייתא ואפילו הכי מצטרפין שומרים דדרי עילייתא בהדי אוכלים תתאי ושומרין תתאי:"],[12,"בחד דרא","קאמר דמצטרפי שומרים דחד שומר הוא דמתוך שקבועים בדוחק מתקיימת ואם יטול אחד מבינתים יש ריוח לחבירו ליפול:"],[12,"חטי דשמעון בן שטח","כשתי כליות של שור הגדול במס' תענית (ד' כג. ע\"ש):"],[13,"השתא דאתית להכי","מתריצנא לך נמי דהא דקאמר חטין בקליפתן לאו דלצטרפו שני חטין עם שומריהם אלא אם יש בין חטה אחת וקליפתה כביצה כגון חטי דשמעון בן שטח מצטרף שומר לחטין:"],[16,"לא שנו אלא עצם דהוי יד אבל נימא","אחת לא חשיבא למיהוי יד דפסקא אלא שומר הויא ויש חומר ביד מבשומר דיד מביאה את הטומאה בכל ענין שהיא אבל שומר אם יש חתיכת עור ועליה בראשה אחד כזית בשר ונגע באחד מן הנימין בראש האחר טהור דשומר אין מביא טומאה כמעשה יד אא\"כ נגע כנגד הבשר כדאמרינן בריש פרקין (לעיל חולין דף קיח.) הנוגע כנגד הבשר מאחוריו:"],[16,"ורבי יוחנן אמר אפילו נימא הויא יד","ומביאה טומאה אפילו נגע בנימא שלא כנגד הבשר:"],[17,"בציב","חוט הבשר:"],[17,"מאי לאו משום יד","ושכנגדו לאו דוקא:"],[18,"לא משום שומר","כיון דאיכא כזית עביד שומר מעשה יד להכניס ולהוציא:"],[18,"שומר על גבי שומר","נימא על גבי עור:"],[18,"חלחולי מחלחל","ומנקיב נימא לעור ויורד על הבשר ולא הוי שומר ע\"ג שומר:"],[19,"אי חלחולי מחלחל תפילין היכי כתבינן","והלא העור חלול כנגד השער ובעינן כתיבה תמה שלמה ולא פסוקה דכתיב (דברים ו) וכתבתם שיהא כתיבה תמה:"],[21,"איבעית אימא כולה","ציב ושערה משום יד וכי קאמר דהוי יד בנימא שבין הנימין דאיכא נימין הרבה דאי מטלטל הבשר ע\"י נימין לא פסקי:"],[21,"מלאי","זקן העליון של שבולת:"],[23,"מיטמאין ומטמאין ואין מצטרפין","דיד היא ואינה שומר:"],[23,"למאי חזי","הא נפסק מאליו כשאוחזין בו:"],[23,"שבין המלאין","שאוחז בכל המלאין של שבולת ולא באחד מהן:"],[24,"לישנא אחרינא אמרי לה כו'","מאן דתני הך לישנא סבר דבנימין הרבה אמר ריש לקיש נמי דלא הוי יד ולותביה מהא מתניתא ותריץ ליה משום (יד) שומר והכי נמי מסתברא דמשום שומר מדקתני שערה דאי משום יד נימא אחת למאי חזיא לעולם משום יד ומאי שערה דקתני נימא שבין הנימין:"],[27,"המלאין שבשבלין מיטמאין ומטמאין","מוציאין ומכניסין טומאה לשבולותיה ואין מצטרפין דאינן שומר אלא יד:"],[28,"ואיכא דמתני לה","להא פלוגתא דר' יוחנן ור\"ל:"]],[[3,"שומר אוכל שחלקו","לא שחלקו לגמרי דא\"כ פשיטא דלא מצטרף כדפרישית לעיל ולהכי נקט נמי דוקא חלקו אבל שני אגוזים שהן שני אוכלים שלמים פשיטא דלא מצטרפין אלא מיירי כגון שיש כאן בשר ועליו עור וחלקו לעור והיה חציו מצד זה וחציו מצד זה ומייתי ראיה מר' אלעזר בן עזריה דמטמא בשל קטנית משום דכל השומרים שבשרביט מצטרפין אע\"ג דכל חד לא מגין אלא אדידיה וא\"ת ואמאי לא משני דאין השומרין מצטרפין ומיירי כגון שיש בין כל הגרגרין כביצה בלא שומרין והשומרין מכניסין ומוציאין ואין מצטרפין ואמאי משני ליה בקולחא ומשום יד וי\"ל דבלאו הכי ניחא ליה טפי לאוקומי בקולחא ומשום יד ומעיקרא לא הוה מוקי לה משום שומר אלא משום דבמשמישן הוה משמע ליה משום שומר אבל השתא דמפרש מאי במשמישן בתשמישן ניחא ליה טפי לאוקומא בקולחא:"],[12,"בחטי דר\"ש בן שטח","ועדשים נמי כעדשים דר' שמעון בן שטח שהיו כדינרי זהב ועם שומריהם יש בהם כביצה:"],[18,"לא משום שומר","וא\"ת אמאי קאמר ר\"ש לעיל אבל נימא לא הוי יד מטעם שומר מיהא ליטמא וי\"ל דלעיל מיירי בנוגע בנימא שלא כנגד הבשר וכן פירש בקונטרס וא\"ת ורבי יוחנן דמוקי לה משום יד אמאי נקט ובשער שכנגדו וצ\"ל דכשכנגדו לאו דוקא כדפירש בקונטרס:"],[28,"איכא דמתני לה אמתניתין כו' עד לא שנו אלא עצם","ה\"נ הוה מצי למימר לא שנו אלא קרנים וטלפים שהן עצמן משום שומר אלא איידי דנקט לעיל לא שנו אלא עצם נקט נמי הכא עצם:"]]],[["אמתניתין העור והרוטב והקיפה וכו' מצטרפין לטמא טומאת אוכלין","אמר ריש לקיש לא שנו אלא עצם דהוי שומר אבל נימא לא הויא שומר ור' יוחנן אמר אפילו נימא נמי הויא שומר","א\"ל ר\"ל לר' יוחנן ומי איכא שומר על גבי שומר חלחולי מחלחל","מתקיף לה רב אחא אלא מעתה תפילין היכי כתבינן הא בעינן כתיבה תמה וליכא","אישתמיטתיה הא דאמרי במערבא כל נקב שהדיו עובר עליו אינו נקב","איתיביה ר' יוחנן לריש לקיש עור שיש עליו כזית בשר הנוגע בציב היוצא ממנו ובשערה שכנגדו טמא מאי לאו משום שומר לא משום יד","נימא אחת למאי חזיא כדאמר רבי אילעא במלאי שבין המלאין ה\"נ בנימא שבין הנימין","והיכא איתמר דרבי אילעא אהא דתנן המלאי שבשבלין מטמאין ומיטמאין ואין מצטרפין מלאי למאי חזיא אמר רבי אילעא במלאי שבין המלאין:","והרוטב: מאי רוטב אמר רבא שומנא","א\"ל אביי הוא עצמו יטמא טומאת אוכלין אלא חלב דקריש","מאי איריא קריש כי לא קריש נמי דאמר ריש לקיש ציר שעל גבי ירק מצטרף לככותבת ביום הכפורים","התם משום יתובי דעתא הוא בכל דהו מיתבא דעתיה","הכא משום איצטרופי הוא אי קריש מצטרף אי לא קריש לא מצטרף:","והקיפה: מאי קיפה אמר רבה פירמא","א\"ל אביי הוא עצמו יטמא טומאת אוכלין אלא אמר רב פפא תבלין","תנן התם הקפה את הדם ואכלו או שהמחה את החלב וגמעו חייב","בשלמא הקפה את הדם ואכלו כיון דאקפיה אחשובי אחשביה אלא המחה את החלב וגמעו אכילה כתיבא ביה והא לאו אכילה היא","אמר ר\"ל אמר קרא (ויקרא ז, כ) נפש לרבות את השותה","תניא נמי גבי חמץ כה\"ג המחהו וגמעו אם חמץ הוא ענוש כרת אם מצה היא אין אדם יוצא בה ידי חובתו בפסח","בשלמא אם מצה היא אין אדם יוצא בה ידי חובתו בפסח (דברים טז, ג) לחם עוני אמר רחמנא והאי לאו לחם עוני הוא אלא אם חמץ הוא ענוש כרת אכילה כתיבא ביה","אמר ריש לקיש אמר קרא (שמות יב, טז) נפש לרבות את השותה","ותניא נמי גבי נבלת עוף טהור כה\"ג המחהו באור טמא בחמה טהור והוינן בה אכילה כתיב ביה","אמר ריש לקיש אמר קרא (ויקרא ז, כה) נפש לרבות את השותה אי הכי בחמה נמי בחמה איסרוחי מסרח","וצריכי דאי כתב רחמנא חלב חמץ לא אתי מיניה שכן לא היתה לו שעת הכושר נבלה לא אתי מיניה שכן ענוש כרת","ואי כתב רחמנא חמץ חלב לא אתי מיניה שכן לא הותר מכללו ונבלה לא אתיא מיניה שכן ענוש כרת","ואי כתב רחמנא בנבלה הנך לא אתיא מינה שכן מטמאה","חדא מחדא לא אתיא תיתי חדא מתרתי הי תיתי לא לכתוב רחמנא בנבלה ותיתי מהנך מה להנך שכן ענוש כרת","לא לכתוב רחמנא בחמץ ותיתי מהנך מה להנך שכן לא היתה להן שעת הכושר","לא לכתוב רחמנא בחלב ותיתי מהנך מה להנך שכן לא הותר מכללן תאמר בחלב שהותר מכללו","ומאי ניהו אילימא חלב בהמה לגבוה נבלה נמי אשתראי מליקת עוף לגבוה","ואלא חלב חיה להדיוט נבלה נמי אשתראי מליקה דחטאת העוף לכהנים","לעולם חלב חיה להדיוט ודקא קשיא לך כהנים כהנים משלחן גבוה קא זכו","והא דתניא הטמאים לאסור צירן ורוטבן וקיפה שלהן למה לי ליגמר מהני","צריכי דאי לא כתב רחמנא הוה אמינא דיו לבא מן הדין להיות כנדון מה התם עד דאיכא כזית אף הכא נמי עד דאיכא כזית"],[[0,"אמתניתין","דקתני עצמות מצטרפין ועל כרחך משום שומר דהא יד לא מצטרף אבל נימא לא הוי שומר ולא מצטרף דאין שומר על גבי שומר:"],[8,"שומנא","שומן שעל המרק:"],[9,"אמר ליה אביי","שומן למה לי לאצטרופי דקתני מצטרפין לטמא טומאת אוכלין בהדי בשר הא בפני עצמו לא ושומן אמאי לא אוכל מעליא הוא:"],[9,"חלב דקריש","לחה היוצאה מן הבשר שקורין גלייר\"א:"],[10,"ציר שעל גבי ירק","משקה היוצא מן הירק. ל\"א ציר שהיו מטבילין מאכלן בציר:"],[10,"מצטרפין לככותבת","ואע\"ג דלא קריש כיון דבהדי אוכל מיחבר אוכל הוא:"],[11,"ומשני התם","טעמא דיוה\"כ לאו משום אוכלא הוא דאי נמי לאו אוכלא כיון דמייתבא דעתיה מחייב דהא לא תעונה כתיב (ויקרא כג) וזה לא התענה אבל הכא אוכל ומשקה אין מצטרפין דהא לא שוו שיעורייהו. ואע\"ג דהתם נמי תנן (יומא דף עג:) אכל ושתה אין מצטרפין ה\"מ אכל ושתה דקים להו לרבנן דלא מייתבא דעתיה בהכי אבל ציר שע\"ג ירק קים להו לרבנן דמייתבא:"],[13,"קיפה","פונדרייל\"א דק שבבשר שצולל ליסוד הקדרה שקורין פונדרייל\"א:"],[14,"תבלין","באנפי נפשייהו ולא אכלי להו אינשי:"],[15,"הקפה","הקרישו על גבי האור:"],[17,"לרבות את השותה","מדכתיב (ויקרא ז) ונכרתה הנפש נפש משמע כל דבר המיישב דעתו של אדם ואפילו שותה כמו (בראשית כג) אם יש את נפשכם שהיא לשון תאוה וקורת רוח שהנפש נהנה ממנו:"],[18,"המחהו","התיכו לעוף טהור באור שקורין פונדר\"א וגמעו מטמא בגדים אבית הבליעה:"],[21,"המחהו בחמה","וגמעו טהור וטעמא מפרש לקמן:"],[22,"וכל נפש אשר תאכל נבלה וגו'","גבי נבלת עוף טהור כתיב (ויקרא יז):"],[31,"משלחן גבוה זכו","והיתרא משום גבוה הוא אבל לגבי הדיוט לא אשכחן דהותר:"],[32,"הטמאים","בשרצים כתיב וה\"א יתירא קא דריש:"],[32,"ליגמר","מחלב וחמץ ונבלה דמיחוי שלהם כמותם:"]],[[14,"הוא עצמו יטמא טומאת אוכלין","הוה מצי למימר יטמא טומאת נבלות א\"נ טומאת נבלות לא מטמא דאיכא מילי טובא דמטמא טומאת אוכלין ולא מטמא טומאת נבלות כדתנן (לעיל חולין דף קיז:) השוחט בהמה לעובד כוכבים ומפרכסת כו':"],[15,"הקפה הדם ואכלו","הקפהו בחמה מיירי כדפרשינן בהקומץ רבה (מנחות דף כא.) אבל באור לא דדם שבשלו אינו עובר עליו:"],[17,"לרבות השותה","וא\"ת ולמה לי קרא הא שתיה הויא בכלל אכילה כדדרשי' בפ\"ג דשבועות (דף כג.) מדכתיב ואכלת לפני וגו' מעשר דגנך תירושך וקרי תירוש אכילה וי\"ל דהתם במילי דשתיה כגון יין ושמן והכא במידי דבר אכילה דממחי להו ושתי להו:"],[19,"לחם עוני אמר רחמנא","הוה מצי למימר נמי אכילה כתיב ביה:"],[19,"אלא אם חמץ הוא ענוש כרת הא אכילה כתיב ביה","אע\"ג דהוא אסור בהנאה הנאת חמץ לית ביה כרת אלא לאו:"],[23,"חמץ לא אתי מיניה שכן לא היתה לו שעת הכושר","וא\"ת חלב נמי הוי לו שעת הכושר כשהיה במעי אמו דאפילו רבי יוחנן דאמר (לעיל חולין דף עה.) תלש חלב מבן ט' חי דחדשים גרמי בבן ח' מודה ויש לומר דחמץ כמו שהוא עתה היתה לו שעת הכושר ושוב לא נשתנה אבל חלב אחר שיצא לאויר העולם לא היתה לו שעת הכושר להיתר:"],[24,"חלב לא אתי מיניה שלא הותר מכללו","הקשה הר\"ר שמואל מוורדו\"ן לר' יוסי דלא חייש להא פירכא בפסחים (דף כג:) וחשיב חלב לא הותר מכללו דקאמר ורבי יוסי הגלילי אנן בבהמה קאמרינן בבהמה מיהא לא אשתרי וליכא למיפרך נמי מה לחמץ שכן אסור בהנאה דהא לר' יוסי הגלילי חמץ מותר בהנאה כדאמר התם וי\"ל דלרבי יוסי [הגלילי] ודאי אתא נפש לדרשה אחריתי:"],[27,"מה להנך שכן לא היתה להם שעת הכושר","דנבלה כמו שהיא עתה מתה לא היה לה שעת הכושר א\"נ מחיים היה בה איסור אבר מן החי ואפילו למ\"ד (לאו) לאיברים עומדת היה בה איסור שאינה זבוחה:"],[32,"והא דתנן הטמאים כו'","דתניא גרסינן דאינה משנה:"]]],[["וליכתוב רחמנא בשרצים וליתו הנך וליגמרו מינייהו","משום דאיכא למיפרך מה לשרצים שכן טומאתן במשהו","והא דתניא הטבל והחדש וההקדש והשביעית והכלאים כולן משקין היוצאין מהן כמותן מנלן","וכי תימא ליגמר מהנך מה להנך שכן איסור הבא מאליו הוו","תינח היכא דאיסור בא מאליו היכא דלאו איסור הבא מאליו מנלן","גמרינן מבכורים ובכורים גופייהו מנלן","דתני ר' יוסי פרי פרי אתה מביא ואי אתה מביא משקה הביא ענבים ודרכן מנין תלמוד לומר (דברים כו, ב) תביא","איכא למיפרך מה לבכורים שכן טעונין קרייה והנחה","אלא גמר מתרומה","ותרומה גופה מנלן דאיתקש לבכורים דאמר מר (דברים יב, יז) ותרומת ידך אלו בכורים","מה לתרומה שכן חייבין עליה מיתה וחומש","אלא גמר מתרוייהו מתרומה ובכורים מה לתרומה ובכורים שכן חייבין עליהם מיתה וחומש","אלא אתיא מתרומה וחד מהנך או מבכורים וחד מהנך","והא דתנן דבש תמרים ויין תפוחים וחומץ סיתווניות ושאר מיני פירות של תרומה רבי אליעזר מחייב קרן וחומש ור' יהושע פוטר","במאי פליגי בדון מינה ומינה ובדון מינה ואוקי באתרה קמיפלגי","דר' אליעזר סבר דון מינה ומינה מה בכורים משקין היוצא מהן כמותן אף תרומה נמי משקין היוצא מהן כמותן ומינה מה בכורים אפי' שאר מינין אף תרומה נמי אפילו שאר מינין","ורבי יהושע סבר דון מינה מה בכורים משקין היוצאין מהן כמותן אף תרומה משקין היוצאין מהן כמותן ואוקי באתרה מה משקין דקדשים בתרומה תירוש ויצהר אין מידי אחרינא לא אף משקין היוצאין מהן כמותן תירוש ויצהר אין מידי אחרינא לא","והא דתנן אין מביאין בכורים משקה אלא היוצא מן הזיתים ומן הענבים מני","רבי יהושע היא דאמר דון מינה ואוקי באתרה וגמר להו לבכורים מתרומה","והא דתנן אין סופגין את הארבעים משום ערלה אלא על היוצא מן הזיתים ומן הענבים מני","רבי יהושע היא דאמר דון מינה ואוקי באתרה וגמר להו לבכורים מתרומה"],[[0,"","שרצים איסור אכילתם בכעדשה כטומאתן דתני ר' יוסי בר' חנינא והבדלתם בין הבהמה הטהורה לטמאה וגו' פתח הכתוב באכילה וסיים בטומאה לומר לך מה טומאה בכעדשה אף אכילה בכעדשה במעילה בפרק קדשי מזבח (מעילה דף טז:) הילכך אי לא כתיב מיחוי בגופייהו ויליף מהנך ה\"א לא מחייב אמיחויין בפחות מכזית:"],[1,"מה לשרצים","דין הוא שיהא מיחוי שלהן כמותן:"],[1,"שכן טומאתן","ואיסורן במשהו:"],[2,"החדש","קודם שקרב העומר ועושה שכר מן השעורין:"],[2,"והשביעית","משקין היוצאין מהן נוהגת בהן שביעית וחייבין בביעור כמותן:"],[3,"מהנך","חלב וחמץ ונבלה:"],[3,"שכן איסור הבא מאליו","ותינח למילף מינייהו טבל וחדש ושביעית וכלאי הכרם אבל הקדש לא אתי מינייהו:"],[5,"בכורים","אין איסורן בא מאליו שע\"י שמפרישן הן קדושים:"],[6,"פרי","מראשית כל פרי:"],[6,"תביא","אשר תביא מארצך דהוה ליה למיכתב אשר מארצך:"],[7,"בכורים טעונין קרייה","ארמי אובד אבי:"],[7,"והנחה","על הרצפה והנחתו לפני ה':"],[11,"מה לתרומה ובכורים שכן חייבים עליהן מיתה","במזיד וחומש בשוגג וכי פרכת מה לתרומה שכן חייבין עליה מיתה וחומש ליכא למימר בכורים יוכיחו:"],[12,"מתרומה וחד מהנך","חמץ או נבלה דכי פרכת מה לתרומה שכן מיתה נבלה תוכיח מה לנבלה שכן איסור הבא מאליו תרומה תוכיח וחזר הדין הצד השוה שבהן שאסורין הן עצמן ומשקין היוצאין מהן כמותן אף אני אביא את אלו:"],[13,"סיתווניות","ענבים הנמצאין בגפנים בימות החורף שאין מתבשלין לעולם ועושין מהן חומץ:"],[13,"ושאר כל מיני פירות","חוץ מענבים וזיתים שדרכן בכך:"],[13,"מחייב קרן וחומש","אם אכלן בשוגג:"],[14,"במאי קמיפלגי","הואיל דילפינן תרומה מבכורים למשקין היוצאין מהן כמותן:"],[14,"בדון מינה ומינה","בכל גזירות שוות ובנין אב שבתורה שאנו למדים דבר מחבירו אי דיינינן ליה וגמרינן ליה לכל מילי או דון מינה מה שאנו צריכין לו ואוקי באתרה למילי אחרנייתא דמיפרשי בגופיה קמיפלגי:"],[15,"בכורים","מביאין מכל שבעת המינין:"],[15,"אף תרומה נמי","שהפרישה בפירות כגון תמרים ותפוחים כיון דתרומה נוהגת בפרי אף על גב דאינה נוהגת במשקין שלהן אלא בתירוש ויצהר בלבד הנך משקין כיון דמפירות תרומה אתו הרי הן כתרומה. והאי דון מינה ומינה לאו דוקא קאמר דהא תמרים ותפוחים גופייהו אין תרומתן מן התורה אלא מדברי סופרים והכי הוא דקאמרינן כיון דבמידי דאורייתא אית לן דון מינה ומינה ואי הואי תרומת תמרים דאורייתא הוה גמרי לה מבכורים למשקין היוצאין מהן כמותן הכי נמי רבנן בדידהו כעין דאורייתא תקון:"],[16,"ורבי יהושע סבר","אי נמי הוא דאורייתא לא הויין משקין היוצאין מהן כמותן דאית לן דון מינה ומינה ואוקי באתרה דון מינה למה שהיא צריכה ללמוד הימנה דהיינו שיהו המשקין ממנה כמותה ותו לא תדון מינה אלא העמד אותה במקומה:"],[16,"תירוש ויצהר","כתיבי בה ולא שאר משקין והנך משקין דנהגו בה תרומה הוא דילפינן מבכורים דאם קרא עליהן שם תרומה קודם שדרכן נאסרין משקה היוצא מהן אבל שאר משקין דלא כתיבא בהו תרומה אפילו היא כתיבא בפירות עצמן לא:"],[17,"אין מביאין בכורים משקה","לגמרי משמע אפילו הביא פירות ודרכן דאי בדרוכין ועומדין אפילו ענבים נמי לא דהא אמרן פרי אתה מביא ואי אתה מביא משקה:"],[18,"רבי יהושע היא דאמר","גבי תרומה לא קדישי דאית ליה דון מינה ואוקי באתרה וכיון דבתרומה לא מתסרי הדר גמר לבכורים מינה דהא דרבי רחמנא בהו תביא זיתים וענבים הוא דרבי:"],[19,"אין סופגין","משום משקה הבא מפירות ערלה:"],[20,"רבי יהושע היא דאמר","בתרומה לא מיתסרי ואתו בכורים גמרי מתרומה בהיקשא דאיקרו תרומה ואתיא ערלה וגמר מבכורים מגזירה שוה:"]],[[0,"ליכתוב בשרצים וליתו הנך כו'","ובמה הצד חד מכולהו לא אתי דחמץ מכולהו לא אתי שלא היה להם שעת הכושר וחלב נמי לא אתי מכולהו שכן לא הותרו מכללן אך קשה דתיתי נבלה מכולהו ושמא לא הייתי אומר אלא לענין איסור אכילה אבל לענין טומאת נבלת עוף טהור לא ואע\"ג דאפקיה בלשון אכילה לא יאכל לטמאה בה:"],[1,"שכן טומאתן במשהו","תימה דבכל מקום מזכיר כעדשה וכאן נקט משהו וכן בפרק השוחט והמעלה (זבחים דף קו:) דפריך לאו בחלב למה לי כו' תיתי משרצים טמאין מה לשרצים טמאין שכן מטמא בכל שהוא ומיהו בלאו הכי התם נראה דלא גרסינן ליה דלא אצטריך להזכיר משהו גבי חלב דהא חלב לא מטמא כלל וסופרים שבשו משום דבתר הכי קאמר ואי משרצים טהורים מה לשרצים טהורים שכן איסורן במשהו פירוש משום בריה וכתבו כמו כן גבי טמאים:"],[4,"היכא דלאו איסור הבא מאליו מנלן","וא\"ת בהי מבעיא ליה דחדש ושביעית איסור הבא מאליו ואי טבל הא יליף חלול חלול מתרומה בסוף אלו הן הנשרפין (סנהדרין דף פד.) ותרומה ילפינן מבכורים ובסמוך משמע דצריך למילף במה הצד ואי כלאים הא לא כתיב בהו אכילה והקדש נמי לא כתיב ביה אכילה ועוד דאיכא למילף חטא חטא מתרומה וצ\"ל דאכלאים בעי דאע\"ג דלא כתיב בהו אכילה סברא היא דלא אסרה תורה אלא כשהאיסור בעין ולעיל דפריך אלא חלב אכילה כתיב ביה בלאו הכי ה\"מ למיפרך אלא כיון דכתב בה בהדיא אכילה פריך מינה וה\"ר שמואל היה אומר דגבי חלב שהמחהו אי לא הוה כתיב ביה אכילה הוה מחייבין כיון שהוא גוף החלב וכן החמץ אלא שנמוח אבל משקה היוצא מכלאים אפילו לא כתיב בהו אכילה כמאן דכתיב בהו דמי שאין זה גוף הפרי ומה שפירש בקונטרס דכולהו קרי איסור הבא מאליו לבר מהקדש אי אפשר לומר כן אלא אכלאים קאמר כדפירשתי שאין זה איסור הבא מאליו שע\"י מעשה של זריעה נאסרין הכלאים וגם העבירה היה בשעת זריעה וא\"ת ושביעית היכי אתי מכולהו דאית בהו לאו ובשביעית עשה כלה לחיה מן השדה כו' וי\"ל דילפינן מטומאת שרצים דלא שייך בהו לאו:"],[6,"הביא ענבים ודרכן כו'","אע\"ג דשתיה בכלל אכילה בענבים וזיתים לענין הבאת בכורים לא כתיבא אכילה דתהוי שתיה בכלל פרי:"],[10,"מה לתרומה שכן חייב עליה מיתה וחומש","לרבי דאמר בסנהדרין (דף פג.) הזיד במעילה במיתה ע\"כ לאו אהקדש בעי לעיל כדפי' בקונט' דהא בהקדש נמי איכא מיתה וחומש לרבי:"],[12,"אלא אי מתרומה וחד מהנך כו'","פי' מנבלה ובכורים או תרומה או משרצים ובכורים או תרומה אבל לא כמו שפי' בקונטרס חמץ ובכורים או תרומה דמה להנך שכן יש בהן נטילת נשמה מיתה וכרת וכן מחלב ותרומה או בכורים לא אתי מהאי טעמא:"],[14,"דון מינה ומינה","פי' בקונטרס דלאו דוקא ומיהו אפשר דהוי דוקא משום דגן שהמחהו דתרומת דגן דאורייתא דרבי אליעזר מחייב דגן מדאורייתא ושאר מינין מדרבנן ורבי יהושע פוטר בדגן שהמחהו דדון מינה ואוקי באתרה תירוש ויצהר אין שאר מינין לא ואפילו דגן ולהכי פטר נמי בשאר מינין שאין להחמיר בהן יותר מדגן:"],[15,"אף תרומה אפילו שאר מינין","ואם תאמר אכתי אימא דוקא שבעה מינים שהבכורים נוהגים בהן ויין תפוחים מנלן וי\"ל כיון דהויא אפילו במילי דרבנן הויא בכולהו:"]]],[["והדר מייתי לה לערלה פרי פרי מבכורים:","והאלל: מאי אלל רבי יוחנן אמר מרטקא ור\"ל אמר בשר שפלטתו סכין","מיתיבי (איוב יג, ד) ואולם אתם טופלי שקר רופאי אליל כולכם בשלמא למאן דאמר מרטקא היינו דלאו בר רפואה הוא אלא למאן דאמר בשר שפלטתו סכין בר רפואה הוא","באלל דקרא דכ\"ע לא פליגי כי פליגי באלל דמתניתין","ת\"ש ר' יהודה אומר האלל המכונס אם יש כזית במקום אחד חייבין עליו ואמר רב הונא והוא שכנסו","בשלמא למ\"ד בשר שפלטתו סכין היינו דכי איכא כזית מיחייב אלא למ\"ד מרטקא כי איכא כזית מאי הוי עץ בעלמא הוא","אליבא דר' יהודה לא פליגי כי פליגי אליבא דרבנן ר' יוחנן אמר מרטקא נמי מצטרף וריש לקיש אמר דוקא בשר שפלטתו סכין אבל מרטקא לא מצטרף","האי בשר שפלטתו סכין היכי דמי אי דחשיב עליה אפי' באנפי נפשיה מיטמא ואי דלא חשיב עליה בטוליה בטליה","רבי אבין ורבי מיישא חד אמר מקצתו חישב עליו","וחד אמר מקצתו פלטתו חיה ומקצתו פלטתו סכין","תנן התם החרטום והצפרנים מיטמאין ומטמאין ומצטרפין חרטום עץ בעלמא הוא","אמר רבי אלעזר בחרטום תחתון תחתון נמי עץ בעלמא הוא אמר רב פפא תחתון של עליון","צפרנים אמר רבי אלעזר מקום המובלעים בבשר","קרנים אמר רב פפא במקום שחותכין ויוצא מהן דם:","כיוצא בו השוחט בהמה:","אמר רבי אסי שונין ישראל בטמאה ועובד כוכבים בטהורה צריכין מחשבה והכשר מים ממקום אחר","הכשר למה לי סופו לטמא טומאה חמורה וכל שסופו לטמא טומאה חמורה לא בעי הכשר","דתני דבי רבי ישמעאל (ויקרא יא, לח) וכי יותן מים על זרע מה זרעים שאין סופן לטמא טומאה חמורה צריכין הכשר אף כל שאין סופו לטמא טומאה חמורה צריך הכשר","ותניא א\"ר יוסי מפני מה אמרו נבלת עוף טהור צריכה מחשבה ואינה צריכה הכשר מפני"],[[1,"מרטקא","גיד השדרה והצואר והוא רחב ולבן וקשה מאד וקורין אותו ייבו\"ל:"],[1,"בשר שפלטתו סכין","כשמפשיטין את הבהמה פעמים שהסכין פולט מן הבשר אצל העור ולא חשיב. ולקמיה פריך היכי דמי דאצרופי מצרף ובאפי נפשיה אין מקבל טומאה:"],[2,"ואולם אתם טופלי שקר","איוב אמר לחביריו מחברי דברי שקר אתם ודבר שאין בו רפואה אתם אומרין לרפואתי. ומרטקא משנפסק אין לו רפואה להחבר עוד:"],[2,"בשר שפלטתו סכין בר רפואה הוא","המדלדל בשר מן החי פעמים שקושרין אותו במקומו והוא נדבק ומעלה ארוכה:"],[4,"המכונס","הנאסף יחד יפה:"],[4,"חייבין עליו","משום נבלה בין שאוכלו בין שנוגע בו ונכנס למקדש ופליג אמתני' דקתני אבל לא טומאת נבלות:"],[4,"והוא שכנסו","דאחשביה וגלי דעתיה דלא בטליה מעיקרא אבל מתכנס מאליו או ע\"י תינוקות שלא במתכוין לא פליג ר' יהודה דליהוי נבלה:"],[5,"בשלמא למ\"ד","אלל היינו בשר שפלטתו סכין היינו דמחייב דאיכא למימר כיון דכנסו אחשביה והדר למילתיה וגלי דעתיה דלא בטליה מעיקרא:"],[6,"באלל דר' יהודה לא פליגי","דודאי רבי יהודה אבשר שפלטתו סכין קאי ורבי יוחנן נמי מודי דבשר שפלטתו סכין איקרי אלל ובמרטקא הוא דפליגי ולת\"ק ר' יוחנן אמר מרטקא נמי מקרי אלל כדאשכחן בקרא ואלל דמתני' דקאמר מצטרף בכולהו אלל קאמר דמצטרפי ובאפי נפשייהו לא מטמו ואתא רבי יהודה למימר באלל מרטקא מודינא דלא הוי בשר באנפי נפשיה לענין נבלות אבל בשר שפלטתו סכין אם חזר וכינסו גלי אדעתיה דלא בטליה וחייבין עליו משום נבלה:"],[6,"אבל מרטקא לא מצטרף","דעץ בעלמא הוא:"],[7,"אי דחשיב עליה","אפילו בתר הכי:"],[7,"באנפי נפשיה","נמי ליטמא טומאת אוכלין דקי\"ל דמחשבה שויא אוכלא כל מידי דמצי למיכליה ואע\"ג דלאו אורחיה כדאמרן בפרק בהמה המקשה (לעיל חולין דף עז:) עור ששלקו ושליא שחישב עליה מטמא טומאת אוכלין ונהי דתו לא הדר הוי בשר לענין טומאת נבלות דהא נעשה עור בבטולו הראשון אבל לאוכלו מיהא הוי לטמא טומאת אוכלין אם נגע בשרץ דלא גרע מעור ששלקו:"],[8,"מקצתו חישב עליו","ולא פי' איזה קצת הלכך כביצה מיניה לא מקבל טומאה דהא לא חישב על כולו אבל כי מצטרף בהדי שאר אוכלין מצטרף ההוא קצת מחשבה דאית ביה לאשלומי שיעורא:"],[9,"פלטתו חיה","נשכה כלב ודלדל מן הבשר לצד העור ואח\"כ שחטה והפליט גם הסכין עוד ואין ידוע אי זה מהן פלטה חיה ואיזה סכין וההוא דפלטתו חיה לא בטיל מסתמא וההוא דסכין בטליה מדעת וכולה בדלא חשיב עליה הלכך כי הוי בהדי שאר אוכלין מצטרף ההוא קצת דחיה בהדייהו ולטומאת נבלות לא ואע\"ג דפלטתו חיה דמתניתין רבי עקיבא היא דאמר העור מבטלו מטומאת נבלות ואפילו פלטתו חיה לקמן (חולין דף קכב.):"],[10,"תנן התם","במסכת טהרות (פ\"א מ\"ב) בסדר טהרות גבי נבלת עוף טהור:"],[10,"החרטום","בי\"ק בלע\"ז:"],[10,"מיטמאין","אם קבל העוף טומאה מן השרץ אלו נעשין יד להכניס ולהוציא טומאת. עוף אין לו טומאת מגע משום נבלה אא\"כ קבלה מאחרים שהרי אין לך אלא האמור בה טומאת אכילה לטמא בבית הבליעה:"],[10,"ומצטרפין","לכביצה:"],[11,"תחתון של עליון","קליפת רצועה דקה יש בתוך הפה דבוקה לחרטום בעליון לארכו:"],[12,"צפרנים","היכא הוו אוכל:"],[12,"מקום המובלע בבשר","שרשי הצפרנים:"],[14,"השוחט בהמה טמאה לעובד כוכבים","הא פרישית לה (לעיל חולין קיז:) דכיון דדכוותה בשחיטת ישראל בטהורה משויא לה אוכלא בעודה מפרכסת ולישראל שריא דהא בשחיטה תליא להו מילתא השתא נמי הואיל וישראל שחטה שחיטה מעליא אע\"ג דבטמאה לא שייכא שחיטה ולעובד כוכבים לא משתרי עד שתמות דאבר מן החי הוא לגביה אפ\"ה מהניא מחשבת ישראל להאכילה לעובד כוכבים לשויא אוכלא בעודה מפרכסת וכ\"ש טהורה שאוכל היתר גמור הוא בעודה מפרכסת והא דאמרינן אסור לאכול מבהמה קודם שתצא נפשה מדרבנן הוא וכן עובד כוכבים בטהורה תניא נמי לקמן דהואיל וטהורה היא ואשכחן היתר בטהורה מפרכסת ששחטה ישראל השתא נמי כי שחטה עובד כוכבים הויא אוכל לטמא טומאת אוכלין מן השרץ שאם תחזור ותגע באוכלין אחרים קודם שתמות ותעשה נבלה תטמאם אבל ישראל בטהורה אין צריכה מחשבה ועובד כוכבים בטמאה לא מהניא לה מחשבה בעודה מפרכסת דלא אשכחן היתר בדכוותה:"],[15,"שונים","יש תנאים ששונים שישראל בטמאה צריך מחשבה להאכילה לעובד כוכבים ואי לא חישב לא הויא אוכל עד שתמות וכן עובד כוכבים בטהורה:"],[15,"והכשר","ממקום אחר הכשר מים דדם שחיטה דילה לא מכשר לה דלא איקרי משקה אלא דם חללים כדאמרינן בהשוחט (לעיל חולין דף לה:) ומיהו דם שחיטה הוגנת מכשיר דאיתקש למים דכתיב על הארץ תשפכנו כמים כדאמרינן בהשוחט (שם) אבל דעובד כוכבים לאו דם חללים הוא ולא דם שחיטה הוא והוי כדם מגפתו וכדם המת דחלל לא מיקרי אלא על ידי גיסטרא ומצואר כדאמרינן בסוטה (דף מה:) לתת אותה על צוארי חלל רשע:"],[17,"הרי סופה לטמא טומאה חמורה","אדם וכלים בכזית ואפילו במשא כשתמות:"],[17,"זרעים","אינן נעשין אב הטומאה עולמית ואפילו נגעו במת שהוא אבי אבות ואינן נעשין אב לטמא אדם וכלים דמהיכא נפקא דנוגע במת מטמא אדם מהאי קרא דכתיב (במדבר יט) וכל אשר יגע בו הטמא יטמא והנפש הנוגעת באותו טמא תטמא עד הערב וכי כתיב האי קרא בדבר שיש לו טהרה בהזאה ובטבילה כתיב דכתיב לעיל מיניה והזה הטהור על הטמא וגו' ובההוא טמא קאי והנפש הנוגעת יצאו אוכלין ומשקין וכלי חרס הואיל ואין להם טהרה במקוה אין נעשין אב הטומאה:"],[18,"נבלת עוף טהור צריכה מחשבה","לקבל טומאת אוכלים מן השרץ שאם לא חישב עליה לאוכלה אינה מקבלת טומאה ואם חזרה ונגעה באוכלים לא נטמאו:"],[18,"ואינה צריכה הכשר","משנה היא במסכת טהרות (פ\"א מ\"א) שלשה עשר דברים נאמרו בעוף טהור וזו אחת מהן:"]],[[0,"והדר מייתי [לה] לערלה פרי פרי מבכורים","וא\"ת דבפ' כל שעה (פסחים כד:) פשיט מהך משנה דכל איסורים שבתורה אין לוקין עליהם אלא כדרך הנאתן והכא קאמר משום דגמר לה מבכורים וי\"ל דרבוי דהכא צריכי דלא נימא זיעה בעלמא הוא:"],[1,"מרטקא","פי' ר\"ח בשר מת וכן נראה לר\"ת ולא כפי' הקונטרס שפי' גידי הצואר מדאמרינן פרק כל הפסולים (זבחים דף לה.) פגל באלל נתפגלה מוראה פגל במוראה לא נתפגלה אלל ובעוף אין גידי צואר קשין ומוראה לא שייך אלא בעוף ולמאן דמפרש בשר שפלטתו סכין לא קשה ליה מהתם דהא אמרי' בסמוך דלכ\"ע מרטקא נמי הוי אלל:"],[4,"ר' יהודה אומר חייבים עליו","הא דלא קאמר מטמא טומאת נבלות דלא תימא מדרבנן להכי קאמר חייבין עליו:"],[4,"והוא שכנסו","תימה מה שייכא מחשבה לאיסור דגבי טומאה שייך לחלק דאי מבטל ליה עץ בעלמא הוא אבל משום דבטליה לא משתרי באכילה לכך נראה דחייבין עליו לא מיירי לענין אכילה דלא צריך כנסו אלא לענין אם נכנס למקדש כמו שפי' בקונטרס בלשון אחר והא דלא נקט טמא דלא תימא מדרבנן כדפי' וכן נראה דאי אאכילה הא כיון דאכלו אין לך כינוס גדול מזה:"],[6,"ורבי יוחנן אמר אף מרטקא מצטרף","ולאו בכה\"ג דהוי שומר דא\"כ מ\"ט דר\"ל עור ועצם מצטרפים משום שומר וצירוף שומר מקראי דרשינן לעיל (חולין דף קיח.) אלא מיירי כגון שיש בראשו כזית בשר דאע\"ג דלא הוי שומר מצטרף דראוי הוא שיאכל אגב בשר וריש לקיש סבר דלא מצטרף דאין ראוי לאכילה דעץ בעלמא הוא:"],[10,"ה\"ג במשנה בטהרות החרטום והצפרנים מטמאין כו'","ולא גרסינן בה קרנים וקרנים דמפרש בה רב פפא בסמוך אמתני' דהכא קאי:"]]],[["שסופה לטמא טומאה חמורה","אמר חזקיה הואיל ויכול לגוררה ולהעמידה על פחות מכזית","א\"ל ר' ירמיה לרבי זירא ומי אמר חזקיה הכי והא איתמר שחט בה שנים או רוב שנים ועדיין היא מפרכסת חזקיה אמר אינה לאברים ר' יוחנן אמר ישנה לאברים","חזקיה אמר אינה לאברים מתה היא רבי יוחנן אמר ישנה לאברים לאו מתה היא","א\"ל יצתה מכלל חיה ולכלל מתה לא באת","גופא שחט בה שנים או רוב שנים ועדיין היא מפרכסת חזקיה אמר אינה לאברים ר' יוחנן אמר ישנה לאברים אמר ר' אלעזר נקוט להא דר' יוחנן בידך דתני רב אושעיא כוותיה","דתני רב אושעיא ישראל ששחט בהמה טמאה לעובד כוכבים שחט בה שנים או רוב שנים ומפרכסת מטמאה טומאת אוכלין אבל לא טומאת נבלות","אבר הפורש ממנה כפורש מן החי ובשר הפורש ממנה כבשר הפורש מן החי ואסור לבני נח ואפי' לאחר שתצא נפשה","שחט בה אחד או רוב אחד אינה מטמאה טומאת אוכלין נחרה אין בה טומאה של כלום","ועובד כוכבים ששחט בהמה טהורה לישראל ומפרכסת מטמאה טומאת אוכלין אבל לא טומאת נבלה","אבר הפורש ממנה כפורש מן החי ובשר הפורש ממנה כפורש מן החי ואסור לבני נח ואפילו לאחר שתצא נפשה","שחט בה אחד או רוב אחד אינה מטמאה טומאת אוכלין נחרה אין בה טומאה של כלום","שחט עובד כוכבים במקום שאין עושה אותה טרפה ובא ישראל וגמרה כשרה","שחט ישראל בין במקום שעושה אותה טרפה ובין במקום שאין עושה אותה טרפה ובא עובד כוכבים וגמר שחיטתו פסולה","הרוצה שיאכל מבהמה קודם שתצא נפשה חותך כזית בשר מבית שחיטתה ומולחו יפה יפה ומדיחו יפה יפה וממתין לה עד שתצא נפשה ואוכלו אחד עובד כוכבים ואחד ישראל מותרין בו","מסייע ליה לרב אידי בר אבין דאמר רב אידי בר אבין א\"ר יצחק בר אשיין הרוצה שיבריא חותך כזית בשר מבית שחיטה ומולחו יפה יפה ומדיחו יפה יפה וממתין לה עד שתצא נפשה אחד עובד כוכבים ואחד ישראל מותרים בו","בעי ר' אלעזר שהה בה דרס בה מהו","א\"ל ההוא סבא הכי א\"ר יוחנן צריכה הכשר שחיטה כבהמה טהורה הכשר למאי אמר רב שמואל בר יצחק בדיקת סכין","בעא מיניה רבי זירא מרב ששת מהו שתציל על הבלועין שבתוכה","א\"ל מטמאה טומאת אוכלין ומצלת א\"ל אינה מטמאה טומאת נבלות ולא תציל","אמר אביי אינה מצלת על הבלועים שבתוכה דהא מטמאה טומאת אוכלין והרובעה חייב דהא אינה מטמאה טומאת נבלה:","רבי יהודה אומר האלל [וכו']: אמר רב הונא והוא שכנסו","ואמר רב הונא שני חצאי זיתים שישנן על גבי העור העור מבטלן"],[[0,"שסופה לטמא טומאה חמורה","אדם ובגדים אם יאכלנה הילכך אינה צריכה הכשר דילפינן מזרעים. וטעמא דמחשבה משום דסתמא לאו לאכילה קיימא ובכפרים קיימינן שאין רגילים לאכול עופות אבל בכרכים תנן (עוקצים פ\"ג משנה ג) דאין צריכין מחשבה דסתמא לאכילת עובדי כוכבים עומדת:"],[1,"אמר חזקיה","שאני מתניתין דבמפרכסת קיימינן שעדיין אין בה טומאה חמורה וסופה נמי שמא לא תבא לידי טומאה חמורה שהרי הוא יכול לגוררה לגירורים דקים פחותים פחותים מכזית עד שתכלה כולה ושוב לא תטמא טומאת נבלות אבל נבלת עוף טהור כבר מתה וראויה לטמא טומאה חמורה:"],[2,"ומי אמר חזקיה הכי","אלמא סבירא ליה לחזקיה הא דתנן דאין טומאת נבלות במפרכסת:"],[2,"שחט בה","בטמאה:"],[2,"אינה לאברים","אין בן נח מוזהר עליה משום אבר מן החי וכ\"ש בטהורה דליכא מידי דלישראל שרי ולעובד כוכבים אסור ואפילו רבי יוחנן מודי בה בטהורה:"],[4,"א\"ל","מודה חזקיה דאינה מטמאה כנבילה ואע\"פ שמותרת לבני נח דיצאה מכלל חיה ולכלל מתה לא באת ובטומאת נבלות כתיב וכי ימות:"],[5,"דתני רב אושעיא כוותיה","דאסורה לבני נח:"],[6,"מטמאה טומאת אוכלין","אם נגעה בשרץ וחזרה ונגעה באוכלין הואיל וישראל שחטה שחיטה מעלייתא וחישב עליה להאכילה לעובד כוכבים כדפרישית לעיל:"],[7,"כפורש מן החי","ומטמא מיד כאבר מן הנבלה דאמרי' בהאי פירקא (לקמן חולין דף קכח:) אבר מן החי מטמא כנבלה:"],[7,"ובשר הפורש ממנה כפורש מן החי","אין בו טומאה דבשר הפורש מן החי טהור ולהכי הוי כמן החי שאסור לבני נח:"],[7,"אפילו לאחר שתצא נפשה","הואיל ונחתך מחיים והיינו כר' יוחנן:"],[8,"שחט בה אחד אינה מטמאה טומאת אוכלין","דלא אשכחן היתר אכילה בדכוותה לא לישראל ולא לבני נח וכן בנחרה ועודה מפרכסת:"],[9,"מטמאה טומאת אוכלין","הואיל ויש היתר אכילה בדוגמתה אם שחטה ישראל השתא נמי מהניא לה הך מחשבת עובד כוכבים לצורך ישראל לשוייה אוכל:"],[13,"במקום שאין עושה אותה טרפה","כגון חצי קנה:"],[13,"שחט ישראל","וגמר עובד כוכבים הואיל וגמרו ביד עובד כוכבים טרפה:"],[14,"יפה יפה","יותר מבשר אחר מפני שלא הספיק דמו לצאת וכשחותכו נבלע בתוכה לפי שכשהבהמה מוציאה נשמה היא מתאנחת ומוציא דמה יפה:"],[14,"וממתין לה עד שתצא נפשה","כדתניא בארבע מיתות (סנהדרין דף סג.) מנין לאוכל מבהמה קודם שתצא נפשה שהוא בלא תעשה שנאמר לא תאכלו על הדם ואסמכתא דרבנן בעלמא היא:"],[14,"אחד עובד כוכבים ואחד ישראל מותרים בו","דהואיל ומותר לישראל הותר אף לעובד כוכבים דליכא מידי דלישראל שרי ולעובד כוכבים אסור. אבל הנך דלעיל שחיטת טמאה וכן שחיטת עובד כוכבים בטהורה אין בה היתר לישראל ולעובד כוכבים נמי לא משתריא דחיה היא:"],[15,"מסייע ליה לרב אידי","הא דקתני שאף העובד כוכבים מותר בו:"],[15,"שיבריא","בשר זה טוב לרפואה:"],[16,"בעי רבי אלעזר","מתניתין דישראל בטמאה ועובד כוכבים בטהורה דטעמא דמשוינן לה אוכלא משום שחיטה היא דהא נחרה אין בה טומאה:"],[16,"שהה בה או דרס מהו","מי הוי כנחירה ולא מטמאה:"],[17,"כבהמה טהורה","כאילו מטהרה לאכילה:"],[17,"למאי","הלכתא קא דייק כולי האי הכשר שחיטה בטהורה:"],[18,"מהו שתציל על הבלועין שבתוכה","ישראל בטמאה ועובד כוכבים בטהורה ומפרכסת ובלעה כלים בחייה והרי היא באהל המת מהו שתציל עליהן כדאמרן בבהמה המקשה (לעיל חולין דף עא:) בלע טבעת טהורה ונכנס לאהל המת לא נטמאה הכא מאי כיון דאינה מטמאה טומאת נבלות חיה היא או דילמא כיון דמטמאה טומאת אוכלין אינה מצלת דלאו בלוע הוא. ובישראל בטהורה לא מיבעי לן דודאי אינה מצלת הואיל ואף באכילה מותרת ועובד כוכבים בטמאה פשיטא לן דמצלת הואיל ואין בה טומאה של כלום אלמא חיה היא:"],[19,"א\"ל מטמאה טומאת אוכלין","אלמא מתה היא:"],[19,"ומצלת","בתמיה:"],[20,"אמר אביי אינה מצלת כו'","לחומרא:"],[20,"חייב","מיתה במזיד וחטאת בשוגג:"],[21,"והוא שכנסו","דגלי דעתיה דלא בטליה מעיקרא אבל נתכנס מאליו כמו שכנסוהו תינוקות אחר הפשט לא הואיל ובטל מתחלה ונעשה עור תו לא הדר הוי בשר דלטומאת אוכלין הוא דמהניא מחשבה לשויה אוכלא דאפילו עור ששלקו מטמא טומאת אוכלין אחרי שעשאו רך אבל לשויה בשר לא:"]],[[1,"הואיל ויכול לגוררה ולהעמידה על פחות מכזית","פ\"ה שיכול לחותכה בחתיכות קטנות פחותות מכזית בעודה מפרכסת ולא היה צריך לפרש כן אלא אפילו חתיכות גדולות ובלבד שלא יהיו אברים דבשר מן החי לא מטמא כדאמר לקמן בפרקין (חולין דף קכח:) ועל הנבלה הוא דקאמר צריך שישייר ויעמיד על (טומאה) פחות מכזית:"],[1,"ולהעמידה על מידה על פחות מכזית","וא\"ת השתא נמי סופו לטמא טומאה חמורה כיון דאילו מצטרף ליה עם חצי זית אחר מטמא כדאמר פ' דם שחיטה (כריתות דף כא.) וי\"ל דהתם בנבלה שמתה לגמרי מהני צירוף אבל הכא הואיל וסופו לטמא טומאה חמורה אחר שתמות שיצרפנה לכזית לא אמרי':"],[2,"ומי אמר חזקיה הכי","דחזקיה אחזקיה ניחא ליה לאקשויי אע\"ג דהוי מצי לאקשויי בלאו הכי ממתניתין דקתני אבל לא טומאת נבילות אחזקיה דאמר מתה היא:"],[8,"נחרה אין בה טומאה של כלום","היינו נמי אין מטמאה טומאת אוכלין דקתני גבי שחט בה סימן אחד אלא משום דלא עשה בה דרך שחיטה נקט האי לישנא כלומר נחרה והתם פשוט דאין בה טומאה כלל כיון דלא עבד כלל דרך שחיטה:"],[9,"ועובד כוכבים ששחט בהמה טהורה לישראל","רבותא נקט דאפי' לישראל דבשחיטה תליא מילתא אבר הפורש ממנה כפורש מן החי:"],[20,"אביי אמר אינה מצלת כו'","וטעמא משום דכי חיה היא לכל דבריה ולכך רובעה חייב ומ\"מ מטמא טומאת אוכלין כיון דבת אכילה היא ובקונט' פירש משום דלחומרא ותימה אי ספיקא היא אמאי רובעה חייב:"]]],[["אליבא דמאן","אי אליבא דר' ישמעאל האמר לא מבטל עור ואי אליבא דר\"ע פשיטא האמר מבטל עור","לעולם אליבא דרבי ישמעאל וכי אמר רבי ישמעאל לא מבטל עור ה\"מ שפלטתו חיה אבל פלטתו סכין בטיל","ת\"ש ר' יהודה אומר האלל המכונס אם יש כזית במקום אחד חייבין עליו ואמר רב הונא והוא שכנסו","אי אמרת בשלמא פלטתו סכין לרבי ישמעאל נמי לא בטיל רב הונא דאמר כרבי ישמעאל","אלא אי אמרת פלטתו סכין לר' ישמעאל בטיל רב הונא דאמר כמאן","אלא לעולם פלטתו סכין לר' ישמעאל לא בטיל ורב הונא דאמר כר\"ע","פשיטא מהו דתימא כי קאמר ר\"ע ה\"מ פלטתו סכין אבל פלטתו חיה לא בטיל","קמ\"ל טעמא דר\"ע מפני שהעור מבטלן ל\"ש פלט חיה ול\"ש פלט סכין כדקתני סיפא מפני מה ר\"ע מטהר בעור מפני שהעור מבטלן:","\u0001מתני׳\u0002 אלו שעורותיהן כבשרן עור האדם ועור חזיר של ישוב ר' יהודה אומר אף עור חזיר הבר","ועור חטרת של גמל הרכה ועור הראש של עגל הרך ועור הפרסות ועור בית הבושת ועור השליל ועור של תחת האליה ועור האנקה והכח והלטאה והחומט ר' יהודה אומר הלטאה כחולדה","וכולן שעבדן או שהילך בהן כדי עבודה טהורין חוץ מעור האדם ר' יוחנן בן נורי אומר שמונה שרצים יש להן עורות:","\u0001גמ׳\u0002 אמר עולא דבר תורה עור אדם טהור ומה טעם אמרו טמא גזירה שמא יעשה אדם עורות אביו ואמו שטיחין","ואיכא דמתני לה אסיפא וכולן שעיבדן או שהילך בהן כדי עבודה טהורין חוץ מעור אדם אמר עולא דבר תורה עור אדם שעבדו טהור ומה טעם אמרו טמא גזירה שמא יעשה אדם עורות אביו ואמו שטיחין","מאן דמתני לה ארישא כ\"ש אסיפא ומאן דמתני אסיפא אבל ארישא טומאה דאורייתא:","ועור חזיר [וכו']: במאי קמיפלגי מר סבר האי אשון והאי רכיך ומר סבר האי נמי רכיך:","עור חטרת של גמל הרכה: וכמה גמל הרכה אמר עולא א\"ר יהושע בן לוי כל זמן שלא טענה","בעי ר' ירמיה הגיע זמנה לטעון ולא טענה מהו בעי אביי לא הגיע זמנה לטעון וטענה מהו תיקו","יתיב ר\"ל וקמיבעיא ליה כמה גמל הרכה א\"ל רבי ישמעאל בר אבא הכי א\"ר יהושע בן לוי כל זמן שלא טענה א\"ל תיב לקבלי","יתיב רבי זירא וקמיבעיא ליה כמה גמל הרכה א\"ל רבין בר חיננא הכי אמר עולא א\"ר יהושע בן לוי כל זמן שלא טענה הוה קתני לה א\"ל חדא הויא לך אמרת","תא חזי מה בין תקיפי ארעא דישראל לחסידי דבבל:","ועור הראש וכו': וכמה עגל הרך עולא אמר בן שנתו ר' יוחנן אמר כל זמן שיונק איבעיא להו היכי קאמר עולא בן שנתו והוא שיונק"],[[0,"","פלוגתא דר' ישמעאל ור\"ע בפירקין (לקמן חולין דף קכד.) במתני' דקתני היו עליו שני חצאי זיתים מטמאין במשא שהרי נשא כזית נבלה ואין מטמא במגע דאין נוגע וחוזר ונוגע ור\"ע אומר לא במגע ולא במשא אלמא לר' ישמעאל לא מבטל עור ולר\"ע מבטל:"],[1,"ה\"ג אי אליבא דר\"ע פשיטא","דהא מתניתין היא:"],[2,"לעולם אליבא דרבי ישמעאל","ואשמועינן רב הונא דכי אמר רבי ישמעאל לא מבטל עור הני מילי בפלטתו חיה שנעשה שלא מדעת אבל פלטתו סכין מדעת ביטלו:"],[3,"ואמר רב הונא והוא שכנסו","אחר הפשט דגלי דעתיה דלא בטליה מעיקרא אבל לא כנסו לא. מדמוקים לה בשכנסו מכלל דבשפלטתו סכין בשנים ושלשה מקומות קאמר וקתני חייבין עליו אלמא אי בטלינהו איהו במתכוין בטילי אבל עור לא מבטל דאי בטלינהו עור תו לא הדרי למיהוי נבלה:"],[4,"אי אמרת בשלמא פלטתו סכין לרבי ישמעאל נמי לא מבטל","עור:"],[4,"רב הונא","דאוקמה לרבי יהודה בשהיה זית מתחלה לחצאין ואפ\"ה לא בטלינהו עור מעיקרא הוא דאמר כרבי ישמעאל דאוקמיה לרבי יהודה אליבא דרבי ישמעאל ורבנן כר\"ע:"],[5,"אלא אי אמרת פלטתו סכין","רבי ישמעאל מודי דמבטל עור:"],[5,"רב הונא","דאוקמה לדר' יהודה כשהיה זית זה מתחלה לחצאין ואפ\"ה לר' יהודה לא בטיל:"],[5,"דאמר כמאן","בשלמא אי לא דרב הונא דאמר והוא שכנסו הוה מוקמינא לר' יהודה בשפלטתו תחלה ביחד ומש\"ה לא בטיל דכי פליגי רבי ישמעאל ור\"ע בשתי חצאי זיתים פליגי אבל בכזית שלם מודו כדתני ריש פלוגתייהו עור שיש עליו כזית בשר כו' ורבנן סברי כי מודו רבי ישמעאל ור\"ע בכזית שלם הני מילי בפלטתו חיה אבל פלטתו סכין אפילו כזית בטל אבל השתא דאוקמה רב הונא בשני חצאי זיתים דאמר כמאן:"],[6,"","הכי גרסינן \u0003אלא לעולם פלטתו סכין לרבי ישמעאל נמי לא בטיל ורב הונא דאמר אליבא דר\"ע \u0004- כלומר הא דאמר רב הונא לעיל העור מבטלו אליבא דר\"ע אמרה וההיא דר' יהודה אליבא דר' ישמעאל:"],[8,"קמ\"ל","רב הונא דאפי' פלטתו חיה מפני שעור מבטלו משמע טעמא בעור תליא ואף על גב דלא בטלינהו איהו:"],[9,"מתני' אלו שעורותיהן","מטמאין כבשרן:"],[9,"ועור חזיר של ישוב","מפני שהוא רך ואוכלין אותו:"],[10,"חטרת","חלדרוב\"א שיש לו לגמל:"],[10,"גמל הרכה","מפרש בגמרא עד כמה נקראת רכה:"],[10,"עגל הרך","נמי מפרש בגמרא עד כמה:"],[10,"ועור הפרסות","כעין שחותכין הרגלים וכל אותו העור רך הוא:"],[10,"בית הבושת","בית הרחם של נקבה:"],[10,"ועור של תחת האליה","עור הזנב מתחת מקום שאין שער מפני שהוא רך:"],[10,"האנקה","הריצו\"ן:"],[10,"הלטאה","ליתיירד\"א:"],[10,"חומט","לימצ\"א שתחלת ברייתו בכעדשה צא ובדוק בתיק שלה שגדל והולך עמה תחלתו כעדשה ממש הוא בשוליו:"],[10,"הלטאה כחולדה","עורה חלוק מבשרה:"],[11,"וכולן שעיבדן","כל אלו שאמרו שהן מטמאין כבשר אם עיבדן נעשה עור ובטלו מתורת בשר וטהורין:"],[11,"או שהילך בהן","ששטחן לדרוס עליהן ברגלים שהוא קצת עיבודן:"],[11,"יש להן עורות","ואין מטמאין כבשרן:"],[12,"גמ' דבר תורה עור האדם טהור","דלאו בשר הוא ולא הוי בכלל מת:"],[12,"שטיחין","למטה ולקתדרא לישב עליהן ששוטחין עור על גבי מטה במקום חבלים:"],[14,"מאן דמתני לה","לדעולא:"],[14,"ארישא","דאפילו כי לא עיבדו נמי לא מטמא אלא מדרבנן כל שכן אסיפא דהא דקתני חוץ מעור האדם דאף על גב דעיבדו טמא מדרבנן הוא ומשום דעולא:"],[14,"ומאן דמתני לה","גזירה דעולא אסיפא:"],[14,"אבל ארישא","כשלא עיבדו סבירא ליה דטומאתו מן התורה:"],[15,"אשון","קשה:"],[16,"שלא טענה","משוי:"],[18,"תיב לקבלי","שאמרת לי דבר טעם ויישר כחך:"],[19,"הוה קתני לה","חוזר ושונה פעם שניה כסבור שלא שמעה:"],[19,"חדא הויא לך אמרת","דבר חידוש אחד היה בידך שאין בידינו הרי אמרתו ולמה תחזור ותשננו פעם שניה להראות חכמתך:"],[20,"","ר\"ל מתקיפי דארעא דישראל הוה כדאמרינן בפרק קמא דיומא (דף ט:) מאן דמשתעי ריש לקיש בהדיה יהבי ליה עיסקא בלא סהדי והכא א\"ל תיב לקבלי ורבי זירא דמבבל סלק להכא כדאמרינן בהשוכר את הפועלים (ב\"מ דף פה.) רבי זירא אותיב ארבעין תעניתי דנשתכח מיניה תלמודא דבבלאי ומחסידי דבבל הוה כדאמרינן בהשוכר את הפועלים (שם) רבי זירא (אותיב) כל תלתין יומין בדיק נפשיה ושגר תנורא וסליק בגוה חזי מאי אכספיה לההוא מדרבנן:"],[21,"והוא שיונק","אבל פירש מלינק אף על פי שעדיין הוא בתוך שנתו כבר הוקשה עורו ואם עבר שנתו נמי אף על פי שיונק לא דתרתי בעינן:"]],[[4,"אי אמרת בשלמא פלטתו סכין לרבי ישמעאל לא בטלה רב הונא דאמר כר' ישמעאל","וא\"ת והא ר' ישמעאל בלא כנסו קאמר ור' יהודה בעי כנוס כדאמר רב הונא וי\"ל דפלוגתייהו דר' ישמעאל ור\"ע בפלטתו חיה לכך לא בעי ר' ישמעאל כנוס אבל פלטתו סכין אי לא בטל לרבי ישמעאל צריך נמי כניסה ועוד דרבי ישמעאל נמי בכנסו איירי ואין זה דוחק כמו דמפרש מילתיה דרבי יהודה הכי:"],[5,"רב הונא דאמר כמאן","לעיל (חולין דף קכא.) כי קאמר וחד אמר מקצת פלטתו חיה ומקצת פלטתו סכין דבעי למימר דפלטתו סכין הוי פלוגתא דר' יהודה ורבנן דלר' יהודה לא בטל לא מצי למפרך דאמר כמאן אי אמרת לר' ישמעאל דבטל כדפריך הכא דאיכא לאוקומי דר' יהודה דאית ביה כזית יחד אבל לרב הונא פריך שפיר כדפי' בקונט':"],[5,"דאמר כמאן","וא\"ת ודילמא הא דאמר רב הונא ב' חצאי זיתים שישנן על העור העור מבטלו מיירי בלא כנסו אבל כנסו מודה דלא בטל וי\"ל דהא פשיטא ולא איצטריך ליה לרב הונא לאשמועינן דעור מבטלן (ועוד דהעור מבטלן משמע מתחלה העור מבטל ותו לא מהני להו כנוס):"],[12,"עור אדם טהור","כדמפרש טעמא בריש דם הנדה (נדה דף נה.) דלא הוי דומיא דעצם אדם דעור גזעו מחליף:"],[12,"עורות אביו ואמו שטיחין כו'","ואע\"ג דמת אסור בהנאה ובכל אדם אסור לעשות מעורו שטיחין כו' מ\"מ לא הוו גזרי רבנן משום הך חששא שיהיה טמא אלא משום אביו ואמו דחמיר טובא וא\"צ לומר דנקט אביו ואמו משום דשכיחי גביה:"],[14,"אבל רישא טומאה דאורייתא היא","והשתא חשיב עור אין גזעו מחליף משום דמקומו נעשה צלקת על בשר כדאמרינן פרק דם הנדה (גז\"ש):"]]],[["ואמר ליה ר' יוחנן כל זמן שיונק","או דלמא עולא בן שנתו קאמר בין יונק ובין שאינו יונק ואמר ליה ר' יוחנן בן שנתו והוא שיונק","ת\"ש ר' יוחנן אמר כל זמן שיונק ואם איתא והוא שיונק מיבעי ליה ש\"מ","בעא מיניה ריש לקיש מר' יוחנן עור הראש של עגל הרך מהו שיטמא אמר ליה אינו מטמא","אמר ליה לימדתנו רבינו אלו שעורותיהן כבשרן ועור הראש של עגל הרך א\"ל אל תקניטני בלשון יחיד אני שונה אותה","דתניא השוחט את העולה להקטיר כזית מעור שתחת האליה חוץ למקומו פסול ואין בו כרת חוץ לזמנו פיגול וחייבין עליו כרת","אלעזר בן יהודה איש אבלום אומר משום ר' יעקב וכן היה ר' שמעון בן יהודה איש כפר עיכום אומר משום רבי שמעון אחד עור פרסות ואחד עור הראש של עגל הרך ואחד עור של תחת האליה וכל שמנו חכמים גבי טומאה שעורותיהן כבשרן להביא עור של בית הבושת","חוץ למקומו פסול ואין בו כרת חוץ לזמנו פיגול וחייבין עליו כרת:","ועור בית הפרסות: מאי בית הפרסות רב אמר בית הפרסות ממש רבי חנינא אמר רכובה הנמכרת עם הראש:","ועור האנקה: תנו רבנן (ויקרא יא, לא) הטמאים לרבות עורותיהן כבשרן","יכול אפי' כולן ת\"ל (ויקרא יא, לא) אלה","והא אלה אכולהו כתיבי אמר רב למינהו הפסיק הענין","וליחשוב נמי תנשמת אמר רב שמואל בר יצחק רב תנא הוא ותני תנשמת","והא תנא דידן לא תני תנשמת","אמר רב ששת בריה דרב אידי תנא דידן סבר לה כר' יהודה דאזיל בתר גישתא","ובגישתא דהלטאה קמיפלגי:","וכולן שעיבדן [וכו']: הילך אין לא הילך לא והא תני ר' חייא אוזן חמור שטלאה לקופתו טהורה טלאה אע\"ג דלא הילך","לא טלאה הילך אין לא הילך לא","כמה כדי עבוד אמר רב הונא אמר רבי ינאי ארבעת מילין","(רבי אבהו משום דריש לקיש אמר) לגבל","ולתפלה ולנטילת ידים ארבעת מילין","אמר רב נחמן בר יצחק"],[[0,"וקאמר ליה ר' יוחנן כל זמן שיונק","ואפילו לאחר שנתן דבהנקה נמי תליא מילתא דחדא הוא דבעינן וה\"ק ר' יוחנן בבן שנתו שפיר קאמרת דהוי רך אבל הנקה לא הוזכר לפחות דאם פירש בתוך שנתו לא יהא רך אלא להוסיף אפילו לאחר שנתו:"],[1,"או דילמא עולא בן שנתו קאמר","אבל הנקה לא מעלה ולא מוריד וקאמר ליה ר' יוחנן אף הנקה נמי בעינן:"],[2,"כל זמן","משמע להוסיף בא:"],[4,"אל תקניטני","להשיב לי ממנה:"],[4,"שבלשון יחיד אני שונה אותה","משנה ולא בלשון סתם משנה שאני אומר אלעזר בן יהודה אמרה כדתניא:"],[5,"","המחשב בדבר שאין דרכו לאכול כגון לאכול למחר דבר שאין דרכו לכך כגון חלב או להקטיר למחר דבר שאין דרכו להקטיר כגון בשר שלמים וחטאת ואשם ושירי מנחה או עור העולה אינה לא לפסול ולא לפגל עד שישחט לאכול למחר דבר שדרכו לאכול או להקטיר למחר דבר שדרכו להקטיר ועור שתחת האליה הרי הוא כבשר ודבר שדרכו להקטיר קרינא ביה אם עולה היא ומועל לפגל את הקרבן במחשבת חוץ לזמנו או לפסול במחשבת חוץ למקומו:"],[5,"וחייבין עליו כרת","האוכל ממנו אפילו בזמנו:"],[6,"וכל שמנו חכמים לענין טומאה","שהוא כבשר שלא מצינו כאן וישנו בבהמה טהורה:"],[6,"להביא עור בית הבושת","של נקבה בחטאת או בשלמים והאי דלא מנייה ברישא כי הנך משום דליתיה בעולה ותנא בעולה קאי. אלמא האי תנא הוא דחשיב להו בשר אבל ת\"ק לא קרי בשר אלא עור שתחת האליה לחודיה:"],[8,"עור הפרסות ממש","ולא עור שעל עצם השוק מן הקרסולים עד הארכובה:"],[8,"רכובה הנמכרת עם הראש","כל עור שעל עצם השוק מרכובה התחתונה שחותכין בשעת הפשטת בהמה:"],[9,"הטמאים","ה\"א יתירא קדריש:"],[9,"לרבות","עורות שרצים הרכין שיהו כבשר ומהאי ה\"א יתירא נמי רבינן (לעיל חולין דף קיב:) צירן ורוטבן וקיפה שלהן ועור הרך נמי איתא בהדייהו דהי מינייהו מפקת איהו נמי אוכלא הוא:"],[9,"","האי הטמאים בתר דחשבינהו לכולהו כתיב:"],[11,"הפסיק הענין","ולא קאי האי אלה אלא אקרא בתרא האנקה והכח והלטאה והחומט והתנשמת אלה הטמאים וגו' ולאו אקרא קמא דלמינהו האמור בסוף פסוק ראשון הפסיקו לומר שאינן מין אחד אותן האמורים בפסוק ראשון חלוקים מהאמורים בפסוק השני:"],[12,"וליחשב נמי","במתניתין:"],[12,"תנשמת","דהא איהו נמי בקרא בתרא כתיב:"],[12,"רב תנא הוא ותני תנשמת","רב דמשני למינהו הפסיק אלמא הטמאים אכל הני דקרא בתרא קאי תנא הוא ותני תנשמת בעורותיהן כבשרן:"],[14,"תנא דידן סבר לה כרבי יהודה","כלומר לא יליף טעמא מהטמאים אלא מסברא דגישתא כל שאין ממש בעורן שהוא רך ואין לו ממש עור קרי בשר כרבי יהודה דאמר הלטאה כחולדה אלמא לאו אקרא סמיך והאי דלא מודי ליה תנא דידן בהלטאה בהא פליגי תנא קמא סבר גישתא דידה לאו גישתא הוא ורבי יהודה סבר גישתא הוא:"],[16,"שטלאה","לשון טלאי. אלמא מכיון שנטלה מתורת בשר ונתנה לתורת עור בטלה והאי נמי כיון ששטחן לפני הדורסן או שכרכן על רגלו להלוך בהן אף על פי שלא הילך:"],[16,"טלאה","הוי מעשה לבטלו:"],[19,"(עבוד) לגבל","הלש עיסתו בטהרה והוא שכיר לבעל הבית וצריך למים להטביל כליו יטריח עצמו ארבעה מילין עד שיגיע למקוה ויטביל ויותר מכאן אין עליו לטרוח מן הסתם אלא אם כן נותן לו בעל הבית שכר הליכה:"],[20,"ולתפלה","המהלך בדרך וגמר בלבו ורוצה ללון מבעוד יום אם יש בית הכנסת לפניו עד ארבעת מילין יטריח וילך שם כדי שיתפלל:"],[20,"ולנטילת ידים","לאכילה ואין לו מים ויש מים לפניו לסוף ארבעה מילין ימתין עד שיגיע למים:"]],[[2,"ואם איתא והוא שיונק מבעי ליה","תימה אכתי ה\"מ למבעי או דילמא ה\"ק עולא בן שנתו בין יונק בין שאין יונק ואמר ליה ר' יוחנן כל זמן שיונק בין בן שנתו בין שאין בן שנתו וי\"ל דלא מסתברא דבעי לאיפלוגי כולי האי ולהכי לא בעי הכי וה\"ר יעקב מקורבי\"ל תירץ דכולה שמעתין סברה דיותר קשה אפילו תוך שנתו כשאין יונק מיונק אחר שנתו ולכך כיון דר' יוחנן כל זמן שיונק קאמר א\"כ פשיטא דעולא והוא שיונק קאמר דאי תוך שנתו בין יונק בין שאינו יונק קאמר א\"כ כ\"ש לאחר שנתו אם הוא יונק דחשיב ליה רך א\"כ מה הוסיף ר' יוחנן כל זמן שיונק הא עולא מודה דכל שכן הוא:"],[3,"עור הראש של עגל הרך מהו שיטמא","על מעשה היה שואל היאך הלכה דמתני' הוה ידע כדפריך מינה לרבי יוחנן בסמוך:"],[11,"למינהו הפסיק הענין","תימה דאמר לעיל (חולין דף קיב:) דהאי הטמאים לאסור צירן ורוטבן דהתם נמי למינהו הפסיק הענין דפסוק אחד הוא לפירוש הקונט' וי\"ל דהכא כל הנהו דממעטינן אית להו גישתא סברא הוא לאוקומי אהנך דכתיב בתר למינהו ואע\"ג דכתיבא תנשמת בהדייהו דיש לה גישתא ומרבינן לה אבל צירן ורוטבן דלעיל סברא הוא לאוקומי בכולהו:"],[11,"למינהו הפסיק הענין","קצת תימה כיון דהפסיק הענין למה לי אלה:"],[14,"כרבי יהודה דאזיל בתר גישתא","פירש בקונטרס דלית ליה דרשה דהטמאים ולפירושו לא הוי תנא דברייתא לא רבי יהודה ולא בר פלוגתיה ובחנם קאמר רב תנא הוא ופליג דהא תנא דברייתא כוותיה ויש לפרש דכולהו אית להו דרשה דהטמאים ומוקי מסברא רבויא בהנהו דלית להו גישתא ומיעוטא בהנהו דאית להו גישתא ולית להו למינהו הפסיק הענין אבל רב דאית ליה למינהו הפסיק הענין ע\"כ פליג עלייהו וחשיב תנשמת:"],[16,"אוזן חמור שטלאה לקופה טהור","ונתבטל הבשר שהיה באזן פ\"ה דפריך דהכא נמי במתני' להוי סגי בהנחה לפני הדורסן בלא הלוך ותימה א\"כ מאי משני טלאה אפילו דלא הילך דאכתי תקשה ליתני במתני' הנחה לפני הדורס בלא הלוך ע\"כ נראה דה\"פ הילך אין טלאה לא מדלא קתני במתניתין טלאה דס\"ד דטלאה גרע מהילן ומשני טלאה אף על גב דלא הילך כלומר כך לי זה כמו זה ואין חדוש בזה יותר מבזה:"],[19,"לגבל","פ\"ה מי שיש לו לגבל עיסת חבירו בטהרה צריך לטרוח עד ד' מילין להטביל כליו ולפי זה לא קאי לפניו ולאחריו אגבל דאין רגילות להשכיר אדם בדרך לעשות לו עיסה ונראה כפירוש הערוך דפי' אם יש גבל העושה עיסה בטהרה ברחוק ד' מילין ימתין עד שיגיע לאותו גבל ומיירי באדם ההולך בדרך ומיהו מה שפירש בערוך לתפלה לרחוץ ידיו לתפלה אין נראה דהיכי דמי אי דמטא זמן צלויי הא לייט עלה אביי בברכות (דף טו.) אמאן דמהדר אמיא בעידן צלותא דכתיב ארחץ בנקיון כפי כל מידי דמנקי ואי לא מטא זמן תפלה מאי איריא ד' מילין אפילו טובא נמי ונראה כפירוש הקונטרס דלענין להתפלל בעשרה איירי ותימה דאמאי לא חשיב עבודה דבסמוך ועוד למאן דחשיב עבודה אמאי לא חשיב שלשים ריס דפרק לא יחפור (ב\"ב דף כג.) דמדת המיל ז' ומחצה ריס ור\"ח פי' לתפלה לטבול לתפלתו דאע\"ג דקי\"ל (לקמן חולין דף קלו:) כרבי יהודה בן בתירא בדברי תורה ה\"מ ללמוד ולק\"ש אבל לתפלה לא אי נמי לא סבירא ליה דרבי יהודה בן בתירא ולפירוש ר\"ח ניחא דלא חשיב עבודה דלא חשיב אלא הנך תלתא שהן ענין טהרה מאן דחשיב עבודה שהיא כמו מענין טהרה שמטהר העור מן הטומאה ולהכי חשיב לה ולא חשיב ההיא דשלשים ריס:"]]],[["איבו אמרה וארבעי אמר בה וחדא מינייהו עבודה","א\"ר יוסי בר' חנינא לא שנו אלא לפניו אבל לאחריו אפילו מיל אחד אינו חוזר רב אחא בר יעקב אמר ומינה מיל הוא דאינו חוזר הא פחות ממיל חוזר:","ת\"ר ליגיון העובר ממקום למקום ונכנס לבית הבית טמא שאין לך כל ליגיון וליגיון שאין לו כמה קרקפלין ואל תתמה שהרי קרקפלו של ר' ישמעאל מונח בראש מלכים:","\u0001מתני׳\u0002 המפשיט בבהמה ובחיה בטהורה ובטמאה בדקה ובגסה","לשטיח כדי אחיזה","ולחמת עד שיפשיט את החזה","המרגיל כולו חבור לטומאה ליטמא ולטמא עור שעל הצואר רבי יוחנן בן נורי אומר אינו חבור וחכ\"א חבור עד שיפשיט את כולו:","\u0001גמ׳\u0002 מכאן ואילך מאי","אמר רב טהור המופשט רבי אסי אמר טפח הסמוך לבשר טמא","מיתיבי המפשיט כשיעור הזה מכאן ואילך הנוגע במופשט טהור מאי לאו אפי' בטפח הסמוך לבשר לא לבד מטפח הסמוך לבשר","תא שמע בעור שכנגד הבשר טמא עור שכנגד הבשר טמא הא בטפח הסמוך לבשר טהור תנא כל טפח הסמוך לבשר עור שכנגד הבשר קרי ליה","ת\"ש המפשיט בבהמה ובחיה בטהורה ובטמאה בדקה ובגסה לשטיח כדי אחיזה וטפח הסמוך לבשר טהור","הכא במאי עסקינן בטפח ראשון","תנא כמה כדי אחיזה טפח והא תניא טפחיים","אמר אביי טפח כפול תניא נמי הכי כמה כדי אחיזה טפח כפול","תנן התם טלית שהתחיל בה לקורעה כיון שנקרע רובה שוב אינו חבור וטהורה","אמר רב נחמן אמר רבה בר אבוה לא שנו אלא בטלית טבולת יום","דמיגו דלא חס עלה ואטבלה לא חייס עלה וקרע לה רובה אבל טלית שאינה טבולת יום לא גזרה דלמא לא אתי למיקרעה רובה","אמר רבה שתי תשובות בדבר חדא שמא יאמרו טבילה בת יומא עולה ועוד"],[[0,"איבו אמרה","להא שמעתא משמיה דריש לקיש והשומע טעה בין איבו לאבהו:"],[0,"וארבעי אמר בה","וארבעה דברים היה אומר בה בשיעור ד' מילין:"],[0,"עבודה","האי כדי עבודה דמתניתין:"],[2,"ליגיון","גדוד העוברים להלחם על בית מלחמתם:"],[2,"קרקפלין","עור ראש אדם מת וזה למכשפות במלחמה:"],[3,"מתני' המפשיט בבהמה ובחיה בטהורה","שחוטה והוא טמא או בטמאה נבלה והוא טהור אם מפשיטו לעשות מן העור שטיח למטה ושלחן דמפשיטו פשוט כדרך שאנו עושין:"],[4,"כדי אחיזה","הוי חבור יד להוציא טומאה מן הנבלה אם נוגע בו ולהכניס טומאה לבשר אם טהורה היא וטפי מהכא לא הוי יד להכניס ולהוציא טומאה. ולקמן מפרש כמה כדי אחיזה:"],[5,"ולחמת","אם מפשיטו כפול לצורך חמת כעין אותן שעושין לצורך דבש ומתחיל מפיה והופכו כלפי זנבה:"],[5,"עד שיפשיט את החזה","הוי חבור והנוגע בעור כנוגע בבשר בין ליטמא בין לטמא מפני שהחזה קשה להפשיט מכל האברים:"],[6,"המרגיל","שהתחיל לחותכו מרגליה כלפי ראשה ומפשיטה כפול לחמת כולו חבור מפני שהחזה לסוף הפשטו הוא לפיכך כולו חבור והנוגע אף בעור המופשט כנוגע בבשר:"],[6,"עור שעל הצואר","מעצמו נפשט לפיכך אינו חבור לעשות המופשט הראשון חבור כדרך שהחזה עושה דהא כולו חבור דקתני לאו דוקא כולו אלא עד החזה:"],[7,"גמ' מכאן ואילך","משהפשיט כדי אחיזה בפשוט על פני כולו לאחר שסדקו מן הצואר עד הזנב באמצעית כדרך המפשיטין והפשיט כדי אחיזה סביבות כולו:"],[8,"טהור המופשט","עד מקום חבורו אבל מחבורו ואילך הוא טמא משום שומר כדאמרן בנוגע כנגד הבשר מאחוריו:"],[8,"טפח","מן העור המופשט סמוך למקום חבור סביבות כולו הוי בית יד וטמא מפני שצריך לו שאוחז שם ומושך ומפשיט מאליו ולרב לאו יד חשיב ליה אא\"כ מטלטלין בו את האוכל:"],[9,"כשיעור הזה","כדי אחיזה:"],[10,"בעור שכנגד הבשר","שלא נפשט עדיין:"],[12,"בטפח ראשון","הסמוך לכדי אחיזה כגון שלא הפשיט אלא טפחיים דאותו טפח הסמוך לכדי אחיזה אינו אוחז בו ומושך לפי שנוח לו לאחוז בשפת העור ולמשוך ולא זה ולא זה טוב לו אלא מפשיט בסכין אבל לאחר שהפשיט קצת שלשה טפחים וארבעה והעור המופשט מכביד כלפי מטה אוחז בטפח הסמוך לבשר ומושך וכובד העור מסייעו:"],[14,"","יש טפח ששיעורו כפול:"],[15,"טלית שהתחיל בה לקורעה","שנטמאה ובא לקורעה לבטלה מתורת טלית ומאחר שאינה ראויה למלאכה הראשונה ואין שמה עליה מטהרת אע\"פ שיש בשיריה שלש על שלש ועדיין ראויה לקבל טומאה טהורה מטומאתה ראשונה דומיא דכלי חרס דשבירתו מטהרתו ושבריו מקבלין טומאה כדאמרי' באלו טרפות (לעיל חולין דף נד:) הן וקרקרותיהן ודופנותיהן. ואף על גב דאמר בבהמה המקשה (לעיל חולין דף עב:) שלשה על שלשה שהיה טמא מדרס ומגע הזב וחלקו טהור מן המדרס ועדיין טמא מגע הזב אלמא טומאת שלשה על שלשה דחזי ליה לא בטלה מיניה התם הוא דהוו עליה ב' טומאות טומאת מדרס חמורה וטומאת מגע קלה אהניא ליה חלוקה לבטל ממנו טומאת מדרס דתו לא חזי ליה ופשה לה טומאת מגע דחזיא לשלש אצבעות אבל הכא חד שמא הוא כולה טומאה דשלשה על שלשה היא וקריעה מהניא לבטולי שמא מינה דתו לא פש עלה מידי:"],[16,"לא שנו אלא בטלית טבולת יום","שנטמאה והטבילה וצריך להשתמש בה טהרות קודם שיעריב שמשה ולפיכך בא לקורעה דהכא הוא דלא גזרינן דליקרעיה כולה אבל רובא לא דילמא חייס עלה ולא אתי למקרע רובא דכיון דלא חס עליה אטבילה שהמים קשין לה ולא חס לכך לא חייס עלה נמי וקרע רובא:"],[17,"אבל","טמאה ולא הטבילה ובא לטהרה בקריעה זו לא סגי לה ברובא עד שיקרענה כולה:"],[17,"דילמא לא אתי","למעבד רובא אלא פלגא ואמר רובא הוא:"],[18,"חדא","בטבולת יום ליכא לאוקומה ולהשתמש בה ביום שהטבילה שהרואה אינו מבין בה שנקרעה לטהר וסבור על ידי טבילתה משתמשין בה ויאמרו טבילה בת יומא עולה בלא הערב שמש ועל כרחך מתניתין לאו ביום טבילה עסקינן אלא בשלא הוטבלה כל עיקר וקרעה ביום המחרת לטומאתה דהרואהו משתמש בה אומר שהטבילה אתמול:"],[18,"ועוד","דקאמרת גזירה רובה אטו חציה:"]],[[8,"טהור המופשט","למאי דפירש בקונטרס דסבר רב דכל יד שאין מטלטלין בו את האוכל אינו יד תימה דאמאי עד כדי אחיזה חשיב יד טפי ונראה משום דבכדי אחיזה ואילך יכול לאחוז בבשר עצמו ולטלטלו אי נמי משום דכל זמן שלא הפשיט כדי אחיזה הוא קשה להפשיטו ופעמים שמניחו כך וצריך לו לטלטלו ממקום למקום אבל משהפשיט כדי אחיזה שוב אין קשה להפשיט ואין זז משם עד שיפשיט כולו וכן בחמת עד שיפשיט את החזה לפי שהחזה קשה להפשיט ולכך לפעמים מניחו כך שעה אחת ותוך כך יצטרך לטלטלו אבל משהופשט החזה אין דרך להניחו כך ועוד יש לפרש טעמא דרב דאמר מכאן ואילך טהור המופשט מפני שכדי אחיזה צריך העור להיות יד לצורך הפשטה אבל ביותר מכדי אחיזה לא לפי שאם מחזיק בשפת העור אין יכול למשוך בכח ולהפשיט ובכדי אחיזה סמוך לבשר אין יכול להחזיק בידו העור היטב ולמשוך הלכך עד [כדי] אחיזה יכול להחזיק ולמשוך בשפת העור טפי לא כדפי' הקונט' גבי הא דמשני בסמוך ההוא בטפח ראשון שכשהפשיט שלשה טפחים שאין יכול להחזיק לא בשפת העור ולא באמצע העור וי\"מ כולה מתני' משום שומר דעד כדי אחיזה הוי חבור וכ\"ש פחות אם נגע שרץ בעור המופשט מכניס טומאה לבשר משום שומר ואע\"ג דאמר לעיל (חולין דף קיח.) דעור כנגד הבשר דוקא הוי שומר הכא חשיב כנגד הבשר כיון דחשיב הכל כמחובר וכן לחמת כל זמן שהחזה מחובר חשיב הכל מחובר אבל משום יד אין לפרש דלרב אסי דאמר טפח סמוך לבשר טמא משום יד דלחמת אמאי כל העור חבור לא היה לטמא אלא טפח הסמוך לחזה דמאי שנא בין חזה לשאר אברים אלא ודאי משום שומר הוי דחשיב כל העור מחובר וכן לשון דהרי זה חבור משמע דהוי משום שומר דביד מה שייך לשון חבור והכי מוכח בת\"כ דתניא התם בנבלתה ולא במפשיט לשטיח כדי אחיזה ולחמת עד שיוציא כל החזה יכול שאני מוציא פחות מכשיעור ת\"ל יטמא אלמא דטעמא דשטיח כדי אחיזה הוי משום שומר דהא מיטמא דרשינן לעיל (שם) שומר דנבלה ויד דריש לעיל מלכם כך פי' הרב רבינו יעקב מאורלינ\"ש ואין הגי' כן בת\"כ ולפי פירושו לא מטמא בת\"כ וגם בשמעתין אלא עד כדי אחיזה ולא כדי אחיזה בכלל דהיינו פחות מכשיעור שמזכיר לשם:"],[11,"","\u0003בפירוש ר\"ח גרסינן בטפח הסמוך לבשר טמא \u0004 ופריך לרב דאמר טהור המופשט ומשני הכא במאי עסקינן בטפח ראשון פירוש טפח ראשון כשמתחיל להפשיט העור עד כדי אחיזה וטפח הוי טפח כפול כמו שמפרש בסמוך ופרושי קא מפרש עד כמה כדי אחיזה היינו טפח סמוך לבשר:"],[15,"טלית שהתחיל בה לקורעה כו'","פר\"ת כיון שנקרע רובה הויא טהורה למפרע מתחלת קריעה ולשון שהתחיל לקורעה משמע כפירושו ומה שקשה לפירוש הקונטרס מפורש בפרק בהמה המקשה (לעיל חולין דף עב: ד\"ה בשעת):"]]],[["עולת העוף לרבי אלעזר ברבי שמעון ליגזר דילמא לא אתי למעבד רוב שנים","א\"ל רב יוסף דקא אמרת גזירה שמא יאמרו טבילה בת יומא עולה קרעה מוכיח עליה","ודקא אמרת עולת העוף לר' אלעזר בר' שמעון ליגזר כהנים זריזים הן","תא שמע המפשיט בבהמה ובחיה בטמאה ובטהורה בדקה ובגסה לשטיח כדי אחיזה","הא יתר מכדי אחיזה טהור אמאי ליגזר דילמא לא אתי למעבד אלא כדי אחיזה וקא נגע בטומאה וקא מטהרינן ליה","אי בטומאה דאורייתא הכי נמי הכא במאי עסקינן בטומאה דרבנן","תינח טמא בטהורה טהור בטמאה טומאה דאורייתא היא בטרפה","טרפה בת טמויי היא אין כדאבוה דשמואל דאמר אבוה דשמואל טרפה ששחטה מטמאה במוקדשין","ת\"ש רבי דוסתאי בן יהודה משום ר\"ש אומר המפשיט בשרצים חבור עד שיפשיט את כולו","הא בגמל אינו חבור","לא תימא הא בגמל אינו חבור אלא אימא בעור שעל הצואר אינו חבור ור' יוחנן בן נורי היא","אמר רב הונא משום ר\"ש בר' יוסי לא שנו אלא שלא שייר בה כדי מעפורת אבל שייר בה כדי מעפורת חבור","אמר ריש לקיש לא שנו אלא טלית אבל עור חלים ורבי יוחנן אמר אפי' עור נמי לא חלים","איתיביה רבי יוחנן לריש לקיש עור טמא מדרס חישב עליו לרצועות וסנדלים כיון שנתן בו איזמל טהור דברי רבי יהודה וחכ\"א עד שימעיטנו מחמשה טפחים כי ממעיט ליה מיהא טהור אמאי לימא חלים","כי קאמרי דחלים היכא דקא צרי ליה להדיא הב\"ע במקצע ובא לו דרך סביבותיו","מתיב ר' ירמיה המפשיט בבהמה ובחיה בטהורה ובטמאה בדקה ובגסה לשטיח כדי אחיזה הא יתר מכדי אחיזה טהור ואמאי לימא חלים תרגמה ר' אבין ראשון ראשון עושה ניפול","מתיב רב יוסף עור שעל הצואר רבי יוחנן בן נורי אומר אינו חבור אמאי הא חלים וקאי","אמר ליה אביי אימא סיפא וחכ\"א חבור","אלא אמר אביי בשומר העשוי לנתק מאליו קא מיפלגי מר סבר הוי שומר ומר סבר לא הוי שומר","מתיב רבי ירמיה תנור שנטמא כיצד מטהרין אותו חולקו לשלשה וגורר את הטפילה"],[[0,"עולת העוף לרבי אלעזר ברבי שמעון","דאמר (בהשוחט) בפ\"ק (לעיל חולין דף כא.) רוב שנים דוקא ואסור למלוק כל השנים דגמר מחטאת דכתיב ביה לא יבדיל היכי שרינן הכי ליגזור דילמא לא אתי למיעבד רובא:"],[5,"בטומאה דרבנן","שהיה המפשיט טמא טומאה דרבנן כגון הנך דגבי שמנה עשר דבר (שבת דף יג:) הבא ראשו ורובו במים שאובים ובהמה זו קדשים היא ואם נגע בה טמאה מדרבנן הלכך לא מחמרינן בה כולי האי:"],[6,"תינח טמא בטהורה טהור בטמאה טומאה דאורייתא היא","דהא מתניתין בין בטמאה בין בטהורה קתני תנא טהורה לענין הכנסת טומאה לקבלה מן המפשיט ותנא טמאה לענין הוצאת טומאה שתטמא היא את המפשיט הראשון הנוגע בכדי אחיזה ולטהר את השני המפשיט מכדי אחיזה ואילך ולא נגע בבשר והכא ליגזר דהא כל בהמה טמאה נבלה היא אפי' שחטה וטומאתה דאורייתא:"],[6,"בטרפה","האי טמאה דמתני' לאו בהמה טמאה אלא בהמה טהורה טרפה ושחטה והיא מטמאתו אם נוגע בה כדמפרש ואזיל:"],[7,"מטמאה במוקדשין","כלומר אם של מוקדשין היא:"],[8,"","שרצים אין נוחין להפשיט:"],[8,"כולו","חבור ואפילו יותר מכדי אחיזה הנוגע במופשט טמא. מדנקט שרצים טעמא משום דקשים להפשיט אבל גמל לא ואע\"פ שטומאתו דאורייתא היא שיעור הפשטה בכדי אחיזה ולא גזרינן משום פחות מכדי אחיזה וקשיא לרב נחמן דגזר דילמא לא אתי למעבד שיעורא:"],[10,"לא תימא הא בגמל","ביותר מכדי אחיזה אינו חבור אלא הך דיוקא דדייקינן למעוטי גמל אעור הצואר הוא דדייקינן והכי קאמר שרצים הוא דעד שיפשיט את כולו אבל גמל שהפשיט עד הצואר אינו חבור ובמפשיט לחמת ובמרגיל קאי ולעולם לשטיח אף ביותר מכדי אחיזה טמא דגזרינן בבהמה טמאה הואיל וטומאתה דאורייתא:"],[10,"ור' יוחנן בן נורי היא","דאמר במתני' אינו חבור והכא ליכא למיגזר מידי דלמא לא אתי למעבד עד הצואר דהיכרא טובא איכא אבל בין פלגא לרובא לא מוכחא מילתא וכן בין כדי אחיזה לפחות מכדי אחיזה:"],[11,"מעפורת","סודר. ויתחפש באפר דכתיב גבי מיכה (מלכים א כ) מתרגמינן ואישתני במעפורתא:"],[11,"שייר","בההוא מיעוט שלא נקרע כדי מעפורת חשוב הוא להיות חבור:"],[11,"לא שנו","דכי לא שייר הוי חילוק:"],[12,"אלא טלית","דכיון שנקרע בטל שמה דאפי' חוזר ותופרה אינה חוזרת לקדמותה:"],[12,"אבל עור","שנטמא וסדקו ושייר מקצת:"],[12,"חלים","חזק הוא ע\"י אותו מקצת וכשחוזר ותופרו הרי הוא כבתחלה הלכך לא בטל שמו מעליו:"],[13,"שנתן בו איזמל","שהתחיל לבטלו טהרו ואע\"פ שעדיין יש בגדול חמשה על חמשה טפחים שהן שיעור למדרס עור כדאמרינן בסוכה (דף יז:) הבגד שלשה על שלשה השק ד' על ד' העור ה' על ה':"],[13,"עד שימעיטנו","דלא דמי לטלית דהתם קודם קריעה היה שמה טלית ועומדת להתכסות ובקריעתה בטל שמה הלכך אף על גב דשיריים בני קבולי טומאה טהרו מטומאה ראשונה אבל הכא כל שעה שם עור עליו הלכך עד שיבטלנו מכשיעור:"],[13,"כי מיעטו מיהא טהור","ואע\"פ שלא סדקו כולו אלא באחד מראשיו:"],[14,"דקא צרי ליה להדיא","סודקו לארכו או לרחבו. צרי לשון סדק כמו צרייא דחיטי בפסחים (דף מ.) וכמו טיליא חריפא דמצרי זיקי במס' ע\"ז (דף ל.):"],[14,"דרך סביבותיו","דתו לא חלים שפיר:"],[15,"חלים","מחובר ועומד הוא לבשר:"],[15,"ראשון ראשון","המופשט עושה ניפול הוי כנפרש לגמרי דהא אין סופו לחזור לבשר עוד:"],[16,"הא חלים וקאי","דהא לא הופשט וקאמר דאינו חבור והנוגע בעור כנגד הצואר אינו טמא:"],[17,"א\"ל אביי","ואדמותבת מדרבי יוחנן בן נורי סייעיה מדרבנן:"],[18,"אלא אמר אביי","אי סבירא לן דחלים דכולי עלמא הוי חבור והכא טעמא משום דלא חלים והוא שעשוי לינתק מאליו בשומר העשוי לנתק קא מיפלגי דרבנן סברי אפ\"ה לא בטיל תורת שומר מיניה כל זמן שלא ניתק:"],[19,"תנור","תחלתו עשוי כלי כקדרה ומטלטל וכשבא לקובעו מעמידו בארץ ומדביק טיט סביביו ומעבהו וקרי ליה טפילה שמטפלה ומחברה לו פלשטר\"א בלע\"ז:"],[19,"חולקו לשלשה","לכלי עצמו מבפנים דאי לשנים הגדול טמא דאיכא רובא:"],[19,"וגורר את הטפילה","שדיבק עליו שגם הוא מחברתו ואע\"פ שעדיין הוא עומד טהור:"]],[[0,"עולת העוף לרבי אלעזר בר' שמעון לגזור","וא\"ת ומאי קושיא שאני התם דגזירת הכתוב הוא שלא להבדיל וי\"ל דמשמע דלא מצריך אלא רוב מצומצם ולהכי פריך דלגזור וה\"ל לאצרוכי רוב הנראה לעינים:"],[4,"דלמא לא אתי למעבד כדי אחיזה","תימה לר\"י דמאי פריך הא לא חייס עלה דמפשיט הבהמה והיה רוצה שיהיה כולה מופשט וי\"ל דהכא חייס שלא להפשיט הרבה שאז הוא נוח לטלטל ולהפשיט:"],[11,"אבל שייר בה כדי מעפורת לא","בפרק דם חטאת (זבחים דף צד:) אמרינן אפילו שייר בה כדי מעפורת אינו טמא אלא מדרבנן:"],[12,"לא שנו אלא טלית אבל עור חלים ור' יוחנן אמר אפילו עור נמי לא חלים","נראה דר' יוחנן לא סגי בעור כדי מעפורת כמו בטלית אלא כל אחד למאי דחשיב לגבי דידיה סגי וצריך בעור ה' על ה' והשתא פריך שפיר בסמוך כי אמעט ליה מה' טפחים טהור דאי בעור נמי סגי לרבי יוחנן כדי מעפורת לא יתיישב בסמוך דאי כדי מעפורת פחות מה' כמו שמשמע באיכא דאמרי תקשה ליה לר' יוחנן אמאי טהור כי ממעט ליה מה' ואם הוא יותר מה' כשיש בו נמי ה' אמאי טמא הא אין בו כדי מעפורת ומיהו יש ליישב דלהאי לישנא סגי לר' יוחנן בעור בחשיבות מעפורת שהוא פחות מה' כדמשמע לקמן והא דקאמר וכי ממעט ליה מה' טהור אע\"פ שיש בו כדי מעפורת כגון דקא בעי ליה למושב זב כדאמר לקמן לר\"ל אבל לאיכא דאמרי לרבי יוחנן ודאי בעי ה':"],[15,"הא יותר מכדי אחיזה טהור ואמאי והא חלים","תימה לר\"י דהיכי מדמה דין דיד להא דאיירי ביה לעיל וי\"ל דנראה לו לדמות דכי היכי דאמרינן דעור הקרוע חשוב כמחובר הכי נמי נימא דעור המופשט ליחשב כמחובר ולהוי יד כאילו לא הופשט:"],[16,"עור שעל הצואר רבי יוחנן בן נורי אומר אינו חבור ואמאי הא חלים וקאי","וא\"ת לרבי יוחנן נמי דאמר עור לא חלים מודה היכא שכבר תפר שטמא וכ\"ש היכא שלא נקרע מעולם וי\"ל דקס\"ד שעל גב הצואר אע\"פ שהוא ניתק מאליו לא גרע מעור שעדיין לא נתפר ולא נתחבר דהוי כמחובר וכי היכי דעור הנקרע הוי כחלים עור שעל גב הצואר נמי אע\"ג דניתק מאליו הוי ליה למימר דהוי חבור ומשני כיון דעשוי לנתק מאליו גרע מעור הנקרע ולא הוי חבור:"]]],[["עד שיהא בארץ רבי מאיר אומר אינו צריך לא לגרור את הטפילה ולא עד שיהא בארץ אלא ממעטו מבפנים מארבע טפחים","כי ממעט לה מד' מיהא טהור אמאי לימא הא חלים וקאי","אמר ליה רבא ואימא מדרבנן גורר את הטפילה עד שיהא בארץ","אלא אמר רבא הכי קאמר תנור שנטמא כיצד מטהרין אותו דברי הכל חולקו לשלשה וגורר את הטפילה עד שיהא בארץ","והרוצה שלא יבא תנורו לידי טומאה כיצד הוא עושה חולקו לשלשה וגורר את הטפילה עד שיהא בארץ רבי מאיר אומר אינו צריך לא לגרור את הטפילה ולא עד שיהא בארץ אלא ממעטו מבפנים מארבע טפחים","אמר מר חולקו לשלשה","ורמינהו תנור תחלתו ארבעה ושיריו ארבעה דברי רבי מאיר","וחכמים אומרים במה דברים אמורים בגדול אבל בקטן תחלתו כל שהוא משתגמר מלאכתו שיריו ברובו","וכמה כל שהוא אמרי דבי רבי ינאי טפח שכן עושים תנורים בנות טפח","טעמא דאיכא שיריו ד' הא ליכא שיריו ד' טהור","אמרי התם דצלקיה מצלק הכא דעבדיה גיסטרא","אמר מר שיריו ברובו רובו דטפח למאי הוי","אמר אביי שירי גדול ברובו והאמרי רבנן ארבעה לא קשיא הא בתנורא בר תשעה הא בתנורא בר שבעה","ל\"א אמרי לה אמר רב הונא משום רבי ישמעאל ברבי יוסי ואפילו שייר בה כדי מעפורת","אמר ריש לקיש לא שנו אלא טלית אבל עור חשיב ורבי יוחנן אמר אפילו עור נמי לא חשיב","איתיביה רבי יוחנן לריש לקיש עור טמא מדרס חישב עליו לרצועה וסנדלין כיון שנתן בו איזמל טהור דברי רבי יהודה וחכמים אומרים עד שימעיטנו מחמשה טפחים","כי ממעט מיהא טהור אמאי לימא חשיב הכא במאי עסקינן דקא בעי ליה למושב זב:","\u0001מתני׳\u0002 עור שיש עליו כזית בשר הנוגע בציב היוצא ממנו ובשערה שכנגדו טמא","היו עליו כשני חצאי זיתים מטמא במשא ולא במגע דברי רבי ישמעאל רבי עקיבא אומר לא במגע ולא במשא ומודה רבי עקיבא בשני חצאי זיתים שתחבן בקיסם והסיטן שהוא טמא ומפני מה רבי עקיבא מטהר בעור מפני שהעור מבטלן:","\u0001גמ׳\u0002 אמר עולא אמר רבי יוחנן לא שנו אלא פלטתו חיה אבל פלטתו סכין בטיל","אמר ליה רב נחמן לעולא אמר רבי יוחנן אפילו כתרטא אמר ליה אין ואפילו כנפיא א\"ל אין א\"ל האלהים אם אמר לי רבי יוחנן מפומיה לא צייתנא ליה","כי סליק רב אושעיא אשכחיה ליה לרבי אמי אמרה לשמעתיה קמיה הכי אמר עולא והכי אהדר ליה רב נחמן א\"ל ומשום דרב נחמן חתניה דבי נשיאה הוא מזלזל בשמעתיה דר' יוחנן","זמנין אשכחיה דיתיב וקאמר לה אסיפא היו עליו שני חצאי זיתים מטמאים במשא ולא במגע דברי ר' ישמעאל ר\"ע אומר לא במגע ולא במשא","א\"ר יוחנן לא שנו אלא פלטתו חיה אבל פלטתו סכין בטיל","א\"ל מר אסיפא מתני לה א\"ל אין ואלא עולא ארישא אמרה ניהליכו א\"ל אין א\"ל האלהים אי אמר לי יהושע בן נון משמיה לא צייתנא ליה","כי אתא רבין וכל נחותי אמרוה ארישא ואלא קשיא כדאמר רב פפא"],[[0,"עד שיהא בארץ","כלומר עד הקרקע מפילה:"],[1,"הא חלים וקאי","שהטפילה מעמידו יפה:"],[2,"ואימא מדרבנן","אדמותבת ליה מדר\"מ סייעיה מדרבנן:"],[3,"אלא אמר רבא","בשנטמא כ\"ע לא פליגי דכל כמה דחלים לא טהר והכא הכי קאמר:"],[4,"כיצד הוא עושה","מתחלתו שלא יהא שם תנור עליו:"],[4,"ר\"מ אומר","בהא שעדיין לא ירד טומאה אינו צריך לגרור כו':"],[6,"תנור תחלתו ד'","אין תנור פחות מארבעה ואפילו נגמרה מלאכתו:"],[6,"ושיריו","אם היה גדול ונטמא ושברו צריך שלא יהא בו שבר של ד':"],[7,"בד\"א","דתחלתו ארבעה ושיריו ד':"],[7,"בגדול","התנורים העשויים לאפות ולצלות כדרכן. אבל קטן שעושין לתינוקות תחלתו כל שהוא:"],[7,"שתגמר מלאכתו","לאחר שנגמר והסיקו אפילו הוא טפח מקבל טומאה: קתני מיהא בד\"א בגדול דשיריו ד' אבל בציר מארבעה לא טמא הוא והתם קתני חלקו לשלשה אבל לשתים לא סגי ואע\"ג דליכא בחציו ד' דמדקא מיקל ר\"מ ואומר אינו צריך אלא ממעטו מבפנים מד' מכלל דרבנן נמי בהא פליגי דאע\"ג דלא הוי השבר ד' אפ\"ה בעינן דלא ליהוי רובא:"],[10,"התם","דקתני דבעינן ד' ואי לא לא הוי טמא:"],[10,"דצלקיה מצלק","לרחבו דשוב אינו עומד יפה:"],[10,"הכא","דקתני ברובא טמא ואע\"ג דלא הוי ד':"],[10,"דעבדיה גיסטרא","שחלקו לארכו בגובהו כזה:"],[11,"","ה\"ג אמר מר שיריו ברובו:"],[12,"הא אמרי רבנן ד'","דקתני בד\"א בגדול אלמא בין אתחלתו בין אשיריו מודו ליה לר\"מ בגדול:"],[12,"בתנורא בר שבעה","קאמרי ד' הואיל ורובו בציר מד' הוא לא מטמינן ליה ברובו דלא חמירי שיריו מתחלתו דהא תחלתו כשהוא שלם לא הוי תנור בציר מארבעה:"],[12,"והאי","דקתני רובו בתנור בר תשעה דאע\"ג דבחציו איכא ארבעה לא מטמא עד דהוי רובא ובהא רבנן לקולא:"],[14,"לא שנו","דאע\"ג דשייר בה כדי מעפורת בטלה אלא טלית:"],[14,"אבל עור","כי האי שיעורא:"],[14,"חשיב","ולא בטיל:"],[16,"למושב זב","פלאדשטור\"א ובבציר מהכי לא חזי למילתיה:"],[17,"מתני' עור שיש עליו כזית בשר","במקום אחד:"],[17,"הנוגע בציב היוצא ממנו","היינו באותו בשר או בשערה שכנגד אותו בשר:"],[17,"טמא","דשערה הוי שומר כדאמרינן (לעיל חולין דף קיט:) חלחולי מחלחל:"],[17,"ציב","רצועה ותלתל היוצא מאותו בשר ותלוי ודבוק במקצת ובאותו ציב ליכא כזית אבל מעורה הוא לכזית:"],[18,"מטמא במשא","שהרי נשא כזית נבלה:"],[18,"ולא במגע","דאי אפשר ליגע ביחד ושתי נגיעות אין מצטרפות:"],[18,"לא במגע ולא במשא","כדמפרש שהעור מבטלו:"],[18,"ומודה רבי עקיבא","דאע\"ג דלא הוי כזית מעורה במקום אחד דלאו עור חיבור שהמסיט שתי חצאי זיתים ביחד טמא:"],[19,"גמ' לא שנו","דכזית שלם דברי הכל לא בטיל אלא פלטתו חיה:"],[20,"כתרטא","רובע הקב לשון מורי. ל\"א כף מאזנים:"],[22,"זימנין","פעם אחרת:"],[22,"אשכחיה","רב אושעיא לר' אמי:"],[22,"דיתיב וקאמר","לא שנו דשתי חצאי זיתים לר' ישמעאל לא בטלי אלא פלטתו חיה:"],[24,"מר אסיפא","אשתי חצאי זיתים:"],[24,"מתני לה","לדר' יוחנן דפלטתו סכין בטל הכי מתוקמא שפיר אי הוו תני לה קמיה דרב נחמן הכי לא הוה מזלזל בה:"],[24,"א\"ל ר' אמי","ואלא עולא ארישא דמיירי בכזית שלם:"],[24,"מתני לה","בתמיה:"],[25,"ואלא קשיא","אי כזית שלם בטיל לעולם בטיל ואפילו כתרטא והא ליכא למימר דכולי האי מבטל איניש:"]],[[1,"כי ממעט ליה מד' מיהא הוי טהור ואמאי והא חלים וקאי","ה\"נ האי תנור דקאי ע\"י טפילה לא חשיב והוי כעור שלא נתחבר:"],[7,"","הכי גרסינן במשנת כלים (בפ\"ק) וחכ\"א בד\"א בגדול אבל בקטן תחלתו כל שהוא שיריו ברובו משתגמור מלאכתו ולא קאי משתגמור מלאכתו אשיריו ברובו אלא אשני תנורים גדול וקטן השנויים בה קאי דאין טמא עד שתגמור מלאכתו ובתר הכי מפרשה איזהו גמר מלאכתו:"],[12,"הא בתנורא בר תשעה והא בתנורא בר שבעה","כמו שפירש בקונטרס לקולא כן נראה דאין לפרש לחומרא דבר תשעה בארבעה ובר שבעה ברובו דלא עדיף שיריו מתחלתו דהוי בארבעה והכא לא בעי לשנויי הא דצלקיה מצלק בארבעה הא דעבדיה גיסטרא ברובו דכיון דמשנה אחת היא מסתבר בענין אחד מיירי או תרוייהו דצלקיה מצלק או תרוייהו דעבדיה גיסטרא הילכך הוצרך לתרץ בב' תנורים ובענין אחד ריב\"א:"],[19,"אבל פלטתו סכין בטל","וא\"ת למאן דמשני לה ארישא דאפי' כזית פלטתו סכין בטליה היכי מוקי מילתיה דר' יהודה דאמר האלל המכונס כו' אי כשכנסו וכי עדיף כנסו מפלטתו יחד כזית וי\"ל דאין ה\"נ אי נמי לדידיה ר' יהודה פליג אר' ישמעאל ור' עקיבא וס\"ל בכזית אפילו פלטתו סכין לא בטל ות\"ק דר' יהודה כר' ישמעאל ור\"ע דאפי' בכזית בפלטתו סכין בטל ולמאן דתני לה אסיפא א\"ש דהא דקאמר הכא בטל היינו בלא כנסו אבל אם כנסו לא בטיל:"]]],[["במרודד הכא נמי במרודד:","היו עליו:","אמר בר פדא לא שנו אלא מאחריו אבל מלפניו יש נוגע וחוזר ונוגע","ורבי יוחנן אמר אין נוגע וחוזר ונוגע ואזדא רבי יוחנן לטעמיה דאמר רבי יוחנן רבי ישמעאל ורבי דוסא בן הרכינס אמרו דבר אחד","רבי ישמעאל הא דאמרן רבי דוסא בן הרכינס דתנן כל המטמאין באהל שנחלקו והכניסן לתוך הבית ר' דוסא בן הרכינס מטהר וחכמים מטמאים","או אמר רבי דוסא בן הרכינס התם אין מאהיל וחוזר ומאהיל הכא נמי אין נוגע וחוזר ונוגע","ומדרבי דוסא בן הרכינס כרבי ישמעאל רבנן כרבי עקיבא והא ר' עקיבא טהורי קא מטהר","עד כאן לא קא מטהר רבי עקיבא אלא בעור אבל בעלמא מטמא כדקתני סיפא ומודה רבי עקיבא בב' חצאי זיתים שתחבן בקיסם והסיטן שהוא טמא ומפני מה ר\"ע מטהר בעור מפני שהעור מבטלן","מתיב רב עוקבא בר חמא בנבלתם ולא בעור שיש עליו ב' חצאי זיתים","יכול אף במשא ת\"ל (ויקרא יא, כה) והנושא יטמא דברי רבי ישמעאל רבי עקיבא אומר הנוגע והנושא את שבא לכלל מגע בא לכלל משא לא בא לכלל מגע לא בא לכלל משא","ואם איתא הרי בא לכלל מגע מלפניו","אמר רבא הכי קאמר את שבא לכלל מגע בכל צד בא לכלל משא לא בא לכלל מגע בכל צד לא בא לכלל משא","בעא מיניה רב אויא סבא מרבה בר רב הונא קולית סתומה לרבי ישמעאל מהו שתטמא","אית ליה לר' ישמעאל את שבא לכלל מגע בא לכלל משא לא בא לכלל מגע לא בא לכלל משא והכא היינו טעמא משום דבא לכלל מגע מלפניו","או דלמא לית ליה","אמר ליה עורבא פרח","א\"ל רבא בריה ולאו היינו רב אויא סבא מפומבדיתא דמשבח לן מר בגויה דגברא רבה הוא א\"ל אני היום (שיר השירים ב, ה) סמכוני באשישות ובעא מינאי מילתא דבעי טעמא","אמר עולא שני חצאי זיתים שתחבן בקיסם אפי' מוליך ומביא כל היום כולו טהור","מ\"ט כתיב (ויקרא יא, כה) ונשא וקרינן נושא בעינן נושא והוא דנישא בבת אחת","תנן היו עליו שני חצאי זיתים מטמאין במשא ולא במגע דברי ר' ישמעאל אמאי והא לאו נישא הוא","א\"ר פפא במרודד","ת\"ש מודה ר\"ע בשני חצאי זיתים שתחבן בקיסם והסיטן שהוא טמא אמאי והא לאו נישא הוא ה\"נ במרודד","כתנאי אחד הנוגע ואחד המסיט ר' אליעזר אומר אף הנושא אטו נושא לאו מסיט הוא","אלא לאו הכי קאמר אחד הנוגע ואחד המסיט בלא נישא ואתא ר' אליעזר למימר והוא דנישא ומאי אף אימא והוא דנישא:","\u0001מתני׳\u0002 קולית המת"],[[0,"במרודד","דק וקלוש וארוך ורחב דכי מצרפת ליה הוי כזית ומיהו לא טרח איניש ומצרף ליה ומיהו פלטתו חיה דלאו איהו בטליה לא בטיל:"],[0,"מרודד","לשון וירקעו (שמות לט) ורדידו:"],[2,"לא שנו","לרבי ישמעאל דאמר דאע\"ג דלא בטלי לענין משא במגע לא מטמו:"],[2,"אלא מאחוריו","שלא נוגע בבשר אלא בעור מאחוריו דכיון דלא הוי כזית שלם יחד אין לו יד ולא שומר. ואע\"ג דאמרן לעיל (חולין דף קיח:) אין שומר לפחות מכפול הא כפול יש שומר הא איכא ת\"ק דאחרים דפליג כדאמרינן לעיל אין זה שומר ורבי ישמעאל ס\"ל כת\"ק דאחרים:"],[2,"יש נוגע וחוזר ונוגע","כלומר שתי נגיעות מצטרפות:"],[4,"כל המטמאים באהל","כגון כזית מן המת ורובע עצמות ומלא תרווד רקב:"],[4,"שנחלקו","השיעור נחלק לשנים והכניס שתי החצאים לתוך הבית:"],[4,"מטהר","דאין לו אהילות מצטרפין שהבית מאהיל כאן וחוזר ומאהיל כאן. מדקאמר רבי יוחנן רבי ישמעאל ורבי דוסא אמרו דבר אחד אלמא טעמיה דרבי ישמעאל משום אין נוגע וחוזר ונוגע:"],[6,"ופרכינן מדרבי דוסא כרבי ישמעאל","מכלל דרבנן דפליגי עליה כרבי עקיבא קיימי והא ר\"ע טפי מיקל:"],[7,"כדקתני סיפא","דטעמיה דר\"ע דעור מבטלו הוא אבל בעלמא אפילו במגע נמי מטמא דאי לא מטמא במגע לא הוה מטמא במשא דהאמר ר\"ע לקמן את שבא לכלל מגע בא לכלל משא:"],[7,"ותחבן בקיסם","נמי רחוקין זה מזה קאמר דנוגע וחוזר ונוגע הוא כדלקמן אמילתיה דעולא:"],[8,"ולא בעור שיש עליו שני חצאים","דלא קרינא ביה הנוגע בנבלתם (ויקרא יא) דאין בכל נגיעה כשיעור נבלה:"],[9,"יכול אף הנושא ת\"ל והנושא יטמא","והרי זה נושא את הנבלה:"],[9,"והנוגע והנושא","קראי גבי הדדי כתיבי בההיא נבלה דכתיב בה הנוגע יטמא אההיא קאי והנושא יטמא:"],[9,"לא בא לכלל מגע","כלומר לדידך כיון דאמרת לא מטמא במגע תו לית לך לטמויי במשא:"],[10,"ואם איתא","לבר פדא מאי קמהדר ליה ר\"ע לרבי ישמעאל הא מודי דבא לכלל מגע מלפניו:"],[11,"בכל צד","אף מאחוריו דהא בההוא קרא דלעיל כתיבא נמי נגיעת אחוריים כדאמרינן בריש פירקין (חולין דף קיח.) יכול אפילו יש עליו כזית הנוגע בעור שכנגד הבשר מאחריו לא יהא טמא ת״ל יטמא:"],[12,"קולית סתומה","ואין עליה בשר ויש בתוכה מוח ותנן במתניתין קולית נבלה וקולית השרץ סתומים טהורין אף מן המשא דלא באו לכלל מגע מי פליג עליה רבי ישמעאל או לא מי אמרינן אית ליה לרבי ישמעאל כו':"],[13,"והכא","בעור של שני חצאין:"],[13,"היינו טעמא","דמטמא במשא משום דבא לכלל מגע מלפניו אבל גבי קולית לא בא לכלל מגע כלל דהא עצמות נבלה אין להם טומאה כדאמרן בנבלתה ולא בעצמות ובמוח אינו יכול ליגע דהא סתומה היא:"],[15,"עורבא פרח","ראה עורב פורח באויר כלומר השיאו לדבר אחר:"],[16,"סמכוני באשישות","כלומר צריכני חיזוק לפי שסר כחי מכח הדרשה שדרשתי היום ברבים דשבת הרגל היתה:"],[17,"הוליך והביא","שנשאן כל היום:"],[18,"כתיב נשא","והנשא את נבלתה חסר הוא בלא וי\"ו וסתם קריאתו כיון דלא כתב וי\"ו נקרא נישא ואנן קרינן נושא:"],[18,"והוא דנישא","שיהא כזית מחובר הניטל כולו כאחד בלא בית יד אחר:"],[19,"דברי רבי ישמעאל","אלמא כיון דאין עור מבטלו מטמא במשא ואף על גב דלאו מחובר הוא ביחד:"],[20,"במרודד","שיש כאן חצי זית ורחוק ממנו חצי זית ורצועת בשר מרודד מזה לזה ומחברתו:"],[22,"אחד הנוגע","בשני חצאי זיתים:"],[22,"ואחד המסיטן","טמא בלא נישא אף על פי שאין מחוברין יחד:"],[23,"והוא דנישא","וקאי בין אמגע בין אמשא דאין מטמאין אפילו במשא אא\"כ מחוברין:"],[24,"מתני' קולית המת","טמא דהא עצם כשעורה במת מטמא במגע ובמשא כדכתיב או בעצם אדם:"]],[[2,"אבל מלפניו יש נוגע וחוזר ונוגע","וסבר כת״ק דאחרים דריש פירקין (חולין דף קיט.) דאין שומר לפחות מכזית:"],[5,"אין מאהיל וחוזר ומאהיל","וא״ת מ״ש אהל ממשא וי״ל דמשא מרבינן' בסמוך מיטמא דקתני יכול אף במשא כן ת״ל והנושא יטמא ואע״ג דבמגע נמי כתיב יטמא יתירא דאמרינן בריש פירקין (חולין דף קיח:) מילתא דאתיא בק״ו טרח וכתב לה קרא ולא מוקמינן לנוגע וחוזר ונוגע ונראה דגבי משא דרשינן מדהוה ליה למכתב והנוגע בנבלתה יטמא עד הערב והנושא יטמא דסיפא למה לי אלא לאוסופי טומאה בנושא שאין בנוגע:"],[7,"(לעיל) שהם תחובים בקיסם והסיטן","וה\"ה בלא תחובים ונגע בהם דטמא דאי לא תימא הכי אפילו במשא לא ליטמו דאת שבא לכלל מגע בא לכלל משא לר\"ע כדאמר בגמרא וקסבר יש נוגע וחוזר ונוגע אלא משום דפליג ר\"ע ארבי ישמעאל בעור שיש עליו שתי חצאי זיתים קאמר דבקיסם כה\"ג מודה ליה:"],[9,"רבי עקיבא אומר הנוגע והנושא כו'","לר\"ע גופיה לא צריך קרא דאיהו ס\"ל דעור מבטלם אלא לדברי רבי ישמעאל קאמר לדידך דלית לך עור מבטלו תיפוק ליה מיהא דכיון דאין בא לכלל מגע כו':"],[13,"והכא היינו טעמא משום דבא לכלל מגע לפניו","רב אויא סבר כבר פדא דאית ליה נוגע וחוזר ונוגע:"],[20,"אמר רב פפא במרודד","וא\"ת ואי חשיב מרודד לצרופינהו לשני חצאי זיתים כגון שאינו מרודד יותר מדאי במגע נמי ליטמא ואי לא חשיב במשא נמי לא ליטמא דלאו נישא הוא וכ\"ת דאתא כר\"א דאמר לא שנו אלא מלאחריו כו' וקסבר כיון דלא מצטרף אלא ע\"י מרודד לא חשיב למהוי שומר ומ\"מ נישא הוא מ\"מ תקשה דהא רישא דעור שיש עליו כזית בשר אוקימנא במרודד וקאמר הנוגע בשערה שכנגדו טמא אלמא דאיכא שומר אפילו למרודד ודוחק לומר דהאי מרודד דהכא גרע מאותו שלמעלה ונראה דקסבר אוחז בקטן ואין גדול עולה עמו אין כמוהו וה\"נ איירי באוחז בקטן ואין גדול עולה עמו לכך אין מטמא במגע אבל במשא מטמא דנישא הוא:"],[23,"אימא והוא דנישא","תימה אמאי מגיה הברייתא אימא איפכא דרבנן סברי אחד הנוגע ואחד המסיט והוא דנישא אבל לא נישא לא ואתא ר' אליעזר למימר אף הנושא אע\"פ שאין נישא ויתיישב שפיר לשון אף ונראה דסבר הש\"ס דמסיט בכל ענין אפילו אין נישא לכך דחק לפרש כן:"]]],[["וקולית המוקדשין הנוגע בהן בין סתומים בין נקובים טמא","קולית נבלה וקולית השרץ הנוגע בהם סתומים טהורים נקובים כל שהוא מטמא במגע מנין שאף במשא ת\"ל (ויקרא יא, כז) הנוגע והנושא את שבא לכלל מגע בא לכלל משא לא בא לכלל מגע לא בא לכלל משא:","\u0001גמ׳\u0002 נוגע אין אבל מאהיל לא","היכי דמי אי דאיכא כזית בשר באהל נמי ליטמא דליכא כזית בשר","ואי דאיכא כזית מוח מבפנים טומאה בוקעת ועולה באהל נמי ליטמא דליכא כזית מוח בפנים","ואי מוח מבפנים מעלה ארוכה מבחוץ אבר מעליא היא באהל נמי ליטמא אמר רב יהודה בריה דרבי חייא זאת אומרת מוח בפנים אינו מעלה ארוכה מבחוץ","במאי אוקימתא דליכא כזית אי הכי במוקדשים אמאי מטמא","ותו קולית נבלה וקולית השרץ כי ניקבו אמאי מטמאו","הא לא קשיא רישא דליכא כזית סיפא דאיכא כזית ומאי קמ\"ל מילי מילי קא משמע לן","רישא קמ\"ל דמוח מבפנים אינו מעלה ארוכה מבחוץ מוקדשין מאי קמ\"ל שימוש נותר מילתא היא דאמר מרי בר אבוה אמר רבי יצחק עצמות קדשים ששימשו נותר מטמאין את הידים הואיל ונעשה בסיס לדבר האסור","נבלה אע\"ג דאיכא כזית ניקבה אין לא ניקבה לא","אביי אמר לעולם מוח מבפנים מעלה ארוכה מבחוץ והכא במאי עסקינן בששפה","וכדרבי אלעזר דא\"ר אלעזר קולית ששפה לארכה טמאה לרחבה טהורה וסימניך דיקלא","ורבי יוחנן אמר לעולם דאיכא כזית ומוח מבפנים מעלה ארוכה מבחוץ ומאי נוגע דקתני מאהיל","ואי מוח מבפנים מעלה ארוכה מבחוץ קולית נבלה וקולית השרץ כי לא נקבו אמאי טהורים","אמר רבי בנימין בר גידל אמר ר' יוחנן הכא במאי עסקינן כגון דאיכא כזית מוח המתקשקש גבי מת טומאה בוקעת ועולה נבלה כיון דמתקשקש הוא ניקבה אין לא ניקבה לא","א\"ר אבין ואיתימא ר' יוסי בר אבין אף אנן נמי תנינא הנוגע בכחצי זית ומאהיל על חצי זית או חצי זית מאהיל עליו טמא","אי אמרת בשלמא חד שמא הוא משו\"ה מצטרף","אלא אי אמרת תרי שמי נינהו מי מצטרף והתנן זה הכלל כל שהוא משם אחד מצטרף וטמא משני שמות טהור","אלא מאי חד שמא הוא אימא סיפא אבל"],[[0,"וקולית המוקדשים","במסכת פסחים (דף קכ:) תנן הפגול והנותר מטמאין את הידים דגזרי בהו רבנן משום חשדי כהונה ועצלי כהונה כדמפרש התם וגזרו אף בעצמות ששימשו נותר:"],[1,"","נבלה אין עצמותיה מטמאים דכתיב (ויקרא יא) בנבלתה ולא בעצמות וכן שרץ הלכך סתומים טהורים אף מלטמא במשא וכ\"ש מגע דאי אפשר לו ליגע ואע\"ג דשומר מכניס ומוציא טומאה ה\"מ בדבר שאפשר ליגע בטומאה עצמה ואפילו לא נגע בה אלא בשומר טמא אבל היכא דאי אפשר ליגע בטומאה עצמה אין שומר מטמא:"],[1,"נקובים כל שהוא","אפילו כחוט השערה שאפשר להכניס בו חוט השערה של ראשו או זקנו והרי הוא מטמא בכך כדלקמן:"],[4,"גמ' ואי דאיכא כזית מוח מבפנים טומאה בוקעת ועולה","קושיא היא אמאי אין מטמא באהל הרי אין לה חלל טפח וקיימא לן בברכות (דף יט:) כל חלל שאין בו טפח אינו חוצץ בפני המת:"],[5,"ואי","קסבר מוח שבפנים מעלה ארוכה לבשר מבחוץ אע\"ג דליכא מוח הואיל ובמחובר לחי סוף המוח לבא שהרי פעמים שהמוח כולו כלה וחוזר וע\"י המוח גדל הבשר מלמעלה א\"כ בלא בשר ובלא מוח חשיב אבר כל עצם חלול ותנן (אהלות פ\"א מ\"ז) האברים אין להן שיעור אפילו פחות מכזית מן המת ופחות מכעדשה מן השרץ:"],[5,"קסבר אין מוח שבפנים מעלה ארוכה","לבשר מבחוץ והכא הואיל וליכא בשר אין סופו להעלות ארוכה בחי ולא אבר מיקרי:"],[6,"א\"ה במוקדשין אמאי טמאים","הרי לא שימשו נותר דאין נותר בפחות מכזית:"],[7,"כי נקבו אמאי טמאין","הא אמרת דאין שומרין מצטרפין לטומאה חמורה:"],[8,"רישא","דקולית המת:"],[8,"דליכא כזית","לפיכך אין מטמא באהל:"],[8,"סיפא","מוקדשים ושרץ ונבלה:"],[8,"דאיכא כזית","לפיכך גבי מוקדשין איכא שיעור נותר וגבי נבלה ושרץ איכא שיעור לטמא:"],[8,"ומאי קמ\"ל","כיון דרישא ליכא כזית אכתי לא אשמעינן דעצם כשעורה מטמא במגע ולא באהל וכזית מן הנבלה מטמא:"],[8,"מילי מילי","כל דבר ששנה במשנתנו אשמעינן טעמא בכל חד וחד מה שהראה זה לא הראה זה:"],[9,"רישא","אשמעינן מדלא טימא באהל על כרחיך שמעת מינה דמוח שבפנים אין מעלה ארוכה מבחוץ דאי מעלה בין אית ביה בין לית ביה מטמא:"],[9,"מילתא היא","כנותר עצמו ואיצטריך לאשמועינן דהכי הוא כדרב מרי משום דבפסחים (דף קכ:) לא תנן אלא הפגול והנותר אבל שמושו לא תנן ואשמעינן מתניתין דמשום דשימשו כזית נותר מטמאה אפי' כשהיא סתומה ולא נגע במוח טמא משום עצם ששימש את הנותר:"],[10,"לא ניקבה לא","דבעינן אפשר ליגע כדתני טעמא בהדיא לקמן:"],[11,"אביי אמר לעולם מוח מעלה ארוכה","ומתניתין בששפה נסרה במגל או בסכין דתו לא מעלה ארוכה והלכך כיון דליכא כזית מוח דמטמא באהל משום שיעור לא מטמא אבר ובמוקדשין נבלה ושרץ בדאיכא כזית כדאוקימנא ואביי לא פליג אלא במעלה ארוכה:"],[12,"לארכה","דעכשיו שייר בה רצועה שלא שיפה:"],[12,"טמאה","ואפילו אין בה לא בשר ולא מוח דמוח שהיה עתיד לבא מבפנים מעלה ארוכה וכיון דדכוותה בעלי חיים מעלה ארוכה השתא נמי אבר הוא ולא בעי שיעור:"],[12,"לרחבה","סביב סביב ואפילו במקום אחד:"],[12,"","דקל אם תטול ממנו רצועה סביב הוא מתיבש שלא הנחת דרך לשרף לעלות מן הקרקע למעלה ממקום שנקלף ואם תקליפנו לארכו ותשייר צדו אחד יש דרך לשרף לעלות:"],[13,"לעולם","רישא דאיכא כזית דלא מוקמינן מתניתין בתרי טעמי וא\"נ ליכא כזית הויא מטמא באהל דמוח שבפנים מעלה ארוכה:"],[13,"ומאי נוגע מאהיל","מאהיל נמי במשמע כדמפרש ואזיל דאיכא תנא דקרי למאהיל נוגע:"],[14,"אמאי טהורים","עצם גופיה אבר הוא ובלא מוח נמי מטמא וסתימה מאי אהניא:"],[15,"המתקשקש","יבש ונעקר בתוך החלל דהוא לא מעלה ארוכה:"],[15,"גבי מת","אף על גב דאינו מעלה ארוכה מטמא באהל דהא בלא חשיבות אבר הא איכא שיעור וסתימה לא מהניא ביה דטומאה בוקעת ועולה ומוקדשים הרי שמשו נותר:"],[15,"נבלה כיון דמתקשקש הוא","ושוב אינו מעלה ארוכה לאו אבר הוא הלכך ניקבו דאפשר ליגע מטמאים משום שיעור לא ניקבו לא דלאו אבר הוא דהשתא גרע מקולית שיש בה בכעדשה מוח לח דההוא מעלה ארוכה הוא:"],[16,"אף אנן נמי תנינא","דקרי למאהיל נוגע:"],[16,"הנוגע בחצי זית ומאהיל על חצי זית","בבת אחת ידו נוגעת כאן והשניה מאהלת כאן:"],[16,"או חצי זית מאהיל עליו","כגון שנתון בקיסם ותחוב בכותל וזה עומד תחתיו:"]],[[2,"נוגע אין מאהיל לא","וא\"ת מנא ליה למידק מאהיל לא אי משום דלא קתני לה הא לא קתני נמי משא אע\"ג דעצם כשעורה מטמא במשא וי\"ל דמשא לא אצטריך למתני אבל אהל הוה ליה למתני כיון דאין עצם מטמא באהל אע\"ג דלא מתני ליה במוקדשין מ\"מ הוה ליה למתני באפי נפשיה אמת אע\"ג דלא הוי אהל דומיא דנוגע דנוגע בכל מקום טמא אבל מאהיל לא מטמא אלא כנגד המוח מ\"מ במאי דהוי לתנייה ואם תאמר ולשני ליה הא מני רבי יוסי דלית ליה טומאה בוקעת ועולה לקמן בשמעתין ושמא לא מסתבר ליה לאוקמה כר' יוסי:"],[5,"ואי מוח שבפנים מעלה ארוכה מבחוץ","פירש הקונטרס אע\"ג דליכא מוח כלל וזה דחקו מדלא מוקי לה דלית ביה מוח ובחנם דחק דמדנקט קולית משמע דמיירי דאיכא מוח קצת:"],[6,"אי הכי מוקדשים כו'","פירוש בשלמא אי איירי בדאיכא כזית א\"ש מוקדשין אפי' למ\"ד בערבי פסחים (פסחים קכא.) נותר בכביצה דכל חד איירי בשיעור דידיה אלא כיון דבמת איירי בדליכא שיעור מוקדשין אמאי כו' תימה דמאי קמ\"ל רב מרי מתניתין היא ועוד דבפ' כיצד צולין (פסחים דף פג.) מייתי סייעתא לרב מרי ודחי לה לייתי הך מתניתין דהכא ונראה דרב מרי אשמועינן עצמות ששמשו נותר כבר אפי' אין בהן עכשיו כלום ומתני' איכא לאוקומי בדאיכא אכתי כזית ומ\"מ חדוש הוא דאיכא שימוש נותר בעולם ובפסחים דבעי לאתויי מעצמות פסח דקאמר אלא לאו דאית ביה מוח היינו שהיה בה מוח כבר דעכשיו לא קאמר דפשיטא דטעונין שרפה משום מוח:"],[11,"הכא במאי עסקינן בששיפה","דתו לא מעלה ארוכה והלכך כיון דליכא כזית מוח לא מטמא באהל דליכא שיעור ולא הוי נמי אבר ואשמועינן דשיפה אינו מטמא באהל:"],[13,"ומאי נוגע דקתני מאהיל","וקמ\"ל דנוגע היינו מאהיל ומצטרפין וא\"ת ליתני כזית מן המת הנוגע בו טמא ואנא ידענא דנוגע היינו מאהיל וי\"ל דלא הוה שמעינן ליה מהכא אלא משום דקים לן בעלמא דכזית מן המת מטמא באהל אבל השתא דקתני קולית מן המת וקתני נוגע מוכיח דנוגע היינו מאהיל דאי אפשר ליגע במוח ממש בתוך הקולית אלא ע\"י אהל:"],[15,"הכא במאי עסקינן בכזית מוח המתקשקש","הא דלא קאמר כששיפה כדאמר לעיל אפשר דסבירא ליה דשיפה מעלה ארוכה מבחוץ:"]]],[["הנוגע בכחצי זית ודבר אחר מאהיל עליו ועל כחצי זית טהור","ואי חד שמא הוא אמאי טהור אלא קשיא רישא","אמר רבי זירא בטומאה רצוצה בין ב' מגדלים עסקינן ואין ביניהן פותח טפח דכולה נגיעה היא","ומאן תנא דקרי לאהל נוגע ר' יוסי היא דתניא ר' יוסי אומר מלא תרווד רקב מטמא במגע ובמשא ובאהל","בשלמא במשא ובאהל הא קא טעין ליה לכוליה והא קא מאהיל אכוליה אלא נוגע הא לא נגע בכוליה אלא לאו ש\"מ מאי נוגע מאהיל","והא קתני נוגע והא קתני מאהיל אמר אביי למטה מטפח אהל נגיעה למעלה מטפח אהל גרידא","רבא אמר אפילו למעלה מטפח נמי אהל נגיעה הוא והיכי דמי אהל גרידא בהמשכה","אמר רבא מנא אמינא לה דתנן ר' יוסי אומר חבילי מטה וסריגי חלונות חוצצין בין הבית לעלייה שלא להכניס טומאה לצד שני","פרסן על פני המת באויר הנוגע כנגד הנקב טמא שלא כנגד הנקב טהור","ה\"ד אילימא למטה מטפח שלא כנגד הנקב אמאי טהור מת בכסותו הוא ומת בכסותו מטמא","אלא לאו למעלה מטפח וקא קרי ליה נוגע","אמר אביי לעולם למטה מטפח ודקאמרת מת בכסותו הוא מת בכסותו מבטל ליה האי לא מבטל ליה","ותהוי כטומאה טמונה בוקעת ועולה קסבר רבי יוסי טומאה טמונה אינה בוקעת","ומנא תימרא דתנן תיבת המגדל שיש בה פותח טפח ואין ביציאתה פותח טפח טומאה בתוכה הבית טמא טומאה בבית מה שבתוכה טהור","מפני שדרך טומאה לצאת ואין דרך טומאה ליכנס","ורבי יוסי מטהר מפני שיכול הוא להוציאה לחצאין או לשורפה במקומה","וקתני סיפא העמידה בפתח ופתחה לחוץ טומאה בתוכה הבית טהור טומאה בבית מה שבתוכה טהור"],[[0,"","ודבר אחר מאהיל עליו ועל כחצי זית כגון חצי זית מוטל ע\"ג קרקע והוא עומד אצלו ודף אחד מאהיל על שניהם:"],[1,"אמאי טהור","הלא זה אהל גמור ועיקר אהל האמור בתורה זה הוא כל הבא אל האהל (במדבר י״ט:י״ד) שהבית מאהיל עליו ועל מת כאחד:"],[2,"רצוצה","כל דבר שאין לו מקום ריוח קרי רצוץ ופחות מטפח לאו חלל הוא ונקרא מה שבתוכו רצוץ:"],[2,"מגדלים","של עץ:"],[2,"דכולה נגיעה היא","אפילו הוא מאהיל למעלה מן הבשר הרבה כגון שהיו המגדלים גבוהים והטומאה למטה והוא מאהיל סמוך לראשיהן קרי נגיעה דכיון דהלמ\"מ היא דטומאה רצוצה בוקעת הוי כמאן דמלי טומאה כל חלל שבין שני המגדלים ומהא לא תסייעיה לרבי יוחנן:"],[3,"ומאן תנא","דמתניתין לרבי יוחנן דאוקי דהנוגע היינו מאהיל:"],[3,"תרווד","כף:"],[3,"רקב","עפר הנמצא בארון של מת שהוא רקבוביתו של מת. ושיעור מלא תרווד הלמ\"מ:"],[4,"הא לא נגע בכוליה","דהא כל העפר אינו מחובר יחד והנוגע בצד זה לא נגע בצד זה וכל חד וחד עפרא באפי נפשיה הוא:"],[5,"אמר אביי","המאהיל למטה מטפח שאין טפח בין ידו לטומאה קרי לה אהל נגיעה. ולאביי לא מיתוקמא מתניתין כרבי יוחנן דלא מיקרי מאהיל נוגע אלא למטה מטפח דהוי כנגיעה ואכתי הדר דוקיין קמא לדוכתיה נוגע אין אבל מאהיל אהל גרידא למעלה מטפח לא ואי דאיכא כזית באהל נמי ליטמא. ואביי לא מהדר לאוקמא לדרבי יוחנן דהא אביי אוקמה למתניתין בשאין בה כזית ובששיפה והכא קא מהדר לתרוצי מילתיה דרבי יוסי דקתני גבי רקב מגע ואהל וקשיא לן הא לא נגע בכוליה ומוקי ליה אביי באהל נגיעה:"],[6,"רבא אמר אפי' למעלה מטפח אהל נגיעה","מיקרי ושפיר מיתוקמא מתני' כר' יוחנן ורבי יוסי היא:"],[6,"בהמשכה","דבר אחר מאהיל עליו ועל הטומאה דהוא אינו מאהיל על הטומאה ולא הטומאה מאהלת עליו אלא דבר אחר ממשיך את הטומאה עליו:"],[7,"מנא אמינא לה","דאפילו למעלה מטפח קרי ליה רבי יוסי אהל נגיעה:"],[7,"חבלי מטה","המסורגים שמסרגים מטות כמין קליעה. וכן סריגי חלונות שנותנים עצים דקים או טסי ברזל בחלונות בסירוג בקליעה שלא יכנס אדם בהן:"],[7,"חוצצין בין בית לעליה","אם שטחו מקורה לחברתה נעשו תקרה ובטלו ואין מקבלין טומאה וחוצצין בפני הטומאה שלא תכנס טומאה לצד שני שעליה כלומר לעליה ואע\"פ שנקובים הרי אין בנקבים פותח טפח וכל נקב העשוי לאויר שיעורו כמלא אגרוף וכל נקב שבין בית לבית או בין בית לעליה שיעורו בפותח טפח ואף הנוגע כנגד הנקב טהור:"],[8,"היו פורסים על המת באויר","שנטלו מן המטה כמו שהן מסורגות ופורסן על המת באויר:"],[8,"הנוגע כנגד הנקב טמא","דעכשיו לא נעשו תקרה להיות הכל כסתום לפיכך הנוגע כנגד הנקב טמא שהרי מאהיל על המת. שלא כנגד הנקב טהור דחבלים בלא מטה אינן מקבלין טומאה הילכך חוצצין:"],[9,"אילימא","ששוטחן על המת למטה מטפח שאין מהן ולמת טפח:"],[11,"לא מבטל ליה","להיות כסותו של מת:"],[12,"ותהוי כטומאה טמונה","אי למטה מטפח עסקינן נהי נמי דלא מבטל ליה תיהוי מיהא טומאה טמונה שאין לה חלל טפח דקי\"ל (אהלות פי\"ד מ\"ו) בוקעת ועולה עד לרקיע אא\"כ תמצא חציצה למעלה מטפח:"],[13,"תיבת מגדל","של עץ משטיי\"ר ועושין אותו תיבות תיבות קטנות להצניע בהן כלים ומשקין:"],[13,"שיש בה","בחלל פותח טפח. ה\"ג לה במשנה דאהלות שיש בה פותח טפח דלא הויא טומאה טמונה:"],[13,"ואין ביציאתה","בחור פתח אין בו טפח:"],[13,"טומאה בתוכה הבית טמא","ואע\"פ שפתחה קטן כדמפרש טעמא מפני שדרך טומאה לצאת על כרחך סופה לצאת דרך פתח זה לפיכך מטמאה מיד דרך יציאתה ומדרבנן:"],[13,"מה שבתוכה טהור","הואיל ואין ביציאתה פותח טפח והרי אין סופו להכניס לה מת:"],[15,"רבי יוסי מטהר","כדמפרש דשמא אין סופה לצאת דרך פתח זה שיהא בה שיעור טומאה שיכול להוציאה לחצאין או לשורפה במקומה:"],[16,"וקתני סיפא העמידה בפתח","וכולה בבית אלא שפתחה לחוץ:"],[16,"טומאה בתוכה הבית טהור","דמשום מאי איכא לטמויי הא טומאת אהל ליכא דיש בה פותח טפח ולא טמונה היא ומשום יציאה נמי לא מטמיא דהא אין יציאתה לפנים:"]],[[2,"אמר ר' זירא רישא בטומאה רצוצה בין ב' מגדלים עסקינן","הוה מצי למימר בטומאה למטה מטפח עסקינן כדאמרינן בסמוך אלא משמעות אהל משמע ליה למעלה מטפח אי נמי לית ליה סברא דלקמן וא\"ת אי בטומאה רצוצה דווקא עסקינן אמאי נקט בסיפא המשכה ע\"י דבר אחר טהור ה\"ל למינקט אבל אם אינה רצוצה טהור וי\"ל דאתא לאשמועינן דאפילו בין שני מגדלים דומיא דרישא לא הוי טומאה רצוצה בהמשכה ע\"י דבר אחר דתרתי בעינן בין ב' מגדלים וגם שהוא עצמו מאהיל על הטומאה או הטומאה עליו:"],[3,"ומאן תנא דקרי לאהל נוגע רבי יוסי היא","פי' בקונט' דלא מייתי ראיה אלא אליבא דרבא וכן עיקר דהא לאביי מאי משני דע\"כ צריך לאוקומי מתניתין בכל ענין דאם לא כן מאי דחה רבי זירא לעיל בטומאה בין שני מגדלים נוקי נמי מתניתין בכה\"ג אלא ע\"כ צריך לפרש בכל ענין דלא תקשה אכתי נוגע אין מאהיל בלא טומאה רצוצה לא הילכך אליבא דאביי לא מיתוקמא כיון דאיכא אהל למעלה מטפח דלא הוי נגיעה אבל רבא דלא מפיק אלא אהל דהמשכה ליכא למיפרך מידי דמתני' לא איירי בהמשכה מדקתני הנוגע משמע אהל דומיא דנוגע דאיהו גופיה ולא ע\"י דבר אחר ואביי ורבא לית להו דרבי זירא דשני לעיל בטומאה בין שני מגדלים דאי אית להו מנא לן לפרש כדמפרש דלמא בטומאה רצוצה בין שני מגדלים עסקינן אלא ודאי לית להו וא\"ת וכיון דלית להו דרבי זירא וההוא דלעיל מתוקמא לאביי כדאית ליה ולרבא כדאית ליה ואתיא טפי שפיר לרבא דמתוקמא בפשיטות דרישא מצטרפין דכאילו נגיעה היא כיון שאין בהמשכה ובסיפא דאין מצטרפין כיון דע\"י המשכה היא וא\"כ אמאי איצטריך להביא מהכא מההיא דלעיל יכול להביא ראיה דקרי לאהל מגע לפי סברת רבא וי\"ל דניחא ליה טפי לאתויי מהכא שנזכר בה שם חכם:"],[8,"שלא כנגד הנקב טהור","וא\"ת כיון דלא מבטל להו כדפי' בקונטרס יהא טמא אפילו שלא כנגד הנקב כדאמרינן פרק לא יחפור (ב\"ב דף יט:) דכל מידי דלא מבטל ליה אין חוצץ בפני הטומאה ומיהו שם פירש דכל דבר שסותם כל החלון א\"צ בטול ושם (כ. ד\"ה היא) מפורש:"],[12,"קסבר רבי יוסי טומאה אינה בוקעת ועולה","וא\"ת היכי מוקמינן לעיל מתניתין כוותיה והא מתניתין סבר דבוקעת ועולה דקתני בקולית סתומה הנוגע בה טמא ואוקמינן דמאי נוגע מאהיל וי\"ל אע\"ג דסבר רבי יוסי טומאה טמונה אינה בוקעת מודה בקולית סתומה שמטמא באהל כמו במת בכסותו דמודה רבי יוסי דמטמא:"],[13,"טומאה בבית מה שבתוכה טהור","שהמגדל חוצץ בין הטומאה ובין מה שבתוכו דאינו מקבל טומאה דעשוי לנחת הוא:"],[15,"יכול הוא להוציאה ולשורפה במקומה","נראה דמודה רבי יוסי בהא דאמרינן בביצה (דף י.) המת בבית ולו פתחים הרבה כולן טמאים מפני שסוף טומאה לצאת דרך שם דהתם במת שלם דאין דרך לשורפו ולנתחו פחות מכזית:"]]],[["ותני עלה רבי יוסי מטהר אהייא אילימא אסיפא ת\"ק נמי טהורי קא מטהר","אלא דקאמר ת\"ק טומאה בתוכה הבית טמא אי משום דדרך טומאה לצאת ואי משום דטומאה טמונה בוקעת וקא\"ל רבי יוסי דקאמרת דרך טומאה לצאת יכול הוא להוציאה לחצאין או לשורפה במקומה ודקאמרת טומאה טמונה בוקעת טומאה טמונה אינה בוקעת","ורמי דר' יוסי אדר' יוסי","דתנן הכלב שאכל בשר מת ומת הכלב ומוטל על האסקופה ר\"מ אומר אם יש בצוארו פותח טפח מביא את הטומאה ואם לאו אינו מביא את הטומאה","ר' יוסי אומר רואין מכנגד השקוף ולפנים הבית טמא מכנגד השקוף ולחוץ הבית טהור","רבי אלעזר אומר פיו לפנים הבית טהור פיו לחוץ הבית טמא מפני שטומאה יוצאה דרך שוליו","רבי יהודה בן בתירא אומר בין כך ובין כך הבית טמא","מאי לאו אאין בצוארו פותח טפח קאי רבי יוסי","וש\"מ טומאה טמונה בוקעת","אמר רבא רואין את חלל הטומאה קתני ורבי יוסי בתרתי פליג וקא\"ל לר' מאיר דקאמרת כי יש בצוארו פותח טפח מביא את הטומאה אנן בתר חללה אזלינן","ודקא אמרת (הבית) כולו טמא מכנגד השקוף ולפנים הבית טמא מכנגד השקוף ולחוץ הבית טהור","רב אחא בריה דרבא מתני לה בהדיא רבי יוסי אומר רואין את חלל הטומאה","ומאן תנא דפליג עליה רבי שמעון הוא דתניא ר\"ש אומר"],[[0,"","ה\"ג ותני עלה ורבי יוסי מטהר אהייא אי נימא אסיפא תנא קמא נמי טהורי מטהר אלא דקאמר ת\"ק הבית טמא אי משום דדרך טומאה לצאת כו' ולא גרסינן אלא לאו ארישא - דהא ברישא בהדיא תנן בה ורבי יוסי מטהר:"],[0,"אי נימא אסיפא","וכדקתני הא ת\"ק נמי מטהר:"],[1,"אלא","שמעיה לת\"ק דקאמר הבית טמא כל היכא דמשכחת חדא מהנך תרי טעמי אי משום דרך טומאה לצאת כגון רישא דיש בה פותח טפח דאין כאן טומאה טמונה אלא משום דסופה לצאת ואי משום דטומאה טמונה בוקעת מדנקט רישא יש בה פותח טפח ותנא סיפא עלה העמידה בפתח ופתחה לחוץ הבית טהור ושמעינן מינה טעמא דיש בה פותח טפח דאין כאן אהל טומאה טמונה הא אין בה פותח טפח אפילו העמידה בפתח ופתחה לחוץ הבית טמא מפני שטומאה טמונה בוקעת והוי כאילו מוטלת בקרקע הבית והבית מאהיל עליה:"],[1,"הבית טמא","השתא קס\"ד אדאין בצוארו טפח קאי דקאמר ר\"מ הבית טהור וקא\"ל רבי יוסי אם הטומאה מן המשקוף ולפנים אע\"פ שאין בצוארו רוחב להיות הוא אהל הרי יש כאן אהל גדול שהבית מאהיל על הטומאה וסתם חלל הגרון אין בו טפח והוי לה טומאה טמונה:"],[1,"וקא\"ל ר' יוסי","ברישא דקאמרת גבי יש בה פותח טפח הבית טמא מפני שדרך טומאה לצאת יכול הוא להוציאה לחצאין:"],[1,"ודקאמרת","בסיפא הבית טהור וטעמא משום דנקט ברישא יש בה פותח טפח הא אין בה פותח טפח הבית טמא משום דטומאה טמונה בוקעת לאו מילתא היא דטומאה טמונה אינה בוקעת:"],[3,"הכלב שאכל בשר המת ומת הכלב","דאילו חי אפילו נכנס לבית הבית טהור כדאמר בבהמה המקשה (לעיל חולין דף עא.) דטומאה הבלועה בבעלי חיים אינה מטמאה:"],[3,"ומוטל על האסקופה","וצוארו לפנים:"],[3,"אם יש בצוארו פותח טפח","רוחב טפח בצוארו:"],[3,"מביא את הטומאה","משום דדופנו העליון מאהיל על הטומאה וראשו השני ממשיך האהל לבית ויוצאה דרך פיו לבית ואע\"ג דאין לה אהל שחללו טפח סבר ר\"מ דממשיך הואיל ורחבו טפח:"],[3,"ואם לאו אין מביא את הטומאה","דכל שאין בו רוחב טפח אינו אהל כדתנן (אהלות פ\"ג מ\"ז) טפח על טפח על רום טפח מרובע מביא את הטומאה:"],[4,"רבי יוסי אומר רואים","את הטומאה קס\"ד דה\"ק בודקין בגופו את מקום הטומאה אם היה מן המשקוף ולפנים:"],[4,"הבית טמא","השתא קס\"ד אדאין בצוארו טפח קאי דקאמר ר\"מ הבית טהור וקא\"ל רבי יוסי אם הטומאה מן המשקוף ולפנים אע\"פ שאין בצוארו רוחב להיות הוא אהל הרי יש כאן אהל גדול שהבית מאהיל על הטומאה וסתם חלל הגרון אין בו טפח והויא לה טומאה טמונה:"],[4,"מן המשקוף ולחוץ הבית טהור","שהרי אין כאן לא בית מאהיל ולא אהל טפח שיהא ממשיכה לתוך הבית:"],[5,"פיו לפנים","ונקב זנבו לחוץ הבית טהור אם טומאה מבחוץ ומשום המשכה לא מטמאינן ליה שהרי אין דרך מאכל לצאת דרך הפה אלא דרך השוליים נקב הריעי:"],[5,"פיו לחוץ","ושוליו לפנים:"],[5,"הבית טמא","שהרי דרך פתח קטן הזה על כרחך היה סופה לצאת:"],[6,"בין כך ובין כך","פיו לפנים או פיו לחוץ בין טומאה מכנגד המשקוף ולפנים בין שהוא לחוץ בין שבצוארו טפח בין אין בצוארו טפח ואכולהו פליג פיו לפנים טמא ואע\"פ שאין סופו לצאת דרך כאן קסבר אף בדרך כניסתה היא מוציאה טומאתה אי נמי פעמים שהיה מקיא וכן שוליו לפנים מפני שדרכה לצאת דרך זה:"],[7,"מאי לאו אאין בצוארו טפח קאי רבי יוסי","ואמר דאם טומאה מן המשקוף ולפנים טמא ואע\"פ שאין כאן המשכה מטמא ליה משום שהבית מאהיל על טומאה טמונה:"],[9,"אמר רבא","ר' יוסי לאו אאין בצוארו טפח קאי ולחומרא דהתם אפי' טומאה בפנים הבית טהור דטומאה טמונה אינה בוקעת אלא איש בצוארו פותח טפח קאי ולקולא דקאמר ר\"מ אהל הצואר ממשיך הטומאה לבית הואיל ורחבו טפח ואע\"פ שאין חללו טפח וקאמר ליה רבי יוסי רואין את חלל הטומאה חלל הצואר אם יש בחללו טפח ממשיך ואם לאו אינו ממשיך. והאי רואין את הטומאה לאו רואין את מקום שכיבת הטומאה קאמר דאמקום שכיבתה לא חיישינן דלא שני לן אם בבית אם לחוץ לבית שאין טומאת הבית אלא משום המשכה אלא רואין את חללה קאמר ודקמסיים בסיפא אם מכנגד המשקוף ולפנים כו' מילתא אחריתי היא:"],[9,"ובתרתי פליג","וה\"ק ליה לר\"מ דקאמרת לענין המשכה אם יש בצוארו כולו עם עובי דפנותיו רחב טפח ממשיך אנן חלל טפח בעינן:"],[10,"ודקאמרת על האסקופה כולה הבית טמא","ואע\"פ שאין פיו מן השקוף ולפנים דקחשבת כל האסקופה כלפנים והאסקופה רחבה ושקוף מחותך בו שהדלת נוקף ושוקף בו כשסוגרין אותו ומההוא שקוף ולפנים הוי כלפנים:"],[10,"שקוף","בטיי\"ל בלע\"ז כמו שאנו עושין למפתן ולמשקוף העליון מקום שהדלת נוקש עליהן. ולשון שקיפה היא הכאה שנוקש דבר על חבירו כדמתרגמינן חבורה (שמות כא) משקופי עלה נדף (ויקרא כו) טרפא דשקיף שדופות קדים (בראשית מא) שקיפן קידום חבוטות ברוח:"],[12,"מאן תנא","דלעיל (חולין דף קכה:) דהנוגע בכחצי זית ודבר אחר מאהיל עליו ועל חצי זית דקתני טהור דלא מצטרפי אלמא מגע ואהל לאו חד שמא הוא ופליג אדר' יוסי דקרי לאהל נוגע:"]],[[3,"אם יש בצוארו פותח טפח כו'","תימה אי צוארו של כלב חשיב דבר שאין מקבל טומאה כי יש בצוארו פותח טפח מאי הוי נהי דרבי מאיר אית ליה חוקקים להשלים מ\"מ הא ממעט הבשר את האויר מטפח ואינה יכולה טומאה לבא ואי חשיב דבר המקבל טומאה היכי קאמר ר' יוסי רואים את חלל הטומאה הא אם אין בחללה טפח אינו מביא ואמאי והא אינו יכול לחוץ והרי הוא כפתוח לבית ומיהו אפשר דמ\"מ לרבי יוסי הבית טהור דכיון שאין בחלל טפח אין כאן אהל שימשוך טומאה לבית ופוסקת הטומאה בחוץ אך קשה נהי דבשר אפשר שאינו חוצץ עצמות אמאי אין חוצצים וי\"ל כיון דאית ליה לר\"מ חוקקין ויש בהם אויר קצת דהעצמות אין סותמים כל הנקב אלא ממעטין ומסתמא אין מבטלין וסופו להוציאם משם לא חייצי כדפרישית פ' לא יחפור (ב\"ב דף יט:):"],[7,"מאי לאו אאין בצוארו פותח טפח","ורואין היינו רואין את הטומאה אם היא כנגד השקוף או לא:"],[9,"אמר רבא ה\"ק כו'","לא הוה מצי למימר דאיש בצוארו פותח טפח קאי ולא בא לחלוק אלא דלא חשיב לשקוף אהל ורואין אצואר כלב קאי דלא שייך למימר לשון רואין אהא דהא מונח קמן אלא אטומאה שהיא בפנים או אחלל שייך לומר רואין:"],[9,"אנן בתר חלל אזלינן","ור\"מ דלא בעי חלל טפח לטעמיה דאית ליה בפ\"ק דשבת (דף ז:) דחוקקין להשלים גבי זרק ונח בחור כל שהוא ונהי דבפ\"ק דערובין (דף יא:) גבי כיפה לא אמר חוקקין להשלים אלא כשיש ברגליה ארבע ה\"מ גבי מזוזה דכתיב (דברים יא) ובשעריך ובעינן שער חשוב אבל בעלמא אפי' אין שם ד' חוקקין וצ\"ע שם ונראה דהך שמעתא מיירי כשאין טפח מן השקוף ולחוץ וכשסוגרים הדלת הוא כאהל בפני עצמו ואין אהל פחות מטפח ור' אלעזר אמר פיו לפנים הבית טהור לחוץ הבית טמא מפני שטומאה יוצאה דרך שוליו ונראה דר' אלעזר לאו אכלב דרבי יוסי קאי דר' יוסי בכלב שיש בצוארו חלל פותח טפח איירי ורבי אלעזר שאין בחלל פותח טפח מדקאמר פיו לפנים הבית טהור אלמא בסתם כלבים איירי שאין בצוארם פותח טפח:"],[12,"מאן תנא דפליג עליה דרבי יוסי ר\"ש היא","פ\"ה מאן תנא דאמר לעיל נוגע בחצי זית ודבר אחר מאהיל עליו ועל חצי זית טהור דלא מצטרף אלמא תרי שמי נינהו דאהל לאו היינו נגיעה וקשה דהתם אפי' רבי יוסי מודה בין לאביי בין לרבא דהא למעלה מטפח אהל בהמשכה הוא ונראה לפרש דאמאי דקאמר לעיל מאן האי תנא דחשיב לאהל נגיעה ר' יוסי מכלל דאיכא דפליג עליה וקאמר מאן הוי האי תנא:"]]],[["שלש טומאות פורשות מן המת שתים בכל אחת ושלישית אין בהן ואלו הן מלא תרווד רקב ועצם כשעורה וגולל ודופק","מלא תרווד רקב מטמא במשא ובאהל ואינו מטמא במגע והיכן מגעו עם אחת מהן","עצם כשעורה מטמא במשא ובמגע ואינו מטמא באהל והיכן אהלו עם אחת מהן","גולל ודופק מטמא במגע ובאהל ואינו מטמא במשא והיכן משאו עם אחד מהן:","קולית נבלה וקולית השרץ וכו': ת\"ר (ויקרא יא, לט) בנבלתה ולא בקולית סתומה","יכול אפילו ניקבה ת\"ל הנוגע יטמא את שאפשר ליגע טמא ואת שאי אפשר ליגע טהור","א\"ל רבי זירא לאביי אלא מעתה בהמה בעורה לא תטמא פוק חזי כמה נקבים יש בה","א\"ל רב פפא לרבא אלא מעתה כוליא בחלבה לא תטמא תא חזי כמה חוטין נמשכין הימנה","בעי רב אושעיא חישב עליה לנוקבה ולא ניקבה מהו מחוסר נקיבה כמחוסר מעשה דמי או לא","הדר פשטה מחוסר נקיבה לאו כמחוסר מעשה דמי:","\u0001מתני׳\u0002 ביצת השרץ המרוקמת טהורה ניקבה כל שהוא טמא עכבר שחציו בשר וחציו אדמה הנוגע בבשר טמא באדמה טהור רבי יהודה אומר אף הנוגע באדמה שכנגד הבשר טמא:","\u0001גמ׳\u0002 ת\"ר (ויקרא יא, לא) הטמאים לרבות ביצת השרץ וקולית השרץ","יכול אפי' לא ריקמה ת\"ל (ויקרא יא, כט) השרץ מה שרץ שרקם אף ביצת השרץ שרקמה","יכול אפי' לא ניקבו ת\"ל הנוגע יטמא את שאפשר ליגע טמא ואת שאי אפשר ליגע טהור","וכמה נקיבתה כחוט השערה שאפשר ליגע כחוט השערה:","עכבר שחציו [וכו']: אמר רבי יהושע בן לוי והוא שהשריץ על פני כולו איכא דמתני לה אסיפא רבי יהודה אומר אף הנוגע באדמה שכנגד בשר טמא אמר ר' יהושע בן לוי והוא שהשריץ על פני כולו","מאן דמתני לה ארישא כל שכן אסיפא ומאן דמתני לה אסיפא אבל רישא אע\"ג דלא השריץ","ת\"ר מתוך שנאמר עכבר שומע אני אפילו עכבר שבים ששמו עכבר ודין הוא טימא בחולדה וטימא בעכבר מה חולדה מין הגדל על הארץ אף עכבר מין הגדל על הארץ","או כלך לדרך זו טימא בחולדה וטימא בעכבר מה חולדה כל ששמה חולדה אף עכבר כל ששמו עכבר אפי' עכבר שבים ששמו עכבר ת\"ל (ויקרא יא, ב) על הארץ","אי על הארץ יכול על הארץ יטמא ירד לים לא יטמא"],[[0,"שלש טומאות פורשות כו'","טומאות הרבה פורשות מן המת כגון כזית בשר ושדרה וגלגולת שלא חסרו ורובע עצמות ומלא תרווד רקב ועצם כשעורה ורוב המנין והבנין אלא שלש טומאות פורשות ממנו ששוות בדבר זה שיש בכל אחת שתים מטומאתו של מת או מגע ומשא בלא אהל או מגע ואהל בלא משא או משא ואהל בלא מגע והשלישית אין בה:"],[0,"ואלו הן","הג' הפורשות שהמשפט הזה נוהג בהן:"],[0,"מלא תרווד רקב ועצם כשעורה וגולל ודופק","גולל זה כסוי העליון דף שנותנין על המת דופק זה דף הניתן בצדיו ורבינן להו מקראי בפ' בהמה המקשה (לעיל חולין דף עב.) והנך תרי חדא טומאה נינהו ששניהם יוצאים ממקרא אחד וטומאתן שוה אבל שאר פורשים מן המת כל ג' טומאות המת נוהגים בהם:"],[1,"מלא תרווד רקב מטמא במשא ואהל","שהרי נושא את כולו:"],[1,"ואינו מטמא במגע","שאין נוגע בכולן. והיינו פליגא דר' יוסי דאמר מלא תרווד רקב מטמא במגע דקרייה לאהל מגע:"],[1,"והיכן מגעו","של מת:"],[1,"באחת מהן","בכל אחת מאלו השתים הנותרות:"],[2,"עצם כשעורה","הלמ\"מ דמגע ומשא אית ליה ולא אהל כדאמרינן בנזיר (דף נג:) עצם כשעורה הלכה:"],[2,"והיכן אהלו","של מת:"],[3,"גולל ודופק","נמי הלכה גמירי לה בבהמה המקשה (לעיל חולין דף עב.). ולמאן דנפקא ליה התם מקרא לא ידענא מהיכן אימעיט משא:"],[5,"יכול אפי' נקבה","לא הוי טמא:"],[5,"ת\"ל הנוגע יטמא","יו\"ד יתירא דריש:"],[5,"את שאפשר ליגע טמא","שם טומאה עליו הילכך אע\"פ דלא נגע אלא בעצם טמא דשומר מכניס ומוציא טומאה:"],[6,"בהמה בתוך עורה","כל זמן שלא הופשטה כלל:"],[6,"לא תטמא","דהא אי אפשר ליגע בבשר:"],[6,"כמה נקבים יש בה","הפה והחוטם והעינים:"],[7,"","חלב אינו טמא כדכתיב יעשה לכל מלאכה ותניא בגמרא דכל שעה בפסחים (דף כג.) מלאכה מה ת\"ל לכל מלאכה שיכול למלאכת הדיוט יהא טהור למלאכת גבוה יהא טמא ת\"ל לכל מלאכה:"],[7,"כוליא","המכוסה בחלבה לא תטמא הואיל ואי אפשר ליגע בה:"],[7,"נמשכין הימנה","באמצעיתה והן בשר:"],[10,"מתני' ביצת השרץ","יש שרץ שהוא מטיל ביצים צב והלטאה וחומט:"],[10,"המרוקמת","שנולד בה אפרוח:"],[10,"טהורה","לפי שאי אפשר ליגע בה:"],[10,"ניקבה כל שהוא טמאה","ואע\"פ שלא נגע אלא שהשומר מוציא טומאה:"],[10,"","יש מין עכבר שאינו פרה ורבה אלא מעצמו נוצר מאדמה כאשפה המשרצת תולעים ואם עדיין לא נברא העכבר אלא צדו אחד הימני או השמאלי הנוגע בבשר טמא באדמה שכנגדו טהור:"],[11,"גמ' הטמאים","אלה הטמאים ה\"א יתירא נדרשת לכמה דרשות לאסור צירן ורוטבן (לעיל חולין דף קיב:) ולעורותיהן כבשרן (לעיל חולין דף קכב:) ולביצת השרץ:"],[12,"ת\"ל השרץ","הטמאים לכם בכל השרץ:"],[14,"כחוט השערה","שער ראשו וזקנו אם יכניסו לתוכו הרי נגע וטמא שהשער המחובר הרי הוא כבשר בין שער טהור הנוגע בטומאה בין שער טמא שנגע בו הטהור טמא. דתניא בת\"כ הנוגע בבשר הזב ולא בצואה שעליו ולא בקילקלין. הוא עירבוב שער תלוש המתקשה ונאסף בשערו שעל החזה ושעל השחי פולטרי\"ץ בלע\"ז ואינם מחוברין לבשר להכי קרי ליה קילקלין מה קילקלין זה מקושר כנגד החוץ אף הני שערות קשורין ומכוסין שם כך מצאתי בדברי רב האי. יכול שאני מוציא את השער ואת הצפורן ת\"ל טמא הא למדת ששער הטמא הרי הוא כבשרו. ושער הטהור נמי תניא התם וכל אשר יגע בו הזב בו ולא בצואה שעליו ולא בקילקלין שעליו יכול שאני מוציא את השער ואת הצפורן ת\"ל יטמא:"],[15,"והוא שהשריץ","חציו על פני ארכו של שרץ מראשו ועד רגליו כלומר שמצד א' הוא נעשה בשר ולהכי טמא אם נגע בבשר דחשיב שרץ הוא:"],[16,"מאן דמתני לה","להא דר' יהושע ארישא דמיירי בנוגע בבשר ואפ\"ה מטהר ליה ריב\"ל אם לא השריץ על פני כולו:"],[16,"כ\"ש אסיפא","אדר' יהודה דמיירי בנוגע באדמה דאשמעינן דלא טימא ר' יהודה בעפר אלא אם כן השריץ על פני כולו דהכי מסתבר שפיר. ולקמן תנא כל שיש ביבשה יש בים חוץ מן החולדה:"],[17,"עכבר שבים","דג הוא דומה לעכבר ועכבר שמו:"],[17,"ודין הוא","מדינא נפקא ליה דלא מטמא ולא צריכא קרא:"],[17,"מה חולדה מין הגדל על הארץ","ולא שבים שהרי אין חולדה בים:"],[17,"אף עכבר","אף על פי שיש ממינו בים לא טימא אלא מין הארץ:"],[19,"אי על הארץ יכול על הארץ יטמא","כלומר אומר אני לא אדרשנו לך במדה זו אלא לכך בא לומר על הארץ יטמא בין עכבר הים בין עכבר היבשה אם על הארץ נגע בטהור יטמאנו ואם נפל לים ושם נגע בטהור לא יטמא:"]],[[2,"עצם כשעורה מטמא במגע ובמשא אבל לא באהל","פי' בקונטרס דהלמ\"מ הוא ואי אפשר לומר כן דמקראי ילפינן לה בנזיר פרק כהן גדול (נזיר דף נג:) ולא הוי הלכה אלא מה שהנזיר מגלח עליו אע\"ג דלא מטמא באהל:"],[3,"גולל ודופק מטמא במגע ובאהל ואין מטמא במשא","למ\"ד בפרק בהמה המקשה (לעיל חולין דף עב.) דגולל ודופק הוו מהלכה איכא למימר דהכי גמירי לה אלא למאן דמייתי לה מעל פני השדה קשה מנא לן ונראה משום דההוא קרא דכל אשר יגע על פני השדה מוקמינן בנזיר (דף נג:) באהל הילכך מטמא באהל ובמגע נמי מטמא משום דאפקיה בלשון נגיעה אבל במשא לא מצינו שיטמא:"],[4,"בנבלתה ולא בקולית סתומה","מהאי קרא נמי ממעטינן בפ' בהמה המקשה (לעיל חולין עז:) עצמות וגידין וקשה דא\"כ היכי נמעט מיניה קולית סתומה ומיהו כיון דלא מרבינן שומר אלא בנקובה שיכול ליגע ממילא כי אמעיטו עצמות אמעיט נמי קולית סתומה אע\"פ דשומר הוי כסתום כגון חטה בקליפתה התם מרבינן מקרא דזרע אשר יזרע כדרך שבני אדם מוציאים לזריעה אבל הכא גלי קרא דשומר לא הוי אלא בשאפשר ליגע וכן גבי שרצים מרבינן לקמן מיטמא דשרצים קולית השרץ נקובה ואע\"ג דמהטמאים דרשינן לקמן לרבות קולית השרץ וביצת השרץ עיקר קרא לא אתא אלא לביצת השרץ אבל קולית נפקא מיטמא ואע\"ג דמהטמאים דרשינן דרשות טובא אפשר דדרשינן מטמא טמאים הטמאים או טובא טמאים כתיב התם:"],[12,"יכול אפילו לא רקמה ת\"ל השרץ","וא\"ת ולרקמה למה לי קרא לענין טומאה הא לענין אכילה פשיטא לן בלא קרא בפרק אלו טרפות (לעיל חולין דף סד.) שאם רקמה ואכלה לוקה משום השרץ השורץ על הארץ אלמא שרץ איקרי ויש לומר דודאי רקמה שרץ איקרי אבל צב ועכבר לא איקרי וכה\"ג אמרינן בפ' בהמה המקשה (לעיל חולין עה.) גבי חלב דלא איקרי חלב שור כשב ועז עד שיצא העובר לאויר העולם אי נמי מקרא דהכא קים לן באלו טרפות לענין אכילה שלוקה:"]]],[["ת\"ל (ויקרא יא, כט) השורץ כל מקום ששורץ","או אינו אלא השורץ (יכול) כל המשריץ יטמא שאין משריץ לא יטמא אוציא עכבר שחציו בשר וחציו אדמה שאין פרה ורבה","ודין הוא טימא בחולדה וטימא בעכבר מה חולדה כל ששמה חולדה אף עכבר כל ששמו עכבר אביא עכבר שחציו בשר וחציו אדמה","או כלך לדרך זו מה חולדה פרה ורבה אף עכבר פרה ורבה ת\"ל (ויקרא יא, כט) בשרץ","אמר ליה ההוא מדרבנן לרבא אימא בשרץ לאתויי עכבר שחציו בשר וחציו אדמה השורץ כל שהוא שורץ ואפילו עכבר שבים ואי משום על הארץ על הארץ יטמא ירד לים לא יטמא","אמר ליה ומאחר דשויתיה לים מקום טומאה מה לי הכא מה לי הכא","והאי על הארץ מיבעי ליה להוציא ספק טומאה צפה דא\"ר יצחק בר אבדימי על הארץ להוציא ספק טומאה צפה","תרתי על הארץ כתיבי","ת\"ר (ויקרא יא, כט) הצב למינהו להביא הערוד וכן הנפילים וסלמנדרא","וכשהיה ר\"ע מגיע לפסוק זה אומר (תהלים קד, כד) מה רבו מעשיך ה' יש לך בריות גדלות בים ויש לך בריות גדלות ביבשה שבים אילמלי עולות ביבשה מיד מתות שביבשה אילמלי יורדות לים מיד מתות","יש לך בריות גדלות באור ויש לך בריות גדלות באויר שבאור אילמלי עולות לאויר מיד מתות שבאויר אילמלי יורדות לאור מיד מתות מה רבו מעשיך ה'","תנו רבנן כל שיש ביבשה יש בים חוץ מן החולדה אמר ר' זירא מאי קראה (תהלים מט, ב) האזינו כל יושבי חלד","אמר רב הונא בריה דרב יהושע ביברי דנרש אינן מן הישוב","אמר רב פפא בשמתא נרש תרביה משכיה ואליתיה (ירמיהו כב, כט) ארץ ארץ ארץ שמעי דבר ה' אמר רב פפא לא אבה נרש שמוע דבר ה'","אמר רב גידל אמר רב נרשאה נשקיך מני ככיך נהר פקודאה לוייך מגלימא שפירא דחזי עלך פומבדיתאה לוייך אשני אושפיזך","אמר רב הונא בר תורתא פעם אחת הלכתי לוועד וראיתי נחש שהוא כרוך על הצב לימים יצא ערוד מביניהם","וכשבאתי לפני ר' שמעון החסיד אמר לי אמר הקב\"ה הם הביאו בריה שלא בראתי בעולמי אף אני אביא עליהם בריה שלא בראתי בעולמי","והאמר מר כל שתשמישן ועיבורן שוה יולדין ומגדלין זה מזה וכל שאין תשמישן ועיבורן שוה אין יולדין ומגדלין זה מזה","אמר רב נס בתוך נס האי פורענותא הוא מאי נס בתוך נס לפורענות:","\u0001מתני׳\u0002 האבר והבשר המדולדלין בבהמה מטמאין טומאת אוכלין במקומן וצריכין הכשר"],[[0,"ת\"ל השורץ","הוה ליה למימר וזה לכם הטמא בשרץ הארץ וכתיב בשרץ השורץ על הארץ אייתר ליה השורץ לדרוש כל מקום שהוא יכול לשרוץ לרחוש ולנוע והרי אף בים הוא שט שמינו עכבר הארץ הלכך ע\"כ על הארץ למין הארץ הוא דאתא ולאו למעוטי ירד לים:"],[1,"או אינו","אומר השורץ לדרשה זו אלא למעוטי עכבר הנוצר מאדמה:"],[1,"שאין פרה ורבה","כלומר שלא היה מפריה ורביה של עכבר לפי שנוצר מאליו הואיל שאינו משריץ טהור דהאי שורץ לשון פרו וישרצו הוא (שמות א) ולא לשון ריחוש וניענוע ולעולם ירד לים לא יטמא דהכי קאמר על הארץ ואפילו עכבר הים ירד לים לא יטמא ואפילו של יבשה והשורץ ופרה ורבה יטמא שאינו שורץ לא יטמא:"],[2,"ודין הוא","דלא נימעטיה מכלל טומאה ולא נדרוש הכי דהא טימא כל ששמו עכבר וניחא ליה למדרש השורץ לרבויי ירד לים ולא למעוטי האי. ולקמיה פריך הא מטהר עכבר הים ממיעוטא דעל הארץ ומאי חזית דמיעוטא לעכבר הים ורבוי לירד לים:"],[3,"בשרץ","קרא יתירא הוא דהא כתיב בתרוייהו אלה הטמאים לכם בכל השרץ:"],[4,"ואימא השורץ","לא דרשינן ליה הכי כל מקום שהוא רוחש ולרבות עכבר הארץ שירד לים אלא הכי דרשינן השורץ כל שהוא פרה ורבה לרבות עכבר הים ומיעוט דעל הארץ דמשמע על הארץ יטמא ולאו שרץ הים אתא לאורויי דאחד זה ואחד זה על הארץ יטמאו ירדו לים אין מטמאין:"],[5,"א\"ל ומאחר דשויתיה לים מקום טומאה","דמרבית מין הים לטומאה:"],[5,"מה לי","בעודו בים מה לי יצא לחוץ אין נוח לדרוש המקראות במדה זו אלא לומר דבר המקובל:"],[6,"ופרכינן האי על הארץ מיבעי ליה להוציא ספק טומאה צפה","שרץ מת צף על המים ספק נגע ספק לא נגע אף ברשות היחיד ספקו טהור ומהאי קרא נפקא לן בפרק בתרא דנזיר (דף סד.) כתיב השרץ כל מקום ששורץ ואפילו על המים וכתיב על הארץ הא כיצד כאן בטומאת ודאי כאן בטומאת ספק:"],[8,"ערוד","מן הצב ומן הנחש הוא בא כדלקמן:"],[8,"וכן הנפילים","שרץ מין צב:"],[8,"וסלמנדרא","שרץ הנוצר מן האור מעצי הדס על ידי כשפים והסך מדמו אין האור שולט בו וקים ליה לר\"ע דמינא דצב הוא:"],[9,"לפסוק זה","משום דמיירי בסלמנדרא:"],[10,"יש לך בריות גדלות באור","סלמנדרא:"],[11,"יושבי חלד","יושבי הארץ שהוא מקום מיושב לחולדות:"],[12,"ביברי דנרש","חיות המצויות באותו מקום ביברונ\"ש בלע\"ז:"],[12,"אינן מן הישוב","אינן גדלות אלא במים:"],[13,"בשמתא נרש","כלומר כל יושביה רשעים כולם יהיו בשמתא:"],[13,"תרביה משכיה ואליתיה","החלב והעור עם הבשר והאליה כלומר כולן כקטן כגדול:"],[13,"לא אבה נרש כו'","לפי שכולן היו רשעים:"],[14,"נרשאה נשקיך מני ככיך","אם נשקך אחד מיושבי נרש מנה שניך אם תמצאם כולם כי מוחזק גנב הוא:"],[14,"נהר פקודאה","אם מיושבי נהר פקוד:"],[14,"לוייך","נתלוה עמך בדרך:"],[14,"מגלימא שפירא דחזי עלך","מחמת שראה לך טלית נאה ודעתו לגונבו נתחבר עמך:"],[14,"אשני אושפיזך","שלא ידע היכן תשכב שגנבים מומחין הם:"],[15,"לוועד","מקום רשעים ומרביעי כלאים:"],[15,"כרוך על הצב","כל שעה היה מצוי אצלו והיה נזקק עמו כדאמרינן בקדושין (דף עט:) בכרוכין אחריה ובבכורות (דף כד.) חזיר שכרוך אחר רחל כלומר נמשך ושוכן אצלו תמיד:"],[15,"יצא ערוד מביניהם","והיה נושך בני אדם וממית כדאמרינן בברכות (דף לג.) גבי ערוד דרבי חנינא בן דוסא:"],[16,"אנשי וועד הן הביאו כו'","מזווגי כלאים היו:"],[16,"אף אני אביא עליהם בריה כו'","והיינו ערוד:"],[17,"תשמישן שוה","שמשמשין שניהם פנים כנגד פנים כגון אדם או פנים כנגד עורף כגון בהמה:"],[17,"ועיבורן","ימי עיבור:"],[17,"יולדים זה מזה","מתעברים זה מזה:"],[17,"ומגדלין","מניקים זה בנו של זה. וימי עיבורו של נחש אינו שוה לא לשרץ ובהמה וחיה כדאמרינן בפ\"ק דבכורות (דף ח.) שועל וכל מיני שרצים לששה חדשים ונחש לשבע שנים ואמרינן התם ולאותו רשע נחש לא מצינו חבר והיאך יצא אותו ערוד מצב ומנחש:"],[18,"נס בתוך נס לפורענות","כדי ליפרע מן הרשעים:"],[19,"מתני' המדולדלין בבהמה","נתלש ממנה אבר בשר גידים ועצמות או נתלש ממנה בשר לבדו ועדיין הן מעורים בה במקצת. ויש הפרש בין אבר מן החי לבשר מן החי שהאבר מטמא אדם וכלים כנבלה והבשר שאינו אבר טהור מכלום כדילפינן לקמן בפירקין (חולין דף קכח:):"],[19,"במקומן","אע\"פ שהן מחוברין אם חישב עליהן להאכילן לעובד כוכבים הוי אוכל לקבל טומאה ולטמא אחרים דטומאת עצמן אין בהן עד שיתלשו כולן כדילפינן בגמרא אבל מקבלים טומאה מן השרץ ומטמאין בה את אחרים:"],[19,"וצריכין הכשר","לבא במים פעם אחת לאחר שנדלדלו ושוב מקבלים טומאה עולמית. וליכא למימר בהאי אבר שסופו לטמא טומאה חמורה דאינו מטמא טומאת אבר מן החי עד שימות ושמא לא יבא לידי טומאה חמורה דשמא ישחטנה ואין שחיטה עושה ניפול:"]],[[3,"תלמוד לומר בשרץ","וא\"ת למה לי קרא דבשרץ ממילא כיון דאיכא לאקושי לקולא ולחומרא לחומרא מקשינן דהא לעיל אי לא על הארץ למעוטי עכבר שבים הוה אזלינן לחומרא ואומר רבינו יצחק דאצטריך בשרץ לעכבר שחציו בשר וחציו אדמה משום דהשורץ משמע טפי כל שהוא משריץ:"],[5,"מה לי הכא ומה לי הכא","ומ\"מ אצטריך השורץ כל מקום ששורץ דלא נמעט מעל הארץ תרוייהו ירד לים ועכבר שבים:"],[12,"הני ביברי דנרש אינן מן הישוב","פירש בקונטרס ביברונ\"ש בלע\"ז שאין לוקים עליהן משום השרץ השורץ שהן גדלות במים ור\"ת אומר דגרסינן ביברי ונרש ועיירות הן כדמשמע בכיצד מעברין (עירובין דף נו.) הני מעלות ומורדות דביברי ונרש אזקינן ובפ\"ק דסוטה (דף י.) גבי וירד שמשון תמנתה ויעל יהודה תמנתה אמר רב פפא חדא תמנת הואי דמהאי גיסא סלקי ומהאי נחתי כמו [שם] ורדיניא וביברי [ושוקא] דנרש וקאי הכא אקרא דאייתי לעיל האזינו כל יושבי חלד וקאמר דהני אינן מן הישוב כלומר בכלל יושבי חלד כי רשעים הם וכיוצא בזה אמר פ\"ק דקדושין (דף מ:) כל שאינו לא במקרא ולא במשנה ולא בדרך ארץ אינו מן הישוב והיינו דאמר רב פפא בסמוך בשמתא נרש כו':"]]],[["נשחטה הבהמה הוכשרו בדמיה דברי רבי מאיר רבי שמעון אומר לא הוכשרו","מתה הבהמה הבשר צריך הכשר האבר מטמא משום אבר מן החי ואינו מטמא משום אבר נבלה דברי ר' מאיר ור' שמעון מטהר:","\u0001גמ׳\u0002 טומאת אוכלין אין טומאת נבלה לא","היכי דמי אי דמעלין ארוכה אפילו טומאת אוכלין נמי לא ליטמו ואי דאין מעלין ארוכה טומאת נבלה נמי ליטמו","לעולם דאין מעלין ארוכה ושאני טומאת נבלה דרחמנא אמר (ויקרא יא, לז) כי יפול עד שיפול","תניא נמי הכי האבר והבשר המדולדלין בבהמה ומעורין בחוט השערה יכול יטמאו טומאת נבלה תלמוד לומר יפול עד שיפול ואפילו הכי טומאת אוכלין מיטמו","מסייע ליה לרב חייא בר אשי דאמר רב חייא בר אשי אמר שמואל תאנים שצמקו באיביהן מטמאות טומאת אוכלין והתולש מהן בשבת חייב חטאת","לימא מסייע ליה ירקות שצמקו באיביהן כגון הכרוב והדלעת אין מטמאין טומאת אוכלין קצצן ויבשן מטמאין טומאת אוכלין","קצצן ויבשן ס\"ד עץ בעלמא הוא וא\"ר יצחק בעל מנת ליבשן","טעמא דכרוב ודלעת הוא כיון דיבשן לאו בני אכילה נינהו הא שאר פירות מטמאי","היכי דמי אי דיבשן הן ועוקציהן פשיטא אלא לאו בלא עוקציהן","לעולם הן ועוקציהן וקצצן על מנת ליבשן איצטריכא ליה","ת\"ש אילן שנפשח ובו פירות הרי הן כתלושין יבשו הרי הן כמחוברין מאי לאו מה תלושין לכל דבריהן אף מחוברין לכל דבריהן","מידי איריא הא כדאיתא והא כדאיתא:","נשחטה הבהמה [וכו']: במאי קא מיפלגי","אמר רבה בבהמה נעשית יד לאבר קמיפלגי מר סבר אין בהמה נעשית יד לאבר ומר סבר בהמה נעשית יד לאבר","אביי אמר באוחז בקטן ואין גדול עולה עמו קמיפלגי","מר סבר אוחז בקטן ואין גדול עולה עמו הרי הוא כמוהו ומר סבר אינו כמוהו","ואף ר' יוחנן סבר באוחז בקטן ואין גדול עולה עמו קא מיפלגי","דרבי יוחנן רמי דר\"מ אדר\"מ מי אמר ר' מאיר אוחז בקטן ואין גדול עולה עמו הרי הוא כמוהו","ורמינהו אוכל שנפרס ומעורה במקצת"],[[0,"נשחטה הבהמה","נטהרו מלטמא עוד משום נבילה ואע\"פ שאסורין באכילה כדאמרינן בבהמה המקשה (לעיל חולין דף עג:) מובשר בשדה טרפה ומידי נבלה טהרו דאין שחיטה עושה ניפול והוכשרו בדמיה לקבל טומאה בלא הכשר אחר:"],[1,"מתה הבהמה הבשר","שנדלדל צריך הכשר לקבל טומאה מן השרץ אם לא הוכשר משנדלדל דטומאת נבלה אין בו כדאמר בבהמה המקשה (שם דף עג:) דמיתה עושה ניפול ואינו כמתנבל עמה במיתתה אלא כפרוש מחיים ובשר הפורש מן החי טהור:"],[1,"האבר מטמא משום אבר מן החי כו'","כדפרישית טעמא דמיתה עושה ניפול כמו שנופל סמוך למיתה ואינו נבלה הלכך אינו מטמא משום נבלה. ובגמרא מפרש מאי איכא בין אבר מן החי לאבר מן הנבלה:"],[1,"ור\"ש מטהר","בגמרא מפרש טעמיה:"],[2,"גמ' טומאת נבלות לא","דלא הוי כתלושין לגמרי דליטמא האבר כשאר אבר מן החי דאמר לקמן שהוא מטמא אדם וכלים:"],[4,"כי יפול מנבלתם","אינו קרוי נבלה עד שיפול לגמרי וגבי שרצים כתיב דאבר מן החי דידהו נמי מטמא כדלקמן ובתרי קראי כתיב גבי שרצים כי יפול חד כי יפול מנבלתם עליו יטמא (ויקרא יא) וכתיב (שם) וכי יפול מנבלתם על כל זרע וגו' חד לאבר מן הבהמה דמיתה עושה ניפול אתא:"],[5,"ואפ\"ה טומאת אוכלין מטמו","בניחותא. כלומר ואע\"ג דמחוברין חשיבי לענין טומאת נבלות קתני מתניתין דלענין טומאת אוכלין תלושין נינהו ומקבלין טומאה כשאר אוכלין:"],[6,"מסייע ליה כו' שצמקו באיביהן","שיבשו באילן:"],[6,"חייב חטאת","אם לא יבשו עוקציהן. אלמא אע\"ג דלענין שבת מחוברין נינהו מטמאין טומאת אוכלין:"],[7,"לימא מסייע ליה","לשמואל:"],[7,"כגון הכרוב והדלעת","שלאחר שהן יבשים הרי הן כעץ ואינן ראויין לאכילה:"],[7,"אין מטמאין טומאת אוכלין","דהא לאו אוכל נינהו וקא ס\"ד דהיא גופה לא איצטריך דעץ לא יטמא אלא למימרא דהני הוא דכי צמקו באיביהן טהורין אבל שאר פירות הנאכלין בצימוקן מקבלין טומאה ואשמעינן דכתלושין דמו:"],[7,"קצצן","לחין על מנת ליבשן אע\"פ שאין עומדין למאכל אלא לעץ כגון דלעת לעשות הימנה כלי וכרוב להסקה אפ\"ה כל זמן שהן לחין מטמאין:"],[9,"","קתני רישא מיהת ירקות שצמקו באיביהן כגון הכרוב והדלעת טעמא דהני כי יבשו לאו אוכלין נינהו הא שאר פירות מטמאין באיביהן:"],[10,"והיכי דמי","הך מתניתא דקתני דכרוב ודלעת הוא דלא מטמו הא אחריני מטמו:"],[10,"אי דיבשו הן ועוקציהן","דאף לענין שבת תלושין הן:"],[10,"פשיטא","דמטמו למה ליה למתנייה לא איהי גופה איצטריך לאשמועינן דעץ לא יטמא ולאו דיוקא דידיה איצטריך לאשמועינן דאחריני מטמו דהא תלושין גמורין הן:"],[10,"אלא לאו בלא עוקציהן","ומשום דוקיא דידיה אצטריך למתנייה דאע\"פ דלענין שבת מחוברין הן לענין טומאה תלושין הן כדשמואל והיינו מסייע ליה:"],[11,"לעולם הן ועוקציהן","ודקא קשיא לן מאי קמ\"ל משום סיפא תנייה דאשמועינן קצצן לחין ע\"מ ליבשן מטמאין טומאת אוכלים:"],[12,"שנפשח","נתלש ממנו ענף ובאותו ענף יש פירות:"],[12,"הרי הן כתלושין","ואפילו הן לחין:"],[12,"יבשו","פירות האילן שלא נפשח הרי הן כמחוברין:"],[12,"מאי לאו אף מחוברין","דקאמר לכל דבריהם קאמר ואפילו לענין טומאה וקשיא לשמואל:"],[13,"הא כדאיתא והא כדאיתא","תלושין שנפשח לכל דבריהם הוו תלושין בין לענין חיוב טומאה בין לענין שבת ומחוברין דקתני גבי יבשו לשבת קאמר ולא לטומאה והיינו כשמואל:"],[14,"במאי קא מיפלגי","ר' מאיר ור' שמעון לגבי הכשר:"],[15,"אמר רבה בבהמה נעשית יד לאבר קמיפלגי","ותרוייהו אית להו יש יד להכשר ומיהו רבי שמעון סבר אין בהמה כולה נעשית יד לאבר אחד הלכך לא הביאה לו הכשר ורבי מאיר סבר בהמה נעשית יד לאבר:"],[16,"אביי אמר","אין טעמייהו משום יד דכ\"ע אין בהמה נעשית יד לאבר אחד אלא טעמא דרבי מאיר משום דכולה חדא חשיב ליה ואע\"ג דכי אוחז את הקטן באבר ובשר המדולדל אין גדול עולה עמו אלא נתלש מיד הואיל וכשאוחז בגדול עולה קטן עמו חד הוא ור' שמעון סבר אינו כמוהו:"],[20,"אוכל","תרומה:"],[20,"שנפרס","לשון פרוסה נשבר:"]],[[4,"דרחמנא אמר כי יפול עד שיפול","תימה מאי משמע כי יפול לענין זה דאבר המדולדל ועוד דהאי קרא בשרצים כתיב ונראה דהכי דריש כי יפול מהם במותם ואמר בפרק בהמה המקשה (לעיל חולין דף עד.) מיתה עושה ניפול וא\"כ ממילא שמעינן דקודם מיתה אינה עושה ניפול ואבהמה דרשי ליה דאמר התם מיתה עושה ניפול ואין שחיטה עושה ניפול ופירש בקונטרס דמקרא יתירא דרשינן ואם אינו ענין לשרצים תנהו ענין לבהמה דבת שחיטה היא:"],[5,"טומאת נבלה","שמזכיר כאן הש\"ס לאו דוקא אלא היינו טומאת אבר מן החי:"],[6,"מסייע ליה לרב חייא כו'","וא\"ת למאי מייתי ליה סייעתא אי להא דאמר תאנים שצמקו באיביהן מטמאין טומאת אוכלין טפי הוה ליה למסייעיה ממתניתין ונראה דמייתי סייעתא אמאי דקאמר התולש מהן בשבת חייב חטאת דמשמע נמי מברייתא דלאו לכל מילי הוה כתלוש מדקא ממעט טומאת נבלה כלומר טומאת אבר מן החי ומקרא ממעט ליה ובמתניתין ליתיה בפירוש אלא מדיוקא שמעינן ליה טומאת אוכלין אין טומאת נבלות לא:"],[7,"לימא מסייע ליה ירקות שצמקו","הא מייתי שפיר אפילו אטומאת אוכלין ומייתי סייעתא אהא דצמקו הוי כמדולדלים:"],[11,"וקצצן על מנת ליבשן איצטריכא ליה","וא\"ת ליתני הכי כרוב ודלעת שקצצן על מנת ליבשן מטמא טומאת אוכלין למה ליה למתני רישא שצמקו באיביהן וי\"ל דהכי מתני ליה טפי שפיר הכרוב והדלעת שצמקו כו' ואם לא צמקו אלא קצצן ע\"מ ליבש כו':"],[15,"ומר סבר אין בהמה נעשית יד לאבר","נראה דרבה מצי סבר דלר\"ש שחיטה מכשרת ולא דם וה\"ק אין בהמה נעשית יד לאבר הא אם נעשית יד לאבר היה מוכשר משחיטת בהמה אע\"פ שהוא אסור באכילה מדרבנן וכן סברי כולהו אמוראי דמפרשי מתניתין לבר מר' אחא דאמר בנתקנח הדם בין סימן לסימן קמיפלגי דלדידיה דם מכשיר לר\"ש וצ\"ל דלרב אחא לא שמיע ליה ברייתא דהשוחט (לעיל חולין דף לו.) דשמעינן מיניה דלר' שמעון שחיטה מכשיר ולא דם אבל שאר אמוראי דהכא הוו ידעי לה שפיר דהא רב פפא נמי מפרש לה לפלוגתייהו בסמוך ובפרק השוחט (גז\"ש) אמר רב פפא עלה דברייתא הכל מודים היכא דאיתיה לדם כו' אלמא ידע לה:"]]],[["רבי מאיר אומר אם אוחז בקטן וגדול עולה עמו הרי הוא כמוהו ואם לאו אינו כמוהו","ואמר רבי יוחנן מוחלפת השיטה","ומאי קושיא דילמא שני ליה לר\"מ בין טבול יום לשאר טומאות","תניא רבי אומר אחד טבול יום ואחד שאר טומאות","ודילמא לרבי לא שני ליה ולר' מאיר שני ליה","אמר ר' יאשיה הכי אמר ר' יוחנן לדברי רבי מוחלפת השיטה","רבא אמר ביש יד לטומאה ואין יד להכשר קמיפלגי","מר סבר יש יד לטומאה ואין יד להכשר ומר סבר יש יד לטומאה ולהכשר","רב פפא אמר בהכשר קודם מחשבה קמיפלגי","דתנן אמר ר' יהודה כך היה רבי עקיבא שונה חלב שחוטה בכפרים צריך מחשבה ואין צריך הכשר שכבר הוכשר בשחיטה","אמרתי לפניו למדתנו רבינו עולשין שלקטן והדיחן לבהמה ונמלך עליהן לאדם צריכות הכשר שני וחזר רבי עקיבא להיות שונה כרבי יהודה","מר סבר לה כמעיקרא ומר סבר לה כחזרה","רב אחא בריה דרב איקא אמר בנתקנח הדם בין סימן לסימן קמיפלגי","מר סבר ישנה לשחיטה מתחלה ועד סוף והאי דם שחיטה הוא ומר סבר אינה לשחיטה אלא לסוף והאי דם מכה הוא","רב אשי אמר בשחיטה מכשרת ולא דם קמיפלגי","בעי רבה בהמה בחייה מהו שתעשה יד לאבר תיקו","אמר אביי הרי אמרו קישות שנטעה בעציץ והגדילה ויצאת חוץ לעציץ טהורה","אמר ר\"ש וכי מה טיבה לטהר אלא הטמא בטומאתו וטהור בטהרתו","בעי אביי מהו שתעשה יד לחברתה תיקו","אמר רבי ירמיה הרי אמרו המשתחוה לחצי דלעת אסרה בעי ר' ירמיה"],[[0,"הרי הוא כמוהו","ואם נגע טבול יום באחד מן השברים פסל את חבירו:"],[0,"ואם לאו","חבירו טהור ואע\"פ שנוגעין זה בזה אין שלישי עושה רביעי בתרומה. וגבי טבול יום תנינא לה במסכת יומא (דף יט.):"],[1,"מוחלפת השיטה","כאן החליף ר\"מ שיטתו אבל בעלמא ס\"ל אוחז בקטן ואין גדול עולה עמו הרי הוא כמוהו ומדקאמר רבי יוחנן הכי ש\"מ דס\"ל דבאוחז בקטן ואין גדול עולה עמו קא מיפלגי:"],[2,"ומהדר הש\"ס ומאי קשיא","ליה לרבי יוחנן דלמא אע\"ג דמיקל ר\"מ בטבול יום שהוא טומאה דרבנן מחמיר הוא בטומאה חמורה:"],[3,"תניא רבי אומר","תירוצא הוא כלומר הא תני רבי דלא שני ליה:"],[3,"אחד טבול יום ואחד שאר טומאות","אין חילוק בנגיעתם דהקרויה בשאר טומאות נגיעה הוי בטבול יום נמי נגיעה:"],[4,"לדברי רבי דלא שני ליה","החליף ר\"מ שיטתו דהא כל היכא דהויא נגיעה בטבול יום הויא נגיעה בשאר טומאות והא שמעינן לר\"מ דמתניתין דאע\"ג דאין גדול עולה עמו חבור הוא:"],[6,"רבא אמר ביש יד להכשר","כי היכי דילפינן יד לטומאה בריש פרקין (חולין דף קיח.) קמיפלגי ודכ״ע בהמה נעשית יד לאבר:"],[8,"בהכשר קודם מחשבה קמיפלגי","ודכ\"ע יש יד לטומאה ולהכשר אלא ששחטה קודם שחישב להאכילו לעובד כוכבים דקדם הכשר למחשבה ר\"ש סבר כיון דבשעת הכשר אכתי לאו בר קבולי טומאה הוא דסתמיה לאו לאכילה קאי שאף לבן נח אסור הוא הכשר נמי לא מקבל:"],[9,"חלב","אין דרכו לאוכלו בכפרים מפני שהעם מועט ויש להם בשר הרבה לצורך סיפוקן אבל בכרכים העם מרובה ואין להם בשר לכל הצורך אוכלין אותו ע\"י הדחק. א\"נ משום הכי אין דרכן לאוכלו בכפרים משום דעניים הם אבל בני כרכים שהם עשירים אוכלין אותו:"],[9,"הוכשר בשחיטה","ואע\"ג דקדם הכשר למחשבה:"],[10,"עולשים","עשב שקורין קרשפיל\"א:"],[10,"שלקטן","לבהמה והוכשרו ואח\"כ נמלך עליהם לאדם צריכין הכשר שני מפני שקדם הכשר למחשבה ור\"מ סבר לה כי היכי דא\"ר עקיבא מעיקרא מאכל בהמה אינו מקבל טומאה:"],[12,"בנתקנח הדם כו'","ודכ\"ע אין יד להכשר אבל יש יד לטומאה ופלוגתייהו בשניתז הדם על האבר וקינחו בין סימן לסימן:"],[13,"דם מכה","אינו מכשיר דם חללים קרוי משקה ולא דם מכה:"],[14,"רב אשי אמר","דכ\"ע אית יד להכשר והאי אבר אית ליה יד דבהמה נעשית יד לאבר א\"נ ס\"ל אוחז בקטן ואין גדול עולה עמו הרי הוא כמוהו וכשניתז הדם על האבר ולא נתקנח קא מיפלגי ר\"מ סבר דם מכשיר והרי הוכשר ור\"ש לטעמיה דאמר בפרק שני (לעיל חולין לו.) שחיטה מכשרת ולא דם והאי אבר כיון דלא מהניא ליה שחיטה להתירו באכילה אע\"ג דמהניא ליה לטהוריה מידי נבלה לא מכשרה ליה לטומאה דטעמא דשחיטה מכשרת היינו משום דכיון דמשויא ליה אוכלא לענין היתר אכילה משויא ליה נמי אוכלא לענין טומאה והכא ליכא למימר הכי:"],[15,"בעי רבה כו'","רבה אוקים פלוגתייהו לעיל בבהמה נעשית יד לאבר בעי רבה לר\"מ דאמר בהמה נעשית יד לאבר בשחיטה לענין הכשר בחייה מהו שתעשה יד להכניס ולהוציא טומאה היכא דהוכשר במים לאחר דלדולו דאמרינן במתניתין דמקבלין טומאה במקומן ואם נגע טומאה בבהמה מהו שתעשה יד להביא טומאה לאבר מי אמרינן כיון דבעלי חיים לא מקבלי טומאה יד נמי לא הוו או דילמא נהי דאיהי גופה טהורה יד לאבר מיהא הויא כי היכי דאמרינן גבי עצם דבשר ואוכל עליו שהוא יד לבשר להכניס ולהוציא טומאה אע\"פ שאין עצם בלא בשר מקבל טומאה:"],[16,"קישות שנטעה בעציץ","שאינו נקוב כתלושה דמיא ומקבלת טומאה כשאר אוכלין או אם היתה טמאה הרי היא בטומאתה ואם הגדילה ויצאה נופה לחוץ ונוטה על הארץ ויונק מריח הארץ דרך אויר כמחובר דמיא וטהרה כל הקישות שבעציץ לפי שחוזרים ויונקין מן הנוף הנוטה חוץ לעציץ:"],[17,"הטמא בטומאתו","מה שבתוך העציץ מקבל טומאה לפי שהוא כתלוש:"],[17,"והטהור","הנוף שיצא לחוץ ויונקת מריח הארץ דרך אויר כמחובר וטהורה:"],[18,"","לר\"ש מהו שיעשה נוף הטהור יד לקישות להביא לה טומאה:"],[19,"המשתחוה לחצי דלעת אסרה","בהנאה משום עבודה זרה ולר\"ש איסורי הנאה אין מטמאין טומאת אוכלין דנפקא ליה לקמן (חולין דף קכט.) מכל האוכל אשר יאכל דבעינן שאתה יכול להאכילו לאחרים והא הדלעת איסורי הנאה היא ותו לא מטמא טומאת אוכלין ונהי דטומאה יוצאה לה מגופה דהא עבודה זרה מטמאה כשרץ שנאמר (דברים ז) שקץ תשקצנו ולר\"ע מטמאה כנדה שנאמר (ישעיהו ל) תזרם כמו דוה מיהו ההיא טומאה דרבנן היא כדאמרינן בפרק ר\"ע (שבת דף פג:) וקרא אסמכתא בעלמא הוא:"]],[[0,"רבי מאיר אומר אם אוחז בקטן וגדול עולה עמו","ה\"ג בספרים ובפי' ר\"ת ובמסכת טבול יום (פ\"ג מ\"א) אינו כן דגרסינן ר\"מ אומר אם אוחז בגדול וקטן עולה עמו הרי הוא כמוהו רבי יהודה אומר אם אוחז בקטן וגדול עולה עמו הרי הוא כמוהו ולהך גירסא תימה מאי פריך הכא דר\"מ אדר\"מ ולא מסתבר לפרש דר' יוחנן דאמר באוחז בקטן ואין גדול עולה עמו אליבא דר\"מ לאו דוקא אלא גם הקטן אין עולה עם הגדול דלא משמע הכי:"],[15,"בהמה בחייה מהו שתעשה יד לאבר","תימה מאי מבעיא ליה אי משום דבהמה בחייה לאו בת קבולי טומאה היא כל ידות שבעולם נמי לא מקבלי טומאה אלא שמכניסות ומוציאות טומאה וי\"ל דלא דמי לשאר ידות דמאי דלא מקבלי טומאה משום שאינן אוכל אבל בעלי חיים כי נמי הוי אוכל כגון בן פקועה איכא למ\"ד פרק בהמה המקשה (לעיל חולין דף עה.) דלא מקבל טומאה:"],[16,"קישות שנטעה בעציץ והגדילה ויצאה חוץ לעציץ טהורה","ואע\"ג דאמר בפרק המביא גט (גיטין כב. ע\"ש) אילן בארץ ונופו נוטה בחוצה לארץ בתר עיקרו אזלינן התם מרובה יניקתו במקום העיקר אבל עיקרו בעציץ אין יניקת השרשים מרובה ואין הנופות יונקות מן העציץ:"],[17,"אלא הטמא בטומאתו והטהור בטהרתו","ואע\"ג דבעציץ נקוב אמרינן בהמצניע (שבת צה:) דלרבי שמעון הוי כמחובר לענין הכשר זרעים ומסתמא הוא הדין לענין טומאה התם ע\"י הנקב הוי כמחובר אבל הכא ע\"י מה שיוצא לחוץ לא יהא מה שבפנים כמחובר:"],[19,"הרי אמרו המשתחוה לחצי דלעת אסרה בעי רבי זירא מהו שתעשה יד לחברתה","לפי' שני שבקונטרס דמבעיא ליה אי הויא חציה שלא השתחוה לה יד להוציא טומאה או לא כלום נעשה יד אוכל לאוכל אחר או לא תימה דבכולה שמעתין מוכח דאוכל נעשה יד לאוכל לקמן כוליא של נבלה בחלבה נעשה החלב יד לכוליא ולעיל נמי לא פליגי אלא בבהמה אם נעשית יד לאבר משום שהבהמה דבר גדול ואינה ראויה להיות יד אבל אם היו שוין הבהמה והאבר הויא יד לכ\"ע ועוד אמאי נקט דלעת ליבעי בשתי חתיכות בשר המדובקין בעור ונטמאה אחת מהן בשרץ ואין לומר נמי דבדלעת מחוברת איירי והחצי טמא מידי דהוה אאשרה וקא מבעיא ליה אי הוי יד אידך להוציא טומאה כיון שהוא מחובר כדמבעיא ליה בקישות שנטעה בעציץ דאכתי אמאי נקט דלעת לימא המשתחוה לחצי אילן ונראה כלשון ראשון שפירש בקונטרס דבעי אם נגע שרץ בחצי שהשתחוה אם נעשית יד לחצי האחר הואיל ואין ראוי לקבל טומאה לר\"ש דאמר אוכל שאין יכול להאכילו לאחרים אינו אוכל ולא דמי לשאר ידות דהתם אין מקבלות טומאה לפי שאינן ראויות לאכילה ועץ בעלמא הן אבל הכא אוכל גמור הוא אבל דבר אחר גורם לו שאין ראוי להאכילו לאחרים כדפרישית לעיל גבי בהמה בחייה מהו כו':"]]],[["מהו שתעשה יד לחברתה תיקו","אמר רב פפא הרי אמרו יחור של תאנה שנפשח ומעורה בקליפתה ר' יהודה מטהר וחכמים אומרים אם יכול לחיות טהור ואם לאו טמא","בעי רב פפא מהו שיעשה יד לחבירו תיקו","אמר רבי זירא הרי אמרו אבן שבזוית כשהוא חולץ חולץ את כולה וכשהוא נותץ נותץ את שלו ומניח את של חבירו","בעי רבי זירא מהו שתעשה יד לחברתה תיקו:","מתה הבהמה: מאי איכא בין אבר מן החי לאבר של הנבלה","איכא בינייהו בשר הפורש ממנו מאבר בהמה דאילו בשר הפורש מאבר מן החי לא מטמא מאבר מן הנבלה מטמא","אבר מן החי דמטמא מאי קרא אמר רב יהודה אמר רב (ויקרא יא, לט) וכי ימות מן הבהמה","והאי מיבעי ליה לכאידך דרב יהודה אמר רב דאמר רב יהודה אמר רב ואמרי לה במתניתא תנא וכי ימות מן הבהמה מקצת בהמה מטמאה ומקצת בהמה אינה מטמאה ואיזו זו זו טרפה ששחטה","אם כן לכתוב רחמנא מבהמה מאי מן הבהמה ש\"מ תרתי","אי הכי אפילו בשר נמי לא ס\"ד דתניא יכול יהא בשר הפורש מן החי טמא ת\"ל וכי ימות מן הבהמה מה מיתה שאינה עושה חליפין אף כל שאינו עושה חליפין דברי ר' יוסי","ר' עקיבא אומר בהמה מה בהמה גידים ועצמות אף כל גידים ועצמות רבי אומר בהמה מה בהמה בשר גידים ועצמות אף כל בשר גידים ועצמות","מאי איכא בין רבי לר\"ע איכא בינייהו ארכובה","בין ר\"ע לר' יוסי הגלילי מאי איכא בינייהו אמר רב פפא כוליא וניב שפתים איכא בינייהו","תניא נמי גבי שרצים כהאי גוונא יכול בשר הפורש מן השרצים יהא טמא ת\"ל (ויקרא יא, לב) במותם מה מיתה שאינה עושה חליפין אף כל שאינה עושה חליפין דברי רבי יוסי הגלילי","ר\"ע אומר שרץ מה שרץ גידים ועצמות אף כל גידים ועצמות רבי אומר שרץ מה שרץ בשר גידים ועצמות אף כל בשר גידים ועצמות","בין רבי לר\"ע איכא בינייהו ארכובה בין ר\"ע לר' יוסי הגלילי מאי איכא בינייהו אמר רב פפא כוליא וניב שפתים איכא בינייהו","וצריכא דאי אשמעינן בהמה היינו טעמא דלא מטמא מחיים משום דלא מטמא בכעדשה אבל שרץ דמטמא בכעדשה אימא לטמא מחיים","ואי אשמועינן שרץ משום דלא מטמא במשא לא מטמא מחיים אבל בהמה דמטמא במשא אימא תטמא מחיים צריכא","ת\"ר החותך כזית בשר מאבר מן החי חתכו ואח\"כ חישב עליו טהור","חישב עליו ואח\"כ חתכו טמא","רבי אסי לא על לבי מדרשא אשכחיה לרבי זירא א\"ל מאי אמור בבי מדרשא א\"ל מאי קשיא לך אמר ליה דקתני חישב ואח\"כ חתכו טמא"],[[0,"מהו שתעשה יד לחברתה","לענין טומאה דאורייתא לקבל טומאה מן השרץ כדי להביאה לחברתה להיות חברתה ראשונה כאילו נגע עצמה בטומאה. שניה לטומאה פשיטא לן דלא הויא ההיא חברתה שהרי זו לא קבלה טומאה לעצמה. לישנא אחרינא לענין טומאת עבודה זרה קמיבעיא ליה דזו שנעשית עבודה זרה הרי היא כשרץ וחציה השני מי הוה לה יד והנוגע בה כנוגע בעבודה זרה או דילמא לא הוי לה יד וטהור הנוגע בה כגון אם לא הוכשרה דאין עליה תורת אוכל לקבל טומאה מחברתה אי נמי הוכשרה הויא לה איהי ראשון והנוגע בה הוי שני נעשה האוכל יד לאוכל אחר או לא:"],[1,"יחור","נוף:"],[1,"רבי יהודה מטהר","דאכתי מחובר הוא:"],[1,"אם יכול לחיות","הוי מחובר וטהור:"],[1,"ואם לאו","הרי הוא כתלוש וטמא:"],[2,"מהו שיעשה יד לחבירו","אם נפשח מיחור זה יחור אחר ומעורה בו בקליפתו ואינו יכול לחיות והוי תלוש והראשון יכול לחיות מהו שיעשה זה שיכול לחיות ואינו מקבל טומאה בית יד לזה התלוש ומביא לו טומאה. א\"נ אם יחור זה אינו יכול לחיות מהו שיעשה לו האילן יד להביא טומאה על פירות שביחור:"],[3,"אבן","המנוגעת:"],[3,"שבזוית","שנראה בבית זה ובבית זה שכן דרך הזויות לתת שם אבנים גדולות המחזיקים את כל עובי הכותל ונראה משני צדדים:"],[3,"כשהוא חולץ","לסוף שבוע של הסגר כדכתיב (ויקרא יד) וחלצו את האבנים:"],[3,"חולץ את כולו","דהא אבן כתיב כמות שהיא או גדולה או קטנה:"],[3,"וכשהוא נותץ","אם הוחלט הבית ובא לנותצו:"],[3,"נותץ את שלו","חולץ את האבן ונותץ את צד שלו:"],[3,"ומניח את חלק חבירו","דהא כתיב (שם) ונתץ את הבית ולא שתי בתים:"],[4,"מהו שיעשה","חלק הטהור בית יד לזה להכניס טומאה לבית חבירו דהא אבן המנוגעת מטמאה באהל כדכתיב (שם) והבא אל הבית:"],[6,"איכא בינייהו בשר הפורש מן האבר","לאחר זמן. בשר הפורש מן החי לא מטמא אא\"כ הוי אבר עם הגידים והעצמות כדיליף לקמן וכ\"ש בשר הפורש מן אבר מן החי:"],[6,"מאבר מן הנבלה מטמא","דהא איכא כזית נבלה:"],[8,"מן הבהמה ממקצת בהמה","כגון אבר ממנה מדכתיב וכי ימות מן דמשמע כעין מיתה שאינה עושה חליפין והיינו אבר וסיפיה דקרא הנוגע בנבלתה יטמא:"],[8,"ומקצת בהמה אינה מטמאה","ואף על פי שהיא כמתה כגון טרפה ששחטה:"],[8,"וכי ימות","מיניה נפקא לן אבר כדאמרינן וקרייה מתה אלמא כעין מיתה בעינן שאינה חוזרת:"],[10,"עושה חליפין","חוזרת לקדמותה ובשר עושה חליפין אם יתלוש בשר מן הבהמה אחר עולה תחתיו:"],[11,"מה בהמה גידין ועצמות","לקמיה מפרש מאי בינייהו:"],[11,"","ה\"ג רבי אומר בהמה מה בהמה בשר גידים ועצמות כו':"],[12,"בין רבי לר\"ע א\"ב רכובה","רכובה הנמכרת עם הראש אין בה בשר כלל אלא גידים ועצמות לר\"ע אבר הוא וכ\"ש לרבי יוסי הגלילי דהא אינו עושה חליפין ולרבי לאו אבר מן החי הוא דהא אין בו בשר:"],[13,"בין ר\"ע לרבי יוסי הגלילי איכא בינייהו כוליא וניב שפתים","דאין עושין חליפין ואין בהן עצם לרבי יוסי הוו אבר לר\"ע לאו אבר נינהו:"],[14,"בשר הפורש מן השרצים","מן החי דאבר מן החי נוהג בהן:"],[17,"דאי אשמועינן בהמה היינו טעמא דלא מטמא","בשר מן החי דידה משום דלא מטמא בכעדשה:"],[17,"","שרץ לא כתיב ביה משא בהמה כתיב בה משא:"],[19,"החותך כזית בשר מאבר מן החי","בתוספתא לא גרסינן כזית אלא החותך בשר מאבר מן החי וכגון דאיכא כביצה:"],[19,"חתכו ואח\"כ חישב עליו","להאכילו לעובד כוכבים:"],[19,"טהור","דהא בשר הפורש מאבר מן החי טהור הלכך טומאת עצמו אין בו ומשחישב עליו לא נגע בטומאה שיקבלנה אבל חישב עליו והורידו באביו באבר לתורת אוכל ואחר כך חתכו קבל טומאה מאביו קודם לכן מטומאה חמורה שהיתה עליו בעודו אבר שלם כשחתכו והלכה לה טומאה חמורה נשארה עליו הקלה שלא היה לו עד עתה:"],[21,"(מאי קשיא לך) א\"ל","הכי קשיא לי דקתני בההיא ברייתא חישב כו' ואמאי היא טמאה כו':"]],[[1,"רבי יהודה מטהר","הא דאמר לעיל (חולין דף קכז:) תאנים שצמקו באיביהן מטמא טומאת אוכלין אתיא דלא כרבי יהודה א\"נ צמקו לא הוי אפילו כמעורה:"],[13,"כוליא וניב שפתים איכא בינייהו","פירוש כוליא שלמה וניב שפתים שלם אבל חצי כוליא וחצי ניב שפתים אע\"פ שאין עושה חליפין אינו מטמא דגמרינן מבהמה מתה שהיא דבר חשוב אף אבר שהוא חשוב ואע\"ג דרבי יוסי הגלילי לא יליף מבהמה לענין דבעי חשיבות קצת יליף אבל אין לומר שאפילו חצי כוליא וחצי ניב שפתים הואיל ואין עושין חליפין מטמו דהא עצם אין עושה חליפין ואם נשבר ונפל מבהמה בחייה מסתמא לא מטמא דלא עדיף עצם מן החי מעצם דנבלה דאמר בנבלתה ולא בעצמות ועצם כשעורה מן המת מטמא אבל פחות לא אע\"ג דאין עושה חליפין וא\"ת דהכא אמר דבשר עושה חליפין חוץ מכוליא וניב שפתים ובפרק דם הנדה (נדה דף נה.) אמר מה עצם שאין גזעו מחליף ופריך והרי בשר כו' ומשני דמקומו נעשה צלקת וי\"ל דהכא מעניניה דקרא והתם מעניניה התם דומיא דעצם שמתרפא קצת אבל אין מתרפא כבתחלה ובשר נמי נעשה צלקת והכא דומיא דמיתה שאינה עושה חליפין כלל ולכך נקט הכא לשון חליפין והתם נקט גזעו מחליף:"],[16,"בין רבי לר\"ע איכא בינייהו בשר","אית' ספרים דגרסי רכובה וכן נראה דמשום הכי לא בעי ר\"ע בשר דאיכא אבר בבהמה דהיינו רכובה שאין עליו בשר ורבי לא אזיל אלא בתר רוב אברים ולא מטמא אפילו ברכובה גופה אבל אי לאו רכובה לא הוה ידעינן טעמא דר\"ע מ\"ט לא דריש נמי מבהמה דנבעי בשר דטעמא דר' יוסי הגלילי ניחא דלא דריש מידי מבהמה וריב\"א פי' דברכובה כ\"ע לא פליגי כיון שנבראת כך בלא בשר לא גרעה משאר איברים ולא פליגי אלא דוקא באבר שהיה עליו בשר והוסר:"]]],[["טומאת בית הסתרים היא וטומאת בית הסתרים לא מטמא","אמר ליה אף לדידי קשיא לי ושאילתיה לרבי אבא בר ממל ואמר לי הא מני רבי מאיר היא דאמר טומאת בית הסתרים מטמא","אמר ליה ולאו זימנין סגיאין אמרה קמאי ואמרי ליה שני ליה לר' מאיר בין טומאה דבעיא הכשר ובין טומאה דלא בעיא הכשר","אמר רבא ומאי קושיא דלמא בשהוכשר","אמר ליה רבה בר רב חנן לרבא למה לי הכשר הרי מטמא טומאה חמורה אגב אביו","אמר ליה כששימש מעשה עץ שימש","אמר אביי הרי אמרו כופת שאור שיחדה לישיבה בטלה","טומאתה לאו דאורייתא דאי סלקא דעתך דאורייתא מצינו לאוכלין שמטמאין טומאה חמורה כששימש מעשה עץ שימש","אמר אביי הרי אמרו תקרובת עבודת כוכבים של אוכלין מטמאין באוהל טומאתה לאו דאורייתא דאי סלקא דעתך דאורייתא מצינו לאוכלין שמטמאין טומאה חמורה כששימש מעשה עץ שימש","אמר אביי הרי אמרו חבורי אוכלין ככלים דמו טומאתן לאו דאורייתא דאי סלקא דעתך דאורייתא מצינו לאוכל שמטמא טומאה חמורה כששימש מעשה עץ שימש","א\"ל רב פפא לרבא הא דתניא חלב נבלה בכפרים צריך מחשבה והכשר טומאתו אגב כוליא לאו דאורייתא דאי סלקא דעתך דאורייתא מצינו לאוכל שמטמא טומאה חמורה","כששימש מעשה עץ שימש","אמר רב מתנה הרי אמרו בית שסככו בזרעים טהרו טומאתו לאו דאורייתא דאי סלקא דעתך דאורייתא מצינו לזרעים שמטמא טומאה חמורה כששימש מעשה עץ שימש:","ר\"ש מטהר:","מה נפשך אי מיתה עושה ניפול ליטמא משום אבר מן החי אי אין מיתה עושה ניפול ליטמא משום אבר מן הנבלה","ר\"ש ארישא קאי האבר והבשר המדולדלין בבהמה מטמא טומאת אוכלין במקומן וצריכין הכשר ורבי שמעון מטהר","אמר רבי אסי אמר רבי יוחנן מ\"ט דר\"ש אמר קרא (ויקרא יא, לד) מכל האוכל אשר יאכל אוכל שאתה יכול להאכילו לאחרים קרוי אוכל אוכל שאי אתה יכול להאכילו"],[[0,"טומאת בית הסתרים היא","היאך קבל טומאה במחובר והלא מגעו בסתר וקיי\"ל בנדה (דף מא:) מקרא דטומאת בית הסתרים לא מטמיא:"],[1,"ר\"מ היא","בבהמה המקשה (לעיל חולין עב.) הוציא עובר את ידו ושחט את אמו ואח\"כ חתכו בשר העובר מגע נבילה שקבל טומאה מאבר היוצא שהיה מחובר לו והוא מטמא כאבר מן החי:"],[2,"א\"ל","רבי אסי לר' זירא בהא דר' אבא בר ממל לא איכפת לי דהא זימנין סגיאין אמרה להאי טעמא קמאי ואמרי ליה אנא:"],[2,"שני ליה לר\"מ בין טומאה דבעיא הכשר כו'","ההיא דבהמה המקשה הוכשר העובר בשחיטת אמו ועדיין האבר הטמא מחובר בו וטמאו אבל משנתינו תנן הבשר צריך הכשר וכיון דצריך הכשר לא הוכשר קודם חתיכה והיאך מקבל טומאה מאביו:"],[3,"בשהוכשר","קודם חתיכה קתני הך ברייתא דטמאה:"],[4,"הרי מטמא טומאה חמורה אגב אביו","בעודו מחובר באבר היה אב הטומאה לטמא אדם וכלים ותנא דבי ר' ישמעאל לעיל בפירקין (חולין דף קכא.) מה זרעים שאין סופן לטמא טומאה חמורה צריך הכשר אף כל שאין סופו לטמא טומאה חמורה צריך הכשר אבל מי שסופו לטמא טומאה חמורה כגון נבלת עוף טהור לא וכ\"ש זה שכבר טימא:"],[5,"כששימש","אותו שמוש טומאה חמורה לאו בתורת אוכל שמשה שאין האבר מטמא כלום ע\"י אותו בשר אלא בתורת עץ שימש שנחשב ונמנה עם הגידין והעצמות ליעשות אבר והן כעץ והשתא אתעביד ליה אוכל ופנים חדשות באו לכאן ולא דמי לנבלת עוף טהור שהיא מטמאה אדם על ידי אכילה:"],[6,"הרי אמרו","בפסחים באלו עוברין (פסחים דף מה:):"],[6,"כופת שאור","מוטיי\"ל בלע\"ז:"],[6,"שיחדה לישיבה בטלה","מתורת חמץ ואינו עובר עליו בפסח משום שאור לא ימצא בבתיכם אלמא לאו אוכל הוא ונעשית כלי ומטמאה מושב הזב שהרי אין אומרין לו עמוד ונעשה מלאכתנו שהרי יחדה לכך אומר אני דטומאה שאנו מטמאין אותו משום מושב הזב לאו דאורייתא אלא דרבנן היא דאמור רבנן בטלה ונעשת כלי:"],[7,"דאי ס\"ד דאורייתא","א\"כ מצינו אוכלין שסופן לטמא טומאה חמורה מאחר שירדו לתורת אוכלים ואנן אמרינן מה זרעים שאין סופן לטמא טומאה חמורה כו':"],[7,"","ומשני לעולם טומאתם דאורייתא ודקאמרת מצינו לאוכלים שמטמאים כו' כששימש אותו שימוש טומאה חמורה לאו בתורת אוכל שימשה אלא מעשה עץ שימש ע\"י מעשה עץ הוא עושה אותה שבטל מתורת אוכל ונעשה עץ:"],[8,"הרי אמרו תקרובת עבודת כוכבים של אוכלין מטמא באהל","וקאמר אביי אומר אני טומאה זו לאו דאורייתא וקרא אסמכתא בעלמא:"],[8,"דאי דאורייתא","מצינו אוכלין שסופן לטמא אדם:"],[8,"מעשה עץ","שאסורים בהנאה ובטלו מאכילה ונעשו כעצים הנעבדים:"],[9,"הרי אמרו","באלו עוברין (פסחים מה:):"],[9,"חבורי אוכלים","שבכלים הרי הם ככלים ואם נגעה טומאה באוכל נטמא הכלי דתנן (שם) בצק שבסדקי עריבה לענין הטומאה אם רוצה בקיומו הרי הן כעריבה ואומר אני טומאתו זו שהוא נעשה כלי ואם נגע במת חוזר ומטמא אדם לאו דאורייתא:"],[10,"חלב נבלה","דבהמה טהורה אינו מטמא כנבלה דנפקא לן מיעשה לכל מלאכה ולענין לקבל טומאה מן הנבלה או מן השרץ:"],[10,"כפרים","שעמם מועטין וחלב לאו בר אכילה הוא אפילו לעובד כוכבים אלא ע\"י דחק:"],[10,"צריך מחשבה","והוי אוכל וכיון דחלב יורד לתורת אוכל אומר אני טומאתו אגב כוליא מה שהוא מטמא אדם משום מגע נבלה שהוא שומר הכוליא כשהכוליא טמונה בו כדאמר לעיל (חולין דף קכו:) כמה חוטין נמשכים הימנה לאו דאורייתא דאי דאורייתא מצינו דבר שיורד לתורת אוכל כגון חלב שחישב עליו ועדיין הכוליא טמונה בו:"],[10,"מטמא טומאה חמורה","ואנן תנן כל שסופו לטמא טומאה חמורה אין צריך הכשר וזה לענין טומאת אוכלין אוכל הוא וקתני צריך הכשר:"],[11,"מעשה עץ שימש","לאו בתורת אוכל הוא מטמא אלא בתורת שומר לאוכל כעצם וכקרנים וכטלפים:"],[12,"הרי אמרו בית שסככו בזרעים","כלומר הרי הזכירו בית המסוכך בזרעים דהוי בית. ולא ידענא היכן אמרו:"],[12,"המסכך בזרעים","כגון שסיכך ביתו בשבלים ובהם הזרעים וכיון שעשה מהם סכך בטל הזרעים ונעשה אהל חשוב ואם פרחה צרעת באותו בית הרי כל הבית טמא כתליו ואהל שלו לטמא אדם וכלים:"],[12,"טומאתו לאו דאורייתא","אותה טומאה שהבית חשוב אהל לטמא אדם לאו דאורייתא היא. ואית דגרסי בית שסיככו בזרעים טהרו כלומר טהרו מטומאת אוכלים ונעשו עץ דבטלו אצל הסיכוך טומאתו לאו דאורייתא כדפרישית:"],[14,"אי אין מיתה עושה ניפול","והרי נתנבל עמה לטמא משום נבלה:"],[16,"מ\"ט דרבי שמעון","דמטהר המעורה בבעלי חיים:"]],[[0,"וטומאת בית הסתרים לא מטמא","פירושה בפרק בהמה המקשה (לעיל חולין עב: ד\"ה בשעת):"],[2,"ולא שני ליה לר' מאיר בין טומאה דבעי הכשר כו'","הלשון אין מיושב דלא ה\"ל למימר טפי אלא הכא לא הוכשר:"],[4,"למה לי הכשר והא מטמא טומאה חמורה אגב אביו","תימה אמאי לא פריך למה ליה לאוקומיה כר\"מ הא מטמא טומאה חמורה אגב אביו ואין צריך לא הכשר מים ולא הכשר שרץ כדאמר פרק בא סימן (נדה דף נ:):"],[5,"כששימש מעשה עץ שימש","פירוש מאותו שם שהיה מטמא טומאה חמורה דהיינו משום אבר מן החי עתה אין אבר מן החי שאין בו אלא בשר ואין קרוי אבר ול\"ד לנבלת עוף טהור ופרים הנשרפים שכשטימא טומאה חמורה היה משום שורף פרים והשתא נמי הם פרים וה\"פ כששימש מעשה עץ שימש לא מתורת אוכל כמו שהוא עתה אלא מתורת עץ בעלמא וא\"ת אע\"ג דמעשה עץ שימש ליטמא דנגמר מזרעים שאין סופן לטמא טומאה חמורה בשום ענין וי\"ל דזרעים נמי סופן לטמא טומאה חמורה ע\"י שמוש עץ כדאמר בסמוך כופת שאור שיחדה לישב עליה בטלה ומטמאה טומאת מדרס:"],[8,"טומאתה לאו דאורייתא","תימה דאי לאו מדאורייתא בטלה אמאי מותר להניחה בביתו:"],[12,"בית שסככו בזרעים טהרו","מכאן קשה על פירוש רבינו שמואל בפ\"ק דסוכה (דף יג:) דאמר ירקות שאדם יוצא בהן ידי חובתו בפסח אין חוצצין בפני הטומאה אבל מביאין הטומאה ופוסלין הסוכה משום אויר פירוש ולא משום סכך פסול דסכך פסול בארבעה ואויר בשלשה ואמר התם מאי טעמא כיון דכי יבשי נפלי כמאן דמפרשי דמו ופירש רבינו שמואל דהא דקאמר מאי טעמא לאו אאין חוצצין בפני הטומאה קאי משום דהוי אוכל ומקבל טומאה ואין חוצץ בפני הטומאה אלא אפוסלים את הסוכה קאי וקשה לפירושו דהכא משמע דבטלי לגבי בית ולא מקבלי טומאה ומיהו יש לומר לפירושו דמילי מילי קתני ואין חוצצין לאו כשסכך בהם קאמר אבל מכל מקום לא היה צריך לפרש כן דאיכא לפרושי כשסיכך בהן ולא מקבלי טומאה והאי דאין חוצצין כדמפרש התם משום דכי יבשי נפלי וכן פירש בקונטרס שם:"]]],[["לאחרים אין קרוי אוכל","אמר ליה רבי זירא לרבי אסי דילמא טעמא דרבי שמעון התם הואיל ומעורה מעורה","דתניא יחור של תאנה שנפשח ומעורה בקליפה ר' יהודה מטהר וחכמים אומרים אם יכול לחיות טהור ואם לאו טמא ואמרינן לך מאי טעמא דרבי יהודה ואמרת לן הואיל ומעורה מעורה","אמר ליה אמצעיתא נשחטה הבהמה הוכשרה בדמיה דברי ר' מאיר ר' שמעון אומר לא הוכשרו","(אמר ר' אסי) אמר רבי יוחנן מאי טעמא דרבי שמעון אמר קרא (ויקרא יא, לד) מכל האוכל אשר יאכל אוכל שאתה יכול להאכילו לאחרים קרוי אוכל אוכל שאין אתה יכול להאכילו לאחרים אין קרוי אוכל","ודילמא טעמא דר' שמעון בההיא","אי כדרבא אי כדרבי יוחנן","אלא לעולם אסיפא ולאו אאבר אלא אבשר מתה הבהמה הבשר צריך הכשר ור' שמעון מטהר","אמר ר' יוחנן מ\"ט דרבי שמעון אמר קרא מכל האוכל אשר יאכל אוכל שאתה יכול להאכילו לאחרים קרוי אוכל אוכל שאי אתה יכול להאכילו לאחרים אין קרוי אוכל:","\u0001מתני׳\u0002 האבר והבשר המדולדלין באדם טהורים מת האדם הבשר טהור האבר מטמא משום אבר מן החי ואינו מטמא משום אבר מן המת דברי ר' מאיר ורבי שמעון מטהר:","\u0001גמ׳\u0002 ורבי שמעון מה נפשך אי מיתה עושה ניפול ליטמא משום אבר מן החי ואי אין מיתה עושה ניפול ליטמא משום אבר מן המת","ר' שמעון בעלמא קאי דקאמר תנא קמא האבר מטמא משום אבר מן החי ואין מטמא משום אבר מן המת אלמא אבר המת בעלמא מטמא ואמר ליה ר\"ש אבר המת בעלמא לא מטמא","דתניא אמר ר' אליעזר שמעתי שאבר מן החי מטמא אמר לו ר' יהושע מן החי ולא מן המת וקל וחומר ומה חי שהוא טהור אבר הפורש ממנו טמא מת שהוא טמא לא כל שכן","כתוב במגילת תענית פסחא זעירא דלא למספד הא רבה למספד אלא כל דכן הכא נמי כל דכן אמר ליה כך שמעתי","ומאי איכא בין אבר מן החי לאבר מן המת כזית בשר ועצם כשעורה הפורש מאבר מן החי איכא בינייהו","דתנן כזית בשר הפורש מאבר מן החי ר' אליעזר מטמא ור' נחוניא בן הקנה ור' יהושע מטהרין עצם כשעורה הפורש מאבר מן החי ר' נחוניא מטמא רבי אליעזר ור' יהושע מטהרין","השתא דאתית להכי בין תנא קמא לרבי שמעון נמי כזית בשר ועצם כשעורה איכא בינייהו:","\u0001הדרן עלך העור והרוטב\u0002"],[[0,"לאחרים","לעובד כוכבים:"],[0,"קרוי אוכל","לענין טומאת אוכלין ואבר מן החי אין אתה יכול להאכילו לאחרים בהיתר:"],[1,"ודילמא טעמא דר' שמעון","ולמה לי קרא להכי:"],[1,"הואיל ומעורה","בבעלי חיים שאין טומאה נוהגת בהם כדאמרינן לגבי יחור דהואיל והתאנה מעורה ביחור חיבור הוא אע\"פ שהיחור נפשח מן האילן שהקליפה מועלת בו לעשות חבור הכא נמי הואיל והאבר מעורה בבהמה כל דהו טהור הוא:"],[3,"נשחטה הבהמה","אין המדולדל ניתר לא לישראל ולא לבני נח:"],[3,"לא הוכשרו","וקמפרש רבי יוחנן משום דלאו בני קבולי טומאה נינהו דלא משויא להו שחיטה אוכלא הואיל שאינו קרוי אוכל:"],[5,"ודלמא","לעולם בני קבולי טומאה נינהו וטעמא דר\"ש אי כדרבא דמפרש לעיל (חולין דף קכז:) טעמא דר\"ש משום דאין בהמה נעשית יד להכשיר האבר אי כדרבי יוחנן דאמר נמי לעיל אין יד להכשר וכשאוחז בקטן ואין גדול עולה עמו פליגי ומשום הכשר:"],[7,"אלא לעולם","אי איתמר דר' אסי אסיפא דמתניתין איתמר אמתה הבהמה ור' שמעון מטהר אפילו הוכשר הבשר אין מקבל טומאה וכ\"ש דפליג ארישא כשהן מחוברין ומיהו קרא לא איצטריך ליה אלא משום סיפא דאי משום רישא הא אית ליה טעם אחר כדאמרינן:"],[9,"מתני' המדולדלין באדם טהורים","דכי ימות כתיב:"],[9,"מת האדם הבשר","המדולדל טהור דמיתה עושה ניפול ובשר הפורש מן החי טהור וכרבי יהושע ור' נחוניא בן הקנה מיתוקמא דמטהרים לקמן בשר הפורש מאדם חי:"],[9,"האבר מטמא משום אבר מן החי כו'","בגמרא מפרש מאי איכא בין אבר מן החי לאבר מן המת אבר מאדם חי מטמא במגע ובמשא ובאהל אבל כזית בשר ועצם כשעורה הפורש מאבר מן החי אינו מטמא ומאבר מן המת מטמא:"],[11,"גמ' בעלמא קאי","ואפילו אאבר מן המת דעלמא פליגי דלא מטמא אלא אם כן יש בו כזית בשר דמטמא משום בשר:"],[12,"א\"ל ר' יהושע","וכי מפני ששמעת מן החי סבור אתה לומר מן החי דוקא ולא מת בתמיה והלא כתיב במגילת תענית פסחא זעירא כו' פסח שני שבאייר:"],[13,"הא רבה","פסח ניסן:"],[13,"למספד","בתמיה:"],[13,"ה\"נ כל דכן","שמעת:"],[13,"א\"ל כך שמעתי","שאבר מן החי מטמא ולא אבר מן המת:"],[14,"ה\"ג ומאי איכא בין אבר מן החי לאבר מן המת","ואמתניתין קאי:"],[14,"כזית בשר ועצם כשעורה הפורש מאבר מן החי איכא בינייהו","תנא דמתניתין סבירא ליה כר' יהושע דמטהר לקמן בין בבשר הפורש בין בעצם הפורש מן החי דהא מתניתין ר' יהושע היא דמטמא באבר מן המת הילכך בבשר מן החי ובעצם מן החי שאינו אבר נמי כרבי יהושע סבירא ליה. טעמא דרבי אליעזר ור' יהושע ור' נחוניא מפרש בעדיות (פ\"ו מ\"ג) מה ראה כל אחד לטמא בזה ולטהר בזה ומה ראה ר' יהושע לטהר בשניהם דתנן התם אמרו לו לר' אליעזר השוה מדותיך או תטמא בשניהם או תטהר בשניהם אמר להם מרבה אני טומאת בשר מטומאת עצמות שהבשר נוהג בנבלות ובשרצים מה שאין כן בעצמות אמרו לו לר' נחוניא השוה מדותיך אמר להם מרבה אני טומאת עצמות מטומאת בשר שהבשר הפורש מן החי טהור ואבר הפורש ממנו והוא כברייתו טמא אמרו לו לר' יהושע מה ראית לטהר בשניהם והא שניהם במת טמאין אמר להם לא אם אמרתם במת שהרי יש בו רובע ורוב ורקב דרובע הקב עצמות מת טמאים באהל ורוב בניינו או רוב מניינו מטמא ומלא תרווד רקב מטמא באהל תאמרו בחי שאין בו רובע ורוב ורקב כו':"],[16,"השתא דאתית להכי","דאדכרתן עצם כשעורה ובשר הפורש מהשתא אימא לך דר\"ש לאו אאבר מן המת פליג אלא בין תנא קמא לר\"ש דמתניתין נמי כזית בשר ועצם כשעורה איכא בינייהו בהא פליגי אם אבר מן החי חלוק מאבר מן המת בשתיהן או באחת מהן דלתנא קמא אינו חלוק אלא באחת מהן דת\"ק סבר אי כרבי אליעזר דמטמא בבשר הפורש מאבר מן החי ובעצם כשעורה הפורש ממנו מטהר אי כר' נחוניא דאמר איפכא והכי קאמר האבר טמא משום אבר מן החי ובשר הפורש ממנו טמא והעצם טהור כר' אליעזר או העצם טמא והבשר טהור כרבי נחוניא ולא משום אבר מן המת דשניהם טמאין בו ור' שמעון מטהר בין בעצם בין בבשר הפורש ממנו דסבר כר' יהושע דמטהר בשניהם אבל אבר עצמו ה\"נ דמטמא לר\"ש:"]],[[15,"כזית בשר הפורש מאבר מן החי ר' אליעזר מטמא","לכאורה נראה דאבר האדם מן החי מבנין אב דשרצים ובהמה אתי אבל במשנה לא משמע כן מדאמרו ליה לר' אליעזר השוה מדותיך וקא יהיב טעמא אמאי מרבה בשר וממעט עצם וצריך לומר מקרא אחד דרשינן מר מוקי ליה בבשר ומר מוקי ליה בעצם כדיהיב טעמא ומר דריש לדרשא אחרינא אבל אי מבניינא דשרצים ודבהמה אתי אמאי אמרו ליה לר' אליעזר מאי טעמא מרבה בשר וממעט עצם:"],[16,"בין תנא קמא לר' שמעון נמי כזית בשר ועצם כשעורה איכא בינייהו","פירוש או עצם כשעורה דהא תרוייהו ליכא למימר לת\"ק טמא דאם כן מאי איכא בין אבר מן המת לאבר מן החי:"]]],[["מתני׳ \u0001הזרוע\u0002 והלחיים והקבה נוהגין בארץ ובחוצה לארץ בפני הבית ושלא בפני הבית בחולין אבל לא במוקדשין","שהיה בדין ומה אם החולין שאינן חייבים בחזה ושוק חייבים במתנות קדשים שחייבים בחזה ושוק אינו דין שחייבים במתנות","ת\"ל (ויקרא ז, לד) ואתן אותם לאהרן הכהן ולבניו לחק עולם אין לו אלא מה שאמור בענין","כל הקדשים שקדם מום קבוע להקדשן ונפדו חייבין בבכורה ובמתנות ויוצאין לחולין להגזז ולהעבד וולדן וחלבן מותר לאחר פדיונן","והשוחטן בחוץ פטור ואין עושין תמורה ואם מתו יפדו חוץ מן הבכור ומן המעשר","כל שקדם הקדשן את מומן או מום עובר קודם להקדשן ולאחר מכאן נולד להם מום קבוע ונפדו פטורין מן הבכורה ומן המתנות ואינן יוצאין לחולין להגזז ולהעבד","וולדן וחלבן אסור לאחר פדיונן והשוחטן בחוץ חייב ועושין תמורה ואם מתו יקברו:","\u0001גמ׳\u0002 טעמא דכתב רחמנא אותם הא לאו הכי הוה אמינא קדשים חייבין במתנות","איכא למיפרך מה לחולין שכן חייבין בבכורה","תיתי מזכרים מה לזכרים שכן חייבין בראשית הגז","מתיישים מה לתיישים שכן נכנסין לדיר להתעשר","מזקנים מה לזקנים שכן נכנסו לדיר להתעשר","מלקוח ויתום מה ללקוח ויתום שכן נכנסין במינן לדיר להתעשר","במינן קאמרת קדשים נמי במינן נכנסין לדיר להתעשר","ויהיו חולין חייבין בחזה ושוק מקל וחומר ומה קדשים שאין חייבים במתנות חייבין בחזה ושוק חולין שחייבין במתנות אינו דין שחייבין בחזה ושוק","אמר קרא (דברים יח, ג) וזה יהיה משפט הכהנים זה אין מידי אחרינא לא","אלא טעמא דכתב רחמנא זה הא לאו הכי הוה אמינא חולין חייבין בחזה ושוק והא בעי תנופה היכא לינופינהו אי אבראי (ויקרא ז, ל) לפני ה' כתיב"],[[0,"","מתני' הזרוע והלחיים:"],[0,"בארץ ובחוצה לארץ","משום דבעי למימר בחולין אבל לא במוקדשין נקט להו:"],[0,"בפני הבית","בעודו קיים:"],[1,"","חולין אינן חייבין בחזה ושוק אלא קדשים לחודייהו:"],[2,"ואתן אותם","בחזה ושוק כתיב. אותם מיעוטא הוא חזה ושוק אין ולא דבר אחר:"],[3,"כל הקדשים שקדם מום קבוע להקדשן","הרי הן כמקדיש עצים ואבנים לדמיהם ואין בהן קדושת הגוף ואם נפדו הרי הן כחולין גמורים וחייבים בבכורה אם ילדו בכור הרי הוא קדוש וכל זמן שלא נפדו לא כדאמר בבכורות פ\"ב (דף יד.) קסבר האי תנא קדושת דמים מדחה מן הבכורה דאין קדושה חלה על קדושה:"],[3,"וולדן וחלבן מותר לאחר פדיונם","מה שאין כן במקדיש תמימים ונסתאבו ופדאן דאמרי' בבכורות (דף טו.) רק בכל אות נפשך תזבח ואכלת בשר בפסולי המוקדשין לאחר פדיונן הכתוב מדבר מדאיצטריך קרא למימר בהו הטמא והטהור יאכלנו וכתיב תזבח ואכלת בשר תזבח ולא גיזה ואכלת ולא לכלביך בשר ולא חלב וולדן דתמימים שנסתאבו ונפדו תנן במתניתין דאסור ובבכורות (דף יד.) מוקמינן כגון דאיעבר לפני פדיונן ואתיליד לאחר פדיונן בין רישא דקתני מותר בין סיפא דקתני אסור:"],[3,"ויוצאין לחולין","ע\"י פדיונן להיות כחולין גמורים אפילו ליגזז וליעבד מה שאין כן בקדם הקדשן את מומן כדלקמן במתניתין:"],[4,"והשוחטן בחוץ פטור","ואילו בקדם הקדשן את מומן תנן מתניתין לקמן דחייב אם שחט בחוץ קודם פדיונן ואע\"ג דאינן ראוים לפתח אהל מועד דהא בעלי מומין נינהו ותנן (זבחים דף קיב.) הראוי לפתח אהל מועד חייבין עליו בחוץ ושאינו ראוי בפנים אין חייבין עליו בחוץ הא מוקמינן לה בבכורות (דף טז.) בדוקין שבעין ואליבא דר\"ע דאמר אם עלו לא ירדו הילכך הואיל ובפנים לא ירדו חייבין עליהן בחוץ. וכולה הך מתני' מיתניא בבכורות בפרק שני (דף יד.) והתם תני לה משום בכורות והכא תני לה משום מתנות:"],[4,"ואין עושין תמורה","אפילו קודם פדיונן. ובבכורות מפרש טעמא טוב מעיקרו עושה תמורה ואפילו נעשה רע אחר שהקדישו אבל רע מעיקרו אינו עושה תמורה:"],[4,"ואם מתו יפדו","ואע\"פ שאינם ראוים אלא לכלבים ואין פודין את הקדשים להאכילן לכלבים כדפרישית לעיל ואכלת ולא לכלביך ה\"מ בקדשים שקדם הקדשן את מומן אבל הני כדיקלא בעלמא נינהו ולא נחת להו קדושת הגוף ועוד אשמועינן דלא בעינן העמדה והערכה וקסבר קדשי בדק הבית לא היו בכלל העמדה והערכה דכתיב בפדיון קדשים שנסתאבו לאחר כך והעמיד את הבהמה (ויקרא כז) וכיון דמתה אי אפשר להעמידה:"],[4,"חוץ מן הבכור והמעשר","דאע\"ג שקדם מומן להקדשן חלה עליהם קדושה גמורה לכל דבריהם אלא שאין כשרים ליקרב דבכור ברחם תלה רחמנא לא שנא תם ולא שנא בעל מום קדיש תם קרב ובעל מום נאכל לכהן כדילפינן בבכורות (דף כח.) ובשרם יהיה לך בשרם תרי משמע לימד על בכור בעל מום שמתנה לכהן ומעשר בהמה נמי כתיב ביה (ויקרא כז) העשירי יהיה קדש לא יבקר בין טוב לרע טוב היינו תם רע היינו בעל מום:"],[5,"או מום עובר קודם להקדשן","דמום עובר כמאן דליתיה דמי:"],[5,"פטורין מן הבכורה","ואע\"פ שנפדו ויצאו לחולין להיתר אכילה פטורין מן הבכורה אם ילדו דכתיב בהו (דברים יב) כצבי וכאיל וצבי ואיל פטורים מן הבכורה דהא בקר וצאן כתיב:"],[5,"ומן המתנות","זרוע ולחיים וקיבה דאין נוהגין בצבי ואיל דכתיב (שם יח) אם שה:"],[5,"ואין יוצאין לחולין","בפדיון:"],[5,"ליגזז וליעבד","כדפרישית לעיל תזבח ואכלת אין בהן אלא היתר זביחה ואכילה בלבד אבל גיזה ועבודה לא:"],[6,"וולדן וחלבן אסור","בבכורות (דף יד.) מוקי לה דאיעבר לפני פדיונן ואתיליד לאחר פדיונן דאי איעבר ואתיליד לאחר פדיונן ולד צבי ואיל הוא ואם נולד לפני פדיונן מאי איריא הני אפילו קדם מומם להקדשן נמי ולדן לפני פדיונן אסור:"],[6,"והשוחטן בחוץ חייב","כדפרישית לעיל בדוקין שבעין וקודם פדיונן:"],[6,"ועושין תמורה","קודם פדיונן דכתיב (ויקרא כז) טוב ברע או רע בטוב:"],[6,"מתו","מעצמן:"],[6,"יקברו","או משום דבעינן העמדה והערכה או משום דאין פודין את הקדשים להאכילם לכלבים:"],[7,"גמ' הוה אמינא קדשים חייבין במתנות","מקל וחומר מחולין כדאמרן במתניתין והיכי מצינן למימר הכי הא איכא למפרך בהאי ק\"ו מה לחולין כו' וקרא למה לי:"],[8,"","בכור אינו נוהג במוקדשים דבקרך וצאנך כתיב (דברים טו) ולא הקדש ועוד תקדיש כתיב (שם) ולא שכבר קדוש:"],[9,"תיתי מזכרים","כלומר אי לאו אותם דקרא הוה אמינא תיתי בק\"ו מזכרים דחולין דליכא למיפרך בהו שכן חייבין בבכורה שאין יולדין:"],[9,"","ראשית הגז אינו נוהג במוקדשים דהא לאו בני גיזה נינהו דכתיב (שם יח) גז צאנך ולא הקדש:"],[9,"","ראשית הגז כל השנה כשהוא גוזז צאנו נותן לכהן דבר מועט כדמפרש לקמן (חולין דף קלה.) שיעורא וקרי ליה ראשית כי היכי דקרי תרומה (שם) ראשית דגנך:"],[10,"","תיישים זכרים אין בהם לא בכורה ולא ראשית הגז ואי לאו אותם מחייבינן מתנות בקדשים מק\"ו מתיישים חולין:"],[10,"","מעשר בהמה אינו במוקדשין דכתיב יהיה קדש ולא שכבר קדוש בפ\"ב דבכורות (דף נג:) הילכך לא אתי בק\"ו דאיכא למיפרך תאמר במוקדשין שאין נכנסין לדיר להתעשר:"],[11,"מזקנים","אי לאו אותם הוה מייתינן ליה מק\"ו מתיישים זקנים דחולין שכבר נתעשרו ואין צריכין עוד להכנס לדיר:"],[11,"מה לזקנים","תיישים זקנים דחולין בדין הוא שהן חייבין במתנות:"],[11,"שכן נכנסו כבר לדיר להתעשר","תאמר בקדשים שלא נכנסו כבר לדיר להתעשר. ומהדר אי לאו אותם הוה מייתינן להו בק\"ו מלקוח ויתום. הלקוח פטור ממעשר בהמה אם לקח עשרה טלאים מן השוק פטור מלעשר דבקרך וצאנך אמר רחמנא והיתום שמתה אמו בשעת לידה כגון זה פירש למיתה וזה פירש לחיים כדאמר בהשוחט (לעיל חולין דף לח:) פטור ממעשר בהמה דאינו ראוי לקדש דכתיב תחת אמו פרט ליתום וילפינן מעשר בהמה מיניה בפ\"ב דבכורות (דף נז.) ר' ישמעאל בנו של ר' יוחנן בן ברוקא אומר נאמר כאן תחת אמו ונאמר להלן תחת השבט מה כאן פרט לכל השמות הללו כלאים ונדמה ויוצא דופן ויתום דכולהו מימעטי מהאי קרא דשור או כשב אף להלן לענין מעשר פרט לכל השמות הללו אע\"ג דבעל מום נכנס לדיר להתעשר אלו אין נכנסים:"],[13,"ה\"ג במינן קאמרת קדשים נמי במינן","כגון חולין נכנסין לדיר הילכך אי לאו אותם אתי בק\"ו:"],[14,"מה קדשים שאין חייבים במתנות","דהא ממעטינן להו מאותם דכתיב גבי חזה ושוק אותם ולא מתנות:"],[15,"אמר קרא","במתנות חולין זה יהיה דבר זה נוהג בחולין ואין חזה ושוק נוהגין בהן:"],[16,"","בחזה ושוק כתיבא תנופה לפני ה':"],[16,"אי אבראי","חוץ לעזרה:"]],[[0,"","מתני' הזרוע והלחיים:"],[2,"תלמוד לומר ואתן אותם","ואי לאו קל וחומר לא הוה צריך קרא אע\"ג דסתמא כתיב בין בחולין בין במוקדשים דה\"א דבר הלמד מענינו במה הכתוב מדבר בחולין דכתיב לעיל מהאי קרא דגנך תירושך ויצהרך וגו' גז צאנך וראשית הגז אינו נוהג במוקדשין כדאמר לקמן פרק ראשית הגז (חולין דף קלה.):"],[12,"תיתי מלקוח ויתום","הוה מצי למימר נמי תיתי מכלאים וטרפה ועוד טובא דתנן בפרק מעשר בהמה (בכורות דף נז.) שאין נכנסין לדיר להתעשר:"],[15,"זה אין מידי אחרינא לא","תימה דקאי במתנות וממעט חזה ושוק אדרבה ה\"ל למעוטי מיניה מוקדשין ממתנות ויש לומר דכבר אמעיטו מאותם וכה\"ג פירש' בפ\"ק (לעיל חולין דף כד.) גבי וזאת אשר ללוים:"]]],[["אי אגואי קא מעייל חולין לעזרה הלכך לא אפשר","אלא זה למה לי לכדרב חסדא דאמר רב חסדא המזיק מתנות כהונה או שאכלן פטור מלשלם","גופא אמר רב חסדא המזיק מתנות כהונה או שאכלן פטור מלשלם מאי טעמא איבעית אימא דכתיב זה ואיבעית אימא משום דהו\"ל ממון שאין לו תובעים","מיתיבי (דברים יח, ג) וזה יהיה משפט הכהנים מלמד שהמתנות דין למאי הלכתא לאו להוציאן בדיינין לא לחולקן בדיינין","וכדרב שמואל בר נחמני דאמר רב שמואל בר נחמני אמר רבי יונתן מנין שאין נותנין מתנה לכהן ע\"ה שנאמר (דברי הימים ב לא, ד) ויאמר לעם ליושבי ירושלים לתת מנת לכהנים וללוים למען יחזקו בתורת ה' כל המחזיק בתורת ה' יש לו מנת ושאינו מחזיק בתורת ה' אין לו מנת","ת\"ש ר' יהודה בן בתירא אומר משפט מלמד שהמתנות דין יכול אפי' חזה ושוק דין ת\"ל זה","למאי אילימא לחולקו בדיינין אטו חזה ושוק לאו בדיינין מיחלקו אלא לאו להוציא בדיינין","הכא במאי עסקינן דאתו לידיה אי דאתו לידיה מאי למימרא דאתו לידיה בטבלייהו וקסבר האי תנא מתנות שלא הורמו כמי שהורמו דמיין","תא שמע בעל הבית שהיה עובר ממקום למקום וצריך ליטול לקט שכחה ופאה ומעשר עני נוטל ולכשיחזור ישלם דברי רבי אליעזר","אמר רב חסדא מדת חסידות שנו כאן אמר רבא תנא תני ישלם ואת אמרת מדת חסידות שנו כאן ועוד מדרבי אליעזר ליקום וליתוב","אלא מסיפא וחכמים אומרים עני היה באותה שעה טעמא דעני הא עשיר משלם","אמאי ליהוי כמזיק מתנות כהונה או שאכלן אמר רב חסדא מדת חסידות שנו כאן","תא שמע מנין לבעל הבית שאכל פירותיו טבלין וכן לוי שאכל מעשרותיו טבלים מנין שפטור מן התשלומין ת\"ל (ויקרא כב, טו) ולא יחללו את קדשי בני ישראל אשר ירימו אין לך בהן אלא משעת הרמה ואילך","הא משעת הרמה ואילך מיהא משלם אמאי ליהוי כמזיק מתנות כהונה או שאכלן הכא נמי"],[[0,"קא מעייל חולין לעזרה","מידי דלא איתעביד ביה צורך גבוה:"],[1,"המזיק מתנות כהונה","קודם שנתנן לכהן השליכם לאור או לים:"],[2,"דכתיב בהו זה","דמשמע בעודן קיימות חייב ליתנן אבל אינן קיימות לא חייב הכתוב בהן תשלומין:"],[2,"שאין לו תובעים","אין לו בעלים שיוכלו לתובעו בדין שהוא יכול לומר לו לכהן אחר אני נותנן ולא לך:"],[3,"משפט מלמד שהמתנות דין","דיינין נזקקין להן להוציאן בדיינין. אלמא כהן ראשון התובען מוציאן מידו וקשיא לרב חסדא דאמר דמתנות כהונה ממון שאין לו תובעין הוא:"],[3,"לחולקן בדיינין","דיינין אומרים לו לישראל לזה תן המתנות שהוא חבר ואל תתן לזה שהוא עם הארץ:"],[4,"ויאמר לעם","ביהושפט כתיב בדברי הימים. סיפיה דקרא למען יחזקו בתורת ה':"],[4,"מנת","חלק כהונה:"],[6,"אטו חזה ושוק מי לא בדיינין מיחלקו","כלום היה יכול לתתם לכהן עם הארץ והא מנת נינהו:"],[6,"אלא לאו להוציאו בדיינין","אלמא דממון שיש לו תובעין הוא משום הכי ממעט חזה ושוק דכיון דלכפרה ולרצוי בא לא שכיח דמעכב:"],[7,"הכא במאי עסקינן דאתו לידיה","דכהן ואחר כך גזלם זה ממנו דהוה ליה ממון שיש לו תובעין שכבר זכה זה בהן ודמי כמאן דגזל מיניה גלימיה:"],[7,"ופריך אי דאתו לידיה","דכהן מאי למימרא פשיטא דיכול להוציאו בדיינין. וקמהדר דאתו לידיה בטיבלייהו הבהמה שלימה היתה מונחת אצלו וזכה במתנות מן ההפקר:"],[7,"כמי שהורמו דמיין","וזכה בהן. במתנות ששוים לכל הכהנים מהני זכייה אם קדם אבל חזה ושוק אינו אלא לאותו בית אב ולא מהני:"],[8,"בעל הבית","עשיר שהיה עובר ממקום למקום:"],[8,"וצריך ליטול כו'","ונצרך למזונות נוטל לקט כשאר עניים הואיל שעכשיו עני הוא:"],[8,"וכשיחזור ישלם","אלמא כל מידי דחייביה רחמנא למיתב לעניים הבא ראשון יכול לתובעו והוא הדין למתנות כהונה:"],[9,"מדת חסידות שנו כאן","אם חסיד הוא ישלם:"],[9,"תנא תני ישלם","דמשמע על כרחו ואת אמרת כו':"],[9,"ועוד","מי סברת מדרבי אליעזר קמותיב דמצינן למימר דרב חסדא משני עלה מדת חסידות שנו כאן אלא מדרבנן מותיב ועלה משני רב חסדא מדת חסידות (שנו כו': כאן - הא) דקתני עני היה באותה שעה דמשמע דתידוק מינה דעשיר בעי שלומי לאו בדיינין קאמר אלא אם חסיד הוא צריך לשלם לצאת ידי שמים:"],[12,"וכן לוי שאכל מעשרותיו טבלים","שלא הפריש תרומת מעשר:"],[12,"את קדשי בני ישראל אשר ירימו לה' אין לך בהן אלא משעת הרמה","הכי גרסינן ליה בתוספתא:"]],[[0,"אי אגואי הא קא מעייל חולין בעזרה","משום דכל חולין מדאורייתא אסור להביא בעזרה וכן אמר בהמוכר את הספינה (ב\"ב דף פא:) גבי בכורים ולא מסתבר דהתם אגוזלות דמייתי בהדייהו קפיד דאפשר דמתני עלייהו ומביאם נדבה וכן בפ' התודה (מנחות דף פ:) גבי תודה שנתערבה בתמורות קאמר ולייתי לחם כו' הא קא מכניס חולין לעזרה ומדקאמר שאין לה תקנה ש\"מ הוי מדאורייתא ותימה דבפ' כל התדיר (זבחים דף צ:) אמרינן ובכולן הכהנים רשאים לשנות באכילתן ולאוכלן צלויין שלוקין ומבושלים ולתת לתוכן תבלין של חולין ואמר בהקומץ רבה (מנחות דף כא:) יאכלוה שיאכלו עמה חולין ותרומה כדי שתהא נאכלת על השובע ונראה דדוקא חזה ושוק וכן בכורים דדרך קדושה מייתי להו דעביד בהו תנופה וכן לחם לצורך תודה שהוא הכשר קרבן יש קפידא טפי בהבאתה בעזרה שלא לצורך:"],[2,"ואב\"א משום דהוי ליה ממון שאין לו תובעין","ולהאי לישנא אייתר וזה יהיה לכדאמר לקמן בסמוך שמתנות דין ואין חזה ושוק דין וללישנא קמא איכא למימר דתרתי שמע מינה ודריש בסמוך מדכתביה אצל משפט דמשמע זה משפט וזה אין משפט ואיכא בין הני תרי לישני דלהאי לישנא דאין לו תובעין נהי דאין יכול לתובעו בדיינין בדיני שמים מיהא מיחייב וללישנא קמא דדריש ליה מוזה אפילו בדיני שמים נמי לא מיחייב:"],[4,"מנין שאין נותנין מתנות לכהן ע\"ה כו'","היינו דווקא כשיש כהן חבר אבל אי ליכא כהן חבר אלא ע\"ה יתנו לו ואל ימתין עד שיזדמן לו חבר כדתנן במסכת חלה (פ\"ד מ\"ט) אלו נותנין לכל מי שירצה החרמים והבכורות ופדיון הבן ופטר חמור והזרוע והלחיים והקבה וראשית הגז כו' ואין לפרש לכל כהן בין לאנשי משמר בין לשאר כהנים דהא בירושלמי בפרק שתי נשים קאמר דיש מהן ניתנין לכל כהן ויש מהן ניתנין לאנשי משמר א\"כ ע\"כ לכל כהן דקאמר היינו בין כהן חבר בין כהן ע\"ה והיינו היכא דליכא חבר או איכא ואין רוצה לקבל כדפרישית בריש כל הבשר (לעיל חולין דף קד:) אבל אין לתרץ דרבי שמואל בר נחמני דהכא כרבי יהודה דגרסינן בירושלמי ר' יהודה אומר אין נותנין אותה אלא לחבר דהתם אבכורים קאי כדאמר התם לעיל מינה רבי אדא אוסר בבכורים:"],[8,"וכשיחזור לביתו ישלם","ללישנא בתרא דקאמר משום דהוי ממון שאין לו תובעין פריך שפיר דישלם משמע שיכול להוציאו בדיינין וללישנא קמא נמי דפטר משום דכתיב זה פרכינן דכיון דבמתנות פטור משום דכתיב זה מסברא אין לנו לחלק בין מתנות ללקט שכחה ופאה ולקמן בפרקין (חולין דף קלד.) פריך מספק לקט דחייב משום עני ורש הצדיקו להא דאמר אין ספק מתנות לכהן:"],[9,"","\u0003אמר רבא \u0004 גרס ולא גרסינן אמר ליה רבא דהוה משמע דלרב חסדא דבר ואם כן מאי קאמר לבסוף מדת חסידות שנו כאן הלא כבר שמע התירוץ ולמה חזר ואמר רב חסדא אלא רבא שמע בבית המדרש הקשיא והתירוץ בשם רב חסדא ארישא והשיב להם דארישא לא שייך לשנויי ולא לאותיב מיניה אלא מסיפא הוקשה לרב חסדא ועל זה תירץ רב חסדא וי\"ס שכתוב בהן ואמר רב חסדא בוי\"ו בסוף מילתיה דרבא וכן משמע דאי לרב חסדא הוה מדבר לא היה אומר ואת אמרת אלא ומר אמר מדת חסידות שנו כאן:"],[9,"תנא תני ישלם ואת אמרת כו'","וא\"ת והאמר בפרק קמא דב\"ק (דף ז.) א\"ל אביי מי כתיב ישולם ישלם כתיב מדעתו ואמר נמי פרק הפועלים (ב\"מ דף צא.) גבי חוסם פי פרה ודש בה לוקה ומשלם ארבעה קבין לפרה כו' ובעי למימר משלם לצאת ידי שמים וללישנא קמא דלעיל דפטור אפילו לצאת ידי שמים פריך שפיר ומיהו לההוא לישנא נמי דאין לו תובעין דחייב לצאת ידי שמים איכא למימר דהיינו דוקא במזיק מתנות כהונה או אכלן שלקחן באיסור אבל הכא שלקחן בהיתר שהיה אז עני אפילו לצאת ידי שמים לא מחייב להכי פריך שפיר ואת אמרת מדת חסידות שנו כאן ולא מחייב אפילו לצאת ידי שמים ומיהו בסמוך קשה דקאמר טעמא דעני הא עשיר חייב ומאי קשיא אימא עני פטור אפילו מלצאת ידי שמים אבל עשיר חייב ומפר\"ת דה\"ק תנא תני ישלם לרבי אליעזר ורבנן פליגי עליה ואת אמרת מדת חסידות כו' דעל מדת חסידות לא הוי פליגי רבנן:"],[12,"אין לך בהן אלא משעת הרמה","ואם תאמר והא קרא לאו לאחר הרמה איירי אלא בעתיד ליתרם דמפקינן מיניה בפרק [אלו] הנשרפים (סנהדרין דף פג.) דטבל במיתה חלול חלול מתרומה דדריש לא יחללו את קדשי בני ישראל את אשר ירימו בעתידים ליתרם הכתוב מדבר ויש לומר דהכא דריש מדסמך ירימו אצל לה' לומר לך שאין לגבוה בהן אלא משעת הרמה אי נמי משום דקאי אקרא דסמיך ליה ואיש כי יאכל קודש דאיירי לאחר הרמה:"]]],[["דאתו לידיה בטבלייהו וקסבר האי תנא מתנות שלא הורמו כמי שהורמו דמיין","תא שמע הרי שאנסו בית המלך גרנו אם בחובו חייב לעשר אם באנפרות פטור מלעשר","שאני התם דקא משתרשי ליה","תא שמע אמר לו מכור לי בני מעיה של פרה והיה בהן מתנות כהונה נותנן לכהן ואינו מנכה לו מן הדמים לקח הימנו במשקל נותנן לכהן ומנכה לו מן הדמים","אמאי ליהוי כמזיק מתנות כהונה או שאכלן שאני התם דאיתנהו בעיניהו","ת\"ש תשעה נכסי כהן תרומה ותרומת מעשר וחלה ראשית הגז ומתנות והדמאי והבכורים והקרן והחומש","למאי לאו להוציאן בדיינין לא לכדתנן למה אמרו נכסי כהן שקונה בהן עבדים וקרקעות ובהמה טמאה ובעל חוב נוטלן בחובו ואשה בכתובתה וספר תורה","ההוא ליואה דהוה חטף מתנתא אתו אמרו ליה לרב אמר להו לא מסתייה דלא שקלינן מיניה אלא מיחטף נמי חטיף","ורב אי איקרו עם משקל נמי לשקול מינייהו אי לא איקרו עם רחמנא פטרינהו","מספקא ליה אי איקרו עם אי לא איקרו עם","יתיב רב פפא וקאמר לה להא שמעתא איתיביה רב אידי בר אבין לרב פפא ארבע מתנות עניים שבכרם הפרט והעוללות והשכחה והפאה ושלש שבתבואה הלקט והשכחה והפאה שנים שבאילן השכחה והפאה","כולן אין בהם טובת הנאה לבעלים ואפילו עני שבישראל מוציאין מידו","מעשר עני המתחלק בתוך ביתו יש בו טובת הנאה לבעלים ואפי' עני שבישראל מוציאין אותו מידו ושאר מתנות כהונה כגון הזרוע והלחיים והקבה אין מוציאין אותן (מידו) לא מכהן לכהן ולא מלוי ללוי","ארבע מתנות שבכרם הפרט והעוללות והשכחה והפאה דכתיב (ויקרא יט, י) וכרמך לא תעולל ופרט כרמך לא תלקט","וכתיב (דברים כד, כא) כי תבצור כרמך לא תעולל אחריך אמר ר' לוי אחריך זו שכחה","פאה גמר אחריך אחריך מזית דכתיב (דברים כד, כ) כי תחבוט זיתך לא תפאר אחריך ותנא דבי ר' ישמעאל שלא תטול תפארתו ממנו","שלשה שבתבואה הלקט"],[[0,"דאתו לידיה","דכהן:"],[0,"בטבלייהו","שהופקד הטבל אצלו:"],[0,"כמי שהורמו דמיין","זכה בהם מן ההפקר שהרי קדם. ל\"א שמסר לו את הטבל לזכות בתרומה שבו:"],[1,"אם בחובו","שהיה חייב לו דבר קצוב ממון:"],[1,"חייב לעשר","ממקום אחר וליתן לכהן שהרי הוא כמוכר:"],[1,"ואם באנפרות","בהפסד ועל חנם פטור מלעשר. קתני מיהת אם בחובו חייב לעשר אלמא יש לו תובעין דאי לאו דינא הוא שישלם לו על כרחו מאי חיוב מצוה איכא הא לא פש גביה מידי:"],[2,"שאני התם דקא משתרשי ליה","התם לאו בהוצאה בדיינין תנן בה אלא חיובא בעלמא כשאר חיובי מעשרות וחיובא ודאי איכא עליה דהא משתרשי ליה כלומר משתכר הוא בה שהרי היה צריך לפרוע מעות:"],[3,"א\"ל","לטבח:"],[3,"מכור לי בני מעיה","בני מעיה של פרה זו:"],[3,"והיו בהן מתנות","הקבה:"],[3,"","נותנן: לוקח זה לכהן:"],[3,"ואין","המוכר מנכה לו ללוקח מן הדמים שהרי היה יודע הלוקח שהמתנות שם וזה לא מכר לו הקבה:"],[3,"לקח הימנו במשקל","הליטרא כך וכך ושקל לו הקבה:"],[3,"נותנן","לו לוקח לכהן שהרי הגזל אצלו וצריך להשיב:"],[3,"והטבח ינכה לו מן הדמים","על כרחו שמכר דבר שאינו שלו:"],[4,"ואמאי","נותנן לכהן ליהוי כמזיק כו':"],[5,"תשעה נכסי כהן","לא ידעתי היכן שנויה ובספרים אינה כתובה בשוה ומוצא אני ט\"ו מתנות כהונה שכולן נכסי כהן לעשות בהן כל צרכיו התרומה ותרומת מעשר ותרומת מעשר של דמאי והחלה והבכורים וראשית הגז ומתנות של חולין ושל קדשים והקרן והחומש של גזל הגר ושדה אחוזה ושדה חרמים ובכור בעל מום ופדיון הבן ופדיון פטר חמור ונראה בעיני שכולן שנוים בה וחשיב תרומה ותרומת מעשר והדמאי וחלה כחדא דכולהו תרומה נינהו ובכור ופדיון הבן ופדיון פטר חמור כחדא וקרן וחומש דגזל הגר חדא וכולהו הנך מתנה לכהן הן ולקמן בפירקין (חולין דף קלג:) חשיב כל כ\"ד מתנות כהונה. הגוזל את הגר ונשבע לו ומת הגר ואח\"כ הודה ונשבע לשקר דאמר רחמנא ואם אין לאיש גואל וגו' וכי יש לך אדם בישראל שאין לו גואלים אלא זהו גר שמת ואין לו יורשין וכתיב האשם המושב לה' לכהן ותניא בפרק הגוזל בב\"ק (דף קי.) האשם זה קרן המושב זה חומש דגבי נשבע לשקר בפקדון או בגזל כתיב ביה חומש בין בגוזל חבירו בפרשת ויקרא בין בגזל הגר בפרשת נשא:"],[6,"למה אמרו","למאי הלכתא:"],[6,"וס\"ת","אע\"פ שאינו לאכילה ולא לדבר שיבא לידי אכילה. ולבי מגמגם למאי תנייה הואיל ותנא דאפי' בהמה טמאה לוקח מהן:"],[7,"חטיף מתנתא","כשהיו התינוקות מוליכין הזרוע והלחיים והקבה לכהן חוטפם מידיהם:"],[7,"לא מסתייה","לא די דכשהוא שוחט את בהמתו אין אנו כופין אותו לתת מתנות לכהן אחר:"],[7,"אלא מיחטף נמי חטיף","בתמיה:"],[8,"ורב","מאי דעתיה דאמר לא מסתייה דלא שקלינן מיניה דמשמע שהיינו יכולין לכופו לכך ונמנעין אנו:"],[9,"אי איקרו עם לשקול מיניה","דהא מאת העם מאת זובחי הזבח כתיב (דברים יח) ואי לא איקרו עם רחמנא פטריה ומאי טיבותא עבדינן גבייהו:"],[9,"מספקא ליה","לרב ומשום ספיקא פטר ליה דהמוציא מחבירו עליו הראיה:"],[10,"להא שמעתא","דרב דמספקא ליה:"],[10,"ד' מתנות עניים","הנוהגות בכרם ואלו הן:"],[10,"הפרט והעוללות","כדכתיב (ויקרא יט) וכרמך לא תעולל ופרט כרמך לא תלקט ובמס' פאה (פ\"ז מ\"ד) מפורש איזו היא עוללות כל שאין לה לא כתף ולא נטף:"],[10,"והשכחה והפאה","כולהו יליף לקמן. פרט ענבים הנושרין בשעת בצירה:"],[10,"לקט","הנושר בשעת קצירה:"],[10,"שתים באילן","לקמן יליף להו:"],[11,"אין בהן טובת הנאה לבעלים","אין בידם לתתן לכל מי שירצו אלא כל הקודם זכה ולקמיה מפרש טעמא:"],[11,"מוציאין את שלו מידו","אם היה לו כרם או תבואה או אילן כופין אותו ליתן. אבל מעשר עני הואיל ומתחלק בתוך הבית לאחר שהכניס תבואתו לבית:"],[12,"יש בהן טובת הנאה לבעלים","שבידו לתתן לאיזה עני שירצה וחבירו אומר לו הילך סלע זה ותן כל מעשרותיך לקרובי עני והיינו טובת הנאה דבר מועט:"],[13,"ד' מתנות","ברישא מפרש לה לכולה ברייתא והדר מותיב תיובתא:"],[14,"אחריך זו שכחה","שאינה אלא מאחריו כדתנן (פאה פ\"ו מ\"ד) שלפניו אינו שכחה שלאחריו שכחה זה הכלל כל שהוא בבל תשוב שכחה שאינו בבל תשוב אינו שכחה. פאה בכרם גמר אחריך אחריך מזית דכתיב ביה לא תפאר אחריך. ותנא דבי רבי ישמעאל שלא תטול תפארתו הימנו כלומר לא תטול כל פארו לשון (איוב לא) ובכל תבואתי תשרש דמשמע עקירה ולשון (דברים כה) ויזנב בך נטל את זנבך. אשפי\"ר בלע\"ז והיינו שלא תטול פאה:"]],[[0,"דאתו לידיה בטבלייהו וקסבר האי תנא מתנות שלא הורמו כמי שהורמו דמיין","ומשעת הרמה ואילך היינו מכי אתו לידיה אפילו בטבלייהו וא\"ת אמאי לא משני דפשטא דברייתא דקתני פטור מן התשלומין היינו דאתו ליד כהן בטבלייהו וקסבר האי תנא מתנות שלא הורמו לאו כמי שהורמו דמיין ומש\"ה פטור דאין לו לכהן אלא משעת הרמה ממש והוה ניחא טפי דהוי לשון הרמה דוקא וי\"ל דאי הוה מוקי לה הכי אז לא היה חדוש הדיוק כלל הא משעת הרמה ואילך משלם דהא פשיטא דמשלם כיון דאתו ליד כהן והורמו אבל השתא עיקר הברייתא משמיענו דמזיק מתנות כהונה או שאכלן פטור ודיוקא קמ\"ל דאע\"ג דאתו לידיה בטבלייהו חייב דכמי שהורמו דמיין:"],[2,"שאני התם דקא משתרשי ליה","דבמקום זה הניח לו המלך שאר ממון ואם תאמר מתנות כהונה כשאכלם משתרשי ליה שבמקום זה לא אכל דבר אחר ואמאי פטור וי\"ל דלא דמי לאנסו בית המלך גרנו דתחתיהן לא לקח משלו אבל באכלו אפשר דלא משתרשי ליה שהיה מתענה:"],[5,"הכי גרסי' בפי' ר\"ח שבעה נכסי כהן","ולא חשיב הכא כל כ\"ד מתנות כהונה דחשיב לקמן בפירקין (חולין דף קלג:) דלא חשיב הכא אלא הנך דאסורים לזרים והם ממון כהן והא דחשיב מתנות אע\"פ שמותרות לזרים משום דטבלי ודמו לתרומה כדאמר לקמן (חולין קלב:) אע\"ג דלית הלכתא הכי היינו דלא הוי כאוכל טבלים אבל מ\"מ איסורא איכא לאכול מבהמה שלא הורמה מתנותיה א\"נ לא חשיב אלא מידי דבר אכילה והא דלא חשיב בכור משום דאכתי לאו בר אכילה הוא שצריך שחיטה:"],[12,"מעשר עני המתחלק בתוך הבית","דוקא נקט המתחלק בתוך הבית דשני דיני מעשר הם אחד מתחלק תוך הבית ואחד מתחלק בתוך הגרנות כדמשמע בפ\"ב דנדרים (דף פד:) ואותו המתחלק תוך הגרנות אין לבעלים בו טובת הנאה אלא באותו המתחלק בתוך הבית ובספרי מפרש להו מקראי כתוב אחד אומר מקצה שלש שנים תוציא את כל מעשר תבואתך והנחת אלמא צריך להניחו בגורן ובאין עניים ונוטלין אותו וכתוב אחד אומר כי תכלה לעשר וגו' ונתת ללוי וגו' אלמא בתוך הבית מחלקו מדכתיב והנחת הא כיצד עד הפסח שהוא זמן גשמים ואם מניחו בחוץ נפסד מחלקו בתוך ביתו וזה מעשר עני המתחלק בתוך הבית מכאן ואילך שהוא ימי הקיץ מניחו בחוץ בגרנות ועניים באים ונוטלין אותו:"],[12,"יש בו טובת הנאה לבעלים","נראה דדבר שיש בו טובת הנאה לבעלים אפילו בא עני ולקחו מוציאין מידו ודבר שאין בו טובת הנאה לבעלים לקחו אין מוציאין מידו ומיהו אם לא לקחו ובא עני ושאלו ממנו אם ירצה לא יתן לו דקרי ליה לעיל ממון שאין לו תובעין ואם היה צריך ליתנו לתובעו א\"כ הוי יש לו תובעין:"],[15,"גמר אחריך אחריך מזית","ואע\"ג דאצטריכו למכתב ולא הוי מופנה גלוי מילתא בעלמא הוא דכמו שיש בזה אחריך פאה ה\"נ יש בזה אחריך פאה ולאו ג\"ש ממש היא אי נמי מדכתיב שכחה בלשון אחריך ש\"מ לג\"ש אתא וצ\"ע למה לא גמרינן בג\"ש דאחריך דלהוי פרט בזית כמו בכרם ונהי דלענין עוללות לא אפשר למילף באילן דלא שייך ביה איזהו עוללות כל שאין לו לא כתף ולא נטף:"]]],[["השכחה והפאה דכתיב (ויקרא כג, כב) ובקוצרכם את קציר ארצכם לא תכלה פאת שדך בקוצרך ולקט קצירך וגו' (דברים כד, יט) כי תקצור קצירך בשדך ושכחת עומר בשדה","שנים שבאילן השכחה והפאה דכתיב (דברים כד, כ) כי תחבוט זיתך לא תפאר אחריך ותנא דבי ר' ישמעאל שלא תטול תפארתו ממנו אחריך זה שכחה","וכולן אין בהן טובת הנאה לבעלים מאי טעמא עזיבה כתיבא בהו","ואפי' עני שבישראל מוציאין אותו מידו דכתיב ולקט קצירך לא תלקט לעני ולגר תעזוב אותם להזהיר עני על שלו","ומעשר עני המתחלק בתוך הבית יש בו טובת הנאה לבעלים מאי טעמא נתינה כתיבא ביה","ואפי' עני שבישראל מוציאין אותו מידו דאמר ר' אילעא גמר לגר לגר מהתם מה להלן מוזהר עני על שלו אף כאן מוזהר עני על שלו","ושאר מתנות כהונה כגון הזרוע והלחיים והקבה אין מוציאין אותן לא מכהן לכהן ולא מלוי ללוי הא מלוי לכהן מוציאין אלמא איקרו עם","כגון הזרוע ולא זרוע ומאי ניהו מעשר ראשון","מעשר ראשון דלוי הוא כרבי אלעזר בן עזריה דתניא תרומה לכהן מעשר ראשון ללוי דברי ר' עקיבא ר' אלעזר בן עזריה אומר אף לכהן","אימר דאמר ר' אלעזר בן עזריה אף לכהן לכהן ולא ללוי מי אמר אין לבתר דקנסינהו עזרא","אימר דקנסינהו עזרא דלא יהבינן להו משקל מינייהו מי אמר אלא כגון זרוע ולא זרוע ומאי ניהו ראשית הגז","ת\"ש זה הכלל כל דבר שהוא בקדושה כגון תרומה ותרומת מעשר וחלה מוציאין אותן מידם וכל דבר שאינו בקדושה כגון הזרוע והלחיים והקבה אין מוציאין אותו מידם","כגון זרוע ולא זרוע ומאי ניהו מעשר ראשון ולבתר דקנסינהו עזרא","ת\"ש השוחט לכהן ולעובד כוכבים פטור מן המתנות הא ללוי ולישראל חייב לא תימא הא ללוי ולישראל חייב אלא אימא הא לישראל חייב","אבל ללוי מאי פטור אי הכי ליתני השוחט ללוי ולעובד כוכבים פטור מן המתנות ועוד הא תניא השוחט לכהן ולעובד כוכבים פטור מן המתנות ללוי ולישראל חייב תיובתא דרב","אמר לך רב תנאי היא דתניא (ויקרא טז, לג) וכפר את מקדש הקדש זה לפני ולפנים","אהל מועד זה היכל מזבח כמשמעו יכפר אלו עזרות כהנים כמשמעו עם הקהל אלו ישראל יכפר אלו הלוים","ותניא אידך יכפר אלו עבדים מאי לאו בהא קמיפלגי דמר סבר איקרו עם ומר סבר לא איקרו עם","ורב אי סבירא ליה כהאי תנא לימא ואי סבירא ליה כהאי תנא לימא מספקא ליה אי כהאי תנא אי כהאי תנא","דרש מרימר הלכתא כוותיה דרב והלכתא כוותיה דרב חסדא","עולא הוה יהיב מתנתא לכהנתא איתיביה רבא לעולא מנחת כהנת נאכלת מנחת כהן אינה נאכלת","ואי אמרת כהן ואפילו כהנת והכתיב (ויקרא ו, טז) וכל מנחת כהן כליל תהיה לא תאכל אמר ליה רבי"],[[2,"כולהו עזיבה כתיבא בהו","שצריך להניח שם בהפקר ולא שיחלקם. הנך דכתיב בהו תעזוב הרי עזיבה והנך נמי כתיב בהו יהיה היינו בעזיבה דמשמע בהוייתו יהא דלא כתיבא בהו נתינה:"],[3,"לא תלקט לעני ולגר וגו'","ומשמע לא תלקט אני מזהיר לעני:"],[4,"נתינה כתיבא ביה","ונתת ללוי לגר וליתום ולאלמנה (שם כו):"],[5,"גמר לגר לגר מהתם","מולקט קצירך לא תלקט לעני ולגר:"],[5,"מה להלן עני מוזהר","כדאמרינן להזהיר עני על שלו:"],[6,"הא מלוי לכהן מוציאין אלמא","דלוים איקרו עם ואמאי מוציאין אי מספקא ליה לרב אי איקרו עם אי לא:"],[7,"ומתרץ כגון הזרוע ולא זרוע","כלומר אשאר מתנות כהונה שהן מתנה לכהן בזו קאמר דמוציאין ולא זרוע עצמה דילמא לא מיקרו עם:"],[7,"ומאי ניהו","דמוציאין מלוי לכהן מעשר ראשון:"],[8,"ופריך מעשר ראשון דלוי הוא","ואמאי מוציאין אותו מידו לתתו לכהן:"],[8,"אף לכהן","דבכ\"ד מקומות נקראו כהנים לוים הלכך אע\"ג דבמעשר ראשון לוי כתיבא ביה כהנים נמי משתמעי:"],[9,"","וקמסיים מילתיה אימר דאמר כו':"],[9,"בתר דקנסינהו עזרא","ביבמות (דף פו:) אמר מפני מה קנסו לוים במעשר מפני שלא עלו בימי עזרא דכתיב ואבינה בעם ובכהנים ומבני לוי לא מצאתי שם. אבל מקרא מפורש לא מצאתי שקנסם אבל דוגמא יש לדבר שכתוב בעזרא בסופו (נחמיה י) והיה הכהן בן אהרן עם הלוים במעשר הלוים למדנו שלא האמינום על תרומת מעשר ולא היו חולקין להן מעשר בגורן אלא (דקנסינהו) בפני הכהנים:"],[10,"ומהדר אימר דקנסינהו כו' משקל נמי מינייהו מי אמר","בתמיה. אכתי הדרא אתקפתא לדוכתיה הא מלוי לכהן מוציאין:"],[10,"אלא הכי תריץ כגון הזרוע","מוציאין מלוי לכהן ולא זרוע עצמו. ומאי ניהו כגון זרוע ראשית הגז דהתם לא כתיב עם ואי נמי לא איקרו עם מחייבי:"],[11,"כל דבר שבקדושה","שאסור לזרים כגון תרומה וכיוצא בהן מוציאין מיד לוי לכהן:"],[11,"ושאין בה משום קדושה כגון הזרוע כו'","שבאין מבהמות של חולין אין מוציאין מיד לוי לכהן. אלמא פשיטא לן דלא איקרו עם ואמאי מספקא ליה לרב:"],[12,"כגון זרוע ולא זרוע","דזרוע מוציאין דאיקרו עם והאי דקתני דאין מוציאין במעשר ראשון קאמר ובתר דקנסינהו עזרא ואיצטריך ליה לאשמועינן דאע\"ג דקנסינהו עזרא דלא למיתני להו דידהו מיהא לא שקלינן מינייהו:"],[13,"השוחט לכהן","להכי נקט השוחט לכהן דעליה דטבח רמיא דכתיב (דברים יח) מאת זובחי הזבח:"],[14,"וליתני ללוי ולעובד כוכבים","ואנא ידענא דכ\"ש בהך:"],[15,"וכפר את מקדש הקדש","בעבודת יום הכפורים:"],[15,"לפני ולפנים","מכפרת עבודה זו על הטומאה שאירעה בפנים דפר ושעיר של יוה\"כ מכפרים על טומאת מקדש וקדשיו כדאמרינן בשבועות (דף ב.):"],[16,"מזבח כמשמעו","על מי שעבד בטומאה במזבח בלא חיוב מקדש כגון נטמא במקדש דעבד בלא שהייה דאין כאן טומאת מקדש דהיכא דנטמא בעזרה קי\"ל בשבועות (דף טז.) הלכה למשה מסיני דלא מחייב עד שישהה כדי השתחואה:"],[16,"יכפר אלו העזרות","על טומאה שאירעה בעזרה על הכהנים ששגגו ונכנסו טמאים לעזרה. וכן לוים וישראלים ועבדים קראי יתירי קדריש:"],[17,"עבדים","כנענים דאינהו נמי בעי כפרה דכל מצות שהאשה חייבת בהן עבד חייב בהן וכל מקום דכתיב עונש איש ואשה שוין:"],[17,"דמר סבר איקרו עם","והוו בכלל עם הקהל הילכך וכפר יתירא אעבדים אתא:"],[17,"ומר סבר לא איקרו עם","ובעי קרא:"],[19,"הילכתא כרב","ולא שקלינן מינייהו:"],[19,"וכרב חסדא","דאמר מזיק מתנות כהונה או אוכלן פטור:"],[20,"לכהנת","בת כהן אפילו אשת איש דכיון דקדושה לית להו דאינן אסורים לזרים הרי מותרת בהן ולא דמי לתרומה ואי משום ונתן לכהן (ויקרא כב) קסבר אפילו כהנת משמע:"],[20,"מנחת כהנת נאכלת","השיריים כמנחת ישראל:"],[20,"מנחת כהן אינה נאכלת","דכולה כליל דכתיב (שם ו) כליל תהיה:"]],[]],[["מטונך אהרן ובניו כתובין בפרשה","דבי רבי ישמעאל תנא כהן ולא כהנת וילמוד סתום מן המפורש","דבי ר' אליעזר בן יעקב תנא כהן ואפילו כהנת הוי מיעוט אחר מיעוט ואין מיעוט אחר מיעוט אלא לרבות","רב כהנא אכל בשביל אשתו רב פפא אכל בשביל אשתו רב יימר אכל בשביל אשתו רב אידי בר אבין אכל בשביל אשתו","אמר רבינא אמר לי מרימר הלכתא כוותיה דרב והלכתא כוותיה דרב חסדא והלכתא כוותיה דעולא","והלכתא כוותיה דרב אדא בר אהבה לויה שילדה בנה פטור מחמש סלעים","תנו רבנן הזרוע והלחיים והקבה נוהגים בכלאים ובכוי רבי אליעזר אומר כלאים הבא מן העז ומן הרחל חייב במתנות (מן התייש ומן הצבייה) פטור מן המתנות","מכדי קי\"ל דלענין כסוי הדם ומתנות לא משכחת ליה אלא בצבי הבא על התיישה ובין לרבי אליעזר בין לרבנן מספקא להו אי חוששין לזרע האב אי אין חוששין","ובשה ואפילו מקצת שה קמיפלגי מר סבר שה ואפי' מקצת שה ומר סבר שה ואפילו מקצת שה לא אמרינן","בשלמא ר' אליעזר דפטר קסבר שה ולא מקצת שה אלא לרבנן נהי נמי דקסברי שה ואפילו מקצת שה פלגא לשקול ואידך פלגא לימא ליה אייתי ראיה דאין חוששין לזרע האב ושקול אמר רב הונא בר חייא מאי חייב נמי דקא אמר חייב בחצי מתנות","מתיב רבי זירא כוי יש בו דרכים שוין לבהמה ויש בו דרכים שוין לחיה ויש בו דרכים שוין לחיה ולבהמה","כיצד חלבו אסור כחלב בהמה ודמו חייב לכסות כדם החיה דרכים שוין לבהמה ולחיה שדמו וגידו אסורין כבהמה וחיה וחייב בזרוע ולחיים והקבה ורבי אליעזר פוטר","ואם איתא חייב בחצי מתנות מבעי ליה איידי דתנא חלבו ודמו דלא מתני חצי חצי משום הכי לא קא תני חצי","כי אתא רבין אמר רבי יוחנן כוי לרבנן חייב בכולהו מתנות דתניא שור מה ת\"ל (דברים יח, ג) אם שור לרבות את הכלאים שה מה ת\"ל (דברים יח, ג) אם שה לרבות את הכוי","ורבי אליעזר האי אם למה לי מיבעי ליה לחלק ורבנן לחלק מנא להו נפקא להו (דברים יח, ג) מאת זובחי הזבח","ור' אליעזר האי מאת זובחי הזבח מאי עביד ליה מבעי ליה לכדרבא דאמר רבא הדין עם הטבח:","\u0001מתני׳\u0002 בכור שנתערב במאה בזמן שמאה שוחטין את כולן פוטרים את כולן אחד שוחט את כולן פוטרים לו אחד","השוחט לכהן ולעובד כוכבים פטור מן המתנות והמשתתף עמהן צריך שירשום ואם אמר חוץ מן המתנות פטור מן המתנות","אמר מכור לי בני מעיה של פרה והיו בהן מתנות נותנן לכהן ואינו מנכה לו מן הדמים לקחן הימנו במשקל נותנן לכהן ומנכה לו מן הדמים:","\u0001גמ׳\u0002 ואמאי יבא עליו כהן משני צדדין ולימא ליה אי בכור הוא כוליה דידי הוא ואי לאו בכור הוא הב לי מתנתאי"],[[0,"מטונך","הגעתיך. מש\"ה אמרינן גבי מנחת כהנת דנאכלת דאהרן ובניו כתובין בפרשה וזאת תורת המנחה הקרב אותה בני אהרן וגו' וכיון דכתיב בהדיא בני אהרן למעוטי בנות אהרן אבל מתנות לא כתיב בהו אלא כהן גרידא ומשמע כהן ואפילו כהנת:"],[1,"סתום מן המפורש","כהן סתם דכתיב גבי מתנות ממפורש מבני אהרן דכתיב גבי מנחה דמה להלן כהן ולא כהנת דאהרן ובניו כתובין אף הכא כהן ולא כהנת:"],[2,"דבי ר' אליעזר בן יעקב תנא","בעלמא כהן ולא כהנת אבל כהן דכתיב גבי מתנות אפילו כהנת במשמע מאי טעמא הוי מיעוט כו' דברישיה דקרא כתיב וזה יהיה משפט הכהנים דמשמע כהנים ולא כהנות וכתיב בסיפיה דקרא ונתן לכהן הזרוע וגו' דמשמע נמי כהן למעוטי כהנת ואין מיעוט אחר מיעוט כו':"],[3,"רב כהנא","ישראל הוה ואשתו כהנת:"],[3,"אכיל","מתנתא:"],[3,"בשביל אשתו","שהיתה כהנת דס\"ל כהן ואפי' כהנת:"],[4,"הלכתא כותיה דרב חסדא","דאמר לעיל (חולין דף קל:) המזיק מתנות או שאכלן פטור מלשלם:"],[5,"והלכתא כרב אדא בר אהבה","דפטר נמי בנה של לויה מפדיון הבן כבנו של לוי דתנן כהנים ולוים פטורים בפ\"ב דבכורות (דף ג:) ואשמעינן רב אדא דלויה כלוי אליבא דמר בריה דרב יוסף דמוקי לה לדרב אדא בר אהבה בפ' יש בכור לנחלה (שם דף מז.) אפי' איעברא מישראל דבפטר רחם תלא רחמנא והרי רחם שיצא ממנו לאו דחיובא הוא ולאפוקי מדרב פפא דמוקים לה דאיעברא מעובד כוכבים אבל איעברא מישראל בתר אב אזלינן ליה וחייב:"],[6,"מן התייש ומן הצביה פטור מן המתנות","דשה כתיב ולא צבי:"],[7,"מכדי קי\"ל","באותו ואת בנו (לעיל חולין דף פ.) דלענין כסוי הדם ומתנות לא משכחת לה פלוגתייהו דר' אליעזר ורבנן אלא בצבי כו' ר' אליעזר סבר שה ולא מקצת שה:"],[9,"בשלמא ר' אליעזר דפטר","כלאים הבא מן התייש ומן הצביה סבירא ליה שה ולא מקצת שה:"],[9,"אידך פלגא לימא ליה","ישראל לכהן אייתי כו':"],[9,"מאי חייב נמי","דקמחייבי רבנן:"],[11,"חלבו אסור כחלב בהמה","דאזלינן לחומרא בכולהו:"],[12,"ואם איתא","כדקאמרת דמחייבי רבנן בחצי מתנות אמאי קתני הכא וחייב בזרוע לחיים וקבה דמשמע בכולהו חייב:"],[12,"","ומהדר לאו דוקא קתני חייב בזרוע כו' אלא איידי דתנא רישא דדמו כולו טעון כסוי וחלבו אסור דלא מצי למיתני חצי חצי דהא לא אפשר שחצי חלבו אסור וחצי מותר וה\"נ דחצי דמו טעון כסוי וחצי דמו אינו טעון ומשום רישא תנא סיפא ולא משום דוקא דה\"ה דאינו חייב אלא בחצי מתנות:"],[13,"שור","הוה מצי למימר:"],[14,"לחלק","דאי לא הוה כתיב אם הוה אמינא דאינו חייב במתנות עד שישחוט שה קמ\"ל אם שאם שוחט שור בפני עצמו חייב ליתן מתנות:"],[14,"הזבח","משמע אפילו זבח אחד:"],[15,"הדין עם הטבח","דינו של כהן לתבוע מן הטבח המתנות ואע\"פ שאין הבהמה של טבח אלא משל אחרים:"],[16,"מתני' בכור","של ישראל שנתערב במאה בהמות אחרות:"],[16,"בזמן שמאה","בני אדם שוחטין את הבהמות פוטרים את כולן ממתנות כהונה דכל אחד ואחד יכול לדחות את עצמו ולומר לכהן בכור שלי הוא וכן שני וכן שלישי:"],[16,"ואם אחד שוחט את כולן","אין פוטרין אותם מאה בהמות מליתן מתנות לכהן אלא אחד הואיל שהוא שוחט את כולן אבל אחד יכול לפטור מן המתנות שאי אפשר שלא יהא הבכור אחד מהן ויכול לומר זה הוא ומן הבכור אין נותנים שאין קדושה חלה על קדושה:"],[17,"צריך שירשום","שיעשה בו סימן שיבינו הרואים שאינו כולו של ישראל:"],[17,"אם אמר","כהן לישראל אני מוכר לך פרה זו חוץ מן המתנות שבה פטור ישראל מן המתנות:"],[17,"ואם אמר","ישראל לחבירו טבח מכור לי כו' כדפרישנא לעיל (חולין דף קלא.):"],[19,"גמ' אמאי","פוטרים את כולן הא יכול לבא כהן עליו משני צדדין כלומר בשני כחות ולימא ליה אי בכור הוא כוליה דידי הוא:"]],[[1,"דבי רבי ישמעאל תנא כהן ולא כהנת","נראה דלא ממעט אלא בנשאת לזר אבל לא נשאת כיון דאכלה בתרומה דחמירא כ\"ש דיהבי ליה מתנות ומיהו אפשר דלא יהבינן לה לר' ישמעאל:"],[3,"רב כהנא אכל בשביל אשתו","זהו רב כהנא שגלה מבבל לא\"י דפרק הגוזל בתרא (ב\"ק דף קיז.) שלא היה כהן כדאמרינן בסוף אלו עוברין (פסחים דף מט.) אמר רב כהנא אי לאו דנסיבת כהנתא לא גלאי ואחר יש שהיה כהן בפ\"ק דקדושין (דף ח.) רב כהנא שקל סודרא בפדיון הבן. [וע\"ע תוס' קדושין ח. ד\"ה ר\"כ ותוס' ב\"ב קי. ד\"ה ולא ובפסחים מט: ד\"ה אמר]:"],[9,"","ה\"ג מאי נוהגין נמי דקתני בחצי מתנות:"],[11,"חלבו אסור כחלב בהמה ודמו טעון כסוי כחיה וחייב במתנות כבהמה","הא דלא קתני הני תרתי דשוה לבהמה ביחד משום דניחא ליה למיתני דם וחלב בזה אחר זה שסמוכין בכל מקום:"],[12,"ואם איתא חייב בחצי מתנות מבעי ליה","בההיא דלעיל ניחא ליה טפי דלא תני בה חייב אלא נוהגין:"],[16,"בזמן שמאה שוחטים כולן פטורים","ע\"כ כשכולן בעלי מומין איירי דאין שוחטין בכור אא\"כ נפל בו מום ומדנתערב ואין מכירין בו א\"כ גם האחרים בעלי מומין הם:"],[17,"וצריך לרשום","סימן על הבשר רגילין היו לרשום בשר שפטור מן המתנות והיו מכירין רישומיהן וא\"ת כיון דלית ליה לכהן אלא חצי חצי ליפטר וחצי ליחייב מידי דהוי אצבי הבא על התיישה דמחייבי רבנן בחצי מתנות וי\"ל דהתם כל שיות שבו מחייב והכא לא מחייב כל שיות שבו לכך פטרי לגמרי:"],[19,"אמאי יבא עליו משני צדדים","בפ\"ב דבכורות (דף יח:) איכא פלוגתא גבי שתי רחלות אחת בכרה ואחת לא בכרה וילדו שני זכרים אחד לו ואחד לכהן והשני ירעה עד שיסתאב וחייב במתנות ור' יוסי פוטר והך סתמא כר\"מ דבתוספתא (פ\"ב דבכורות) מסיים בה דברי ר\"מ ומפרש בגמ' טעמא דר\"מ משום דבא עליו כהן משני צדדין ואע\"ג שכבר לקח אחד והשתא לא מבעיא לר\"מ דפריך הכא שפיר אלא אפילו רבי יוסי דפליג התם היינו משום דלא מצי אמר אי בכור הוא כוליה דידי הוא שכבר לקח אחד אבל הכא מודי משום דמצי אמר אי בכור הוא כוליה דידי הוא ומשני שמכרו לישראל במומו ואפי' לר\"מ דמחייב התם משום דממה נפשך אית ליה מתנות גביה אבל הכא ספק גמור והמוציא מחבירו עליו הראיה:"]]],[["אמר רב אושעיא בבא לידי כהן ומכרו לישראל במומו:","השוחט לכהן ולעובד כוכבים פטור מן המתנות: וליתני כהן ועובד כוכבים פטורין מן המתנות אמר רבא זאת אומרת הדין עם הטבח","דרש רבא (דברים יח, ג) מאת העם ולא מאת הכהנים כשהוא אומר (דברים יח, ג) מאת זובחי הזבח הוי אומר אפילו טבח כהן במשמע","אושפיזיכניה דר' טבלא כהן הוה והוה דחיק ליה מלתא אתא לקמיה דרבי טבלא אמר ליה זיל אישתתף בהדי טבחי ישראל דמגו דמפטרי ממתנתא משתתפי בהדך","חייביה רב נחמן אמר ליה והא רבי טבלא פטרן אמר ליה זיל אפיק ואי לא מפקינא לך ר' טבלא מאונך","אזל ר' טבלא קמיה דרב נחמן א\"ל מ\"ט עביד מר הכי א\"ל דכי אתא ר' אחא בר חנינא מדרומא אמר ר' יהושע בן לוי זקני דרום אמרו כהן טבח שתים ושלש שבתות פטור מן המתנות מכאן ואילך חייב במתנות","אמר ליה ולעביד ליה מר מיהת כר' אחא בר חנינא א\"ל הני מילי דלא קבע מסחתא אבל הכא הא קבע מסחתא","אמר רב חסדא האי כהנא דלא מפריש מתנתא ליהוי בשמתא דאלהי ישראל אמר רבה בר רב שילא הני טבחי דהוצל קיימי בשמתא דרב חסדא הא עשרים ותרתין שנין","למאי הלכתא אילימא דתו לא משמתינן להו והא תניא במה דברים אמורים במצות לא תעשה אבל במצות עשה כגון אומרים לו עשה סוכה ואינו עושה לולב ואינו עושה עשה ציצית ואינו עושה מכין אותו עד שתצא נפשו","אלא דקנסינן להו בלא אתרייתא כי הא דרבא קניס אטמא רב נחמן בר יצחק קניס גלימא","ואמר רב חסדא זרוע לאחד וקבה לאחד לחיים לשנים איני והא כי אתא רב יצחק בר יוסף אמר במערבא פלגינן להו גרמא גרמא","התם בדתורא","אמר רבה בר בר חנה א\"ר יוחנן אסור לאכול מבהמה שלא הורמה מתנותיה אמר רבה בר בר חנה א\"ר יוחנן כל האוכל מבהמה שלא הורמה מתנותיה כאילו אוכל טבלים ולית הלכתא כוותיה","אמר רב חסדא מתנות כהונה אין נאכלות אלא צלי ואין נאכלות אלא בחרדל מאי טעמא אמר קרא (במדבר יח, ח) למשחה לגדולה כדרך שהמלכים אוכלים","ואמר רב חסדא עשרים וארבע מתנות כהונה כל כהן שאינו בקי בהן אין נותנין לו מתנה ולאו מילתא היא דתניא רש\"א כל כהן שאינו מודה בעבודה אין לו חלק בכהונה שנאמר (ויקרא ז, לג) המקריב את דם השלמים ואת החלב מבני אהרן לו תהיה שוק הימין למנה","אין לי אלא זה בלבד מנין לרבות חמש עשרה עבודות כגון היציקות והבלילות והפתיתות והמליחות תנופות והגשות [והקמיצות] הקטרות (והמציות) [והמליקות]"],[[0,"אמר רב אושעיא","הכא במאי עסקינן דקתני מתניתין דפוטרין את כולן בבא אותו בכור ליד כהן ונפל בו מום קבוע:"],[1,"וליתני כהן ועובד כוכבים כו'","דהא לא איקרו עם ומאי איריא דקתני השוחט:"],[1,"זאת אומרת","מתניתין דקתני השוחט אתא לאשמועינן דבעלמא היכא דקשחיט בהמת ישראל הדין עם הטבח דינו של כהן לתבוע מתנותיו מן הטבח והכא כיון שהבהמה של כהן ועובד כוכבים הוא פטור הטבח מן המתנות והא לא מצינן למילף מכהן ועובד כוכבים לחוד:"],[2,"ולא מאת הכהנים","קס\"ד דכהנים לא איקרו עם:"],[2,"כשהוא אומר מאת זובחי הזבח","כלומר מי שהוא ואפילו כהן להביא כהן שנעשה טבח למכור אבל אבהמה שהוא שוחט לצרכו פטור:"],[3,"והוה דחיקא ליה מילתא","דחוק ועני היה:"],[3,"דמגו דפטרת להו ממתנתא","מזרוע לחיים וקבה כדאמרינן במתני' המשתתף עמהם פטור מן המתנות:"],[4,"חייביה","להאי ישראל שנשתתף עם אותו כהן:"],[4,"זיל אפיק","הוצא אותם מתחת ידיך ותתנם לכהן:"],[4,"מפיקנא לך כו'","כלומר כל ראיותיו וסייעותיו אמחה לו:"],[4,"מאונך","מאזנך:"],[5,"שתים ושלש שבתות פטור מן המתנות","לתתם לכהן אחר משום דאכתי לא קביע ואינן יודעין עדיין שהוא טבח אבל מכאן ואילך חייב הואיל דקביע:"],[6,"לעביד ליה מר הכי כדרבי אחא","ותפטרנו משתים ושלש שבתות:"],[6,"א\"ל הני מילי","דקא\"ר אחא וזקני דרום דשתים ושלש שבתות פטור:"],[6,"היכא דלא קבע מסחתא","חנות:"],[6,"אבל הכא","האי טבח כהן כבר קבע חנותו וגלי אדעתיה דקביע:"],[7,"דלא מפריש מתנתא","לכהן אחר:"],[7,"הא עשרין ותרתין שנין","כלומר כבר עברו כ\"ב שנה:"],[8,"למאי הלכתא","קאמר הא עשרין ותרתין שנין:"],[8,"אילימא","דמאחר שעמדו בשמתא כ\"ב שנה תו לא משמתינן להו:"],[8,"והתניא בד\"א","דתו לא משמתינן להו:"],[8,"במצות ל\"ת","דאית ביה מיתה או כרת דקם ליה בדרבה מיניה:"],[8,"כגון אומרים לו עשה סוכה עשה לולב","שאין בהן חסרון כיס כולי האי:"],[9,"אלא","הא קמ\"ל רבה מאחר שעמדו בשמתייהו כ\"ב שנה קנסינן להו בלא התראה אבל קודם לכן לא:"],[9,"קנים אטמא","כל הירך היה גוזל ממי שלא היה רוצה לתת המתנות לכהן והיה נותנה לכהן:"],[10,"ואמר רב חסדא","מתנות כהונה כך היא נחלקת זרוע היה נותן ישראל לכהן אחד וקבה לכהן אחד ולחיים לשני כהנים:"],[10,"גרמא גרמא","כל עצם ועצם היה מחלק לשנים:"],[11,"התם בדתורא","בשור הגדול שאבריו גדולים ביותר דאפילו היה מחלק האבר לשנים עדיין יש בכל חלק וחלק שיעור נתינה מעליא אבל בבהמה דקה אם היה מחלק האבר לשנים לא היה בכל חלק נתינה מעלייתא ורחמנא אמר ונתן לכהן נתינה יפה:"],[13,"למשחה","במתנות כהונה כתיב בויקח קרח לך נתתים למשחה כל מתנות שנתתי לך בכהונתך נתתי לך לגדולה כדמתרגמינן לרבותא:"],[14,"עשרים וארבע","לקמן בפירקין (חולין קלג:) חשיב להו:"],[14,"שאינו בקי בהן","היאך דין מתנה היאך נאכלין בגדולה:"],[14,"שאינו מודה בעבודה","שאמר בלבו דברי הבל הן ולא צוה המקום להקריב לו קרבנות אלא משה בדה מלבו:"],[14,"אין לו חלק בכהונה","אין לו חלק בקדשים:"],[14,"המקריב","היא הולכה:"],[15,"היציקות והבלילות","שנותן שמן במנחה ובוללה וחוזר ונותן עליה שמן לקיים בה מצות יציקה ויצק עליה שמן כדאמרינן באלו מנחות דכולן צריכות שלשה מתנות שמן:"],[15,"הפתיתות","מנחת מחבת ומרחשת ומנחת מאפה תנור שהיו נקמצות לאחר אפיה פותתן ומחזירן לסולתן וקומץ דכתיב פתות אותה פתים וגו':"],[15,"המליחות","במלח תמלח (ויקרא ב):"],[15,"התנופות","מוליך ומביא. ולא כל המנחות טעונות תנופה והגשה והתם מפרש להו יש טעונות תנופה ולא הגשה הגשה ולא תנופה לא תנופה ולא הגשה. ומה היא הגשה מגישה כשהיא בכלי קודם קמיצה ומגיעה לקרן מערבית דרומית כנגד חודה של קרן במנחות (סא.) ובסוטה (יד:):"],[15,"והמליקות גרסינן ולא גרסינן וההקרבות","דהא איהו חשיבא ברישא ובהדיא פרט בה קרא (שם ז) המקריב את זבח השלמים והיא הולכה:"]],[[2,"כשהוא אומר מאת זובחי הזבח","דמיירי בטבח ולא קאי אעם דנמעט טבח כהן מדלא כתיב מאת העם זובחי הזבח וכתיב מאת זובחי יתירה הפסיק הענין דאכל שהוא טבח קאמר ואפילו כהן הואיל ושחיט בהמת ישראל אבל אם היתה שלו אפילו למכור רחמנא פטריה אלא דמדרבנן גזרו כשהוא טבח ליתן מתנות כהונה אפילו הבהמה שלו שלא ירגילו טבחי ישראל לשתף כהנים עמהם ליפטר מן המתנות ועד ג' שבתות דאיכא למימר דדידיה שחיט לא גזרו רבנן ואוקמוה על דין תורה ומכאן ואילך גזרו וכי קבע מסחתא מיד מוכח דלאו לדידיה שחיט ולכך גזרו לאלתר כדמוכח בסמוך ולא כפי' הקונטרס דפירש דחייב מה\"ת בשוחט למכור דא\"כ שנים או שלשה שבתות אמאי פטור אטו שלשה שבתות כתיבי בקרא ועוד אי מן התורה א\"א שלא היה יודע ר' טבלא דבר זה אלא ודאי תקנת חכמים היא כדפירשנו ור' טבלא לא הוה שמיע ליה הך תקנתא עד דאמר ליה ר\"נ:"],[12,"כאילו אוכל טבלים","ממש דמתנות ילפינן נתינה נתינה מתרומה בפ' ראשית הגז (לקמן חולין דף קלו.):"],[13,"אין נאכלין אלא צלי ואלא בחרדל","וא\"ת דבפ' כל התדיר (זבחים דף צ:) אמרי' ובכולן רשאין הכהנים לשנות באכילה לאוכלן צלויין שלוקין מבושלין ואמר בגמרא טעמא משום דכתיב בהו למשחה פירוש לגדולה כדרך שהמלכים אוכלין ונראה דודאי כמו שטוב לו ונהנה יותר מצי אכיל להו אבל אדם שטוב לו צלי כשלוק ומבושל יאכל צלי שהוא דרך גדולה יותר:"],[14,"ולאו מילתא היא דתניא כו'","הוה מצי למימר מדאמרינן בריש פירקין המחזיקין בתורת ה' יש להם מנת משמע מחזיק אפילו שאין בקי:"]]],[["וקבלות הזאות והשקאת סוטה ועריפת עגלה ערופה וטהרת מצורע ונשיאות כפים בין מבפנים בין מבחוץ תלמוד לומר מבני אהרן עבודה האמורה לבני אהרן","וכל כהן שאינו מודה בה אין לו חלק בכהונה טעמא דאינו מודה בה הא מודה בה אע\"ג דאינו בקי בהן","אמר ר' אבא אמר רב הונא אמר רב חוטין שבלחי אסורים וכל כהן שאינו יודע ליטלן אין נותנין לו מתנה","ולא היא אי בטויא מידב דייבי ואי לקדרה אי דמיחתך להו ומלח להו מידב דייבי","אמר רבא בדק לן רב יוסף האי כהנא דחטיף מתנתא חבובי קא מחבב מצוה או זלזולי קא מזלזל במצוה ופשטנא ליה (דברים יח, ג) ונתן ולא שיטול מעצמו","אמר אביי מריש הוה חטיפנא מתנתא אמינא חבובי קא מחביבנא מצוה כיון דשמענא להא ונתן ולא שיטול מעצמו מיחטף לא חטיפנא מימר אמרי הבו לי וכיון דשמענא להא דתניא (שמואל א ח, ג) ויטו אחרי הבצע ר' מאיר אומר בני שמואל חלקם שאלו בפיהם מימר נמי לא אמינא ואי יהבו לי שקילנא","כיון דשמענא להא דתניא הצנועים מושכין את ידיהם והגרגרנים חולקים משקל נמי לא שקילנא לבר ממעלי יומא דכיפורי לאחזוקי נפשאי בכהני","ולפרוס ידיה אנסיה ליה עידניה","אמר רב יוסף האי כהנא דאית ליה צורבא מרבנן בשבבותיה ודחיקא ליה מילתא ליזכי ליה מתנתא ואף על גב דלא אתי לידיה במכרי כהונה ולויה","רבא ורב ספרא איקלעו לבי מר יוחנא בריה דרב חנא בר אדא ואמרי לה לבי מר יוחנא בריה דרב חנא בר ביזנא עביד להו עגלא תילתא א\"ל רבא לשמעיה זכי לן מתנתא דבעינא למיכל לישנא בחרדלא","זכי ליה רבא אכל ורב ספרא לא אכל אקריוה לרב ספרא בחלמא (משלי כה, כ) מעדה בגד ביום קרה חומץ על נתר ושר בשירים על לב רע","אתא לקמיה דרב יוסף א\"ל דלמא משום דעברי אשמעתא דמר אקריין הכי אמר ליה כי אמרי אנא באחר שמעא בעל כרחיה מזכי וכי אמרי אנא למאן דלא אפשר ליה הא אפשר ליה","ואלא מ\"ט אקריין הכי כלפי רבא ולקריין לרבא רבא נזוף הוה","א\"ל אביי לרב דימי ופשטיה דקרא במאי כתיב א\"ל בשונה לתלמיד שאינו הגון","דאמר רב יהודה אמר רב כל השונה לתלמיד שאינו הגון נופל בגיהנם שנאמר (איוב כ, כו) כל חושך טמון לצפוניו תאכלהו אש לא נופח ירע שריד באהלו ואין שריד אלא ת\"ח שנאמר (יואל ג, ה) ובשרידים אשר ה' קורא","אמר רבי זירא אמר רב כל השונה לתלמיד שאינו הגון כזורק אבן למרקוליס שנאמר (משלי כו, ח) כצרור אבן במרגמה כן נותן לכסיל כבוד וכתיב (משלי יט, י) לא נאוה לכסיל תענוג:","והמשתתף עמהן צריך לרשום: ואפילו עם העובד כוכבים ורמינהו המשתתף עם כהן צריך לרשום והמשתתף עם העובד כוכבים ופסולי המוקדשים אין צריך לרשום"],[[0,"קבלות","קבלת הדם:"],[0,"הזאות","היא זריקת דם הנזרקים במזבח בין הניתזין בפנים על הפרוכת ועל מזבח הזהב בין הניתזין בחוץ. שחיטה לא קחשיב שאף הזר כשר בה:"],[0,"עריפת העגלה","בכהנים היא כדכתיב (דברים כ״א:ה׳) ונגשו הכהנים בני לוי:"],[0,"טהרת מצורע","בצפרים להזות:"],[0,"בין מבפנים","במקדש כדכתיב (ויקרא ט׳:כ״ב) וישא אהרן את ידיו וגו':"],[0,"בין מבחוץ","בגבולין בכל עיר ועיר בבית הכנסת:"],[0,"מבני אהרן","סיפיה דקרא דלעיל הוא:"],[2,"חוטין שבלחי אסורים","משום דם:"],[3,"בטויא","בצלי:"],[4,"בדק לן","מנסה אותנו אם נדע להשיב ורבא כהן היה:"],[4,"דחטיף מתנתא","מתינוקות שנושאין אותם לכהנים:"],[5,"מי אמרינן חבובי קא מחבב המצוה","ויפה הוא עושה:"],[5,"ונתן","לכהן ולא שיטול הכהן מעצמו:"],[5,"מימר אמרי הבו לי","הייתי שואלו בפה מלא שהייתי סבור שהוא חיבוב מצוה:"],[5,"חלקם שאלו בפיהם","דמגני להו קרא לבני שמואל ויטו אחרי הבצע אמר רבי מאיר שלא היה עבירת גזל בידם אלא חלק לויה כגון מעשר ראשון היו שואלין בפיהם:"],[6,"הצנועים מושכין את ידיהם","בחילוק לחם הפנים קאמר במס' יומא בטרף בקלפי (יומא דף לט.) משמת שמעון הצדיק נשתלחה מארה בלחם הפנים:"],[6,"לאחזוקי נפשאי בכהני","שלא ישתכח הדבר שאני כהן:"],[7,"ופריך וליפרוס ידיה","כיון שאינו עושה אלא שלא ישתכח שם כהן מעליו יפרוס ידיו לדוכן כל השנה ומחזיק נפשיה בכהני:"],[7,"אנסיה ליה עידניה","עתים שקבע לתלמידיו היו טורדים אותו מלישא את כפיו שהיה עוסק לתלמידיו בעת שהצבור נאספים לבית הכנסת:"],[8,"ודחיקא ליה מלתא","לההוא צורבא מרבנן והכהן רוצה לההנותו יתן לו חלק מתנותיו לקבל זרוע ולחיים מבני העיר בשביל הכהן והוא יאכלם:"],[8,"ואע\"ג דלא אתי לידיה","דכהן יכול לזכות לו:"],[8,"במכרי כהונה ולויה","בכהן שהיה ניכר בעיר ורוב בני אדם אוהבים אותו ונותנין לו המתנות ובאותו כהן אמרינן דיכול לזכות מעשרותיו לאחר אף על גב דלא אתי לידיה. מכרי לשון (מלכים ב יב) איש מאת מכרו:"],[9,"אמר ליה רבא לשמעיה","לשמשו של בעה\"ב והוא כהן ובעה\"ב נותן לו מתנותיו:"],[9,"זכי לי מתנתא","תן לי רשות ליקח מתנותיך לאוכלם מפני שהלשון עם הלחיים ניתן לכהנים ובעינן למיכל לישנא בחרדלא שהוא דבר חשוב וה\"נ אמרינן בהשוכר את הפועלים (בבא מציעא דף פו:) כדי להאכילם שלש לשונות בחרדל. ואף על גב דרבא נמי כהן הוה דקיימא לן (ראש השנה דף יח.) דמבני עלי אתא ובבכורות (דף כז.) נמי אמרינן רבא הוה מבטל תרומת חוצה לארץ ברוב ואכיל לה בימי טומאתו מיהו מנפשיה לא מצי שקיל דכתיב ונתן ולא שיטול מעצמו ומימר נמי לא בעי למימר הבו לי דתניא חלקם שאלו בפיהם להכי שקלם בתורת זר על ידי נתינת כהן ואף על גב דלא מטא לידיה דשמעא סמך רבא אדרב יוסף דלעיל:"],[10,"רב ספרא לא אכל","משום דלא מטא לידיה דשמעא:"],[10,"מעדה בגד ביום קרה","בגד בלוי ונרקב כמו (ישעיהו סד) וכבגד עדים. בעת הקור אינו שוה כלום:"],[10,"וכמו חומץ על נתר","שאינו אלא מפסידו. נתר הוא מין צריף אלו\"ם בלע\"ז:"],[10,"כן שר בשירים על לב רע","כן האומר דברי תורה למי שאינו יודע להבין בהן:"],[11,"משום דעברי אשמעתא דמר","שלא סמכתי על שמועתך שאמרת דמותר לצורבא מרבנן לקבלה אף על גב דלא אתו לידיה דכהן:"],[11,"כי אמרי אנא באחר","היכא דמזכי ליה כהן אחר שאינו כפוף לו אבל שמעא דבעל הבית על כרחו מזכי ליה לאדם חשוב שהוא בא בביתו של בעל הבית. אי נמי אימר דאמרי אנא דיכול לזכות מתנתא לאחר אף על גב דלא אתו לידיה:"],[11,"דלא אפשר ליה","כלומר לאיש שהוא עני ודחוק אבל רבא אפשר ליה ולא דחיקא ליה מילתא:"],[12,"","כיון דלא עבר רב ספרא אשמעתיה דרב יוסף מאי טעמא אקריוה בחלמיה:"],[12,"כלפי רבא","כלומר על רבא שלא ידע להבין בטעמו של רב יוסף הקרוהו לרב ספרא כך:"],[12,"נזוף הוה","אני שמעתי משום דהטיח כלפי מעלה במסכת תענית (דף כד:) דבעא מיטרא ללא צורך משום יקרא דאמיה דשבור מלכא ואמרינן התם דאיתחזי ליה אבוה בחלמיה וא\"ל מי איכא דמיטרח קמי שמיא אשני דוכתיך אשני דוכתיה למחר אשכחיה לפורייה דמרשם בסכיני שנועדו מלאכי חבלה להורגו בלילה. ולי נראה נזוף משום האי מעשה:"],[14,"ירע שריד באהלו","למי שירע שריד באהלו תלמיד רע:"],[14,"תאכלהו אש לא נופח","אשו של גיהנם:"],[15,"כזורק אבן למרקוליס","זו היא עבודתו כדאמרינן במסכת ע\"ז (דף מט:):"],[16,"ואפילו עם העובד כוכבים","בתמיה. ורמינהי המשתתף עם הכהן כו':"],[16,"עם העובד כוכבים","או המוכר פסולי המוקדשין שנפדו ושחטן ומכרן והן פטורין מן המתנות כדאמר במתניתין דצבי ואיל כתיב בהו:"],[16,"אינו צריך לרשום","ולקמן מפרש:"]],[[0,"קבלות","וא\"ת תיפוק ליה קבלות מהמקריב את דם השלמים דהקרבה הוי לשון קבלה כדאמרינן פרק הקומץ [רבה] (מנחות דף יט.) והקריבו בני אהרן מקבלה ואילך מצות כהונה וי\"ל דהכא כיון דכתיב המקריב את דם השלמים ואת החלב ובחלב לא שייך קבלה דם נמי לא משתעי בקבלה:"],[0,"היציקות","בריש הקומץ [רבה] (שם דף יח:) פריך מינה להא דאמר התם לא יצק כהן אלא זר כשר והכא קאמר שהיא עבודה המסורה לבני אהרן ומסקינן דלא כר\"ש:"],[6,"משקל נמי לא שקילנא","שלא אקרא גרגרן ולא אגזול ממי שצריך יותר ממני אע\"פ שגם הוא לא היה עשיר:"],[6,"לבר ממעלי יומא דכפורי","שיום טוב הוא כדאמר בפרק אותו ואת בנו (לעיל חולין דף פג.) ומתנות מרובות וכהנים מתאספין ואילו לא היה נוטל היו אומרים שאינו כהן:"],[9,"אמר ליה רבא לשמעיה כו'","רבא גרסי' דרבה כהן הוה כדאמר פרק עד כמה (בכורות דף כז.) (רבא) [רבה] הוה מבטל לה ברוב ואמרי' נמי (ר\"ה דף יח.) אביי ורבה מדבית עלי קא אתו:"]]],[["הכא במאי עסקינן דיתיב עובד כוכבים אמסחתא","דכותה גבי כהן דיתיב אמסחתא אמאי צריך לרשום דאמרי בשרא קא זבין אי הכי עובד כוכבים נמי אמרי בשרא קא זבין","אלא הכא במאי עסקינן דיתיב עובד כוכבים אכספתא דכותה גבי כהן דיתיב אכספתא אמאי צריך לרשום אמרי המוני הימניה עובד כוכבים נמי אמרי המוני הימניה","אין אמונה בעובד כוכבים איבעית אימא סתם עובד כוכבים מפעא פעי","אמר מר ופסולי המוקדשין אין צריך לרשום אלמא מוכחא מלתא והא אנן תנן פסולי המוקדשין נמכרים באיטליז ונשחטים באיטליז ונשקלים בליטרא","תרגמא רב אדא בר אהבה קמיה דרב פפא באותן הנמכרים בתוך הבית","אמר רב הונא שותף בראש פטור מן הלחי שותף ביד פטור מן הזרוע שותף בבני מעיין פטור מן הקבה וחייא בר רב אמר אפי' שותף באחת מהן פטור מכולן","מיתיבי הראש שלי וכולה שלך ואפי' אחד ממאה בראש פטור היד שלי וכולה שלך אפי' אחד ממאה ביד פטור בני מעיין שלי וכולה שלך אפי' אחד ממאה בהן פטור","מאי לאו פטור מן הלחי וחייב בכולן פטור מן הזרוע וחייב בכולן פטור מן הקבה וחייב בכולן לא פטור מכולן","וליתני פטור מכולן ועוד תניא הראש שלי וכולה שלך אפי' אחד ממאה בראש פטור מן הלחי וחייב בכולן תיובתא דחייא בר רב תיובתא","אמר רב חסדא הא מתניתא אטעיתיה לחייא בר רב דתניא עשרים וארבע מתנות כהונה הן וכולן ניתנו לאהרן ולבניו בכלל ופרט וברית מלח","כל המקיימן כאילו קיים בכלל ופרט וברית מלח וכל העובר עליהן כאילו עובר על בכלל ופרט וברית מלח","ואלו הן עשר במקדש וארבע בירושלים ועשר בגבולים עשר במקדש חטאת וחטאת העוף אשם ודאי ואשם תלוי וזבחי שלמי צבור ולוג שמן של מצורע ושתי הלחם ולחם הפנים ושירי מנחות ומנחת העומר","וארבע בירושלים הבכורה והבכורים ומורם מן התודה ומאיל נזיר ועורות קדשים","ועשר בגבולים תרומה ותרומת מעשר וחלה וראשית הגז ומתנות ופדיון הבן ופדיון פטר חמור","ושדה אחוזה ושדה חרמים וגזל הגר","הוא סבר מדקא חשיב להו למתנות בחדא חדא נינהו ולא היא אטו מורם מתודה ואיל נזיר דקא חשיב להו כחדא משום דחדא נינהו אלא כיון דדמיין להדדי חשיב להו כחדא ה\"נ כיון דדמיין להדדי חשיב להו כחדא","איבעיא להו הראש שלך וכולה שלי מהו בתר חיובא אזלינן וחיובא גבי ישראל הוא או דלמא בתר עיקר בהמה אזלינן ועיקר בהמה דכהן הוא","ת\"ש עובד כוכבים וכהן שמסרו צאנם לישראל לגזוז פטור הלוקח גז צאנו של עובד כוכבים פטור מראשית הגז","זה חומר בזרוע ובלחיים ובקבה יותר מראשית הגז ש\"מ בתר חיובא אזלינן שמע מינה:","ואם אמר לו חוץ מן המתנות פטור מן המתנות:"],[[0,"הכא במאי עסקינן","דהמשתתף עם עובד כוכבים אינו צריך לרשום:"],[0,"דיתיב עובד כוכבים אמסחתא","כשהטבח מוכר הבשר דמוכחא מילתא דעובד כוכבים שותף הוא ואין כאן חשד ומתניתין בדלא יתיב:"],[1,"דכותה גבי כהן","דברייתא:"],[1,"דיתיב","כהן אמסחתא אמאי צריך לרשום הא נמי מוכחא מילתא דכהן שותף בה:"],[1,"","אפ\"ה דיתיב כהן אמסחתא לא הוי ידעי אינשי דכהן שותף בה:"],[1,"דאמרי בשרא קזבין","בשר הוא רוצה לקנות:"],[2,"אלא","לא תוקמה דיתיב עובד כוכבים אמסחתא אלא הכי תוקמה דיתיב עובד כוכבים אכספתא על הארגז שנותן בה הטבח המעות כשמקבלם תמיד מן הלוקחים דהא ודאי מוכחא שפיר דעובד כוכבים שותף בה:"],[2,"דאמרי","הרואים המוני הימניה לשומרם לו שלא יגנבום הימנו:"],[3,"אין אמונה בעובד כוכבים","אין ישראל רגילין להאמין בהם:"],[3,"אבע\"א","לעולם כדאוקימנא מעיקרא דיתיב עובד כוכבים אמסחתא וכהן נמי דיתיב אמסחתא ולא דמו דסתם עובד כוכבים מפעא פעי תדיר הוא צועק אל תתנם בכך אלא בכך והכל יודעין שיש לו חלק בה אבל כהן צנוע הוא וסומך על הטבח ואין הכל יודעין שהוא שותף:"],[4,"אלמא מוכחא מילתייהו","דלא מזבין להו כדרך חולין:"],[4,"באיטליז","בשוק:"],[5,"באותן הנמכרים בתוך הבית","בכור ומעשר דהתם תנן חוץ מן הבכור והמעשר שהנאתן לבעלים שאין דמיהן קדש דכתיב בהו לא תפדה ולא תגאל דהיינו אין קדושה לדמיהן לפיכך לא התירו לו בשביל הנאתו לזלזל בהן למוכרן בשוק כדרך חולין אלא בתוך הבית ואע\"פ שמפסיד בדבר שאין עליהם קופצין כל כך והיינו מוכחא מילתא אבל פסולי המוקדשים שדמי פדיונן נכנסו בקדושתן אי לא שרית ליה למוכרן בשוק לא פריק להו מעיקרא אלא בזול ואיכא פסידא דהקדש והנהו צריך לרשום:"],[6,"שותף בראש","ולא ביותר:"],[7,"אפילו אחד ממאה ביד","אפילו אין לכהן או לעובד כוכבים חלק בזרוע אלא אחד ממאה פטור טבח. ובכהן או עובד כוכבים שמכרו בהמה לטבח ישראל קאמר. ובכולהו גרסינן פטור סתמא:"],[9,"אי הכי ליתני פטור מכולם","בהדיא:"],[9,"ועוד תניא","בהדיא דלא פטר ליה אלא מן הלחי:"],[10,"בכלל ופרט","בויקח קרח לכל קדשי בני ישראל לך נתתים והדר מפרש כל חד וחד וזה יהיה לך מקדש הקדשים מן האש וגו':"],[10,"וברית מלח","כתיב בסיפיה ברית מלח עולם הוא כשם שברית מלח אינה שובתת כך זו לא תשבות:"],[11,"כאילו קיים כללות ופרטות","שבתורה:"],[11,"וברית מלח","של קרבנות:"],[12,"עשר במקדש","ניתנו להם בתוך עזרה לאוכלן שם:"],[12,"זבחי שלמי צבור","כבשי עצרת והם קדשי קדשים לאכול בעזרה:"],[12,"לוג שמן של מצורע","מה שנשאר ממתנותיו נאכל לכהנים כדאמרינן במנחות (דף נח.) ובזבחים (דף מד:) לכל קרבנם דכתיב בויקח קרח לרבות לוג שמן של מצורע דקרוי קרבנם דכתיב ביה והקריב אותם לאשם ואת לוג השמן וכתיב בויקח קרח בקדש הקדשים תאכלנו אכולהו לכל קרבנם ולכל מנחתם ולכל חטאתם ולכל אשמם וגו':"],[12,"","עומר לא חשיב ליה בהדי שאר מנחת צבור מפני שהיא מנחת צבור הנקמצת ונאכלת ואין לך עוד בצבור:"],[12,"ושירי מנחות","של יחיד:"],[13,"בירושלים","הנאכלים ומתחלקים לכל העיר:"],[13,"הבכורה","בכור תם:"],[13,"בכורים","אינם נאכלים אלא בירושלים דכתיב (דברים י״ב:י״ז) לא תוכל לאכול בשעריך וגו' ואמר מר (מכות דף יז:) ותרומת ידך אלו הבכורים:"],[13,"ומורם מתודה","חזה ושוק וד' חלות כדכתיב (ויקרא ז) והקריב ממנו אחד מכל קרבן תרומה לה' לכהן הזורק וגו' מארבעת מינים חלות ורקיקים ורבוכה וחמץ אחת מכל מין:"],[13,"ומורם מאיל נזיר","זרוע בשלה וחלה ורקיק כדכתיב בפרשת נשא שמניפין אותן. והני חד חשיב להו משום דדמו אהדדי דתרווייהו מורם מקדשים קלים נינהו וחזה ושוק של שאר שלמים נמי בכלל זה הן והאי דנקט תודה משום דאית ביה מורם אחרינא ותנינהו לכולהו בחדא שמא:"],[13,"ועורות קדשים","של עולה חטאת ואשם כדכתיב (ויקרא ז) עור העולה אשר הקריב ובתורת כהנים נמי מרבה עור חטאת ואשם:"],[14,"בגבולים","נתנין להם בכל ערי ישראל:"],[14,"ומתנות","הזרוע והלחיים והקבה:"],[14,"פדיון הבן","ה' סלעים:"],[14,"פדיון פטר חמור","שה:"],[15,"שדה אחוזה","שהקדיש ולא גאלה ומכרה גזבר לאחר והרי היא יוצאה ביובל ומתחלקת לכהנים של אותו משמר שאירע בו יובל שנאמר (ויקרא כז) והיה השדה בצאתו ביובל וגו' לכהן תהיה אחוזתו:"],[15,"וגזל הגר","האשם המושב לה' בפרשת נשא וגזל הגר שנשבע לו לשקר ואח\"כ הודה לאחר מיתת הגר כדפי' לעיל בפרקין [חולין קלא. ד\"ה תשעה]:"],[16,"הוא סבר","חייא בר רב סבר:"],[16,"מדקא חשיב","האי תנא לכולהו זרוע לחיים וקבה כחדא מתנה שלא אמר עשרים ושש:"],[16,"ש\"מ","חדא היא והמחוייב באחד מתחייב בכולם והנפטר מאחת מהן פטור מכולן:"],[17,"כולה שלי והראש שלך","כהן מוכר לטבח הראש קודם שחיטה:"],[18,"הכי גרסינן ת\"ש עובד כוכבים וכהן שמסרו צאנן לישראל לגזוז","שעשאוהו שלוחן לגזוז את צאנן:"],[18,"פטור","ואיידי דתנא לה גבי מתנות השוחט לכהן ולעובד כוכבים פטור תנייה נמי גבי ראשית הגז:"],[18,"הלוקח גז צאנו של עובד כוכבים","אפילו קודם שנגזזו פטור:"],[19,"וזה חומר וכו'","דהלוקח מתנות מן הכהן חייב קודם שחיטה וכל בהמה לכהן חייב במתנות שלא זכה בה קודם שחיטה:"],[19,"ש\"מ","מדקתני זה חומר אלמא בתר חיובא אזלינן דהאי לא קנה אלא מתנות וקאמר חייב:"]],[[12,"זבחי שלמי צבור","הן כבשי עצרת ויש להם דין אשמות ליאכל לפנים מן הקלעים כדתנן באיזהו מקומן (זבחים דף נד:):"],[13,"ועורות קדשים","תימה אמאי חשיב עורות קדשים מהארבע שהיו בירושלים הלא בעזרה היו מפשיטין אפילו קדשים קלים משום אימורים שלא היו יכולים להוציא חוץ לעזרה וה\"ל למימניה עם עשר שבמקדש:"],[17,"או דילמא בתר עיקר בהמה אזלינן","הא לא דמי כלל למתניתין דתנן חוץ מן המתנות פטור מן המתנות דהא לא מחייב התם ישראל במתנות משום שהמתנות נשארו ביד כהן:"]]],[["ורמינהו על מנת שהמתנות שלי נותן לכל כהן שירצה","על מנת אחוץ קא רמית חוץ שיורא על מנת לאו שיורא","ורמינהו על מנת שהמתנות שלי המתנות שלו בהא פליגי מר סבר על מנת שיורא הוא ומר סבר על מנת לאו שיורא הוא:","אמר לו מכור לי בני מעיה וכו': אמר רב לא שנו אלא ששקל לעצמו אבל שקל לו טבח הדין עם הטבח ורב אסי אמר אפי' שקל לו טבח הדין עמו","לימא בדרב חסדא קא מיפלגי דאמר רב חסדא גזל ולא נתייאשו הבעלים ובא אחר ואכלו רצה מזה גובה רצה מזה גובה דמר אית ליה דרב חסדא ומר לית ליה דרב חסדא","לא דכולי עלמא אית להו דרב חסדא והכא במתנות כהונה נגזלות קא מיפלגי דמר סבר נגזלות ומר סבר אין נגזלות","איכא דמתני לה להא שמעתא בפני עצמה רב אמר מתנות כהונה נגזלות ורב אסי אמר מתנות כהונה אין נגזלות:","\u0001מתני׳\u0002 גר שנתגייר והיתה לו פרה נשחטה עד שלא נתגייר פטור משנתגייר חייב ספק פטור שהמוציא מחבירו עליו הראיה:","\u0001גמ׳\u0002 כי אתא רב דימי אמר רמי ליה רבי שמעון בן לקיש לר' יוחנן תנן ספק פטור אלמא ספיקא לקולא","ורמינהו חורי הנמלים שבתוך הקמה הרי אלו של בעל הבית ושלאחר הקוצרים העליונים לעניים והתחתונים של בעל הבית","רבי מאיר אומר הכל לעניים שספק לקט לקט","אמר ליה אל תקניטני שבלשון יחיד אני שונה אותה דתניא ר' יהודה בן אגרא אומר משום רבי מאיר ספק לקט לקט ספק שכחה שכחה ספק פאה פאה","אמר לו אל תשנה אותה אלא בלשון בן תדל והא טעמא קאמר דאמר ר\"ש בן לקיש מאי דכתיב (תהלים פב, ג) עני ורש הצדיקו מאי הצדיקו","אילימא בדינים והא כתיב (שמות כג, ג) ודל לא תהדר בריבו אלא צדק משלך ותן לו","אמר רבא הכא פרה בחזקת פטורה קיימא קמה בחזקת חיובא קיימא","אמר ליה אביי והרי עיסה נעשית עד שלא נתגייר פטור מן החלה משנתגייר חייב ספק חייב","אמר ליה ספק איסורא לחומרא ספק ממונא לקולא","דאמר רב חסדא וכן תני ר' חייא שמונה ספקות נאמרו בגר ארבע לחיוב וארבע לפטור","קרבן אשתו וחלה ובכור בהמה טמאה ובכור בהמה טהורה לחיוב"],[[0,"ורמינהו","כהן שמכר בהמה לישראל ואמר לו ע\"מ שהמתנות שלי נותנן ישראל לכל כהן שירצה דכיון דכולה בהמה זבין ליה לא מצי לאתנויי ליה האי אמתנות שאינן שלו אלא של כהנים נינהו ואין לו בהן אלא טובת הנאה מ\"מ ש\"מ דחייב במתנות:"],[1,"חוץ שיור","לשון שיור משמע ששייר המתנות ולא מכרן לפיכך פטור הלוקח שהרי של כהן הן ודכוותה בישראל הוה מחייב הלוקח דכיון שהוא שחטה עליה רמיא למיתבינהו:"],[1,"על מנת לאו שיורא הוא","אלא תנאה הכל מכר לו ע\"מ שיתנם לו והוא אין בו כח להתנות:"],[2,"ורמינהו","ברייתא אברייתא:"],[3,"לא שנו","היכא דלקח הימנו במשקל דקתני נותנן לוקח לכהן והוא חוזר ותובע דמים מן הטבח:"],[3,"אלא","כששקלן לוקח לעצמו דכיון דטבח לא נגע בהן אינו בעל דברים של כהן לפיכך זה הלוקח נותנן והוא שואל לו הדמים שעל הטבח היה מוטל ליתן:"],[3,"אבל שקלן לו טבח הדין","של כהן ומחלוקתו ותביעתו אף על הטבח הוא והטבח חוזר עליהן אם יש בעין נותנן לכהן והכי מפרש לה בריש הגוזל בב\"ק (דף קטו.) דאף עם הטבח קאמר ר' יהודה:"],[3,"הדין עמו","דינו של כהן ותביעתו עם הלוקח הוא הואיל וישנה לגזלה בעין במקום שהוא שם ילך:"],[4,"","רב אית ליה דרב חסדא:"],[4,"רצה מזה גובה","דכיון דקודם יאוש אכלו זה האחרון הוה ליה איהו גזלן עלייהו דהא כל מקמי יאוש ברשותייהו דמרייהו קיימי כל היכא דאיתנהו:"],[5,"לא","בגזלן דעלמא שהגזלן קונה אותו בגזלתו לשלם:"],[5,"דכולי עלמא אית להו דרב חסדא","דאם רצה נגזל לדון עם הראשון ידון:"],[5,"והכא","בגזל מתנות כהונה קמיפלגי מר סבר מתנות כהונה נגזלות ונתחייב גזלן בגזלתו לשלם דתורת גזל עליהן:"],[5,"ומר סבר אינם נגזלות","אין כח לגזלן וכל זמן שהן בעין כל מקום שהולכין החוב מוטל על מי שהם אצלו לתתו לכהן והראשון לא נעשה גזלן עליהן:"],[5,"באפי נפשה","ולא בלשון לא שנו ואמתני' כדלעיל:"],[6,"מתנות כהונה נגזלות","לכדאמרן שאם רצה כהן לדון עם הראשון ידון:"],[8,"אלמא ספק","מתנות כהונה לקולא דאמרינן המוציא מחבירו עליו הראיה:"],[9,"שבתוך הקמה","לפני הקוצרים שעדיין לא הגיעו הקוצרים לשם:"],[9,"הרי","כל הנמצא בהן לבעה\"ב דאין לקט אלא הנושר בשעת קצירה:"],[9,"העליונים","חטין העליונים שעל פי החור איכא למימר לקט הן שנשרו מן השבלין בשעת קצירה:"],[9,"והתחתונים","שבקרקעיתו של חור:"],[9,"לבעל הבית","דקודם קצירה כנסום נמלים שם:"],[10,"שספק לקט לקט","אלמא לרבי מאיר גבי מתנות עניים וה\"ה למתנות כהונה ספיקא לחומרא וסתם מתני' ר\"מ היא וקתני ספיקא לקולא:"],[11,"אל תקניטני","דהא דקתני ספק לקט לקט יחידאה היא שאיני שונה אותה כמו ששנית דברי ר\"מ אלא דברי ר' יהודה בן אגרא משום ר\"מ:"],[12,"א\"ל","ר\"ל:"],[12,"אל תשנה אותה אלא בלשון בן תדל","אפי' אין אתה שונה אותה אלא בשם שוטה שבעולם ששמו בן תדל אפילו הכי קשיא לך דהא טעמא קאמר למילתיה:"],[13,"אילימא בדינין","לראות לו זכות בדין:"],[13,"","צדק משלך ותן לו:"],[14,"פרה","כשנולד לך ספק זה במתנותיה ואתה מעמידה על חזקתה הראשונה הרי היא פטורה שהרי בחזקת של עובד כוכבים היתה עומדת:"],[14,"קמה","כשנולד לך ספק בלקט ואתה מעמידה על חזקתה חזקת חיוב הוא דמעולם היא עומדת לכך דשל ישראל היא:"],[15,"","חיוב חלה הכל הולך אחר גלגולה משגלגל בה הוי חיובה וגלגול העובד כוכבים פוטר דכתיב (במדבר טו) עריסותיכם. אם עד שלא נתגייר נתגלגלה פטור אם ספק חייב גרסינן:"],[16,"","חלה ספק איסורא שיש בה עון מיתה הלכך לא סמכינן אחזקה אבל מתנות אין בהן קדושה אלא דין ממון והמוציא מחבירו עליו הראיה:"],[18,"קרבן אשתו","ספק ילדה כשהיתה עובדת כוכבים ספק משנתגיירה מביאה קרבן דספק איסור כרת הוא לאכול בקדשים עד שתביא כפרה דמחוסר כפורים אסור בקדשים וענוש כרת:"],[18,"וחלה","ספק מיתה:"],[18,"ובכור בהמה טהורה","ספק כרת לשוחטו בחוץ וצריך להמתין עד שיסתאב דתו לית ביה אלא דין ממון ואוכלו הוא במומו:"],[18,"ובכור","פטר חמור. כמאן דאמר בבכורות (דף ט:) אסור בהנאה עד שיפדנו וצריך להפריש עליו טלה לפדיונו לאפקועי איסוריה ומעכב הטלה בידו והוא שלו דשה של פדיון לא רמיא קדושה עליה אלא ממונא דכהן הוא וכיון דספק הוא המוציא מחבירו עליו הראיה:"]],[[1,"חוץ שיורא הוא ע\"מ לאו שיורא הוא","וא\"ת כי א\"ל ע\"מ דאמרינן נותנן לכל כהן שירצה א\"כ המקח בטל שלא נתן לו הבהמה אלא ע\"מ שיהיו המתנות שלו וי\"ל דמיירי שהתנו שיהיו המתנות שלו ואם לא יתן לו לא יהיה המקח בטל אי נמי הוי כמו מתנה על מה שכתוב בתורה שהרשתו תורה ליתנם לכל מי שירצה:"],[4,"דמר אית ליה דרב חסדא","אין לפרש דרב אית ליה דרב חסדא ועם הראשון דקאמר רב היינו אפי' עם הראשון דא\"כ לרב אסי הדין עם השני ולא עם הראשון בגזל ולא נתייאשו הבעלים ובא אחר ואכלו דהא ליכא מאן דפליג שלא יוכל לגבות מן הראשון הגוזל ובאחר שאכלו הוא דאיכא דלית ליה דרב חסדא אלא יש לפרש איפכא דרב לית ליה דרב חסדא דהדין דוקא עם הטבח ורב אסי אית ליה דרב חסדא והדין אף עם הלוקח ודחי דכ\"ע אית להו דרב חסדא ובמתנות כהונה נגזלות קא מיפלגי דרב סבר נגזלות והדין עם הטבח היינו אף עם הטבח כרב חסדא ורב אסי סבר דהדין דווקא עם הלוקח לפי שהמתנות אין נגזלות והוי איפכא ממאי דהוה בעי למימר מעיקרא ותימה דבמאי קא מיירי אי בשאין מתנות בעין הא אמרינן בריש פירקין דמזיק מתנות כהונה או אכלן פטור ואם הם בעין היכי קאמר דבדרב חסדא קא מיפלגי הא משמע בריש הגוזל בתרא (ב\"ק דף קיא:) דהיכא דהם בעין ליכא מאן דפליג אדרב חסדא אלא דווקא כשאכלן דתני רבי אושעיא הגוזל ומאכיל את בניו פטורין מלשלם הניח לפניהן גזלה קיימת חייבים לשלם אין גזלה קיימת פטורין כו' ופריך לימא תהוי תיובתא דרב חסדא משמע דלמאן דפליג עליה אתי שפיר דדוקא אין גזילה קיימת פטורים אבל בגזלה קיימת חייבים לשלם וצ\"ע:"],[9,"ורמינהי חורי הנמלים שבתוך הקמה כו'","מרבנן נמי פריך דלא פליגי רבנן אלא משום דסברי דתחתונים ודאי נמלים כנסום הילכך הם של בעה\"ב הא אם היו ספק היו מודים דהוי לקט כמו עליונים שספק לקט לקט:"]]],[["ראשית הגז והמתנות ופדיון הבן ופדיון פטר חמור לפטור","כי אתא רבין אמר קמה אקמה רמי ליה","לוי זרע בכישר ולא הוו עניים למשקל לקט אתא לקמיה דרב ששת אמר ליה (ויקרא יט, י) לעני ולגר תעזוב אותם ולא לעורבים ולא לעטלפים","מיתיבי אין מביאין תרומה לא מגורן לעיר ולא ממדבר לישוב ואם אין שם כהן שוכר פרה ומביאה מפני הפסד תרומה","שאני תרומה דטבלה ולא סגיא דלא מפריש לה","והרי מתנות דלא טבלי ותניא מקום שנהגו למלוג בעגלים לא יפשיט את הזרוע","להפשיט את הראש לא יפשיט את הלחי ואם אין שם כהן מעלין אותן בדמים ואוכלן מפני הפסד כהן","שאני מתנות כהונה דנתינה כתיבא ביה השתא דאתית להכי תרומה נמי נתינה כתיבא ביה","ואלא תעזוב יתירא למה לי","לכדתניא המפקיר את כרמו ולשחר השכים ובצרו חייב בפרט ובעוללות ובשכחה ובפאה ופטור מן המעשרות","ההוא שקא דדינרי דאתא לבי מדרשא קדים רבי אמי וזכה בהן והיכי עביד הכי והא כתיב ונתן ולא שיטול מעצמו רבי אמי נמי לעניים זכה בהן","ואיבעית אימא אדם חשוב שאני דתניא (ויקרא כא, י) והכהן הגדול מאחיו שיהא גדול מאחיו בנוי בחכמה ובעושר","אחרים אומרים מנין שאם אין לו שאחיו הכהנים מגדלין אותו תלמוד לומר והכהן הגדול מאחיו גדלהו משל אחיו:","\u0001מתני׳\u0002 איזהו הזרוע מן הפרק של ארכובה עד כף של יד והוא של נזיר וכנגדו ברגל שוק ר' יהודה אומר שוק מן הפרק של ארכובה עד סובך של רגל אי זהו לחי מן הפרק של לחי עד פיקה של גרגרת:","\u0001גמ׳\u0002 ת\"ר (דברים יח, ג) הזרוע זה זרוע ימין אתה אומר זה זרוע ימין או אינו אלא זרוע שמאל ת\"ל הזרוע","מאי תלמודא כדאמר רבא הירך המיומנת שבירך הכא נמי הזרוע המיומן שבזרוע","והלחיים למאי אתא להביא צמר שבראש כבשים ושער שבזקן תיישים והקבה למאי אתא להביא חלב שעל גבי הקבה וחלב שבתוך הקבה דאמר ר' יהושע כהנים נהגו בו עין יפה ונתנוהו לבעלים טעמא דנהגו הא לא נהגו דידיה הוא","דורשי חמורות היו אומרים הזרוע כנגד היד וכן הוא אומר (במדבר כה, ז) ויקח רומח בידו","ולחיים כנגד תפלה וכן הוא אומר (תהלים קו, ל) ויעמוד פנחס ויפלל קבה כמשמעה וכן הוא אומר (במדבר כה, ח) ואת האשה אל קבתה","ותנא מייתי לה מהכא (ויקרא ז, לב) שוק הימין אין לי אלא שוק הימין זרוע מוקדשין מנין ת\"ל (ויקרא ז, יד) תרומה זרוע חולין מנין ת\"ל תתנו:","איזהו לחי מן הפרק של לחי ועד פיקה של גרגרת: והתניא נוטלה ובית שחיטה עמה","לא קשיא הא רבנן והא רבי חנינא בן אנטיגנוס","דתניא מוגרמת פסולה העיד רבי חנינא בן אנטיגנוס על מוגרמת שהיא כשרה","איבעית אימא הא והא רבנן ומאי עמה עמה דבהמה:","\u0001הדרן עלך הזרוע והלחיים\u0002"],[[0,"ראשית הגז כו'","כל הנך כולהו לא רמיא איסורא עלייהו אלא ממונא הילכך ספיקן לקולא:"],[0,"ופדיון פטר חמור","כדפרישית מפריש טלה והוא לעצמו:"],[1,"קמה אקמה רמי עליה","מתניתא אחריתי אשכח לר\"מ דפטר בקמה של גר ספק נקצרה קודם שנתגייר ספק משנתגייר ורמייה אהא דקתני ספק לקט לקט ושני ליה בלשון בן אגרא אני שונה אותה:"],[2,"בכישר","מקום:"],[3,"אין מביאין","אין צריך ישראל לטרוח ולהביא תרומה מן הגורן לעיר ליד כהן אלא כהן הולך ומביאה:"],[3,"ואם אין שם כהן כו'","אלמא בעי לאפרושה ולאצנועה עד דמשכח כהן ה\"נ בעי לאצנועה עד דמשכח עניים:"],[4,"שאני תרומה דטבלה","אוסרת הכל עליו משום טבל לפיכך על כרחו צריך להפריש:"],[5,"למלוג בעגלים","שמולגין אותן ברותחין עם עורן ואוכלין אותן עם העור:"],[5,"אין רשאי להפשיט את הזרוע","אלא נותנו לכהן כמו שהוא בעורו:"],[6,"הראש לא יפשיט את הלחי","כדמרבינן לקמן מקרא יתירא שאף הצמר שבראש כבשים הוא חייב ליתן לו וכ\"ש העור:"],[6,"ואם אין שם כהן","לתת לו המתנות:"],[6,"מעלים אותם בדמים","שם את דמי המתנות ואוכל המתנות ונותן דמיהם לכהן הבא ראשון:"],[7,"נתינה כתיבא בהו","ועליו ליתנן לכהן:"],[8,"אלא תעזוב יתירא","דכתיב בלקט למה לי חד בקדושים תהיו וחד בשור או כשב לאו לרבויי שאפילו במקום שאין עניים שעליו להצניעם עד שימצא עניים:"],[9,"חייב בפרט ובעוללות כו'","אע\"ג דהפקר פטור מכולם דבכולהו כתיב קצירך כרמך ולא של הפקר ובכולהו תנן כל שהוא אוכל ונשמר פרט לשל הפקר להכי אהני תעזוב יתירא דכתיב בכולהו לאתויי הפקר כי האי גוונא דהדר איהו וזכה ביה. בלקט ופאה כתיב תעזוב יתירא חד בקדושים תהיו וחד בשור או כשב ופרט בכרם היינו לקט. עוללות חד בקדושים תהיו וכרמך לא תעולל וחד במשנה תורה (כד) כי תבצור כרמך לא תעולל אחריך. שכחה חד גבי שכחת אילן וחד גבי שכחת כרם דאמרינן לעיל (חולין דף קלא.) אחריך זו שכחה:"],[10,"שקא דדינרי","דינרי זהב ששלחו ממקום אחר לבני הישיבה:"],[11,"ואיבעית אימא אדם חשוב","כגון ממונה ראש ישיבה יכול לקדם ולזכות שהרי עליו לגדלו ולהעשירו אפילו משלו וכ\"ש ממאי דאתי ליה מעלמא:"],[13,"מתני' מן פרק של ארכובה","ארכובה הנמכרת עם הראש:"],[13,"עד כף של יד","עצם רחב של כתף שקורין אשפלדו\"ן:"],[13,"והוא של נזיר","וכן זרוע בשלה האמור בנזיר (במדבר ו) כך ניטלת:"],[13,"וכנגדו ברגל שוק","האמור בשלמים (ויקרא ז) נמי הוי שתי עצמות מן הפרק של ארכובה עד בוקא דאטמא דהיינו כל הירך:"],[13,"סובך של רגל","היינו פרק שבין הקולית ועצם אמצעי:"],[13,"הפרק של לחי","אצל הצדעים וחותך כלפי מטה עד פיקה של גרגרת עד שיפוי כובע שהוא פקעיתא ופתחה של קנה בית הבליעה דהיינו לחיים התחתונות עם הלשון:"],[14,"גמ' הזרוע","ונתן לכהן הזרוע:"],[15,"כדאמר רבא","בפרק גיד הנשה (לעיל חולין דף צא.) אליבא דרבי יהודה דאמר אינו נוהג אלא באחת והדעת מכרעת של ימין:"],[16,"","ה' דהלחיים למאי אתא:"],[16,"חלב של הקבה וחלב שבתוך הקבה","חלב הקרום:"],[16,"כהנים נהגו בו עין יפה","שלא ליטלו מן הבעלים. אלמא דמדאורייתא של כהנים הוא דנפקא ליה מה\"א יתירא והקבה:"],[17,"דורשי חמורות","מקראות הסתומים:"],[17,"היו אומרים","מנלן דשל ימין מהכא:"],[17,"יד","שנותנין לכהן כנגד ידו של פנחס שעל כך ניתנה לו ברית כהונת עולם וזה שכרו ואיזו יד שעושה מלחמה הוי אומר של ימין:"],[19,"זרוע המוקדשין","של איל נזיר:"],[19,"ת\"ל תתנו","תרומה לכהן:"],[19,"זרוע חולין","מתנות כהונה:"],[20,"ובית שחיטה עמה","היינו תופס בעומק הצואר באלכסון יותר מן הפיקה:"],[21,"לעולם עד הפיקה ולא קשיא","ברייתא דקרי לה בית שחיטה ר' חנינא היא דמכשיר שחיטה למעלה מבית הבליעה ומתניתין דלא קרי לה בית שחיטה רבנן היא:"],[23,"ואיבעית אימא","ברייתא נמי רבנן היא והאי עמה דקתני לאו עם הלחי אלא עם הבהמה היה נשאר בית שחיטה והלחי ניטל עם הפיקה:"]],[[0,"ראשית הגז והמתנות","תימה למאן דאית ליה לעיל (חולין דף קלב:) דמתנות טבלי ליתני נמי מתנות לחיוב קודם שהורמו ולפטור אחר שהורמו המתנות דהוו שלו כי היכי דתני בבכור בהמה טמאה לחיוב ולפטור:"],[13,"פיקה של גרגרת","היא טבעת הגדולה שעשויה עגולה כפיקה:"],[15,"הזרוע המיומנת","אפילו לרבנן דדרשי פרק גיד הנשה (לעיל חולין דף צו:) הירך דפשיט איסוריה בכוליה ירך הכא מודו דלא שייך למדרש הכי:"],[17,"דורשי חמורות","פירש בערוך בשם רב סעדיה גאון כמין המעשה דבלשון ארמי מהו חמרך מה מעשיך:"]]],[["מתני׳ \u0001ראשית\u0002 הגז נוהג בארץ ובחו\"ל בפני הבית ושלא בפני הבית בחולין אבל לא במוקדשים","חומר בזרוע ולחיים ובקבה מראשית הגז שהזרוע והלחיים והקבה נוהגין בבקר ובצאן במרובה ובמועט וראשית הגז אינו נוהג אלא ברחלות ואינו נוהג אלא במרובה","וכמה הוא מרובה ב\"ש אומרים שתי רחלות שנאמר (ישעיהו ז, כא) יחיה איש עגלת בקר ושתי צאן וב\"ה אומרים [חמש שנאמר (שמואל א כה, יח) חמש צאן עשויות","רבי דוסא בן הרכינס אומר חמש רחלות גוזזות מנה מנה ופרס חייבות בראשית הגז וחכ\"א חמש רחלות גוזזות כל שהן","וכמה נותנין לו משקל חמש סלעים ביהודה שהן עשר סלעים בגליל מלובן ולא צואי כדי לעשות ממנו בגד קטן שנאמר (דברים יח, ד) תתן לו שיהא בו כדי מתנה","לא הספיק ליתנו לו עד שצבעו פטור לבנו ולא צבעו חייב","הלוקח גז צאנו של עובד כוכבים פטור מראשית הגז הלוקח גז צאנו של חבירו אם שייר המוכר חייב לא שייר הלוקח חייב היו לו שני מינים שחופות ולבנות מכר לו שחופות אבל לא לבנות זכרים אבל לא נקבות זה נותן לעצמו וזה נותן לעצמו:","\u0001גמ׳\u0002 במוקדשין מאי טעמא לא אמר קרא (דברים יח, ד) צאנך ולא צאן הקדש","טעמא דכתב רחמנא צאנך הא לאו הכי הוה אמינא קדשים חייבים בראשית הגז הא לאו בני גיזה נינהו דכתיב (דברים טו, יט) ולא תגוז בכור צאנך","אי בקדשי מזבח הכי נמי הכא במאי עסקינן בקדשי בדק הבית","והאמר ר\"א קדשי בדק הבית אסורים בגיזה ועבודה מדרבנן סלקא דעתך אמינא הואיל ומדאורייתא בני גיזה נינהו היכא דגזז ליה ליתיב ליה","והא קדיש לה סד\"א לפרוק וליתיב ליה","והא בעי העמדה והערכה הניחא למאן דאמר קדשי בדק הבית לא היו בכלל העמדה והערכה אלא למ\"ד היו מאי איכא למימר","אמר ר' מני בר פטיש משום ר' ינאי הכא במקדיש בהמתו לבדק הבית חוץ מגיזותיה סד\"א ליגזוז וליתיב ליה אמר קרא צאנך ולא צאן של הקדש","אי הכי קדשי מזבח נמי כחשי","קדשי בדק הבית נמי כחשי דאמר חוץ מגיזה וכחישה","קדשי מזבח נמי דאמר חוץ מגיזה וכחישה אפ\"ה פשטה קדושה בכולה","ומנא תימרא דאמר ר' יוסי והלא במוקדשין האומר רגלה של זו עולה כולה עולה ואפי' לר\"מ דאמר אין כולה עולה הני מילי דאקדיש דבר שאין הנשמה תלויה בו אבל הקדיש דבר שהנשמה תלויה בו קדשה","רבא אמר במקדיש גיזה עצמה סד\"א ליגזוז וליפרוק וליתיב ליה","אמר קרא (דברים יח, ד) גז צאנך תתן לו מי שאין מחוסר אלא גזיזה ונתינה יצא זה שמחוסר גזיזה פדייה ונתינה","אלא צאנך למאי אתא לכדתניא בהמת השותפים חייב בראשית הגז ור' אלעאי פוטר מ\"ט דר' אלעאי אמר קרא צאנך ולא של שותפות","ורבנן למעוטי שותפות עובד כוכבים ור' אלעאי שותפות עובד כוכבים מנא ליה","נפקא ליה מרישא דקרא (דברים יח, ד) ראשית דגנך ולא שותפות עובד כוכבים","ורבנן ראשית (הגז) הפסיק הענין","ור' אלעאי וי\"ו הדר ערביה"],[[0,"מתני' ראשית הגז","כל הגוזז צאנו בין טלאים ובין זקנים ואפילו גוזזן מאה פעמים נותן ממנה מתנה לכהן ושיעורא מפרש לקמן מחמש גיזות שיש בכל אחד מנה ופרס היה נותן משקל חמש סלעים:"],[1,"נוהגין בבקר ובצאן","דכתיב (דברים יח) אם שור אם שה:"],[1,"ובמועט","אפילו לא שחט אלא אחת:"],[1,"אלא ברחלים","דגז צאנך כתיב ועזים לאו גז איקרו כדמפרש בגמרא:"],[3,"מנה מנה ופרס","כל אחת מנה וחצי ובציר מהכי לא חשיב גז שזו פחותה שבגיזות:"],[3,"כל שהן","בגמרא מפרש מאי היא:"],[4,"וכמה נותן לו","בגמרא מפרש אהיכא קאי:"],[4,"צואי","שלא נתלבן עדיין כולו:"],[5,"שצבעו","ישראל זה:"],[5,"פטור","דקנייה בשינוי דהוה ליה כמזיק מתנות כהונה או שאכלן:"],[5,"לבנו ולא צבעו","אין זה שינוי ואכתי בעיניה הוא:"],[6,"הלוקח גז צאנו של עובד כוכבים","במחובר:"],[6,"פטור","דגז צאנך כתיב והאי צאן לאו דידיה הוא ואצאן דידיה קפיד קרא ולאו אגיזין דידיה:"],[6,"שחופות","לא שחור ולא לבן:"],[6,"זה נותן לעצמו","בגמרא מפרש טעמא:"],[9,"גמ' בקדשי בדק הבית","דמותרין בגיזה אתא קרא למעוטינהו מחיובא דראשית הגז:"],[10,"מדרבנן","תירוצא הוא:"],[10,"היכא","דעבר אדרבנן וגזז אמינא ליחייב להכי אתא קרא:"],[11,"והא קדשה לה","והיכי תיסק אדעתין דניחייב למיתב ליה מידי דהקדש ולמה לי למעוטינהו. כל הקדוש בבעלי חיים טעון העמדה והערכה היכא דאקדיש בהמה גופה והיכי משכחת לה דניחייב דאיצטריך קרא למעוטי והא אחר שגזז אינו יכול להעמיד הגיזה:"],[12,"הניחא למ\"ד","בתמורה (דף לב:):"],[12,"קדשי בדק הבית לא היו בכלל כו'","איצטריך האי קרא דלא נימא ניפרוק וניתיב ליה:"],[13,"הכי גרסינן סלקא דעתך אמינא ליגזוז וליתיב ליה","כלומר יגזוז לכתחלה וליתיב ליה דהא גז לא הקדיש:"],[14,"אי הכי","דבחוץ מגיזתה אוקימתה חוץ מגיזתה שהוא מותר לגוזזה שהגיזה שלו מאי דוחקך לאוקומה בקדשי בדק הבית אפילו קדשי מזבח נמי ובדעבר וגזז:"],[14,"ומשני מכחש","הגיזה הניטלת מכחשת הבשר ואסור לגוזזה:"],[16,"אפילו הכי","דאמר חוץ מגיזתה קדשה נמי גיזתה דאיידי דקדושת הגוף חמורה פשטה בכל המחובר בה אבל קדושת דמים כגון קדשי בדק הבית מאי דלא אקדיש לא אקדיש:"],[17,"והלא במוקדשים","כלומר בתחלת הקדש האומר רגלה של זו עולה כולה עולה אף בתמורה כשיאמר רגלה של זו תמורה תהא כולה תמורה ופליג אדרבי מאיר דאמר אין ממירין באברין ולא אברין בשלמין ובפרק בהמה המקשה היא מפורשת:"],[17,"ואפילו לר\"מ דאמר אין כולה עולה","בפרק בהמה המקשה מייתי לה בגמרא אבל במקדיש דבר שהנשמה תלויה בו מוקמינן בתמורה דמודי ר\"מ דקדשה כולה:"],[18,"רבא אמר","לא תטרח לאוקומי מתניתין במקדיש חוץ מגיזה וכחישתה אלא במקדיש גיזה לבדה וטעמא דמתניתין לאו מגז צאנך יליף דהכא צאנך הוא אלא מדסמך נתינה לגיזה:"],[18,"סלקא דעתך אמינא ליפרוק וליתיב","קא משמע לן דאמר קרא גז תתן מי שאינו מחוסר אלא גיזה ונתינה והכא משום העמדה והערכה ליכא דכי כתיבא העמדה במקדיש בהמה עצמה כתיבא:"],[18,"","\u0003השתא דאתית להכי\u0004 לא גרסינן:"],[20,"אלא צאנך","דמשמע מיעוטא למאי אתא למעוטי שותפות עובד כוכבים לרבנן או שותפות ישראל לרבי אלעאי:"],[20,"ולא של שותפות","דרוש הכי צאנך המיוחד לך:"],[21,"למעוטי שותפות דעובד כוכבים","אבל דישראל מיוחד לך קרינא ביה הואיל ושניהם בני חיוב וכל ישראל קרוים בלשון יחיד:"],[23,"ראשית הפסיק הענין","מדלא כתבינהו בחד ראשית ש\"מ לא איתקוש הילכך איצטריך לפרושי בה מיעוטא לשותפות עובד כוכבים:"]],[[0,"","מתני' ראשית הגז:"],[11,"ליפרוק וליתיב ליה","תימה אמאן קאי אי אמאן דעבר וגזז אטו קנסא הוא דקניס ליה משום דעבר וגזז לפדותו ובעלים שהקדישו נמי אמאי מיחייבי ואי אכהן לא הול\"ל לפרוק וליתיב ונהי דהאי לא תקשי מה מרויח שפודה דמרויח שפודה בשוה פרוטה אפילו שוה מנה דמחולל:"],[12,"והא בעי העמדה והערכה","וא\"ת מה שייך העמדה והערכה בגיזה דהויא כמקדיש עצים ואבנים וי\"ל כיון שהיה מתחלה מחובר בבהמה שהיא בת העמדה והערכה צריך העמדה והערכה וא\"ת ולימא כשהעמיד והעריך ואחר כך עבר וגזז ופדה ויש לומר דבשעת פדייה בעינן העמדה והערכה:"],[18,"במקדיש גיזה עצמה","ורבי מני בר פטיש דלעיל אית ליה שפיר הך דרשא אבל רבא לית ליה דרשה דרבי מני בר פטיש דפטר מקדיש בהמה חוץ מגיזתה וכחישתה מדבעי בסמוך ואלא צאנך למאי אתא:"]]],[["ורבנן לא נכתוב רחמנא לא וי\"ו ולא ראשית","ורבי אלעאי איידי דהאי קדושת דמים והאי קדושת הגוף פסיק להו והדר ערבי להו","ואיבעית אימא שותפות עובד כוכבים בתרומה רבנן חיובי מחייבי דתניא ישראל ועובד כוכבים שלקחו שדה בשותפות טבל וחולין מעורבים זה בזה דברי רבי רבן שמעון בן גמליאל אומר של ישראל חייב ושל עובד כוכבים פטור","עד כאן לא פליגי אלא דמר סבר יש ברירה ומר סבר אין ברירה אבל שותפות דעובד כוכבים דברי הכל חייבת","ואי בעית אימא תרוייהו לר' אלעאי מצאנך נפקא","שותפות דעובד כוכבים מאי טעמא דלא מייחדא ליה לישראל נמי לא מייחדא ליה ורבנן עובד כוכבים לאו בר חיובא הוא ישראל בר חיובא הוא","אמר רבא מודה רבי אלעאי בתרומה אע\"ג דכתיב (דברים יח, ד) דגנך דידך אין דשותפות לא","כתב רחמנא תרומותיכם אלא דגנך למה לי למעוטי שותפות עובד כוכבים","חלה אע\"ג דכתיב ראשית ואיכא למימר נילף ראשית ראשית מראשית הגז מה להלן דשותפות לא אף כאן דשותפות לא כתב רחמנא (במדבר טו, כא) עריסותיכם","אלא טעמא דכתיב עריסותיכם הא לאו הכי הוה אמינא נילף ראשית ראשית מראשית הגז אדרבה נילף מתרומה","ה\"נ אלא עריסותיכם למה לי כדי עריסותיכם","פאה אע\"ג דכתיב שדך דידך אין שותפות לא כתב רחמנא (ויקרא יט, ט) ובקצרכם את קציר ארצכם אלא שדך ל\"ל למעוטי שותפות עובד כוכבים","בכורה אע\"ג דכתיב (דברים טו, יט) כל הבכור אשר יולד בבקרך ובצאנך דידך אין דשותפות לא","כתב רחמנא (דברים יב, ו) ובכורות בקרכם וצאנכם אלא וצאנך למה לי למעוטי שותפות עובד כוכבים","מזוזה אף על גב דכתיב (דברים ו, ט) ביתך דידך אין שותפות לא כתב רחמנא (דברים יא, כא) למען ירבו ימיכם וימי בניכם ואלא ביתך למאי אתא לכדרבה דאמר רבה"],[[0,"ורבנן לא לכתוב רחמנא לא וי\"ו ולא ראשית","רבנן אמרי לך אי ס\"ד איתקוש למידי לא נכתוב לא ראשית לאפסוקינהו ולא וי\"ו למהדר ערבינהו אלא ודאי אפסקינהו ולא תקשינהו להכי כי היכי דאייתר לך צאנך לשותפות ישראל אבל דגנך למעוטי שותפות עובד כוכבים מתרומה וצאנך לשותפות העובד כוכבים בגז אבל לשותפות ישראל לא אייתר קרא:"],[1,"","תרומה קדושת הגוף שאסורה לזרים וראשית הגז קדושת דמים ממונא בעלמא וקדושה לאו דוקא:"],[1,"פסיק","אורחיה לאפסקינהו והדר עריב להו למילף פטורא דשותפות דעובד כוכבים מהיקשא דתרומה והדר אייתר צאנך למיפטר שותפות דישראל:"],[2,"ואיבעית אימא שותפות עובד כוכבים בתרומה רבנן חיובי מחייבי","חלקו של ישראל ולא מצי למפטר שותפות דעובד כוכבים בראשית הגז בהיקשא דתרומה הילכך צאנך למעוטי שותפות עובד כוכבים אתא ודגנך למעוטי דיגון עובד כוכבים כגון עובד כוכבים שלקח שדה של ישראל ומירחה הלוקח אותה תבואה מן העובד כוכבים פטור מלעשר ואף על פי שגדלה בשדה של ישראל כדאמרינן במנחות בפרק רבי ישמעאל (מנחות דף סז.) מירוח העובד כוכבים פוטר אי נמי דגנך ולא דגן עובד כוכבים ולאשמועינן דיש קנין לעובד כוכבים בארץ ישראל להפקיע מיד מעשר וחלקו של עובד כוכבים פטור שאם חזר ומכרו לישראל אינו חייב לעשר אבל חלקו של ישראל חייב ואע\"ג דמצאנך משמע להו ולא שותפות עובד כוכבים לא משמע להו מדגנך למעוטי של שותפות עובד כוכבים דדגן כמאן דפליג דמי שהרי חולקין אותה במדה וקרינא ביה דגנך בחלקו של ישראל אבל צאן כל בהמה ובהמה יש לעובד כוכבים חלק בה ולא קרינא בחדא מינייהו צאנך:"],[2,"שלקחו שדה","שקנו שדה בשותפות:"],[2,"טבל וחולין מעורבין זה בזה","ואפילו לאחר שחלקו לא אמרינן יש ברירה וחלקו של עובד כוכבים הלך לו וזה חלק המגיע לישראל וטבל גמור הוא אלא אין ברירה וגם זה שנשאר חציו טבל וחציו חולין דיש קנין לעובד כוכבים בא\"י להפקיע חלקו מיד מעשר. ואני שמעתי שאין לו תקנה לפי שאם בא להפריש נמצא מפריש מן הפטור על החיוב. ולי נראה שיש לו תקנה בשני צדדין אם יש לו טבל ממקום אחר מפריש על זה לפי חציו שאין חייב אלא חציו ואם אין לו טבל אחר מפריש מיניה וביה לפי כולו כגון אם יש לו עשרים מפריש שנים מהן שאם אין מפריש אלא אחד לא נפטר לפי שזה שהפריש יש חציו שאין שם מעשר חל עליו לפי שהוא פטור ועומד אבל כשמפריש שנים הרי השם חל על האחד ופוטר את העשרה המחוייבין והא ליכא למימר דילמא שניהם המופרשין בחלקו של עובד כוכבים גדלו ואין שם מעשר חל עליהם דתניא בגמרא דראש השנה (דף יב:) גבי חדש וישן המעורבין דקי\"ל אין תורמין מזה על זה וקתני צובר את גרנו לתוכו ונמצא תורם מן החדש שבו על החדש שבו ומן הישן שבו על הישן שבו וכי היכי דפריש חדש וישן בחולין איכא נמי חדש וישן במעשר הכא נמי נמצא תורם מן החיוב שבו על החיוב שבו ומן הפטור שבו על הפטור שבו ואפילו למאן דפליג עליה דההוא הכא מודי דהתם הוא דאיכא למימר אין בילה לא נבללו יפה ושמא אין חדש במעשר לפי חשבון הנותר בחולין ואין ישן במעשר לפי חשבון הנותר בחולין אבל הכא יש בילה דהא בכל חטה וחטה יש לעובד כוכבים ולישראל חלק כיון דאין ברירה וכי אפריש מיניה וביה יש במעשר מן החיוב כפי החיוב ומן הפטור כפי הפטור. ובתוספתא דדמאי (פרק ה הי\"ד) מצאתי דטבל וחולין שנתערבו אם יש לו פרנסה ממקום אחר מוציא לפי חשבון כלומר מפריש ממקום אחר לפי חשבון טבל זה המעורב ואם לאו נוטל מן החולין כפי תרומת מעשר שבטבל ואיני יודע מהו. ורבי ורשב\"ג הכי פליגי רבי סבר אם יש לו טבל אחר מפריש על זה לפי חציו ואם הפריש לפי כולו דנמצא מרבה במעשרות ומעשרותיו מקולקלים וזה מתוקן ועוד נ\"מ שאין מפרישים מזה על טבל אחר ור\"ש [ב\"ג] סבר יש ברירה וכיון שחלקו הרי חלקו של ישראל כולו חייב ואפילו הוא בא להפריש עליו ממקום אחר מפריש לפי כולו והשם חל על מעשרותיו ומתוקנים הם ואם רצה להפריש מזה על מקום אחר מותר:"],[4,"ואי בעית אימא","לא תדחק למימר הדר ערביה דתרוייהו בין שותפות עובד כוכבים בין שותפות ישראל לרבי אלעאי מצאנך נפקי דבעינן מיוחד לך ולא שותפות לא שנא דעובד כוכבים ולא שנא דישראל:"],[5,"ישראל בר חיובא הוא","וכל ישראל נקראין בלשון יחיד ולא מיוחד בעינן ובלבד שאוכל לקרוא בה צאן של ישראל:"],[6,"אמר רבא","אע\"פ דפטר ר' אלעאי בשותפות דראשית הגז מודה הוא בכל הני דאמר לקמיה כל חד וחד כדמפרש טעמא:"],[7,"תרומותיכם","משמע לשנים:"],[9,"אדרבה לילף מתרומה","לחיובא דהא בתרומה נמי כתיב ראשית ושותפות חייבת בה וקולא וחומרא לחומרא מקשינן (יבמות דף ח:):"],[10,"למה לי","קרא עריסותיכם לחיובא בשותפות:"],[10,"כדי עריסותיכם","במדבר ניתנה להם תורה ושם נאמר להם כדי עריסותיכם של עכשיו חייב בחלה וכמה עיסת מדבר עומר לגלגלת והעומר עשירית האיפה והחשבון עולה לחמשה לוגין צפוריים שהן שבעה רבעים ועוד מדבריות שהן מ\"ג ביצים וחומש ביצה כדאמרינן בעירובין בפ' כיצד משתתפין (עירובין דף פג:). איפה שלש סאין סאה ששת קבין הרי איפה י\"ח קבין קב ד' לוגין הרי איפה ע\"ב לוגין עשירית דידה כמה הוה שבעה לוגין לשבעים לוג ולשני לוגין שהן י\"ב ביצים עשירית שלהן ביצה וחומש הרי שבעת לוגין וביצה וחומש ביצה והלוג ששה ביצים הרי מ\"ג ביצים וחומש:"],[11,"ארצכם","של שנים הוא אומר:"],[12,"בקרך וצאנך","כל הבכור וגו' הרי כתיב ובכורות בקרכם וצאנכם אפילו לשנים:"]],[[0,"ורבנן לא לכתוב לא וי\"ו ולא ראשית","וא\"ת לרבנן נמי תקשי לא לכתוב צאנך ולא ראשית ואנא ילפינא מדגנך דשותפות עובד כוכבים פטור מראשית הגז דמדאמרי רבנן לעיל ראשית הפסיק הענין משמע הא לאו ראשית הוה ילפינן מרישיה דקרא וי\"ל דרבנן לדבריו דר' אלעאי קא אמרי לדבריך דבעי למילף מרישיה דקרא הא ראשית הפסיק הענין:"],[2,"ואב\"א שותפות עובד כוכבים בתרומה רבנן חיובי מחייבי","מתוך פ\"ה אחרון משמע דמדגנך ליכא למעוטי שותפות עובד כוכבים דסברא הוא לחלק בין של עובד כוכבים לגמרי בין של שותפות אבל בגז אין סברא לחלק שבכל בהמה ובהמה יש לעובד כוכבים חלק בה ולא קרינא בחדא מינייהו צאנך ותימה דא\"כ מה איצטריך לרבנן קרא דצאנך הא מדגנך דרשינן ולא של עובד כוכבים וילפינן בגז דשל עובד כוכבים פטור וכיון דשל עובד כוכבים פטור של שותפות נמי פטור כדפרישית שאין סברא לחלק צ\"ל דלאו סברא הוא כלל דאפילו ידעינן דשל עובד כוכבים פטור מ\"מ לא ידעינן דשל שותפות פטור בשותפות עובד כוכבים והשתא מדגנך ילפינן בגז דשל עובד כוכבים פטור ואיצטריך צאנך לשל שותפות אך לפי' קמא בקונטרס דדגנך אתא ולא דיגון עובד כוכבים צ\"ל האי סברא דאי לא תימא הכי לרבנן מנא להו דשותפות עובד כוכבים פוטר בראשית הגז אימא צאנך למעוטי של עובד כוכבים אבל שותפות עובד כוכבים חייב:"],[6,"אמר רבא ומודה רבי אלעאי בתרומה","נראה דסבר כלישנא בתרא דאין סברא למעט של עובד כוכבים טפי משל ישראל דללישנא קמא דלית לן למעוטי מחד קרא אלא שותפות עובד כוכבים ולא שותפות ישראל לא הוה צריך בכל הנהו דמייתי קרא לרבות שותפות ישראל:"]]],[["דרך ביאתך מן הימין","מעשר אע\"ג דכתיב מעשר דגנך דילך אין דשותפות לא כתב רחמנא מעשרותיכם אלא מעשר דגנך למאי אתא למעוטי שותפות דעובד כוכבים","מתנות אע\"ג דכתב רחמנא ונתן","איכא למימר יליף נתינה נתינה מראשית הגז מה להלן דשותפות לא אף כאן דשותפות לא כתב רחמנא (דברים יח, ג) מאת זובחי הזבח","אלא טעמא דכתב רחמנא מאת זובחי הזבח הא לאו הכי הוה אמינא לילף מראשית הגז אדרבה נילף מתרומה","אין ה\"נ מאת זובחי הזבח למה לי לכדרבא דאמר רבא הדין עם הטבח","בכורים אע\"ג דכתיב (דברים כו, ב) ארצך דידך אין דשותפות לא","כתב רחמנא (במדבר יח, יג) בכורי כל אשר בארצך אלא ארצך למה לי למעוטי חוצה לארץ","ציצית אע\"ג דכתב רחמנא (דברים כב, יב) כסותך דידך אין דשותפות לא","כתב רחמנא (במדבר טו, לח) על כנפי בגדיהם לדורותם ואלא כסותך למה לי לכדרב יהודה דאמר רב יהודה טלית שאולה פטורה מן הציצית כל שלשים יום","מעקה אע\"ג דכתב רחמנא (דברים כב, ח) לגגך דידך אין דשותפות לא","כתב רחמנא (דברים כב, ח) כי יפול הנופל ממנו אלא גגך למאי אתא למעוטי בתי כנסיות ובתי מדרשות","אמר רב ביבי בר אביי ליתנהו להני כללי דתניא בהמת השותפין חייבת בבכורה ור' אלעאי פוטרה","מאי טעמא דר' אלעאי דכתיב (דברים טו, יט) בקרך וצאנך והא כתיב (דברים יב, ו) בקרכם וצאנכם דכולהו ישראל","אמר רב חנינא מסורא ליתנהו להני כללי דתניא בהמת השותפין חייבת במתנות ור' אלעאי פוטר מאי טעמא יליף נתינה נתינה מראשית הגז מה להלן דשותפות לא אף כאן דשותפות לא","ואי ס\"ד בתרומה מיחייב נילף נתינה נתינה מתרומה אלא ש\"מ בתרומה נמי פוטר","אי מה תרומה בארץ אין בחוצה לארץ לא אף מתנות בארץ אין בחוצה לארץ לא אמר רבי יוסי מנהרביל אין והתניא רבי אלעאי אומר מתנות אין נוהגין אלא בארץ וכן היה רבי אלעאי אומר ראשית הגז אין נוהג אלא בארץ","מאי טעמא דר' אלעאי אמר רבא יליף נתינה נתינה מתרומה מה תרומה בארץ אין בחוצה לארץ לא אף ראשית הגז בארץ אין בחוצה לארץ לא","אמר ליה אביי אי מה תרומה טובלת אף ראשית הגז טובלת א\"ל אמר קרא (דברים יח, ד) וראשית גז צאנך תתן לו אין לך בו אלא מראשיתו ואילך","אי מה תרומה חייבים עליה מיתה וחומש אף ראשית הגז חייבים עליו מיתה וחומש","אמר קרא (ויקרא כב, ט) ומתו בו ויסף עליו עליו ולא על ראשית הגז בו ולא בראשית הגז","אי מה תרומה ראשון ושני אחריה אף ראשית הגז ראשון ושני אחריה אמר קרא ראשית אין לך בו אלא ראשית בלבד","אי מה תרומה מחדש על הישן לא אף ראשית הגז מחדש על הישן לא אין","והתניא היו לו שתי רחלות גזז והניח גזז והניח שנים ושלשה שנים אין מצטרפות הא חמש מצטרפות","והתניא אין מצטרפות אלא ש\"מ הא דר' אלעאי והא דרבנן","אי מה תרומה גדל בחיוב חייב גדל בפטור פטור אף ראשית הגז נמי גדל בחיוב חייב בפטור פטור","וגבי תרומה מנלן דתניא ישראל שלקח שדה בסוריא מעובד כוכבים עד שלא הביאה שליש חייב משהביאה שליש ר\"ע מחייב בתוספת וחכמים פוטרין","וכי תימא הכי נמי והתנן הלוקח גז צאן עובד כוכבים פטור מראשית הגז הא צאנו לגזוז חייב מתני'"],[[0,"דרך ביאתך","לבית אתה קובע מזוזה וכשהוא נכנס לביתו רגליה דימינא עייל ברישא נמצא שהימין בכניסה הוא דרך ביאה:"],[2,"מתנות","הזרוע והלחיים והקבה:"],[3,"זובחי","שנים משמע:"],[4,"אדרבה נילף נתינה מתרומה","ולא תבעי קרא דהא קולא וחומרא לחומרא מקשינן:"],[5,"הדין עם הטבח","בפירקין דלעיל וזובחי אורחיה דקרא הוא:"],[6,"ארצך","אשר תביא מארצך ארצך משמע מיעוטא ארצכם לא משמע מיעוטא כולי האי ולא ממעטא חוצה לארץ מיניה דמשמע כל מקום שיש להם ארץ אבל ארצך משמע המיוחדת לך ולא לעובדי כוכבים:"],[11,"כי יפול הנופל","כל שראוי ליפול הימנו ואפילו בשותפות:"],[11,"בתי כנסיות","שאין חלק לאחד מהן בו שאף לבני עבר הים הוא ועוד שאינו בית דירה:"],[12,"ליתנהו להני כללי","דאמר רבא דמודי ר' אלעאי בכל הני דהא תניא דפליג ר' אלעאי בבכורה ולא מרבי לה מבקרכם וצאנכם:"],[14,"ואמר ר' חנינא מסורא ליתנהו להני כללי","דרבא דהא תניא דפליג רבי אלעאי במתנות ומדפטר במתנות על כרחך פטר נמי בתרומה דאי ס\"ד בתרומה מחייב היכי פטר במתנות לייתינהו לחיובא מתרומה הואיל וגמיר גזירה שוה דנתינה נתינה מסתברא דהא אגמרוה דלחומרא אית לן למידן:"],[15,"אלא ש\"מ בתרומה נמי פטור","דדייק דגנך והדר יליף מתנות או מתרומה או מראשית הגז בנתינה נתינה:"],[16,"אי מה","כיון דמתרומה יליף רבי אלעאי לראשית הגז דאמרן לעיל שותפות דעובד כוכבים נפקא ליה מרישיה דקרא אי מה תרומה בחו\"ל לא אף ראשית הגז בחו\"ל לא דבפ\"ק דקדושין (דף לו:) קי\"ל כל מצוה שאינה תלויה בארץ נוהגת בין בארץ בין בחו\"ל דיליף מעבודת כוכבים שהיא חובת הגוף ונוהגת בכל מקום אבל חובת קרקע אינה נוהגת אלא בארץ:"],[16,"מנהרביל","שם מקום:"],[16,"אין","ודאי:"],[16,"והתניא","בניחותא:"],[18,"תרומה טובלת","אוסרת משום טבל דכתיב אשר ירימו בעתידים ליתרם הכתוב מדבר באלו הן הנשרפין (סנהדרין דף פג.):"],[18,"אין לך בו אלא מראשיתו ואילך","משהופרש ונעשה ראשית היא שלו אבל מעיקרא אין לו אלא שם אחד דהאי ראשית קרא יתירא הוא ואראשית דלעיל סמיך והוה ליה למכתב וגז צאנך:"],[19,"מיתה","זר האוכלה במזיד:"],[19,"חומש","בשוגג:"],[21,"ראשון ושני","מעשר ראשון ומעשר שני:"],[21,"אין לך אלא ראשיתו","אין לך נתינה אחרת להפריש ממנו מדלא כתב ומגז צאנך ש\"מ מתנה ראשונה בלבד אתא ראשית לאשמועי':"],[22,"תרומה מחדש על הישן לא","דכתיב היוצא השדה שנה שנה (דברים יד):"],[23,"היו לו שתי רחלות גזז","שנה זו והניח:"],[23,"גזז","שניה והניח עד שהיו לו חמש גיזים אין מצטרפות דאגיזים של חמש צאן קפיד רחמנא והא לית ליה:"],[23,"הא חמש מצטרפות","אם היו לו חמש צאן וגוזז השתים בשנה זו ושלש בשנה שניה דהשתא איכא גיזים של חמש צאן מצטרפות ואף על גב דחדש וישן הוא:"],[24,"והתניא","אידך דאפילו חמש אין מצטרפות קשיין אהדדי:"],[24,"אלא לאו שמע מינה","בהא נמי פליגי רבי אלעאי ורבנן לרבי אלעאי דמקיש גז לתרומה אין מצטרפות ולרבנן מצטרפות. כל הני קושייתא לרבי אלעאי:"],[25,"הגדל בחיוב","כגון ישראל שלקח שדה מן העובד כוכבים כדמפרש לקמיה:"],[25,"הגדל בפטור","ביד עובד כוכבים:"],[25,"בחיוב","לאחר שבאו ביד ישראל:"],[26,"בסוריא","ארם צובה שכבשה דוד ולא שמיה כבוש ולא חלה בה קדושת הארץ וקלה קדושתה ויש קנין לעובד כוכבים להפקיע מיד מעשר לפיכך אין ישראל חייב לעשר אלא על התוספת השני שלישים שגדלו אצלו טבל וחולין מעורבין אבל בארץ ישראל מעשר על הכל שאין קנין לעובד כוכבים בה להפקיע מן המעשר וחכמים פוטרין דכיון שהביאה שליש ביד עובד כוכבים כאילו נגמרה כולה בידו דקיימא לן (ר\"ה יב: יג.) תבואה בתר שליש אזלא:"],[27,"וכי תימא הכי נמי","דהגדל ביד עובד כוכבים פטור מראשית הגז אפילו בא ליד ישראל:"],[27,"הלוקח גז צאנו של עובד כוכבים","קודם שנגזזה:"],[27,"פטור מראשית הגז","דצאנך בעינן ולא גיזותיך והכא לאו צאנו דישראל הוא:"],[27,"הא צאנו לגזוז","לקח וקנה עדרו של עובד כוכבים כשהיא עומדת לגזוז הואיל והכל שלו וקרינא ביה צאנך:"],[27,"חייב","ואף על פי שגדלו הגיזים אצל עובד כוכבים:"]],[[0,"ביתך דרך ביאתך","תימה אמאי לא אמר שותפות דעובד כוכבים כדקאמר בכל הני דלעיל:"],[7,"אלא ארצך ל\"ל למעוטי חו\"ל","אע\"ג דמצוה התלויה בארץ היא מכל מקום אצטריך למעוטי משום דאתקש לבשר בחלב בחד קרא. רשב\"ם:"],[19,"","אי מה תרומה חייבין עליה מיתה וחומש כו'. ואע\"ג דבראשית הגז לא שייכא ביה אכילה ואין בתרומה חומש אלא באכילתה הנאת ראשית היא אכילתה:"]]],[["דלא כר' אלעאי","אי מה תרומה ממין על שאינו מינו לא אף ראשית הגז ממין על שאינו מינו לא","וגבי תרומה מנלן דתניא היו לו שני מיני תאנים שחורות ולבנות וכן שני מיני חטין אין תורמים ומעשרים מזה על זה ר' יצחק אומר משום ר' אלעאי ב\"ש אומרים אין תורמין וב\"ה אומרים תורמין אף ראשית הגז ממין על שאינו מינו לא","אין והתנן היו לו ב' מינים שחופות ולבנות מכר לו שחופות אבל לא לבנות זה נותן לעצמו וזה נותן לעצמו","אלא מעתה סיפא דקתני זכרים אבל לא נקבות זה נותן לעצמו וזה נותן לעצמו הכי נמי משום דתרי מיני נינהו","אלא עצה טובה קמ\"ל דליתיב ליה מהאי דרכיך ומהאי דאשון הכא נמי עצה טובה קמ\"ל דליתיב להו מתרוייהו","הא אוקימנא למתניתין דלא כר' אלעאי","אי מה תרומה בעינן ראשית ששיריה ניכרין אף ראשית הגז ששיריה ניכרין אין","והתנן האומר כל גרני תרומה וכל עיסתי חלה לא אמר כלום הא כל גזיי ראשית דבריו קיימין ותניא אידך לא אמר כלום","אלא לאו שמע מינה הא רבי אלעאי והא רבנן שמע מינה","אמר רב נחמן בר יצחק האידנא נהוג עלמא כהני תלת סבי כר' אלעאי בראשית הגז דתניא רבי אלעאי אומר ראשית הגז אינו נוהג אלא בארץ","וכר' יהודה בן בתירה בדברי תורה דתניא ר' יהודה בן בתירה אומר אין דברי תורה מקבלין טומאה","וכר' יאשיה בכלאים דתניא רבי יאשיה אומר לעולם אין חייב עד שיזרע חטה ושעורה וחרצן במפולת יד:","חומר בזרוע [וכו']: וליתני חומר בראשית הגז שנוהג בטרפות מה שאין כן במתנות","אמר רבינא הא מני ר' שמעון היא דתניא ר' שמעון פוטר את הטרפות מראשית הגז מאי טעמא דר' שמעון יליף נתינה נתינה ממתנות מה מתנות טרפה לא אף ראשית הגז נמי טרפה לא","ואי יליף נתינה נתינה ממתנות לילף נתינה נתינה מתרומה מה תרומה בארץ אין בחו\"ל לא אף ראשית הגז נמי בארץ אין בחו\"ל לא אלמה תנן ראשית הגז נוהג בארץ ובחוצה לארץ","אלא היינו טעמא דר\"ש דיליף צאן צאן ממעשר מה מעשר טרפה לא אף ראשית הגז טרפה לא","והתם מנלן דכתיב (ויקרא כז, לב) כל אשר יעבור תחת השבט פרט לטרפה שאינה עוברת ולילף צאן צאן מבכור מה בכור אפי' טרפה אף ראשית הגז אפי' טרפה","מסתברא ממעשר הוה ליה למילף שכן זכרים טמאין","במרובין מרחם","אדם פשוט לפני הדבור","אדרבה מבכור הוה ליה למילף שכן יתום שלקחו","בשותפות נתנו בפני כהן"],[[0,"דלא כר' אלעאי","דמקיש גז לתרומה:"],[1,"ממין על שאינו מינו","כגון שחורות ולבנות ואע\"ג דחד פירא הוא:"],[2,"וב\"ה אומרים תורמין","דכולו מין תאנים ות\"ק פליג אדרבי יצחק ואמר לא נחלקו ב\"ה בדבר זה דתרי מיני נינהו:"],[3,"שחופות","פלנ\"ש:"],[3,"מכר לו","ישראל לישראל:"],[3,"זה נותן לעצמו וזה נותן לעצמו","הואיל ולא שייר לעצמו מאותו המין כלום אין עליו להפריש על אותן גיזים שמכר ואע\"פ שהצאן לא מכרום על הלוקח להפריש שלקח ממתנות הכהן אלמא תרי מיני נינהו ואין מפריש מזה על זה דאי מפרשי הוה ליה שיורא גבי מוכר ותנן לקח גז צאנו של חבירו אם שייר המוכר חייב:"],[4,"","סיפא דקתני נמי מכר זכרים אבל לא נקבות זה נותן לעצמו כו':"],[4,"ה\"נ דתרי מיני נינהו","ולא הוי שיורא:"],[5,"אלא","ודאי שיורא הוא ואמוכר רמיא למיתב כולהו והא דקתני זה נותן לעצמו וזה נותן לעצמו עצה טובה קמ\"ל אשמעינן תנא למוכר שלא יתן לו מן הנקבות המשומרות לו על הזכרים שמכר משום דהאי דזכרים אשון קשה והאי דנקבות רכיך לפיכך יקנה מן הלוקח כדי ראשית הגז של זכרים מצמר הזכרים:"],[5,"ה\"נ","גבי שחופות ולבנות משום עצה טובה הוא דגיזת הלבנות טובה משל שחופות ויקנה מן הלוקח כשיעור השחופות ויתן לו לכהן:"],[7,"ששיריה נכרין","דאם אמר כל גרני תרומה לא אמר כלום:"],[8,"אין והתנן","בניחותא:"],[8,"","ה\"ג ותניא אידך לא אמר כלום:"],[10,"כר' אלעאי בראשית הגז","וה\"ה למתנות:"],[11,"אין דברי תורה מקבלין טומאה","במסכת ברכות דקתני גבי בעל קרי דצריך טבילה לדברי תורה:"],[12,"חטה שעורה וחרצן","שלשתן יחד כדאמר באותו ואת בנו הזורע כלאים לוקה ואוקימנא לאפוקי מדרבי יאשיה:"],[13,"חומר בזרוע כו'","כדפרישית לה במתניתין:"],[13,"","טרפה אינה בכלל מתנות דכתיב תתנו לו ולא לכלבו:"],[15,"ואי יליף","תנא דידן נתינה נתינה לילף כו' דהא מתני' כר' שמעון אוקימתא:"],[16,"ממעשר","כל מעשר בקר וצאן:"],[17,"יש טרפה שאינה עוברת תחת השבט","כגון נחתכו רגליה מן הארכובה ולמעלה ומינה יליף שאר טרפות:"],[17,"","בבכור קדוש אפילו טרפה ובעי קבורה דהא קדישתיה רחם:"],[18,"","מעשר וראשית הגז לא בעינן זכרים ואין נוהגים בטמאים אבל בכור אינו אלא זכר ונוהג בחמור. מעשר וראשית הגז אינו אלא במרובים מעשר בעשרה ראשית הגז בחמש. ואינן קדושים מרחם ואין נוהגים באדם אבל בכור נוהג ביחיד וקדוש מרחם ונוהג באדם. מעשר וגז אינן נוהגים אלא בפשוטין ואינן לפני הדבור אבל בכורות קדשו במצרים:"],[21,"ה\"ג אדרבה מבכור הוה ליה למילף שכן יתום שלקחו בשותפות נתנו בפני כהן בקדושה ובמכירה והנך נפישין","בכור וראשית הגז נוהגין ביתום אף על פי שמתה אמו קודם לידתו כגון זה פירש למיתה וזה פירש לחיים אבל מעשר לא דגמר תחת תחת מקדשים דכתיב תחת אמו פרט ליתום אבל בכור קדוש ואפילו יתום וירעה עד שיסתאב ויאכל במומו לכהן. בכור וגז נוהגים בלקוח ובשותפות אבל לקוח פטור מן המעשר וכן השותפות דכתיב יהיה לך ולא של שותפות (בכורות דף נו:) וכן שנתנו לו במתנה במסכת בכורות בפ' בתרא (דף נה:):"],[22,"בפני","בכור וגז נוהגים אף שלא בפני הבית אבל מעשר לא כדמפרש בגמ' דבכורות בפרק בתרא (דף נג.) גזרה משום לקוח ומשום יתום. בכור וגז ממתנות כהונה הן ולא מעשר דנאכל הוא לבעלים כשלמים:"]],[[7,"אף ראשית הגז ששיריה נכרין","תימה מנלן דבעינן ששיריה נכרין אי מדכתיב ראשית בראשית הגז נמי כתיב ראשית ומה צריך למילף מתרומה ויש לומר דהא דבעינן בתרומה שיריה נכרים משום דילפינן תרומה מחלה דחלה נקראת תרומה ובחלה כתיב מראשית דמשמע ולא כל ראשית:"],[10,"כרבי אלעאי בראשית הגז","וה\"ה במתנות כדפי' בקונט' אע\"ג דכולהו אמוראי בפרק הזרוע (לעיל חולין דף קלב.) סברי שנוהג בחו\"ל דהוו יהבי מתנתא בבבל אפילו הכי הלכה כר' אלעאי וה\"נ קאמר כרבי יאשיה בכלאים ורוב אמוראין לית להו דר' יאשיה כדמוכח בפ' תולין (שבת דף קלט.) גבי כשותא בכרמא וכן נמי הא דקאמר כר' יהודה בן בתירא בדברי תורה וטובא אמוראי ותנאי סברי בפרק מי שמתו (ברכות דף כב.) דבעל קרי אסור בדברי תורה וא\"ת דרב נחמן בר יצחק קאמר הכא דנהוג עלמא כרבי אלעאי וה\"ה במתנות ובפ' הזרוע (לעיל חולין דף קלב:) אמר דרב נחמן בר יצחק קניס גלימא ושמא קודם דנהוג הוה קניס גלימא פי' רב האי גאון דהא דאמר בפסחים (דף ז:) כל המצות כולן מברך עליהן עובר לעשייתן חוץ מן הטבילה היינו בטבילת גר דלא הוי ישראל אלא כשטבל ולא מצי למימר וצונו אבל בשאר טבילות אף על פי שהוא טמא מברך דנהוג עלמא כרבי יהודה בן בתירא בדברי תורה וי\"מ דאכל טבילות קאמר דאע\"ג דנהוג עלמא כר' יהודה בן בתירא הרבה מהם היו מחמירין לטבול:"],[13,"שהמתנות נוהנות בין במרובה בין במועט כו'","וא\"ת וליתני נמי הא דתניא לעיל לקח גז צאנו של עובד כוכבים פטור זה חומר בזרוע ולחיים מראשית הגז וי\"ל דלא תני אלא דברים שזה נוהג וזה אין נוהג אבל זה פטור וזה חייב לא קתני:"],[17,"פרט לטרפה שאינה עוברת","תימה מן הארכובה ולמטה נמי אינה עוברת ושמא דאין הכי נמי דאין נכנסת לדיר להתעשר ודוחק:"],[17,"לילף צאן צאן מבכור","וא\"ת א\"כ ג\"ש ל\"ל דבלא ג\"ש ממילא ידעינן דראשית הגז נוהג בטרפה דמהיכא תיתי למעט וי\"ל דצאן לא הויא ג\"ש אלא גילוי מילתא מה צאן זה דינו בכך אף צאן זה דינו בכך דבדלא צאן לא אפשר שלא לכותבו דאיצטריך לגופיה:"],[21,"שכן יתום","תימה דהיא גופה נילף שלא' ינהוג יתום בראשית הגז בבכור ה\"מ למימר נמי שכן צאנך מצאנך דבמעשר כתיב וכל מעשר בקר וצאן:"],[22,"לפני","בקונט' מגיה וגרס בפני ופי' בפני הבית משא\"כ במעשר שבטלו וקשה וכי מפני שבטל מדרבנן יש לבטל ג\"ש אלא לפני גרסינן בכל הספרים ופירוש שמעשר מקודש לפניו ולאחריו משא\"כ בבכור וראשית הגז:"]]],[["בקדושה ומכירה והנך נפישין","פשוט מפשוט עדיף ליה:","ראשית הגז אינו נוהג אלא ברחלים: מנא הני מילי אמר רב חסדא אתיא גיזה גיזה כתיב הכא (דברים יח, ד) ראשית גז צאנך תתן לו וכתיב התם (איוב לא, כ) ומגז כבשי יתחמם מה להלן כבשים אף כאן כבשים","ונילף גיזה גיזה מבכור דתניא (דברים טו, יט) לא תעבוד בבכור שורך ולא תגוז בכור צאנך אין לי אלא שור בעבודה וצאן בגיזה","מנין ליתן האמור של זה בזה ואת האמור של זה בזה ת\"ל לא תעבוד ולא תגוז","אמר קרא (דברים יח, ד) תתן לו ולא לשקו","אלא מעתה נוצה של עזים ליחייב בעינן גיזה וליכא","מאן שמעת ליה האי סברא ר' יוסי הא מודי ר' יוסי במידי דאורחיה","אלא כדאמר ר' יהושע בן לוי (דברים יח, ה) לעמוד לשרת דבר הראוי לשירות הכא נמי דבר הראוי לשירות","אלא גיזה גיזה למאי אתא לכדתנא דבי ר' ישמעאל דתנא דבי ר' ישמעאל כבשים שצמרן קשה פטורים מראשית הגז שנאמר ומגז כבשי יתחמם","תני חדא גוזז את העזים ושוטף את הרחלים פטור ותניא אידך הגוזז את העזים פטור ושוטף את הרחלים חייב לא קשיא הא רבנן והא ר' יוסי","דתניא (ויקרא יט, ט) לקט קצירך ולא לקט קיטוף ר' יוסי אומר אין לקט אלא הבא מחמת קציר","ר' יוסי היינו ת\"ק כולה ר' יוסי היא והכי קתני שר' יוסי אומר אין לקט אלא הבא מחמת קציר","א\"ל רב אחא בריה דרבא לרב אשי מודה ר' יוסי במידי דאורחיה דתניא ר' יוסי אומר קציר אין לי אלא קציר עוקר מנין","ת\"ל (ויקרא יט, ט) לקצור תולש מנין ת\"ל (ויקרא כג, כב) בקוצרך","אמר ליה רבינא לרב אשי אף אנן נמי תנינא מלבנות בצלים שבין הירק ר' יוסי אומר פאה מכל אחד ואחד וחכמים אומרים מאחת על הכל:","וכמה הוא מרובה: בשלמא לב\"ש תרתי נמי איקרו צאן אלא לב\"ה מ\"ט","אמר רב כהנא אמר קרא (שמואל א כה, יח) עשויות שעושות ב' מצות ראשית הגז ומתנות אימא בכורה ומתנות","בכורה חדא מי לא מיחייבא ולטעמיך מתנות חדא מי לא מיחייבא אלא אמר רב אשי עשויות שמעשות את בעליהן ואומרות לו קום עשה מצוה","תניא דבי רבי ישמעאל בר' יוסי אומר משום אביו ארבע שנאמר (שמות כא, לז) וארבע צאן תחת השה","תניא אמר רבי אלמלא דבריהן דברי תורה ודברי בריבי קבלה אנן דברי בריבי שומעין וכל שכן שדבריהם דברי קבלה ודברי בריבי דברי תורה","והאמר מר אין הכרעה שלישית מכרעת"],[[0,"בקדושה","בכור אינו צריך להקדיש דקדושתו מרחם וגז נמי אין צריך להקדיש דאין קדושה חלה עליו אבל מעשר מקדישו בשבט. לישנא אחרינא אמרי ליה בקדושה בכור וגז נכסי כהן לקדש בו את האשה כדתניא בגמרא דארבעה אבות (ב\"ק דף יג.) בכור מוכרין אותו תם ובעל מום חי ושחוט ומקדשין בו את האשה אבל מעשר אינו נכסי בעלים לקדש בו את האשה דהא כתיב ביה לא ימכר ולא יגאל ולאו מלתא היא דאפ\"ה ממון בעלים הוא ומקדשין בו דתנן (קדושין דף נב:) המקדש בחלקו בין בקדשים קלים כו' ואמרי' טעמא דלאחר שחיטה לאו דידיה הוא דמשלחן גבוה קא זכו אבל מחיים דידיה הוא:"],[0,"ומכירה","בכור יכול כהן למוכרו וכן גז אבל מעשר אינו נמכר דתנן במסכת בכורות (דף לב.) (בבכור) [במעשר] נאמר לא יגאל ואינו נמכר לא חי ולא שחוט אלא אם כן הוי של יתומין:"],[0,"והנך נפישין","הנך דבכור נפישין ולילף מיניה:"],[3,"ונילף גיזה מבכור","דאפילו בשור אקרי גיזה ונימא מה גיזה דהתם אפילו דשור הכא נמי אפילו דשור:"],[5,"לו","למלבוש ולא לשקו וגיזת שורו אין ראויה אלא לשק:"],[6,"","להכי קרי ליה נוצה שאין דרך לגוזזן אלא לתולשן כנוצה של עוף:"],[6,"ליחייב","דהא ראוי לאדם לבגדים נאים:"],[6,"בעינן גיזה","והא תלישה הוא:"],[7,"מאן שמעת ליה הך סברא","דדריש לישנא דקרא דכתיב גז:"],[7,"רבי יוסי","דאמר לקמן לקט קצירך ולא לקט קיטוף:"],[7,"הא","אמרינן לקמן:"],[7,"מודה ר' יוסי במידי דאורחיה","וכיון דאורחא דעזים בתלישה כגיזה דמו:"],[8,"אלא","גז דאינו אלא ברחלים:"],[8,"כדר' יהושע בן לוי","לקמן בפרקין דכתיב גז וגו' וסמיך ליה כי בו בחר וגו':"],[8,"לעמוד לשרת דבר הראוי לשירות","לתכלת דבגדי שרד והתם צמר בעינן ואין צמר אלא של רחלים:"],[9,"שצמרן קשה","כגון שהיו משונים משאר כבשים:"],[9,"יתחמם","לא מיקרי גז אלא בר חימום:"],[10,"הגוזז את העזים פטור","כדאמרינן אין גז אלא של רחלים דבר הראוי לשירות:"],[10,"שוטף","במים בנהר ליפותן והצמר נתלש מהם:"],[10,"פטור","דלאו גז הוא:"],[10,"והא","דקתני שוטף פטור רבי יוסי הוא דדייק לישנא דקרא:"],[11,"ולא לקט קיטוף","הקוטף בידיו שבלי קמתו אין הנושר לקט דלישנא דקרא דייקא ופליגי רבנן עליה:"],[13,"במידי דאורחיה","כגון בצלים ושומים דקיטוף שלהן זהו קצירן:"],[13,"קציר","קציר ארצכם:"],[13,"עוקר","עם השרשים כגון עדשים:"],[14,"תולש","ביד ולא עם השרשים כגון פולין:"],[15,"","\u0003רבי יוסי \u0004לא גרסינן בהא מתניתא. ומיהו על כרחך הני קראי דריש להו ר' יוסי מדאמר אין לי אלא קציר דאיהו דדייק לישנא דקרא ומוקי להו במידי דאורחיה:"],[15,"אף אנן נמי תנינא","בהדיא דמודה רבי יוסי במידי דאורחיה:"],[15,"מלבנות","שורות שבין ירק לירק:"],[15,"פאה מכל אחת ואחת","מן המלבנות שהירק שבין מלבן למלבן הפסק לפאה דידה דירק אינו בכלל פאה חוץ מן השומים והבצלים כדתנן (פאה פ\"א מ\"ד) כל שהוא אוכל ונשמר ומכניסו לקיום ואמרינן במקום שנהגו (פסחים דף נו:) מכניסו לקיום פרט לירק ומיהו שומין ובצלים מכניסן לקיום. קתני מיהא לרבי יוסי דבצלים חייבין בפאה ואע\"ג דאינו קוצרן במגל אלמא מודי הוא במידי דאורחיה:"],[16,"בשלמא לב\"ש","אשכחן תרתי דאיקרו נמי צאן הילכך אין אתה יכול להוציאן מכלל חיוב:"],[17,"חמש צאן עשויות","לישנא יתירא קדרשי מאי עשויות שעושות שתי מצות ראשית הגז ומתנות דכל כמה דלא הוו חמש לא הוו נהגי בהו אלא חדא מתנות לחודייהו:"],[18,"אטו בכורה חדא מי לא מחייבא","על כרחך כי תלא רחמנא בחמש ראשית הגז הוא דתלא:"],[18,"וליטעמיך מתנות נמי חדא מי לא מחייבא","אישתכח דבתרתי ובחדא נמי איכא שתי מצות בכורה ומתנות וליכא למימר דהאי עשויות הכי מדריש והא ליכא למימר עשויות שלש מצות דהיכי משמע מיעוט עשויות שתים הוו:"],[18,"אלא אמר רב אשי","הכי דריש:"],[18,"עשויות שמעשות את בעליהן","למצוה חדשה שלא היה מצוה עליו בפחות מכן והיינו על כרחך ראשית הגז דכתיב בה צאן דמשמע מרובה דאילו בכורה דכתיב (במדבר י״ח:י״ז) בכור שור אפילו חד וכן מתנות אם שור אם שה (דברים י״ח:ג׳):"],[20,"","\u0003תניא א\"ר\u0004 גרסינן:"],[20,"דברי בריבי","שהיה גדול בדורו דקיימא לן רבי יוסי נמוקו עמו:"],[20,"אנן דברי בריבי שומעין","קס\"ד מפני שהוא מכריע ביניהם לא חמש כבית הלל ולא שתים כב\"ש:"],[20,"","תורת משה קרויה תורה לפי שנתנה תורה לדורות ושל נביאים לא קרי אלא קבלה שקבלו מרוח הקדש כל נבואה ונבואה לפי צורך השעה והדור והמעשה:"],[21,"והאמר מר אין הכרעה שלישית מכרעת","כשזה אומר כך וזה אומר כך וזה אומר דעת שלישית אפילו אמצעית היא ביניהם אין זה הכרע כגון (פסחים דף כ:) חבית של תרומה שנתגלתה ב\"ש אומר תשפך הכל וב\"ה אומרים תעשה זילוף א\"ר ישמעאל בר' יוסי אני אכריע בשדה תשפך הכל בבית תעשה זילוף אמרו לו אין הכרעה שלישית מכרעת והיכי הויא הכרעה כגון ההיא דקולי מטלניות דבמה מדליקין (שבת דף כט.) ר' אליעזר אומר בין מן המוכן בין שלא מן המוכן טמא ר' יהושע אומר בין מן המוכן בין שלא מן המוכן טהור ר\"ע אומר מן המוכן טמא שלא מן המוכן טהור א\"ר יוחנן עלה כל מקום שאתה מוצא שנים חולקים ואחד מכריע כו' אלמא כה\"ג קרי הכרעה היכא דגלו מאי דעתייהו דשייך לפלוגי בין מוכן לשאינו מוכן אפ\"ה לא פלגינן ואתא ר\"ע ונתן חילוק בדבר הוי הכרעה שהכריע במוכן כר' אליעזר ונמצאו שנים מטמאים במוכן ור' יהושע יחיד מטהר ובשאינו מוכן כר' יהושע והוו שנים מטהרים בשאינו מוכן אבל גבי חבית דלא גלו דעתייהו ב\"ש וב\"ה דנהוי שייך חילוק בין בית לשדה שלא אמרו כך ב\"ש אומר בין בבית בין בשדה תשפך הכל וב\"ה אומר בין בבית בין בשדה תעשה זילוף ובא שלישי וחלק בין שדה לבית התם אין זה הכרע לדבריהם אלא דעת שלישית דהכרע לשון כף מאזנים הוי בשנים חולקין ובא שלישי ומכריע המשקל כאחד מהן או בכל הדבר או בחציו כזה ובחציו כזה:"]],[[2,"מה\"מ","פירוש דראשית הגז אינו נוהג אלא ברחלים ולא בעזים דעזים נמי אקרו צאן דכתיב (בראשית כז) לך נא אל הצאן וקח לי משם שני גדיי עזים:"],[2,"אתיא גיזה גיזה","אע\"ג דדברי תורה מדברי קבלה לא ילפינן גילוי מילתא בעלמא הוא דגז דכבשים הוא ואין זה דבר חדש וקצת משמע דגזרה שוה היא מדפריך בסמוך אלא גיזה גיזה למאי אתא מ\"מ אינו דבר חדש:"],[3,"ולילף גיזה גיזה מבכור","וא\"ת והיכי מצינן למילף מבכור דאפילו שור הא צאן כתיב וי\"ל דהוה אמינא דצאן לאו דוקא כי היכי דלא תגוז בכור צאנך לאו דוקא:"],[14,"עוקר מנין ת\"ל לקצור תולש מנין תלמוד לומר בקוצרך","ואיצטריך תרי קראי משום דעוקר הוא קצת אורחיה טפי מתולש:"]]],[["אמר ר' יוחנן מפי שמועה אמרה מפי חגי זכריה ומלאכי:","ר' דוסא בן הרכינס אומר וכו': וכמה כל שהן אמר רב מנה ופרס ובלבד שיהו מחומשות ושמואל אמר ששים ונותן סלע אחת לכהן","רבה בר בר חנה אמר ר' יוחנן שש לכהן חמשה ואחד לו עולא אמר ר' אלעזר כל שהן שנינו","תנן וכמה נותן לו משקל חמש סלעים ביהודה שהן עשר סלעים בגליל בשלמא לרב ורבי יוחנן ניחא אלא לשמואל ור' אלעזר קשיא","וליטעמיך ולרב מי ניחא והא רב ושמואל דאמרי תרוייהו ראשית הגז בששים","הא איתמר עלה דההיא רב ושמואל דאמרי תרוייהו בישראל שיש לו גיזין הרבה עסקינן ומבקש ליתנן לכהן ואמרי' ליה כל חד וחד לא תבצר ליה מחמשת סלעים","גופא רב ושמואל דאמרי תרוייהו ראשית הגז בששים תרומה בששים פאה בששים","תרומה בששים והא אנן תנן תרומה עין יפה אחד מארבעים דאורייתא בששים דרבנן בארבעים","דאורייתא בששים והאמר שמואל חטה אחת פוטרת את הכרי דאורייתא כדשמואל דרבנן בדאורייתא אחת מארבעים דרבנן בדרבנן בששים","פאה בששים והתנן אלו דברים שאין להן שיעור הפאה והבכורים והראיון דאורייתא אין לה שיעור דרבנן בששים","מאי קמ\"ל תנינא אין פוחתין לפאה מששים אע\"פ שאמרו הפאה אין לה שיעור התם בארץ הכא בחו\"ל","כי סליק איסי בר היני אשכחיה לר' יוחנן דקא מתני ליה לבריה רחלים אמר ליה אתנייה רחלות א\"ל כדכתיב (בראשית לב, טו) רחלים מאתים אמר ליה לשון תורה לעצמה לשון חכמים לעצמן","אמר ליה מאן ריש סדרא בבבל אמר ליה אבא אריכא אמר ליה אבא אריכא קרית ליה דכירנא כד הוה יתיבנא אחר י\"ז שורן אחוריה דרב קמיה דרבי ונפקי זיקוקין דנור מפומיה דרב לפומיה דרבי ומפומיה דרבי לפומיה דרב ולית אנא ידע מה הן אמרין ואת אבא אריכא קרית ליה","אמר ליה איהו ראשית הגז בכמה אמר ליה ר' יוחנן בששים והאנן בכל שהן תנן אמר ליה אם כן מה בין לי ולך","כי אתא רב דימי אמר ראשית הגז רב אמר בששים ור' יוחנן משום ר' ינאי אמר בשש אמר ליה אביי לרב דימי אנחת לן חדא ואקשת לן חדא","בשלמא דר' יוחנן אדר' יוחנן לא קשיא הא דידיה הא דרביה","אלא דרב אדרב קשיא דהא אמר רב מנה ופרס דרב אדרב נמי לא קשיא מאי מנה דקאמר בן ארבעים סלעים דהוה ליה"],[[0,"א\"ר יוחנן מפי השמועה אמרה","ר' יוסי הלכך הלכתא כוותיה:"],[1,"מנה ופרס","החמשה כולן:"],[1,"שיהו מחומשות","לכל אחת מהן שבעה סלעים וחצי דהוו לה כולהו מנה ופרס שהמנה מאה זוז עשרים וחמשה סלעים הרי ל\"ז סלעים וחצי:"],[1,"ונותן סלע מהם לכהן","ולקמיה פריך ליה ממתניתין:"],[2,"רבי יוחנן אומר שש","סלעים הוי כל שהן ויתן מהם חמש סלעים כדתנן במתני':"],[2,"ואחד לו","ואפילו הן גוזזות אלף סלעים סגי ליה נמי בחמשה סלעים לכהן:"],[3,"כל שהן תנן","ואפילו אין גוזזות כולן אלא סלע אחד:"],[3,"בשלמא לרב ורבי יוחנן ניחא","דרב לא איירי בנתינת כהן כלל ואיכא למימר דהוא נמי סבירא ליה דנותן מהנך ל\"ז סלעים לכהן ה' סלעים:"],[3,"אלא לשמואל","דאמר נותן סלע לכהן הא אנן חמש תנן ולעולא נמי דאמר כל שהוא קשיא דמהיכא יתן לכהן ה' סלעים:"],[4,"ולרב מי ניחא והאמר ראשית הגז בס'","וכיון דאמר שבעה ושלשים סלעים וחצי חייבין בראשית הגז אם מחמש רחלות באו צא מהם חלק ס' מטי לשלשים סלעים חצי סלע ולשבעה סלעים וחצי דבר מועט וא\"נ מוקמינן לה כדלקמן במנה בן מ' סלעים אכתי סלע הוא דהוי ואנן ה' סלעים לכהן תנן:"],[5,"הא אתמר עלה","כלומר ולעולם ראשית הגז בששים בין רב למעט ומתניתין דקתני חמש סלעים לאו ארישא קאי אלא מילתא באנפי נפשה היא:"],[5,"בישראל שיש לו גיזין הרבה","דחלק ששים שבהם יש בו כדי לחלק לכהנים הרבה ומבקש ליתנם לכהנים הרבה דאמרי' ליה כל חד וחד כהן לא תבצר ליה מחמשה סלעים דהואיל ויש לו ליתן בעינן נתינה ראויה לכל כהן כדלקמן והיכא דגוזזות מעט נמי סגי ליה בששים. יש לשונות אחרים ואין בהם ממש:"],[7,"והא תניא עין יפה אחד מארבעים","והיכי רב ושמואל אעין רעה נקטי שיעורייהו:"],[7,"ומשני דאורייתא בששים","מדאורייתא סגי ליה בששים והיינו דקתני עין רעה אחד מששים. רב ושמואל שיעורא דאורייתא אתו לאשמועינן. וביחזקאל (מה) רמיזא וששיתם האיפה מחומר החטים וששיתם האיפה מחומר השעורים חומר ל' סאין איפה שלש סאין שתות שלה חצי סאה כשתוציא חצי סאה תרומה משלשים הרי אחד מששים:"],[7,"דרבנן מארבעים","ואתו רבנן ותקון דניהיב עין יפה מארבעים ובינונית בחמשים:"],[8,"פוטרת את הכרי","ראשית דגנך ולא יהיב ביה קרא שיעור:"],[8,"דאורייתא כדשמואל","מדאורייתא בכל שהן מיפטר:"],[8,"דרבנן בדאורייתא בארבעים","ושעורא דרבנן אתמר בתרומה שהיא מן התורה כגון תרומת תירוש ויצהר שתנתן בארבעים:"],[8,"ושיעור דרבנן בדרבנן","ושיעורא דאמור רבנן בתרומה דידהו כגון פירות האילן וירק בששים ורמיזא דיחזקאל אצרי עין אמרה:"],[9,"והראיון","מפרש בגמ' דחגיגה (דף ז.) דכל כמה דבעי לאתחזויי בעזרה ברגל מיתחזי ומייתי קרבן עולת ראיה וגם הקרבן אין שיעורא לדמים אם מרובה אם מועט מן התורה אבל חכמים אמרו הראיה מעה כסף והחגיגה שתי כסף:"],[9,"דאורייתא אין לה שיעור","כלל ורבנן יהבו לן בה שיעורא בששים אבל בתרומה אף על גב דמדאורייתא נמי בכל דהו מפטר נהי דמפטר ממיתה דטבל מיהו לכתחלה רמיזא שיעורא דילה חמשים וששים דתנא בתוספתא אמר רבי יוסי מנין לתרומה שהיא אחד מחמשים שנאמר במדין (במדבר לא) תקח אחד אחוז מן החמשים אחוז שאמרתי לך במקום אחר כזה ומנין אם תרם ועלה בידו אחד מששים שאין צריך לתרום שנאמר וזאת התרומה אשר תרימו ששית האיפה מחומר החטים וגו' אלמא דמתייהב בה שיעורא הלכך לא תני לה בדברים שאין להם שיעור:"],[11,"אשכחיה","רבי יוחנן לאיסי בר היני:"],[11,"דמתני לבריה","מתניתין חמש רחלים גוזזות מנה מנה ופרס:"],[11,"אמר ליה","איסי כדכתיב קרא קא מתני רחלים מאתים אמר ליה לשון תורה לחוד וכו':"],[12,"אמר ליה","ר' יוחנן לאיסי:"],[12,"מאן ריש סידרא בבבל","ראש ישיבה:"],[12,"אבא אריכא","רב קרי אריכא שארוך בדורו היה כדאמרינן בהמפלת בנדה (דף כד:):"],[12,"אבא אריכא קרית ליה","ולא אמרת רבינו בלשון כבוד:"],[12,"דכירנא","כשהיה בכאן קודם שירד לבבל היה חשוב ממני שהיה יושב לפני רבי ואני הייתי יושב שבעה עשר שורות מאחריו:"],[12,"זיקוקין","נושאין ונותנין בהלכה:"],[13,"א\"ל איהו","איסי לרבי יוחנן:"],[13,"ראשית הגז בכמה","כמה יהיה לו ויתחייב בראשית הגז אמר ליה בששים סלעים:"],[13,"מה בין לי ולך","אם איני יודע פירושה של משנתינו יותר ממך מה אני גדול ממך אני יש בידי דכל שהוא לאו דוקא אלא איידי דאמר ר' דוסא שיעורא רבה אמור רבנן לשון שיעור מועט וגוזמא הוא ומיהו ששה סלעים בעינן כי היכי דלימטי סלע לכהן דבציר מהכי ליכא למאן דאמר דתיהוי נתינה:"],[14,"בששים","חלק ששים יתן לכהן. לישנא אחרינא ששים סלעים חייבים בראשית הגז:"],[14,"אנחת לן חדא","אחת מדבריך יכולה להתקיים:"],[15,"בשלמא דרבי יוחנן","דאמרת משמיה בששים:"],[15,"אדר' יוחנן","דאמר לעיל כמה כל שהן שש חמש לכהן ואחד לו לא קשיא:"],[15,"הא דידיה הא דרביה","משום רבי ינאי כדקאמרינן:"],[16,"אלא דרב אדרב קשיא דאמר רב (כולו) מנה ופרס","חייבות בראשית הגז ואי ראשית הגז בששים לא מטו ליה לכהן סלע ובציר מהכי ליכא למאן דאמר:"],[16,"במנה בן ארבעים סלעים","יש מנה גדול כך כדלקמן דהוו מנה ופרס ששים ומהן יתן סלע לכהן:"]],[[1,"עד שצבעו פטור","פירש בקונטרס משום דהוי כמו מזיק מתנות או אוכלן דפטור וה\"נ גוזל ותימה דא\"כ מאי קמ\"ל רב חסדא כיון דמתני' היא ובפי' רש\"י הראשונים במכתב ידו פירש שקודם שגזז חמש צאן דהיינו כדי חיוב צבע מה שגזז שלא בא לידי חיוב עד שצבעו והעביר עליו קולמוס ונראה דקמ\"ל רב חסדא שלא נפרש מתני' כפירוש שמחק בקונטרס אלא פטור משום דמזיק מתנות כהונה שקנאן בשינוי:"],[7,"והא אנן תנן","שיעור תרומה עין יפה אחד מארבעים ולא בעי למימר דשמואל איירי בעין רעה דאם כן מאי קמ\"ל מתניתין היא במסכת תרומות (פרק ד מ\"ג) עין רעה אחד מששים:"],[9,"אלו דברים שאין להם שיעור הפאה כו'","בירושלמי דמסכת פאה פריך אמאי לא חשיב נמי תרומה בהדייהו דחטה אחת פוטרת הכרי כדשמואל ומשני דתרומה יש לה שיעור למעלה שאין יכול לעשות כל גרנו תרומה כדתנן העושה כל גרנו תרומה וכל עיסתו חלה לא עשה ולא כלום ופריך והרי פאה דאין אדם עושה כל שדהו פאה וקתני ומשני פאה בשעת חיובא דהיינו משמתחיל לקצור אדם עושה כל שדהו פאה דהוי פאה למה שכבר קצר אבל תרומה בתר חיובא דהיינו אחר מירוח אין יכול לעשות כל גרנו תרומה בגמ' דהראיון פריך אמאי לא חשיב אפר פרה ועפר סוטה ורוק יבמה ומשני דלא חשיב במתני' אלא דברים דאי עביד טובא הוי מצוה אבל אין מחויב לעשות אלא כל שהוא:"]]],[["בששים ותני תנא מנה בן ארבעים סלעים אין והתנן חמת חדשה אע\"פ שמקבלת רמונים טהורה","תפרה ונקרעה שיעורה כמוציא רמונים רבי אליעזר בן יעקב אומר כפקעיות של שתי אחת מארבע במנה בן ארבעים סלעים:","וכמה נותן לו כו': תנא לא שילבננו ויתננו לו אלא שילבננו כהן ויעמוד על חמש סלעים:","כדי לעשות בגד קטן: מנהני מילי אמר ר' יהושע בן לוי אמר קרא (דברים יח, ה) לעמוד לשרת דבר שהוא ראוי לשירות מאי ניהו אבנט","אימא מעיל תפשת מרובה לא תפשת תפשת מועט תפשת","ואימא כיפה של צמר דתניא כיפה של צמר היתה מונחת בראש כהן גדול ועליה ציץ נתון לקיים מה שנאמר ושמת אותו על פתיל תכלת","אמר קרא הוא ובניו דבר השוה לאהרן ולבניו","אבנט נמי לא שוי הניחא למאן דאמר אבנטו של כ\"ג לא זהו אבנטו של כהן הדיוט שפיר","אלא למאן דאמר זהו אבנטו של כהן הדיוט מאי איכא למימר שם אבנט בעולם:","לא הספיק ליתנו וכו': איתמר גזז ומכר ראשונה רב חסדא אמר חייב ר' נתן בר הושעיא אמר פטור","רב חסדא אמר חייב דהא גזז ר' נתן בר הושעיא אמר פטור בעידנא דקא מלא שיעורא בעינן צאנך וליכא","תנן הלוקח גז צאנו של עובד כוכבים פטור מראשית הגז הא צאנו לגזוז חייב אמאי כל חד וחד בתר גיזה נפקא לה מרשותיה","תרגמא רב חסדא אליבא דר' נתן בר הושעיא כגון שהקנן לו כל שלשים יום:","הלוקח גז צאנו של חבירו כו': מאן תנא דהיכא דאיכא שיורא גבי מוכר בתר מוכר אזלינן","א\"ר חסדא רבי יהודה היא דתנן המוכר קלחי אילן בתוך שדהו נותן פאה לכל אחד ואחד","אמר רבי יהודה אימתי בזמן שלא שייר בעל השדה אבל שייר בעל השדה נותן פאה על הכל","אמר ליה רבא והא מר הוא דאמר והוא שהתחיל בעל השדה לקצור","וכי תימא הכא נמי והוא שהתחיל לגזוז בשלמא התם (ויקרא יט, ט) ובקצרכם את קציר ארצכם כתיב מעידנא דאתחיל לקצור מיחייב בכולה שדה אלא הכא מעידנא דאתחיל למיגז לא מיחייב בכוליה עדריה","אלא אמר רבא האי תנא הוא דתנן אמר לו מכור לי בני מעיה של פרה זו והיה בהן מתנות נותנן לכהן ואין מנכה לו מן הדמים לקח ממנו במשקל נותנן לכהן ומנכה לו מן הדמים"],[[0,"ופרכינן ותני תנא מנה בן ארבעים","והא מנה ופרס דרב הוא מנה ופרס דקאמר רבי דוסא בכל אחת מנה ופרס ופליגי רבנן עליה דאמרי כל שהן ופירש רב למילתייהו דכל שהן היינו בין כולן מנה ופרס:"],[0,"חמת חדשה","של עור שלא גמר תפירתה ושייר בה סדק:"],[0,"אע\"פ שמקבלת רמונים","שאין בסדק כמוציא רמון:"],[0,"טהורה","שלא נגמרה מלאכתה:"],[1,"תפרה","ונגמרה מלאכתה וחל עליה שם כלי ואח\"כ נקרעה כמוציא רמון טהורה אבל מקבלת רמונים טמאה דלא פקע שם כלי מינה עד שתינקב כמוציא רמון כשיעור כל כלי בעלי בתים ששיעורן כרמונים:"],[1,"כפקעיות של שתי","שיעור קריעת כלי לטהר כשמוציא פקעיות של שתי שזה הוא תשמישתה של חמת ואין דרך להשתמש בה פירות וסתם פקעיות של שתי גדולים עשר סלעים משקלם ארבעה למנה:"],[1,"פקעיות","למושיי\"ל:"],[2,"תנא","הא דקתני מתניתין חמש סלעים מלובן לא שיהא על ישראל מוטל ללבנו אלא אשיעורא קפיד דליתיב ליה בהכרע שכשיתלבן שיהא בו חמש סלעים ונפטרות כל גיזים:"],[3,"אמר קרא לעמוד לשרת","בתר ראשית הגז כתיב כי בו בחר ה' מכל שבטיך לעמוד לשרת:"],[3,"מאי ניהו אבנט","שהוא קטן שבבגדי כהונה וקים להו לרבנן שיכול לעשות מחמש סלעים צמר שהרי אין כולו צמר אלא כלאים הוא:"],[4,"תפשת מרובה לא תפשת","ברייתא בתורת כהנים גבי זבה (ויקרא טו) ימים רבים ימים שנים רבים שלשה או אינו אלא רבים עשרה אמרת כל ששמעו מרובה ושמעו מועט תפסת מרובה לא תפסת תפסת מועט תפסת הואיל ולא פירש לך איזה מהן יש לך לתפוס הראשון שבמשמע שאם לא נתפוס אלא המרובה אני משיבך מהיכן אתה ממעטו לזה המועט והלא אף הוא במשמע כשתאמר אינה זבה בפחות מעשרה אני אומר לך והלא אף שלשה במשמע וכשתאמר בשלשה ואני משיבך אינו אלא עשרה אתה אומר לי אף השלשה במשמע. וגבי שירות נמי תאמר אבנט ואני משיבך ואימא מעיל אתה אומר לי והלא אף האבנט בכלל שירות ומהיכן אתה ממעטו אבל כשתאמר אין פטור אלא בכדי מעיל אני משיבך והלא אבנט ראוי לשירות וקרא שירות הוא דכתיב:"],[5,"ואימא כיפה של צמר","שהיא מועטת מאבנט ואף היא בכלל שירות כדכתיב (שמות כח) על פתיל תכלת ותכלת עמרא הוא:"],[5,"כיפה","כובע קטן פלטרי\"י:"],[5,"ושמת אותו","בציץ:"],[6,"אמר קרא","גבי שירות דראשית הגז:"],[6,"הוא ובניו","וציץ אינו בכהן הדיוט:"],[7,"הניחא למ\"ד אבנטו של כהן גדול","ביום הכפורים שהוא בוץ כדכתיב (ויקרא טז) ובאבנט בד יחגור:"],[7,"לא זהו אבנטו של כהן הדיוט","של כל השנה דהא הוא הואי של כלאים כדכתיב (שמות לט) ואת האבנט שש משזר תכלת וגו' וכי כתיב אבנט דכלאים בין בכהן גדול בין בכהן הדיוט דכל השנה כתיב:"],[7,"שפיר","משכחת שוין אהרן ובניו באבנט של צמר כגון של שאר ימות השנה:"],[8,"אלא למ\"ד","אבנטו של כהן גדול ביום הכפורים כשר הוא בהדיוט כל השנה דכי כתיב אבנט בכלאים גבי פרשת בגדי כהונה בכהן גדול הוא דכתיב אבל בכהן הדיוט כולו של בוץ א\"כ לא משכחת צמר באבנט של הדיוט ואמאי משערת ראשית הגז באבנט הא לא שוין בה אהרן ובניו שהצמר אינו ראוי לשירות הדיוט:"],[8,"שם אבנט","אע\"ג דאין צמר בשירות הדיוטות הרי ראוי לשירות כ\"ג ואי משום הוא ובניו הכי קאמר דברים הראויין לאבנט שהרי אבנט נוהגת בו ובבניו:"],[9,"מכר לו שחופות כו'","הא אוקימנא עצה טובה קמ\"ל דאע\"ג ששייר לעצמו מן הטוב יקנה מן הלוקח ממין הרעות אחד מששים ויתן לו:"],[9,"גזז ומכר ראשונה","ראשונה היה מוכר לאחר גיזתה מיד קודם שצירף חמש גיזין:"],[9,"חייב","בראשית הגז דגז צאנך אמר רחמנא והא איכא דבשעת גיזה כל אחת היתה שלו:"],[10,"בעידנא דקא מלי שיעורא","דחמש צאן שעל ידי גיזה החמישית הוא מתחייב בארבעה ראשונות וההיא שעתא לא הוו מצאן שלו:"],[11,"תנן הלוקח צאנו של עובד כוכבים","אפילו עד שלא נגזזה וגזזה פטור הלוקח דלאו צאנו הוא:"],[11,"הא צאנו לגזוז","שמכר לו גוף הצאן זה קנה לו הגוף עד שגזז:"],[11,"חייב","דצאנך קרינא ביה:"],[11,"כל חדא וחדא בתר גיזה נפק מרשותיה","וקתני חייב אלמא בתר שעת גיזה דכל חדא אזלינן:"],[12,"כל שלושים יום","לאו דוקא אלא שיהו כל הגופים קנויין לו עד תשלום כל הגיזים:"],[13,"בתר מוכר אזלינן","למיתב אכולהו:"],[14,"קלחי אילן","אילנות עצמן לקח עם פירותיהן. להכי נקט לשון קלחי שאין שדה זו שדה אילן אלא שדה לבן וגדלו בה שנים או שלשה אילנות ומכרן:"],[14,"נותן","לוקח פאה מכל אילן ואילן כדכתיב (דברים כד) לא תפאר אחריך ואין אחד מהם פוטר את חבירו הואיל ואין השדה שלו שאם היתה שדה שלו היה נותן מאחד על כולן:"],[15,"אימתי בזמן שלא שייר בעל השדה","שום אילן בשדה לעצמו:"],[15,"אבל שייר","אחד לעצמו רמיא כולה חיובו עליה ונותן פאה בקרקע בזרעים לעניים ופוטר את כל האילנות. אלמא היכא דאיכא שיורא כולה חיובא רמיא עליה דאי לאו עליה רמיא היכי פטר בפאה דידיה אילנות של אחרים:"],[16,"והוא שהתחיל בעל הבית לקצור","הזרעים קודם מכירת האילנות דמההיא שעתא מיחייב בפאה ופאה דידיה דההיא שעתא חזיא למפטר כולה שדה ומיהו כי לא שייר מידי אסתלק מדין פירות אילנות ואין פאת זרעים פוטרתן וכי שייר דאכתי שייר בפירות אילנות לא נפק מחיובא קמא והוה ליה כדמעיקרא:"],[17,"ובקצרכם","משמע מתחלת קצירה:"],[17,"לא מיחייב בכוליה עדריה","דלא כתיב בגזזכם אלא גז צאנכם לאחר שנקרא גז צאן:"],[18,"אלא אמר רבא","טעמא דמתני' משום דאין אדם רשאי להפקיע ממונו מיד מצוה ולמכור גיזיו כדי שיהא גז של אחד וצאן של אחר לפוטרן דלא קרינא ביה גז צאנך אלא כי קא מזבין לא קמזבין מתנות דכהן הילכך כי שייר מידי איכא למימר מדלא פריש מוכר ללוקח חוץ ממתנותיו של כהן ודאי הכל מכר לו ושייר אצלו את מתן הכהן ואמר לוקח למוכר מתנה דכהן גבך היא וכי לא שייר חייב הלוקח ולא משום דחיוב המצוה עליה דלאו צאנך הוא אלא משום דזה לא מכר לו חלקו של כהן:"],[18,"נותנו","לוקח לכהן ואין הטבח מנכה לו כלום לפי שלא מכר לו את המתנות מסתמא:"],[18,"לקח הימנו במשקל","דהשתא ודאי זבין ליה:"],[18,"מנכה לו מן הדמים","משנשחטה זכו הכהנים במתנותיהן והדין על הטבח. וגבי ראשית הגז ודאי אם פירש לו הכל אני מוכר לך אין כאן לכהן כלום על זה הואיל ועד שלא נגזזה נמכרה לא חל עליה חובת ראשית הגז דלא קרינא ביה גז צאנך וטעמא דמתני' משום דלא זבניה ולטעמיה דרב חסדא אפילו פריש ליה יהיב ליה ולאו מילתא היא:"]],[[7,"הכי גרסינן הניחא למאן דאמר לא זהו אבנטו כו'","כדמוכח בפ\"ק דיומא (דף יב.)"]]],[["אלמא מתנות דכהן לא מזבין איניש הכא נמי מתנות דכהן לא מזבין איניש הלכך שייר המוכר מוכר חייב דאמר ליה לוקח מתנה דכהן גבך היא לא שייר לוקח חייב דאמר ליה מוכר מתנה דכהן לא זבני לך:","\u0001הדרן עלך ראשית הגז\u0002","מתני׳ \u0001שילוח\u0002 הקן נוהג בארץ ובחו\"ל בפני הבית ושלא בפני הבית בחולין אבל לא במוקדשין חומר בכסוי הדם משילוח הקן שכסוי הדם נוהג בחיה ובעוף במזומן ובשאין מזומן ושילוח הקן אינו נוהג אלא בעוף ואינו נוהג אלא בשאינו מזומן","איזהו שאינו מזומן כגון אווזין ותרנגולים שקננו בפרדס אבל אם קננו בבית וכן יוני הרדסיאות פטור משילוח עוף טמא פטור מלשלח עוף טמא רובץ על ביצי עוף טהור וטהור רובץ על ביצי עוף טמא פטור מלשלח קורא זכר רבי אליעזר מחייב וחכמים פוטרין:","\u0001גמ׳\u0002 רבי אבין ור' מיישא חד אמר כל היכא דתנן בארץ ובחו\"ל שלא לצורך לבד מראשית הגז לאפוקי מדר' אלעאי דאמר ראשית הגז אינו נוהג אלא בארץ","וחד אמר כל היכא דתנן בפני הבית ושלא בפני הבית שלא לצורך לבד מאותו ואת בנו סלקא דעתך אמינא הואיל ובענינא דקדשים כתיב בזמן דאיכא קדשים ננהוג בזמן דליכא קדשים לא ננהוג קמ\"ל","ותרוייהו אמרי כל היכא דתנן בחולין ובמוקדשים לצורך לבד מגיד הנשה פשיטא משום דאיקדש פקע ליה איסור גיד הנשה מיניה","ולאו אוקימנא בולדות קדשים","ומאי טעמא אוקימנא לאו משום דקשיא לן לא ליתני מעיקרא נמי לא תקשי לך איידי דתנא לצורך תנא נמי שלא לצורך:","בחולין אבל לא במוקדשים: אמאי לא דאמר קרא (דברים כב, ז) שלח תשלח את האם במי שאתה מצווה לשלחו יצא זה שאי אתה מצווה לשלחו אלא להביאו לידי גזבר","אמר רבינא הלכך עוף טהור שהרג את הנפש פטור משלוח מ\"ט דאמר קרא שלח תשלח את האם במי שאתה מצווה לשלחו יצא זה שאי אתה מצווה לשלחו אלא להביאו לב\"ד היכי דמי אי דגמר דיניה"],[[2,"","מתני' שילוח הקן:"],[2,"אבל לא במוקדשין","בגמ' מפרש היכי דמי מוקדשין:"],[2,"ואינו נוהג אלא בשאינו מזומן","דכתיב (דברים כב) כי יקרא:"],[3,"שקננו בפרדס","שמרדו ויצאו מן הבית ואין חוזרות לבית ונעשו מדבריות ופרדס לאו מזומן הוא שיכולים הם לברוח אבל אם בבית קננו פטור:"],[3,"קננו בתוך הבית","שלא מרדו:"],[3,"וכן יוני הרדסיאות","שדרכם ליגדל עם בני אדם פטור:"],[3,"עוף טמא פטור","כדמפרש בגמרא צפור טהורה ולא טמאה:"],[3,"עוף טמא רובץ על ביצי עוף טהור","אע\"ג דמינא דאפרוח בר שילוח הוא:"],[3,"פטור","דקן צפור בעינן שתהא האם המקננת צפור טהורה. ועוף טהור הרובץ על ביצי עוף טמא נמי אע\"ג דקן צפור הוא פטור כדמפרש בגמרא ואת הבנים תקח לך ולא לכלביך ובגמרא פריך מכלל דעוף טהור הרובץ על ביצי מין אחר כמותו טהור חייב:"],[3,"קורא","עוף טמא הוא ודרכו לרבוץ על ביצי אחרים:"],[3,"זכר פטור מלשלח","כדיליף טעמא בגמ':"],[4,"גמ' רבי אבין ורבי מיישא","מפרשי הך מתניתין דכסוי הדם ואותו ואת בנו וגיד הנשה והזרוע והלחיים וראשית הגז ושלוח הקן דתנן בכולהו בארץ ובחו\"ל בפני הבית ושלא בפני הבית בחולין ובמוקדשין מר פריש חדא ומר פריש חדא ולא פליגי ותרוייהו קא מפרשי לאידך וצריכין אנו לומר דבר בשם אומרו:"],[4,"כל היכא דתנן בארץ ובחו\"ל","בהנך פרקין:"],[4,"שלא לצורך","הוא דלאו חובת קרקע נינהו אלא חובת הגוף ונוהגת בכל מושבות כדיליף בפ\"ק דקדושין (דף לז:):"],[4,"לבד מראשית הגז לאפוקי מדרבי אלעאי","דמקיש לה לתרומה. וה\"ה נמי במתנות נשנית לצורך דהא רבי אלעאי יליף מתנות מראשית הגז והא דנקט ראשית הגז משום דעלה א\"ר אלעאי בהדיא כדאמר לעיל רבי אלעאי אומר ראשית הגז אינה נוהגת אלא בארץ:"],[6,"וכל היכא דתני בחולין ובמוקדשין","דהיינו גיד הנשה ואותו ואת בנו:"],[6,"לצורך","דאותו ואת בנו אי לאו דאשמועינן ליה הוה אמינא דאינו נוהג אלא במוקדשין דהא בקדשים כתיב הילכך אשמועינן דנוהג הוא בחולין כדאמר התם ושור הפסיק הענין וכ\"ש הנך דתנן אבל לא במוקדשין לצורך הוא דאשמועינן חילוק:"],[6,"בר מגיד הנשה","דשלא לצורך תנייה דנוהג הוא דפשיטא לן דמשום דאקדשיה לא לפקע איסור גיד הנשה מיניה:"],[7,"ולאו מי אוקימנא ליה","בפרק גיד הנשה (לעיל חולין דף פט:):"],[7,"בולדות קדשים","דאתא לאשמועינן דחייב משום גיד ומוקדשין דכיון דאיסור מוקדשין קדים כדמפרש התם שיצירת הולד קודמת לגידין איצטריך לאשמועינן דאתי איסור גיד וחייל עלייהו:"],[8,"ומשני מ\"ט","דוחקת לאוקמה בהכי משום דהיה קשיא לך למאי הלכתא תנינהו והשתא אתו רבי אבין ורבי מיישא להנך למימר לא תדחק לאוקמה בהכי דמעיקרא כי מקשת התם פשיטא לאו קושיא היא דהא איכא טובא דמתני שלא לצורך ואיידי דתנינהו כל חדא וחדא בחדא לצורך תנא נמי בהן באידך שלא לצורך וה\"ה למוקדשין איידי דתנייה בכולהו לצורך תנייה נמי בהן שלא לצורך וכן בפני הבית משום אותו ואת בנו תנייה בכולהו וכן חו\"ל משום ראשית הגז:"],[10,"שהרג את הנפש","ואח\"כ מרד ונמצא בקן:"],[10,"פטור מלשלח","הואיל ובר קטלא הוא והכי דרשת ליה דקא בעי לשלח למקום הצלה והפקר והאי לאו בר הכי הוא והכי דריש קרא שלח תשלח את הראוי לשלחו ואת שאין ראוי לשלחו אל תשלחנו:"]],[[0,"אלמא מתנות דכהן לא מזבני אינשי","פירוש לא מזבני כמו לא זבני דכי היכי דכשלקח ממנו במשקל מנכה לו משום דכשאמר ליה מכור לי ליטרא בשר לא רצה לקנות מתנות ה\"נ מתני' שייר אצל מוכר הוי כלוקח הימנו במשקל ולא זבין מתנה דכהן אבל בשלא שייר כלום לא שייך לומר לא זבין שהרי קנה הכל ומיהו הא דקאמר דא\"ל מוכר מתנה דכהן לא זבני לך לא א\"ש:"],[2,"","מתני' שילוח הקן:"],[4,"לבד מראשית הגז","וה\"ה לבד ממתנות וחדא מינייהו נקט:"],[6,"כל היכא דתנן בחולין ובמוקדשין לצורך כו'","תימה כיון דאין חילוק בין חולין ומוקדשים אלא בגיד הנשה ובאותו ואת בנו א\"כ הכי נמי הוה מצי למימר איפכא שלא לצורך לבד מאותו ואת בנו וי\"ל דכיון דחדוש הוא באותו שהוא שלא לצורך כדמפרש ואזיל ולאו מי אוקימנא כו' ניחא טפי לומר לבד מאותו דבר שהייתי סבור שהוא לצורך והוא שלא לצורך:"],[8,"מאי טעמא אוקימנא לאו משום דקשיא לן כו'","דהא דאשמועינן דולדות קדשים במעי אמן או בהוייתן הן קדושין הוה מצי לאשמועינן בעלמא בלא גיד הנשה אלא איידי דתנא לצורך תנא נמי שלא לצורך ומ\"מ מוקמינן לה בולדות קדשים כיון דמצינן לפרושי דאשמועינן חדוש קצת:"],[9,"יצא זה שאין אתה מצווה לשלחו אלא להביאו ליד גזבר","פ\"ה דטעמא משום דלא אמרה תורה שלח לתקלה וקשה חדא דלישנא לא משמע הכי ועוד דמסיק ומוקי לה בלא נגמר דינו וא\"כ אין בו תקלה ונראה דפשטיה דקרא דריש דמשמע דבמידי שיכול לשלחו משתעי אבל הקדש מצוה להביאו ליד גזבר ופירש בקונטרס מתקח לך לא מצי לאתויי דהא ביצי תורים לא מועלים ולא נהנים ואע\"ג דבקדשי בדק הבית מועלים מתניתין איירי בקדשי מזבח לכ\"ע ולא פליגי בסמוך אלא בקדשי בדק הבית ולהכי לא מצי ממעט מתקח לך ומיהו לשון להביאו ליד גזבר אין מיושב כל כך דגזבר לא שייך אלא בקדשי בדק הבית:"]]],[["בר קטלא הוא אלא דלא גמר דיניה ובעי לאתוייה לבי דינא וקיומי ביה (דברים יג, ו) ובערת הרע מקרבך","הני מוקדשין היכי דמי אילימא דהוה ליה קן בתוך ביתו ואקדשיה מי מיחייב (דברים כב, ו) כי יקרא קן צפור פרט למזומן","אלא דחזא קן בעלמא ואקדשיה ומי קדוש (ויקרא כז, יד) איש כי יקדיש את ביתו קדש אמר רחמנא מה ביתו ברשותו אף כל ברשותו","אלא דאגבהינהו לאפרוחים ואקדשינהו והדר הדרינהו האי אפילו בחולין נמי לא מיחייב דתנא נטל את הבנים והחזירן לקן ואח\"כ חזרה האם עליהן פטור מלשלח","אלא דאגבהה לאם ואקדשה והדרה מעיקרא איחייב ליה בשילוח מקמי דאקדשה דתניא ר' יוחנן בן יוסף אומר הקדיש חיה ואח\"כ שחטה פטור מלכסות שחטה ואח\"כ הקדישה חייב לכסות שכבר נתחייב בכסוי קודם שיבא לידי הקדש","רב אמר במקדיש פירות שובכו ומרדו ושמואל אמר במקדיש תרנגולתו לבדק הבית","בשלמא שמואל לא אמר כרב דקא מוקים לה בקדשי בדק הבית אלא רב מאי טעמא לא אמר כשמואל","אמר לך רב דוקא קפטרי משילוח כגון פירות שובכו דקדשי מזבח נינהו דכיון דקדשי קדושת הגוף לא פקעה קדושתייהו מינייהו אבל במקדיש תרנגולתו לבדק הבית דלאו קדשי מזבח דקדושת דמים בעלמא הוא כיון דמרדה פקעה קדושתייהו וחייבת בשילוח","ושמואל אמר כל היכא דאיתיה בבי גזא דרחמנא איתא דכתיב (תהלים כד, א) לה' הארץ ומלואה וכן אמר ר' יוחנן במקדיש תרנגולתו לבדק הבית ומרדה אמר ליה רבי שמעון בן לקיש וכיון שמרדה פקעה ליה קדושתה אמר ליה בבי גזא דרחמנא איתא דכתיב לה' הארץ ומלואה","ורמי דר' יוחנן אדר' יוחנן ורמי דר' שמעון בן לקיש אדר\"ש בן לקיש","דאיתמר מנה זה לבדק הבית ונגנבו או נאבדו רבי יוחנן אמר חייב באחריותן עד שיבואו לידי גזבר וריש לקיש אמר כל היכא דאיתיה בבי גזא דרחמנא איתיה דכתיב לה' הארץ ומלואה קשיא דריש לקיש אדריש לקיש קשיא דר' יוחנן אדר' יוחנן","דריש לקיש אדריש לקיש לא קשיא הא מקמי דשמעיה מר' יוחנן רביה הא לבתר דשמעיה מר' יוחנן רביה","אלא דר' יוחנן אדר' יוחנן קשיא דר' יוחנן אדר' יוחנן נמי לא קשיא הא דאמר עלי הא דאמר הרי זו","מכלל דר\"ש בן לקיש אע\"ג דאמר עלי לא מחייב","והתניא איזהו נדר ואיזו היא נדבה נדר האומר הרי עלי עולה נדבה האומר הרי זו עולה ומה בין נדר לנדבה נדר מתה או נגנבה או שאבדה חייב באחריותה נדבה מתה או נגנבה או שאבדה אינו חייב באחריותה","אמר לך ריש לקיש הני מילי קדשי מזבח דמחוסר הקרבה אבל קדשי בדק הבית דלאו מחוסר הקרבה אע\"ג דאמר עלי לא מחייב","והתנן האומר שור זה עולה בית זה קרבן מת השור נפל הבית אינו חייב באחריותן שור זה עלי עולה בית זה עלי קרבן מת השור ונפל הבית חייב לשלם","ה\"מ היכא דמת השור ונפל הבית חייב לשלם דליתנהו אבל היכא דאיתנהו כל היכא דאיתיה בבי גזא דרחמנא איתיה דכתיב לה' הארץ ומלואה","אמר רב המנונא הכל מודים בערכין אע\"ג דאמר עלי לא מיחייב מאי טעמא דלא מיתמר ליה בלא עלי","היכי לימא לימא ערכי אמאן לימא ערך פלוני אמאן","מתקיף לה רבא לימא הריני בערכי הריני בערך פלוני ועוד תניא רבי נתן אומר (ויקרא כז, כג) ונתן את הערכך ביום ההוא קדש לה' מה תלמוד לומר לפי שמצינו בהקדשות ומעשרות שמתחללין על מעות שבחולין נגנבו או שאבדו אינן חייבין באחריותן"],[[0,"בר קטלא הוא","ומהיכן נמלט:"],[0,"ובערת הרע","מצוה על כל הפוגע בחייבי מיתה להביאן לב\"ד כדי לבער רשעים מישראל:"],[1,"מי מיחייב","אפילו כשהוא חולין:"],[2,"אלא דחזא קן בעלמא","במקום שאין קנוי לו והביצים אינן שלו דהא כל מקום שהביצים שלו אפילו ע\"י זכיית חצר המשתמרת לאדם שלא מדעתו חשיב ליה מזומן בהשואל את הפרה (ב\"מ דף קב.):"],[3,"אלא דאגבהינהו לאפרוחים","וזכה בהו ואקדשינהו ומאחר דאפרוחין קדושים נפטר מלשלח את האם:"],[3,"והדר אהדרינהו","וחזרה האם עליהן:"],[3,"פטור מלשלח","דהא כיון דזכה בהו מזומן קרינא בהו:"],[4,"איחייב ליה בשילוח","כשמצאן ומשום דאקדשה בתר הכי לא פקע ליה שום מצוה מינייהו. דתניא וכו' מוקדשים אין כסוי הדם נוהג בהן כדאמרינן בפרק כסוי הדם (לעיל חולין דף פג:) משום שחיטה שאינה ראויה שאסורים בהנאה:"],[4,"שחטה ואחר כך הקדישה חייב לכסות","דחיובא דחייל עליה לא פקע:"],[5,"רב אמר","לתרוצי למתני':"],[5,"במקדיש פירות שובכו","גוזלות שובכו למזבח לעולת נדבה ואחר כך כשגדלו אותן פירות מרדו ויצאו וקננו במקום אחר דמעיקרא כי אקדשינהו דידיה הוו וחל הקדש עלייהו והשתא דמצאן לאו מזומן הוא ואי הוו חולין הוו מיחייבי. והאי דנקט פירות ולא אמר מקדיש שובכו עצמו משום דיונים אינן ראויין אלא כשהן קטנים ורב לא אמר למילתיה אלא בקדשי מזבח:"],[6,"דקא מוקים ליה אפילו בקדשי בדק הבית","ואשמועינן רבותא דאע\"ג דקדושת דמים בעלמא הוא פטור מלשלח כדאמרן טעמא שאתה מצווה להביאו לידי גזבר:"],[7,"לא פקעה קדושתייהו","במרידתן לא יצאו מכח הקדש:"],[7,"פקעה קדושתייהו","ומיחייבי בשילוח:"],[8,"לה' הארץ","אינן אבודין שבכל מקום שהם של הקדש הן:"],[11,"הא מקמי דשמעיה מר' יוחנן רבו","הוה קים ליה כיון דמרדה פקעה לה קדושתה ובתר דשמעיה מרבי יוחנן דתריץ ליה לה' הארץ ומלואה קבלה ממנו ומשום הכי פטור במקדיש ואבד:"],[12,"הא דאמר הרי עלי","להביאו וכשהפרישה אחר כך נגנבו ואבדו אע\"ג דבי גזא דרחמנא הוא לא קיים נדרו:"],[14,"נדר האומר הרי עלי עולה","ואח\"כ הפריש בהמה ואמר הרי זו לנדרי אם מתה חייב באחריותה הואיל ומעיקרא ארכבה אכתפיה:"],[15,"דמיחסר הקרבה","דכי אמר עלי הכי קאמר עלי להביאו לעזרה אבל בדק הבית גמרו בהפרשתו ואי משום דלא הביאו ליד גזבר הכל גזברים הן דלה' הארץ:"],[16,"ובית זה קרבן","לבדק הבית שאף הן נקראים קרבן כענין שנאמר (במדבר לא) ונקרב את קרבן ה' איש אשר מצא כלי זהב וקדושת דמים הם:"],[16,"שור זה עלי עולה","אע\"ג דאמר זה כיון דקאמר עלי עלי להביאו קאמר וכן בבית לבדק הבית למוכרו להביא דמיו ליד גזבר:"],[17,"אבל היכא דאיתנהו","כגון מעות שאבדו בי גזא דרחמנא אתנהו ואם הוציאן הגנב הוא מעל ועליו לשלמן להקדש:"],[18,"בערכין","האומר ערכי עלי והפריש ערכו:"],[18,"דלא מיתמר ליה בלא עלי","דלא אפשר למימר הרי זה בלשון ערך דהא עדיין לא קבל חובת ערך עליו:"],[19,"דאי נימא ערכי","ולא עלי אמאן רמי האי נדר לשלומי:"],[19,"אם אמר ערך פלוני","ולא אמר עלי אמאן רמי:"],[20,"ועוד תניא","דחייב באחריותו:"],[20,"ונתן את הערכך","בפודה שדה מקנה מן ההקדש כתיב וחשב לו הכהן את מכסת הערכך עד שנת היובל ונתן את הערכך הו\"ל למכתב ונתן אותו או ונתנו מה ת\"ל הערכך ש\"מ אערכין קמהדר:"],[20,"לפי שמצינו בהקדשות ומעשר שני שהן מתחללין על המעות","כשהפריש פדיונן ואבד אינו חייב באחריותן דהא כתיב ויסף חמישית כסף ערכך עליו והיה לו ולא כתיב ביה נתינה אלא משהפרישו ואמר הרי זה מחולל על זה נקרא ערך להקדיש דמיו ויצא לחולין ההקדש:"]],[[8,"כיון דמרדו פקעה קדושתייהו","שמעינן מהכא דאווזים ותרנגולים של חולין שמרדו בבעליהם והלכו להן הוו הפקר והמחזיק בהן זכה דהא הכא היינו טעמא כיון דמרדו הוו הפקר וחייבין בשלוח:"],[17,"דוקא מת ונפל דליתנהו","לאו דוקא נקט מת דהא שור אפילו נגנב או נאבד נמי חייב באחריותו שהוא קדשי המזבח ולרבי יוחנן נפל נמי לאו דוקא:"],[20,"לפי שמצינו בהקדשות ומעשר שני כו'","תימה באיזה הקדש מיירי אי דאמר הרי זה מאי איריא דנקט לאחר שנתחללו אפילו הקדש עצמו נגנב או נאבד אין חייב באחריותו אלא על כרחך דאמר עלי אף על גב דבהקדש גופיה חייב באחריותו כיון שנתחלל אינו חייב באחריות המעות ואם כן מה קאמר יכול אף זה כן היאך דומה ערך להקדש שנתחלל:"]]],[["יכול אף זה כן ת\"ל ונתן את הערכך וגו' חולין עד שיבאו לידי גזבר","אלא אי איתמר הכי איתמר אמר רב המנונא הכל מודים בערכין דאע\"ג דלא אמר עלי מיחייב דכתיב (ויקרא כז, כג) ונתן את הערכך חולין הן בידך עד שיבאו לידי גזבר:","חומר בכסוי וכו': תנו רבנן (דברים כב, ו) כי יקרא קן צפור לפניך מה ת\"ל","לפי שנאמר (דברים כב, ז) שלח תשלח את האם ואת הבנים תקח לך יכול יחזור בהרים וגבעות כדי שימצא קן ת\"ל כי יקרא במאורע לפניך","קן מ\"מ צפור טהורה ולא טמאה לפניך ברשות היחיד בדרך ברשות הרבים באילנות מנין ת\"ל בכל עץ בבורות שיחין ומערות מנין ת\"ל או על הארץ","וכי מאחר שסופנו לרבות כל דבר לפניך בדרך למה לי לומר לך מה דרך שאין קנו בידך אף כל שאין קנו בידך מכאן אמרו יוני שובך ויוני עלייה שקננו בטפיחין ובבירות ואווזין ותרנגולין שקננו בפרדס חייב בשילוח אבל קננו בתוך הבית וכן יוני הרדסיאות פטור משילוח","אמר מר מה דרך שאין קנו בידך אף כל שאין קנו בידך הא למה לי מכי יקרא נפקא כי יקרא פרט למזומן ועוד לפניך למה לי","אלא לפניך לאתויי שהיו לפניך ומרדו בדרך כדרב יהודה אמר רב דאמר רב יהודה אמר רב מצא קן בים חייב בשילוח שנאמר (ישעיהו מג, טז) כה אמר ה' הנותן בים דרך וגו'","אלא מעתה מצא קן בשמים דכתיב (משלי ל, יט) דרך נשר בשמים הכי נמי דמיחייב בשילוח הקן דרך נשר איקרי דרך סתמא לא איקרי","אמרי ליה פפונאי לרב מתנה מצא קן בראשו של אדם מהו אמר (שמואל ב טו, לב) ואדמה על ראשו משה מן התורה מנין (בראשית ו, ג) בשגם הוא בשר","המן מן התורה מנין (בראשית ג, יא) המן העץ","אסתר מן התורה מנין (דברים לא, יח) ואנכי הסתר אסתיר מרדכי מן התורה מנין דכתיב (שמות ל, כג) מר דרור ומתרגמינן מירא דכיא:","ואיזהו שאינו מזומן וכו': ר' חייא ור' שמעון חד תני הדרסיאות וחד תני הרדסיאות מאן דתני הרדסיאות על שם הורדוס ומאן דתני הדרסיאות על שם מקומן","אמר רב כהנא לדידי חזיין וקיימן שיתסר דרי בפתי מילא והוה קרא קירי קירי הוה חד מינייהו דלא הוה קרי קירי קירי אמרה לה חברתה סומא אמרי קירי קירי אמרה סומא אמרי קירי בירי אתיוה ושחטוה","א\"ר אשי אמר לי [ר'] חנינא מילין מילין ס\"ד אלא אימא במילין:","עוף טמא פטור מלשלח: מנה\"מ א\"ר יצחק דאמר קרא כי יקרא קן צפור לפניך עוף משמע לן בין טהור בין טמא צפור טהור אשכחן דאיקרי צפור טמא לא אשכחן דאיקרי צפור","תא שמע (דברים ד, יז) תבנית כל צפור כנף מאי לאו צפור בין טהור בין טמא כנף חגבים לא צפור טהור כנף טמא וחגבים","ת\"ש (תהלים קמח, י) החיה וכל בהמה רמש וצפור כנף מאי לאו צפור בין טהור בין טמא וכנף חגבים לא צפור טהור כנף טמא וחגבים","תא שמע (בראשית ז, יד) כל צפור כל כנף מאי לאו כדמקשינן לא כדמשנינן","תא שמע (יחזקאל לט, א) ואתה בן אדם אמור לצפור כל כנף מאי לאו כדאקשינן לא כדשנינן","ת\"ש"],[[0,"יכול אף","ערכין משהפרישן יפטר:"],[0,"תלמוד לומר ונתן את הערכך קדש","אין ערכין קדושין עד שעת נתינה וקרא הכי מדריש וחשב לו הכהן למקדיש את שדה מקנה את מכסת הערכך ושבקיה והאי את הערכך קאי אערכין דאילו בפדיון הקדש כתיב לעיל מיניה והיה לו בלא שום נתינה:"],[3,"ה\"ג לפי שנאמר שלח תשלח","ב' פעמים שומע אני לחזור אחר המצוה הזאת עד שתבא לידו:"],[3,"ת\"ל כי יקרא במאורע","הכתוב מדבר לכשיקרא:"],[4,"קן מ\"מ","אפילו באפרוח אחד או בביצה אחת כדתנן במתניתין:"],[4,"צפור טהורה ולא טמאה","לקמן מפרש לה ר' יצחק עוף משמע בין בטמא בין בטהור אבל צפור לא אשכחן בטמאים אלא בטהורים:"],[4,"לפניך","משמע ברה\"י כגון בפרדס ובשדה שאינה משתמרת דלא קניא ליה חצרו דלאו מזומן הוא:"],[4,"בדרך","להביא רה\"ר:"],[5,"שאין קנו בידך","אין קן מזומן לך ואין קנוי לך:"],[5,"יוני שובך","ויוני מדבריות שקננו בשובך ובשלהי פרקין פריך הא כיון דחצרו קונה לו הביצים מזומן הוא:"],[5,"טפיחים","שנותנין בהן קדרות קטנות בחומה וקורין בוייל\"ש:"],[5,"ובבירות","דירות ומגדל עיר:"],[5,"שקננו בפרדס","שמרדו דהשתא אין קנו בידך:"],[6,"ועוד לפניך למה לי","משום רה\"י דפרדס הואיל וסופנו לרבות את הכל:"],[7,"אלא לפניך","מיבעי ליה לחייב את שהיו כבר שלו ומרדו:"],[7,"בדרך","נמי מיבעי ליה לכדרב יהודה:"],[7,"קן בים","ששטף הים את האילן והיה קן בראשו חייב לשלח דים נמי איקרי דרך:"],[8,"קן בשמים","עוף נושא קן באויר:"],[8,"דרך סתמא לא איקרי","אבל ים איקרי דרך סתמא הנותן בים דרך:"],[9,"ואדמה על ראשו","אע\"פ שהיה בראשו לא אבדה את שמה ש\"מ אדם גופיה אדמה הוא מדלא אבדה את שמה דלא קרייה עפר והשתא נמי על הארץ קרינא ביה:"],[9,"","ועוד זה שאלו ממנו מנין למשה רמז קודם שבא שסופו לבא:"],[9,"בשגם הוא","בשגם בגימטריא כמו משה וכתיב שם והיו ימיו מאה ועשרים שנה וכך היו ימי חיי משה כלומר עתיד לבא בשגם משה מן הנולדים וכן ימיו:"],[10,"מנין","למעשה המן:"],[10,"המן העץ","יתלה על העץ:"],[11,"למעשה אסתר","הסתר אסתיר בימי אסתר יהיה הסתר פנים ומצאוהו צרות רבות ורעות:"],[11,"מנין","לגדולת מרדכי:"],[11,"מר דרור","וקרי ליה ראש לבשמים לצדיקים ואנשי כנסת הגדולה:"],[12,"","חד תני הדרסיאות וחד תני הרדסיאות:"],[12,"הורדוס","התחיל להתעסק בגדולן:"],[13,"לדידי חזיין לי","הנך שנשארו מבני בניהם של יוני הורדוס:"],[13,"וקיימא שית סרי דרי","ט\"ז שורות:"],[13,"בפתי מילא","כל שורה ארכה ברחב מיל ואמרן קירי קרי אדוני אדוני. קירי הוא לשון אדון בירי הוא עבד כדאמר בעירובין (דף נג:) גבי בני גליל שאין מדקדקים בלשונם ההוא דאתאי לקמיה (דרבי ינאי) [דדיינא] דבעא למימר מרי קירי טבלא הוית לי וגנבוה ממני ואמרה מרי בירי טפלא הוית לי וגנבוך מין:"],[13,"סומא","שוטה בלא ראות:"],[13,"אימא קירי","כמו שאנו אומרים:"],[13,"אמרה לה","איהי לחברתה:"],[13,"סומא ואימא קירי בירי","לאותו שאת קורא אדון עבד הוא על שהיה הוא עבד:"],[13,"אתיוה","עבדים שנשארו מעבדי הורדוס ושחטוה:"],[14,"אמר לי ר' חנינא מילין","דברי רוח הן שלא דברו מעולם:"],[14,"מילין ס\"ד","והאמר רב כהנא לדידי חזי לי והרי רב כהנא מעיד על הדבר ואי לאו דקושטא הוא לא הוה אמר:"],[14,"אלא במילין","על ידי כשפים מלומדות לדבר אותן עופות:"],[15,"עוף משמע בין טמא וכו'","אי הוה כתיב עוף הוה משמע בין טמא בין טהור כדכתיב (דברים יד) כל עוף טהור תאכלו וכתיב כל שרץ העוף טמא הוא לכם וכתיב (ויקרא יא) תשקצו מן העוף:"],[16,"ת\"ש","דהזהיר הכתוב שלא לעשות עבודה זרה דמות צפור וע\"כ אטמאים נמי מזהיר ומהיכא משתמע מיניה לאו מצפור משתמעי בין טמאין בין טהורין וכנף לאתויי חגבים:"],[16,"לא צפור טהורה","משתמעי מיניה וכנף לאתויי טמאים וחגבים:"],[17,"תא שמע","החיה וכל בהמה יהללו את שם ה' וע\"כ צפרים טמאים נמי משבחי קמיה ומהיכא אדכרינהו דוד לאו מצפור וכנף לאתויי חגבים:"]],[[2,"שכסוי הדם נוהג כו'","תימה אמאי לא תני שכסוי הדם נוהג בזכרים ונקבות ושלוח הקן אינו נוהג אלא בנקבות:"],[7,"בדרך כדרב יהודה כו'","וא\"ת אמאי איצטריך ריבויא לקן שבים דאי משום דכתיב על הארץ א\"כ לא ליכתוב בדרך ולשתוק מעל הארץ ומיהו על הארץ איצטריך למעוטי נשר בשמים אבל קשה דא\"כ מאי פריך בסמוך מצא קן בשמים הכי נמי דמחייב ומאי קושיא הא כתיב על הארץ ונראה דפריך דקן בשמים נחייב מבדרך ומעל הארץ נמעט שבים במה ראית:"],[16,"תא שמע תבנית כל צפור כנף וגו'","וא\"ת והא כתיב (תהלים יא) איך תאמרו לנפשי נודי הרכם צפור י\"ל דפשיטא דדוד לעוף טהור היה מדמה עצמו וכן (שם קכד) כצפור נמלטה מפח יוקשים (ישעיהו לא) כצפרים עפות וא\"ת והא כתיב (תהלים פד) גם צפור מצאה בית דאיירי נמי בטמא דאטו טהור מצא טמא לא מצא ומיהו אפשר דמיירי בטהור כדמוכח סיפא דקרא דכתיב ודרור קן לה וצפור דרור היא טהורה כדמוכח באלו טריפות (לעיל חולין דף סב.) והא דכתיב (תהלים קד) אשר שם צפרים יקננו חסידה וגו' אפשר דבכלל חסידה הם כל הטמאים וצפרים היינו טהורה:"]]],[["(דניאל ד, ט) ובענפוהי ידורן צפרי שמיא צפרי שמיא איקרו צפרי סתמא לא איקרו","ת\"ש (דברים יד, יא) כל צפור טהורה מכלל דאיכא טמאה לא מכלל דאיכא אסורה","מאי היא אי טרפה בהדיא כתיב ואי בשחוטה דמצורע מסיפא דקרא נפקא (דברים יד, יב) וזה אשר לא תאכלו מהם לרבות שחוטת מצורע","לעולם בשחוטה דמצורע ולעבור עליו בעשה ובלא תעשה ולוקמה בטרפה ולעבור עליו בעשה ולא תעשה דבר הלמד מענינו ובענינא דשחוטה כתיב","ת\"ש (ויקרא יד, ד) שתי צפרים חיות מאי חיות לאו שחיות בפיך מכלל דאיכא לאו שחיות בפיך לא מאי חיות שחיין ראשי אברים שלהן","ת\"ש מסיפא טהורות מכלל דאיכא טמאות לא מכלל דאיכא טרפות","טרפות מחיות נפקא הניחא למאן דאמר טרפה חיה אלא למ\"ד טרפה אינה חיה מאי איכא למימר ועוד בין למ\"ד טרפה חיה בין למ\"ד אינה חיה מדתנא דבי ר' ישמעאל נפקא","דתנא דבי רבי ישמעאל נאמר מכשיר ומכפר בפנים ונאמר מכשיר ומכפר בחוץ","מה מכשיר ומכפר האמור בפנים עשה בו מכשיר כמכפר אף מכשיר ומכפר האמור בחוץ עשה בו מכשיר כמכפר","אלא אמר רב נחמן בר יצחק למעוטי צפורי עיר הנדחת למאי אי לשילוח לא אמרה תורה שלח לתקלה אלא לשחיטה","רבא אמר למעוטי שלא לזווג לה אחרת קודם שלוחיה למאי אי לשחיטה הא בעיא שילוח אלא לשילוח","רב פפא אמר לצפורים שהחליפו (בצפורי) עבודה זרה דכתיב (דברים ז, כו) והיית חרם כמוהו כל מה שאתה מהייה הימנו כמוהו למאי אי לשילוח לא אמרה תורה שלח לתקלה אלא לשחיטה","רבינא אמר הכא במאי עסקינן בעוף שהרג את הנפש היכי דמי אי דגמר דינא בר קטלא הוא אלא קודם גמר דינא ולמאי אי לשילוח בעי לאתויי לבי דינא וקיומי (דברים יג, ו) ובערת הרע מקרבך אלא לשחיטה:","עוף טמא רובץ על ביצי עוף טהור: בשלמא עוף טמא רובץ על ביצי טהור בעינן צפור וליכא אלא עוף טהור רובץ על ביצי עוף טמא הא צפור הוא","כדאמר רב כהנא (דברים כב, ז) תקח לך ולא לכלביך הכא נמי תקח לך ולא לכלביך","והיכא איתמר דרב כהנא אהא דתניא אם טרפה חייב בשילוח אפרוחים טרפות פטור משילוח מנא הני מילי אמר רב כהנא דאמר קרא תקח לך ולא לכלביך","ולהקיש אם טרפה לאפרוחים מה אפרוחים טרפות פטור משילוח אף אם טרפה נמי פטור מלשלח"],[[0,"ובענפוהי ידורן צפרי שמיא","הכא לא כתיב כנף וע\"כ עופות טמאין נמי מתקבצין באילנות ומשתמעי כולהו מצפור:"],[1,"מדקאמר צפור טהורה מכלל דאיכא טמאה","דאי אין טמאים בכלל צפור לכתוב קרא כל צפור תאכלו: ומשני האי טהור לאו למעוטי טמאה אתא אלא למעוטי אסורה ומן הטהורים היא וטרפה:"],[2,"והא בהדיא כתיב","(ויקרא כב) נבלה וטרפה לא יאכל לטמאה בה ובעוף טהור מיתוקם קרא בת\"כ שיהא מטמא בבית הבליעה:"],[2,"אי שחוטה דמצורע","ושחט את הצפור האחת וקי\"ל בע\"ז (דף עד.) ובקדושין (דף נז.) דאסורין בהנאה:"],[2,"וזה אשר לא תאכלו מהם","יתירא הוא מהם מן הטהורין דהא אטהורין דלעיל מיניה קאי:"],[2,"לרבות שחוטה דמצורע","אבל המשולחת מותרת דלא אמרה תורה שלחנה כדי שיכשלו בה אחריני שיהו צדין ואוכלין אותה בני אדם אלא ודאי מותר:"],[3,"עשה","טהורה תאכלו ולא האסורה כגון שחוטה דמצורע ולאו הבא מכלל עשה עשה:"],[3,"ואימא לרבות טרפה","כלומר אמאי ניחא לך לאוקומי עשה בשחוטה דמצורע טפי מטרפה:"],[3,"דבר הלמד מענינו","זה אחד מי\"ג מדות מקרא שכתוב סתם ואין אנו יודעין במה מדבר הוי לומדו מענינו:"],[3,"והא בענינא דשחוטה כתיב","טהורה תאכלו והא ודאי לא אכיל לה אלא שחוטה ועלה כתיב וזה אשר לא תאכלו מן השחוטה:"],[4,"שתי צפרים חיות מאי חיות לאו חיות לפיך","ראויות לפיך טהורות ומדכתיב צפרים חיות מכלל דאיכא דשמייהו צפרים ולא חיות נינהו דהוו טמאות:"],[4,"שחיין ראשי אברים שלהן","למעוטי מחוסרות אבר:"],[5,"לאו מכלל דאיכא טמאות","בלשון קושיא: ומשני לא מכלל דאיכא אסורות טרפות ומעטינהו דלא ליתכשרו לטהרת מצורע אע\"ג דלאו קרבן נינהו אלא מחוץ למחנה שוחטה אל כלי חרס:"],[6,"מחיות נפקא","ולא טרפה דאינה חיה:"],[6,"הניחא","הא דמצרכת קרא אחרינא למאן דאמר טרפה חיה:"],[6,"ועוד","טרפה מדתנא דבי רבי ישמעאל מבנין אב נפקא:"],[7,"מכשיר בפנים","אשם מצורע וחטאות מחוסרי כפרה דזבין ויולדות שאינן באין אלא להכשירן בקדשים:"],[7,"מכפר בפנים","כל חטאות ואשמות:"],[7,"מכשיר בחוץ","צפרי מצורע שהן לטהר:"],[7,"מכפר בחוץ","שעיר המשתלח:"],[8,"עשה בו מכשיר כמכפר","בכל מיני כשרות וטהרה שהרי גם המכשירין קרבים האמורין שלהן:"],[8,"אף בחוץ עשה מכשיר","צפרים כמכפר שעיר המשתלח דאסור במום דבעי ראוי לשם שבאיזה שיפול הגורל לשם יהיה ראוי למזבח:"],[9,"אמר רב נחמן","טהורות למעוטי צפורים של עיר הנדחת:"],[9,"ולמאי","להי מינייהו איצטריך קרא להך דהא משלח פשיטא דשל עיר הנדחת לאו בר שילוח הוא דלא אמרה תורה שלח לתקלה דממון עיר הנדחת אסור ואם ישלחנה יהיו בני אדם צדין אותה לאחר זמן:"],[9,"אלא בשחוטה","אפילו ההיא דשחוטה היא ולא אכלי לה ויכול לשורפה אחר שחיטה לא תיתי מעיר הנדחת:"],[10,"רבא אמר","להכי אתי טהורות שלא יזווג לה אחרת שאם בא לידו מצורע אחר לאחר שיטהר את זה לא יאמר הכהן הבא אחרת וזווגה לחיה של מצורע ראשון דהכי משמע טהורות מכלל דאיכא אסורות ומאי ניהו הנשארת דמצורע:"],[10,"ולמאי","בעית לה דמצורע:"],[10,"אי לשחיטה הא בעיא שילוח","משום מצורע קמא ופשיטא דאסור:"],[10,"אלא לשילוח","ותיפוק ליה לשילוח דתרוייהו:"],[11,"רב פפא אמר","טהורות למעוטי צפרים שהחליפן ולקחן מן העובד כוכבים בדמי עבודה זרה שמכר לו:"],[11,"ולמאי","קבעי לה דמבעי קרא למיסרה:"],[11,"אי לשילוח","פשיטא דאסור:"],[12,"בר קטלא הוא","ופשיטא דאינו ראוי לשלוח ולא לשחיטה דהא דינו בסקילה:"],[12,"אלא לשחיטה","דאי משום ובערת הרע הרי מבוער מן העולם הוא:"],[13,"רבי אליעזר מחייב לשלח","אע\"פ שאין הביצים שלו הואיל ומנהגו בכך ששוכן על ביצים אחרים ועוף טהור הוא ולא זהו שקורין קוקו\"א:"],[13,"קורא זכר","אבל נקבה אפילו רבנן מודו כדמפרש בגמרא טעמא דרבי אליעזר:"],[15,"אם טרפה","אמן של אפרוחים טרפה חייב לשלח אבל אפרוחים טרפות אינו חייב לשלח את האם:"]],[[6,"טרפות מחיות נפקא","תימה הא דרשינן מיניה שחיין ראשי אברים וליכא למימר דה\"ק דטרפה ידעינן מכל שכן דמחוסר אבר דאמעיט מחיות דאכתי אימא דקרא למעוטי טרפה אתא ולא למחוסר אבר וע\"ק דקאמר הניחא למ\"ד טרפה חיה דמשמע לדידיה לא ממעטינן טרפה מחיות ובפ\"ק דע\"ז (דף ה:) אמרינן מנין למחוסר אבר שאסור לבני נח שנאמר מכל החי אמרה תורה הבא בהמה שחיין ראשי אברים שלה ופריך והא מבעי ליה למעוטי טרפה טרפה מלהחיות זרע נפקא הניחא למ\"ד טרפה אינה יולדת אלא למאן דאמר טרפה יולדת כו' אלמא ממעט טרפה מקרא דמכל החי אפילו למ\"ד טרפה חיה דלמ\"ד דיולדת כ\"ש דחיה דאפילו למ\"ד דחיה מצי סבר דאינה יולדת כדמשמע באלו טרפות (לעיל חולין דף נז:) ומשמע נמי התם דליכא לאוקומי קרא אתרוייהו וי\"ל דהתם דלקיום העולם אין סברא למעט מחוסר אבר אלא טרפה דאע\"ג דחיה אינה חיה זמן מרובה אבל הכא איכא לאוקומי אתרוייהו ולמ\"ד טרפה חיה לא מסתבר למעט מיניה טרפה כיון דאיכא לאוקומי אמחוסר אבר או שמא יש לחלק בין חי לחיות:"],[9,"למעוטי צפרי עיר הנדחת","תימה הא נמי נפקא מדתנא דבי רבי ישמעאל דכיון שאסורים בהנאה לא קרינן ביה ממשקה ישראל ואפשר דלא ממעטינן ממשקה ישראל אלא דומיא דערלה וכלאי הכרם שלא היה להם שעת הכושר כדאמר פ\"ק דמנחות (דף ו.) והילכך אפילו לכפרה מותרות דאי משום הנאה מצות לאו ליהנות ניתנו וצ\"ע בבהמת עיר הנדחת אם עבר והקדישה והקריבה אם הוא קרבן כשר כיון דלשרפה קיימא:"],[10,"שלא יזווג לה אחר","צ\"ע היאך משמע זה מטהורות וא\"ת וחיות ל\"ל וי\"ל דרבה ורב נחמן בר יצחק לא פליגי אהדדי ותרי מיעוטי חד לדמר וחד לדמר:"],[11,"לצפרים שהחליפן בעבודה זרה","כאן נמי צ\"ל דלכפרה כשרות דאל\"כ תיפוק ליה מדתני דבי רבי ישמעאל ומשום הכי נקט שהחליפם בעבודה זרה אבל צפרים הנעבדים פשיטא דאסורין דאין ראויין לכפרה:"]]],[["אם כן צפור למעוטי עוף טמא ל\"ל","והתניא אם אפרוחין טרפה חייב בשילוח אמר אביי הכי קאמר אפרוח שאמן טרפה חייב בשילוח","בעי רב הושעיא הושיט ידו לקן ושחט מיעוט סימנים מהו","מי אמרינן כיון דאילו שביק להו מטרפי בעינן לך ולא לכלביך או דלמא כיון דבידו למגמר שחיטה תקח לך קרינא ביה וחייב בשילוח תיקו","בעי ר' ירמיה מטלית מהו שתחוץ כנפים מהו שיחוצו","ביצים מוזרות מהו שני סדרי ביצים זו על גב זו מהו זכר על גבי ביצים ונקבה על גבי זכר מהו תיקו","בעי ר' זירא יונה על ביצי תסיל מהו תסיל על ביצי יונה מהו","אמר אביי ת\"ש עוף טמא רובץ על ביצי עוף טהור וטהור רובץ על ביצי עוף טמא פטור משילוח הא טהור וטהור חייב דלמא בקורא:","קורא זכר רבי אליעזר מחייב וחכמים פוטרין: אמר רבי אבהו מאי טעמא דרבי אליעזר אתיא דגירה דגירה כתיב הכא (ירמיהו יז, יא) קורא דגר ולא ילד וכתיב התם (ישעיהו לד, טו) ובקעה ודגרה בצלה","אמר ר\"א מחלוקת בקורא זכר אבל בקורא נקבה דברי הכל חייב פשיטא קורא זכר תנן מהו דתימא רבנן אפילו קורא נקבה פטרי והא דקתני זכר להודיעך כחו דרבי אליעזר קמשמע לן","ואמר רבי אלעזר מחלוקת בקורא זכר אבל בזכר דעלמא דברי הכל פטור פשיטא קורא זכר תנן מהו דתימא רבי אליעזר אפי' זכר דעלמא מחייב והאי דקתני קורא זכר להודיעך כחן דרבנן קמ\"ל","תניא נמי הכי זכר דעלמא פטור קורא זכר ר\"א מחייב וחכמים פוטרין:","\u0001מתני׳\u0002 היתה מעופפת בזמן שכנפיה נוגעות בקן חייב לשלח אין כנפיה נוגעות בקן פטור מלשלח אין שם אלא אפרוח אחד או ביצה אחת חייב לשלח שנאמר קן קן מכל מקום","היו שם אפרוחים מפריחים או ביצים מוזרות פטור מלשלח שנאמר (דברים כב, ו) והאם רובצת על האפרוחים או על הביצים מה אפרוחים בני קיימא אף ביצים בני קיימא יצאו מוזרות ומה הביצים צריכין לאמן אף האפרוחין צריכין לאמן יצאו מפריחין:","\u0001גמ׳\u0002 תנו רבנן רובצת ולא מעופפת יכול אפי' כנפיה נוגעות בקן ת\"ל רובצת מאי תלמודא מדלא כתיב יושבת","אמר רב יהודה אמר רב היתה יושבת בין שני רובדי אילן רואים כל שאם תשמט נופלת עליהם חייב לשלח ואם לאו פטור","מיתיבי היתה יושבת ביניהן פטור מלשלח על גביהן חייב לשלח היתה מעופפת אפי' כנפיה נוגעות בקן פטור מלשלח","מאי לאו על גביהן דומיא דביניהן מה ביניהן דנגעה בהו אף על גביהן דנגעה בהו אבל רובדי אילן פטור","לא על גביהן דומיא דביניהן מה ביניהן דלא נגעה עלייהו אף על גביהן דלא נגעה עלייהו והיינו רובדי אילן","ה\"נ מסתברא דאי סלקא דעתך רובדי אילן פטור אדתני היתה מעופפת אפי' כנפיה נוגעות בקן פטור מלשלח ליתני רובדי אילן וכ\"ש מעופפת","מעופפת איצטריך ליה דאפי' כנפיה נוגעות בקן פטור מלשלח","והאנן תנן בזמן שכנפיה נוגעות בקן חייב לשלח אמר ר' ירמיה כי קתני מתניתא בנוגע מן הצד","איכא דאמרי לימא מסייע ליה היתה יושבת ביניהן פטור מלשלח על גביהן חייב לשלח היתה מעופפת אפי' כנפיה נוגעות בקן פטור מלשלח","מאי לאו על גביהן דומיא דביניהן מה ביניהן דלא נגעה עלייהו אף על גביהן דלא נגעה עלייהו והיינו רובדי אילן","לא על גביהן דומיא דביניהן מה ביניהן דנגעה בהו אף על גביהן דנגעה בהו אבל רובדי אילן פטור אי הכי אדקתני סיפא היתה מעופפת אפי' כנפיה נוגעות בקן פטור"],[[0,"א\"כ","דאמן נמי מקשת להו ומתקח לך ולא לכלביך ממעט האם כמו האפרוחים אם טמאה נמי מהתם אימעיט:"],[1,"והתניא אם אפרוחים טרפה חייב לשלח","קס\"ד דה\"ק אמן של אפרוחים שהן טרפות והאם כשרה חייב לשלח ולא דרשינן תקח לך ולא לכלביך:"],[2,"מיעוט סימנים","של אפרוחין תחת האם:"],[2,"מהו","לחייבו בשלוח האם כיון שבידו לגמור את השחיטה תקח לך קרינא ביה וחייב לשלח או דילמא השתא מיהת כל זמן שלא גמר בהם סימנים פטור מלשלח ונוטל את האם בהיתר ואח\"כ גומר שחיטה:"],[4,"מטלית","פרוסה על הביצים והאם רובצת עליה מי הויא חציצה דלא ליבעי שלוח דלא קרינא ביה רובצת או לא:"],[4,"כנפים","נוצה תלושה:"],[5,"ביצים מוזרות","שאין אפרוח בא מהן כדאמרי' במתני' דלא מיחייבי בשלוח:"],[5,"מהו שיחוצו","אם תמצא לומר ביצים מוזרות חוצצים ב' סדרי ביצים בני קיימא זה ע\"ג זה מהו אם נתכוין ליטול התחתונים מי הוו אמצעים חציצה ופטור מלשלח או לא:"],[5,"","זכר לאו בר שלוח הוא כדאמרינן לקמן אבל זכר דברי הכל פטור דהא אם כתיב ובקורא הוא דמחייב ר' אליעזר משום דכתיב ביה דגירה כדלקמן:"],[6,"תסיל","עוף טהור ודומה ליונה:"],[7,"דלמא","הא דתני בטהור וטהור חייב בקורא נקבה דמנהגו בכך ומודו בקורא נקבה אפי' אין הביצים שלה כדלקמן דהואיל ודרכה הוא לגדלן והאם רובצת קרינא ביה וכי רובצת על ביצת עוף טמא פטור דכתיב תקח לך ולא לכלביך אבל עוף אחר בטלה דעתו ואינה בשלוח:"],[8,"ובקעה ודגרה","מה התם דגירה מעליא דבמינו משתעי קרא אף הכא דגירה מעליא אבל הקורא נקבה אפילו אין הביצים שלה חייב לשלם דהאם קרינא ביה הואיל ומנהגו בכך אבל זכר דעלמא דברי הכל פטור והאם רובצת כתיב ולא האב רובץ ובקורא הוא דמחייב ר' אליעזר משום דכתיב ביה דגירה לא שנא זכר ול\"ש נקבה:"],[10,"כחן דרבנן","דאפילו בקורא פטרי אי לאו דנקבה היא אע\"ג דכתיב ביה דגירה אם בעינן ולא זכר:"],[13,"מתני' מפריחים","גדולים:"],[15,"גמ' היתה יושבת בין שני רובדי אילן","והביצים תחתיה אבל הענפים סומכים ומגביהים אותה באויר:"],[15,"כל","שאילו ידחה זה מזה תשמט האם ותפול עליהן חייב ואם נופלת לצדדין פטור:"],[16,"ביניהן","ביצה מכאן וביצה מכאן:"],[16,"אפילו כנפיה נוגעות בהן פטור","ולקמן מפרש לה מן הצד:"],[17,"מה ביניהן אפילו נגעה בהן","ואשמועינן פטור דעל בעינן:"],[17,"אף על גביהן","דקתני חייב בדנגעה בהו וממתני' ליכא לאותובי אדרב דבעי נוגעים משום דמתניתין במעופפת הא בין שני רובדי אילן רובצת קרינא ביה:"],[18,"מה ביניהן דלא נגעה עלייהו אף על גביהן דלא נגעה עלייהו","מלעיל ושוב אין כאן נגיעה דאי נמי נגעה מן הצדדין אינה נגיעה דעל בעינן ואפילו הכי קתני חייב הואיל ועליהן רובצת:"],[19,"ליתני רובדי אילן","ואע\"ג דיושבת במקומה תחתיה דפטור וכ\"ש מעופפת דאינה רובצת:"],[21,"מן הצד","שנוגעת בצידיהן ולא על גביהן:"],[23,"אף על גביהן דלא נגעה עלייהו","ושוב אין כאן נגיעה ואפילו הכי הואיל ויושבת חייב דרובצת קרינא ביה:"],[24,"מה ביניהן דנגעה בהו","דאי לא נגעה לא איצטריך לאשמועינן:"],[24,"אף על גביהן דנגעה בהו","מלמעלה:"]],[[1,"","הכי גרסינן וכן נמצא בספר ישן והתניא אם אפרוח טרפה חייב וקא סלקא דעתך דטרפה קאי אאפרוח ומשני הכי קאמר אפרוח שאמו טרפה אבל לספרים דגרסי אפרוחים טריפות אינו מיושב:"],[5,"שני סדרי ביצים זה על גב זה מהו","פי' אי הוי חציצה ויכול ליקח התחתונים קודם שילוח ואי לא הויא חציצה אסור ליקח עד שישלח כדאמרינן לקמן:"],[18,"מה ביניהן דלא נגע עלייהו","תימה הא דמחייב לעיל ברובדי אילן היכי מיירי אי אפילו בלא נגע מן הצד כלל מאי משני הכא אף על גביהן דלא נגעה עלייהו והיינו רובדי אילן משמע הא מן הצד נגעה אכתי תקשה דהא חייב ברובדי אילן לעיל אע\"ג דלא נגעה כלל ואי לא מחייב לעיל אלא בנגעה מן הצד דוקא אם כן מאי קאמר בסמוך מעופפת איצטריכא ליה דאפילו כנפיה נוגעות בקן כיון דההוא נוגעים במן הצד אכתי תקשה ליתני רובדי אילן וכ\"ש מעופפת דהא ברובדי אילן מיירי נמי בנוגעים מן הצד:"]]],[["ליתני רובדי אילן וכ\"ש מעופפת מעופפת איצטריך ליה דאפי' כנפיה נוגעות בקן פטור מלשלח","והאנן תנן בזמן שכנפיה נוגעות בקן חייב לשלח אמר רב יהודה כי קתני מתניתין בנוגע מן הצד:","אין שם אפרוח וכו': א\"ל ההוא מרבנן לרבא אימא איפכא אין שם אפרוח אלא אחד או ביצה אחת פטור מלשלח דבעינן אפרוחים או ביצים וליכא","היו שם אפרוחים מפריחים או ביצים מוזרות חייב לשלח שנאמר קן קן מכל מקום אם כן נכתוב קרא והאם רובצת עליהם מאי (דברים כב, ו) והאם רובצת על האפרוחים או על הביצים לאקושי אפרוחים לביצים וביצים לאפרוחים:","\u0001מתני׳\u0002 שלחה וחזרה אפי' ארבעה וחמשה פעמים חייב שנאמר (דברים כב, ז) שלח תשלח את האם אמר הריני נוטל את האם ומשלח את הבנים חייב שנאמר שלח תשלח את האם נטל את הבנים והחזירן לה ואח\"כ חזרה האם עליהן פטור מלשלח:","\u0001גמ׳\u0002 א\"ל ההוא מרבנן לרבא ואימא שלח חדא זימנא תשלח תרי זימנין","א\"ל שלח אפילו מאה פעמים תשלח אין לי אלא לדבר הרשות לדבר מצוה מנין ת\"ל תשלח מכל מקום","א\"ל ר' אבא בריה דרב יוסף בר רבא לרב כהנא אלא טעמא דכתב רחמנא תשלח הא לאו הכי הוה אמינא לדבר מצוה לא עשה ולא תעשה הוא ואין עשה דוחה לא תעשה ועשה","לא צריכא דעבר ושקלה לאם דלאו עבריה עשה הוא דאיכא ליתי עשה ולידחי עשה קמ\"ל","הניחא למאן דתני קיימו ולא קיימו","אלא למאן דתני בטלו ולא בטלו כמה דלא שחטה לא עבריה ללאו","ותו לר' יהודה דאמר שלח מעיקרא משמע אפי' עשה נמי ליכא","אלא אמר מר בר רב אשי כגון שנטלה על מנת לשלח דלאו ליכא עשה הוא דאיכא וליתי עשה ולידחי עשה","מאי אולמיה דהאי עשה מהאי עשה סלקא דעתך הואיל ואמר מר גדול שלום שבין איש לאשתו שהרי אמרה תורה שמו של הקב\"ה שנכתב בקדושה ימחה על המים","והאי מצורע כיון דכמה דלא מטהר אסור בתשמיש המטה דכתיב (ויקרא יד, ח) וישב מחוץ לאהלו שבעת ימים אהלו זו אשתו מכאן שאסור בתשמיש המטה מהו דתימא כיון דאסור בתשמיש המטה ליתי עשה דידיה ולידחי עשה דשלוח הקן קמ\"ל:","\u0001מתני׳\u0002 הנוטל אם על הבנים ר' יהודה אומר לוקה ואינו משלח וחכמים אומרים משלח ואינו לוקה זה הכלל כל מצות לא תעשה שיש בה קום עשה אין לוקין עליה:","\u0001גמ׳\u0002 בעי רבי אבא בר ממל טעמא דרבי יהודה משום דסבר לאו שניתק לעשה לוקין עליו","או דלמא בעלמא סבר לאו שניתק לעשה אין לוקין עליו והכא היינו טעמא משום דקסבר שלח מעיקרא משמע","תא שמע גנב וגזלן ישנן בכלל מלקות דברי רבי יהודה והא הכא דלאו שניתק לעשה הוא דרחמנא אמר (ויקרא יט, יג) לא תגזול (ויקרא ה, כג) והשיב את הגזלה שמע מינה טעמא דר' יהודה משום דקסבר לאו שניתק לעשה לוקין עליו","אמר ליה ר' זירא לאו אמינא לכו כל מתניתא דלא תניא בי"],[[0,"ליתני רובדי אילן","אע\"ג דדמיא לרביצה וכ\"ש מעופפת:"],[3,"","ה\"ג א\"כ ליכתוב והאם רובצת עליהן:"],[3,"לאקושי אפרוחין לביצים","למפטר מפריחים:"],[3,"וביצים לאפרוחים","למפטר מוזרות. ועל כרחך קן מ\"מ לרבות ביצה אחת ואפרוחים וביצים אורחיה דקרא הוא למינקט רבים ברוב קנים:"],[4,"מתני' נטל את הביצים ואח\"כ חזרה האם עליהם פטור מלשלח","דכיון דנטל את הביצים הוה ליה קן מזומן:"],[5,"גמ' ואימא","תשלח לאתויי עוד פעם שניה ותו לא:"],[6,"א\"ל שלח לעולם משמע","ורבוי דתשלח להכי הוא דאתא:"],[6,"אין לי","דצריך שלוח אלא לדבר הרשות:"],[6,"לדבר מצוה","כגון קן יולדת וטהרת מצורע מנין ת\"ל תשלח:"],[7,"הא לאו הכי ה\"א לדבר מצוה","לא בעי שלוח והא שלוח עשה ול\"ת הוא תשלח ולא תקח ואין עשה של ולקח למטהר דוחה את שניהם:"],[8,"לא צריכא דעבר ושקליה","ואשמועינן דחוזר ומשלח ואי לא רבי דבר מצוה ה\"א דהיכא דעבר ונטלה דכבר עבר על לאו דלא תקח תו לא קאי באפיה עשה דטהרת מצורע אלא עשה דשלוח דאכתי בעמוד ושלח קאי ואימא לידחייה. ולקמן פריך מאי אולמיה דעשה דמצורע מעשה דשילוח דנימא דנידחייה דאיצטריך לרבויי:"],[8,"דלאו עבריה","הלאו כבר עבר עליה:"],[9,"הניחא למאן דתני","במסכת מכות (דף טו.):"],[9,"קיימו ולא קיימו","כל מצות ל\"ת שיש בה קום עשה כגון זה שניתק הלאו לעשה דמשמע לא תקח ואם לקחה קיים עשה שבה כשהתרו בו לא תקח ולקחה ושלחה בתוך כדי דבור של התראה פטור ואע\"פ שעבר על לא תקח דלכך נתקו לעשה לומר אם עברת על אזהרה זו עשה זה והפטר לא קיים עשה שבה תוך כדי דבור דקי\"ל תכ\"ד כדבור דמי כי עבר על התראה חייב אפילו שלחה אחר זמן הכא נמי איכא למימר עבריה ללאו משלקחה ולא שלחה והשתא עשה הוא דאיכא ס\"ד אמינא ליתי עשה ולידחי עשה להכי איצטריך קרא:"],[10,"אלא למאן דתני בטלו ולא בטלו","בטל עשה שבה לגמרי שאין יכול לקיימו עוד כגון ששחטה חייב לא בטל עשה שבה כל זמן שלא שחטה אע\"פ שלא שלח מיד כשהתרו בו פטור וה\"נ כל זמן שלא שחטה לא עבריה ללאו דבעמוד ושלח והפטר קאי ואכתי לאו ועשה הוא ולא בעי קרא כלל לדבר מצוה ואנא ידענא דאין עשה דוחה את לא תעשה ועשה:"],[11,"ותו לרבי יהודה דאמר","במתני' לוקה ואינו משלח ואמר לקמן דהיינו טעמא דרבי יהודה דקסבר שלח מעיקרא משמע כלומר לא תקח האם אבל כשתמצאנה שלחנה ואם לקחה לא קאמר קרא דלשלחה הא תו ליכא לאוקמא כשעבר ונטלה דהא אפילו לדבר הרשות עשה ליכא ולא בעי שילוח דכיון דנטלה עבריה ללאו ועשה דלאו בעמוד ושלח קאי:"],[12,"על מנת לשלחה","ואפילו לרבי יהודה בעמוד ושלח קאי דהא לא עבריה ללאו ואי נמי לא משלחה תו ליכא לאו דהא כבר לקחה בהיתר ותו לא קרינא ביה לא תקח ועשה איכא וס\"ד ליתי עשה דמצורע ולידחיה להכי איצטריך קרא:"],[13,"ומאי אולמיה","דעשה דמצורע מעשה דשלוח דתיסק אדעתיה דנדחייה:"],[13,"ימחה על המים","פרשת סוטה יש בה הזכרות הרבה כתובות:"],[14,"אסור בתשמיש המטה","כמאן דאמר במועד קטן (דף ז:) ימי ספירו וקל וחומר לימי חלוטו:"],[14,"אהלו זו אשתו","שובו לכם לאהליכם לנשותיכם שאסרתים לכם ואמרתי אל תגשו אל אשה (שמות י״ט:ט״ו):"],[15,"","מתני' טעמא דרבי יהודה דלוקה מפרש בגמרא:"],[15,"ואינו משלח","דאיסור דעבד עבד:"],[15,"אין לוקין עליו","דלהכי נתקו לעשה לומר אם עבר על הלאו יעשה זאת וינצל לא תקח האם ואם לקח שלח תשלח:"],[15,"זה הכלל וכו' אין לוקין עליו","אלא אם כן לא קיימו תוך כדי דבור למאן דתני קיימו ולא קיימו אלא משלח תוך כדי דבור ואינו לוקה ואם לא שלח לוקה וצריך לשלח אחר לקיחה משמע ולמאן דתני בטלו ולא בטלו בעי עד שישחוט אותה ואי לא לא לקי:"],[17,"גמ' בעלמא","כגון לא תגזול והשיב את הגזלה דהתם ליכא למימר קודם גזילה משמע דאם לא גזל מה ישיב:"],[17,"שלח מעיקרא משמע","הכי קאמר קרא לא תקח האם אבל מה יש עליך לעשות כשתמצא קן שלח תשלח את האם ואין כאן ניתק לעשה אלא עברת עשה ולא תעשה מפני שהעשה קדם:"],[18,"והשיב את הגזלה","אף על פי שכתוב אחרון בפרשה על כרחך לאו שניתק לעשה הוא שאין השבה קודם גזילה וכשגזל עבר על לא תגזול נמצא העשה נצטווה לאחר גזילה:"]],[[8,"לא צריכא דעבר ושקליה דלאו עבריה כו'","מכאן קשה לפי' ריב\"א בפ' אלו עוברין (פסחים דף מז:) דאמר אחרישה לא ליחייב הואיל וחזי לכסויי בהו דם צפור והקשה והא יום טוב עשה ולא תעשה הוא ותירץ דנהי דלא דחי מיהו אם עבר על אותו לאו אינו לוקה דהא דלא דחי היינו משום עשה אבל הלאו כמאן דליתיה דעשה דחי ליה והכא משמע דכל זמן דלא עבר ושקלה איכא עשה ולא תעשה וצריך לומר לפירושו שמא דוקא לענין דלא לקי על אותו לאו אבל לא מדחי ליה לגמרי:"]]],[["רבי חייא ובי רבי אושעיא משבשתא היא ולא תותבו מינה בי מדרשא דלמא אינה בכלל מלקות ארבעים תניא","ת\"ש דתני ר' אושעיא ור' חייא (דברים כד, יט) לא תשוב ושב (ויקרא יט, ט) לא תכלה וכלה ישנן בכלל מלקות ארבעים דברי רבי יהודה","שמע מינה טעמיה דרבי יהודה משום דקסבר לאו שניתק לעשה לוקין עליו","דלמא התם היינו טעם דקסבר תעזוב מעיקרא משמע","א\"ל רבינא לרב אשי ת\"ש (שמות יב, י) לא תותירו ממנו עד בקר וגו' באש תשרופו בא הכתוב ליתן עשה אחר לא תעשה לומר לך שאין לוקין עליו דברי ר' יהודה","ש\"מ טעמא דר' יהודה משום דקסבר שלח מעיקרא משמע ש\"מ","א\"ל רב אידי לרב אשי מתני' נמי דיקא דקתני הנוטל אם על הבנים ר' יהודה אומר לוקה ואין משלח ואי ס\"ד טעמא דר' יהודה לאו שניתק לעשה לוקין עליו לוקה ומשלח מבעי ליה","ודלמא הכי קאמר במתני' אין נפטר עד דמלקין ליה","עד כמה משלחה אמר רב יהודה כדי שתצא מתחת ידו במה משלחה רב הונא אמר ברגליה רב יהודה אמר באגפיה רב הונא אמר ברגליה דכתיב (ישעיהו לב, כ) משלחי רגל השור והחמור רב יהודה אמר באגפיה דהא כנפיה נינהו","ההוא דגזינהו לגפה ושלחה ואח\"כ תפשה נגדיה רב יהודה א\"ל זיל רבי לה גדפיה ושלחה","כמאן אי כר' יהודה לוקה ואין משלח אי כרבנן משלח ואין לוקה לעולם כרבנן ומכת מרדות מדרבנן","ההוא דאתא לקמיה דרבא א\"ל תימה מהו אמר לא ידע האי גברא דעוף טהור חייב לשלוחי אמר ליה דילמא חדא ביעתא הוא דרמיא אמר ליה האי ידעי לך מתניתין היא אין שם אלא אפרוח אחד או ביצה אחת חייב לשלח","שלחה ואהדר לה רבא פרסתקי ותפסה וליחוש לחשדא כלאחר יד","ת\"ר יוני שובך ויוני עלייה חייבות בשלוח ואסורות משום גזל מפני דרכי שלום","ואי איתא להא דאמר ר' יוסי בר ר' חנינא חצרו של אדם קונה לו שלא מדעתו קרי כאן כי יקרא פרט למזומן","אמר רב ביצה עם יציאת רובה הוא דאחייב בשלוח מקנא לא קני עד דתפול לחצרו וכי קתני חייבות בשלוח מקמי דתפול לחצרו","אי הכי אמאי אסורות משום גזל אאמם ואיבעית אימא לעולם אביצה וביצה כיון דנפיק ליה רובא דעתיה עליה","והשתא דאמר רב יהודה אמר רב אסור לזכות בביצים שהאם רובצת עליהן שנאמר שלח את האם והדר הבנים תקח לך אפי' תימא אע\"ג דנפל לחצרו כל היכא דאיהו מצי זכי חצרו נמי זכיא וכל היכא דאיהו לא מצי זכי חצרו נמי לא זכיא ליה","אי הכי אמאי אסורות מפני דרכי שלום אי דשלחה גזל מעליא הוא אי דלא שלחה שלוחי בעי","בקטן קטן בר דרכי שלום הוא הכי קאמר אביו של קטן חייב להחזיר לו מפני דרכי שלום","לוי בר סימון אקני פירות שובכו לרב יהודה אתא לקמיה דשמואל א\"ל זיל טרוף אקן דליתגבהו וקנינהו","למאי אי למקנא לקנינהו ליה בסודר אי ביום טוב"],[[0,"","רבי חייא ורבי אושעיא סדרו את הברייתות ודקדקו בדברי כל חכם לומר כמו שאמר אבל יש תנאים הרבה שמוסיפים על משנתם בדדמי כי הכא משום דשמעינן לרבי יהודה הכא דמחייב סברי טעמא משום לאו שניתק לעשה לוקין עליו והוסיפו לומר גנב וגזלן:"],[0,"דילמא אינו בכלל מלקות ארבעים תניא","ואשמועינן דטעמא דרבי יהודה במתני' משום דשלח מעיקרא משמע והתנאים טעו בגירסתם לאחר זמן ואמרו שישנן דאמרי דומיא דמתני':"],[1,"לא תשוב","לקחתו:"],[1,"לא תכלה","דפאה והרי הן ניתקין לעשה דכתיב לעני ולגר תעזוב אותם:"],[3,"מעיקרא משמע","לא תכלה אבל מה עליך לעשות עזוב אותם ולא תכלה אבל גנב וגזלן דעל כרחך ניתק לעשה אימא לך דלא לקי:"],[4,"לא תותירו","ואם תותירו באש תשרופו הא ודאי ניתק לעשה:"],[6,"ואי ס\"ד","קסבר ר' יהודה שלח דקרא אחר לקיחה משמע וטעמא דלוקה משום לאו שניתק לעשה לוקין עליו אמאי קתני ואין משלח הכתוב מחייבו אף לשלחו לאחר לקיחה והוא פוטרו:"],[7,"דילמא","אינו משלח דקאמר אינו נפטר בשלוח אלא אף לוקה:"],[8,"עד כמה משלחה","אם נטלה:"],[8,"שתצא מתחת ידו","ואם יכול לחזור ולתופשה מותר:"],[8,"במה משלחה ברגל","יאחזנה ברגלה וישלחנה:"],[8,"בגפה","אוחזה בכנפה ומשלחה:"],[8,"משלחי רגל","אלמא שילוח ברגל הוא כך שמעתי. ונראה בעיני שאין שילוח זה דומה לשילוח רגל השור שהוא הולך ברגלים והכא אחיזה ברגלים וכמדומה לי דהכי קאמר רב הונא אמר ברגל שאם תלש גפה ושלחה נפטר ממצות שילוח כיון שהלכה ב' פסיעות או ג' ומותר לחזור לתופשה ורב יהודה אמר בגפה שתוכל לעוף כדרכה וראייה לדברי מדמייתי עובדא דההוא דתלשינהו לגפה ושלחה דחייביה רב יהודה למשלחיה דרב יהודה לטעמיה דאמר אין שילוח עוף ברגל:"],[9,"רבי לה גדפה","השהה אותה עד שיגדלו לה כנפיה ותשלחנה:"],[10,"מכת מרדות","רידוי בתוכחה שלא ירגיל בזה ואין לה קצבה אלא עד שיקבל עליו:"],[11,"תימה","עוף טהור הוא:"],[11,"אמר ליה","רבא:"],[11,"דלמא חדא ביעתא הוא דרמיא","לכך הוצרכת לשאול שלא הטילה אלא ביצה אחת וקרא אפרוחים או ביצים כתיב:"],[12,"פרסתקי","מצודות:"],[12,"וליחוש לחשדא","שעל הנאת עצמו חייבו לשלחה דצריך להתרחק מן הכיעור כדאמר באלו טרפות (לעיל חולין דף מד:) דרב חסדא שרי בוכרא ולא זבין מיניה:"],[12,"ומשני כלאחר יד","מרחוק פירש המצודה שלא הבין המשלח:"],[14,"ואם איתא לדר' יוסי וכו'","הש\"ס פריך לה:"],[15,"יציאת רובה","דאם בא אדם ומצא את האם כשהיא מטילה ביצתה וכבר יצא רובה חייב לשלח מקמי דתפול לחצרו דאכתי לאו מזומן הוא:"],[16,"אי הכי","דלא קנתה חצרו:"],[16,"אמאי אסורות משום גזל","ואפילו מפני דרכי שלום והלא עדיין מגוף האם הוא:"],[16,"ומשני אאמן","דרכי שלום דקאמר אפילו על האם עצמה יש משום דרכי שלום:"],[16,"ואיבעית אימא לעולם אביצים","דאילו על אמן אפילו משום דרכי שלום אין כאן הואיל ואינה נוחה לתופשה לא סמכה דעת בעל השובך עלה ואינו מתקוטט עם הלוקח אבל מהביצים הוא מתקוטט דדעתיה עליהן ונהי נמי דלא קנה לו חצרו משום דרכי שלום מיהא איכא:"],[17,"והשתא דאמר רב יהודה כו'","מהשתא מצית לאוקומא מתניתין אפילו יצאת כולה ולא תקשה לרבי יוסי ברבי חנינא דלא מזומן הוא וחייבת בשילוח משום ביצה אחרונה זאת שלא עמדה האם עליה משהטילתה ואף על פי שנפלה לחצר לא קנתה חצרו דכיון דהוא עצמו אם היה כאן לא היה יכול להחזיק כל חצרו נמי לא מצי זכי ליה ואין זה מזומן:"],[17,"לזכות","לפשוט ידו תחת האם ולהחזיק בהם. כל קנייה דהפקר זכייה קרי ליה:"],[18,"אי הכי אמאי אסורות","משום גזל. משום דרכי שלום ותו לא:"],[18,"אי דשלחה","קודם דהחזיק בה הרי קנתה חצרו לבעל הבית וגזל מעליא הוא ואי דלא שלחה היאך הוא יכול ליטלם לביצים הא בעי שלוח קודם לקיחת הביצים כרב יהודה:"],[19,"ומשני בקטן","דלאו בר שלוח הוא. והוא הדין דהוה מצי לשנויי כגון דעבר ונטלן תחת האם דגזל מעליא ליכא אלא ניחא ליה לשנויי בדרך היתר ולא בדרך איסור:"],[19,"","והדר מתמה ואמר \u0003 קטן בר דרכי שלום הוא\u0004:"],[19,"","ה\"ג אביו של קטן חייב להחזיר מפני דרכי שלום:"],[20,"פירות שובכו","אפרוחים וביצים:"],[20,"אתא לקמיה דשמואל","לקמן מפרש מאי איצטריך ליה למבעי:"],[20,"טרוף אקן","הקש בידך על הקן:"],[20,"דליתגבהו","מיראתך. והשתא מפרש ואזיל מאי בעא מיניה ומאי מהדר ליה:"],[21,"למאי","הגבהה זו למה:"],[21,"אי למקנא","שלא יחזור בו לוי בן סימון והכי קאמר ליה טרוף אקן דליתגבהו אפרוחים מיראתך ותקנה אותם בהגבהה:"],[21,"ליקנינהו בסודר","ולמה הוצרך רב יהודה לשאול היאך יקנה:"],[21,"ואם ליו\"ט","שהוא ערב יו\"ט ולמחר יהיו אסורים משום מוקצה ובא לשאול במה הכנתם למה לי האי טרחא לטרוף אקן:"]],[[10,"אי כרבנן משלח ואינו לוקה","הוה מצי למימר דסבר קיימו ולא קיימו הילכך לוקה ומשלח אליבא דרבנן:"],[16,"אי הכי אמאי אסורות משום גזל","מפורש בסוף השואל (ב\"מ דף קב.):"]]],[["בעומד ואומר זה וזה אני נוטל סגיא הנהו פירי חדתי הוו דלוי בר סימון גופיה לא הוה קני להו והכי קאמר ליה זיל וטריף אקן דליתגבהו וניקנינהו לוי בר סימון והדר ליקנינהו ניהלך בסודר:","\u0001מתני׳\u0002 לא יטול אדם אם על בנים אפי' לטהר את המצורע ומה אם מצוה קלה שהיא כאיסר אמרה תורה (דברים כב, ז) למען ייטב לך והארכת ימים ק\"ו על מצות חמורות שבתורה:","\u0001גמ׳\u0002 תניא דבי ר' יעקב אומר אין לך כל מצוה ומצוה שבתורה שמתן שכרה בצדה שאין תחיית המתים תלויה בה בכבוד אב ואם כתיב (דברים ה, טו) למען יאריכון ימיך ולמען ייטב לך בשילוח הקן כתיב למען ייטב לך והארכת ימים","הרי שאמר לו אביו עלה לבירה והבא לי גוזלות ועלה ושלח את האם ולקח את הבנים ובחזרתו נפל ומת היכן אריכות ימיו של זה והיכן טובתו של זה אלא למען יאריכון ימיך בעולם שכולו ארוך ולמען ייטב לך לעולם שכולו טוב","ודלמא לא הוה הכי ר' יעקב מעשה חזא ודלמא מהרהר בעבירה הוה מחשבה רעה אין הקב\"ה מצרפה למעשה","ודלמא מהרהר בעבודה זרה הוה דכתיב (יחזקאל יד, ה) למען תפוש את בית ישראל בלבם ואמר רב אחא בר יעקב זו מחשבת עבודה זרה","הכי קאמר אם איתא דאיכא שכר מצות בהאי עלמא תהני ליה ותגן עליה דלא ליתי לידי הרהור וליתזק אלא שכר מצות בהאי עלמא ליכא והאמר ר' אלעזר שלוחי מצוה אינן נזוקים בחזרתם שאני","והאמר רבי אלעזר שלוחי מצוה אינן נזוקים לא בהליכתן ולא בחזרתן סולם רעוע הוה ומקום דקבוע היזקא שאני דכתיב (שמואל א טז, ב) ויאמר שמואל איך אלך ושמע שאול והרגני","אמר רב יוסף אלמלא דרשיה אחר להאי קרא כרבי יעקב בר ברתיה לא חטא מאי חזא איכא דאמרי כי האי מעשה חזא ואיכא דאמרי לישנא דרבי חוצפית המתורגמן חזא דהוה מוטלת באשפה אמר פה שהפיק מרגליות ילחוך עפר והוא לא ידע למען ייטב לך בעולם שכלו טוב ולמען יאריכון ימיך בעולם שכולו ארוך:","\u0001הדרן עלך שילוח הקן וסליקא לה מסכת חולין\u0002"],[[0,"בעומד ואומר זה וזה אני נוטל סגיא","כבית הלל במסכת ביצה (דף י.):"],[0,"פירי חדתי","ביצים שהטילה אותם האם ולא עמדה מעליהם מעולם ולא קנתה לו חצרו ללוי דאסור לזכות בהן כל זמן שהאם רובצת עליהם ולוי היה צריך לילך לקנות ומה שלא קנה אינו יכול להקנות ואם יקנה לו בסודר יכול לחזור בו:"],[0,"זיל טרוף אקן דליתגבהו","אמהות וליקנינהו לוי לפירות על ידו חצירו ויקנהו לוי ניהלך בסודר:"],[1,"מתני' שהיא כאיסר","שאין בה חסרון כיס אלא דבר מועט:"],[2,"גמ' שמתן שכרה בצדה","כגון כבוד אב ואם ושלוח הקן שלא תוכל להבין מתן שכרה שעתידין המתים להחיות:"],[3,"לעולם שכולו טוב","שאין בו לא היזק ולא יסורין אלא טובה. ובשילהי פרק קמא דקדושין (דף לט:) אמרינן דרבי יעקב עובדא חזא באחד שאמר לו אביו עלה לבירה והבא לי גוזלות ועלה ושלח את האם ונטל את הבנים וקיים כבוד אב ואם ושלוח הקן ובחזרתו נפל ומת היכן טובתו של זה והיכן אריכות ימיו אלא הוי אומר למען ייטב לך לעולם שכולו טוב ולמען יאריכון ימיך לעולם שכולו ארוך:"]],[]]]};
